119:         private void SetupAudio()
120:         {
121:             _audioSource = gameObject.GetComponent<AudioSource>();
122:             if (_audioSource == null) _audioSource = gameObject.AddComponent<AudioSource>();
123:             _audioSource.playOnAwake = false;
124: 
125:             // Dedicated 2D Music AudioSource
126:             if (musicSource == null)
127:             {
128:                 Transform musicChild = transform.Find("Cutscene_Music_Source");
129:                 if (musicChild != null)
130:                 {
131:                     musicSource = musicChild.GetComponent<AudioSource>();
132:                 }
133:                 else
134:                 {
135:                     GameObject mGo = new GameObject("Cutscene_Music_Source");
136:                     mGo.transform.SetParent(transform);
137:                     musicSource = mGo.AddComponent<AudioSource>();
138:                 }
139:             }
140: 
141:             if (musicSource != null)
142:             {
143:                 musicSource.spatialBlend = 0f; // Pure 2D cinematic soundtrack
144:                 musicSource.loop = true;
145:                 musicSource.playOnAwake = false;
146:                 musicSource.volume = menuMusicVolume;
147:             }
148: 
149:             // UI button click clip
150:             int clickSamples = 1600;
151:             _buttonClickClip = AudioClip.Create("UI_Click", clickSamples, 1, 44100, false);
152:             float[] clickData = new float[clickSamples];
153:             for (int i = 0; i < clickSamples; i++)
154:             {
155:                 float t = (float)i / clickSamples;
156:                 clickData[i] = Mathf.Sin(t * 2200f * Mathf.PI * 2f) * Mathf.Exp(-t * 26f) * 0.6f;
157:             }
158:             _buttonClickClip.SetData(clickData, 0);
159: 
160:             // Diagnostic probe relay click
161:             int relaySamples = 1200;
162:             _relayClickClip = AudioClip.Create("Relay_Click", relaySamples, 1, 44100, false);
163:             float[] relayData = new float[relaySamples];
164:             for (int i = 0; i < relaySamples; i++)
165:             {
166:                 float t = (float)i / relaySamples;
167:                 relayData[i] = ((Random.value * 2f - 1f) * 0.5f + Mathf.Sin(t * 1800f * Mathf.PI * 2f) * 0.5f) * Mathf.Exp(-t * 20f) * 0.7f;
168:             }
169:             _relayClickClip.SetData(relayData, 0);
170: 
171:             // Doctor Voice Source
172:             if (doctorVoiceSource == null && doctorActor != null)
173:             {
174:                 doctorVoiceSource = doctorActor.GetComponent<AudioSource>();
175:                 if (doctorVoiceSource == null) doctorVoiceSource = doctorActor.AddComponent<AudioSource>();
176:                 doctorVoiceSource.spatialBlend = 0.25f; // Mostly clear dialogue with subtle spatial presence
177:                 doctorVoiceSource.playOnAwake = false;
178:                 doctorVoiceSource.volume = 1.0f;
179:             }
180:         }
