451:             // Doctor walks from entrance (0s to 12s) towards notice point
452:             if (doctorActor != null)
453:             {
454:                 float t = Mathf.Clamp01(_phaseTime / 12.0f);
455:                 float smoothT = Mathf.SmoothStep(0f, 1f, t);
456:                 doctorActor.transform.position = Vector3.Lerp(doctorEntrancePos, doctorNoticePos, smoothT);
457:                 Vector3 moveDir = (doctorNoticePos - doctorEntrancePos).normalized;
458:                 if (moveDir != Vector3.zero)
459:                 {
460:                     doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(moveDir), Time.deltaTime * 5f);
461:                 }
462:             }
463: 
464:             if (_phaseTime >= 12.0f)
465:             {
466:                 currentPhase = CutscenePhase.IdoApproaching;
467:                 _phaseTime = 0f;
468:                 SetSubtitleAndVoice("Dr. Dyson Ido: \"Wait... what is that faint glow beneath the wreckage?\"", 4.5f, voiceIdoNotice);
469:                 if (_audioSource != null && _relayClickClip != null) _audioSource.PlayOneShot(_relayClickClip, 0.7f);
