473:         private void UpdateIdoApproaching()
474:         {
475:             Vector3 alitaPos = alitaActor != null ? alitaActor.transform.position : doctorAlitaPos;
476:             float t = Mathf.Clamp01(_phaseTime / 8.5f);
477: 
478:             // Slower, cautious pace as he gets closer
479:             float approachSpeed = Mathf.Lerp(1.0f, 0.45f, t);
480:             SetDoctorAnimation(approachSpeed, false, false, false);
481: 
482:             // Doctor walks from notice point to kneeling position beside Alita (0s to 8.5s)
483:             if (doctorActor != null)
484:             {
485:                 float smoothT = Mathf.SmoothStep(0f, 1f, t);
486:                 doctorActor.transform.position = Vector3.Lerp(doctorNoticePos, doctorAlitaPos, smoothT);
487:                 Vector3 moveDir = (doctorAlitaPos - doctorNoticePos).normalized;
488:                 if (moveDir != Vector3.zero)
489:                 {
490:                     doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(moveDir), Time.deltaTime * 5f);
491:                 }
492:             }
493: 
494:             if (_phaseTime >= 8.5f)
495:             {
496:                 currentPhase = CutscenePhase.IdoExamining;
497:                 _phaseTime = 0f;
498:                 SetDoctorAnimation(0f, true, false, false);
499:                 SetSubtitleAndVoice("Dr. Dyson Ido: \"A Martian Berserker chassis... discarded centuries ago.\"", 5.0f, voiceIdoExamine);
500:                 StartCoroutine(DiagnosticExaminationRoutine());
501:             }
502:         }
