504:         private IEnumerator DiagnosticExaminationRoutine()
505:         {
506:             yield return new WaitForSeconds(3.8f);
507:             SetSubtitleAndVoice("Dr. Dyson Ido: \"Her brain is intact... and her antimatter core is still warm.\"", 5.5f, voiceIdoCoreWarm);
508: 
509:             if (diagnosticProbeLight != null)
510:             {
511:                 diagnosticProbeLight.enabled = true;
512:                 Vector3 probeCenter = GetAlitaFocusCenter();
513:                 diagnosticProbeLight.transform.position = probeCenter + new Vector3(-0.15f, 0.25f, -0.20f);
514:             }
515: 
516:             float diagTimer = 0f;
517:             while (diagTimer < 5.0f)
518:             {
519:                 diagTimer += Time.deltaTime;
520:                 if (diagnosticProbeLight != null)
521:                 {
522:                     diagnosticProbeLight.intensity = Mathf.PingPong(diagTimer * 3.5f, 1.6f) + 1.1f;
523:                 }
524:                 yield return null;
525:             }
526: 
527:             if (diagnosticProbeLight != null) diagnosticProbeLight.enabled = false;
528: 
529:             // Doctor recognizes she cannot wake up here in the storm:
530:             SetSubtitleAndVoice("Dr. Dyson Ido: \"She's in deep stasis. I need to take her back to the clinic.\"", 5.0f, voiceIdoStasis);
531:             yield return new WaitForSeconds(4.2f);
532: 
533:             // Proceed to lifting Alita
534:             currentPhase = CutscenePhase.IdoLiftingAlita;
535:             _phaseTime = 0f;
536:             SetDoctorAnimation(0f, false, true, false);
537: 
538:             if (carryRig != null)
539:             {
540:                 carryRig.StartPickupSequence(() =>
541:                 {
542:                     currentPhase = CutscenePhase.IdoWalkingCarrying;
543:                     _phaseTime = 0f;
544:                     SetDoctorAnimation(1.0f, false, false, true);
545:                     SetSubtitleAndVoice("Dr. Dyson Ido: \"Hang on, little angel. Let's get you home.\"", 5.5f, voiceIdoCarryHome);
546:                 });
547:             }
548:             else
549:             {
550:                 currentPhase = CutscenePhase.IdoWalkingCarrying;
551:                 _phaseTime = 0f;
552:                 SetDoctorAnimation(1.0f, false, false, true);
553:             }
554:         }
