634:         public Vector3 GetAlitaFocusCenter()
635:         {
636:             if (alitaActor != null)
637:             {
638:                 var anim = alitaActor.GetComponentInChildren<Animator>();
639:                 if (anim != null)
640:                 {
641:                     Transform head = anim.GetBoneTransform(HumanBodyBones.Head);
642:                     Transform chest = anim.GetBoneTransform(HumanBodyBones.Chest);
643:                     if (head != null && chest != null) return (head.position + chest.position) * 0.5f;
644:                 }
645:                 return alitaActor.transform.position + Vector3.up * 1.25f;
646:             }
647: 
648:             var alitaGo = GameObject.Find("Alita_Cyborg_Character") ?? GameObject.Find("Alita_Broken_Cyborg");
649:             if (alitaGo != null)
650:             {
651:                 var anim = alitaGo.GetComponentInChildren<Animator>();
652:                 if (anim != null)
653:                 {
654:                     Transform head = anim.GetBoneTransform(HumanBodyBones.Head);
655:                     Transform chest = anim.GetBoneTransform(HumanBodyBones.Chest);
656:                     if (head != null && chest != null) return (head.position + chest.position) * 0.5f;
657:                 }
658:                 return alitaGo.transform.position + Vector3.up * 1.25f;
659:             }
660: 
661:             return doctorAlitaPos + Vector3.up * 0.45f;
