203:         private void Update()
204:         {
205:             if (!isPlaying) return;
206: 
207:             phaseTimer += Time.deltaTime;
208:             if (_subtitleTimer > 0f)
209:             {
210:                 _subtitleTimer -= Time.deltaTime;
211:                 if (_subtitleTimer <= 0f) _currentSubtitle = "";
212:             }
213: 
214:             // Phase Sequence Transitions
215:             switch (currentPhase)
216:             {
217:                 case AwakeningPhase.TerminalBoot:
218:                     UpdateTerminalBoot();
219:                     if (phaseTimer >= 7.5f)
220:                     {
221:                         TransitionToPhase(AwakeningPhase.StasisScanning);
222:                     }
223:                     break;
224: 
225:                 case AwakeningPhase.StasisScanning:
226:                     UpdateStasisScanning();
227:                     if (phaseTimer >= 4.5f)
228:                     {
229:                         TransitionToPhase(AwakeningPhase.PowerSurge);
230:                         fxAudioSource.PlayOneShot(AlitaAwakeningAudioEngine.CreatePowerSurgeSwell(4.5f), 0.85f);
231:                     }
232:                     break;
233: 
234:                 case AwakeningPhase.PowerSurge:
235:                     UpdatePowerSurge();
236:                     if (phaseTimer >= 4.0f)
237:                     {
238:                         TransitionToPhase(AwakeningPhase.OpticActivation);
239:                         fxAudioSource.PlayOneShot(AlitaAwakeningAudioEngine.CreateOpticBootChime(2.8f), 0.90f);
240:                     }
241:                     break;
242: 
243:                 case AwakeningPhase.OpticActivation:
244:                     UpdateOpticActivation();
245:                     if (phaseTimer >= 3.0f)
246:                     {
247:                         TransitionToPhase(AwakeningPhase.DepressurizeCanopy);
248:                         fxAudioSource.PlayOneShot(AlitaAwakeningAudioEngine.CreatePneumaticSteamHiss(3.5f), 0.80f);
249:                         if (cryoSteamFX != null) cryoSteamFX.Play();
250:                     }
251:                     break;
252: 
253:                 case AwakeningPhase.DepressurizeCanopy:
254:                     UpdateDepressurizeCanopy();
255:                     if (phaseTimer >= 4.5f)
256:                     {
257:                         TransitionToPhase(AwakeningPhase.AlitaSitUp);
258:                     }
259:                     break;
260: 
261:                 case AwakeningPhase.AlitaSitUp:
262:                     UpdateAlitaSitUp();
263:                     if (phaseTimer >= 5.5f)
264:                     {
265:                         TransitionToPhase(AwakeningPhase.InspectHands);
266:                         SetSubtitle("Alita: \"...What is this? Where am I?\"", 6.0f);
267:                     }
268:                     break;
269: 
270:                 case AwakeningPhase.InspectHands:
271:                     UpdateInspectHands();
272:                     if (phaseTimer >= 7.5f)
273:                     {
274:                         TransitionToPhase(AwakeningPhase.IdoApproach);
275:                         StartCoroutine(IdoDialogueSequence());
276:                     }
277:                     break;
278: 
279:                 case AwakeningPhase.IdoApproach:
280:                     UpdateIdoApproach();
281:                     if (phaseTimer >= 9.0f)
282:                     {
283:                         TransitionToPhase(AwakeningPhase.Epilogue);
284:                     }
285:                     break;
286: 
287:                 case AwakeningPhase.Epilogue:
288:                     _epilogueAlpha = Mathf.MoveTowards(_epilogueAlpha, 1.0f, Time.deltaTime * 0.5f);
289:                     break;
290:             }
291:         }
