332:             }
333:             if (phaseTimer >= 2.75f && !_typedSound2Played)
334:             {
335:                 _typedSound2Played = true;
336:                 if (fxAudioSource != null) fxAudioSource.PlayOneShot(AlitaAwakeningAudioEngine.CreateTypingSequence(2.0f, 32), 0.85f);
337:             }
338:             if (phaseTimer >= 4.85f && !_beep2Played)
339:             {
340:                 _beep2Played = true;
341:                 if (fxAudioSource != null) fxAudioSource.PlayOneShot(AlitaAwakeningAudioEngine.CreateTerminalBeep(1100f), 0.65f);
342:             }
