470:         private void ApplyProceduralPosing()
471:         {
472:             if (alitaDollBody == null) return;
473: 
474:             switch (currentPhase)
475:             {
476:                 case AwakeningPhase.StasisScanning:
477:                 case AwakeningPhase.PowerSurge:
478:                 case AwakeningPhase.OpticActivation:
479:                 case AwakeningPhase.DepressurizeCanopy:
480:                     // Lying flat in pod
481:                     PoseLyingFlat();
482:                     break;
483: 
484:                 case AwakeningPhase.AlitaSitUp:
485:                     float sitT = Mathf.Clamp01(phaseTimer / 5.0f);
486:                     float smoothSit = Mathf.SmoothStep(0f, 1f, sitT);
487:                     PoseSitUp(smoothSit);
488:                     break;
489: 
490:                 case AwakeningPhase.InspectHands:
491:                 case AwakeningPhase.IdoApproach:
492:                 case AwakeningPhase.Epilogue:
493:                     PoseInspectHands();
494:                     break;
495:             }
