498:         private void PoseLyingFlat()
499:         {
500:             if (_alitaSpine != null) _alitaSpine.localRotation = Quaternion.identity;
501:             if (_alitaChest != null) _alitaChest.localRotation = Quaternion.identity;
502:             if (_alitaHead != null) _alitaHead.localRotation = Quaternion.identity;
503: 
504:             // Arms resting by sides
505:             if (_alitaUpperArmL != null) _alitaUpperArmL.localRotation = Quaternion.Euler(15f, 0f, 12f);
506:             if (_alitaLowerArmL != null) _alitaLowerArmL.localRotation = Quaternion.Euler(0f, 0f, 10f);
507:             if (_alitaUpperArmR != null) _alitaUpperArmR.localRotation = Quaternion.Euler(15f, 0f, -12f);
508:             if (_alitaLowerArmR != null) _alitaLowerArmR.localRotation = Quaternion.Euler(0f, 0f, -10f);
509:         }
