511:         private void PoseSitUp(float weight)
512:         {
513:             // Spine tilts forward from 0 to 65 degrees
514:             if (_alitaSpine != null) _alitaSpine.localRotation = Quaternion.Slerp(Quaternion.identity, Quaternion.Euler(-32f, 0f, 0f), weight);
515:             if (_alitaChest != null) _alitaChest.localRotation = Quaternion.Slerp(Quaternion.identity, Quaternion.Euler(-33f, 0f, 0f), weight);
516:             if (_alitaHead != null) _alitaHead.localRotation = Quaternion.Slerp(Quaternion.identity, Quaternion.Euler(18f, Mathf.Sin(phaseTimer * 1.5f) * 12f, 0f), weight);
517: 
518:             // Arms transition toward lap
519:             if (_alitaUpperArmL != null) _alitaUpperArmL.localRotation = Quaternion.Slerp(Quaternion.Euler(15f, 0f, 12f), Quaternion.Euler(45f, 15f, 25f), weight);
520:             if (_alitaLowerArmL != null) _alitaLowerArmL.localRotation = Quaternion.Slerp(Quaternion.Euler(0f, 0f, 10f), Quaternion.Euler(30f, 20f, 0f), weight);
521: 
522:             if (_alitaUpperArmR != null) _alitaUpperArmR.localRotation = Quaternion.Slerp(Quaternion.Euler(15f, 0f, -12f), Quaternion.Euler(45f, -15f, -25f), weight);
523:             if (_alitaLowerArmR != null) _alitaLowerArmR.localRotation = Quaternion.Slerp(Quaternion.Euler(0f, 0f, -10f), Quaternion.Euler(30f, -20f, 0f), weight);
524:         }
525: 
526:         private void PoseInspectHands()
527:         {
528:             // Upright torso
529:             if (_alitaSpine != null) _alitaSpine.localRotation = Quaternion.Euler(-32f, 0f, 0f);
530:             if (_alitaChest != null) _alitaChest.localRotation = Quaternion.Euler(-33f, 0f, 0f);
531:             if (_alitaHead != null) _alitaHead.localRotation = Quaternion.Euler(22f, Mathf.Sin(phaseTimer * 0.8f) * 8f, 0f);
532: 
533:             // Raise both arms in front of face to admire porcelain filigree fingers
534:             float wristFlex = Mathf.Sin(phaseTimer * 1.2f) * 18f;
535:             if (_alitaUpperArmL != null) _alitaUpperArmL.localRotation = Quaternion.Euler(75f, 25f, 35f);
536:             if (_alitaLowerArmL != null) _alitaLowerArmL.localRotation = Quaternion.Euler(60f, 35f, 20f);
537:             if (_alitaHandL != null) _alitaHandL.localRotation = Quaternion.Euler(10f, 30f + wristFlex, -15f);
538: 
539:             if (_alitaUpperArmR != null) _alitaUpperArmR.localRotation = Quaternion.Euler(75f, -25f, -35f);
540:             if (_alitaLowerArmR != null) _alitaLowerArmR.localRotation = Quaternion.Euler(60f, -35f, -20f);
541:             if (_alitaHandR != null) _alitaHandR.localRotation = Quaternion.Euler(10f, -30f - wristFlex, 15f);
542: 
543:             // Delicate procedural finger curling
544:             float fingerCurl = Mathf.PingPong(phaseTimer * 1.5f, 35f) + 10f;
545:             foreach (var f in _leftFingers)
546:             {
547:                 if (f != null) f.localRotation = Quaternion.Euler(fingerCurl, 0f, 0f);
548:             }
549:             foreach (var f in _rightFingers)
550:             {
551:                 if (f != null) f.localRotation = Quaternion.Euler(fingerCurl, 0f, 0f);
552:             }
553:         }
