557:         #region Camera Choreography
558: 
559:         private void UpdateCinematicCamera()
560:         {
561:             Vector3 podCenter = podBase != null ? podBase.position : Vector3.zero;
562:             Vector3 alitaHeadPos = _alitaHead != null ? _alitaHead.position : podCenter + Vector3.up * 0.95f;
563:             Vector3 targetCamPos = cutsceneCamera.transform.position;
564:             Vector3 targetLookAt = alitaHeadPos;
565:             float targetFov = 34f;
566:             float smoothSpeed = 4.5f;
567: 
568:             switch (currentPhase)
569:             {
570:                 case AwakeningPhase.TerminalBoot:
571:                     // 0.0s - 5.5s: OTS framing of Dr. Ido typing at diagnostic console
572:                     // 5.5s - 7.5s: Sub-bass drop - smooth crane swoop from console to pod establishing shot
573:                     Vector3 docPos = doctorActor != null ? doctorActor.transform.position : doctorConsolePos;
574:                     Vector3 screenPos = new Vector3(-1.60f, 1.15f, 1.20f);
575:                     Vector3 otsCamPos = docPos + new Vector3(-0.35f, 1.48f, -0.45f);
576: 
577:                     if (phaseTimer < 5.5f)
578:                     {
579:                         targetCamPos = otsCamPos;
580:                         targetLookAt = screenPos;
581:                         targetFov = 30f;
582:                         smoothSpeed = 5.0f;
583:                     }
584:                     else
585:                     {
586:                         // Swoop toward pod establishing position
587:                         float swoopT = Mathf.Clamp01((phaseTimer - 5.5f) / 2.0f);
588:                         float smoothSwoop = Mathf.SmoothStep(0f, 1f, swoopT);
589:                         Vector3 podEstablishingPos = podCenter + new Vector3(-2.6f, 2.2f, -1.4f);
590:                         Vector3 podLookAt = podCenter + new Vector3(0f, 1.45f, 0.35f);
591: 
592:                         targetCamPos = Vector3.Lerp(otsCamPos, podEstablishingPos, smoothSwoop);
593:                         targetLookAt = Vector3.Lerp(screenPos, podLookAt, smoothSwoop);
594:                         targetFov = Mathf.Lerp(30f, 34f, smoothSwoop);
595:                         smoothSpeed = 4.0f;
596:                     }
597:                     break;
598: 
599:                 case AwakeningPhase.StasisScanning:
600:                     // Establishing 3/4 tracking shot of glowing pod and stasis bed
601:                     targetCamPos = podCenter + new Vector3(-2.6f, 2.2f, -1.4f);
602:                     targetLookAt = podCenter + new Vector3(0f, 1.45f, 0.35f);
603:                     targetFov = 34f;
604:                     break;
605: 
606:                 case AwakeningPhase.PowerSurge:
607:                     // High-angle spiral crane shot revealing the glowing Tron floor grid
608:                     float spiralAngle = (phaseTimer * 16f - 40f) * Mathf.Deg2Rad;
609:                     targetCamPos = podCenter + new Vector3(Mathf.Sin(spiralAngle) * 3.4f, 3.2f, Mathf.Cos(spiralAngle) * 3.4f);
610:                     targetLookAt = podCenter + new Vector3(0f, 1.40f, 0.35f);
611:                     targetFov = 38f;
612:                     break;
613: 
614:                 case AwakeningPhase.OpticActivation:
615:                     // Dramatic snap push-in with Dutch angle on Alita's glowing eyes
616:                     targetCamPos = alitaHeadPos + new Vector3(-0.65f, 0.55f, -0.85f);
617:                     targetLookAt = alitaHeadPos + Vector3.up * 0.05f;
618:                     targetFov = 26f;
619:                     smoothSpeed = 7.0f;
620:                     break;
621: 
622:                 case AwakeningPhase.DepressurizeCanopy:
623:                     // Front tracking dolly as steam parts and canopy ascends
624:                     targetCamPos = podCenter + new Vector3(-2.2f, 1.95f, -1.2f);
625:                     targetLookAt = podCenter + new Vector3(0f, 1.55f, 0.35f);
626:                     targetFov = 34f;
627:                     break;
628: 
629:                 case AwakeningPhase.AlitaSitUp:
630:                     // Hero eye-level track as Alita sits upright
631:                     targetCamPos = alitaHeadPos + new Vector3(-1.85f, 0.40f, -1.15f);
632:                     targetLookAt = alitaHeadPos + Vector3.down * 0.10f;
633:                     targetFov = 32f;
634:                     break;
635: 
636:                 case AwakeningPhase.InspectHands:
637:                     // Clean hero 3/4 framing of porcelain filigree hands
638:                     targetCamPos = alitaHeadPos + new Vector3(-1.45f, 0.30f, -0.85f);
639:                     targetLookAt = _alitaHandL != null ? _alitaHandL.position : (alitaHeadPos + Vector3.down * 0.15f);
640:                     targetFov = 28f;
641:                     break;
642: 
643:                 case AwakeningPhase.IdoApproach:
644:                 case AwakeningPhase.Epilogue:
645:                     // Cinematic two-shot establishing Dr. Ido beside pod talking with Alita
646:                     Vector3 idoPos = doctorActor != null ? doctorActor.transform.position : doctorPodSidePos;
647:                     targetCamPos = new Vector3(-3.4f, 2.1f, -0.9f);
648:                     targetLookAt = Vector3.Lerp(idoPos + Vector3.up * 1.4f, alitaHeadPos, 0.5f);
649:                     targetFov = 36f;
650:                     break;
651:             }
652: 
653:             // Smooth interpolation
654:             cutsceneCamera.transform.position = Vector3.Lerp(cutsceneCamera.transform.position, targetCamPos, Time.deltaTime * smoothSpeed);
655:             Vector3 lookDir = (targetLookAt - cutsceneCamera.transform.position).normalized;
656:             if (lookDir != Vector3.zero)
657:             {
658:                 Quaternion targetRot = Quaternion.LookRotation(lookDir);
659:                 cutsceneCamera.transform.rotation = Quaternion.Slerp(cutsceneCamera.transform.rotation, targetRot, Time.deltaTime * smoothSpeed);
660:             }
661:             cutsceneCamera.fieldOfView = Mathf.Lerp(cutsceneCamera.fieldOfView, targetFov, Time.deltaTime * 3.0f);
662:         }
