562:                         Vector3 wreckPos = worldPos + new Vector3(Mathf.Sin(rad + 0.3f) * 2.5f, 0.6f, Mathf.Cos(rad + 0.3f) * 2.5f);
563:                         Quaternion wreckRot = Quaternion.Euler(
564:                             Mathf.Sin(i * 1.5f) * 28f,
565:                             (angleDeg + 90f) % 360f,
566:                             Mathf.Cos(i * 1.2f) * 22f
567:                         );
568:                         Vector3 wreckScale = wreckPrefab.Contains("Container") ? new Vector3(1.3f, 1.3f, 1.3f) : new Vector3(1.15f, 1.15f, 1.15f);
569:                         SpawnPropSafe(wreckPrefab, wreckPos, wreckRot, wreckScale, parent);
570:                     }
571:                 }
572:             }
573: 
574:             // 2. Closed 360-degree colossal mountain perimeter (Radius 85m - 95m)
