581:                 float dist = 88f + (m % 2 == 0 ? 6f : -4f);
582:                 Vector3 mPos = centerOffset + new Vector3(Mathf.Sin(rad) * dist, 0f, Mathf.Cos(rad) * dist);
583:                 Quaternion mRot = Quaternion.Euler(0f, angleDeg + 180f, 0f); // Face inward
584:                 Vector3 mScale = new Vector3(4.8f, 3.8f + (m % 3) * 0.4f, 4.8f);
585: 
586:                 SpawnPropSafe("Assets/PolygonCyberCity/Prefabs/Env/SM_Env_Junk_Background_01.prefab", mPos, mRot, mScale, parent);
