214:         private void AddReactiveButtonHover(Button btn)
215:         {
216:             if (btn == null) return;
217:             var trigger = btn.gameObject.GetComponent<UnityEngine.EventSystems.EventTrigger>() 
218:                           ?? btn.gameObject.AddComponent<UnityEngine.EventSystems.EventTrigger>();
