220: 
221:             // Pointer Enter
222:             var enterEntry = new UnityEngine.EventSystems.EventTrigger.Entry { eventID = UnityEngine.EventSystems.EventTriggerType.PointerEnter };
223:             enterEntry.callback.AddListener((_) =>
224:             {
225:                 PlayHoverSound();
226:                 StartCoroutine(ScaleButtonRoutine(btn.transform, 1.04f, 0.12f));
227:             });
228:             trigger.triggers.Add(enterEntry);
229: 
230:             // Pointer Exit
231:             var exitEntry = new UnityEngine.EventSystems.EventTrigger.Entry { eventID = UnityEngine.EventSystems.EventTriggerType.PointerExit };
232:             exitEntry.callback.AddListener((_) =>
233:             {
234:                 StartCoroutine(ScaleButtonRoutine(btn.transform, 1.0f, 0.12f));
235:             });
236:             trigger.triggers.Add(exitEntry);
237:         }
