239:         private IEnumerator ScaleButtonRoutine(Transform tr, float targetScale, float duration)
240:         {
241:             if (tr == null) yield break;
242:             Vector3 start = tr.localScale;
243:             Vector3 end = Vector3.one * targetScale;
244:             float elapsed = 0f;
245:             while (elapsed < duration)
246:             {
247:                 if (tr == null) yield break;
248:                 elapsed += Time.unscaledDeltaTime;
249:                 tr.localScale = Vector3.Lerp(start, end, elapsed / duration);
250:                 yield return null;
251:             }
252:             if (tr != null) tr.localScale = end;
253:         }
