261:         private void UpdateECGMonitor()
262:         {
263:             if (_ecgTexture == null) return;
264: 
265:             // Shift texture columns 1 pixel to the left
266:             for (int y = 0; y < ECG_HEIGHT; y++)
267:             {
268:                 for (int x = 0; x < ECG_WIDTH - 1; x++)
269:                 {
270:                     _ecgPixels[y * ECG_WIDTH + x] = _ecgPixels[y * ECG_WIDTH + (x + 1)];
271:                 }
272:             }
273: 
274:             // Calculate current Y plot on right edge
275:             float pulse = (alitaCyborg != null) ? alitaCyborg.currentNormalizedPulse : 0f;
276:             _ecgTimer += Time.deltaTime * 3.5f;
277: 
278:             float baselineY = ECG_HEIGHT * 0.45f;
279:             float targetY = baselineY + (pulse * (ECG_HEIGHT * 0.42f));
280:             // Add subtle electronic noise
281:             targetY += Mathf.Sin(_ecgTimer * 12f) * 1.5f;
282:             int plotY = Mathf.Clamp(Mathf.RoundToInt(targetY), 1, ECG_HEIGHT - 2);
283: 
284:             Color32 bg = new Color32(4, 14, 22, 180);
285:             Color32 cyanLine = new Color32(0, 245, 255, 255);
286:             Color32 cyanGlow = new Color32(0, 180, 220, 120);
287: 
288:             // Clear right column
289:             for (int y = 0; y < ECG_HEIGHT; y++)
290:             {
291:                 _ecgPixels[y * ECG_WIDTH + (ECG_WIDTH - 1)] = bg;
292:             }
293: 
294:             // Draw line point with glow
295:             _ecgPixels[plotY * ECG_WIDTH + (ECG_WIDTH - 1)] = cyanLine;
296:             if (plotY > 0) _ecgPixels[(plotY - 1) * ECG_WIDTH + (ECG_WIDTH - 1)] = cyanGlow;
297:             if (plotY < ECG_HEIGHT - 1) _ecgPixels[(plotY + 1) * ECG_WIDTH + (ECG_WIDTH - 1)] = cyanGlow;
298: 
299:             _ecgTexture.SetPixels32(_ecgPixels);
300:             _ecgTexture.Apply(false);
301: 
302:             // Update UI texts & indicators
303:             if (pulseIndicatorGlow != null)
304:             {
305:                 pulseIndicatorGlow.color = new Color(0f, 0.95f, 1f, Mathf.Clamp01(pulse * 1.5f + 0.15f));
306:             }
307: 
308:             if (ecgPulseStatusText != null)
309:             {
310:                 ecgPulseStatusText.text = pulse > 0.35f 
311:                     ? "> [URM CORE PULSE: HARMONIC DETECTED]" 
312:                     : "// [CORE FREQUENCY: 54.2 BPM DORMANT]";
313:                 ecgPulseStatusText.color = pulse > 0.35f ? new Color(0.2f, 1f, 0.5f) : new Color(0f, 0.85f, 1f);
314:             }
315:         }
