339:         public void PlayAwakeningSurgeSound()
340:         {
341:             int sampleRate = 44100;
342:             int samples = (int)(sampleRate * 1.6f);
343:             float[] data = new float[samples];
344:             for (int i = 0; i < samples; i++)
345:             {
346:                 float t = (float)i / sampleRate;
347:                 // Heavy sub-bass building into high-frequency resonant charge
348:                 float freq = Mathf.Lerp(45f, 480f, Mathf.Pow(t / 1.6f, 2.0f));
349:                 float amp = Mathf.Sin(t / 1.6f * Mathf.PI);
350:                 data[i] = Mathf.Sin(2f * PI() * freq * t) * amp * 0.45f;
351:             }
352:             AudioClip clip = AudioClip.Create("Awakening_Surge", samples, 1, sampleRate, false);
353:             clip.SetData(data, 0);
354:             if (uiAudioSource != null) uiAudioSource.PlayOneShot(clip, 0.85f);
355:         }
356: 
357:         private static float PI() => Mathf.PI;
358: 
359:         private void PlayProceduralTone(float freq, float duration, float volume)
360:         {
361:             int sampleRate = 44100;
362:             int samples = (int)(sampleRate * duration);
363:             float[] data = new float[samples];
364:             for (int i = 0; i < samples; i++)
365:             {
366:                 float t = (float)i / sampleRate;
367:                 float envelope = Mathf.Sin(t / duration * Mathf.PI);
368:                 data[i] = Mathf.Sin(2f * Mathf.PI * freq * t) * envelope * volume;
369:             }
370:             AudioClip clip = AudioClip.Create("UI_Tone", samples, 1, sampleRate, false);
371:             clip.SetData(data, 0);
372:             if (uiAudioSource != null) uiAudioSource.PlayOneShot(clip, volume);
373:         }
