404:             float duration = 1.8f;
405:             while (elapsed < duration)
406:             {
407:                 elapsed += Time.deltaTime;
408:                 float progress = elapsed / duration;
409: 
410:                 if (hudCanvasGroup != null)
411:                 {
412:                     hudCanvasGroup.alpha = Mathf.Lerp(1f, 0f, progress);
413:                 }
414: 
415:                 if (glitchOverlayGroup != null)
416:                 {
417:                     glitchOverlayGroup.blocksRaycasts = false;
418:                     glitchOverlayGroup.alpha = Mathf.PingPong(progress * 8f, 0.45f);
419:                 }
420: 
421:                 yield return null;
422:             }
423: 
424:             if (hudCanvasGroup != null) hudCanvasGroup.alpha = 0f;
425:             if (glitchOverlayGroup != null)
426:             {
427:                 glitchOverlayGroup.alpha = 0f;
428:                 glitchOverlayGroup.blocksRaycasts = false;
429:             }
430: 
431:             // 5. Fire Cutscene Hook Event
432:             onAwakeningCutsceneTriggered?.Invoke();
433: 
434:             // 6. Check if custom cutscene is handled
435:             if (hasCustomCutscene)
436:             {
437:                 Debug.Log("[AlitaStartMenu] Custom cutscene triggered. Waiting for cutscene completion callback...");
438:                 // The user's cutscene will call CompleteCutsceneAndStartGame() when finished!
439:             }
440:             else
441:             {
442:                 // Default immediate transition to Cyber City gameplay
443:                 yield return new WaitForSeconds(0.4f);
444:                 ProceedToGameScene();
445:             }
446:         }
