private void UpdateFinished()
{
    _fadeAlpha = Mathf.MoveTowards(_fadeAlpha, 1.0f, Time.deltaTime * 0.55f);

    if (_fadeAlpha >= 0.85f && !_isLoadingNextScene)
    {
        _finishedTimer += Time.deltaTime;

        if ((autoAdvanceToNextScene && _finishedTimer >= transitionCardDuration) ||
            Input.GetKeyDown(KeyCode.Space) || Input.GetKeyDown(KeyCode.Return))
        {
            StartCoroutine(TransitionToNextSceneRoutine());
        }
    }
}

public void SkipToFinish()
{
    currentPhase = CutscenePhase.Finished;
    _phaseTime = 0f;
    _finishedTimer = 0f;
    SetDoctorAnimation(0f, false, false, true);
    _currentSubtitle = "";
    _fadeAlpha = 1.0f;
}

private IEnumerator TransitionToNextSceneRoutine()
{
    _isLoadingNextScene = true;
    _fadeAlpha = 1.0f;

    if (musicSource != null) musicSource.volume = 0f;
    if (stormSystem != null && stormSystem.rainAudioSource != null)
    {
        stormSystem.rainAudioSource.volume = 0f;
    }

    yield return new WaitForSeconds(0.25f);

    var op = UnityEngine.SceneManagement.SceneManager.LoadSceneAsync(nextCutsceneSceneName);
    if (op != null)
    {
        while (!op.isDone)
        {
            _loadProgress = Mathf.Clamp01(op.progress / 0.9f);
            yield return null;
        }
    }
}

