43:         [MenuItem("Tools/Alita Battle Angel/Generate Clinic Awakening Cutscene (Tron Style)", false, 20)]
44:         public static void GenerateAwakeningScene()
45:         {
46:             Debug.Log("[AlitaAwakening] Starting Tron-style Clinic Awakening Cutscene Generation...");
47: 
48:             Directory.CreateDirectory("Assets/Scenes");
49: 
50:             // 1. Create clean empty scene
51:             var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
52: 
53:             // 2. Build Chamber Architecture
54:             GameObject chamberRoot = BuildTronChamber();
55: 
56:             // 3. Build Hibernation Pod & Platform
57:             Transform podCanopy;
58:             GameObject podGo = SpawnHibernationPod(out podCanopy);
59: 
60:             // 4. Spawn Alita in Doll Body inside the pod
61:             Light coreLight, leftEyeLight, rightEyeLight;
62:             GameObject alitaGo = SpawnAlitaInPod(podGo.transform, out coreLight, out leftEyeLight, out rightEyeLight);
63: 
64:             // 5. Spawn Dr. Dyson Ido at diagnostic console
65:             GameObject doctorGo = SpawnDoctor();
66: 
67:             // 6. Spawn High-Tech Medical & Holographic Hardware
68:             SpawnMedicalHardware(chamberRoot.transform);
69: 
70:             // 7. Lighting & Post-Processing
71:             Light overheadSurgLight;
72:             BuildLightingAndPostProcessing(out overheadSurgLight);
73: 
74:             // 8. Visual Effects (Cryo Steam & Laser Scanner)
75:             ParticleSystem cryoSteamFX;
76:             LineRenderer scanLaserLine;
77:             BuildVFX(podGo.transform, out cryoSteamFX, out scanLaserLine);
78: 
79:             // 9. Main Camera
80:             GameObject camGo = BuildCinematicCamera();
81: 
82:             // 10. Master Controller Setup
83:             GameObject controllerGo = new GameObject("Alita_Awakening_Cutscene_Controller");
84:             var controller = controllerGo.AddComponent<AlitaAwakeningCutsceneController>();
85: 
86:             controller.alitaDollBody = alitaGo;
87:             controller.alitaAnimator = alitaGo.GetComponent<Animator>();
88:             if (controller.alitaAnimator != null) controller.alitaAnimator.enabled = false;
89: 
90:             controller.doctorActor = doctorGo;
91:             controller.doctorAnimator = doctorGo.GetComponentInChildren<Animator>();
92: 
93:             controller.podBase = podGo.transform;
94:             controller.podCanopy = podCanopy;
95: 
96:             controller.overheadSurgicalLight = overheadSurgLight;
97:             controller.quantumCoreLight = coreLight;
98:             controller.leftEyeOpticLight = leftEyeLight;
99:             controller.rightEyeOpticLight = rightEyeLight;
100: 
101:             controller.cryoSteamFX = cryoSteamFX;
102:             controller.scanLaserLine = scanLaserLine;
103:             controller.cutsceneCamera = camGo.GetComponent<Camera>();
