105:             // Assign Laser Grid Material for pulsing
106:             var gridMat = AssetDatabase.LoadAssetAtPath<Material>(LaserGridMatPath);
107:             if (gridMat != null) controller.tronGridMaterial = gridMat;
108: 
109:             // 11. Save Scene and Add to Build Settings
110:             EditorSceneManager.SaveScene(scene, ScenePath);
111:             AddSceneToBuildSettings(ScenePath);
112: 
113:             Debug.Log($"[AlitaAwakening] SUCCESS: Clinic Awakening Cutscene generated and saved to {ScenePath}!");
114:         }
