479:         private static Transform FindChildRecursive(Transform parent, string childName)
480:         {
481:             if (parent == null) return null;
482:             if (parent.name.Equals(childName, StringComparison.OrdinalIgnoreCase) || parent.name.Contains(childName)) return parent;
483:             for (int i = 0; i < parent.childCount; i++)
484:             {
485:                 Transform found = FindChildRecursive(parent.GetChild(i), childName);
486:                 if (found != null) return found;
487:             }
488:             return null;
489:         }
