495:             // 1. Overhead Volumetric Surgical Light
496:             GameObject surgGo = new GameObject("Light_Overhead_Surgical_Spot");
497:             surgGo.transform.SetParent(lightRoot.transform);
498:             surgGo.transform.position = new Vector3(0f, 5.2f, 0.2f);
