using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;

namespace Alita
{
    public enum ClinicPhase
    {
        ClinicEntrance,         // 0s - 6s: Ido enters carrying Alita into his warm, rainy workshop
        LayingOnOperatingBed,   // 6s - 13s: Ido approaches the surgical bed, gently lays Alita down
        DiagnosticConnection,  // 13s - 22s: Ido connects neural cable, heart core pulses, monitors boot
        DollBodyMemory,         // 22s - 31s: Ido gazes at his daughter's porcelain doll body in stasis pod
        TerminalWorkstation,    // 31s - 39s: Ido sits at terminal desk, types neural reboot commands
        DetonationHandoff       // 39s - 43s: Blinding terminal detonation flash -> seamless jump to Cutscene 2
    }

    /// <summary>
    /// Master Narrative Controller for ACT 1.5: DR. IDO'S CYBER-SURGERY CLINIC & WORKSHOP.
    /// Bridges the visceral emotional gap between the Scrapyard Discovery and the Cyberspace Awakening.
    /// Features:
    /// - Moody clinic atmosphere: Rain on windows, warm tungsten surgical lamps, and cyan holograms
    /// - Dr. Ido carrying Alita in from the storm and placing her gently onto the operating bed
    /// - Diagnostic cable magnetic latching, quantum heart flare, and multi-monitor telemetry boot
    /// - Emotional reflection on his late daughter's doll body in the glass stasis pod
    /// - Terminal command execution leading directly into Act 2 (TRON Ares IMAX Awakening)
    /// </summary>
    public class AlitaClinicWorkshopController : MonoBehaviour
    {
        public static AlitaClinicWorkshopController Instance { get; private set; }

        [Header("Scene Progression")]
        public ClinicPhase currentPhase = ClinicPhase.ClinicEntrance;
        public float phaseTimer = 0f;
        public float totalSceneTimer = 0f;
        public string nextAwakeningSceneName = "Alita_Tron_Awakening";
        public bool isPlaying = true;
        public bool allowSkip = true;

        [Header("Actors & Characters")]
        public GameObject doctorActor;
        public Animator doctorAnimator;
        public GameObject carriedAlitaTorso;
        public GameObject restingAlitaOnBed;
        public GameObject porcelainDollInPod;

        [Header("Surgical & Diagnostic Hardware")]
        public Transform operatingBedTransform;
        public Transform terminalDeskTransform;
        public Transform stasisPodTransform;
        public Light overheadSurgicalLight;
        public Light deskLampLight;
        public Light alitaCoreGlowLight;
        public Light stasisPodInteriorLight;
        public Transform diagnosticCableProbe;

        [Header("Cameras & Framing")]
        public Camera mainCamera;
        public float cameraFov = 38f;
        public bool allowMouseLook = true;

        [Header("Audio Sources")]
        public AudioSource ambientRainSource;
        public AudioSource ambientDroneSource;
        public AudioSource voiceAudioSource;
        public AudioSource sfxAudioSource;

        [Header("Waypoints")]
        public Vector3 entranceDoorPos = new Vector3(4.5f, 0f, -4.0f);
        public Vector3 bedsidePos = new Vector3(0.85f, 0f, 0.2f);
        public Vector3 terminalChairPos = new Vector3(-2.4f, 0f, 1.4f);

        // Subtitles and Presentation
        private string _activeSubtitle = "";
        private float _subtitleTimer = 0f;
        private float _fadeAlpha = 1.0f;
        private float _detonationWhiteAlpha = 0f;
        private bool _isLoadingNext = false;
        private float _loadProgress = 0f;

        // Sound Synthesis Cache
        private AudioClip _relayClickClip;
        private AudioClip _heartPulseClip;
        private AudioClip _terminalBeepClip;
        private float _lastKeystrokeTime = 0f;

        // Cinematic Framing Points
        private Vector3 _camTargetPos;
        private Vector3 _camLookTarget;
        private float _camTargetFov = 38f;

        private void Awake()
        {
            Instance = this;
            InitializeAudioSynthesizer();
        }

        private void Start()
        {
            if (mainCamera == null) mainCamera = Camera.main;

            currentPhase = ClinicPhase.ClinicEntrance;
            phaseTimer = 0f;
            totalSceneTimer = 0f;
            _fadeAlpha = 1.0f;
            _detonationWhiteAlpha = 0f;
            _isLoadingNext = false;

            // Initial actor states:
            if (doctorActor != null)
            {
                doctorActor.transform.position = entranceDoorPos;
                Vector3 toBed = (bedsidePos - entranceDoorPos).normalized;
                toBed.y = 0;
                if (toBed != Vector3.zero) doctorActor.transform.rotation = Quaternion.LookRotation(toBed);
            }

            if (carriedAlitaTorso != null) carriedAlitaTorso.SetActive(true);
            if (restingAlitaOnBed != null) restingAlitaOnBed.SetActive(false);

            if (alitaCoreGlowLight != null) alitaCoreGlowLight.intensity = 0.25f;

            // Start ambient audio
            if (ambientRainSource != null && !ambientRainSource.isPlaying) ambientRainSource.Play();
            if (ambientDroneSource != null && !ambientDroneSource.isPlaying) ambientDroneSource.Play();

            SetSubtitle("LOWER CITY — DR. DYSON IDO'S CYBER-SURGERY WORKSHOP\nTIME: 03:22 AM // RAIN HEAVY OVER SECTOR 4", 5.5f);
        }

        private void InitializeAudioSynthesizer()
        {
            if (sfxAudioSource == null)
            {
                sfxAudioSource = gameObject.AddComponent<AudioSource>();
                sfxAudioSource.spatialBlend = 0f;
            }

            // Diagnostic relay click
            int rSamples = 1200;
            _relayClickClip = AudioClip.Create("Relay_Click", rSamples, 1, 44100, false);
            float[] rData = new float[rSamples];
            for (int i = 0; i < rSamples; i++)
            {
                float t = (float)i / rSamples;
                rData[i] = ((Random.value * 2f - 1f) * 0.4f + Mathf.Sin(t * 1900f * Mathf.PI * 2f) * 0.6f) * Mathf.Exp(-t * 24f) * 0.8f;
            }
            _relayClickClip.SetData(rData, 0);

            // Resonant Quantum Core Pulse
            int pSamples = 8820;
            _heartPulseClip = AudioClip.Create("Quantum_Pulse", pSamples, 1, 44100, false);
            float[] pData = new float[pSamples];
            for (int i = 0; i < pSamples; i++)
            {
                float t = (float)i / pSamples;
                float bass = Mathf.Sin(t * 68f * Mathf.PI * 2f) * Mathf.Exp(-t * 6f);
                float harmonic = Mathf.Sin(t * 136f * Mathf.PI * 2f) * Mathf.Exp(-t * 14f) * 0.4f;
                pData[i] = (bass + harmonic) * 0.9f;
            }
            _heartPulseClip.SetData(pData, 0);

            // Terminal Confirmation Chime
            int bSamples = 4410;
            _terminalBeepClip = AudioClip.Create("Terminal_Beep", bSamples, 1, 44100, false);
            float[] bData = new float[bSamples];
            for (int i = 0; i < bSamples; i++)
            {
                float t = (float)i / bSamples;
                bData[i] = Mathf.Sin(t * 960f * Mathf.PI * 2f) * Mathf.Exp(-t * 12f) * 0.5f;
            }
            _terminalBeepClip.SetData(bData, 0);
        }

        private void Update()
        {
            if (!isPlaying) return;

            phaseTimer += Time.deltaTime;
            totalSceneTimer += Time.deltaTime;

            // Fade in from black at opening
            if (_fadeAlpha > 0f && currentPhase != ClinicPhase.DetonationHandoff)
            {
                _fadeAlpha = Mathf.MoveTowards(_fadeAlpha, 0f, Time.deltaTime * 0.8f);
            }

            // Subtitle timer
            if (_subtitleTimer > 0f)
            {
                _subtitleTimer -= Time.deltaTime;
                if (_subtitleTimer <= 0f) _activeSubtitle = "";
            }

            // Skip to Act 2 directly via ESC or TAB
            if (allowSkip && !_isLoadingNext)
            {
                if (Input.GetKeyDown(KeyCode.Escape) || Input.GetKeyDown(KeyCode.Tab))
                {
                    StartCoroutine(TransitionToAwakeningRoutine());
                }
            }

            // Phase Sequence Logic
            switch (currentPhase)
            {
                case ClinicPhase.ClinicEntrance:
                    UpdateEntrancePhase();
                    break;

                case ClinicPhase.LayingOnOperatingBed:
                    UpdateLayingOnBedPhase();
                    break;

                case ClinicPhase.DiagnosticConnection:
                    UpdateDiagnosticPhase();
                    break;

                case ClinicPhase.DollBodyMemory:
                    UpdateDollBodyPhase();
                    break;

                case ClinicPhase.TerminalWorkstation:
                    UpdateTerminalWorkstationPhase();
                    break;

                case ClinicPhase.DetonationHandoff:
                    UpdateDetonationPhase();
                    break;
            }
        }

        private void LateUpdate()
        {
            UpdateCinematicCamera();
        }

        #region Phase Sequences

        private void UpdateEntrancePhase()
        {
            // Doctor walks carrying Alita from entrance door towards bedside
            float t = Mathf.Clamp01(phaseTimer / 6.0f);
            float smoothT = Mathf.SmoothStep(0f, 1f, t);

            if (doctorActor != null)
            {
                doctorActor.transform.position = Vector3.Lerp(entranceDoorPos, bedsidePos, smoothT);
                Vector3 moveDir = (bedsidePos - entranceDoorPos).normalized;
                moveDir.y = 0;
                if (moveDir != Vector3.zero)
                {
                    doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(moveDir), Time.deltaTime * 5f);
                }
            }

            SetDoctorAnimSpeed(smoothT < 0.95f ? 1.0f : 0f, isCarrying: true);

            if (phaseTimer >= 6.0f)
            {
                currentPhase = ClinicPhase.LayingOnOperatingBed;
                phaseTimer = 0f;
                SetSubtitle("Dr. Dyson Ido: \"Out of the storm... safe and sound on the table.\"", 4.5f);
            }
        }

        private void UpdateLayingOnBedPhase()
        {
            float t = Mathf.Clamp01(phaseTimer / 7.0f);

            // Doctor stands beside bed and turns to face operating surface
            if (doctorActor != null && operatingBedTransform != null)
            {
                Vector3 toBed = (operatingBedTransform.position - doctorActor.transform.position).normalized;
                toBed.y = 0;
                if (toBed != Vector3.zero)
                {
                    doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(toBed), Time.deltaTime * 4f);
                }
            }

            // Transfer Alita from carried arms onto operating bed mattress at 2.8s
            if (phaseTimer >= 2.8f && carriedAlitaTorso != null && carriedAlitaTorso.activeSelf)
            {
                carriedAlitaTorso.SetActive(false);
                if (restingAlitaOnBed != null)
                {
                    restingAlitaOnBed.SetActive(true);
                }
                PlaySfx(_relayClickClip, 0.7f);
            }

            // Overhead surgical spotlight ramps up warmly
            if (overheadSurgicalLight != null)
            {
                overheadSurgicalLight.intensity = Mathf.Lerp(1.2f, 4.2f, Mathf.Clamp01(phaseTimer / 4.5f));
            }

            SetDoctorAnimSpeed(0f, isCarrying: (phaseTimer < 2.8f));

            if (phaseTimer >= 7.0f)
            {
                currentPhase = ClinicPhase.DiagnosticConnection;
                phaseTimer = 0f;
                SetSubtitle("Dr. Dyson Ido: \"Let's interface with that Martian quantum core...\"", 5.0f);
            }
        }

        private void UpdateDiagnosticPhase()
        {
            // Dr. Ido reaches forward and connects diagnostic probe
            if (phaseTimer >= 2.0f && phaseTimer < 2.1f)
            {
                PlaySfx(_relayClickClip, 0.85f);
            }

            // Heart core flaring & rhythmic pulse
            if (phaseTimer >= 2.4f)
            {
                if (alitaCoreGlowLight != null)
                {
                    float pulse = Mathf.PingPong((phaseTimer - 2.4f) * 2.2f, 1.8f) + 1.2f;
                    alitaCoreGlowLight.intensity = pulse;
                }
            }

            // Telemetry heartbeat audio
            if (phaseTimer >= 3.5f && phaseTimer < 3.6f)
            {
                PlaySfx(_heartPulseClip, 0.9f);
            }
            if (phaseTimer >= 5.5f && phaseTimer < 5.6f)
            {
                PlaySfx(_heartPulseClip, 0.85f);
            }

            if (phaseTimer >= 9.0f)
            {
                currentPhase = ClinicPhase.DollBodyMemory;
                phaseTimer = 0f;
                SetSubtitle("Dr. Dyson Ido: \"Antimatter core responsive... cellular brain tissue 100% intact.\"", 5.5f);
            }
        }

        private void UpdateDollBodyPhase()
        {
            // Doctor turns gaze toward the corner stasis pod containing his daughter's doll body
            if (doctorActor != null && stasisPodTransform != null)
            {
                Vector3 toPod = (stasisPodTransform.position - doctorActor.transform.position).normalized;
                toPod.y = 0;
                if (toPod != Vector3.zero)
                {
                    doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(toPod), Time.deltaTime * 3.5f);
                }
            }

            // Soft stasis light swell on the porcelain doll body
            if (stasisPodInteriorLight != null)
            {
                stasisPodInteriorLight.intensity = Mathf.PingPong(phaseTimer * 0.8f, 0.6f) + 1.4f;
            }

            if (phaseTimer >= 3.5f && phaseTimer < 3.6f)
            {
                SetSubtitle("Dr. Dyson Ido: \"I sculpted this porcelain chassis for my lost daughter. Perhaps... she saved it for you.\"", 5.5f);
            }

            if (phaseTimer >= 9.0f)
            {
                currentPhase = ClinicPhase.TerminalWorkstation;
                phaseTimer = 0f;
                SetSubtitle("Dr. Dyson Ido: \"Three hundred years in stasis... let's see who you were, little angel.\"", 5.0f);
            }
        }

        private void UpdateTerminalWorkstationPhase()
        {
            float t = Mathf.Clamp01(phaseTimer / 5.5f);
            float smoothT = Mathf.SmoothStep(0f, 1f, t);

            // Doctor walks over and takes a seat at his master terminal desk
            if (doctorActor != null)
            {
                doctorActor.transform.position = Vector3.Lerp(bedsidePos, terminalChairPos, smoothT);
                Vector3 toDesk = (terminalDeskTransform != null ? (terminalDeskTransform.position - doctorActor.transform.position).normalized : Vector3.forward);
                toDesk.y = 0;
                if (toDesk != Vector3.zero)
                {
                    doctorActor.transform.rotation = Quaternion.Slerp(doctorActor.transform.rotation, Quaternion.LookRotation(toDesk), Time.deltaTime * 4.5f);
                }
            }

            SetDoctorAnimSpeed(smoothT < 0.92f ? 0.9f : 0f, isCarrying: false);

            // Keystroke clicks as Ido rapidly types the neural bridge script
            if (phaseTimer >= 5.5f && phaseTimer < 8.0f)
            {
                if (Time.time - _lastKeystrokeTime > 0.12f)
                {
                    _lastKeystrokeTime = Time.time;
                    PlayProceduralKeystroke();
                }
            }

            if (phaseTimer >= 8.0f)
            {
                currentPhase = ClinicPhase.DetonationHandoff;
                phaseTimer = 0f;
                PlaySfx(_terminalBeepClip, 0.9f);
                SetSubtitle("Dr. Dyson Ido: \"Neural bridge synchronized. Reconstructing consciousness matrix...\"", 4.0f);
            }
        }

        private void UpdateDetonationPhase()
        {
            // Enter slam detonates a blinding flash of incandescent light
            float t = Mathf.Clamp01(phaseTimer / 3.5f);
            _detonationWhiteAlpha = Mathf.SmoothStep(0f, 1f, t);

            if (phaseTimer >= 2.0f && !_isLoadingNext)
            {
                StartCoroutine(TransitionToAwakeningRoutine());
            }
        }

        private IEnumerator TransitionToAwakeningRoutine()
        {
            _isLoadingNext = true;
            _detonationWhiteAlpha = 1.0f;

            // Fade audio down
            if (ambientRainSource != null) ambientRainSource.volume = 0f;
            if (ambientDroneSource != null) ambientDroneSource.volume = 0f;

            yield return new WaitForSeconds(0.2f);

            var op = SceneManager.LoadSceneAsync(nextAwakeningSceneName);
            if (op != null)
            {
                while (!op.isDone)
                {
                    _loadProgress = Mathf.Clamp01(op.progress / 0.9f);
                    yield return null;
                }
            }
        }

        #endregion

        #region Camera Choreography

        private void UpdateCinematicCamera()
        {
            if (mainCamera == null) return;

            Vector3 bedPos = operatingBedTransform != null ? operatingBedTransform.position : Vector3.zero;
            Vector3 deskPos = terminalDeskTransform != null ? terminalDeskTransform.position : Vector3.zero;
            Vector3 podPos = stasisPodTransform != null ? stasisPodTransform.position : Vector3.zero;
            Vector3 docPos = doctorActor != null ? doctorActor.transform.position : entranceDoorPos;

            switch (currentPhase)
            {
                case ClinicPhase.ClinicEntrance:
                    // Atmospheric leading 3/4 tracking camera gliding backward in front of Dr. Ido entering
                    _camTargetPos = docPos + new Vector3(-1.8f, 1.45f, 2.6f);
                    _camLookTarget = docPos + Vector3.up * 1.25f;
                    _camTargetFov = 38f;
                    break;

                case ClinicPhase.LayingOnOperatingBed:
                    // High-angle surgical establishing shot framing Dr. Ido laying Alita on operating mattress
                    _camTargetPos = bedPos + new Vector3(1.9f, 2.1f, -1.8f);
                    _camLookTarget = bedPos + Vector3.up * 0.85f;
                    _camTargetFov = 34f;
                    break;

                case ClinicPhase.DiagnosticConnection:
                    // Intimate medium close-up of Alita's face and glowing chest under the surgical lamp
                    _camTargetPos = bedPos + new Vector3(-0.85f, 1.25f, -0.65f);
                    _camLookTarget = bedPos + Vector3.up * 0.92f;
                    _camTargetFov = 28f;
                    break;

                case ClinicPhase.DollBodyMemory:
                    // Over-the-shoulder framing Dr. Ido looking past at the glowing porcelain doll body in pod
                    _camTargetPos = docPos + new Vector3(0.55f, 1.55f, -1.4f);
                    _camLookTarget = podPos + Vector3.up * 1.35f;
                    _camTargetFov = 32f;
                    break;

                case ClinicPhase.TerminalWorkstation:
                    // Profile two-shot of Dr. Ido sitting at the illuminated terminal desk with bed behind
                    _camTargetPos = deskPos + new Vector3(-1.85f, 1.45f, -1.25f);
                    _camLookTarget = deskPos + Vector3.up * 1.15f;
                    _camTargetFov = 34f;
                    break;

                case ClinicPhase.DetonationHandoff:
                    // Extreme snap zoom pushing right into the illuminated CLI screen
                    float zoomT = Mathf.Clamp01(phaseTimer / 2.5f);
                    _camTargetPos = Vector3.Lerp(deskPos + new Vector3(-1.85f, 1.45f, -1.25f), deskPos + Vector3.up * 1.12f, zoomT);
                    _camLookTarget = deskPos + Vector3.up * 1.12f;
                    _camTargetFov = Mathf.Lerp(34f, 18f, zoomT);
                    break;
            }

            // Smooth interpolation
            mainCamera.transform.position = Vector3.Lerp(mainCamera.transform.position, _camTargetPos, Time.deltaTime * 4.5f);
            Vector3 dir = (_camLookTarget - mainCamera.transform.position).normalized;
            if (dir != Vector3.zero)
            {
                Quaternion targetRot = Quaternion.LookRotation(dir);
                mainCamera.transform.rotation = Quaternion.Slerp(mainCamera.transform.rotation, targetRot, Time.deltaTime * 4.5f);
            }
            mainCamera.fieldOfView = Mathf.Lerp(mainCamera.fieldOfView, _camTargetFov, Time.deltaTime * 3.5f);
        }

        #endregion

        #region Audio Helpers

        private void PlaySfx(AudioClip clip, float volume = 1f)
        {
            if (sfxAudioSource != null && clip != null)
            {
                sfxAudioSource.PlayOneShot(clip, volume);
            }
        }

        private void PlayProceduralKeystroke()
        {
            if (sfxAudioSource == null) return;
            int samples = 800;
            float[] data = new float[samples];
            float freq = Random.Range(1800f, 2600f);
            for (int i = 0; i < samples; i++)
            {
                float t = (float)i / samples;
                data[i] = ((Random.value * 2f - 1f) * 0.4f + Mathf.Sin(t * freq * Mathf.PI * 2f) * 0.6f) * Mathf.Exp(-t * 22f) * 0.35f;
            }
            AudioClip click = AudioClip.Create("KeyClick", samples, 1, 44100, false);
            click.SetData(data, 0);
            sfxAudioSource.PlayOneShot(click, 0.45f);
        }

        public void SetDoctorAnimSpeed(float speed, bool isCarrying = false)
        {
            if (doctorAnimator == null && doctorActor != null)
            {
                doctorAnimator = doctorActor.GetComponentInChildren<Animator>();
            }

            if (doctorAnimator != null)
            {
                doctorAnimator.SetFloat("Speed", speed);
                doctorAnimator.SetBool("IsCarrying", isCarrying);
            }
        }

        public void SetSubtitle(string text, float duration)
        {
            _activeSubtitle = text;
            _subtitleTimer = duration;
        }

        #endregion

        #region Presentation GUI

        private void OnGUI()
        {
            int sw = Screen.width;
            int sh = Screen.height;

            // 1. Cinematic Anamorphic Letterbox Bars (2.39:1)
            int barHeight = Mathf.Max(42, (int)(sh * 0.088f));
            GUI.color = Color.black;
            GUI.DrawTexture(new Rect(0, 0, sw, barHeight), Texture2D.whiteTexture);
            GUI.DrawTexture(new Rect(0, sh - barHeight, sw, barHeight), Texture2D.whiteTexture);

            // 2. Initial Fade-In from Black
            if (_fadeAlpha > 0.005f)
            {
                GUI.color = new Color(0f, 0f, 0f, _fadeAlpha);
                GUI.DrawTexture(new Rect(0, 0, sw, sh), Texture2D.whiteTexture);
            }

            // 3. Detonation Flash Transition to Act 2 (Pure blinding white / cyan flare)
            if (_detonationWhiteAlpha > 0.005f)
            {
                GUI.color = new Color(1f, 1f, 1f, _detonationWhiteAlpha);
                GUI.DrawTexture(new Rect(0, 0, sw, sh), Texture2D.whiteTexture);

                if (_detonationWhiteAlpha >= 0.7f)
                {
                    float textFade = (_detonationWhiteAlpha - 0.7f) / 0.3f;
                    GUIStyle transStyle = new GUIStyle(GUI.skin.label)
                    {
                        fontSize = Mathf.Clamp(sw / 46, 22, 34),
                        fontStyle = FontStyle.Bold,
                        alignment = TextAnchor.MiddleCenter
                    };
                    transStyle.normal.textColor = new Color(0.1f, 0.85f, 1.0f, textFade);
                    GUI.Label(new Rect(0, sh * 0.42f, sw, 44), "INITIATING DIGITAL CONSCIOUSNESS RECONSTRUCTION...", transStyle);

                    GUIStyle subStyle = new GUIStyle(GUI.skin.label)
                    {
                        fontSize = 13,
                        alignment = TextAnchor.MiddleCenter
                    };
                    subStyle.normal.textColor = new Color(0.2f, 0.2f, 0.3f, textFade);
                    GUI.Label(new Rect(0, sh * 0.42f + 46, sw, 26), "ENTERING MARTIAN BERSERKER NEURAL MATRIX", subStyle);
                }
            }

            // 4. Cinematic Subtitles with Drop Shadows
            if (!string.IsNullOrEmpty(_activeSubtitle) && _detonationWhiteAlpha < 0.5f)
            {
                GUIStyle subStyle = new GUIStyle(GUI.skin.label)
                {
                    fontSize = Mathf.Clamp(sw / 72, 14, 21),
                    fontStyle = FontStyle.Bold,
                    alignment = TextAnchor.MiddleCenter
                };

                // Drop shadows
                subStyle.normal.textColor = new Color(0f, 0f, 0f, 0.95f);
                GUI.Label(new Rect(1, sh - barHeight - 48 + 1, sw, 34), _activeSubtitle, subStyle);
                GUI.Label(new Rect(-1, sh - barHeight - 48 - 1, sw, 34), _activeSubtitle, subStyle);

                // Crisp subtitle text
                subStyle.normal.textColor = new Color(1f, 0.96f, 0.88f);
                GUI.Label(new Rect(0, sh - barHeight - 48, sw, 34), _activeSubtitle, subStyle);
            }

            // 5. Skip Prompt
            if (allowSkip && !_isLoadingNext && _detonationWhiteAlpha < 0.2f)
            {
                GUIStyle skipStyle = new GUIStyle(GUI.skin.label)
                {
                    fontSize = 11,
                    alignment = TextAnchor.MiddleRight
                };
                skipStyle.normal.textColor = new Color(0.7f, 0.8f, 0.9f, 0.5f);
                GUI.Label(new Rect(sw - 230, 12, 210, 22), "Press [ESC] to Skip to Act 2", skipStyle);
            }
        }

        #endregion
    }
}

