        public static void GenerateClinicWorkshopScene()
        {
            Debug.Log("[AlitaClinicWorkshop] Building Act 1.5: Dr. Ido's Cyber-Surgery Clinic...");

            Directory.CreateDirectory("Assets/Scenes");

            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            // 1. Clinic Room Architecture (Floor, Walls, Skylight)
            GameObject clinicEnv = BuildClinicArchitecture();

            // 2. Central Operating Bed
            Transform bedTransform;
            GameObject bedGo = SpawnOperatingBed(out bedTransform);

            // 3. Resting Alita Torso on the Operating Bed (Deactivated during phase 1)
            Light coreLight;
