            // 4. Stasis Pod with Porcelain Doll Body
            Transform podTransform;
            Light podInteriorLight;
            GameObject stasisPodGo = SpawnStasisPodWithDollBody(out podTransform, out podInteriorLight);

            // 5. Master Terminal Workstation Desk
            Transform deskTransform;
            Light deskLampLight;
            GameObject deskGo = SpawnTerminalWorkstation(out deskTransform, out deskLampLight);

            // 6. Secondary Hardware (Servers, Holo-Table, Medical Cabinets)
            SpawnSecondaryHardware(clinicEnv.transform);

            // 7. Lighting & Overhead Surgical Lamp
            Light surgLight;
            BuildLightingAndAtmosphere(bedTransform, out surgLight);

            // 8. Dr. Ido Actor & Carried Alita Torso
            GameObject carriedAlita;
            GameObject doctorActor = SpawnDoctorWithCarriedAlita(out carriedAlita);

            // 9. Camera & Audio Setup
            GameObject camGo = BuildCamera();
            AudioSource rainSrc, droneSrc;
            BuildAudioSources(clinicEnv, out rainSrc, out droneSrc);

            // 10. Master Controller Setup
            GameObject ctrlGo = new GameObject("Alita_Clinic_Workshop_Controller");
            var ctrl = ctrlGo.AddComponent<AlitaClinicWorkshopController>();

            ctrl.doctorActor = doctorActor;
            ctrl.doctorAnimator = doctorActor.GetComponentInChildren<Animator>();
            ctrl.carriedAlitaTorso = carriedAlita;
            ctrl.restingAlitaOnBed = restingAlita;
            ctrl.porcelainDollInPod = stasisPodGo;

            ctrl.operatingBedTransform = bedTransform;
            ctrl.terminalDeskTransform = deskTransform;
            ctrl.stasisPodTransform = podTransform;

            ctrl.overheadSurgicalLight = surgLight;
            ctrl.deskLampLight = deskLampLight;
            ctrl.alitaCoreGlowLight = coreLight;
            ctrl.stasisPodInteriorLight = podInteriorLight;

            ctrl.mainCamera = camGo.GetComponent<Camera>();
            ctrl.ambientRainSource = rainSrc;
            ctrl.ambientDroneSource = droneSrc;

            ctrl.entranceDoorPos = new Vector3(4.2f, 0f, -4.2f);
            ctrl.bedsidePos = new Vector3(0.85f, 0f, 0.2f);
            ctrl.terminalChairPos = new Vector3(-2.4f, 0f, 1.4f);
            ctrl.nextAwakeningSceneName = "Alita_Tron_Awakening";

            // Save Scene & Add to Build Settings
            EditorSceneManager.SaveScene(scene, ScenePath);
            AddSceneToBuildSettings(ScenePath);

            Debug.Log($"[AlitaClinicWorkshop] SUCCESS: Act 1.5 Clinic Workshop generated and saved to {ScenePath}!");
        }

        private static GameObject BuildClinicArchitecture()
