            floor.transform.SetParent(root.transform);
            floor.transform.position = Vector3.zero;
            floor.transform.localScale = new Vector3(1.4f, 1f, 1.4f);
            if (floorMat != null) floor.GetComponent<MeshRenderer>().sharedMaterial = floorMat;

            // Room Walls (North, South, East, West - 5.5m high)
            BuildWall(root.transform, "Wall_North", new Vector3(0f, 2.75f, 7.0f), new Vector3(14f, 5.5f, 0.4f), wallMat);
            BuildWall(root.transform, "Wall_South", new Vector3(0f, 2.75f, -7.0f), new Vector3(14f, 5.5f, 0.4f), wallMat);
            BuildWall(root.transform, "Wall_East", new Vector3(7.0f, 2.75f, 0f), new Vector3(0.4f, 5.5f, 14f), wallMat);
            BuildWall(root.transform, "Wall_West", new Vector3(-7.0f, 2.75f, 0f), new Vector3(0.4f, 5.5f, 14f), wallMat);

            // Ceiling with High Rainy Skylight Frame
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Quad);
            ceiling.name = "Ceiling";
            ceiling.transform.SetParent(root.transform);
            ceiling.transform.position = new Vector3(0f, 5.5f, 0f);
            ceiling.transform.rotation = Quaternion.Euler(-90f, 0f, 0f);
            ceiling.transform.localScale = new Vector3(14f, 14f, 1f);
