        private static void BuildLightingAndAtmosphere(Transform bedT, out Light overheadSurgLight)
        {
            GameObject lightRoot = new GameObject("Lighting_And_Atmosphere");

            // 1. Warm Volumetric Overhead Surgical Spotlight directly over Operating Bed
            GameObject surgGo = new GameObject("Light_Overhead_Surgical_Spot");
            surgGo.transform.SetParent(lightRoot.transform);
            surgGo.transform.position = bedT.position + new Vector3(0f, 3.8f, 0f);
            surgGo.transform.rotation = Quaternion.Euler(90f, 0f, 0f);

            overheadSurgLight = surgGo.AddComponent<Light>();
            overheadSurgLight.type = LightType.Spot;
            overheadSurgLight.spotAngle = 65f;
            overheadSurgLight.innerSpotAngle = 40f;
            overheadSurgLight.range = 6.5f;
            overheadSurgLight.color = new Color(1.0f, 0.94f, 0.85f); // Warm tungsten clinical glow
            overheadSurgLight.intensity = 3.6f;
            overheadSurgLight.shadows = LightShadows.Soft;

            // 2. Cyan Ambient Workshop Fill Light
            GameObject ambGo = new GameObject("Light_Clinic_Ambient_Fill");
            ambGo.transform.SetParent(lightRoot.transform);
            ambGo.transform.position = new Vector3(0f, 2.8f, -2.5f);
            Light amb = ambGo.AddComponent<Light>();
            amb.type = LightType.Point;
            amb.range = 14f;
            amb.color = new Color(0.1f, 0.55f, 0.85f);
            amb.intensity = 1.0f;
            amb.shadows = LightShadows.None;

            // 3. Post-Processing Volume
            GameObject volGo = new GameObject("Global_Clinic_PostProcess");
            volGo.transform.SetParent(lightRoot.transform);
            var vol = volGo.AddComponent<Volume>();
            vol.isGlobal = true;

            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            profile.name = "Clinic_Workshop_PostProcess_Profile";

            var bloom = profile.Add<Bloom>(true);
            bloom.intensity.value = 1.25f;
            bloom.threshold.value = 0.90f;
            bloom.tint.value = new Color(1.0f, 0.95f, 0.88f);

            var tone = profile.Add<Tonemapping>(true);
            tone.mode.value = TonemappingMode.ACES;

            var colorAdj = profile.Add<ColorAdjustments>(true);
            colorAdj.contrast.value = 14f;
            colorAdj.postExposure.value = 0.15f;

            var vignette = profile.Add<Vignette>(true);
            vignette.intensity.value = 0.38f;
            vignette.smoothness.value = 0.50f;

            vol.sharedProfile = profile;
        }

        private static GameObject SpawnDoctorWithCarriedAlita(out GameObject carriedAlita)
        {
            var docPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(DoctorCyberCityPath)
                ?? AssetDatabase.LoadAssetAtPath<GameObject>(DoctorPrefabPath);

            GameObject doctorActor = new GameObject("Doctor_Actor");
            doctorActor.transform.position = new Vector3(4.2f, 0f, -4.2f);
            doctorActor.transform.rotation = Quaternion.Euler(0f, -45f, 0f);

            if (docPrefab != null)
            {
                GameObject model = (GameObject)PrefabUtility.InstantiatePrefab(docPrefab, doctorActor.transform);
                model.name = "Doctor_Model";
                model.transform.localPosition = Vector3.zero;
                model.transform.localRotation = Quaternion.identity;

                // Silver hair
                var anim = model.GetComponent<Animator>();
                Transform head = anim != null ? anim.GetBoneTransform(HumanBodyBones.Head) : null;
                if (head != null && head.Find("Doctor_Hair") == null)
                {
                    var hairPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(DoctorHairPrefabPath);
                    if (hairPrefab != null)
                    {
                        GameObject hair = (GameObject)PrefabUtility.InstantiatePrefab(hairPrefab, head);
                        hair.name = "Doctor_Hair";
                        hair.transform.localPosition = Vector3.zero;
                        hair.transform.localRotation = Quaternion.identity;
                        var mat = AssetDatabase.LoadAssetAtPath<Material>(DoctorHairMatPath);
                        if (mat != null) hair.GetComponent<Renderer>().sharedMaterial = mat;
                    }
                }

                if (anim != null)
                {
                    var ac = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/PolygonCyberCity/Animations/AC_CyberNPC.controller");
                    if (ac != null) anim.runtimeAnimatorController = ac;
                    anim.applyRootMotion = false;
                }
            }

            // Carried Alita torso attached to Dr. Ido's chest during Phase 1
            var alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(AlitaBrokenPrefabPath);
            if (alitaPrefab != null)
            {
                carriedAlita = (GameObject)PrefabUtility.InstantiatePrefab(alitaPrefab, doctorActor.transform);
                carriedAlita.name = "Carried_Alita_Torso";
                carriedAlita.transform.localPosition = new Vector3(0.06f, 1.15f, 0.36f);
                carriedAlita.transform.localRotation = Quaternion.Euler(-120f, -8f, 115f);
                carriedAlita.transform.localScale = Vector3.one * 0.95f;
            }
            else
            {
                carriedAlita = new GameObject("Carried_Alita_Torso");
                carriedAlita.transform.SetParent(doctorActor.transform, false);
            }

            return doctorActor;
        }

        private static GameObject BuildCamera()
        {
            GameObject camGo = new GameObject("MainCamera");
            camGo.tag = "MainCamera";
            camGo.transform.position = new Vector3(2.4f, 1.8f, -2.4f);
            camGo.transform.rotation = Quaternion.Euler(14f, -40f, 0f);

            Camera cam = camGo.AddComponent<Camera>();
            cam.fieldOfView = 38f;
            cam.nearClipPlane = 0.05f;
            cam.farClipPlane = 100f;

            var uac = camGo.AddComponent<UniversalAdditionalCameraData>();
            uac.renderPostProcessing = true;
            uac.antialiasing = AntialiasingMode.SubpixelMorphologicalAntiAliasing;

            camGo.AddComponent<AudioListener>();
            return camGo;
        }

        private static void BuildAudioSources(GameObject parent, out AudioSource rainSrc, out AudioSource droneSrc)
        {
            GameObject audioRoot = new GameObject("Audio_Ambiance_Sources");
            audioRoot.transform.SetParent(parent.transform);

            // Rain source
            rainSrc = audioRoot.AddComponent<AudioSource>();
            rainSrc.playOnAwake = false;
            rainSrc.loop = true;
            rainSrc.volume = 0.45f;
            var rainClip = AssetDatabase.LoadAssetAtPath<AudioClip>(RainAudioPath);
            if (rainClip != null) rainSrc.clip = rainClip;

            // Drone source
            droneSrc = audioRoot.AddComponent<AudioSource>();
            droneSrc.playOnAwake = false;
            droneSrc.loop = true;
            droneSrc.volume = 0.38f;
            var droneClip = AssetDatabase.LoadAssetAtPath<AudioClip>(DroneAudioPath);
            if (droneClip != null) droneSrc.clip = droneClip;
        }

        private static void AddSceneToBuildSettings(string scenePath)
        {
            var scenes = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            if (!scenes.Exists(s => s.path == scenePath))
            {
                scenes.Add(new EditorBuildSettingsScene(scenePath, true));
                EditorBuildSettings.scenes = scenes.ToArray();
            }
        }
    }
}
