using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using Alita;

namespace Alita.EditorScripts
{
    public static class AlitaCutsceneMenuUIBuilder
    {
        private const string SCENE_PATH = "Assets/Scenes/Alita_Discovery_Cutscene.unity";

        // Asset Paths
        private const string FONT_ZEN_DOTS = "Assets/Synty/InterfaceSciFiMenus/Fonts/Zen_Dots/ZenDots-Regular SDF.asset";
        private const string FONT_QUANTICO_BOLD = "Assets/Synty/InterfaceSciFiMenus/Fonts/Quantico/Quantico-Bold SDF.asset";
        private const string FONT_EXO_SEMIBOLD = "Assets/Synty/InterfaceSciFiMenus/Fonts/exo-2-0/Exo2.0-SemiBold SDF.asset";

        private const string SPR_PANEL_BG = "Assets/Synty/InterfaceSciFiMenus/Sprites/SciFiMenus/SPR_SciFiMenus_Frame_Box_Large_01_Background.png";
        private const string SPR_PANEL_FRAME = "Assets/Synty/InterfaceSciFiMenus/Sprites/SciFiMenus/SPR_SciFiMenus_Frame_Box_Large_01.png";
        private const string SPR_CARD_BG = "Assets/Synty/InterfaceSciFiMenus/Sprites/SciFiMenus/SPR_SciFiMenus_Frame_Box_Small_01_Background.png";
        private const string SPR_CARD_FRAME = "Assets/Synty/InterfaceSciFiMenus/Sprites/SciFiMenus/SPR_SciFiMenus_Frame_Box_Small_01.png";
        private const string SPR_BRACKETS = "Assets/Synty/InterfaceSciFiMenus/Sprites/Crests/SPR_SciFiMenus_Crest_Brackets_01.png";
        private const string SPR_HOVER_GLOW = "Assets/Synty/InterfaceSciFiSoldierHUD/Sprites/FX/SPR_FX_SciFi_Box_Glowy.png";

        [MenuItem("Tools/Alita Battle Angel/Upgrade Cutscene UI (AAA Cyberpunk Glassmorphism)", false, 6)]
        public static void UpgradeCutsceneUI()
        {
            var scene = EditorSceneManager.OpenScene(SCENE_PATH, OpenSceneMode.Single);
            Debug.Log($"[AlitaCutsceneMenuUIBuilder] Upgrading Cutscene UI in {scene.path}...");

            var canvasGo = GameObject.Find("SciFi_Menu_Canvas");
            if (canvasGo == null)
            {
                Debug.LogError("[AlitaCutsceneMenuUIBuilder] SciFi_Menu_Canvas not found!");
                return;
            }

            Undo.RegisterFullObjectHierarchyUndo(canvasGo, "Upgrade Cutscene UI");

            // Ensure CanvasGroup on Canvas
            var canvasGroup = canvasGo.GetComponent<CanvasGroup>();
            if (canvasGroup == null) canvasGroup = canvasGo.AddComponent<CanvasGroup>();

            // Load Fonts
            var fontZenDots = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_ZEN_DOTS);
            var fontQuantico = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_QUANTICO_BOLD);
            var fontExo = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_EXO_SEMIBOLD);

            // Load Sprites
            var sprPanelBg = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_PANEL_BG);
            var sprPanelFrame = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_PANEL_FRAME);
            var sprCardBg = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_CARD_BG);
            var sprCardFrame = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_CARD_FRAME);
            var sprBrackets = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_BRACKETS);
            var sprGlow = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_HOVER_GLOW);

            // Hide or clean up outdated Synty template if present
            var oldSyntyScreen = canvasGo.transform.Find("Screen_SciFiMenus_Title");
            if (oldSyntyScreen != null)
            {
                oldSyntyScreen.gameObject.SetActive(false);
            }

            // Find or create Panel_Cyberpunk_LeftMenu
            Transform panelTrans = canvasGo.transform.Find("Panel_Cyberpunk_LeftMenu");
            GameObject panelGo;
            if (panelTrans == null)
            {
                panelGo = new GameObject("Panel_Cyberpunk_LeftMenu", typeof(RectTransform));
                panelGo.transform.SetParent(canvasGo.transform, false);
            }
            else
            {
                panelGo = panelTrans.gameObject;
            }

            // Clear old children from Panel_Cyberpunk_LeftMenu to rebuild clean, high-precision layout
            for (int i = panelGo.transform.childCount - 1; i >= 0; i--)
            {
                Object.DestroyImmediate(panelGo.transform.GetChild(i).gameObject);
            }

            // Configure Master Panel RectTransform (Left Anchor, towering sci-fi frame)
            var panelRt = panelGo.GetComponent<RectTransform>();
            panelRt.anchorMin = new Vector2(0f, 0.5f);
            panelRt.anchorMax = new Vector2(0f, 0.5f);
            panelRt.pivot = new Vector2(0f, 0.5f);
            panelRt.anchoredPosition = new Vector2(75f, 0f);
            panelRt.sizeDelta = new Vector2(530f, 890f);

            // Panel Background: Dark obsidian glassmorphic plate (9-slice)
            var panelImg = panelGo.GetComponent<Image>() ?? panelGo.AddComponent<Image>();
            panelImg.sprite = sprPanelBg;
            panelImg.type = Image.Type.Sliced;
            panelImg.color = new Color32(4, 11, 19, 235); // Sleek 92% obsidian dark cyan
            panelImg.raycastTarget = true;

            // 1. Panel Neon Outer Frame
            var borderFrameGo = CreateChild(panelGo, "Border_Neon_Frame");
            var borderFrameRt = borderFrameGo.GetComponent<RectTransform>();
            SetStretchFull(borderFrameRt);
            var borderFrameImg = borderFrameGo.AddComponent<Image>();
            borderFrameImg.sprite = sprPanelFrame;
            borderFrameImg.type = Image.Type.Sliced;
            borderFrameImg.color = new Color(0f, 0.92f, 1f, 0.85f);
            borderFrameImg.raycastTarget = false;

            // 2. Panel Glowing Corner Brackets
            if (sprBrackets != null)
            {
                var bracketsGo = CreateChild(panelGo, "Border_Corner_Brackets");
                var bracketsRt = bracketsGo.GetComponent<RectTransform>();
                SetStretchFull(bracketsRt, -6f, -6f, 6f, 6f);
                var bracketsImg = bracketsGo.AddComponent<Image>();
                bracketsImg.sprite = sprBrackets;
                bracketsImg.color = new Color(0f, 1f, 1f, 0.90f);
                bracketsImg.raycastTarget = false;
            }

            // 3. Inner Content Container
            var contentGo = CreateChild(panelGo, "Content_Container");
            var contentRt = contentGo.GetComponent<RectTransform>();
            SetStretchFull(contentRt, 32f, 26f, -32f, -26f);

            // ==========================================
            // SECTION A: HEADER
            // ==========================================
            var headerGo = CreateChild(contentGo, "Header_Section");
            var headerRt = headerGo.GetComponent<RectTransform>();
            SetTopAnchored(headerRt, 0f, 0f, 156f);

            // Beacon + Sector Live Feed
            var feedRowGo = CreateChild(headerGo, "Feed_Live_Row");
            var feedRowRt = feedRowGo.GetComponent<RectTransform>();
            SetTopAnchored(feedRowRt, 0f, -4f, 22f);

            // Pulsing Beacon Indicator Dot
            var beaconGo = CreateChild(feedRowGo, "Indicator_Beacon");
            var beaconRt = beaconGo.GetComponent<RectTransform>();
            beaconRt.anchorMin = new Vector2(0f, 0.5f);
            beaconRt.anchorMax = new Vector2(0f, 0.5f);
            beaconRt.pivot = new Vector2(0f, 0.5f);
            beaconRt.anchoredPosition = new Vector2(0f, 0f);
            beaconRt.sizeDelta = new Vector2(10f, 10f);
            var beaconImg = beaconGo.AddComponent<Image>();
            beaconImg.color = new Color(0f, 0.95f, 1f, 1f);

            // Live Feed Label
            var feedTextGo = CreateChild(feedRowGo, "Label_SectorTag");
            var feedTextRt = feedTextGo.GetComponent<RectTransform>();
            feedTextRt.anchorMin = new Vector2(0f, 0f);
            feedTextRt.anchorMax = new Vector2(1f, 1f);
            feedTextRt.offsetMin = new Vector2(18f, 0f);
            feedTextRt.offsetMax = Vector2.zero;
            var feedTmp = feedTextGo.AddComponent<TextMeshProUGUI>();
            feedTmp.font = fontQuantico != null ? fontQuantico : feedTmp.font;
            feedTmp.fontSize = 12.5f;
            feedTmp.characterSpacing = 2.5f;
            feedTmp.alignment = TextAlignmentOptions.MidlineLeft;
            feedTmp.text = "<color=#00F5FF>LIVE FEED</color>  <color=#52788A>//</color>  SECTOR 04 SALVAGE BASIN";
            feedTmp.color = new Color(0.68f, 0.88f, 0.98f, 0.95f);

            // Main Title "ALITA"
            var titleGo = CreateChild(headerGo, "Label_MainTitle_Alita");
            var titleRt = titleGo.GetComponent<RectTransform>();
            SetTopAnchored(titleRt, 0f, -28f, 66f);
            var titleTmp = titleGo.AddComponent<TextMeshProUGUI>();
            titleTmp.font = fontZenDots != null ? fontZenDots : titleTmp.font;
            titleTmp.fontSize = 56f;
            titleTmp.characterSpacing = 18f;
            titleTmp.alignment = TextAlignmentOptions.MidlineLeft;
            titleTmp.text = "ALITA";
            titleTmp.color = Color.white;

            // Subtitle "BATTLE ANGEL"
            var subtitleGo = CreateChild(headerGo, "Label_Subtitle_BattleAngel");
            var subtitleRt = subtitleGo.GetComponent<RectTransform>();
            SetTopAnchored(subtitleRt, 0f, -96f, 28f);
            var subtitleTmp = subtitleGo.AddComponent<TextMeshProUGUI>();
            subtitleTmp.font = fontQuantico != null ? fontQuantico : subtitleTmp.font;
            subtitleTmp.fontSize = 21f;
            subtitleTmp.characterSpacing = 7f;
            subtitleTmp.alignment = TextAlignmentOptions.MidlineLeft;
            subtitleTmp.text = "B A T T L E   A N G E L";
            subtitleTmp.color = new Color(0f, 0.95f, 1f, 1f);

            // Divider Line
            var divLineGo = CreateChild(headerGo, "Divider_Line");
            var divLineRt = divLineGo.GetComponent<RectTransform>();
            SetTopAnchored(divLineRt, 0f, -128f, 2f);
            var divLineImg = divLineGo.AddComponent<Image>();
            divLineImg.color = new Color(0f, 0.85f, 1f, 0.55f);

            // Classification Tag
            var classTagGo = CreateChild(headerGo, "Label_PrologueTag");
            var classTagRt = classTagGo.GetComponent<RectTransform>();
            SetTopAnchored(classTagRt, 0f, -134f, 18f);
            var classTagTmp = classTagGo.AddComponent<TextMeshProUGUI>();
            classTagTmp.font = fontExo != null ? fontExo : classTagTmp.font;
            classTagTmp.fontSize = 11.5f;
            classTagTmp.characterSpacing = 4f;
            classTagTmp.alignment = TextAlignmentOptions.MidlineLeft;
            classTagTmp.text = "PROLOGUE <color=#00E5FF>//</color> THE CYBORG DISCOVERY";
            classTagTmp.color = new Color(0.55f, 0.75f, 0.88f, 0.85f);

            // ==========================================
            // SECTION B: BIO-SYNAPSE ECG MONITOR CARD
            // ==========================================
            var ecgCardGo = CreateChild(contentGo, "Card_CoreTelemetry");
            var ecgCardRt = ecgCardGo.GetComponent<RectTransform>();
            SetTopAnchored(ecgCardRt, 0f, -168f, 126f);

            var ecgCardBgImg = ecgCardGo.AddComponent<Image>();
            ecgCardBgImg.sprite = sprCardBg;
            ecgCardBgImg.type = Image.Type.Sliced;
            ecgCardBgImg.color = new Color32(2, 9, 16, 230);

            var ecgCardFrameGo = CreateChild(ecgCardGo, "Frame");
            var ecgCardFrameRt = ecgCardFrameGo.GetComponent<RectTransform>();
            SetStretchFull(ecgCardFrameRt);
            var ecgCardFrameImg = ecgCardFrameGo.AddComponent<Image>();
            ecgCardFrameImg.sprite = sprCardFrame;
            ecgCardFrameImg.type = Image.Type.Sliced;
            ecgCardFrameImg.color = new Color(0f, 0.85f, 1f, 0.45f);
            ecgCardFrameImg.raycastTarget = false;

            // Header for ECG Monitor
            var ecgHeaderGo = CreateChild(ecgCardGo, "Label_ECG_Header");
            var ecgHeaderRt = ecgHeaderGo.GetComponent<RectTransform>();
            SetTopAnchored(ecgHeaderRt, 0f, -8f, 18f);
            ecgHeaderRt.offsetMin = new Vector2(14f, ecgHeaderRt.offsetMin.y);
            ecgHeaderRt.offsetMax = new Vector2(-14f, ecgHeaderRt.offsetMax.y);
            var ecgHeaderTmp = ecgHeaderGo.AddComponent<TextMeshProUGUI>();
            ecgHeaderTmp.font = fontQuantico != null ? fontQuantico : ecgHeaderTmp.font;
            ecgHeaderTmp.fontSize = 11f;
            ecgHeaderTmp.characterSpacing = 2f;
            ecgHeaderTmp.alignment = TextAlignmentOptions.MidlineLeft;
            ecgHeaderTmp.text = "<color=#00F5FF>● CORE TELEMETRY</color> <color=#496A79>//</color> MARTIAN ANTIMATTER REACTOR";
            ecgHeaderTmp.color = new Color(0.55f, 0.88f, 0.95f, 0.95f);

            // ECG Monitor RawImage
            var ecgRawGo = CreateChild(ecgCardGo, "RawImage_ECG_Waveform");
            var ecgRawRt = ecgRawGo.GetComponent<RectTransform>();
            SetTopAnchored(ecgRawRt, 0f, -30f, 54f);
            ecgRawRt.offsetMin = new Vector2(14f, ecgRawRt.offsetMin.y);
            ecgRawRt.offsetMax = new Vector2(-14f, ecgRawRt.offsetMax.y);
            var ecgRawImg = ecgRawGo.AddComponent<RawImage>();
            ecgRawImg.color = Color.white;
            ecgRawImg.raycastTarget = false;

            // ECG Status Subtitle
            var ecgStatusGo = CreateChild(ecgCardGo, "Label_ECG_Status");
            var ecgStatusRt = ecgStatusGo.GetComponent<RectTransform>();
            SetTopAnchored(ecgStatusRt, 0f, -92f, 22f);
            ecgStatusRt.offsetMin = new Vector2(14f, ecgStatusRt.offsetMin.y);
            ecgStatusRt.offsetMax = new Vector2(-14f, ecgStatusRt.offsetMax.y);
            var ecgStatusTmp = ecgStatusGo.AddComponent<TextMeshProUGUI>();
            ecgStatusTmp.font = fontExo != null ? fontExo : ecgStatusTmp.font;
            ecgStatusTmp.fontSize = 10.5f;
            ecgStatusTmp.characterSpacing = 1.5f;
            ecgStatusTmp.alignment = TextAlignmentOptions.MidlineLeft;
            ecgStatusTmp.text = "ANTIMATTER HEART CORE // BIO-STASIS STABLE";
            ecgStatusTmp.color = new Color(0.6f, 0.88f, 0.98f, 0.85f);

            // ==========================================
            // SECTION C: ACTION BUTTONS COLUMN
            // ==========================================
            var buttonColGo = CreateChild(contentGo, "Button_Column");
            var buttonColRt = buttonColGo.GetComponent<RectTransform>();
            SetTopAnchored(buttonColRt, 0f, -310f, 370f);

            // 1. Button: START JOURNEY
            var btn1Go = CreateButtonCard(
                buttonColGo,
                "Btn_StartJourney",
                0f,
                92f,
                sprCardBg,
                sprCardFrame,
                sprGlow,
                new Color32(2, 22, 36, 245), // Obsidian Cyan
                new Color(0f, 0.95f, 1f, 0.92f), // Cyan Neon Border
                new Color(0f, 0.95f, 1f, 0f), // Hover Glow Color
                "▶  START DISCOVERY",
                "GOD OF WAR SINGLE-TAKE // SEAMLESS IMMERSION",
                fontQuantico,
                fontExo,
                Color.white,
                new Color(0f, 0.9f, 1f, 0.95f),
                out Image btn1Glow
            );

            // 2. Button: CLINIC AWAKENING (TRON CHAPTER 1)
            var btn2Go = CreateButtonCard(
                buttonColGo,
                "Btn_ClinicAwakening",
                -106f,
                92f,
                sprCardBg,
                sprCardFrame,
                sprGlow,
                new Color32(26, 12, 4, 245), // Tron Warm Charcoal
                new Color(1f, 0.48f, 0.05f, 0.92f), // Tron Orange Border
                new Color(1f, 0.48f, 0.05f, 0f), // Hover Glow Color
                "◈  CLINIC AWAKENING",
                "CHAPTER I // TRON: ARES RECONSTRUCTION (120S)",
                fontQuantico,
                fontExo,
                new Color(1f, 0.96f, 0.92f, 1f),
                new Color(1f, 0.65f, 0.35f, 0.95f),
                out Image btn2Glow
            );

            // 3. Button: EXIT SIMULATION
            var btn3Go = CreateButtonCard(
                buttonColGo,
                "Btn_Quit",
                -212f,
                64f,
                sprCardBg,
                sprCardFrame,
                sprGlow,
                new Color32(10, 16, 22, 235), // Neutral Dark Metal
                new Color(0.38f, 0.54f, 0.70f, 0.75f), // Steel Slate Border
                new Color(0.40f, 0.60f, 0.80f, 0f), // Hover Glow Color
                "✕  EXIT SIMULATION",
                null,
                fontQuantico,
                fontExo,
                new Color(0.75f, 0.88f, 0.98f, 0.95f),
                Color.white,
                out Image btn3Glow
            );

            // ==========================================
            // SECTION D: FOOTER INPUT BADGE
            // ==========================================
            var footerGo = CreateChild(contentGo, "Footer_InputPrompt");
            var footerRt = footerGo.GetComponent<RectTransform>();
            footerRt.anchorMin = new Vector2(0f, 0f);
            footerRt.anchorMax = new Vector2(1f, 0f);
            footerRt.pivot = new Vector2(0.5f, 0f);
            footerRt.anchoredPosition = new Vector2(0f, 0f);
            footerRt.sizeDelta = new Vector2(0f, 46f);

            var footerBgImg = footerGo.AddComponent<Image>();
            footerBgImg.sprite = sprCardBg;
            footerBgImg.type = Image.Type.Sliced;
            footerBgImg.color = new Color32(3, 10, 16, 215);

            var footerFrameGo = CreateChild(footerGo, "Frame");
            var footerFrameRt = footerFrameGo.GetComponent<RectTransform>();
            SetStretchFull(footerFrameRt);
            var footerFrameImg = footerFrameGo.AddComponent<Image>();
            footerFrameImg.sprite = sprCardFrame;
            footerFrameImg.type = Image.Type.Sliced;
            footerFrameImg.color = new Color(0f, 0.85f, 1f, 0.35f);
            footerFrameImg.raycastTarget = false;

            var keyPromptGo = CreateChild(footerGo, "Label_KeyPrompt");
            var keyPromptRt = keyPromptGo.GetComponent<RectTransform>();
            SetStretchFull(keyPromptRt);
            var keyPromptTmp = keyPromptGo.AddComponent<TextMeshProUGUI>();
            keyPromptTmp.font = fontQuantico != null ? fontQuantico : keyPromptTmp.font;
            keyPromptTmp.fontSize = 12.5f;
            keyPromptTmp.characterSpacing = 2.5f;
            keyPromptTmp.alignment = TextAlignmentOptions.Center;
            keyPromptTmp.text = "<color=#00F5FF>[ SPACE ]</color>  OR  <color=#00F5FF>[ ENTER ]</color>  TO BEGIN JOURNEY";
            keyPromptTmp.color = new Color(0.80f, 0.94f, 1f, 0.95f);

            // ==========================================
            // ATTACH & CONFIGURE AlitaCutsceneSciFiMenu
            // ==========================================
            var menuController = canvasGo.GetComponent<AlitaCutsceneSciFiMenu>();
            if (menuController == null) menuController = canvasGo.AddComponent<AlitaCutsceneSciFiMenu>();

            menuController.canvasGroup = canvasGroup;
            menuController.btnStartJourney = btn1Go.GetComponent<Button>();
            menuController.btnClinicAwakening = btn2Go.GetComponent<Button>();
            menuController.btnQuit = btn3Go.GetComponent<Button>();

            menuController.startJourneyGlow = btn1Glow;
            menuController.clinicAwakeningGlow = btn2Glow;
            menuController.quitGlow = btn3Glow;

            menuController.ecgMonitorImage = ecgRawImg;
            menuController.ecgStatusText = ecgStatusTmp;
            menuController.beaconIndicator = beaconImg;
            menuController.keyPromptText = keyPromptTmp;

            // Wire AlitaCutsceneController
            var cutsceneController = Object.FindAnyObjectByType<AlitaCutsceneController>();
            if (cutsceneController != null)
            {
                cutsceneController.scifiMenuCanvasGroup = canvasGroup;
                EditorUtility.SetDirty(cutsceneController);
            }

            EditorUtility.SetDirty(menuController);
            EditorUtility.SetDirty(panelGo);
            EditorUtility.SetDirty(canvasGo);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);

            Debug.Log("[AlitaCutsceneMenuUIBuilder] AAA Cyberpunk Glassmorphism UI successfully constructed and saved!");
        }

        private static GameObject CreateChild(GameObject parent, string name)
        {
            var go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent.transform, false);
            return go;
        }

        private static void SetStretchFull(RectTransform rt, float left = 0f, float bottom = 0f, float right = 0f, float top = 0f)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = new Vector2(left, bottom);
            rt.offsetMax = new Vector2(right, top);
        }

        private static void SetTopAnchored(RectTransform rt, float posX, float posY, float height)
        {
            rt.anchorMin = new Vector2(0f, 1f);
            rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.anchoredPosition = new Vector2(posX, posY);
            rt.sizeDelta = new Vector2(0f, height);
        }

        private static GameObject CreateButtonCard(
            GameObject parent,
            string btnName,
            float posY,
            float height,
            Sprite sprBg,
            Sprite sprFrame,
            Sprite sprGlow,
            Color bgColor,
            Color frameColor,
            Color glowColor,
            string titleText,
            string subtitleText,
            TMP_FontAsset fontTitle,
            TMP_FontAsset fontSubtitle,
            Color titleColor,
            Color subtitleColor,
            out Image glowImage)
        {
            var btnGo = CreateChild(parent, btnName);
            var btnRt = btnGo.GetComponent<RectTransform>();
            SetTopAnchored(btnRt, 0f, posY, height);

            var btnBgImg = btnGo.AddComponent<Image>();
            btnBgImg.sprite = sprBg;
            btnBgImg.type = Image.Type.Sliced;
            btnBgImg.color = bgColor;
            btnBgImg.raycastTarget = true;

            var btnComp = btnGo.AddComponent<Button>();
            btnComp.targetGraphic = btnBgImg;
            var colors = btnComp.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1.1f, 1.1f, 1.1f, 1f);
            colors.pressedColor = new Color(0.85f, 0.85f, 0.85f, 1f);
            btnComp.colors = colors;

            // Frame
            var frameGo = CreateChild(btnGo, "Frame");
            var frameRt = frameGo.GetComponent<RectTransform>();
            SetStretchFull(frameRt);
            var frameImg = frameGo.AddComponent<Image>();
            frameImg.sprite = sprFrame;
            frameImg.type = Image.Type.Sliced;
            frameImg.color = frameColor;
            frameImg.raycastTarget = false;

            // Hover Glow Plate
            var glowGo = CreateChild(btnGo, "Hover_Glow");
            var glowRt = glowGo.GetComponent<RectTransform>();
            SetStretchFull(glowRt);
            glowImage = glowGo.AddComponent<Image>();
            glowImage.sprite = sprGlow;
            glowImage.type = Image.Type.Sliced;
            glowImage.color = glowColor;
            glowImage.raycastTarget = false;

            // Text Container
            var textContainerGo = CreateChild(btnGo, "Text_Container");
            var textContainerRt = textContainerGo.GetComponent<RectTransform>();
            SetStretchFull(textContainerRt, 22f, 8f, -22f, -8f);

            if (string.IsNullOrEmpty(subtitleText))
            {
                // Single line title
                var titleTmp = textContainerGo.AddComponent<TextMeshProUGUI>();
                titleTmp.font = fontTitle != null ? fontTitle : titleTmp.font;
                titleTmp.fontSize = 17f;
                titleTmp.characterSpacing = 3f;
                titleTmp.alignment = TextAlignmentOptions.MidlineLeft;
                titleTmp.text = titleText;
                titleTmp.color = titleColor;
                titleTmp.raycastTarget = false;
            }
            else
            {
                // Title
                var titleGo = CreateChild(textContainerGo, "Label_Title");
                var titleRt = titleGo.GetComponent<RectTransform>();
                titleRt.anchorMin = new Vector2(0f, 0.45f);
                titleRt.anchorMax = new Vector2(1f, 1f);
                titleRt.offsetMin = Vector2.zero;
                titleRt.offsetMax = Vector2.zero;
                var titleTmp = titleGo.AddComponent<TextMeshProUGUI>();
                titleTmp.font = fontTitle != null ? fontTitle : titleTmp.font;
                titleTmp.fontSize = 20f;
                titleTmp.characterSpacing = 3.5f;
                titleTmp.alignment = TextAlignmentOptions.MidlineLeft;
                titleTmp.text = titleText;
                titleTmp.color = titleColor;
                titleTmp.raycastTarget = false;

                // Subtitle
                var subGo = CreateChild(textContainerGo, "Label_Subtitle");
                var subRt = subGo.GetComponent<RectTransform>();
                subRt.anchorMin = new Vector2(0f, 0f);
                subRt.anchorMax = new Vector2(1f, 0.45f);
                subRt.offsetMin = Vector2.zero;
                subRt.offsetMax = Vector2.zero;
                var subTmp = subGo.AddComponent<TextMeshProUGUI>();
                subTmp.font = fontSubtitle != null ? fontSubtitle : subTmp.font;
                subTmp.fontSize = 11f;
                subTmp.characterSpacing = 2f;
                subTmp.alignment = TextAlignmentOptions.MidlineLeft;
                subTmp.text = subtitleText;
                subTmp.color = subtitleColor;
                subTmp.raycastTarget = false;
            }

            return btnGo;
        }
    }
}

