        var alita = GameObject.Find("Alita_BrokenCyborg_Laying");
        if (alita == null) alita = GameObject.Find("Alita");
        if (alita == null)
        {
            var alitaComps = Object.FindObjectsByType<Alita.AlitaBrokenCyborg>(FindObjectsSortMode.None);
            if (alitaComps.Length > 0) alita = alitaComps[0].gameObject;
        }

        if (alita != null)
        {
            result.Log("Alita found: {0}, pos={1}, active={2}", alita.name, alita.transform.position, alita.activeInHierarchy);
        }
        else
        {
            result.Log("Alita object not found by name");
        }

        var cam = GameObject.Find("MainCamera")?.GetComponent<Camera>();
        if (cam != null && alita != null)
        {
            Vector3 viewportPos = cam.WorldToViewportPoint(alita.transform.position);
            result.Log("Alita viewport position in MainCamera: {0}", viewportPos);
        }
    }
}

