                iconClinic,
                new Color32(26, 12, 4, 245), // Tron Warm Charcoal
                new Color(1f, 0.48f, 0.05f, 0.90f), // Tron Orange Border
                new Color(1f, 0.48f, 0.05f, 0f), // Hover Glow
                new Color(1f, 0.55f, 0.12f, 1f), // Icon Tint
                "CLINIC AWAKENING",
                "CHAPTER I // TRON: ARES RECONSTRUCTION",
