            var cutsceneController = Object.FindAnyObjectByType<AlitaCutsceneController>();
            if (cutsceneController != null)
            {
                cutsceneController.scifiMenuCanvasGroup = canvasGroup;

                // Also align the scene's MainCamera in edit mode so the framing is instant
                if (cutsceneController.cutsceneCamera != null)
                {
                    Vector3 focus = cutsceneController.GetAlitaFocusCenter();
                    cutsceneController.cutsceneCamera.transform.position = focus + new Vector3(-0.55f, 0.12f, -1.85f);
                    cutsceneController.cutsceneCamera.transform.LookAt(focus + new Vector3(-0.35f, -0.06f, 0f));
                    cutsceneController.cutsceneCamera.fieldOfView = 34f;
                    EditorUtility.SetDirty(cutsceneController.cutsceneCamera);
                }

                EditorUtility.SetDirty(cutsceneController);
            }

            EditorUtility.SetDirty(menuController);
            EditorUtility.SetDirty(panelGo);
            EditorUtility.SetDirty(canvasGo);
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);

            Debug.Log("[AlitaCutsceneMenuUIBuilder] AAA Cyberpunk Glassmorphism Menu successfully constructed and saved!");
        }

        private static GameObject CreateChild(GameObject parent, string name)
        {
            var go = new GameObject(name, typeof(RectTransform));
            go.transform.SetParent(parent.transform, false);
            return go;
        }

        private static void SetStretchFull(RectTransform rt, float left = 0f, float bottom = 0f, float right = 0f, float top = 0f)
        {
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = new Vector2(left, bottom);
            rt.offsetMax = new Vector2(right, top);
        }

        private static void SetTopAnchored(RectTransform rt, float posX, float posY, float height)
        {
            rt.anchorMin = new Vector2(0f, 1f);
            rt.anchorMax = new Vector2(1f, 1f);
            rt.pivot = new Vector2(0.5f, 1f);
            rt.anchoredPosition = new Vector2(posX, posY);
            rt.sizeDelta = new Vector2(0f, height);
        }

        private static GameObject CreateButtonCard(
            GameObject parent,
            string btnName,
            float posY,
            float height,
            Sprite sprBg,
            Sprite sprFrame,
            Sprite sprGlow,
            Sprite sprIcon,
            Color bgColor,
            Color frameColor,
            Color glowColor,
            Color iconColor,
            string titleText,
            string subtitleText,
            TMP_FontAsset fontTitle,
            TMP_FontAsset fontSubtitle,
            Color titleColor,
            Color subtitleColor,
            out Image glowImage)
        {
            var btnGo = CreateChild(parent, btnName);
            var btnRt = btnGo.GetComponent<RectTransform>();
            SetTopAnchored(btnRt, 0f, posY, height);

            var btnBgImg = btnGo.AddComponent<Image>();
            btnBgImg.sprite = sprBg;
            btnBgImg.type = Image.Type.Sliced;
            btnBgImg.color = bgColor;
            btnBgImg.raycastTarget = true;

            var btnComp = btnGo.AddComponent<Button>();
            btnComp.targetGraphic = btnBgImg;
            var colors = btnComp.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1.15f, 1.15f, 1.15f, 1f);
            colors.pressedColor = new Color(0.85f, 0.85f, 0.85f, 1f);
            btnComp.colors = colors;

            // Neon Border Frame
            var frameGo = CreateChild(btnGo, "Frame");
            var frameRt = frameGo.GetComponent<RectTransform>();
            SetStretchFull(frameRt);
            var frameImg = frameGo.AddComponent<Image>();
            frameImg.sprite = sprFrame;
            frameImg.type = Image.Type.Sliced;
            frameImg.color = frameColor;
            frameImg.raycastTarget = false;

            // Hover Glow Inner Plate
            var glowGo = CreateChild(btnGo, "Hover_Glow");
            var glowRt = glowGo.GetComponent<RectTransform>();
            SetStretchFull(glowRt);
            glowImage = glowGo.AddComponent<Image>();
            glowImage.sprite = sprGlow;
            glowImage.type = Image.Type.Sliced;
            glowImage.color = glowColor;
            glowImage.raycastTarget = false;

            // Content Row (Icon on left, Text on right)
            var contentRowGo = CreateChild(btnGo, "Content_Row");
            var contentRowRt = contentRowGo.GetComponent<RectTransform>();
            SetStretchFull(contentRowRt, 16f, 6f, -16f, -6f);

            // Left Icon
            if (sprIcon != null)
            {
                var iconGo = CreateChild(contentRowGo, "Icon");
                var iconRt = iconGo.GetComponent<RectTransform>();
                iconRt.anchorMin = new Vector2(0f, 0.5f);
                iconRt.anchorMax = new Vector2(0f, 0.5f);
                iconRt.pivot = new Vector2(0f, 0.5f);
                iconRt.anchoredPosition = new Vector2(0f, 0f);
                iconRt.sizeDelta = new Vector2(24f, 24f);

                var iconImg = iconGo.AddComponent<Image>();
                iconImg.sprite = sprIcon;
                iconImg.color = iconColor;
                iconImg.raycastTarget = false;
            }

            // Text Stack (offset by icon if present)
            float textLeftOffset = sprIcon != null ? 34f : 0f;
            var textStackGo = CreateChild(contentRowGo, "Text_Stack");
            var textStackRt = textStackGo.GetComponent<RectTransform>();
            SetStretchFull(textStackRt, textLeftOffset, 0f, 0f, 0f);

            if (string.IsNullOrEmpty(subtitleText))
            {
                // Single line centered vertically
                var titleTmp = textStackGo.AddComponent<TextMeshProUGUI>();
                titleTmp.font = fontTitle != null ? fontTitle : titleTmp.font;
                titleTmp.fontSize = 14f;
                titleTmp.characterSpacing = 2.5f;
                titleTmp.alignment = TextAlignmentOptions.MidlineLeft;
                titleTmp.text = titleText;
                titleTmp.color = titleColor;
                titleTmp.raycastTarget = false;
            }
            else
            {
                // Title (top half)
                var titleGo = CreateChild(textStackGo, "Label_Title");
                var titleRt = titleGo.GetComponent<RectTransform>();
                titleRt.anchorMin = new Vector2(0f, 0.42f);
                titleRt.anchorMax = new Vector2(1f, 1f);
                titleRt.offsetMin = Vector2.zero;
                titleRt.offsetMax = Vector2.zero;
                var titleTmp = titleGo.AddComponent<TextMeshProUGUI>();
                titleTmp.font = fontTitle != null ? fontTitle : titleTmp.font;
                titleTmp.fontSize = 18f;
                titleTmp.characterSpacing = 2.5f;
                titleTmp.alignment = TextAlignmentOptions.MidlineLeft;
                titleTmp.text = titleText;
                titleTmp.color = titleColor;
                titleTmp.raycastTarget = false;

                // Subtitle (bottom half)
                var subGo = CreateChild(textStackGo, "Label_Subtitle");
                var subRt = subGo.GetComponent<RectTransform>();
                subRt.anchorMin = new Vector2(0f, 0f);
                subRt.anchorMax = new Vector2(1f, 0.42f);
                subRt.offsetMin = Vector2.zero;
                subRt.offsetMax = Vector2.zero;
                var subTmp = subGo.AddComponent<TextMeshProUGUI>();
                subTmp.font = fontSubtitle != null ? fontSubtitle : subTmp.font;
                subTmp.fontSize = 10f;
                subTmp.characterSpacing = 1.8f;
                subTmp.alignment = TextAlignmentOptions.MidlineLeft;
                subTmp.text = subtitleText;
                subTmp.color = subtitleColor;
                subTmp.raycastTarget = false;
            }

            return btnGo;
        }
    }
}

