using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Alita.EditorScripts.AlitaCutsceneMenuUIBuilder.UpgradeCutsceneUI();

        // Render preview from MainCamera
        var cam = GameObject.Find("MainCamera")?.GetComponent<Camera>();
        if (cam == null)
        {
            result.LogError("MainCamera not found");
            return;
        }

        int width = 1920;
        int height = 1080;
        var rt = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32);
        var prevTarget = cam.targetTexture;
        cam.targetTexture = rt;
        cam.Render();

        RenderTexture.active = rt;
        var tex = new Texture2D(width, height, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, width, height), 0, 0);
        tex.Apply();

        cam.targetTexture = prevTarget;
        RenderTexture.active = null;
        Object.DestroyImmediate(rt);

        byte[] png = tex.EncodeToPNG();
        Object.DestroyImmediate(tex);

        string outPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\scrapyard_ui_preview.png";
        File.WriteAllBytes(outPath, png);

        result.Log("Successfully upgraded UI and rendered preview to {0}!", outPath);
    }
}

