using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using Alita;

namespace Alita.EditorScripts
{
    public static class AlitaCutsceneMenuUIBuilder
    {
        private const string SCENE_PATH = "Assets/Scenes/Alita_Discovery_Cutscene.unity";

        // Fonts
        private const string FONT_ZEN_DOTS = "Assets/Synty/InterfaceSciFiMenus/Fonts/Zen_Dots/ZenDots-Regular SDF.asset";
        private const string FONT_QUANTICO_BOLD = "Assets/Synty/InterfaceSciFiMenus/Fonts/Quantico/Quantico-Bold SDF.asset";
        private const string FONT_EXO_SEMIBOLD = "Assets/Synty/InterfaceSciFiMenus/Fonts/exo-2-0/Exo2.0-SemiBold SDF.asset";

        // Sprites
        private const string SPR_HOVER_GLOW = "Assets/Synty/InterfaceSciFiSoldierHUD/Sprites/FX/SPR_FX_SciFi_Box_Glowy.png";
        private const string ICON_START = "Assets/Synty/InterfaceSciFiMenus/Sprites/Icons_Menu/ICON_SciFiMenus_Menu_Solo_01_Clean.png";
        private const string ICON_CLINIC = "Assets/Synty/InterfaceSciFiMenus/Sprites/Icons_Menu/ICON_SciFiMenus_Menu_DNA_01_Clean.png";
        private const string ICON_QUIT = "Assets/Synty/InterfaceSciFiMenus/Sprites/Icons_Menu/ICON_SciFiMenus_Menu_Quit_01_Clean.png";

        [MenuItem("Tools/Alita Battle Angel/Upgrade Cutscene UI (AAA Cyberpunk Glassmorphism)", false, 6)]
        public static void UpgradeCutsceneUI()
        {
            var scene = EditorSceneManager.OpenScene(SCENE_PATH, OpenSceneMode.Single);
            Debug.Log($"[AlitaCutsceneMenuUIBuilder] Constructing sleek minimalist Cyberpunk Menu in {scene.path}...");

            var canvasGo = GameObject.Find("SciFi_Menu_Canvas");
            if (canvasGo == null)
            {
                Debug.LogError("[AlitaCutsceneMenuUIBuilder] SciFi_Menu_Canvas not found!");
                return;
            }

            Undo.RegisterFullObjectHierarchyUndo(canvasGo, "Upgrade Cutscene UI");

            var canvasGroup = canvasGo.GetComponent<CanvasGroup>();
            if (canvasGroup == null) canvasGroup = canvasGo.AddComponent<CanvasGroup>();

            // Load Fonts & Sprites
            var fontZenDots = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_ZEN_DOTS);
            var fontQuantico = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_QUANTICO_BOLD);
            var fontExo = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(FONT_EXO_SEMIBOLD);
            var sprGlow = AssetDatabase.LoadAssetAtPath<Sprite>(SPR_HOVER_GLOW);
            var iconStart = AssetDatabase.LoadAssetAtPath<Sprite>(ICON_START);
            var iconClinic = AssetDatabase.LoadAssetAtPath<Sprite>(ICON_CLINIC);
            var iconQuit = AssetDatabase.LoadAssetAtPath<Sprite>(ICON_QUIT);

            // Hide old template
            var oldSyntyScreen = canvasGo.transform.Find("Screen_SciFiMenus_Title");
            if (oldSyntyScreen != null) oldSyntyScreen.gameObject.SetActive(false);

            // Clean master panel
            Transform panelTrans = canvasGo.transform.Find("Panel_Cyberpunk_LeftMenu");
            GameObject panelGo;
            if (panelTrans == null)
            {
                panelGo = new GameObject("Panel_Cyberpunk_LeftMenu", typeof(RectTransform));
                panelGo.transform.SetParent(canvasGo.transform, false);
            }
            else
            {
                panelGo = panelTrans.gameObject;
            }

            for (int i = panelGo.transform.childCount - 1; i >= 0; i--)
            {
                Object.DestroyImmediate(panelGo.transform.GetChild(i).gameObject);
            }

            // Panel: Sleek, borderless vertical anchor on left
            var panelRt = panelGo.GetComponent<RectTransform>();
            panelRt.anchorMin = new Vector2(0f, 0f);
            panelRt.anchorMax = new Vector2(0f, 1f);
            panelRt.pivot = new Vector2(0f, 0.5f);
            panelRt.anchoredPosition = new Vector2(80f, 0f);
            panelRt.sizeDelta = new Vector2(460f, 0f);

            // Soft sheer glass backing (gradient from left to transparent)
            var panelImg = panelGo.GetComponent<Image>() ?? panelGo.AddComponent<Image>();
            panelImg.sprite = null;
            // Sheer dark obsidian scrim (40% opacity) with zero heavy borders
            panelImg.color = new Color(0.01f, 0.04f, 0.08f, 0.55f);
            panelImg.raycastTarget = false;

            // Sleek 1px cyan hairline on the left edge
            var leftHairlineGo = CreateChild(panelGo, "Hairline_Left");
            var leftHairlineRt = leftHairlineGo.GetComponent<RectTransform>();
            leftHairlineRt.anchorMin = new Vector2(0f, 0.12f);
            leftHairlineRt.anchorMax = new Vector2(0f, 0.88f);
            leftHairlineRt.pivot = new Vector2(0f, 0.5f);
            leftHairlineRt.anchoredPosition = Vector2.zero;
            leftHairlineRt.sizeDelta = new Vector2(2f, 0f);
            var leftHairlineImg = leftHairlineGo.AddComponent<Image>();
            leftHairlineImg.color = new Color(0f, 0.85f, 1f, 0.45f);

            // Inner Content
            var contentGo = CreateChild(panelGo, "Content_Container");
            var contentRt = contentGo.GetComponent<RectTransform>();
            contentRt.anchorMin = new Vector2(0f, 0.5f);
            contentRt.anchorMax = new Vector2(1f, 0.5f);
            contentRt.pivot = new Vector2(0.5f, 0.5f);
            contentRt.anchoredPosition = Vector2.zero;
            contentRt.sizeDelta = new Vector2(-40f, 620f); // Tightly fits all content!

            // ==========================================
            // HEADER
            // ==========================================
            var headerGo = CreateChild(contentGo, "Header");
            var headerRt = headerGo.GetComponent<RectTransform>();
            SetTopAnchored(headerRt, 0f, 0f, 150f);

            // Live Feed Tag
            var feedRow = CreateChild(headerGo, "Feed_Tag");
            var feedRowRt = feedRow.GetComponent<RectTransform>();
            SetTopAnchored(feedRowRt, 0f, 0f, 18f);

            var beaconGo = CreateChild(feedRow, "Beacon_Dot");
            var beaconRt = beaconGo.GetComponent<RectTransform>();
            beaconRt.anchorMin = new Vector2(0f, 0.5f);
            beaconRt.anchorMax = new Vector2(0f, 0.5f);
            beaconRt.pivot = new Vector2(0f, 0.5f);
            beaconRt.anchoredPosition = new Vector2(0f, 0f);
            beaconRt.sizeDelta = new Vector2(8f, 8f);
            var beaconImg = beaconGo.AddComponent<Image>();
            beaconImg.color = new Color(0f, 0.95f, 1f, 1f);

            var feedText = CreateChild(feedRow, "Text");
            var feedTextRt = feedText.GetComponent<RectTransform>();
            feedTextRt.anchorMin = new Vector2(0f, 0f);
            feedTextRt.anchorMax = new Vector2(1f, 1f);
            feedTextRt.offsetMin = new Vector2(14f, 0f);
            feedTextRt.offsetMax = Vector2.zero;
            var feedTmp = feedText.AddComponent<TextMeshProUGUI>();
            feedTmp.font = fontQuantico != null ? fontQuantico : feedTmp.font;
            feedTmp.fontSize = 11f;
            feedTmp.characterSpacing = 2.5f;
            feedTmp.text = "<color=#00F5FF>LIVE FEED</color> // SECTOR 04 SALVAGE BASIN";
            feedTmp.color = new Color(0.65f, 0.85f, 0.95f, 0.9f);

            // Title: ALITA
            var titleGo = CreateChild(headerGo, "Title_Alita");
            var titleRt = titleGo.GetComponent<RectTransform>();
            SetTopAnchored(titleRt, 0f, -22f, 64f);
            var titleTmp = titleGo.AddComponent<TextMeshProUGUI>();
            titleTmp.font = fontZenDots != null ? fontZenDots : titleTmp.font;
            titleTmp.fontSize = 54f;
            titleTmp.characterSpacing = 16f;
            titleTmp.text = "ALITA";
            titleTmp.color = Color.white;

            // Subtitle: BATTLE ANGEL
            var subGo = CreateChild(headerGo, "Subtitle_BattleAngel");
            var subRt = subGo.GetComponent<RectTransform>();
            SetTopAnchored(subRt, 0f, -86f, 26f);
            var subTmp = subGo.AddComponent<TextMeshProUGUI>();
            subTmp.font = fontQuantico != null ? fontQuantico : subTmp.font;
            subTmp.fontSize = 20f;
            subTmp.characterSpacing = 7f;
            subTmp.text = "B A T T L E   A N G E L";
            subTmp.color = new Color(0f, 0.95f, 1f, 1f);

            // 1px Hairline Divider
            var divGo = CreateChild(headerGo, "Divider");
            var divRt = divGo.GetComponent<RectTransform>();
            SetTopAnchored(divRt, 0f, -118f, 1.5f);
            var divImg = divGo.AddComponent<Image>();
            divImg.color = new Color(0f, 0.9f, 1f, 0.4f);

            // Chapter Label
            var chapGo = CreateChild(headerGo, "Chapter_Tag");
            var chapRt = chapGo.GetComponent<RectTransform>();
            SetTopAnchored(chapRt, 0f, -126f, 18f);
            var chapTmp = chapGo.AddComponent<TextMeshProUGUI>();
            chapTmp.font = fontExo != null ? fontExo : chapTmp.font;
            chapTmp.fontSize = 11f;
            chapTmp.characterSpacing = 3.5f;
            chapTmp.text = "PROLOGUE <color=#00E5FF>//</color> THE CYBORG DISCOVERY";
            chapTmp.color = new Color(0.55f, 0.75f, 0.88f, 0.8f);

            // ==========================================
            // BUTTON STACK (Sleek minimalist horizontal strips)
            // ==========================================
            var btnStackGo = CreateChild(contentGo, "Button_Stack");
            var btnStackRt = btnStackGo.GetComponent<RectTransform>();
            SetTopAnchored(btnStackRt, 0f, -180f, 320f);

            // Button 1: START DISCOVERY
            var btn1Go = CreateSleekButton(
                btnStackGo,
                "Btn_StartJourney",
                0f,
                72f,
                "01",
                "START DISCOVERY",
                "GOD OF WAR SINGLE-TAKE // SEAMLESS IMMERSION",
                iconStart,
                new Color(0f, 0.95f, 1f, 1f),
                fontQuantico,
                fontExo,
                sprGlow,
                out Image glow1
            );

            // Button 2: CLINIC AWAKENING
            var btn2Go = CreateSleekButton(
                btnStackGo,
                "Btn_ClinicAwakening",
                -88f,
                72f,
                "02",
                "CLINIC AWAKENING",
                "CHAPTER I // TRON: ARES RECONSTRUCTION",
                iconClinic,
                new Color(1f, 0.55f, 0.1f, 1f),
                fontQuantico,
                fontExo,
                sprGlow,
                out Image glow2
            );

            // Button 3: EXIT
            var btn3Go = CreateSleekButton(
                btnStackGo,
                "Btn_Quit",
                -176f,
                54f,
                "03",
                "EXIT SIMULATION",
                null,
                iconQuit,
                new Color(0.55f, 0.72f, 0.88f, 1f),
                fontQuantico,
                fontExo,
                sprGlow,
                out Image glow3
            );

            // ==========================================
            // FOOTER: Discrete Status & Keycap Prompt
            // ==========================================
            var footerGo = CreateChild(contentGo, "Footer");
            var footerRt = footerGo.GetComponent<RectTransform>();
            footerRt.anchorMin = new Vector2(0f, 0f);
            footerRt.anchorMax = new Vector2(1f, 0f);
            footerRt.pivot = new Vector2(0.5f, 0f);
            footerRt.anchoredPosition = new Vector2(0f, 0f);
            footerRt.sizeDelta = new Vector2(0f, 70f);

            // 1px Hairline top
            var footLine = CreateChild(footerGo, "Line");
            var footLineRt = footLine.GetComponent<RectTransform>();
            SetTopAnchored(footLineRt, 0f, 0f, 1.5f);
            var footLineImg = footLine.AddComponent<Image>();
            footLineImg.color = new Color(0f, 0.9f, 1f, 0.3f);

            // Waveform monitor (compact, sleek horizontal line)
            var ecgRawGo = CreateChild(footerGo, "RawImage_ECG");
            var ecgRawRt = ecgRawGo.GetComponent<RectTransform>();
            SetTopAnchored(ecgRawRt, 0f, -8f, 26f);
            var ecgRawImg = ecgRawGo.AddComponent<RawImage>();
