using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scene = EditorSceneManager.OpenScene("Assets/Scenes/Alita_Tron_Awakening.unity", OpenSceneMode.Single);
        result.Log("Opened scene: {0}", scene.name);

        var chamber = GameObject.Find("TRON_Red_Grid_Chamber");
        if (chamber == null)
        {
            result.LogError("TRON_Red_Grid_Chamber not found!");
            return;
        }

        PrintHierarchy(chamber.transform, "", result);
    }

    void PrintHierarchy(Transform t, string indent, ExecutionResult result)
    {
        result.Log("{0}{1}: pos={2}, rot={3}, scale={4}", indent, t.name, t.position, t.rotation.eulerAngles, t.localScale);
        for (int i = 0; i < t.childCount; i++)
        {
            PrintHierarchy(t.GetChild(i), indent + "  ", result);
        }
    }
}

