            result.Log("Director found: profileWideCam={0}, profileCam={1}, ceilingCam={2}, overShoulderCam={3}, orbitCam={4}",
                director.profileWideCam?.position,
                director.profileCam?.position,
                director.ceilingCam?.position,
                director.overShoulderCam?.position,
                director.orbitCam?.position);
