            result.LogError("Chamber_Grid_Enclosure not found");
            return;
        }

        // Room dimensions: Width 20m (X = ±10m), Length 24m (Z = ±12m), Height 5.5m (Y = 0 to 5.5m)
        float halfW = 10.0f;
        float halfL = 12.0f;
        float height = 5.5f;
        float halfH = height * 0.5f;

        var floorBase = enc.transform.Find("Floor_Obsidian_Base");
        if (floorBase != null) floorBase.localScale = new Vector3(2.5f, 1f, 2.5f);

        var floorGrid = enc.transform.Find("Floor_Red_Grid");
        if (floorGrid != null) floorGrid.localScale = new Vector3(2.5f, 1f, 2.5f);

        var ceiling = enc.transform.Find("Ceiling_Red_Grid");
        if (ceiling != null)
        {
            ceiling.position = new Vector3(0f, height, 0f);
            ceiling.localScale = new Vector3(2.5f, 1f, 2.5f);
        }

        var wallNorth = enc.transform.Find("Wall_North");
        if (wallNorth != null)
        {
            wallNorth.position = new Vector3(0f, halfH, halfL);
            wallNorth.localScale = new Vector3(12f, 1f, 12f);
        }

        var wallSouth = enc.transform.Find("Wall_South");
        if (wallSouth != null)
        {
            wallSouth.position = new Vector3(0f, halfH, -halfL);
            wallSouth.localScale = new Vector3(12f, 1f, 12f);
        }

        var wallEast = enc.transform.Find("Wall_East");
        if (wallEast != null)
        {
            wallEast.position = new Vector3(halfW, halfH, 0f);
            wallEast.localScale = new Vector3(12f, 1f, 12f);
        }

        var wallWest = enc.transform.Find("Wall_West");
        if (wallWest != null)
        {
            wallWest.position = new Vector3(-halfW, halfH, 0f);
            wallWest.localScale = new Vector3(12f, 1f, 12f);
        }

        var horizon = enc.transform.Find("Horizon_Laser_Beam");
        if (horizon != null)
        {
            horizon.position = new Vector3(-halfW + 0.05f, 0.65f, 0f);
            horizon.localScale = new Vector3(0.06f, 0.05f, halfL * 2f + 2f);
        }

        // Adjust Grid Material spacing for tighter, cleaner look
        var redGridMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/Tron/Mat_Tron_Red_Cube_Grid.mat");
        if (redGridMat != null)
        {
            redGridMat.SetFloat("_GridSpacing", 2.2f);
            redGridMat.SetFloat("_LineWidth", 0.012f);
            EditorUtility.SetDirty(redGridMat);
        }

        var floorGridMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/Tron/Mat_Tron_Floor_Red_Grid.mat");
        if (floorGridMat != null)
        {
            floorGridMat.SetFloat("_GridSpacing", 2.2f);
            floorGridMat.SetFloat("_LineWidth", 0.012f);
            EditorUtility.SetDirty(floorGridMat);
        }

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);

        // Render camera from wide profile position looking at slab
        var cam = GameObject.Find("Main Camera")?.GetComponent<Camera>();
        if (cam != null)
        {
            cam.transform.position = new Vector3(7.5f, 0.70f, 0.05f);
            cam.transform.LookAt(new Vector3(0f, 0.85f, 0.05f));
            cam.fieldOfView = 32f;

            int width = 1920;
            int heightPx = 1080;
            var rt = new RenderTexture(width, heightPx, 24, RenderTextureFormat.ARGB32);
            var prevTarget = cam.targetTexture;
            cam.targetTexture = rt;
            cam.Render();

            RenderTexture.active = rt;
            var tex = new Texture2D(width, heightPx, TextureFormat.RGB24, false);
            tex.ReadPixels(new Rect(0, 0, width, heightPx), 0, 0);
            tex.Apply();

            cam.targetTexture = prevTarget;
            RenderTexture.active = null;
            Object.DestroyImmediate(rt);

            byte[] png = tex.EncodeToPNG();
            Object.DestroyImmediate(tex);

            string outPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\tron_room_preview.png";
            File.WriteAllBytes(outPath, png);
            result.Log("Saved preview to {0}!", outPath);
        }

        result.Log("Grid room resized successfully!");
    }
}

