var scene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
if (scene.name != "Alita_Tron_Awakening")
{
    UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Alita_Tron_Awakening.unity");
}

