var orbital = GameObject.Find("TRON_Orbital_Master");
if (orbital != null) orbital.SetActive(false);

var pupilVFX = GameObject.Find("Tron_Eye_Pupil_Radial_Burst");
if (pupilVFX != null) pupilVFX.SetActive(false);

// 2. Adjust Grid Chamber Enclosure dimensions
var chamberGridRoot = GameObject.Find("Chamber_Grid_Enclosure");
if (chamberGridRoot != null)
{
    var floorBase = chamberGridRoot.transform.Find("Floor_Obsidian_Base");
    if (floorBase != null) floorBase.localScale = new Vector3(2.5f, 1f, 2.5f);

    var floorGrid = chamberGridRoot.transform.Find("Floor_Red_Grid");
    if (floorGrid != null) floorGrid.localScale = new Vector3(2.5f, 1f, 2.5f);

    var ceiling = chamberGridRoot.transform.Find("Ceiling_Red_Grid");
    if (ceiling != null)
    {
        ceiling.position = new Vector3(0f, 5.5f, 0f);
        ceiling.localScale = new Vector3(2.5f, 1f, 2.5f);
    }

    var wallN = chamberGridRoot.transform.Find("Wall_North");
    if (wallN != null) wallN.position = new Vector3(0f, 2.75f, 12f);

    var wallS = chamberGridRoot.transform.Find("Wall_South");
    if (wallS != null) wallS.position = new Vector3(0f, 2.75f, -12f);

    var wallE = chamberGridRoot.transform.Find("Wall_East");
    if (wallE != null) wallE.position = new Vector3(10f, 2.75f, 0f);

    var wallW = chamberGridRoot.transform.Find("Wall_West");
    if (wallW != null) wallW.position = new Vector3(-10f, 2.75f, 0f);

    var beam = chamberGridRoot.transform.Find("Horizon_Laser_Beam");
    if (beam != null)
    {
        beam.position = new Vector3(-9.95f, 0.65f, 0f);
        beam.localScale = new Vector3(0.06f, 0.05f, 26f);
    }
}

