using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scene = EditorSceneManager.GetActiveScene();
        result.Log("Active Scene: {0}", scene.name);

        // Find camera
        Camera cam = Camera.main;
        if (cam != null)
        {
            result.Log("Main Camera GameObject: {0}", cam.gameObject.name);
            var comps = cam.GetComponents<Component>();
            foreach (var c in comps)
            {
                if (c != null)
                {
                    result.Log("Camera Component: {0}", c.GetType().FullName);
                }
            }
        }

        // Find all objects with "filter" or "scanline" or "crt" or "hud" or "canvas"
        var allGOs = GameObject.FindObjectsOfType<GameObject>(true);
        foreach (var go in allGOs)
        {
            string n = go.name.ToLower();
            if (n.Contains("scanline") || n.Contains("filter") || n.Contains("crt") || n.Contains("overlay") || n.Contains("cyberpunkhud") || n.Contains("kiroshi"))
            {
                result.Log("Found Candidate GO: {0} (Active: {1})", go.name, go.activeInHierarchy);
            }
        }
    }
}

