using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scene = EditorSceneManager.GetActiveScene();
        if (scene.name != "Demo_City")
        {
            EditorSceneManager.OpenScene("Assets/PolygonCyberCity/Scenes/Demo_City.unity");
        }

        // 1. Inspect all Volumes in Demo_City
        var volumes = Object.FindObjectsOfType<Volume>(true);
        foreach (var v in volumes)
        {
            result.Log("Volume GO: {0}, Profile: {1}", v.gameObject.name, v.sharedProfile != null ? v.sharedProfile.name : "null");
            if (v.sharedProfile != null)
            {
                foreach (var comp in v.sharedProfile.components)
                {
                    result.Log("  - Volume Component: {0} (active: {1})", comp.name, comp.active);
                }
            }
        }

        // 2. Inspect URP Pipeline Asset / Render Features
        var urpAsset = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
        if (urpAsset != null)
        {
            result.Log("URP Asset: {0}", urpAsset.name);
        }

        // 3. Inspect Cameras
        var cams = Object.FindObjectsOfType<Camera>(true);
        foreach (var c in cams)
        {
            result.Log("Camera: {0} (tag: {1}, active: {2})", c.gameObject.name, c.tag, c.gameObject.activeInHierarchy);
            var comps = c.GetComponents<MonoBehaviour>();
            foreach (var mb in comps)
            {
                if (mb != null) result.Log("  - Camera Script: {0}", mb.GetType().FullName);
            }
        }
    }
}

