using UnityEngine;
using UnityEngine.Rendering.Universal;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var urpAsset = UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
        if (urpAsset != null)
        {
            var so = new SerializedObject(urpAsset);
            var renderersProp = so.FindProperty("m_RendererDataList");
            for (int i = 0; i < renderersProp.arraySize; i++)
            {
                var rData = renderersProp.GetArrayElementAtIndex(i).objectReferenceValue as ScriptableRendererData;
                if (rData != null)
                {
                    result.Log("Renderer Data [{0}]: {1}", i, rData.name);
                    foreach (var rf in rData.rendererFeatures)
                    {
                        if (rf != null)
                        {
                            result.Log("  - Render Feature: {0} ({1}) Active: {2}", rf.name, rf.GetType().FullName, rf.isActive);
                        }
                    }
                }
            }
        }
    }
}

