using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace SyntyCombined
{
    /// <summary>
    /// AAA Cyberpunk 2077 In-Game HUD (Authentic Clean UI).
    /// Faithfully recreated from CD PROJEKT RED's Cyberpunk 2077:
    /// 1. Clean Camera View: Zero scanlines, zero screen-obscuring filters, zero CRT noise.
    /// 2. Top-Left: Sleek level badge (55), ultra-thin crimson health bar, trailing ghost health,
    ///    numeric HP readout (e.g. 475), thin cyan stamina/RAM bar, and status buff icon.
    /// 3. Top-Right: Clean time of day (10:11 AM), minimalist minimap with thin subtle border,
    ///    and authentic mission tracker directly underneath ("UNDISCOVERED // [!] Who knows what you might find?").
    /// 4. Bottom-Left: Cyberpunk 2077 D-Pad widget (Phone [T], Vehicle [V], Scan [TAB]) and
    ///    compact quick item slots (MaxDoc [X] with count, Gadget [G] with count).
    /// 5. Bottom-Right: Floating contextual action prompts ("Draw Weapon [TAB]", "Crouch [C]")
    ///    with red posture stance silhouette.
    /// 6. Center: Minimalist unobtrusive crosshair dot.
    /// </summary>
    public class CyberpunkHUDController : MonoBehaviour
    {
        public static CyberpunkHUDController Instance { get; private set; }

        // ─── Cyberpunk Color Palette ─────────────────────────────────────────────
        public static readonly Color CyberYellow    = new Color(0.988f, 0.933f, 0.039f, 1.0f); // #FCEE0A (CDPR Signature Yellow)
        public static readonly Color NeonCrimson    = new Color(1.000f, 0.000f, 0.235f, 1.0f); // #FF003C (Health & High Alert)
        public static readonly Color CrimsonDim     = new Color(0.180f, 0.020f, 0.040f, 0.95f); // Health background
        public static readonly Color KiroshiCyan    = new Color(0.000f, 0.941f, 1.000f, 1.0f); // #00F0FF (Tech / RAM / Stamina)
        public static readonly Color CyanDim        = new Color(0.000f, 0.160f, 0.220f, 0.90f); // Empty RAM cell
        public static readonly Color StanceOrange   = new Color(1.000f, 0.518f, 0.000f, 1.0f); // #FF8400 (Iconic tier / stamina)
        public static readonly Color DarkObsidian   = new Color(0.020f, 0.028f, 0.045f, 0.88f); // Translucent deep obsidian
        public static readonly Color GlassTileBg    = new Color(0.040f, 0.060f, 0.090f, 0.78f); // Translucent glass tile
        public static readonly Color TextWhite      = new Color(0.960f, 0.980f, 1.000f, 1.0f);
        public static readonly Color TextMuted      = new Color(0.550f, 0.650f, 0.750f, 1.0f);

        [Header("Target Controller")]
        public SyntySwordLocomotionController playerController;
        private InsaneGun.Combat.InsaneGunSwordController _insaneHero;

        [Header("UI Resources Cache")]
        public TMP_FontAsset headerFont;
        public TMP_FontAsset boldFont;
        public TMP_FontAsset bodyFont;

        // Top-Left References
        private RectTransform _healthFillRect;
        private RectTransform _ghostHealthFillRect;
        private TextMeshProUGUI _healthText;
        private TextMeshProUGUI _levelBadgeText;
        private RectTransform _staminaFillRect;
        private float _currentStamina = 1.0f;
        private float _ghostHealthRatio = 1.0f;
        private GameObject _buffBadgeObj;

        // Top-Right References
        private TextMeshProUGUI _clockText;
        public RawImage minimapRawImage;
        public RectTransform playerIconRect;
        public Transform enemyBlipsContainer;
        private TextMeshProUGUI _questHeaderTitleText;
        private TextMeshProUGUI _questObjectiveText;

        // Bottom-Right References
        private TextMeshProUGUI _weaponNameText;
        private TextMeshProUGUI _weaponTierText;
        private TextMeshProUGUI _contextualActionDrawText;
        private TextMeshProUGUI _contextualActionCrouchText;
        private Image _crouchStanceIcon;

        // Bottom-Left References
        private TextMeshProUGUI _maxDocCountText;
        private TextMeshProUGUI _gadgetCountText;
        private int _maxDocCount = 5;
        private int _gadgetCount = 2;

        // Center Reticle References
        private RectTransform _reticleCenterDot;
        private RectTransform _reticleLeftBracket;
        private RectTransform _reticleRightBracket;

        // Screen Overlays
        private Image _lowHealthVignette;
        private GameObject _toastBannerObj;
        private TextMeshProUGUI _toastBannerText;
        private float _toastTimer = 0f;

        // World Telemetry Simulation
        private float _inGameMinutes = 611f; // 10:11 AM in minutes
        private Camera _mainCam;

        private void Awake()
        {
            Instance = this;
            LoadFonts();
        }

        private void Start()
        {
            FindPlayerReference();
            _mainCam = Camera.main;
            BuildCyberpunkHUD();
        }

        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
        }

        private void LoadFonts()
        {
            headerFont = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Header");
            boldFont   = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Bold");
            bodyFont   = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Body");
        }

        private void FindPlayerReference()
        {
            if (playerController == null)
            {
                playerController = Object.FindAnyObjectByType<SyntySwordLocomotionController>();
            }
            if (_insaneHero == null)
            {
                var heroes = Object.FindObjectsByType<InsaneGun.Combat.InsaneGunSwordController>();
                foreach (var h in heroes)
                {
                    if (h.controlMode == InsaneGun.Combat.InsaneGunSwordController.ControlMode.PlayerControlled || h.CompareTag("Player"))
                    {
                        _insaneHero = h;
                        break;
                    }
                }
            }
        }

        public void SetQuestObjective(string gigTitle, string objectiveText)
        {
            if (_questHeaderTitleText != null && !string.IsNullOrEmpty(gigTitle))
            {
                _questHeaderTitleText.text = gigTitle.ToUpper();
            }
            if (_questObjectiveText != null && !string.IsNullOrEmpty(objectiveText))
            {
                _questObjectiveText.text = objectiveText;
            }
        }

        // ─────────────────────────────────────────────────────────────────────────
        // BUILD CYBERPUNK 2077 HUD CANVAS (CLEAN, DIEGETIC, AUTHENTIC)
        // ─────────────────────────────────────────────────────────────────────────
        public void BuildCyberpunkHUD()
        {
            // Clean up any existing children from this canvas
            for (int i = transform.childCount - 1; i >= 0; i--)
            {
                Destroy(transform.GetChild(i).gameObject);
            }

            BuildTopLeftBioMonitor();
            BuildTopRightTelemetryAndMinimap();
            BuildBottomLeftQuickItemsAndDPad();
            BuildBottomRightContextualPrompts();
            BuildCenterMinimalReticle();
            BuildCinematicOverlays();
        }

        // ─── 1. TOP-LEFT: CYBERPUNK 2077 BIO-MONITOR ─────────────────────────────
        private void BuildTopLeftBioMonitor()
        {
            // Anchored neatly at top-left
            GameObject root = CreateAnchorPanel("Zone_TopLeft_BioMonitor",
                new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f),
                new Vector2(36f, -32f), new Vector2(380f, 60f));

            // A. Compact Level Badge [55]
            GameObject lvlBox = CreateChild(root, "Badge_Level", new Vector2(0f, -4f), new Vector2(28f, 26f));
            SetAnchorLeft(lvlBox, 0f);
            Image lvlBg = lvlBox.AddComponent<Image>();
            lvlBg.color = new Color(0.12f, 0.02f, 0.04f, 0.95f);
            AddBorder(lvlBox, new Color(1f, 0.15f, 0.25f, 0.8f), 1f);

            _levelBadgeText = CreateText(lvlBox, "Text_Lvl", "55", 13f, TextAlignmentOptions.Center, Vector2.zero, TextWhite, boldFont);
            _levelBadgeText.fontStyle = FontStyles.Bold;

            // B. Thin Sleek Cyberpunk Health Bar (Width 240, Height 9)
            GameObject hpContainer = CreateChild(root, "Container_Health", new Vector2(34f, -4f), new Vector2(240f, 9f));
            SetAnchorLeft(hpContainer, 34f);
            Image hpBg = hpContainer.AddComponent<Image>();
            hpBg.color = CrimsonDim;
            AddBorder(hpContainer, new Color(0.4f, 0.05f, 0.08f, 0.8f), 1f);

            // Ghost Health Lag Bar
            GameObject ghostHpBar = CreateChild(hpContainer, "Bar_GhostHealth", Vector2.zero, new Vector2(240f, 9f));
            SetFullStretch(ghostHpBar);
            Image ghostImg = ghostHpBar.AddComponent<Image>();
            ghostImg.color = new Color(1f, 0.55f, 0.65f, 0.75f);
            _ghostHealthFillRect = ghostHpBar.GetComponent<RectTransform>();

            // Active Health Fill Bar (Cyberpunk Neon Crimson)
            GameObject hpBar = CreateChild(hpContainer, "Bar_ActiveHealth", Vector2.zero, new Vector2(240f, 9f));
            SetFullStretch(hpBar);
            Image hpImg = hpBar.AddComponent<Image>();
            hpImg.color = NeonCrimson;
            _healthFillRect = hpBar.GetComponent<RectTransform>();

            // C. Numeric Health Value Beside Bar ("475")
            GameObject hpTextObj = CreateChild(root, "Text_HealthValue", new Vector2(282f, -3f), new Vector2(80f, 26f));
            SetAnchorLeft(hpTextObj, 282f);
            _healthText = CreateText(hpTextObj, "Text_HP", "475", 17f, TextAlignmentOptions.Left, Vector2.zero, new Color(1f, 0.82f, 0.85f, 1f), boldFont);
            _healthText.fontStyle = FontStyles.Bold;

            // D. Ultra-Thin Cyan Stamina / Cyberware Line Under Health Bar (Height 3)
            GameObject stamContainer = CreateChild(root, "Container_Stamina", new Vector2(34f, -17f), new Vector2(240f, 3f));
            SetAnchorLeft(stamContainer, 34f);
