using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using SyntyCombined;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var scene = EditorSceneManager.GetActiveScene();
        if (scene.name != "Demo_City")
        {
            EditorSceneManager.OpenScene("Assets/PolygonCyberCity/Scenes/Demo_City.unity");
        }

        GameObject hudCanvasObj = GameObject.Find("Canvas_InGameHUD");
        if (hudCanvasObj != null)
        {
            var hudCtrl = hudCanvasObj.GetComponent<CyberpunkHUDController>();
            if (hudCtrl != null)
            {
                hudCtrl.BuildCyberpunkHUD();
                hudCtrl.SetQuestObjective("UNDISCOVERED", "Who knows what you might find?");
            }

            Camera cam = Camera.main;
            if (cam != null)
            {
                var rt = new RenderTexture(1920, 1080, 24, RenderTextureFormat.ARGB32);
                var prevTarget = cam.targetTexture;
                cam.targetTexture = rt;

                Canvas c = hudCanvasObj.GetComponent<Canvas>();
                var prevMode = c.renderMode;
                c.renderMode = RenderMode.ScreenSpaceCamera;
                c.worldCamera = cam;
                c.planeDistance = 1.0f;

                cam.Render();

                RenderTexture.active = rt;
                var tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
                tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
                tex.Apply();

                c.renderMode = prevMode;
                c.worldCamera = null;
                cam.targetTexture = prevTarget;
                RenderTexture.active = null;

                byte[] bytes = tex.EncodeToPNG();
                string outPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\cyberpunk_hud_preview.png";
                System.IO.File.WriteAllBytes(outPath, bytes);

                Object.DestroyImmediate(rt);
                Object.DestroyImmediate(tex);

                result.Log("PREVIEW_RENDER_SUCCESSFUL_ZERO_WARNINGS");
            }
        }
    }
}

