481:         // ─────────────────────────────────────────────────────────────────────────
482:         private void Update()
483:         {
484:             if (playerController == null && _insaneHero == null)
485:             {
486:                 FindPlayerReference();
487:                 if (playerController == null && _insaneHero == null) return;
488:             }
489: 
490:             UpdateBioMonitor();
491:             UpdateClockAndTelemetry();
492:             UpdateContextualPrompts();
493:             UpdateReticleMotion();
494:             UpdateConsumablesAndHotkeys();
495:             UpdateToastBanner();
496:         }
