498:         private void UpdateBioMonitor()
499:         {
500:             float maxHp = playerController != null ? playerController.maxHealth : (_insaneHero != null ? _insaneHero.maxHealth : 250f);
501:             float curHp = playerController != null ? playerController.currentHealth : (_insaneHero != null ? _insaneHero.currentHealth : 250f);
502:             maxHp = Mathf.Max(maxHp, 1f);
503:             curHp = Mathf.Clamp(curHp, 0f, maxHp);
504:             float hpRatio = curHp / maxHp;
505: 
506:             // Smooth active health fill
507:             if (_healthFillRect != null)
508:             {
509:                 _healthFillRect.anchorMax = new Vector2(hpRatio, 1f);
510:             }
511: 
512:             // Smooth ghost health trailing
513:             if (_ghostHealthFillRect != null)
514:             {
515:                 _ghostHealthRatio = Mathf.MoveTowards(_ghostHealthRatio, hpRatio, Time.deltaTime * 0.40f);
516:                 _ghostHealthFillRect.anchorMax = new Vector2(_ghostHealthRatio, 1f);
517:             }
518: 
519:             // Numeric HP text (Cyberpunk 2077 clean number format)
520:             if (_healthText != null)
521:             {
522:                 _healthText.text = $"{curHp:F0}";
523:             }
524: 
525:             // Stamina simulation (drains during sprint, restores when walking/idle)
526:             bool isSprint = playerController != null ? (playerController.IsSprintingState && playerController.CurrentMoveSpeed > 0.5f) : (Input.GetKey(KeyCode.LeftShift));
527:             if (isSprint)
528:             {
529:                 _currentStamina = Mathf.Clamp01(_currentStamina - Time.deltaTime * 0.25f);
530:             }
531:             else
532:             {
533:                 _currentStamina = Mathf.Clamp01(_currentStamina + Time.deltaTime * 0.35f);
534:             }
535: 
536:             if (_staminaFillRect != null)
537:             {
538:                 _staminaFillRect.anchorMax = new Vector2(_currentStamina, 1f);
539:             }
540: 
541:             // Low health vignette (< 25% HP)
542:             if (_lowHealthVignette != null)
543:             {
544:                 if (hpRatio < 0.25f)
545:                 {
546:                     float pulse = (Mathf.Sin(Time.time * 6f) + 1f) * 0.5f;
547:                     _lowHealthVignette.color = new Color(1f, 0f, 0.15f, 0.12f + pulse * 0.20f);
548:                 }
549:                 else
550:                 {
551:                     _lowHealthVignette.color = Color.clear;
552:                 }
553:             }
554:         }
555: 
556:         private void UpdateClockAndTelemetry()
557:         {
558:             // Advance in-game clock (1 real sec = 2.5 in-game mins)
559:             _inGameMinutes += Time.deltaTime * 2.5f;
560:             if (_inGameMinutes >= 1440f) _inGameMinutes -= 1440f;
561:             int hours = Mathf.FloorToInt(_inGameMinutes / 60f);
562:             int mins = Mathf.FloorToInt(_inGameMinutes % 60f);
563:             string ampm = hours >= 12 ? "PM" : "AM";
564:             int displayHours = hours % 12;
565:             if (displayHours == 0) displayHours = 12;
566: 
567:             if (_clockText != null)
568:             {
569:                 _clockText.text = $"{displayHours:D2}:{mins:D2} {ampm}";
570:             }
571:         }
572: 
573:         private void UpdateContextualPrompts()
574:         {
575:             bool drawn = playerController != null ? playerController.IsSwordDrawn : true;
576: 
577:             if (_contextualActionDrawText != null)
578:             {
579:                 _contextualActionDrawText.text = drawn
580:                     ? "Sheathe Weapon  <color=#00F0FF><b>[TAB]</b></color>"
581:                     : "Draw Weapon  <color=#00F0FF><b>[TAB]</b></color>";
582:             }
583: 
584:             if (_weaponNameText != null)
585:             {
586:                 _weaponNameText.gameObject.SetActive(drawn);
587:             }
588:         }
