590:         private void UpdateReticleMotion()
591:         {
592:             float speedRatio = playerController != null
593:                 ? Mathf.Clamp01(playerController.CurrentMoveSpeed / 6f)
594:                 : (_insaneHero != null && _insaneHero.GetComponent<CharacterController>() != null
595:                     ? Mathf.Clamp01(_insaneHero.GetComponent<CharacterController>().velocity.magnitude / 6f)
596:                     : 0f);
597: 
598:             float bracketOffset = 12f + speedRatio * 8f;
599:             if (_reticleLeftBracket != null) _reticleLeftBracket.anchoredPosition = new Vector2(-bracketOffset, 0f);
600:             if (_reticleRightBracket != null) _reticleRightBracket.anchoredPosition = new Vector2(bracketOffset, 0f);
601:         }
