603:         private void UpdateConsumablesAndHotkeys()
604:         {
605:             var kb = UnityEngine.InputSystem.Keyboard.current;
606:             if (kb == null) return;
607: 
608:             // X Key: Consume MaxDoc Mk.3 Hypo
609:             if (kb.xKey.wasPressedThisFrame)
610:             {
611:                 if (_maxDocCount > 0)
612:                 {
613:                     _maxDocCount--;
614:                     float healAmount = 50f;
615:                     if (playerController != null)
616:                         playerController.currentHealth = Mathf.Min(playerController.currentHealth + healAmount, playerController.maxHealth);
617:                     else if (_insaneHero != null)
618:                         _insaneHero.currentHealth = Mathf.Min(_insaneHero.currentHealth + healAmount, _insaneHero.maxHealth);
619: 
620:                     if (_maxDocCountText != null) _maxDocCountText.text = $"{_maxDocCount}";
621:                     ShowToast($"MAXDOC INJECTED // +{healAmount:F0} HP", 2.0f);
622:                 }
623:             }
624: 
625:             // G Key: Deploy Gadget
626:             if (kb.gKey.wasPressedThisFrame)
627:             {
628:                 if (_gadgetCount > 0)
629:                 {
630:                     _gadgetCount--;
631:                     if (_gadgetCountText != null) _gadgetCountText.text = $"{_gadgetCount}";
632:                     ShowToast("THERMAL GADGET DEPLOYED", 2.0f);
633:                 }
634:             }
635: 
636:             // V Key: Summon Hover Taxi / Autonomous Vehicle
637:             if (kb.vKey.wasPressedThisFrame)
638:             {
639:                 ShowToast("CALLING VEHICLE // AUTONOMOUS HOVER TAXI DISPATCHED", 2.5f);
640:             }
641:         }
