322:         private static Button CreateButton(GameObject parent, GameObject prefab, string name, string labelText, Vector2 pos, Vector2 size)
323:         {
324:             GameObject btnObj = null;
325:             if (prefab != null)
326:             {
327:                 btnObj = Object.Instantiate(prefab, parent.transform);
328:                 btnObj.name = name;
329: 
330:                 // Remove duplicate template text children from instantiated prefab
331:                 TMP_Text[] existingTmps = btnObj.GetComponentsInChildren<TMP_Text>(true);
332:                 for (int i = 1; i < existingTmps.Length; i++)
333:                 {
334:                     Object.DestroyImmediate(existingTmps[i].gameObject);
335:                 }
336:             }
337:             else
338:             {
339:                 btnObj = new GameObject(name);
340:                 btnObj.transform.SetParent(parent.transform, false);
341:                 Image img = btnObj.AddComponent<Image>();
342:                 img.color = new Color(0.08f, 0.25f, 0.40f, 0.9f);
343:                 btnObj.AddComponent<Button>();
344:             }
345: 
346:             RectTransform rect = btnObj.GetComponent<RectTransform>();
347:             if (rect != null)
348:             {
349:                 rect.anchoredPosition = pos;
350:                 rect.sizeDelta = size;
351:             }
352: 
353:             Button button = btnObj.GetComponent<Button>();
354:             if (button == null) button = btnObj.AddComponent<Button>();
355: 
356:             TMP_Text tmp = btnObj.GetComponentInChildren<TMP_Text>(true);
357:             if (tmp == null)
358:             {
359:                 GameObject textObj = new GameObject("Text_Label");
360:                 textObj.transform.SetParent(btnObj.transform, false);
361:                 RectTransform textRect = textObj.AddComponent<RectTransform>();
362:                 textRect.anchorMin = Vector2.zero;
363:                 textRect.anchorMax = Vector2.one;
364:                 textRect.offsetMin = Vector2.zero;
365:                 textRect.offsetMax = Vector2.zero;
366:                 tmp = textObj.AddComponent<TextMeshProUGUI>();
367:             }
368: 
369:             tmp.text = labelText;
370:             tmp.enableAutoSizing = true;
371:             tmp.fontSizeMin = 14;
372:             tmp.fontSizeMax = 24;
373:             tmp.textWrappingMode = TextWrappingModes.NoWrap;
374:             tmp.overflowMode = TextOverflowModes.Overflow;
375:             tmp.alignment = TextAlignmentOptions.Center;
376:             tmp.color = Color.white;
377:             tmp.fontStyle = FontStyles.Bold;
378: 
379:             return button;
380:         }
