using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace SyntyCombined
{
    /// <summary>
    /// AAA Cyberpunk 2077 In-Game HUD (Pixel-Authentic Diegetic UI).
    /// Faithfully recreated from CD PROJEKT RED's Cyberpunk 2077:
    /// 1. Clean Camera View: Zero scanlines, zero screen-obscuring filters, zero CRT noise.
    /// 2. Top-Left Bio-Monitor:
    ///    - Dark trapezoid Level badge [55] with vertical red tab.
    ///    - Ultra-thin crimson health bar (#FF003C) with ghost health trailing lag.
    ///    - Bold numeric HP readout ("475") directly beside the bar.
    ///    - Segmented 10-pip Cyberdeck RAM row (#00F0FF) underneath the health bar.
    ///    - Status buff badge with droplet icon and live countdown timer ("04:11").
    /// 3. Top-Right Minimap & Quest Tracker:
    ///    - Time of day ("10:11 AM") in crisp cyan/white font above minimap.
    ///    - Clean square minimap (190x190) with subtle cyan border and dark blueprint radar.
    ///    - Borderless floating quest tracker: "UNDISCOVERED" header + yellow [!] badge + "Who knows what you might find?".
    /// 4. Bottom-Left D-Pad & Equipment Cards:
    ///    - Authentic 4-way D-Pad widget with crisp Phone [T], Vehicle [V], and Cyberware [TAB] icons.
    ///    - Royal blue "9+" notification badge on top corner.
    ///    - Dual quick equipment cards: MaxDoc Inhaler [X] with count (3) and Thermal Gadget [G] with count (2).
    /// 5. Bottom-Right Contextual Action Prompts:
    ///    - Floating right-aligned prompts: "Draw Weapon [TAB]", "Crouch [C]".
    ///    - Standing posture humanoid silhouette in neon crimson (#FF003C).
    /// 6. Center: Minimalist 3px cyan reticle dot with expanding motion brackets.
    /// </summary>
    public class CyberpunkHUDController : MonoBehaviour
    {
        public static CyberpunkHUDController Instance { get; private set; }

        // ─── Cyberpunk 2077 Color Palette ─────────────────────────────────────────
        public static readonly Color CyberYellow    = new Color(0.988f, 0.933f, 0.039f, 1.0f); // #FCEE0A (CDPR Signature Yellow)
        public static readonly Color NeonCrimson    = new Color(1.000f, 0.000f, 0.235f, 1.0f); // #FF003C (Health & High Alert)
        public static readonly Color CrimsonDim     = new Color(0.160f, 0.020f, 0.040f, 0.95f); // Health background
        public static readonly Color KiroshiCyan    = new Color(0.000f, 0.941f, 1.000f, 1.0f); // #00F0FF (Cyberdeck / Tech / RAM)
        public static readonly Color CyanDim        = new Color(0.000f, 0.160f, 0.220f, 0.85f); // Depleted RAM cell
        public static readonly Color NotifBlue      = new Color(0.000f, 0.520f, 1.000f, 1.0f); // #0084FF (9+ badge)
        public static readonly Color DarkObsidian   = new Color(0.030f, 0.040f, 0.060f, 0.92f); // UI Backing
        public static readonly Color GlassTileBg    = new Color(0.040f, 0.065f, 0.100f, 0.85f); // Translucent glass tile
        public static readonly Color TextWhite      = new Color(0.960f, 0.980f, 1.000f, 1.0f);
        public static readonly Color TextMuted      = new Color(0.550f, 0.650f, 0.750f, 1.0f);

        [Header("Target Controller")]
        public SyntySwordLocomotionController playerController;
        private InsaneGun.Combat.InsaneGunSwordController _insaneHero;

        [Header("UI Resources Cache")]
        public TMP_FontAsset headerFont;
        public TMP_FontAsset boldFont;
        public TMP_FontAsset bodyFont;

        // Top-Left References
        private RectTransform _healthFillRect;
        private RectTransform _ghostHealthFillRect;
        private TextMeshProUGUI _healthText;
        private TextMeshProUGUI _levelBadgeText;
        private Image[] _ramCells = new Image[10];
        private float _ghostHealthRatio = 1.0f;
        private TextMeshProUGUI _buffTimerText;

        // Top-Right References
        private TextMeshProUGUI _clockText;
        public RawImage minimapRawImage;
        public RectTransform playerIconRect;
        public Transform enemyBlipsContainer;
        private TextMeshProUGUI _questHeaderTitleText;
        private TextMeshProUGUI _questObjectiveText;

        // Bottom-Right References
        private TextMeshProUGUI _weaponNameText;
        private TextMeshProUGUI _contextualActionDrawText;
        private TextMeshProUGUI _contextualActionCrouchText;
        private Image _crouchStanceIcon;

        // Bottom-Left References
        private TextMeshProUGUI _maxDocCountText;
        private TextMeshProUGUI _gadgetCountText;
        private int _maxDocCount = 3;
        private int _gadgetCount = 2;

        // Center Reticle References
        private RectTransform _reticleCenterDot;
        private RectTransform _reticleLeftBracket;
        private RectTransform _reticleRightBracket;

        // Screen Overlays
        private Image _lowHealthVignette;
        private GameObject _toastBannerObj;
        private TextMeshProUGUI _toastBannerText;
        private float _toastTimer = 0f;

        // World Simulation
        private float _inGameMinutes = 611f; // 10:11 AM
        private float _buffCountdownSeconds = 251f; // 04:11
        private Camera _mainCam;

        // Procedural Icon Cache
        private static Sprite s_phoneSprite;
        private static Sprite s_carSprite;
        private static Sprite s_cyberwareSprite;
        private static Sprite s_inhalerSprite;
        private static Sprite s_grenadeSprite;
        private static Sprite s_humanoidSprite;
        private static Sprite s_dropletSprite;
        private static Texture2D s_minimapRadarTexture;

        private void Awake()
        {
            Instance = this;
            LoadFonts();
            EnsureProceduralSprites();
        }

        private void Start()
        {
            FindPlayerReference();
            _mainCam = Camera.main;
            BuildCyberpunkHUD();
        }

        private void OnDestroy()
        {
            if (Instance == this) Instance = null;
        }

        private void LoadFonts()
        {
            headerFont = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Header");
            boldFont   = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Bold");
            bodyFont   = Resources.Load<TMP_FontAsset>("SyntyUI/Fonts/Font_SciFi_Body");
        }

        private void FindPlayerReference()
        {
            if (playerController == null)
            {
                playerController = Object.FindAnyObjectByType<SyntySwordLocomotionController>();
            }
            if (_insaneHero == null)
            {
                var heroes = Object.FindObjectsByType<InsaneGun.Combat.InsaneGunSwordController>();
                foreach (var h in heroes)
                {
                    if (h.controlMode == InsaneGun.Combat.InsaneGunSwordController.ControlMode.PlayerControlled || h.CompareTag("Player"))
                    {
                        _insaneHero = h;
                        break;
                    }
                }
            }
        }

        public void SetQuestObjective(string gigTitle, string objectiveText)
        {
            if (_questHeaderTitleText != null && !string.IsNullOrEmpty(gigTitle))
            {
                _questHeaderTitleText.text = gigTitle.ToUpper();
            }
            if (_questObjectiveText != null && !string.IsNullOrEmpty(objectiveText))
            {
                _questObjectiveText.text = objectiveText;
            }
        }

        // ─────────────────────────────────────────────────────────────────────────
        // BUILD CYBERPUNK 2077 HUD CANVAS (CLEAN, DIEGETIC, AUTHENTIC)
        // ─────────────────────────────────────────────────────────────────────────
        public void BuildCyberpunkHUD()
        {
            EnsureProceduralSprites();

            // Clean up any existing children from this canvas
            for (int i = transform.childCount - 1; i >= 0; i--)
            {
                if (Application.isPlaying)
                    Destroy(transform.GetChild(i).gameObject);
                else
                    DestroyImmediate(transform.GetChild(i).gameObject);
            }

            BuildTopLeftBioMonitor();
            BuildTopRightTelemetryAndMinimap();
            BuildBottomLeftQuickItemsAndDPad();
            BuildBottomRightContextualPrompts();
            BuildCenterMinimalReticle();
            BuildCinematicOverlays();
        }

        // ─── 1. TOP-LEFT: AUTHENTIC CYBERPUNK 2077 BIO-MONITOR ───────────────────
        private void BuildTopLeftBioMonitor()
        {
            // Anchored neatly at top-left
            GameObject root = CreateAnchorPanel("Zone_TopLeft_BioMonitor",
                new Vector2(0f, 1f), new Vector2(0f, 1f), new Vector2(0f, 1f),
                new Vector2(40f, -36f), new Vector2(440f, 70f));

            // A. Dark Level Badge [55] with Red Vertical Accent
            GameObject lvlBox = CreateChild(root, "Badge_Level", new Vector2(0f, 0f), new Vector2(30f, 22f));
            SetAnchorLeft(lvlBox, 0f);
            Image lvlBg = lvlBox.AddComponent<Image>();
            lvlBg.color = DarkObsidian;
            AddBorder(lvlBox, new Color(0f, 0.941f, 1f, 0.5f), 1f);

            _levelBadgeText = CreateText(lvlBox, "Text_Lvl", "55", 13f, TextAlignmentOptions.Center, Vector2.zero, TextWhite, boldFont);
            _levelBadgeText.fontStyle = FontStyles.Bold;

            // Red vertical tab separator
            GameObject redTab = CreateChild(root, "Tab_RedSeparator", new Vector2(33f, 0f), new Vector2(3f, 20f));
            SetAnchorLeft(redTab, 33f);
            redTab.AddComponent<Image>().color = NeonCrimson;

            // B. Thin Sleek Cyberpunk Health Bar (Width 240, Height 7)
            GameObject hpContainer = CreateChild(root, "Container_Health", new Vector2(42f, 4f), new Vector2(240f, 7f));
            SetAnchorLeft(hpContainer, 42f);
            Image hpBg = hpContainer.AddComponent<Image>();
            hpBg.color = CrimsonDim;

            // Ghost Health Lag Bar
            GameObject ghostHpBar = CreateChild(hpContainer, "Bar_GhostHealth", Vector2.zero, new Vector2(240f, 7f));
            SetFullStretch(ghostHpBar);
            Image ghostImg = ghostHpBar.AddComponent<Image>();
            ghostImg.color = new Color(1f, 0.45f, 0.55f, 0.65f);
            _ghostHealthFillRect = ghostHpBar.GetComponent<RectTransform>();

            // Active Health Fill Bar (Cyberpunk Neon Crimson #FF003C)
            GameObject hpBar = CreateChild(hpContainer, "Bar_ActiveHealth", Vector2.zero, new Vector2(240f, 7f));
            SetFullStretch(hpBar);
            Image hpImg = hpBar.AddComponent<Image>();
            hpImg.color = NeonCrimson;
            _healthFillRect = hpBar.GetComponent<RectTransform>();

            // C. Numeric Health Value Beside Bar ("475" in crisp white-pink)
            GameObject hpTextObj = CreateChild(root, "Text_HealthValue", new Vector2(290f, 4f), new Vector2(65f, 24f));
            SetAnchorLeft(hpTextObj, 290f);
            _healthText = CreateText(hpTextObj, "Text_HP", "475", 19f, TextAlignmentOptions.Left, Vector2.zero, new Color(1f, 0.92f, 0.94f, 1f), boldFont);
            _healthText.fontStyle = FontStyles.Bold;

            // D. Segmented Cyberdeck RAM Pips (10 Distinct Cyan Cells)
            GameObject ramRow = CreateChild(root, "Row_CyberdeckRAM", new Vector2(42f, -8f), new Vector2(240f, 6f));
            SetAnchorLeft(ramRow, 42f);

            HorizontalLayoutGroup ramLayout = ramRow.AddComponent<HorizontalLayoutGroup>();
            ramLayout.childForceExpandWidth = false;
            ramLayout.childForceExpandHeight = false;
            ramLayout.spacing = 3f;
            ramLayout.childAlignment = TextAnchor.MiddleLeft;

            _ramCells = new Image[10];
            for (int i = 0; i < 10; i++)
            {
                GameObject pipObj = CreateChild(ramRow, $"RAM_Pip_{i}", Vector2.zero, new Vector2(13f, 5f));
                LayoutElement le = pipObj.AddComponent<LayoutElement>();
                le.preferredWidth = 13f;
                le.preferredHeight = 5f;

                Image pipImg = pipObj.AddComponent<Image>();
                pipImg.color = KiroshiCyan;
                _ramCells[i] = pipImg;
            }

            // E. Status Buff Badge with Cyan Water Droplet & Live Timer ("04:11")
            GameObject buffRoot = CreateChild(root, "Badge_StatusBuff", new Vector2(360f, 2f), new Vector2(24f, 24f));
            SetAnchorLeft(buffRoot, 360f);

            Image buffBg = buffRoot.AddComponent<Image>();
            buffBg.color = GlassTileBg;
            AddBorder(buffRoot, new Color(0f, 0.941f, 1f, 0.45f), 1f);

            // Droplet icon
            GameObject dropObj = CreateChild(buffRoot, "Icon_Droplet", Vector2.zero, new Vector2(16f, 16f));
            Image dropImg = dropObj.AddComponent<Image>();
            dropImg.sprite = s_dropletSprite;
            dropImg.color = KiroshiCyan;

            // Countdown timer above badge ("04:11")
            GameObject timerObj = CreateChild(buffRoot, "Text_BuffTimer", new Vector2(0f, 17f), new Vector2(44f, 14f));
            _buffTimerText = CreateText(timerObj, "Txt_Timer", "04:11", 9f, TextAlignmentOptions.Center, Vector2.zero, KiroshiCyan, boldFont);
            _buffTimerText.fontStyle = FontStyles.Bold;
        }

        // ─── 2. TOP-RIGHT: MINIMALIST MINIMAP & YELLOW QUEST TRACKER ─────────────
        private void BuildTopRightTelemetryAndMinimap()
        {
            GameObject root = CreateAnchorPanel("Zone_TopRight_MinimapArea",
                new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f),
                new Vector2(-40f, -36f), new Vector2(210f, 360f));

            // A. Clean Clock Above Minimap ("10:11 AM")
            GameObject clockObj = CreateChild(root, "Text_ClockHeader", new Vector2(0f, 0f), new Vector2(200f, 18f));
            SetAnchorTop(clockObj, 0f);
            _clockText = CreateText(clockObj, "Txt_Time", "10:11 AM", 11.5f, TextAlignmentOptions.Left, Vector2.zero, new Color(0f, 0.941f, 1f, 0.9f), boldFont);
            _clockText.fontStyle = FontStyles.Bold;

            // B. Clean Square Minimap with Subtle Border (190x190)
            GameObject minimapFrame = CreateChild(root, "Frame_Minimap", new Vector2(0f, -22f), new Vector2(190f, 190f));
            SetAnchorTop(minimapFrame, -22f);
            Image frameBg = minimapFrame.AddComponent<Image>();
            frameBg.color = DarkObsidian;
            AddBorder(minimapFrame, new Color(0f, 0.941f, 1f, 0.35f), 1f);

            // RawImage for orthographic minimap RenderTexture (with procedural cyber radar fallback)
            GameObject rawImgObj = CreateChild(minimapFrame, "RawImage_Minimap", Vector2.zero, new Vector2(186f, 186f));
            minimapRawImage = rawImgObj.AddComponent<RawImage>();
            minimapRawImage.texture = s_minimapRadarTexture;
            minimapRawImage.color = Color.white;

            // Player Blip Icon (Cyan View Cone)
            GameObject playerIconObj = CreateChild(rawImgObj, "Icon_Player", Vector2.zero, new Vector2(16f, 16f));
            Image pBlipImg = playerIconObj.AddComponent<Image>();
            pBlipImg.color = KiroshiCyan;
            Sprite coneSprite = Resources.Load<Sprite>("SyntyUI/Sprites/HUD/SPR_HUD_SciFi_Map_PlayerViewCone");
            if (coneSprite != null) { pBlipImg.sprite = coneSprite; }
            playerIconRect = playerIconObj.GetComponent<RectTransform>();

            // Container for dynamic enemy blips
            GameObject enemyBlips = CreateChild(rawImgObj, "Container_EnemyBlips", Vector2.zero, new Vector2(186f, 186f));
            enemyBlipsContainer = enemyBlips.transform;

            // North Compass Marker (Minimal Yellow "N")
            GameObject northObj = CreateChild(minimapFrame, "Marker_North", new Vector2(0f, 84f), new Vector2(20f, 14f));
            TextMeshProUGUI nTxt = CreateText(northObj, "Txt_N", "N", 10.5f, TextAlignmentOptions.Center, Vector2.zero, CyberYellow, boldFont);
            nTxt.fontStyle = FontStyles.Bold;

            // Link with MinimapController if present
            MinimapController minimapCtrl = GetComponent<MinimapController>() ?? Object.FindAnyObjectByType<MinimapController>();
            if (minimapCtrl != null)
            {
                minimapCtrl.SetMinimapTarget(minimapRawImage, playerIconRect, enemyBlipsContainer);
            }

            // C. Borderless Cyberpunk 2077 Quest Tracker Directly Below Minimap
            GameObject questArea = CreateChild(root, "Area_QuestTracker", new Vector2(0f, -220f), new Vector2(210f, 80f));
            SetAnchorTop(questArea, -220f);

            // Title: "UNDISCOVERED" in signature Cyberpunk Yellow (#FCEE0A)
            GameObject titleObj = CreateChild(questArea, "Text_QuestTitle", new Vector2(0f, 0f), new Vector2(210f, 18f));
            SetAnchorTop(titleObj, 0f);
            _questHeaderTitleText = CreateText(titleObj, "Txt_Title", "UNDISCOVERED", 12f, TextAlignmentOptions.Left, Vector2.zero, CyberYellow, boldFont);
