        // ─────────────────────────────────────────────────────────────────────────
        // REAL-TIME UPDATES (UPDATE LOOP)
        // ─────────────────────────────────────────────────────────────────────────
        private void Update()
        {
            if (playerController == null && _insaneHero == null)
            {
                FindPlayerReference();
                if (playerController == null && _insaneHero == null) return;
            }

            UpdateBioMonitor();
            UpdateClockAndBuff();
            UpdateContextualPrompts();
            UpdateReticleMotion();
            UpdateConsumablesAndHotkeys();
            UpdateToastBanner();
        }

        private void UpdateBioMonitor()
        {
            float maxHp = playerController != null ? playerController.maxHealth : (_insaneHero != null ? _insaneHero.maxHealth : 250f);
            float curHp = playerController != null ? playerController.currentHealth : (_insaneHero != null ? _insaneHero.currentHealth : 250f);
            maxHp = Mathf.Max(maxHp, 1f);
            curHp = Mathf.Clamp(curHp, 0f, maxHp);
            float hpRatio = curHp / maxHp;

            // Active health fill
            if (_healthFillRect != null)
            {
                _healthFillRect.anchorMax = new Vector2(hpRatio, 1f);
            }

            // Ghost health trailing lag
            if (_ghostHealthFillRect != null)
            {
                _ghostHealthRatio = Mathf.MoveTowards(_ghostHealthRatio, hpRatio, Time.deltaTime * 0.40f);
                _ghostHealthFillRect.anchorMax = new Vector2(_ghostHealthRatio, 1f);
            }

            // Numeric HP text (Cyberpunk 2077 clean bold number)
            if (_healthText != null)
            {
                _healthText.text = $"{curHp:F0}";
            }

            // Cyberdeck RAM simulation (stamina drains RAM pips temporarily)
            bool isSprint = playerController != null ? (playerController.IsSprintingState && playerController.CurrentMoveSpeed > 0.5f) : (Input.GetKey(KeyCode.LeftShift));
            int activePips = isSprint ? 7 : 10;
            if (_ramCells != null)
            {
                for (int i = 0; i < _ramCells.Length; i++)
                {
                    if (_ramCells[i] != null)
                    {
                        _ramCells[i].color = (i < activePips) ? KiroshiCyan : CyanDim;
                    }
                }
            }

            // Low health vignette (< 25% HP)
            if (_lowHealthVignette != null)
            {
                if (hpRatio < 0.25f)
                {
                    float pulse = (Mathf.Sin(Time.time * 6f) + 1f) * 0.5f;
                    _lowHealthVignette.color = new Color(1f, 0f, 0.15f, 0.12f + pulse * 0.20f);
                }
                else
                {
                    _lowHealthVignette.color = Color.clear;
                }
            }
        }

        private void UpdateClockAndBuff()
        {
            // Advance in-game clock (1 real sec = 2.5 in-game mins)
            _inGameMinutes += Time.deltaTime * 2.5f;
            if (_inGameMinutes >= 1440f) _inGameMinutes -= 1440f;
            int hours = Mathf.FloorToInt(_inGameMinutes / 60f);
            int mins = Mathf.FloorToInt(_inGameMinutes % 60f);
            string ampm = hours >= 12 ? "PM" : "AM";
            int displayHours = hours % 12;
            if (displayHours == 0) displayHours = 12;

            if (_clockText != null)
            {
                _clockText.text = $"{displayHours:D2}:{mins:D2} {ampm}";
            }

            // Buff countdown timer
            if (_buffCountdownSeconds > 0f)
            {
                _buffCountdownSeconds -= Time.deltaTime;
                if (_buffCountdownSeconds < 0f) _buffCountdownSeconds = 0f;
                int bMins = Mathf.FloorToInt(_buffCountdownSeconds / 60f);
                int bSecs = Mathf.FloorToInt(_buffCountdownSeconds % 60f);
                if (_buffTimerText != null)
                {
                    _buffTimerText.text = $"{bMins:D2}:{bSecs:D2}";
                }
            }
        }

        private void UpdateContextualPrompts()
        {
            bool drawn = playerController != null ? playerController.IsSwordDrawn : true;

            if (_contextualActionDrawText != null)
            {
                _contextualActionDrawText.text = drawn
                    ? "Sheathe Weapon  <color=#00F0FF><b>(Y)</b></color>"
                    : "Draw Weapon  <color=#00F0FF><b>(Y)</b></color>";
            }

            if (_weaponNameText != null)
            {
                _weaponNameText.gameObject.SetActive(drawn);
            }
        }

        private void UpdateReticleMotion()
        {
            float speedRatio = playerController != null
                ? Mathf.Clamp01(playerController.CurrentMoveSpeed / 6f)
                : (_insaneHero != null && _insaneHero.GetComponent<CharacterController>() != null
                    ? Mathf.Clamp01(_insaneHero.GetComponent<CharacterController>().velocity.magnitude / 6f)
                    : 0f);

            float bracketOffset = 12f + speedRatio * 8f;
            if (_reticleLeftBracket != null) _reticleLeftBracket.anchoredPosition = new Vector2(-bracketOffset, 0f);
            if (_reticleRightBracket != null) _reticleRightBracket.anchoredPosition = new Vector2(bracketOffset, 0f);
        }

        private void UpdateConsumablesAndHotkeys()
        {
            var kb = UnityEngine.InputSystem.Keyboard.current;
            if (kb == null) return;

            // X Key: Consume MaxDoc Inhaler
            if (kb.xKey.wasPressedThisFrame)
            {
                if (_maxDocCount > 0)
                {
                    _maxDocCount--;
                    float healAmount = 50f;
                    if (playerController != null)
                        playerController.currentHealth = Mathf.Min(playerController.currentHealth + healAmount, playerController.maxHealth);
                    else if (_insaneHero != null)
                        _insaneHero.currentHealth = Mathf.Min(_insaneHero.currentHealth + healAmount, _insaneHero.maxHealth);

                    if (_maxDocCountText != null) _maxDocCountText.text = $"{_maxDocCount}";
                    ShowToast($"MAXDOC INHALED // +{healAmount:F0} HP", 2.0f);
                }
            }

            // G Key: Deploy Gadget
            if (kb.gKey.wasPressedThisFrame)
            {
                if (_gadgetCount > 0)
                {
                    _gadgetCount--;
                    if (_gadgetCountText != null) _gadgetCountText.text = $"{_gadgetCount}";
                    ShowToast("THERMAL GADGET DEPLOYED", 2.0f);
                }
            }

            // V Key: Summon Vehicle
            if (kb.vKey.wasPressedThisFrame)
            {
                ShowToast("CALLING VEHICLE // AUTONOMOUS HOVER TAXI DISPATCHED", 2.5f);
            }
        }

        private void UpdateToastBanner()
        {
            if (_toastTimer > 0f)
            {
                _toastTimer -= Time.deltaTime;
                if (_toastTimer <= 0f && _toastBannerObj != null)
                {
                    _toastBannerObj.SetActive(false);
                }
            }
        }

        public void ShowToast(string message, float duration = 3.0f)
        {
            if (_toastBannerObj != null && _toastBannerText != null)
            {
                _toastBannerText.text = message;
                _toastBannerObj.SetActive(true);
                _toastTimer = duration;
            }
        }

