            FillRect(tex, 18, 4, 4, 22, white);
            // Arms
            FillRect(tex, 7, 26, 3, 20, white);
            FillRect(tex, 22, 26, 3, 20, white);

            tex.filterMode = FilterMode.Bilinear;
