        private static Sprite CreateProceduralDropletSprite()
        {
            Texture2D tex = new Texture2D(32, 32, TextureFormat.RGBA32, false);
            Color clear = Color.clear;
            Color white = Color.white;
            for (int y = 0; y < 32; y++)
                for (int x = 0; x < 32; x++)
                    tex.SetPixel(x, y, clear);

            // Bulbous lower circle
            FillCircle(tex, 16, 12, 7, white);
            // Pointed upper cone
            for (int y = 14; y <= 27; y++)
            {
                int halfW = (27 - y) / 2;
                FillRect(tex, 16 - halfW, y, halfW * 2 + 1, 1, white);
            }

            tex.filterMode = FilterMode.Bilinear;
            tex.Apply();
            return Sprite.Create(tex, new Rect(0, 0, 32, 32), new Vector2(0.5f, 0.5f));
        }

        private static Texture2D CreateProceduralRadarTexture()
        {
            Texture2D tex = new Texture2D(256, 256, TextureFormat.RGBA32, false);
            Color bg = new Color(0.02f, 0.04f, 0.08f, 0.95f);
            Color gridColor = new Color(0f, 0.941f, 1f, 0.08f);
            Color ringColor = new Color(0f, 0.941f, 1f, 0.18f);
            Color buildingColor = new Color(0f, 0.941f, 1f, 0.22f);
            Color buildingOutline = new Color(0f, 0.941f, 1f, 0.50f);

            // Background
            for (int y = 0; y < 256; y++)
                for (int x = 0; x < 256; x++)
                    tex.SetPixel(x, y, bg);

            // Blueprint grid lines every 32px
            for (int i = 0; i < 256; i += 32)
            {
                for (int p = 0; p < 256; p++)
                {
                    tex.SetPixel(i, p, gridColor);
                    tex.SetPixel(p, i, gridColor);
                }
            }

            // Concentric radar scan rings
            DrawCircleOutline(tex, 128, 128, 42, ringColor);
            DrawCircleOutline(tex, 128, 128, 84, ringColor);
            DrawCircleOutline(tex, 128, 128, 118, ringColor);

            // Blueprint city blocks
            DrawBlueprintBuilding(tex, 28, 36, 52, 64, buildingColor, buildingOutline);
            DrawBlueprintBuilding(tex, 94, 28, 44, 76, buildingColor, buildingOutline);
            DrawBlueprintBuilding(tex, 150, 48, 68, 56, buildingColor, buildingOutline);
            DrawBlueprintBuilding(tex, 32, 134, 58, 74, buildingColor, buildingOutline);
            DrawBlueprintBuilding(tex, 154, 130, 72, 80, buildingColor, buildingOutline);

            // Center radar crosshair ticks
            for (int d = -8; d <= 8; d++)
            {
                tex.SetPixel(128 + d, 128, ringColor);
                tex.SetPixel(128, 128 + d, ringColor);
            }

            tex.filterMode = FilterMode.Bilinear;
            tex.Apply();
            return tex;
        }

        private static void FillRect(Texture2D tex, int x0, int y0, int w, int h, Color col)
        {
            for (int y = y0; y < y0 + h && y < tex.height; y++)
                for (int x = x0; x < x0 + w && x < tex.width; x++)
                    if (x >= 0 && y >= 0) tex.SetPixel(x, y, col);
        }

        private static void FillCircle(Texture2D tex, int cx, int cy, int r, Color col)
        {
            int r2 = r * r;
            for (int y = cy - r; y <= cy + r; y++)
                for (int x = cx - r; x <= cx + r; x++)
                    if (x >= 0 && x < tex.width && y >= 0 && y < tex.height)
                        if ((x - cx) * (x - cx) + (y - cy) * (y - cy) <= r2)
                            tex.SetPixel(x, y, col);
        }

        private static void DrawCircleOutline(Texture2D tex, int cx, int cy, int r, Color col)
        {
            int rMin2 = (r - 1) * (r - 1);
            int rMax2 = (r + 1) * (r + 1);
            for (int y = cy - r - 1; y <= cy + r + 1; y++)
                for (int x = cx - r - 1; x <= cx + r + 1; x++)
                    if (x >= 0 && x < tex.width && y >= 0 && y < tex.height)
                    {
                        int d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
                        if (d2 >= rMin2 && d2 <= rMax2) tex.SetPixel(x, y, col);
                    }
        }

        private static void DrawBlueprintBuilding(Texture2D tex, int x, int y, int w, int h, Color fill, Color outline)
        {
            FillRect(tex, x, y, w, h, fill);
            // 1px outline
            for (int i = 0; i < w; i++)
            {
                if (x + i >= 0 && x + i < tex.width)
                {
                    if (y >= 0 && y < tex.height) tex.SetPixel(x + i, y, outline);
                    if (y + h - 1 >= 0 && y + h - 1 < tex.height) tex.SetPixel(x + i, y + h - 1, outline);
                }
            }
            for (int j = 0; j < h; j++)
            {
                if (y + j >= 0 && y + j < tex.height)
                {
                    if (x >= 0 && x < tex.width) tex.SetPixel(x, y + j, outline);
                    if (x + w - 1 >= 0 && x + w - 1 < tex.width) tex.SetPixel(x + w - 1, y + j, outline);
                }
            }
        }

