// ─── 2. TOP-RIGHT: MINIMALIST MINIMAP & YELLOW QUEST TRACKER ─────────────
private void BuildTopRightTelemetryAndMinimap()
{
    GameObject root = CreateAnchorPanel("Zone_TopRight_MinimapArea",
        new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f),
        new Vector2(-40f, -36f), new Vector2(230f, 360f));

    // A. Clean Clock Above Minimap ("10:11 AM")
    GameObject clockObj = CreateChild(root, "Text_ClockHeader", new Vector2(0f, 0f), new Vector2(200f, 18f));
    SetAnchorTop(clockObj, 0f);
    _clockText = CreateText(clockObj, "Txt_Time", "10:11 AM", 12f, TextAlignmentOptions.Left, Vector2.zero, new Color(0f, 0.941f, 1f, 0.95f), boldFont);
    _clockText.fontStyle = FontStyles.Bold;

    // B. Clean Square Minimap with Subtle Border (190x190)
    GameObject minimapFrame = CreateChild(root, "Frame_Minimap", new Vector2(0f, -22f), new Vector2(190f, 190f));
    SetAnchorTop(minimapFrame, -22f);
    Image frameBg = minimapFrame.AddComponent<Image>();
    frameBg.color = DarkObsidian;
    AddBorder(minimapFrame, new Color(0f, 0.941f, 1f, 0.40f), 1f);

    // RawImage for orthographic minimap RenderTexture (with procedural cyber radar fallback)
    GameObject rawImgObj = CreateChild(minimapFrame, "RawImage_Minimap", Vector2.zero, new Vector2(186f, 186f));
    minimapRawImage = rawImgObj.AddComponent<RawImage>();
    minimapRawImage.texture = s_minimapRadarTexture;
    minimapRawImage.color = Color.white;

    // Player Blip Icon (Cyan View Cone)
    GameObject playerIconObj = CreateChild(rawImgObj, "Icon_Player", Vector2.zero, new Vector2(18f, 18f));
    Image pBlipImg = playerIconObj.AddComponent<Image>();
    pBlipImg.color = KiroshiCyan;
    Sprite coneSprite = Resources.Load<Sprite>("SyntyUI/Sprites/HUD/SPR_HUD_SciFi_Map_PlayerViewCone");
    if (coneSprite != null) { pBlipImg.sprite = coneSprite; }
    playerIconRect = playerIconObj.GetComponent<RectTransform>();

    // Container for dynamic enemy blips
    GameObject enemyBlips = CreateChild(rawImgObj, "Container_EnemyBlips", Vector2.zero, new Vector2(186f, 186f));
    enemyBlipsContainer = enemyBlips.transform;

    // North Compass Marker (Minimal Yellow "N")
    GameObject northObj = CreateChild(minimapFrame, "Marker_North", new Vector2(0f, 84f), new Vector2(20f, 14f));
    TextMeshProUGUI nTxt = CreateText(northObj, "Txt_N", "N", 11f, TextAlignmentOptions.Center, Vector2.zero, CyberYellow, boldFont);
    nTxt.fontStyle = FontStyles.Bold;

    // Link with MinimapController if present
    MinimapController minimapCtrl = GetComponent<MinimapController>() ?? Object.FindAnyObjectByType<MinimapController>();
    if (minimapCtrl != null)
    {
        minimapCtrl.SetMinimapTarget(minimapRawImage, playerIconRect, enemyBlipsContainer);
    }

    // C. Borderless Cyberpunk 2077 Quest Tracker Directly Below Minimap
    GameObject questArea = CreateChild(root, "Area_QuestTracker", new Vector2(0f, -222f), new Vector2(230f, 90f));
    SetAnchorTop(questArea, -222f);

    // Title: "UNDISCOVERED" in signature Cyberpunk Yellow (#FCEE0A)
    GameObject titleObj = CreateChild(questArea, "Text_QuestTitle", new Vector2(0f, 0f), new Vector2(230f, 20f));
    SetAnchorTop(titleObj, 0f);
    _questHeaderTitleText = CreateText(titleObj, "Txt_Title", "UNDISCOVERED", 12.5f, TextAlignmentOptions.Left, Vector2.zero, CyberYellow, boldFont);
    _questHeaderTitleText.fontStyle = FontStyles.Bold;

    // Objective row with yellow [!] badge
    GameObject objRow = CreateChild(questArea, "Row_Objective", new Vector2(0f, -22f), new Vector2(230f, 60f));
    SetAnchorTop(objRow, -22f);

    // Yellow exclamation badge [!]
    GameObject exclamBox = CreateChild(objRow, "Box_Exclamation", new Vector2(0f, -2f), new Vector2(14f, 14f));
    SetAnchorLeft(exclamBox, 0f);
    Image exclamBg = exclamBox.AddComponent<Image>();
    exclamBg.color = CyberYellow;
    TextMeshProUGUI exTxt = CreateText(exclamBox, "Txt_Ex", "!", 10.5f, TextAlignmentOptions.Center, Vector2.zero, Color.black, boldFont);
    exTxt.fontStyle = FontStyles.Bold;

    // Objective description text (clean Cyberpunk yellow body text)
    GameObject descObj = CreateChild(objRow, "Text_ObjectiveBody", new Vector2(20f, 0f), new Vector2(210f, 60f));
    SetAnchorLeft(descObj, 20f);
    _questObjectiveText = CreateText(descObj, "Txt_Body", "Who knows what you might find?", 11.5f, TextAlignmentOptions.Left, Vector2.zero, CyberYellow, bodyFont);
    _questObjectiveText.textWrappingMode = TextWrappingModes.Normal;
    _questObjectiveText.lineSpacing = 10f;
}

// ─── 3. BOTTOM-LEFT: CYBERPUNK 2077 D-PAD & EQUIPMENT CARDS ──────────────
private void BuildBottomLeftQuickItemsAndDPad()
{
    GameObject root = CreateAnchorPanel("Zone_BottomLeft_QuickAccess",
        new Vector2(0f, 0f), new Vector2(0f, 0f), new Vector2(0f, 0f),
        new Vector2(40f, 36f), new Vector2(280f, 100f));

    // A. D-Pad Cluster (Phone [T], Vehicle [V], Cyberware [TAB], with Royal Blue 9+ Badge)
    GameObject dpadRoot = CreateChild(root, "Cluster_DPad", new Vector2(0f, 0f), new Vector2(74f, 78f));
    SetAnchorLeft(dpadRoot, 0f);

    // Up: Phone
    CreateDpadIconTile(dpadRoot, "DPad_Phone", s_phoneSprite, "T", new Vector2(24f, 26f));
    // Left: Car / Vehicle
    CreateDpadIconTile(dpadRoot, "DPad_Vehicle", s_carSprite, "V", new Vector2(-4f, 0f));
    // Down: Cyberware / Scanner
    CreateDpadIconTile(dpadRoot, "DPad_Cyberware", s_cyberwareSprite, "TAB", new Vector2(24f, -26f));

    // Royal Blue "9+" Unread Notification Badge
    GameObject notifBadge = CreateChild(dpadRoot, "Badge_Notification", new Vector2(48f, 40f), new Vector2(22f, 15f));
    Image notifBg = notifBadge.AddComponent<Image>();
    notifBg.color = NotifBlue;
    TextMeshProUGUI notifTxt = CreateText(notifBadge, "Txt_Notif", "9+", 9.5f, TextAlignmentOptions.Center, Vector2.zero, Color.white, boldFont);
    notifTxt.fontStyle = FontStyles.Bold;

    // B. Dual Equipment Cards (MaxDoc [X] & Thermal Gadget [G])
    // Card 1: MaxDoc Inhaler [X]
    GameObject maxDocCard = CreateChild(root, "Card_MaxDoc", new Vector2(92f, 0f), new Vector2(44f, 58f));
    SetAnchorLeft(maxDocCard, 92f);
    Image mdBg = maxDocCard.AddComponent<Image>();
    mdBg.color = GlassTileBg;
    AddBorder(maxDocCard, new Color(1f, 0.15f, 0.25f, 0.7f), 1f);

    // Red corner tab
    GameObject mdTab = CreateChild(maxDocCard, "Tab_Red", new Vector2(0f, 27.5f), new Vector2(44f, 3f));
    mdTab.AddComponent<Image>().color = NeonCrimson;

    // Inhaler icon
    GameObject mdIcon = CreateChild(maxDocCard, "Icon_MaxDoc", new Vector2(0f, 4f), new Vector2(26f, 26f));
    Image mdIconImg = mdIcon.AddComponent<Image>();
    mdIconImg.sprite = s_inhalerSprite;
    mdIconImg.color = Color.white;

    // Count badge (3)
    _maxDocCountText = CreateText(maxDocCard, "Text_Count", "3", 12.5f, TextAlignmentOptions.BottomRight, new Vector2(-5f, 4f), TextWhite, boldFont);
    _maxDocCountText.fontStyle = FontStyles.Bold;

    // Prompt underneath [X]
    GameObject xPrompt = CreateChild(maxDocCard, "Prompt_Key", new Vector2(0f, -16f), new Vector2(36f, 14f));
    CreateText(xPrompt, "Txt_Key", "[X]", 9.5f, TextAlignmentOptions.Center, Vector2.zero, TextMuted, headerFont);

    // Card 2: Thermal Gadget / Grenade [G]
    GameObject gadgetCard = CreateChild(root, "Card_Gadget", new Vector2(148f, 0f), new Vector2(44f, 58f));
    SetAnchorLeft(gadgetCard, 148f);
    Image gBg = gadgetCard.AddComponent<Image>();
    gBg.color = GlassTileBg;
    AddBorder(gadgetCard, new Color(0f, 0.941f, 1f, 0.6f), 1f);

    // Cyan corner tab
    GameObject gTab = CreateChild(gadgetCard, "Tab_Cyan", new Vector2(0f, 27.5f), new Vector2(44f, 3f));
    gTab.AddComponent<Image>().color = KiroshiCyan;

    // Grenade icon
    GameObject gIcon = CreateChild(gadgetCard, "Icon_Gadget", new Vector2(0f, 4f), new Vector2(26f, 26f));
    Image gIconImg = gIcon.AddComponent<Image>();
    gIconImg.sprite = s_grenadeSprite;
    gIconImg.color = Color.white;

    // Count badge (2)
    _gadgetCountText = CreateText(gadgetCard, "Text_Count", "2", 12.5f, TextAlignmentOptions.BottomRight, new Vector2(-5f, 4f), TextWhite, boldFont);
    _gadgetCountText.fontStyle = FontStyles.Bold;

    // Prompt underneath [G]
    GameObject gPrompt = CreateChild(gadgetCard, "Prompt_Key", new Vector2(0f, -16f), new Vector2(36f, 14f));
    CreateText(gPrompt, "Txt_Key", "[G]", 9.5f, TextAlignmentOptions.Center, Vector2.zero, TextMuted, headerFont);
}

private void CreateDpadIconTile(GameObject parent, string name, Sprite iconSprite, string keyPrompt, Vector2 pos)
{
    GameObject tile = CreateChild(parent, name, pos, new Vector2(26f, 26f));
    Image bg = tile.AddComponent<Image>();
    bg.color = GlassTileBg;
    AddBorder(tile, new Color(0f, 0.941f, 1f, 0.45f), 1f);

    if (iconSprite != null)
    {
        GameObject iconObj = CreateChild(tile, "Icon", Vector2.zero, new Vector2(18f, 18f));
        Image iconImg = iconObj.AddComponent<Image>();
        iconImg.sprite = iconSprite;
        iconImg.color = KiroshiCyan;
    }

    // Key badge underneath
    GameObject badge = CreateChild(tile, "Badge", new Vector2(0f, -15f), new Vector2(30f, 12f));
    CreateText(badge, "Key", $"[{keyPrompt}]", 8f, TextAlignmentOptions.Center, Vector2.zero, TextMuted, headerFont);
}

// ─── 4. BOTTOM-RIGHT: CONTEXTUAL ACTIONS & RED STANCE SILHOUETTE ──────────
private void BuildBottomRightContextualPrompts()
{
    GameObject root = CreateAnchorPanel("Zone_BottomRight_ContextPrompts",
        new Vector2(1f, 0f), new Vector2(1f, 0f), new Vector2(1f, 0f),
        new Vector2(-40f, 36f), new Vector2(260f, 90f));

    // A. Contextual Action Prompts
    GameObject actionsRoot = CreateChild(root, "List_ContextActions", new Vector2(-30f, 0f), new Vector2(220f, 60f));
    SetAnchorRight(actionsRoot, -30f);

    // Action 1: Draw Weapon
    GameObject drawRow = CreateChild(actionsRoot, "Row_DrawWeapon", new Vector2(0f, 16f), new Vector2(220f, 22f));
    SetAnchorTop(drawRow, 0f);
    _contextualActionDrawText = CreateText(drawRow, "Txt_Draw", "Draw Weapon  <color=#00F0FF><b>(Y)</b></color>", 13f, TextAlignmentOptions.Right, Vector2.zero, TextWhite, boldFont);

    // Action 2: Crouch
    GameObject crouchRow = CreateChild(actionsRoot, "Row_Crouch", new Vector2(0f, -10f), new Vector2(220f, 22f));
    SetAnchorTop(crouchRow, -24f);
    _contextualActionCrouchText = CreateText(crouchRow, "Txt_Crouch", "Crouch  <color=#00F0FF><b>[RS]</b></color>", 13f, TextAlignmentOptions.Right, Vector2.zero, TextWhite, boldFont);

    // B. Neon Crimson Standing Posture Figure in Far Corner
    GameObject stanceObj = CreateChild(root, "Icon_StanceFigure", new Vector2(0f, 6f), new Vector2(18f, 42f));
    SetAnchorRight(stanceObj, 0f);
    _crouchStanceIcon = stanceObj.AddComponent<Image>();
    _crouchStanceIcon.sprite = s_humanoidSprite;
    _crouchStanceIcon.color = NeonCrimson;

    // C. Weapon Subtitle (Subtle tier indicator)
    GameObject wpObj = CreateChild(root, "Text_ActiveWeaponTag", new Vector2(0f, -22f), new Vector2(260f, 18f));
    SetAnchorBottom(wpObj, -22f);
    _weaponNameText = CreateText(wpObj, "Txt_Wp", "ARASAKA \"TSUNAGI\" (TIER 5++)", 10.5f, TextAlignmentOptions.Right, Vector2.zero, new Color(1f, 0.6f, 0.2f, 0.85f), boldFont);
}

