private TextMeshProUGUI CreateText(GameObject parent, string name, string text, float fontSize, TextAlignmentOptions align, Vector2 pos, Color color, TMP_FontAsset font)
{
    GameObject obj = new GameObject(name);
    obj.transform.SetParent(parent.transform, false);

    RectTransform rt = obj.AddComponent<RectTransform>();
    rt.anchoredPosition = pos;
    RectTransform pRt = parent.GetComponent<RectTransform>();
    float w = (pRt != null && pRt.sizeDelta.x > 0) ? pRt.sizeDelta.x : 240f;
    float h = (pRt != null && pRt.sizeDelta.y > 0) ? pRt.sizeDelta.y : 24f;
    rt.sizeDelta = new Vector2(w, h);

    TextMeshProUGUI tmp = obj.AddComponent<TextMeshProUGUI>();
    if (font != null) tmp.font = font;
    tmp.text = text;
    tmp.fontSize = fontSize;
    tmp.alignment = align;
    tmp.color = color;
    tmp.textWrappingMode = TextWrappingModes.NoWrap;
    tmp.overflowMode = TextOverflowModes.Overflow;

    return tmp;
}

