    AddBorder(tile, new Color(0f, 0.941f, 1f, 0.4f), 1f);

    if (iconSprite != null)
    {
        GameObject iconObj = CreateChild(tile, "Icon", Vector2.zero, new Vector2(16f, 16f));
        Image iconImg = iconObj.AddComponent<Image>();
        iconImg.sprite = iconSprite;
        iconImg.color = KiroshiCyan;
    }

    // Key badge underneath
    GameObject badge = CreateChild(tile, "Badge", new Vector2(0f, -13f), new Vector2(26f, 10f));
    CreateText(badge, "Key", $"[{keyPrompt}]", 7.5f, TextAlignmentOptions.Center, Vector2.zero, TextMuted, headerFont);
}

