using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using System.IO;
using SyntyCombined;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var cam = Camera.main;
        if (cam == null)
        {
            result.LogError("Camera.main not found");
            return;
        }

        GameObject hudObj = GameObject.Find("Canvas_InGameHUD");
        if (hudObj == null)
        {
            hudObj = new GameObject("Canvas_InGameHUD");
            Canvas c = hudObj.AddComponent<Canvas>();
            c.renderMode = RenderMode.ScreenSpaceOverlay;
            c.sortingOrder = 15;

            CanvasScaler scaler = hudObj.AddComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920, 1080);
            scaler.matchWidthOrHeight = 0.5f;

            hudObj.AddComponent<GraphicRaycaster>();
            hudObj.AddComponent<CyberpunkHUDController>();
            result.RegisterObjectCreation(hudObj);
        }

        var hudCtrl = hudObj.GetComponent<CyberpunkHUDController>();
        if (hudCtrl == null)
        {
            hudCtrl = hudObj.AddComponent<CyberpunkHUDController>();
        }

        // Rebuild the authentic Cyberpunk 2077 HUD
        hudCtrl.BuildCyberpunkHUD();

        // Switch to ScreenSpaceCamera temporarily for high-res render capture
        Canvas canvas = hudObj.GetComponent<Canvas>();
        RenderMode originalMode = canvas.renderMode;
        Camera originalCam = canvas.worldCamera;
        float originalDist = canvas.planeDistance;

        canvas.renderMode = RenderMode.ScreenSpaceCamera;
        canvas.worldCamera = cam;
        canvas.planeDistance = 1.0f;

        // Force canvas update
        Canvas.ForceUpdateCanvases();

        // Render to 1920x1080 RenderTexture
        int width = 1920;
        int height = 1080;
        RenderTexture rt = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32);
        RenderTexture prevTarget = cam.targetTexture;
        cam.targetTexture = rt;
        cam.Render();

        RenderTexture.active = rt;
        Texture2D screenTex = new Texture2D(width, height, TextureFormat.RGB24, false);
        screenTex.ReadPixels(new Rect(0, 0, width, height), 0, 0);
        screenTex.Apply();

        // Restore camera and canvas
        cam.targetTexture = prevTarget;
        RenderTexture.active = null;
        Object.DestroyImmediate(rt);

        canvas.renderMode = originalMode;
        canvas.worldCamera = originalCam;
        canvas.planeDistance = originalDist;

        // Save to artifacts directory
        string savePath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\cyberpunk_hud_preview.png";
        byte[] bytes = screenTex.EncodeToPNG();
        File.WriteAllBytes(savePath, bytes);
        Object.DestroyImmediate(screenTex);

        result.Log("Successfully rendered authentic Cyberpunk 2077 HUD to {0}", savePath);
    }
}

