using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var cam = Camera.main;
        var hits = Physics.RaycastAll(cam.transform.position, cam.transform.forward, 30f);
        foreach (var h in hits)
        {
            result.Log("Hit: {0}, pos: {1}, dist: {2}", h.collider.name, h.collider.transform.position, h.distance);
        }

        // Also check if there is an object named *Taxi* or *Car* near the camera
        var all = Object.FindObjectsByType<Transform>(FindObjectsSortMode.None);
        foreach (var t in all)
        {
            if (Vector3.Distance(t.position, cam.transform.position) < 15f && 
                (t.name.ToLower().Contains("taxi") || t.name.ToLower().Contains("car") || t.name.ToLower().Contains("quad")))
            {
                result.Log("Nearby vehicle/quad: {0}, pos: {1}", t.name, t.position);
            }
        }
    }
}

