        // ─────────────────────────────────────────────────────────────────────────
        // REAL-TIME UPDATES (UPDATE LOOP)
        // ─────────────────────────────────────────────────────────────────────────
        private void Update()
        {
            if (playerController == null && _insaneHero == null)
            {
                FindPlayerReference();
                if (playerController == null && _insaneHero == null) return;
            }

            UpdateBioMonitor();
            UpdateTelemetryAndMinimap();
            UpdateWeaponDiagnostics();
            UpdateReticleAndRangefinder();
            UpdateConsumablesAndHotkeys();
            UpdateToastBanner();
        }

        private void UpdateBioMonitor()
        {
            float maxHp = playerController != null ? playerController.maxHealth : (_insaneHero != null ? _insaneHero.maxHealth : 250f);
            float curHp = playerController != null ? playerController.currentHealth : (_insaneHero != null ? _insaneHero.currentHealth : 250f);
            maxHp = Mathf.Max(maxHp, 1f);
            curHp = Mathf.Clamp(curHp, 0f, maxHp);
            float hpRatio = curHp / maxHp;

            // Smooth active health fill
            if (_healthFillRect != null)
            {
                _healthFillRect.anchorMax = new Vector2(hpRatio, 1f);
            }

            // Smooth ghost health trailing
            if (_ghostHealthFillRect != null)
            {
                _ghostHealthRatio = Mathf.MoveTowards(_ghostHealthRatio, hpRatio, Time.deltaTime * 0.45f);
                _ghostHealthFillRect.anchorMax = new Vector2(_ghostHealthRatio, 1f);
            }

            // Numeric HP text
            if (_healthText != null)
            {
                _healthText.text = $"{curHp:F0} / {maxHp:F0} HP";
            }

            // Godmode / Subdermal Armor Overclock badge
            if (_armorBadgeObj != null)
            {
                bool isGod = playerController != null ? playerController.isInvincible : (_insaneHero != null ? _insaneHero.isInvincible : false);
                if (_armorBadgeObj.activeSelf != isGod)
                {
                    _armorBadgeObj.SetActive(isGod);
                    if (isGod) ShowToast("SUB-DERMAL SHIELD OVERCLOCK: ACTIVATED (GODMODE)", 2.5f);
                }
            }

            // Stamina simulation (drains during sprint, restores when idle/walking)
            bool isSprint = playerController != null 
                ? (playerController.IsSprintingState && playerController.CurrentMoveSpeed > 0.5f) 
                : (Input.GetKey(KeyCode.LeftShift));
            if (isSprint)
            {
                _currentStamina = Mathf.Clamp01(_currentStamina - Time.deltaTime * 0.25f);
            }
            else
            {
                _currentStamina = Mathf.Clamp01(_currentStamina + Time.deltaTime * 0.35f);
            }

            if (_staminaFillRect != null)
            {
                _staminaFillRect.anchorMax = new Vector2(_currentStamina, 1f);
            }

            // Low health glitch vignette (< 30% HP)
            if (_lowHealthVignette != null)
            {
                if (hpRatio < 0.30f)
                {
                    float pulse = (Mathf.Sin(Time.time * 6f) + 1f) * 0.5f;
                    _lowHealthVignette.color = new Color(1f, 0f, 0.15f, 0.15f + pulse * 0.25f);
                }
                else
                {
                    _lowHealthVignette.color = Color.clear;
                }
            }
        }

        private void UpdateTelemetryAndMinimap()
        {
            // Advance in-game clock
            _inGameMinutes += Time.deltaTime * 2.5f; // 1 real sec = 2.5 in-game mins
            if (_inGameMinutes >= 1440f) _inGameMinutes -= 1440f;
            int hours = Mathf.FloorToInt(_inGameMinutes / 60f);
            int mins = Mathf.FloorToInt(_inGameMinutes % 60f);
            string ampm = hours >= 12 ? "PM" : "AM";
            int displayHours = hours % 12;
            if (displayHours == 0) displayHours = 12;

            if (_clockText != null)
            {
                _clockText.text = $"TIME: {displayHours:D2}:{mins:D2} {ampm}";
            }

            // Heading & Compass
            Transform heroT = playerController != null ? playerController.transform : (_insaneHero != null ? _insaneHero.transform : null);
            if (_compassText != null && heroT != null)
            {
                float yRot = heroT.eulerAngles.y;
                string dir = GetCompassDirection(yRot);
                _compassText.text = $"HDG: {yRot:F0}° {dir}";
            }

            // NCPD Alert Status (Check if combat is engaged)
            bool combatActive = playerController != null
                ? (playerController.CurrentCombatState != SyntySwordLocomotionController.CombatState.None || playerController.IsSwordDrawn)
                : (_insaneHero != null && (_insaneHero.IsBlocking || _insaneHero.CurrentComboCount > 0));

            if (_threatBadgeText != null && _threatBadgeBg != null)
            {
                if (combatActive)
                {
                    float pulse = (Mathf.Sin(Time.time * 8f) + 1f) * 0.5f;
                    _threatBadgeBg.color = Color.Lerp(new Color(0.25f, 0.02f, 0.05f, 0.98f), new Color(0.45f, 0.03f, 0.08f, 0.98f), pulse);
                    _threatBadgeText.color = NeonCrimson;
                    _threatBadgeText.text = "⚠ [NCPD ALERT: COMBAT // WEAPON ENGAGED]";
                }
                else
                {
                    _threatBadgeBg.color = DarkObsidian;
                    _threatBadgeText.color = KiroshiCyan;
                    _threatBadgeText.text = "[NCPD ALERT: NO ACTIVE THREAT]";
                }
            }

            // Ensure minimap target link is kept active
            if (minimapRawImage != null && (minimapRawImage.texture == null || (_minimapCtrl != null && _minimapCtrl.minimapRawImage != minimapRawImage)))
            {
                if (_minimapCtrl == null) _minimapCtrl = GetComponent<MinimapController>() ?? Object.FindAnyObjectByType<MinimapController>();
                if (_minimapCtrl != null)
                {
                    _minimapCtrl.SetMinimapTarget(minimapRawImage, playerIconRect, enemyBlipsContainer);
                }
            }
        }

        private void UpdateWeaponDiagnostics()
        {
            bool drawn = playerController != null ? playerController.IsSwordDrawn : true;

            if (_weaponStanceText != null)
            {
                _weaponStanceText.text = drawn ? "<color=#00F0FF>● [DRAWN // READY]</color>"
                                               : "<color=#888888>○ [SHEATHED // HOLSTERED]</color>";
            }

            if (_weaponActionText != null)
            {
                if (playerController != null)
                {
                    var state = playerController.CurrentCombatState;
                    string actionName = state switch
                    {
                        SyntySwordLocomotionController.CombatState.None          => "ACTION: IDLE STANCE",
                        SyntySwordLocomotionController.CombatState.LightAttack   => $"ACTION: <color=#00ff88>{playerController.CurrentAttackName.ToUpper()}</color>",
                        SyntySwordLocomotionController.CombatState.HeavyAttack   => $"ACTION: <color=#ffaa00>{playerController.CurrentAttackName.ToUpper()}</color>",
                        SyntySwordLocomotionController.CombatState.SpecialAttack => $"ACTION: <color=#00ffff>{playerController.CurrentAttackName.ToUpper()} (DYNAMIC)</color>",
                        SyntySwordLocomotionController.CombatState.Block         => "ACTION: <color=#00ccff>DEFENSIVE GUARD / BLOCK</color>",
                        SyntySwordLocomotionController.CombatState.Parry         => "ACTION: <color=#ff00ff>PARRY DEFLECTION</color>",
                        SyntySwordLocomotionController.CombatState.Dodge         => "ACTION: <color=#ffff00>DODGE ROLL</color>",
                        SyntySwordLocomotionController.CombatState.Draw          => "ACTION: <color=#00ffff>DRAWING BLADE</color>",
                        SyntySwordLocomotionController.CombatState.Sheathe       => "ACTION: <color=#ff6666>SHEATHING BLADE</color>",
                        _                                                        => $"ACTION: {state}"
                    };
                    _weaponActionText.text = actionName;
                }
                else if (_insaneHero != null)
                {
                    if (_insaneHero.IsBlocking) _weaponActionText.text = "ACTION: <color=#00ccff>DEFENSIVE GUARD / BLOCK</color>";
                    else if (_insaneHero.CurrentComboCount > 0) _weaponActionText.text = $"ACTION: <color=#00ff88>KATANA COMBO #{_insaneHero.CurrentComboCount}</color>";
                    else if (_insaneHero.CurrentHeavyComboCount > 0) _weaponActionText.text = $"ACTION: <color=#ffaa00>HEAVY COMBO #{_insaneHero.CurrentHeavyComboCount}</color>";
                    else _weaponActionText.text = "ACTION: READY STANCE";
                }
            }
        }

        private void UpdateReticleAndRangefinder()
        {
            if (_mainCam == null) _mainCam = Camera.main;
            if (_mainCam == null) return;

            Ray ray = new Ray(_mainCam.transform.position, _mainCam.transform.forward);
            float dist = 50f;
            string targetInfo = "TARGET: SCANNING...";
            Color reticleColor = KiroshiCyan;

            if (Physics.Raycast(ray, out RaycastHit hit, 80f))
            {
                dist = hit.distance;
                GameObject hitObj = hit.collider.gameObject;

                if (hitObj.CompareTag("Enemy") || hitObj.GetComponentInParent<SwordEnemyAI>() != null || hitObj.GetComponentInParent<InsaneGun.Combat.InsaneGunSwordController>() != null)
                {
                    targetInfo = "<color=#FF003C>TARGET: CYBORG TROUBLEMAKER // THREAT: HOSTILE</color>";
                    reticleColor = NeonCrimson;
                }
                else if (hitObj.name.Contains("NPC") || hitObj.name.Contains("Pedestrian") || hitObj.name.Contains("Citizen"))
                {
                    targetInfo = "<color=#00F0FF>TARGET: CITIZEN // SCAN: CIVILIAN</color>";
                    reticleColor = KiroshiCyan;
                }
                else if (hitObj.name.Contains("Hover") || hitObj.name.Contains("Car") || hitObj.name.Contains("Taxi"))
                {
                    targetInfo = "<color=#FCEE0A>TARGET: AUTONOMOUS VEHICLE // IN SERVICE</color>";
                    reticleColor = CyberYellow;
                }
                else
                {
                    targetInfo = $"TARGET: TERRAIN // DIST: {dist:F1}M";
                }
            }

            if (_rangefinderText != null)
            {
                _rangefinderText.text = $"RNG: {dist:F1} M";
                _rangefinderText.color = reticleColor;
            }

            if (_targetScannerText != null)
            {
                _targetScannerText.text = targetInfo;
            }

            // Reticle breathing expansion during movement / combat
            float speedRatio = playerController != null
                ? Mathf.Clamp01(playerController.CurrentMoveSpeed / 6f)
                : (_insaneHero != null && _insaneHero.GetComponent<CharacterController>() != null
                    ? Mathf.Clamp01(_insaneHero.GetComponent<CharacterController>().velocity.magnitude / 6f)
                    : 0f);
            float bracketOffset = 20f + speedRatio * 12f;
            if (_reticleLeftBracket != null) _reticleLeftBracket.anchoredPosition = new Vector2(-bracketOffset, 0f);
            if (_reticleRightBracket != null) _reticleRightBracket.anchoredPosition = new Vector2(bracketOffset, 0f);
        }

        private void UpdateConsumablesAndHotkeys()
        {
            var kb = UnityEngine.InputSystem.Keyboard.current;
            bool xPressed = (kb != null && kb.xKey.wasPressedThisFrame) || Input.GetKeyDown(KeyCode.X);
            bool vPressed = (kb != null && kb.vKey.wasPressedThisFrame) || Input.GetKeyDown(KeyCode.V);

            // X Key: Consume MaxDoc Mk.3 Hypo
            if (xPressed)
            {
                if (_maxDocCount > 0)
                {
                    _maxDocCount--;
                    float healAmount = 40f;
                    if (playerController != null)
                        playerController.currentHealth = Mathf.Min(playerController.currentHealth + healAmount, playerController.maxHealth);
                    else if (_insaneHero != null)
                        _insaneHero.currentHealth = Mathf.Min(_insaneHero.currentHealth + healAmount, _insaneHero.maxHealth);

                    if (_hypoCountText != null) _hypoCountText.text = $"💉 MAXDOC MK.3 [X] (x{_maxDocCount})";
                    ShowToast($"MAXDOC MK.3 INJECTED // +{healAmount:F0} HP // REMAINING: {_maxDocCount}", 2.0f);
                }
                else
                {
                    ShowToast("NO MAXDOC HYPOS REMAINING IN INVENTORY", 2.0f);
                }
            }

            // V Key: Summon Hover Taxi / Autonomous Vehicle
            if (vPressed)
            {
                ShowToast("CALLING VEHICLE // AUTONOMOUS HOVER TAXI DISPATCHED TO GPS", 3.0f);
            }
        }

        private void UpdateToastBanner()
        {
            if (_toastTimer > 0f)
            {
                _toastTimer -= Time.deltaTime;
                if (_toastTimer <= 0f && _toastBannerObj != null)
                {
                    _toastBannerObj.SetActive(false);
                }
            }
        }

        public void ShowToast(string message, float duration = 3.0f)
        {
            if (_toastBannerObj != null && _toastBannerText != null)
            {
                _toastBannerText.text = message;
                _toastBannerObj.SetActive(true);
                _toastTimer = duration;
            }
        }

        private string GetCompassDirection(float deg)
        {
            if (deg >= 337.5f || deg < 22.5f) return "N";
            if (deg >= 22.5f && deg < 67.5f) return "NE";
            if (deg >= 67.5f && deg < 112.5f) return "E";
            if (deg >= 112.5f && deg < 157.5f) return "SE";
            if (deg >= 157.5f && deg < 202.5f) return "S";
            if (deg >= 202.5f && deg < 247.5f) return "SW";
            if (deg >= 247.5f && deg < 292.5f) return "W";
            return "NW";
        }

