using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = Object.FindAnyObjectByType<SyntyCombined.CyberpunkHUDController>();
        if (hud == null)
        {
            result.LogError("CyberpunkHUDController not found.");
            return;
        }

        var minimap = Object.FindAnyObjectByType<SyntyCombined.MinimapController>();
        if (minimap == null)
        {
            minimap = hud.gameObject.AddComponent<SyntyCombined.MinimapController>();
        }

        // Setup minimap camera and link targets
        var setupMethod = typeof(SyntyCombined.MinimapController).GetMethod("SetupMinimapCamera", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
        if (setupMethod != null) setupMethod.Invoke(minimap, null);
        minimap.SetMinimapTarget(hud.minimapRawImage, hud.playerIconRect, hud.enemyBlipsContainer);

        // Find minimap camera and render one frame
        Camera minimapCam = minimap.GetComponentInChildren<Camera>();
        if (minimapCam != null)
        {
            minimapCam.Render();
            result.Log("Minimap camera rendered to texture successfully.");
        }

        Camera mainCam = Camera.main;
        if (mainCam == null)
        {
            result.LogError("Camera.main not found.");
            return;
        }

        Canvas canvas = hud.GetComponent<Canvas>();
        RenderMode origMode = canvas.renderMode;
        Camera origCam = canvas.worldCamera;
        float origDist = canvas.planeDistance;

        canvas.renderMode = RenderMode.ScreenSpaceCamera;
        canvas.worldCamera = mainCam;
        canvas.planeDistance = 0.5f;

        RenderTexture rt = new RenderTexture(1920, 1080, 24, RenderTextureFormat.ARGB32);
        RenderTexture prevTarget = mainCam.targetTexture;
        mainCam.targetTexture = rt;
        mainCam.Render();

        RenderTexture.active = rt;
        Texture2D tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
        tex.Apply();

        mainCam.targetTexture = prevTarget;
        RenderTexture.active = null;
        Object.DestroyImmediate(rt);

        canvas.renderMode = origMode;
        canvas.worldCamera = origCam;
        canvas.planeDistance = origDist;

        string outPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\cyberpunk_hud_preview.png";
        byte[] pngBytes = tex.EncodeToPNG();
        Object.DestroyImmediate(tex);

        File.WriteAllBytes(outPath, pngBytes);
        result.Log("Saved HUD screenshot to: {0} ({1} bytes)", outPath, pngBytes.Length);
    }
}

