private void BuildTopRightTelemetryAndMinimap()
{
    GameObject root = CreateAnchorPanel("Zone_TopRight_TelemetryMinimap",
        new Vector2(1f, 1f), new Vector2(1f, 1f), new Vector2(1f, 1f),
        new Vector2(-28f, -24f), new Vector2(280f, 350f));

    // District & Sector Banner (Cyber Yellow Header)
    GameObject bannerObj = CreateChild(root, "Banner_District", new Vector2(0f, 0f), new Vector2(280f, 42f));
    SetAnchorTop(bannerObj, 0f);
    Image bannerBg = bannerObj.AddComponent<Image>();
    bannerBg.color = DarkObsidian;
    AddBorder(bannerObj, CyberYellow, 1.5f);

    TextMeshProUGUI distTxt = CreateText(bannerObj, "Text_District", "NIGHT CITY // UPPER DOWNTOWN", 14f, TextAlignmentOptions.Left, new Vector2(10f, 7f), CyberYellow, boldFont);
    distTxt.fontStyle = FontStyles.Bold;

    CreateText(bannerObj, "Text_Sector", "WATSON SECTOR // DISTRICT 02", 10f, TextAlignmentOptions.Left, new Vector2(10f, -9f), KiroshiCyan, headerFont);

    // Telemetry Bar (Clock + Compass)
    GameObject teleObj = CreateChild(root, "Bar_Telemetry", new Vector2(0f, -46f), new Vector2(280f, 20f));
    SetAnchorTop(teleObj, -46f);
    Image teleBg = teleObj.AddComponent<Image>();
    teleBg.color = new Color(0.02f, 0.03f, 0.05f, 0.98f);

    _clockText = CreateText(teleObj, "Text_Clock", "TIME: 02:47 AM", 10f, TextAlignmentOptions.Left, new Vector2(8f, 0f), TextWhite, headerFont);
    _compassText = CreateText(teleObj, "Text_Compass", "HDG: 015° N", 10f, TextAlignmentOptions.Right, new Vector2(-8f, 0f), KiroshiCyan, headerFont);

    // Threat / NCPD Status Badge
    GameObject threatObj = CreateChild(root, "Badge_ThreatStatus", new Vector2(0f, -70f), new Vector2(280f, 22f));
    SetAnchorTop(threatObj, -70f);
    _threatBadgeBg = threatObj.AddComponent<Image>();
    _threatBadgeBg.color = DarkObsidian;
    AddBorder(threatObj, KiroshiCyan, 1f);

    _threatBadgeText = CreateText(threatObj, "Text_Threat", "[NCPD ALERT: NO ACTIVE THREAT]", 10f, TextAlignmentOptions.Center, Vector2.zero, KiroshiCyan, boldFont);
    _threatBadgeText.fontStyle = FontStyles.Bold;

    // Minimap Container Frame (Chamfered Cyberpunk Radar)
    GameObject minimapFrame = CreateChild(root, "Frame_Minimap", new Vector2(0f, -98f), new Vector2(240f, 240f));
    SetAnchorTop(minimapFrame, -98f);
    Image frameBg = minimapFrame.AddComponent<Image>();
    frameBg.color = DarkObsidian;
    AddBorder(minimapFrame, KiroshiCyan, 1.5f);

    // Tech Corner Greeble Sprite
    Sprite cornerSprite = Resources.Load<Sprite>("SyntyUI/Sprites/HUD/SPR_HUD_SciFi_Frame_Corners_A");
    if (cornerSprite != null)
    {
        GameObject greeble = CreateChild(minimapFrame, "Greeble_Corners", Vector2.zero, new Vector2(240f, 240f));
        SetFullStretch(greeble);
        Image gImg = greeble.AddComponent<Image>();
        gImg.sprite = cornerSprite;
        gImg.color = new Color(0.988f, 0.933f, 0.039f, 0.45f);
        gImg.raycastTarget = false;
    }

    // RawImage for orthographic minimap RenderTexture (Live 3D City view)
    GameObject rawImgObj = CreateChild(minimapFrame, "RawImage_Minimap", Vector2.zero, new Vector2(224f, 224f));
    minimapRawImage = rawImgObj.AddComponent<RawImage>();
    minimapRawImage.color = Color.white;

    // Player Blip Icon
    GameObject playerIconObj = CreateChild(rawImgObj, "Icon_Player", Vector2.zero, new Vector2(18f, 18f));
    Image pBlipImg = playerIconObj.AddComponent<Image>();
    pBlipImg.color = KiroshiCyan;
    Sprite coneSprite = Resources.Load<Sprite>("SyntyUI/Sprites/HUD/SPR_HUD_SciFi_Map_PlayerViewCone");
    if (coneSprite != null) { pBlipImg.sprite = coneSprite; }
    playerIconRect = playerIconObj.GetComponent<RectTransform>();

    // Container for dynamic enemy blips
    GameObject enemyBlips = CreateChild(rawImgObj, "Container_EnemyBlips", Vector2.zero, new Vector2(224f, 224f));
    enemyBlipsContainer = enemyBlips.transform;

    // North Compass Marker
    GameObject northObj = CreateChild(minimapFrame, "Marker_CompassNorth", new Vector2(0f, 106f), new Vector2(30f, 18f));
    TextMeshProUGUI nTxt = CreateText(northObj, "Txt_N", "N", 14f, TextAlignmentOptions.Center, Vector2.zero, CyberYellow, boldFont);
    nTxt.fontStyle = FontStyles.Bold;

    // Connect to MinimapController
    _minimapCtrl = GetComponent<MinimapController>() ?? Object.FindAnyObjectByType<MinimapController>();
    if (_minimapCtrl == null)
    {
        _minimapCtrl = gameObject.AddComponent<MinimapController>();
    }
    if (_minimapCtrl != null)
    {
        _minimapCtrl.SetMinimapTarget(minimapRawImage, playerIconRect, enemyBlipsContainer);
    }
}

