    AddBorder(threatObj, KiroshiCyan, 1f);

    _threatBadgeText = CreateText(threatObj, "Text_Threat", "[NCPD ALERT: NO ACTIVE THREAT]", 10f, TextAlignmentOptions.Center, Vector2.zero, KiroshiCyan, boldFont);
    _threatBadgeText.fontStyle = FontStyles.Bold;

    // Minimap Container Frame (Chamfered Cyberpunk Radar)
    GameObject minimapFrame = CreateChild(root, "Frame_Minimap", new Vector2(0f, -98f), new Vector2(240f, 240f));
    SetAnchorTop(minimapFrame, -98f);
    Image frameBg = minimapFrame.AddComponent<Image>();
    frameBg.color = DarkObsidian;
    AddBorder(minimapFrame, KiroshiCyan, 1.5f);

    // Tech Corner Greeble Sprite
    Sprite cornerSprite = Resources.Load<Sprite>("SyntyUI/Sprites/HUD/SPR_HUD_SciFi_Frame_Corners_A");
    if (cornerSprite != null)
    {
        GameObject greeble = CreateChild(minimapFrame, "Greeble_Corners", Vector2.zero, new Vector2(240f, 240f));
        SetFullStretch(greeble);
        Image gImg = greeble.AddComponent<Image>();
        gImg.sprite = cornerSprite;
        gImg.color = new Color(0.988f, 0.933f, 0.039f, 0.45f);
        gImg.raycastTarget = false;
    }

    // RawImage for orthographic minimap RenderTexture (Live 3D City view)
    GameObject rawImgObj = CreateChild(minimapFrame, "RawImage_Minimap", Vector2.zero, new Vector2(224f, 224f));
