using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var minimap = Object.FindAnyObjectByType<SyntyCombined.MinimapController>();
        if (minimap == null)
        {
            result.LogError("MinimapController not found.");
            return;
        }

        minimap.SetupMinimapCamera();
        Camera cam = GameObject.Find("MinimapRenderCamera")?.GetComponent<Camera>();
        if (cam == null)
        {
            result.LogError("MinimapRenderCamera not found.");
            return;
        }

        var player = GameObject.FindWithTag("Player");
        if (player != null)
        {
            minimap.targetPlayer = player.transform;
            cam.transform.position = player.transform.position + Vector3.up * 80f;
            cam.transform.rotation = Quaternion.Euler(90f, 0f, 0f);
        }

        cam.Render();

        RenderTexture rt = cam.targetTexture;
        if (rt == null)
        {
            result.LogError("cam.targetTexture is NULL!");
            return;
        }

        RenderTexture.active = rt;
        Texture2D tex = new Texture2D(rt.width, rt.height, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, rt.width, rt.height), 0, 0);
        tex.Apply();
        RenderTexture.active = null;

        // Sample center pixels
        Color centerCol = tex.GetPixel(rt.width / 2, rt.height / 2);
        Color cornerCol = tex.GetPixel(10, 10);
        float avgBrightness = 0f;
        int nonZero = 0;
        for (int x = 0; x < rt.width; x += 16)
        {
            for (int y = 0; y < rt.height; y += 16)
            {
                Color c = tex.GetPixel(x, y);
                float b = (c.r + c.g + c.b) / 3f;
                avgBrightness += b;
                if (b > 0.05f) nonZero++;
