using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.FindWithTag("Player");
        if (player == null)
        {
            result.LogError("Player not found");
            return;
        }

        Vector3 pPos = player.transform.position;
        float[] heights = new float[] { 30f, 50f, 70f, 90f, 120f };
        foreach (float h in heights)
        {
            Vector3 cPos = pPos + Vector3.up * h;
            RaycastHit hit;
            if (Physics.Raycast(cPos, Vector3.down, out hit, h + 5f))
            {
                result.Log("Height {0}m: Ray down hit '{1}' at dist={2:F1}m (y={3:F1})", h, hit.collider.gameObject.name, hit.distance, hit.point.y);
            }
            else
            {
                result.Log("Height {0}m: Clear to ground/player!", h);
            }
        }
    }
}

