using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string scenePath = "Assets/PolygonCyberCity/Scenes/Demo_City.unity";
        var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        result.Log("Opened scene: {0}", scene.name);

        // 1. Destroy any stale MinimapRenderCameras
        var allCams = GameObject.FindObjectsByType<Camera>(FindObjectsSortMode.None);
        foreach (var c in allCams)
        {
            if (c.gameObject.name == "MinimapRenderCamera")
            {
                Object.DestroyImmediate(c.gameObject);
                result.Log("Removed old MinimapRenderCamera");
            }
        }

        // 2. Find Canvas_InGameHUD
        var hudObj = GameObject.Find("Canvas_InGameHUD");
        if (hudObj == null)
        {
            hudObj = new GameObject("Canvas_InGameHUD");
            var canvas = hudObj.AddComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = 15;
            var scaler = hudObj.AddComponent<UnityEngine.UI.CanvasScaler>();
            scaler.uiScaleMode = UnityEngine.UI.CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920, 1080);
            scaler.matchWidthOrHeight = 0.5f;
            hudObj.AddComponent<UnityEngine.UI.GraphicRaycaster>();
        }

        // Set UI layer
        int uiLayer = LayerMask.NameToLayer("UI");
        if (uiLayer >= 0) hudObj.layer = uiLayer;

        var hudComp = hudObj.GetComponent<SyntyCombined.CyberpunkHUDController>() ?? hudObj.AddComponent<SyntyCombined.CyberpunkHUDController>();
        var minimapComp = hudObj.GetComponent<SyntyCombined.MinimapController>() ?? hudObj.AddComponent<SyntyCombined.MinimapController>();

        // Find Player
        var player = GameObject.FindWithTag("Player");
        if (player != null)
        {
            minimapComp.targetPlayer = player.transform;
            hudComp.playerController = player.GetComponent<SyntyCombined.SyntySwordLocomotionController>();
        }

        // Rebuild HUD
        hudComp.BuildCyberpunkHUD();
        minimapComp.SetupMinimapCamera();
        minimapComp.SetMinimapTarget(hudComp.minimapRawImage, hudComp.playerIconRect, hudComp.enemyBlipsContainer);

        // Position minimap camera directly above player
        var miniCamObj = GameObject.Find("MinimapRenderCamera");
        if (miniCamObj != null && player != null)
        {
            Vector3 camPos = player.transform.position;
            camPos.y += 100f;
            miniCamObj.transform.position = camPos;
            miniCamObj.transform.rotation = Quaternion.Euler(90f, 0f, 0f);

            var miniCam = miniCamObj.GetComponent<Camera>();
            if (miniCam != null)
            {
                miniCam.Render();
                result.Log("Minimap camera rendered to texture!");
            }
        }

        // Set all HUD children to UI layer
        SetLayerRecursively(hudObj, uiLayer);

        // Save scene
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        result.Log("Demo_City scene saved successfully!");

        // Render game view preview
        Camera mainCam = Camera.main;
        if (mainCam != null)
        {
            Canvas canvas = hudObj.GetComponent<Canvas>();
            RenderMode origMode = canvas.renderMode;
            Camera origCam = canvas.worldCamera;
            float origDist = canvas.planeDistance;

            canvas.renderMode = RenderMode.ScreenSpaceCamera;
            canvas.worldCamera = mainCam;
            canvas.planeDistance = 0.5f;

            RenderTexture rt = new RenderTexture(1920, 1080, 24, RenderTextureFormat.ARGB32);
            RenderTexture prevTarget = mainCam.targetTexture;
            mainCam.targetTexture = rt;
            mainCam.Render();

            RenderTexture.active = rt;
            Texture2D tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
            tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
            tex.Apply();

            mainCam.targetTexture = prevTarget;
            RenderTexture.active = null;
            Object.DestroyImmediate(rt);

            canvas.renderMode = origMode;
            canvas.worldCamera = origCam;
            canvas.planeDistance = origDist;

            string outPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\cyberpunk_hud_preview.png";
            File.WriteAllBytes(outPath, tex.EncodeToPNG());
            Object.DestroyImmediate(tex);
            result.Log("Captured clean preview to: {0}", outPath);
        }
    }

    private void SetLayerRecursively(GameObject obj, int newLayer)
    {
        if (obj == null) return;
        obj.layer = newLayer;
        foreach (Transform child in obj.transform)
        {
            SetLayerRecursively(child.gameObject, newLayer);
        }
    }
}

