using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var smrs = Object.FindObjectsByType<SkinnedMeshRenderer>(FindObjectsSortMode.None);
        result.Log("Total SkinnedMeshRenderers in scene: {0}", smrs.Length);
        foreach (var smr in smrs)
        {
            if (smr.sharedMesh != null && smr.sharedMesh.blendShapeCount > 0)
            {
                result.Log("SMR with blendshapes: '{0}' on '{1}' (count={2})", smr.name, smr.transform.root.name, smr.sharedMesh.blendShapeCount);
                for (int i = 0; i < Mathf.Min(5, smr.sharedMesh.blendShapeCount); i++)
                {
                    result.Log("  BlendShape {0}: '{1}'", i, smr.sharedMesh.GetBlendShapeName(i));
                }
            }
        }

        var npcs = GameObject.FindObjectsByType<Transform>(FindObjectsSortMode.None);
        int npcCount = 0;
        foreach (var t in npcs)
        {
            if (t.name.Contains("NPC") || t.name.Contains("Chr_") || t.name.Contains("Pedestrian") || t.name.Contains("Citizen"))
            {
                if (t.parent == null || !t.parent.name.Contains("NPC"))
                {
                    npcCount++;
                    if (npcCount <= 6)
                    {
                        result.Log("NPC entity: '{0}', components: {1}", t.name, t.GetComponents<Component>().Length);
                    }
                }
            }
        }
        result.Log("Total NPC entities found: {0}", npcCount);
    }
}

