using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] guids = AssetDatabase.FindAssets("t:Prefab", new string[] { "Assets/Synty", "Assets/Characters", "Assets/PolygonCyberCity" });
        result.Log("Total prefabs found: {0}", guids.Length);
        int blendShapePrefabs = 0;
        foreach (var guid in guids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            var go = AssetDatabase.LoadAssetAtPath<GameObject>(path);
            if (go != null)
            {
                var smrs = go.GetComponentsInChildren<SkinnedMeshRenderer>(true);
                foreach (var smr in smrs)
                {
                    if (smr.sharedMesh != null && smr.sharedMesh.blendShapeCount > 10)
                    {
                        blendShapePrefabs++;
                        result.Log("Found prefab with blendshapes ({0} shapes): {1}", smr.sharedMesh.blendShapeCount, path);
                        break;
                    }
                }
            }
        }
        result.Log("Total prefabs with blendshapes: {0}", blendShapePrefabs);
    }
}

