    {
        var player = GameObject.FindWithTag("Player");
        if (player == null) return;

        Vector3 pPos = player.transform.position;
        if (Physics.Raycast(pPos + Vector3.up * 2f, Vector3.down, out RaycastHit hit, 50f))
        {
            result.Log("Ground hit below player at: {0}, object: {1}", hit.point, hit.collider.name);
        }

        // Raycast down in front of player
        Vector3 forwardPos = pPos + player.transform.forward * 3.5f;
        if (Physics.Raycast(forwardPos + Vector3.up * 5f, Vector3.down, out RaycastHit hitFwd, 50f))
        {
            result.Log("Ground hit 3.5m in front of player: {0}, object: {1}", hitFwd.point, hitFwd.collider.name);
        }
    }
}

