using UnityEngine;
using UnityEditor;
using UnityEngine.AI;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.FindWithTag("Player");
        if (player == null) return;
        Vector3 pPos = player.transform.position;

        // Test a few candidate positions for NPCs around player
        Vector3[] offsets = new Vector3[]
        {
            player.transform.forward * 4.0f + player.transform.right * -2.2f, // Left-forward
            player.transform.forward * 4.5f + player.transform.right * 2.5f,  // Right-forward
            player.transform.forward * 7.5f,                                  // Center street forward
            player.transform.right * -3.5f,                                   // Left sidewalk
            player.transform.right * 3.5f                                     // Right sidewalk
        };

        for (int i = 0; i < offsets.Length; i++)
        {
            Vector3 testPos = pPos + offsets[i];
            if (Physics.Raycast(testPos + Vector3.up * 4f, Vector3.down, out RaycastHit hit, 20f))
            {
                bool onNavMesh = NavMesh.SamplePosition(hit.point, out NavMeshHit navHit, 1.5f, NavMesh.AllAreas);
                result.Log("Candidate {0}: hit={1} (ground obj={2}), onNavMesh={3}", i, hit.point, hit.collider.name, onNavMesh);
            }
            else
            {
                result.LogWarning("Candidate {0}: No ground hit!", i);
            }
        }
    }
}

