        Vector3 fwd = player.transform.forward;

        for (float d = 2.0f; d <= 7.0f; d += 1.0f)
        {
            Vector3 test = pPos + fwd * d;
            if (Physics.Raycast(test + Vector3.up * 3f, Vector3.down, out RaycastHit hit, 15f))
            {
                result.Log("Distance {0}m forward: ground at {1}, obj={2}", d, hit.point, hit.collider.name);
            }
        }
    }
}

