    {
        var ido = GameObject.Find("Sidekick_Doctor_Ido");
        if (ido != null)
        {
            result.DestroyObject(ido);
        }

        var demoPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/SidekickCharacters/_Demos/Prefabs/SK_FacialDemoCharacter.prefab");
        if (demoPrefab != null)
        {
            GameObject newChar = (GameObject)PrefabUtility.InstantiatePrefab(demoPrefab);
            newChar.name = "Sidekick_Doctor_Ido";
            newChar.transform.position = new Vector3(14.2f, -16.24f, 54.8f);
            newChar.transform.rotation = Quaternion.Euler(0f, -45f, 0f);

            var fa = newChar.AddComponent<Synty.Sidekick.Facial.SyntySidekickFacialAnimator>();
            fa.characterDisplayName = "DR. IDO";
            fa.characterRoleSubtitle = "CYBER SURGEON // CLINIC";
            fa.richDialogueLines = new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry[]
            {
                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("Stay sharp out there, choom. Boostergangers in Sector 4 are packing military disruptors.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Serious),
                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("I inspected your Damascus katana earlier. Blade alignment is pristine. Treat it well.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Friendly),
                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("If your core cyber-servos surge past redline, drop by the clinic. Cleanest chrome in town.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.CyberpunkSmirk),
                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("The Blackwall telemetry is fluctuating wildly today. Keep your ICE filters calibrated.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Serious)
            };
            fa.enableProximityInteraction = true;
            fa.interactionRadius = 3.6f;
            fa.enableBlinking = true;
            fa.enableHeadMicroGestures = true;
            fa.enableLookAtPlayer = true;
            fa.currentMood = Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Serious;
            fa.CacheBlendShapeIndices();

            var anim = newChar.GetComponent<Animator>();
            if (anim != null)
            {
                var idleAc = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Synty/SidekickCharacters/_Demos/Animations/AC_FacialAnim.controller");
                if (idleAc != null) anim.runtimeAnimatorController = idleAc;
            }

            var col = newChar.GetComponent<Collider>();
            if (col == null)
            {
                var cap = newChar.AddComponent<CapsuleCollider>();
                cap.center = new Vector3(0, 0.95f, 0);
                cap.radius = 0.35f;
                cap.height = 1.9f;
            }

            result.RegisterObjectCreation(newChar);
            result.Log("Instantiated complete unified SK_FacialDemoCharacter as Doctor Ido!");
        }

        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(
            UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene());
        UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
    }
