using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var ido = GameObject.Find("Sidekick_Doctor_Ido");
        if (ido == null) return;

        // Add a soft cyberpunk cyan rim/key light to highlight facial expressions
        var lightObj = ido.transform.Find("FaceKeyLight");
        Light lightComp;
        if (lightObj == null)
        {
            var go = new GameObject("FaceKeyLight");
            go.transform.SetParent(ido.transform, false);
            go.transform.localPosition = new Vector3(0.2f, 1.7f, 0.8f);
            lightComp = go.AddComponent<Light>();
        }
        else
        {
            lightComp = lightObj.GetComponent<Light>();
        }
        lightComp.type = LightType.Point;
        lightComp.range = 2.5f;
        lightComp.intensity = 2.2f;
        lightComp.color = new Color(0.9f, 0.95f, 1.0f);

        // Frame close-up on head
        var sv = SceneView.lastActiveSceneView;
        if (sv != null)
        {
            Vector3 headPos = ido.transform.position + Vector3.up * 1.55f;
            Vector3 camPos = headPos + ido.transform.forward * 0.85f + Vector3.up * 0.05f;
            sv.pivot = headPos;
            sv.rotation = Quaternion.LookRotation((headPos - camPos).normalized, Vector3.up);
            sv.size = 0.42f;
            sv.Repaint();
            result.Log("Framed close-up with key light on Doctor Ido!");
        }
    }
}

