internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var ido = GameObject.Find("Sidekick_Doctor_Ido");
        if (ido == null) return;

        var smr = ido.GetComponentInChildren<SkinnedMeshRenderer>();
        if (smr != null)
        {
            // Reset all blendshapes first
            UnityEngine.Mesh m = smr.sharedMesh;
            for (int i = 0; i < m.blendShapeCount; i++) smr.SetBlendShapeWeight(i, 0f);

            // Set mouth wide open and blinking eyes shut
            smr.SetBlendShapeWeight(27, 95f); // eyeBlinkUpperLeft
            smr.SetBlendShapeWeight(34, 95f); // eyeBlinkUpperRight
            smr.SetBlendShapeWeight(6, 40f);  // eyeBlinkLowerLeft
            smr.SetBlendShapeWeight(15, 40f); // eyeBlinkLowerRight
            smr.SetBlendShapeWeight(79, 90f); // jawOpen
            smr.SetBlendShapeWeight(12, 60f); // mouthFunnel

            var sv = SceneView.lastActiveSceneView;
            if (sv != null) sv.Repaint();
            result.Log("Tested Doctor Ido blink and mouth open!");
        }
    }
}

