221:         public void CacheBlendshapeIndices()
222:         {
223:             _blendshapeIndices = new Dictionary<SkinnedMeshRenderer, Dictionary<string, int>>();
224:             if (_meshRenderers.Count < 1)
225:             {
226:                 return;
227:             }
228: 
229:             foreach (SkinnedMeshRenderer meshRenderer in _meshRenderers)
230:             {
231:                 if (meshRenderer == null || meshRenderer.sharedMesh == null)
232:                 {
233:                     continue;
234:                 }
235: 
236:                 Dictionary<string, int> currentIndices = new Dictionary<string, int>();
237: 
238:                 Mesh mesh = meshRenderer.sharedMesh;
239:                 for (int i = 0; i < mesh.blendShapeCount; i++)
240:                 {
241:                     string blendName = mesh.GetBlendShapeName(i);
242:                     currentIndices[blendName] = i;
243:                 }
244: 
245:                 _blendshapeIndices[meshRenderer] = currentIndices;
246:             }
247:         }
248: 
249:         public void SetBlendValue(string blendName, float value)
250:         {
251:             foreach (SkinnedMeshRenderer meshRenderer in _meshRenderers)
252:             {
253:                 if (_blendshapeIndices.TryGetValue(meshRenderer, out Dictionary<string, int> currentIndices))
254:                 {
255:                     if (currentIndices.TryGetValue(blendName, out int index))
256:                     {
257:                         meshRenderer.SetBlendShapeWeight(index, Mathf.Clamp01(value) * 100f);
258:                     }
259:                 }
260:             }
261:         }
