                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("My daemon breached their proxy node. We have 90 seconds before countermeasures engage.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Friendly),
