                new Synty.Sidekick.Facial.SyntySidekickFacialAnimator.DialogueEntry("Stay in the shadows until I drop the perimeter defense protocol.", Synty.Sidekick.Facial.SyntySidekickFacialAnimator.FacialMood.Serious)
            };
            fa.enableProximityInteraction = true;
            fa.interactionRadius = 3.6f;
            fa.enableBlinking = true;
            fa.enableHeadMicroGestures = true;
            fa.enableLookAtPlayer = true;
