                if (idleAc != null) anim.runtimeAnimatorController = idleAc;
            }

            var col = go.GetComponent<Collider>();
            if (col == null)
            {
                var cap = go.AddComponent<CapsuleCollider>();
                cap.center = new Vector3(0, 0.95f, 0);
                cap.radius = 0.35f;
                cap.height = 1.9f;
            }

