            l.type = LightType.Point;
            l.range = 2.5f;
            l.intensity = 2.2f;
            l.color = new Color(1.0f, 0.85f, 0.95f);

            result.RegisterObjectCreation(go);
            result.Log("Instantiated ScifiCivilians_02 as Mira!");
