        var ido = GameObject.Find("Sidekick_Doctor_Ido");
        if (ido == null)
        {
            result.Log("Doctor Ido not found!");
            return;
        }

        // Reposition Ido directly onto the walkway in front of the player
        ido.transform.position = new Vector3(14.6f, -17.99f, 55.6f);
        ido.transform.rotation = Quaternion.Euler(0, -50f, 0); // Facing towards the player

        var anim = ido.GetComponent<SyntySidekickFacialAnimator>();
        if (anim != null)
        {
            anim.characterDisplayName = "DOCTOR IDO";
            anim.characterRoleSubtitle = "CYBERNETIC CHIRURGEON // SECTOR 4";
            anim.interactionRadius = 3.8f;
            anim.currentMood = SyntySidekickFacialAnimator.FacialMood.CyberpunkSmirk;
            anim.richDialogueLines = new SyntySidekickFacialAnimator.DialogueEntry[]
            {
                new SyntySidekickFacialAnimator.DialogueEntry("Careful with that neural cyberware, kid. Black market implants leak cortex radiation.", SyntySidekickFacialAnimator.FacialMood.CyberpunkSmirk),
                new SyntySidekickFacialAnimator.DialogueEntry("I rebuilt that cyberarm myself. Reinforced titanium alloy and fluid pneumatic servos.", SyntySidekickFacialAnimator.FacialMood.Friendly),
                new SyntySidekickFacialAnimator.DialogueEntry("Arasaka patrols have been sweeping the underground scrapyard. Don't let them scan you.", SyntySidekickFacialAnimator.FacialMood.Serious),
                new SyntySidekickFacialAnimator.DialogueEntry("If your Damascus blade dulls, bring it by my clinic. I have high-frequency thermal polishers.", SyntySidekickFacialAnimator.FacialMood.Friendly)
            };
            anim.CacheBlendShapeIndices();
            result.Log("Updated Doctor Ido at {0} with rich dialogue lines!", ido.transform.position);
        }

        var mira = GameObject.Find("Sidekick_Netrunner_Mira");
        if (mira != null)
        {
            mira.transform.position = new Vector3(16.2f, -17.99f, 56.4f);
            mira.transform.rotation = Quaternion.Euler(0, -95f, 0); // Facing player & Ido
            var animM = mira.GetComponent<SyntySidekickFacialAnimator>();
            if (animM != null)
            {
                animM.interactionRadius = 3.8f;
                animM.CacheBlendShapeIndices();
                result.Log("Updated Mira at {0}!", mira.transform.position);
            }
        }

        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(
            UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene());
        UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
    }
}

