using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var allObjects = Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        List<GameObject> rails = new List<GameObject>();
        List<GameObject> trains = new List<GameObject>();

        foreach (var go in allObjects)
        {
            string name = go.name.ToLower();
            if (name.Contains("rail") || name.Contains("train"))
            {
                if (name.Contains("veh_train") || name.Contains("train_cockpit") || name.Contains("train_middle"))
                {
                    trains.Add(go);
                }
                else if (name.Contains("bld_train_rail") || name.Contains("train_rail") || name.Contains("rail_"))
                {
                    rails.Add(go);
                }
                else
                {
                    result.Log("Other train/rail related: {0} at {1}", go.name, go.transform.position);
                }
            }
        }

        result.Log("Found {0} rail pieces and {1} train vehicle objects in scene.", rails.Count, trains.Count);

        for (int i = 0; i < Mathf.Min(rails.Count, 15); i++)
        {
            result.Log("Rail [{0}]: {1} at pos={2}, rot={3}", i, rails[i].name, rails[i].transform.position, rails[i].transform.eulerAngles);
        }
    }
}

using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trainsObj = GameObject.Find("Trains");
        if (trainsObj != null)
        {
            result.Log("Found 'Trains' root at {0}, active={1}, childCount={2}", trainsObj.transform.position, trainsObj.activeSelf, trainsObj.transform.childCount);
            for (int i = 0; i < trainsObj.transform.childCount; i++)
            {
                var c = trainsObj.transform.GetChild(i);
                result.Log("  Child [{0}]: {1} at pos={2}, rot={3}, active={4}", i, c.name, c.position, c.eulerAngles, c.gameObject.activeSelf);
            }
        }
        else
        {
            result.Log("'Trains' root not found by exact name.");
        }

        // Also search specifically for SM_Bld_Train_Rail or SM_Veh_Train
        var allMFs = Object.FindObjectsByType<MeshFilter>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        int railCount = 0;
        int vehTrainCount = 0;
        foreach (var mf in allMFs)
        {
            if (mf.sharedMesh == null) continue;
            string meshName = mf.sharedMesh.name.ToLower();
            if (meshName.Contains("train_rail"))
            {
                railCount++;
                if (railCount <= 20)
                {
                    result.Log("Rail MeshFilter: GO='{0}', mesh='{1}', pos={2}, rot={3}", mf.gameObject.name, mf.sharedMesh.name, mf.transform.position, mf.transform.eulerAngles);
                }
            }
            else if (meshName.Contains("veh_train"))
            {
                vehTrainCount++;
                result.Log("Veh Train MeshFilter: GO='{0}', mesh='{1}', pos={2}, rot={3}", mf.gameObject.name, mf.sharedMesh.name, mf.transform.position, mf.transform.eulerAngles);
            }
        }
        result.Log("Total Train_Rail mesh instances: {0}, Total Veh_Train mesh instances: {1}", railCount, vehTrainCount);
    }
}

