{
    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");
        var vehiclesRoot = GameObject.Find("Vehicles");

        var train1Cockpit = trainsRoot.transform.Find("SM_Veh_Train_Cockpit_01 (7)");
        var train2Cockpit = vehiclesRoot.transform.Find("SM_Veh_Train_Cockpit_01 (1)");
        var train3Cockpit = vehiclesRoot.transform.Find("SM_Veh_Train_Cockpit_01");

        void CheckCockpit(string label, Transform t)
        {
            if (t == null) { result.Log("{0}: null", label); return; }
            result.Log("=== {0} ===", label);
            result.Log("Pos: {0}, Rot: {1}", t.position, t.eulerAngles);

            // Find nearest rail pieces
            var allRails = trainsRoot.GetComponentsInChildren<Transform>();
            Transform nearestRail = null;
            float minDist = float.MaxValue;
            foreach (var r in allRails)
            {
                if (!r.name.Contains("Rail_Straight") && !r.name.Contains("Rail_Curve")) continue;
                float d = Vector3.Distance(t.position, r.position);
                if (d < minDist)
                {
                    minDist = d;
                    nearestRail = r;
                }
            }
            if (nearestRail != null)
            {
                result.Log("Nearest Rail: {0} at pos={1}, rot={2}, delta={3}", 
                    nearestRail.name, nearestRail.position, nearestRail.eulerAngles, t.position - nearestRail.position);
            }
        }

        CheckCockpit("Train 1 (High Eastern Track)", train1Cockpit);
        CheckCockpit("Train 2 (Mid Western Track)", train2Cockpit);
        CheckCockpit("Train 3 (Low Underground/Lower Track)", train3Cockpit);
    }
}

