using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");
        if (trainsRoot == null) return;

        List<Transform> allRails = new List<Transform>();
        foreach (Transform child in trainsRoot.transform)
        {
            if (child.name.Contains("Rail_Straight") || child.name.Contains("Rail_Curve") || child.name.Contains("Rail_Connector"))
            {
                allRails.Add(child);
            }
        }

        result.Log("Total rail pieces to analyze: {0}", allRails.Count);

        // Group by Y elevation within tolerance of 1.0m
        List<List<Transform>> circuits = new List<List<Transform>>();
        var remaining = new HashSet<Transform>(allRails);

        while (remaining.Count > 0)
        {
            var first = remaining.First();
            remaining.Remove(first);

            List<Transform> group = new List<Transform> { first };
            Queue<Transform> queue = new Queue<Transform>();
            queue.Enqueue(first);

            while (queue.Count > 0)
            {
                var curr = queue.Dequeue();
                var toRemove = new List<Transform>();

                foreach (var other in remaining)
                {
                    // Pieces that connect are typically within ~26m of each other (straight pieces are 25m long)
                    if (Mathf.Abs(curr.position.y - other.position.y) < 1.5f)
                    {
                        float dist = Vector3.Distance(curr.position, other.position);
                        if (dist < 32f) // connected!
                        {
                            toRemove.Add(other);
                            queue.Enqueue(other);
                            group.Add(other);
                        }
                    }
                }

                foreach (var r in toRemove) remaining.Remove(r);
            }

            circuits.Add(group);
        }

        result.Log("Identified {0} distinct connected track networks/levels:", circuits.Count);
        for (int i = 0; i < circuits.Count; i++)
        {
            var c = circuits[i];
            float avgY = c.Average(p => p.position.y);
            Vector3 min = c.Select(p => p.position).Aggregate(Vector3.Min);
            Vector3 max = c.Select(p => p.position).Aggregate(Vector3.Max);
            result.Log("Circuit [{0}]: {1} pieces, Y={2:F1}m, bounds=({3:F0},{4:F0}) to ({5:F0},{6:F0}), span=({7:F0}m x {8:F0}m)",
                i, c.Count, avgY, min.x, min.z, max.x, max.z, max.x - min.x, max.z - min.z);
        }
    }
}

