using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");
        var vehiclesRoot = GameObject.Find("Vehicles");

        var train1Cockpit = trainsRoot.transform.Find("SM_Veh_Train_Cockpit_01 (7)");
        var train2Cockpit = vehiclesRoot.transform.Find("SM_Veh_Train_Cockpit_01 (1)");
        var train3Cockpit = vehiclesRoot.transform.Find("SM_Veh_Train_Cockpit_01");

        void TraceTrackFrom(string trainName, Transform cockpit)
        {
            if (cockpit == null) return;
            result.Log("--------------------------------------------------");
            result.Log("Tracing Track for {0} at {1}", trainName, cockpit.position);

            // Find all rails near this Y level (within +- 3m)
            List<Transform> levelRails = new List<Transform>();
            foreach (Transform c in trainsRoot.transform)
            {
                if ((c.name.Contains("Rail_Straight") || c.name.Contains("Rail_Curve") || c.name.Contains("Rail_Connector"))
                    && Mathf.Abs(c.position.y - cockpit.position.y - 4.4f) < 4.0f)
                {
                    levelRails.Add(c);
                }
            }
            result.Log("Found {0} rail pieces near this Y elevation (Y ~ {1:F1})", levelRails.Count, cockpit.position.y + 4.4f);

            // Print the nearest 10 rails to the train
            levelRails.Sort((a, b) => Vector3.Distance(cockpit.position, a.position).CompareTo(Vector3.Distance(cockpit.position, b.position)));
            for (int i = 0; i < Mathf.Min(levelRails.Count, 8); i++)
            {
                var r = levelRails[i];
                result.Log("  Rail [{0}]: {1} at {2}, rot={3}", i, r.name, r.position, r.eulerAngles);
            }
        }

        TraceTrackFrom("Train 1", train1Cockpit);
        TraceTrackFrom("Train 2", train2Cockpit);
        TraceTrackFrom("Train 3", train3Cockpit);
    }
}

