internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");

        void InspectTrackLevel(string label, float targetY)
        {
            List<Transform> pieces = new List<Transform>();
            foreach (Transform t in trainsRoot.transform)
            {
                if ((t.name.Contains("Rail_Straight") || t.name.Contains("Rail_Curve") || t.name.Contains("Rail_Connector"))
                    && Mathf.Abs(t.position.y - targetY) < 1.0f)
                {
                    pieces.Add(t);
                }
            }

            result.Log("==============================================");
            result.Log("{0}: {1} pieces at Y={2:F2}", label, pieces.Count, targetY);

            // Print pieces sorted in order of connection
            foreach (var p in pieces)
            {
                result.Log("  Piece: {0} | pos={1} | rot={2}", p.name, p.position, p.eulerAngles);
            }
        }

        InspectTrackLevel("Track at Y=25.38 (Train 1)", 25.38f);
        InspectTrackLevel("Track at Y=16.50 (Train 2)", 16.50f);
        InspectTrackLevel("Track at Y=-10.25 (Train 3)", -10.25f);
        InspectTrackLevel("Track at Y=-46.90 (Subway / Lower)", -46.90f);
        InspectTrackLevel("Track at Y=95.50 (Skyline Rail)", 95.50f);
    }
}

