internal class CommandScript : IRunCommand
{
    public class RailSegment
    {
        public string name;
        public bool isCurve;
        public Vector3 pA; // transform.position
        public Vector3 pB; // far endpoint
        public Transform transform;
    }

    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");
        List<RailSegment> segments = new List<RailSegment>();

        foreach (Transform t in trainsRoot.transform)
        {
            if (Mathf.Abs(t.position.y - 25.38f) < 1.0f)
            {
                if (t.name.Contains("Rail_Straight"))
                {
                    segments.Add(new RailSegment {
                        name = t.name,
                        isCurve = false,
                        pA = t.position,
                        pB = t.TransformPoint(new Vector3(-25f, 0f, 0f)),
                        transform = t
                    });
                }
                else if (t.name.Contains("Rail_Curve"))
                {
                    segments.Add(new RailSegment {
                        name = t.name,
                        isCurve = true,
                        pA = t.position,
                        pB = t.TransformPoint(new Vector3(-25f, 0f, -25f)),
                        transform = t
                    });
                }
            }
        }

        result.Log("Total Track 1 segments: {0}", segments.Count);

        // Find endpoints of the whole network
        List<RailSegment> terminusSegments = new List<RailSegment>();
        List<bool> terminusIsA = new List<bool>();

        foreach (var seg in segments)
        {
            bool matchA = false;
            bool matchB = false;
            foreach (var other in segments)
            {
                if (seg == other) continue;
                if (Vector3.Distance(seg.pA, other.pA) < 0.5f || Vector3.Distance(seg.pA, other.pB) < 0.5f) matchA = true;
                if (Vector3.Distance(seg.pB, other.pA) < 0.5f || Vector3.Distance(seg.pB, other.pB) < 0.5f) matchB = true;
            }

            if (!matchA) { terminusSegments.Add(seg); terminusIsA.Add(true); }
            if (!matchB) { terminusSegments.Add(seg); terminusIsA.Add(false); }
        }

        result.Log("Found {0} terminus endpoints in Track 1.", terminusSegments.Count);
        for (int i = 0; i < terminusSegments.Count; i++)
        {
            var s = terminusSegments[i];
            Vector3 pt = terminusIsA[i] ? s.pA : s.pB;
            result.Log("  Terminus {0}: on '{1}', at {2}", i, s.name, pt);
        }

        // Now traverse from Terminus 0 to Terminus 1!
        if (terminusSegments.Count >= 2)
        {
            var currSeg = terminusSegments[0];
            Vector3 currPt = terminusIsA[0] ? currSeg.pA : currSeg.pB;
            Vector3 exitPt = terminusIsA[0] ? currSeg.pB : currSeg.pA;

            List<Vector3> waypoints = new List<Vector3> { currPt, exitPt };
            List<RailSegment> visited = new List<RailSegment> { currSeg };

            while (visited.Count < segments.Count)
            {
                RailSegment nextSeg = null;
                bool enterAtA = false;

                foreach (var other in segments)
                {
                    if (visited.Contains(other)) continue;
                    if (Vector3.Distance(exitPt, other.pA) < 0.5f)
                    {
                        nextSeg = other;
                        enterAtA = true;
                        break;
                    }
                    if (Vector3.Distance(exitPt, other.pB) < 0.5f)
                    {
                        nextSeg = other;
                        enterAtA = false;
                        break;
                    }
                }

                if (nextSeg == null)
                {
                    result.Log("Traversal stopped at {0} segments visited.", visited.Count);
                    break;
                }

                visited.Add(nextSeg);
                currSeg = nextSeg;
                exitPt = enterAtA ? nextSeg.pB : nextSeg.pA;
                waypoints.Add(exitPt);
            }

            result.Log("Track 1 full continuous path traversed: {0}/{1} segments, total path length: {2:F1}m!",
                visited.Count, segments.Count, CalculateLength(waypoints));
            result.Log("Path Start: {0}, Path End: {1}", waypoints[0], waypoints[waypoints.Count - 1]);
        }
    }

    private float CalculateLength(List<Vector3> pts)
    {
        float len = 0f;
        for (int i = 0; i < pts.Count - 1; i++) len += Vector3.Distance(pts[i], pts[i + 1]);
        return len;
    }
}

