internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        GameObject root = GameObject.Find("Trains");
        Transform sampleCurve = null;
        for (int i = 0; i < root.transform.childCount; i++)
        {
            Transform child = root.transform.GetChild(i);
            if (child.name.Contains("Rail_Curve"))
            {
                sampleCurve = child;
                break;
            }
        }

        if (sampleCurve != null)
        {
            Mesh mesh = sampleCurve.GetComponent<MeshFilter>().sharedMesh;
            Vector3[] verts = mesh.vertices;
            // Let's find vertices near (0,0,0) and near the other end
            Vector3 min = Vector3.zero, max = Vector3.zero;
            foreach (var v in verts)
            {
                min = Vector3.Min(min, v);
                max = Vector3.Max(max, v);
            }
            result.Log("Curve vertex min: {0}, max: {1}", min, max);

            // Check adjacent rails to sampleCurve in the scene
            for (int i = 0; i < root.transform.childCount; i++)
            {
                Transform child = root.transform.GetChild(i);
                if (child == sampleCurve) continue;
                float d1 = Vector3.Distance(sampleCurve.position, child.position);
                Vector3 endLocal = new Vector3(-25f, 0f, -25f);
                Vector3 endWorld = sampleCurve.TransformPoint(endLocal);
                float d2 = Vector3.Distance(endWorld, child.position);
                Vector3 otherEnd = child.TransformPoint(new Vector3(-25f, 0f, 0f));
                float d3 = Vector3.Distance(endWorld, otherEnd);
                if (d1 < 1f || d2 < 1f || d3 < 1f)
