                    result.Log("Adjacent to {0}: '{1}' (pos: {2}, rot: {3}, d_start={4:F2}, d_end={5:F2}, d_endToOtherEnd={6:F2})",
                        sampleCurve.name, child.name, child.position, child.eulerAngles, d1, d2, d3);
