using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public class RailSegment
    {
        public Transform tf;
        public Vector3 p0; // world start
        public Vector3 p1; // world end
        public bool isCurve;
    }

    public void Execute(ExecutionResult result)
    {
        GameObject root = GameObject.Find("Trains");
        if (root == null)
        {
            result.LogError("Could not find 'Trains' GameObject");
            return;
        }

        List<RailSegment> rails = new List<RailSegment>();
        for (int i = 0; i < root.transform.childCount; i++)
        {
            Transform t = root.transform.GetChild(i);
            if (!t.name.Contains("Rail_")) continue;

            bool isCurve = t.name.Contains("Rail_Curve");
            Vector3 p0 = t.position;
            Vector3 p1 = isCurve ? t.TransformPoint(new Vector3(-25f, 0f, -25f)) : t.TransformPoint(new Vector3(-25f, 0f, 0f));

            rails.Add(new RailSegment { tf = t, p0 = p0, p1 = p1, isCurve = isCurve });
        }

        result.Log("Total rail pieces found: {0}", rails.Count);

        // Group into connected components
        List<List<RailSegment>> components = new List<List<RailSegment>>();
        HashSet<RailSegment> visited = new HashSet<RailSegment>();

        foreach (var rail in rails)
        {
            if (visited.Contains(rail)) continue;

            List<RailSegment> comp = new List<RailSegment>();
            Queue<RailSegment> queue = new Queue<RailSegment>();
            queue.Enqueue(rail);
            visited.Add(rail);

            while (queue.Count > 0)
            {
                var cur = queue.Dequeue();
                comp.Add(cur);

                foreach (var other in rails)
                {
                    if (visited.Contains(other)) continue;
                    // check endpoint proximity (within 1.5m)
                    if (Vector3.Distance(cur.p0, other.p0) < 1.5f ||
                        Vector3.Distance(cur.p0, other.p1) < 1.5f ||
                        Vector3.Distance(cur.p1, other.p0) < 1.5f ||
                        Vector3.Distance(cur.p1, other.p1) < 1.5f)
                    {
                        visited.Add(other);
                        queue.Enqueue(other);
                    }
                }
            }
            components.Add(comp);
        }

        result.Log("Identified {0} distinct connected track circuits/networks", components.Count);
        for (int c = 0; c < components.Count; c++)
        {
            var comp = components[c];
            float avgY = 0f;
            foreach (var r in comp) avgY += r.p0.y;
            avgY /= comp.Count;
            result.Log("Track {0}: {1} segments, avg Y={2:F2}m", c + 1, comp.Count, avgY);
        }
    }
}

