                        // check endpoint proximity (within 1.5m)
                        if (Vector3.Distance(cur.p0, other.p0) < 1.5f || Vector3.Distance(cur.p0, other.p1) < 1.5f || Vector3.Distance(cur.p1, other.p0) < 1.5f || Vector3.Distance(cur.p1, other.p1) < 1.5f)
                        {
                            visited.Add(other);
                            queue.Enqueue(other);
                        }
                    }
                }

                components.Add(comp);
            }

            result.Log("Identified {0} distinct connected track circuits/networks", components.Count);
            for (int c = 0; c < components.Count; c++)
            {
                var comp = components[c];
                float avgY = 0f;
                foreach (var r in comp)
