using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public class RailNode
    {
        public Transform tf;
        public string name;
        public Vector3 p0; // start
        public Vector3 p1; // end
        public bool isCurve;
        public List<RailConnection> connections = new List<RailConnection>();
    }

    public class RailConnection
    {
        public RailNode target;
        public bool fromIsP1; // true if connecting from this.p1, false if this.p0
        public bool toIsP1;   // true if connecting to target.p1, false if target.p0
    }

    public void Execute(ExecutionResult result)
    {
        GameObject root = GameObject.Find("Trains");
        var nodes = new List<RailNode>();

        for (int i = 0; i < root.transform.childCount; i++)
        {
            Transform t = root.transform.GetChild(i);
            if (!t.name.Contains("Rail_")) continue;
            bool isCurve = t.name.Contains("Rail_Curve");
            Vector3 p0 = t.position;
            Vector3 p1 = isCurve ? t.TransformPoint(new Vector3(-25f, 0f, -25f)) : t.TransformPoint(new Vector3(-25f, 0f, 0f));
            nodes.Add(new RailNode { tf = t, name = t.name, p0 = p0, p1 = p1, isCurve = isCurve });
        }

        // Build adjacency graph
        float threshold = 1.0f;
        for (int i = 0; i < nodes.Count; i++)
        {
            for (int j = i + 1; j < nodes.Count; j++)
            {
                var a = nodes[i];
                var b = nodes[j];

                if (Vector3.Distance(a.p0, b.p0) < threshold)
                {
                    a.connections.Add(new RailConnection { target = b, fromIsP1 = false, toIsP1 = false });
                    b.connections.Add(new RailConnection { target = a, fromIsP1 = false, toIsP1 = false });
                }
                else if (Vector3.Distance(a.p0, b.p1) < threshold)
                {
                    a.connections.Add(new RailConnection { target = b, fromIsP1 = false, toIsP1 = true });
                    b.connections.Add(new RailConnection { target = a, fromIsP1 = true, toIsP1 = false });
                }
                else if (Vector3.Distance(a.p1, b.p0) < threshold)
                {
                    a.connections.Add(new RailConnection { target = b, fromIsP1 = true, toIsP1 = false });
                    b.connections.Add(new RailConnection { target = a, fromIsP1 = false, toIsP1 = true });
                }
                else if (Vector3.Distance(a.p1, b.p1) < threshold)
                {
                    a.connections.Add(new RailConnection { target = b, fromIsP1 = true, toIsP1 = true });
                    b.connections.Add(new RailConnection { target = a, fromIsP1 = true, toIsP1 = true });
                }
            }
        }

        // Check for each of the 3 trains:
        Vector3[] trainPos = new Vector3[]
        {
            new Vector3(10.66f, 20.99f, -14.99f), // Train 1
            new Vector3(-5.61f, 17.88f, -0.38f),  // Train 2
            new Vector3(-5.50f, -14.83f, 49.55f)  // Train 3
        };

        for (int tIdx = 0; tIdx < trainPos.Length; tIdx++)
        {
            RailNode nearest = null;
            float minDist = float.MaxValue;
            foreach (var n in nodes)
            {
                // Rail is around 4.5m above train
                float d = Vector2.Distance(new Vector2(n.p0.x, n.p0.z), new Vector2(trainPos[tIdx].x, trainPos[tIdx].z));
                float dy = Mathf.Abs(n.p0.y - (trainPos[tIdx].y + 4.4f));
                if (dy < 3f && d < minDist)
                {
                    minDist = d;
                    nearest = n;
                }
            }

            if (nearest == null)
            {
                result.LogWarning("No rail found for Train {0}", tIdx + 1);
                continue;
            }

            // Trace the track component
            HashSet<RailNode> comp = new HashSet<RailNode>();
            Queue<RailNode> q = new Queue<RailNode>();
            q.Enqueue(nearest);
            comp.Add(nearest);
            while (q.Count > 0)
            {
                var cur = q.Dequeue();
                foreach (var conn in cur.connections)
                {
                    if (!comp.Contains(conn.target))
                    {
                        comp.Add(conn.target);
                        q.Enqueue(conn.target);
                    }
                }
            }

            // Find endpoints (degree 1)
            List<RailNode> endpoints = new List<RailNode>();
            foreach (var n in comp)
            {
                if (n.connections.Count == 1) endpoints.Add(n);
            }

            result.Log("Train {0}: Track has {1} rails, endpoints: {2}. Nearest rail: '{3}' (dist={4:F2}m)",
                tIdx + 1, comp.Count, endpoints.Count, nearest.name, minDist);
            foreach (var ep in endpoints)
            {
                result.Log("   Endpoint: '{0}' at p0={1}, p1={2}", ep.name, ep.p0, ep.p1);
            }
        }
    }
}

