using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public class RailNode
    {
        public Transform tf;
        public string name;
        public Vector3 p0; // local (0,0,0) in world
        public Vector3 p1; // local end in world
        public bool isCurve;
        public List<RailConn> conns = new List<RailConn>();
    }

    public class RailConn
    {
        public RailNode other;
        public bool myEndIsP1;
        public bool otherEndIsP1;
    }

    public void Execute(ExecutionResult result)
    {
        GameObject root = GameObject.Find("Trains");
        var nodes = new List<RailNode>();

        for (int i = 0; i < root.transform.childCount; i++)
        {
            Transform t = root.transform.GetChild(i);
            if (!t.name.Contains("Rail_Straight") && !t.name.Contains("Rail_Curve")) continue;
            if (Mathf.Abs(t.position.y - 16.50f) > 1.0f) continue;

            bool isCurve = t.name.Contains("Rail_Curve");
            Vector3 p0 = t.position;
            Vector3 p1 = isCurve ? t.TransformPoint(new Vector3(-25f, 0f, -25f)) : t.TransformPoint(new Vector3(-25f, 0f, 0f));
            nodes.Add(new RailNode { tf = t, name = t.name, p0 = p0, p1 = p1, isCurve = isCurve });
        }

        float threshold = 1.0f;
        for (int i = 0; i < nodes.Count; i++)
        {
            for (int j = i + 1; j < nodes.Count; j++)
            {
                var a = nodes[i];
                var b = nodes[j];
                if (Vector3.Distance(a.p0, b.p0) < threshold)
                {
                    a.conns.Add(new RailConn { other = b, myEndIsP1 = false, otherEndIsP1 = false });
                    b.conns.Add(new RailConn { other = a, myEndIsP1 = false, otherEndIsP1 = false });
                }
                else if (Vector3.Distance(a.p0, b.p1) < threshold)
                {
                    a.conns.Add(new RailConn { other = b, myEndIsP1 = false, otherEndIsP1 = true });
                    b.conns.Add(new RailConn { other = a, myEndIsP1 = true, otherEndIsP1 = false });
                }
                else if (Vector3.Distance(a.p1, b.p0) < threshold)
                {
                    a.conns.Add(new RailConn { other = b, myEndIsP1 = true, otherEndIsP1 = false });
                    b.conns.Add(new RailConn { other = a, myEndIsP1 = false, otherEndIsP1 = true });
                }
                else if (Vector3.Distance(a.p1, b.p1) < threshold)
                {
                    a.conns.Add(new RailConn { other = b, myEndIsP1 = true, otherEndIsP1 = true });
                    b.conns.Add(new RailConn { other = a, myEndIsP1 = true, otherEndIsP1 = true });
                }
            }
        }

        // Find endpoint
        RailNode startNode = null;
        bool startAtP1 = false;
        foreach (var n in nodes)
        {
            if (n.conns.Count == 1)
            {
                startNode = n;
                // If the single connection is at P1, we enter at P0 and exit at P1
                startAtP1 = n.conns[0].myEndIsP1; // if true, connection is at P1, so outer tip is P0
                break;
            }
        }

        // Traverse sequence
        List<Vector3> pathPoints = new List<Vector3>();
        RailNode current = startNode;
        // If connection is at P1, start tip is P0 (enterAtP0 = true)
        bool enterAtP0 = current.conns[0].myEndIsP1;

        HashSet<RailNode> visited = new HashSet<RailNode>();

        while (current != null)
        {
            visited.Add(current);
            // Sample points from entrance to exit
            if (!current.isCurve)
            {
                Vector3 entry = enterAtP0 ? current.p0 : current.p1;
                Vector3 exit = enterAtP0 ? current.p1 : current.p0;
                if (pathPoints.Count == 0) pathPoints.Add(entry);
                pathPoints.Add(exit);
            }
            else
            {
                int steps = 10;
                for (int s = 0; s <= steps; s++)
                {
                    float t = (float)s / steps;
                    if (!enterAtP0) t = 1f - t; // reverse if entering at P1

                    float rad = (Mathf.PI * 0.5f) * (1f + t);
                    Vector3 localPt = new Vector3(25f * Mathf.Cos(rad), 0f, -25f + 25f * Mathf.Sin(rad));
                    Vector3 worldPt = current.tf.TransformPoint(localPt);
                    if (pathPoints.Count == 0 || s > 0)
                        pathPoints.Add(worldPt);
                }
            }

            // Find next node
            RailNode next = null;
            bool nextEnterAtP0 = false;
            foreach (var conn in current.conns)
            {
                if (!visited.Contains(conn.other))
                {
                    next = conn.other;
                    // If conn.otherEndIsP1 is true, connection is at other's P1, so we enter other at P1 (nextEnterAtP0 = false)
                    nextEnterAtP0 = !conn.otherEndIsP1;
                    break;
                }
            }

            current = next;
            enterAtP0 = nextEnterAtP0;
        }

        float totalLen = 0f;
        for (int i = 0; i < pathPoints.Count - 1; i++)
        {
            totalLen += Vector3.Distance(pathPoints[i], pathPoints[i + 1]);
        }

        result.Log("Track 2 ordered path successfully generated! {0} points, Total Length = {1:F2}m",
            pathPoints.Count, totalLen);
        result.Log("Start: {0}, End: {1}", pathPoints[0], pathPoints[pathPoints.Count - 1]);
    }
}

