                if (!current.isCurve)
                {
                    Vector3 entry = enterAtP0 ? current.p0 : current.p1;
                    Vector3 exit = enterAtP0 ? current.p1 : current.p0;
                    if (pathPoints.Count == 0)
                        pathPoints.Add(entry);
                    pathPoints.Add(exit);
                }
                else
