using System.Collections.Generic;
using UnityEngine;

namespace Cyberpunk.Traffic.Trains
{
    /// <summary>
    /// High-precision parametric 3D track path generated from connected rail beam segments.
    /// Provides constant-speed distance evaluation, smooth curvature interpolation, and zero-allocation sampling.
    /// </summary>
    [System.Serializable]
    public class CyberTrainPath
    {
        [SerializeField] private List<Vector3> _waypoints = new List<Vector3>();
        [SerializeField] private List<float> _cumulativeDistances = new List<float>();
        [SerializeField] private float _totalLength = 0f;

        public float TotalLength => _totalLength;
        public int WaypointCount => _waypoints.Count;
        public IReadOnlyList<Vector3> Waypoints => _waypoints;

        public Vector3 StartPoint => _waypoints.Count > 0 ? _waypoints[0] : Vector3.zero;
        public Vector3 EndPoint => _waypoints.Count > 0 ? _waypoints[_waypoints.Count - 1] : Vector3.zero;

        public bool IsValid => _waypoints != null && _waypoints.Count >= 2 && _totalLength > 0.01f;

        /// <summary>
        /// Clears and initializes the path with a list of ordered 3D points.
        /// Precomputes cumulative distances for O(log N) constant-velocity sampling.
        /// </summary>
        public void InitializeFromPoints(List<Vector3> points)
        {
            _waypoints.Clear();
            _cumulativeDistances.Clear();

            if (points == null || points.Count < 2)
            {
                _totalLength = 0f;
                return;
            }

            _waypoints.AddRange(points);
            _cumulativeDistances.Add(0f);
            float accum = 0f;

            for (int i = 1; i < _waypoints.Count; i++)
            {
                float segmentDist = Vector3.Distance(_waypoints[i - 1], _waypoints[i]);
                accum += segmentDist;
                _cumulativeDistances.Add(accum);
            }

            _totalLength = accum;
        }

        /// <summary>
        /// Evaluates the 3D position and forward tangent along the track at a given linear distance.
        /// Guaranteed zero GC allocations.
        /// </summary>
        public Vector3 Evaluate(float distance, out Vector3 forwardTangent)
        {
            if (_waypoints.Count == 0)
            {
                forwardTangent = Vector3.forward;
                return Vector3.zero;
            }

            if (_waypoints.Count == 1)
            {
                forwardTangent = Vector3.forward;
                return _waypoints[0];
            }

            // Clamp distance within track boundaries
            float clampedDist = Mathf.Clamp(distance, 0f, _totalLength);

            // Binary search for the containing segment
            int low = 0;
            int high = _cumulativeDistances.Count - 1;
            while (low <= high)
            {
                int mid = (low + high) >> 1;
                if (_cumulativeDistances[mid] < clampedDist)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }

            int index = Mathf.Clamp(low - 1, 0, _waypoints.Count - 2);
            float segStartDist = _cumulativeDistances[index];
            float segEndDist = _cumulativeDistances[index + 1];
            float segLength = segEndDist - segStartDist;

            float t = segLength > 0.0001f ? (clampedDist - segStartDist) / segLength : 0f;
            t = Mathf.Clamp01(t);

            Vector3 p0 = _waypoints[index];
            Vector3 p1 = _waypoints[index + 1];

            forwardTangent = (p1 - p0).normalized;
            if (forwardTangent.sqrMagnitude < 0.001f) forwardTangent = Vector3.forward;

            return Vector3.Lerp(p0, p1, t);
        }

        /// <summary>
        /// Finds the closest distance along the path to an arbitrary world point.
        /// </summary>
        public float FindClosestDistance(Vector3 worldPoint)
        {
            if (!IsValid) return 0f;

            float closestPathDist = 0f;
            float minSqrDist = float.MaxValue;

            for (int i = 0; i < _waypoints.Count - 1; i++)
            {
                Vector3 p0 = _waypoints[i];
                Vector3 p1 = _waypoints[i + 1];
                Vector3 segment = p1 - p0;
                float segLenSqr = segment.sqrMagnitude;

                float t = segLenSqr > 0.0001f ? Vector3.Dot(worldPoint - p0, segment) / segLenSqr : 0f;
                t = Mathf.Clamp01(t);

                Vector3 proj = p0 + segment * t;
                float sqrDist = (worldPoint - proj).sqrMagnitude;

                if (sqrDist < minSqrDist)
                {
                    minSqrDist = sqrDist;
                    closestPathDist = _cumulativeDistances[i] + Mathf.Sqrt(segLenSqr) * t;
                }
            }

            return closestPathDist;
        }

        /// <summary>
        /// Draws debug gizmos in the Scene view.
        /// </summary>
        public void DrawGizmos(Color pathColor, float sphereSize = 0.8f)
        {
            if (!IsValid) return;

            Gizmos.color = pathColor;
            for (int i = 0; i < _waypoints.Count - 1; i++)
            {
                Gizmos.DrawLine(_waypoints[i], _waypoints[i + 1]);
            }

            // Draw termini
            Gizmos.color = Color.green;
            Gizmos.DrawWireSphere(_waypoints[0], sphereSize);
            Gizmos.color = Color.red;
            Gizmos.DrawWireSphere(_waypoints[_waypoints.Count - 1], sphereSize);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace Cyberpunk.Traffic.Trains
{
    /// <summary>
    /// Utility class for assembling continuous CyberTrainPath spline curves from
    /// scene rail gameobjects (both straight beams and 90-degree curved beams).
    /// </summary>
    public static class CyberTrackBuilder
    {
        private class RailNode
        {
            public Transform tf;
            public string name;
            public Vector3 p0; // world start (local 0,0,0)
            public Vector3 p1; // world end (local -25, 0, 0 or -25, 0, -25)
            public bool isCurve;
            public List<RailConn> connections = new List<RailConn>();
        }

        private class RailConn
        {
            public RailNode other;
            public bool myEndIsP1;
            public bool otherEndIsP1;
        }

        /// <summary>
        /// Builds a continuous CyberTrainPath for all connected rails around a given Y height or seed transform.
        /// </summary>
        public static CyberTrainPath BuildPathFromSeed(Transform seedRail, Transform railsRoot, float curveSubdivisions = 12)
        {
            if (seedRail == null || railsRoot == null) return null;

            List<RailNode> allNodes = ExtractRailNodes(railsRoot);
            RailNode seedNode = allNodes.Find(n => n.tf == seedRail);
            if (seedNode == null) return null;

            BuildAdjacencyGraph(allNodes, 1.5f);

            // Extract connected component containing seed
            HashSet<RailNode> component = new HashSet<RailNode>();
            Queue<RailNode> q = new Queue<RailNode>();
            q.Enqueue(seedNode);
            component.Add(seedNode);

            while (q.Count > 0)
            {
                var cur = q.Dequeue();
                foreach (var conn in cur.connections)
                {
                    if (!component.Contains(conn.other))
                    {
                        component.Add(conn.other);
                        q.Enqueue(conn.other);
                    }
                }
            }

            // Find an endpoint (degree 1 node) to start path from
            RailNode startNode = null;
            foreach (var n in component)
            {
                if (n.connections.Count == 1)
                {
                    startNode = n;
                    break;
                }
            }

            // If it's a closed loop without degree 1, pick seedNode
            if (startNode == null) startNode = seedNode;

            return TraverseAndSample(startNode, component, (int)curveSubdivisions);
        }

        private static List<RailNode> ExtractRailNodes(Transform root)
        {
            List<RailNode> nodes = new List<RailNode>();
            for (int i = 0; i < root.childCount; i++)
            {
                Transform t = root.GetChild(i);
                if (!t.name.Contains("Rail_Straight") && !t.name.Contains("Rail_Curve")) continue;

                bool isCurve = t.name.Contains("Rail_Curve");
                Vector3 p0 = t.position;
                Vector3 p1 = isCurve
                    ? t.TransformPoint(new Vector3(-25f, 0f, -25f))
                    : t.TransformPoint(new Vector3(-25f, 0f, 0f));

                nodes.Add(new RailNode { tf = t, name = t.name, p0 = p0, p1 = p1, isCurve = isCurve });
            }
            return nodes;
        }

        private static void BuildAdjacencyGraph(List<RailNode> nodes, float threshold)
        {
            for (int i = 0; i < nodes.Count; i++)
            {
                for (int j = i + 1; j < nodes.Count; j++)
                {
                    var a = nodes[i];
                    var b = nodes[j];

                    if (Vector3.Distance(a.p0, b.p0) < threshold)
                    {
                        a.connections.Add(new RailConn { other = b, myEndIsP1 = false, otherEndIsP1 = false });
                        b.connections.Add(new RailConn { other = a, myEndIsP1 = false, otherEndIsP1 = false });
                    }
                    else if (Vector3.Distance(a.p0, b.p1) < threshold)
                    {
                        a.connections.Add(new RailConn { other = b, myEndIsP1 = false, otherEndIsP1 = true });
                        b.connections.Add(new RailConn { other = a, myEndIsP1 = true, otherEndIsP1 = false });
                    }
                    else if (Vector3.Distance(a.p1, b.p0) < threshold)
                    {
                        a.connections.Add(new RailConn { other = b, myEndIsP1 = true, otherEndIsP1 = false });
                        b.connections.Add(new RailConn { other = a, myEndIsP1 = false, otherEndIsP1 = true });
                    }
                    else if (Vector3.Distance(a.p1, b.p1) < threshold)
                    {
                        a.connections.Add(new RailConn { other = b, myEndIsP1 = true, otherEndIsP1 = true });
                        b.connections.Add(new RailConn { other = a, myEndIsP1 = true, otherEndIsP1 = true });
                    }
                }
            }
        }

        private static CyberTrainPath TraverseAndSample(RailNode startNode, HashSet<RailNode> component, int curveSteps)
        {
            List<Vector3> sampledPoints = new List<Vector3>();
            HashSet<RailNode> visited = new HashSet<RailNode>();

            RailNode current = startNode;
            // If connection is at P1, the outer terminus end is P0, so we enter at P0
            bool enterAtP0 = current.connections.Count == 0 || current.connections[0].myEndIsP1;

            while (current != null && visited.Count < component.Count)
            {
                visited.Add(current);

                if (!current.isCurve)
                {
                    Vector3 entry = enterAtP0 ? current.p0 : current.p1;
                    Vector3 exit = enterAtP0 ? current.p1 : current.p0;

                    if (sampledPoints.Count == 0) sampledPoints.Add(entry);
                    sampledPoints.Add(exit);
                }
                else
                {
                    // 90-degree circular curve of radius 25
                    for (int s = 0; s <= curveSteps; s++)
                    {
                        float t = (float)s / curveSteps;
                        if (!enterAtP0) t = 1f - t; // Reverse arc parameter if entering at P1

                        float rad = (Mathf.PI * 0.5f) * (1f + t);
                        Vector3 localPt = new Vector3(25f * Mathf.Cos(rad), 0f, -25f + 25f * Mathf.Sin(rad));
                        Vector3 worldPt = current.tf.TransformPoint(localPt);

                        if (sampledPoints.Count == 0 || s > 0)
                        {
                            sampledPoints.Add(worldPt);
                        }
                    }
                }

                // Advance to next node
                RailNode next = null;
                bool nextEnterAtP0 = false;

                foreach (var conn in current.connections)
                {
                    if (!visited.Contains(conn.other) && component.Contains(conn.other))
                    {
                        next = conn.other;
                        // If connection meets other at P1, we enter other at P1 (nextEnterAtP0 = false)
                        nextEnterAtP0 = !conn.otherEndIsP1;
                        break;
                    }
                }

                current = next;
                enterAtP0 = nextEnterAtP0;
            }

            CyberTrainPath path = new CyberTrainPath();
            path.InitializeFromPoints(sampledPoints);
            return path;
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace Cyberpunk.Traffic.Trains
{
    public enum TrainState
    {
        Accelerating,
        Cruising,
        Decelerating,
        Dwelling
    }

    /// <summary>
    /// Articulated multi-carriage monorail train consist simulator.
    /// Manages kinematics, realistic acceleration/braking curves, carriage coupling,
    /// cornering banking, station dwell reversals, directional headlights, and 3D audio.
    /// </summary>
    [DisallowMultipleComponent]
    public class CyberTrainConsist : MonoBehaviour
    {
        [Header("Train Carriages")]
        [Tooltip("The lead cockpit carriage.")]
        public Transform cockpit;

        [Tooltip("First middle passenger carriage.")]
        public Transform middleCar1;

        [Tooltip("Second middle passenger carriage.")]
        public Transform middleCar2;

        [Tooltip("Optional rear cockpit carriage for double-ended bidirectional shuttles.")]
        public Transform rearCockpit;

        [Header("Coupling & Alignment")]
        [Tooltip("Distance between adjacent carriage pivots (meters).")]
        public float carSpacing = 12.75f;

        [Tooltip("Vertical offset from rail beam pivot to train car pivot.")]
        public float verticalOffset = -4.39f;

        [Tooltip("Invert Cockpit forward orientation if model nose points in -Z.")]
        public bool invertCockpitForward = true;

        [Tooltip("Invert Middle cars forward orientation if model forward differs.")]
        public bool invertMiddleForward = false;

        [Tooltip("Subtle banking tilt into high-speed curves.")]
        [Range(0f, 10f)]
        public float maxBankAngle = 3.5f;

        [Header("Kinematics & Speeds")]
        [Tooltip("Top cruising speed in meters/second (~80 km/h).")]
        public float cruiseSpeed = 22.0f;

        [Tooltip("Linear acceleration in m/s².")]
        public float acceleration = 3.5f;

        [Tooltip("Braking deceleration in m/s².")]
        public float deceleration = 4.5f;

        [Tooltip("Station dwell duration in seconds before reversing direction.")]
        public float stationDwellDuration = 5.0f;

        [Tooltip("Safety margin from the physical track ends to keep all cars on rails.")]
        public float terminusBuffer = 28.0f;

        [Header("Audio")]
        public AudioClip engineHumClip;
        [Range(0f, 1f)] public float maxAudioVolume = 0.65f;
        public float audioMinDistance = 5.0f;
        public float audioMaxDistance = 50.0f;

        [Header("Lighting")]
        public bool enableHeadlights = true;
        public Color headlightColor = new Color(0.3f, 0.85f, 1.0f);
        public float headlightIntensity = 3.5f;
        public float headlightRange = 35.0f;

        // Path & Runtime State
        private CyberTrainPath _path;
        private float _currentDistance = 0f;
        private float _currentSpeed = 0f;
        private int _travelDirection = 1; // +1 = forward along path, -1 = reverse
        private TrainState _state = TrainState.Accelerating;
        private float _dwellTimer = 0f;

        private AudioSource _audioSource;
        private Light _headlightFront;
        private Light _headlightRear;

        public float CurrentSpeed => _currentSpeed;
        public TrainState State => _state;
        public int TravelDirection => _travelDirection;
        public CyberTrainPath Path => _path;

        public void Initialize(CyberTrainPath path, float startDistance = 0f, float yOffset = -4.39f)
        {
            _path = path;
            verticalOffset = yOffset;

            if (_path != null && _path.IsValid)
            {
                // Ensure starting distance is clamped within valid bounds
                float minD = terminusBuffer;
                float maxD = Mathf.Max(terminusBuffer + 1f, _path.TotalLength - terminusBuffer);
                _currentDistance = Mathf.Clamp(startDistance, minD, maxD);
            }

            SetupAudio();
            SetupHeadlights();
            UpdateCarriagePositions(true);
        }

        private void SetupAudio()
        {
            if (engineHumClip == null) return;

            Transform audioTarget = cockpit != null ? cockpit : transform;
            _audioSource = audioTarget.GetComponent<AudioSource>();
            if (_audioSource == null)
            {
                _audioSource = audioTarget.gameObject.AddComponent<AudioSource>();
            }

            _audioSource.clip = engineHumClip;
            _audioSource.loop = true;
            _audioSource.spatialBlend = 1.0f; // Full 3D spatialization
            _audioSource.rolloffMode = AudioRolloffMode.Linear;
            _audioSource.minDistance = audioMinDistance;
            _audioSource.maxDistance = audioMaxDistance;
            _audioSource.volume = 0.1f;
            _audioSource.pitch = 0.8f;
            _audioSource.playOnAwake = false;

            if (!_audioSource.isPlaying)
            {
                _audioSource.Play();
            }
        }

        private void SetupHeadlights()
        {
            if (!enableHeadlights) return;

            if (cockpit != null && _headlightFront == null)
            {
                GameObject lightObj = new GameObject("Train_Headlight_Front");
                lightObj.transform.SetParent(cockpit, false);
                lightObj.transform.localPosition = new Vector3(0f, 1.2f, invertCockpitForward ? -5.5f : 5.5f);
                lightObj.transform.localRotation = Quaternion.Euler(10f, invertCockpitForward ? 180f : 0f, 0f);

                _headlightFront = lightObj.AddComponent<Light>();
                _headlightFront.type = LightType.Spot;
                _headlightFront.color = headlightColor;
                _headlightFront.intensity = headlightIntensity;
                _headlightFront.range = headlightRange;
                _headlightFront.spotAngle = 65f;
            }

            Transform rear = rearCockpit != null ? rearCockpit : middleCar2;
            if (rear != null && _headlightRear == null)
            {
                GameObject rearLightObj = new GameObject("Train_Headlight_Rear");
                rearLightObj.transform.SetParent(rear, false);
                rearLightObj.transform.localPosition = new Vector3(0f, 1.2f, invertMiddleForward ? -5.5f : 5.5f);
                rearLightObj.transform.localRotation = Quaternion.Euler(10f, invertMiddleForward ? 180f : 0f, 0f);

                _headlightRear = rearLightObj.AddComponent<Light>();
                _headlightRear.type = LightType.Spot;
                _headlightRear.color = Color.red; // Red taillight
                _headlightRear.intensity = headlightIntensity * 0.6f;
                _headlightRear.range = 15f;
                _headlightRear.spotAngle = 70f;
            }
        }

        private void Update()
        {
            if (_path == null || !_path.IsValid) return;

            float dt = Time.deltaTime;
            if (dt <= 0.00001f) return;

            UpdateKinematics(dt);
            UpdateCarriagePositions(false);
            UpdateAudio();
            UpdateLights();
        }

        private void UpdateKinematics(float dt)
        {
            float minD = terminusBuffer;
            float maxD = Mathf.Max(terminusBuffer + 1f, _path.TotalLength - terminusBuffer);

            switch (_state)
            {
                case TrainState.Dwelling:
                    _currentSpeed = 0f;
                    _dwellTimer += dt;
                    if (_dwellTimer >= stationDwellDuration)
                    {
                        // Reverse direction and start accelerating
                        _travelDirection = -_travelDirection;
                        _state = TrainState.Accelerating;
                        _dwellTimer = 0f;
                    }
                    break;

                case TrainState.Accelerating:
                    _currentSpeed = Mathf.MoveTowards(_currentSpeed, cruiseSpeed, acceleration * dt);
                    if (Mathf.Abs(_currentSpeed - cruiseSpeed) < 0.05f)
                    {
                        _state = TrainState.Cruising;
                    }
                    CheckBrakingDistance(minD, maxD);
                    AdvanceDistance(dt);
                    break;

                case TrainState.Cruising:
                    _currentSpeed = cruiseSpeed;
                    CheckBrakingDistance(minD, maxD);
                    AdvanceDistance(dt);
                    break;

                case TrainState.Decelerating:
                    _currentSpeed = Mathf.MoveTowards(_currentSpeed, 1.0f, deceleration * dt);

                    float distRemaining = _travelDirection > 0 ? (maxD - _currentDistance) : (_currentDistance - minD);
                    if (distRemaining <= 0.5f || _currentSpeed <= 1.2f)
                    {
                        _currentDistance = _travelDirection > 0 ? maxD : minD;
                        _currentSpeed = 0f;
                        _state = TrainState.Dwelling;
                        _dwellTimer = 0f;
                    }
                    else
                    {
                        AdvanceDistance(dt);
                    }
                    break;
            }
        }

        private void CheckBrakingDistance(float minD, float maxD)
        {
            // v^2 = 2 * a * d => stoppingDistance = v^2 / (2 * deceleration)
            float stoppingDist = (_currentSpeed * _currentSpeed) / (2f * Mathf.Max(0.5f, deceleration)) + 2.0f;
            float distToEnd = _travelDirection > 0 ? (maxD - _currentDistance) : (_currentDistance - minD);

            if (distToEnd <= stoppingDist)
            {
                _state = TrainState.Decelerating;
            }
        }

        private void AdvanceDistance(float dt)
        {
            _currentDistance += _currentSpeed * _travelDirection * dt;
        }

        private void UpdateCarriagePositions(bool snap)
        {
            // Lead car (Cockpit) is positioned at _currentDistance
            PositionCarriage(cockpit, _currentDistance, invertCockpitForward);

            // Carriages trail behind lead car based on direction
            float spacing1 = _currentDistance - carSpacing * _travelDirection;
            PositionCarriage(middleCar1, spacing1, invertMiddleForward);

            float spacing2 = _currentDistance - (carSpacing * 2f) * _travelDirection;
            PositionCarriage(middleCar2, spacing2, invertMiddleForward);

            if (rearCockpit != null)
            {
                float spacing3 = _currentDistance - (carSpacing * 3f) * _travelDirection;
                PositionCarriage(rearCockpit, spacing3, !invertCockpitForward);
            }
        }

        private void PositionCarriage(Transform car, float distOnPath, bool invertForward)
        {
            if (car == null) return;

            float clampedD = Mathf.Clamp(distOnPath, 0f, _path.TotalLength);
            Vector3 railPoint = _path.Evaluate(clampedD, out Vector3 tangent);

            // Apply vertical offset so train hangs below (or rides above) rail
            Vector3 targetPos = railPoint + Vector3.up * verticalOffset;
            car.position = targetPos;

            // Compute direction along travel
            Vector3 moveDir = tangent * _travelDirection;
            if (moveDir.sqrMagnitude < 0.001f) moveDir = Vector3.forward;

            // Orient model
            Vector3 lookVector = invertForward ? -moveDir : moveDir;
            Quaternion targetRot = Quaternion.LookRotation(lookVector, Vector3.up);

            // Subtle corner banking
            if (maxBankAngle > 0.1f && _currentSpeed > 2.0f)
            {
                // Measure tangent difference slightly ahead to get curvature
                _path.Evaluate(Mathf.Clamp(clampedD + 4f * _travelDirection, 0f, _path.TotalLength), out Vector3 aheadTangent);
                float turnAngle = Vector3.SignedAngle(tangent, aheadTangent, Vector3.up);
                float bankRoll = Mathf.Clamp(-turnAngle * 0.4f * (_currentSpeed / cruiseSpeed), -maxBankAngle, maxBankAngle);
                targetRot *= Quaternion.Euler(0f, 0f, bankRoll);
            }

            car.rotation = targetRot;
        }

        private void UpdateAudio()
        {
            if (_audioSource == null || !_audioSource.isPlaying) return;

            float speedRatio = Mathf.Clamp01(_currentSpeed / Mathf.Max(1f, cruiseSpeed));
            _audioSource.pitch = Mathf.Lerp(0.75f, 1.25f, speedRatio);
            _audioSource.volume = Mathf.Lerp(0.15f, maxAudioVolume, speedRatio);
        }

        private void UpdateLights()
        {
            if (!enableHeadlights) return;

            // Front headlight shines in travel direction
            if (_headlightFront != null)
            {
                _headlightFront.color = _travelDirection > 0 ? headlightColor : Color.red;
                _headlightFront.intensity = _travelDirection > 0 ? headlightIntensity : headlightIntensity * 0.5f;
            }

            if (_headlightRear != null)
            {
                _headlightRear.color = _travelDirection > 0 ? Color.red : headlightColor;
                _headlightRear.intensity = _travelDirection > 0 ? headlightIntensity * 0.5f : headlightIntensity;
            }
        }

        private void OnDrawGizmosSelected()
        {
            if (_path != null)
            {
                _path.DrawGizmos(new Color(0f, 0.9f, 1f, 0.7f));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Cyberpunk.Traffic.Trains
{
    [Serializable]
    public class TrainConfiguration
    {
        public string lineName = "Sector 7 Express";
        public Transform cockpit;
        public Transform middleCar1;
        public Transform middleCar2;
        public Transform seedRail;
        public float verticalOffset = -4.39f;
        public float cruiseSpeed = 22.0f;
        public float dwellDuration = 5.0f;
        public Color headlightColor = new Color(0.3f, 0.85f, 1.0f);
        [HideInInspector] public CyberTrainConsist consist;
        [HideInInspector] public CyberTrainPath path;
    }

    /// <summary>
    /// Master coordinator for all monorail transit trains in Cyberpunk Demo City.
    /// Manages track spline construction, consist initialization, and runtime scheduling.
    /// </summary>
    [DisallowMultipleComponent]
    public class CyberCityTrainManager : MonoBehaviour
    {
        private static CyberCityTrainManager _instance;
        public static CyberCityTrainManager Instance => _instance;

        [Header("Scene References")]
        [Tooltip("The root 'Trains' GameObject containing all rail pieces.")]
        public Transform railsRoot;

        [Header("Global Audio")]
        [Tooltip("Audio clip for monorail electric motor hum.")]
        public AudioClip trainAudioClip;

        [Header("Train Fleets")]
        public List<TrainConfiguration> trainFleet = new List<TrainConfiguration>();

        [Header("Simulation Settings")]
        [Tooltip("Auto-discover and initialize all trains on scene Start.")]
        public bool autoInitialize = true;

        [Tooltip("Master speed multiplier for all trains in the city.")]
        [Range(0.2f, 2.5f)]
        public float speedMultiplier = 1.0f;

        private void Awake()
        {
            if (_instance != null && _instance != this)
            {
                Destroy(gameObject);
                return;
            }
            _instance = this;
        }

        private void Start()
        {
            if (autoInitialize)
            {
                InitializeAllTrains();
            }
        }

        /// <summary>
        /// Auto-locates the 3 pre-existing trains in Demo_City if not explicitly configured in Inspector.
        /// </summary>
        public void AutoDiscoverTrains()
        {
            if (railsRoot == null)
            {
                GameObject trObj = GameObject.Find("Trains");
                if (trObj != null) railsRoot = trObj.transform;
            }

            if (trainFleet.Count == 0)
            {
                // Train 1: High Eastern Skybridge Line (Underslung, Y = 25.38m)
                Transform c1 = FindTransform("SM_Veh_Train_Cockpit_01 (7)");
                Transform m1_1 = FindTransform("SM_Veh_Train_Middle_01 (9)");
                Transform m1_2 = FindTransform("SM_Veh_Train_Middle_01 (10)");
                Transform seed1 = FindTransform("SM_Bld_Train_Rail_Straight_01 (11)");

                if (c1 != null && seed1 != null)
                {
                    trainFleet.Add(new TrainConfiguration
                    {
                        lineName = "Skyline Line (Upper Skybridge)",
                        cockpit = c1,
                        middleCar1 = m1_1,
                        middleCar2 = m1_2,
                        seedRail = seed1,
                        verticalOffset = -4.39f,
                        cruiseSpeed = 24.0f,
                        dwellDuration = 5.0f,
                        headlightColor = new Color(0.2f, 0.9f, 1.0f) // Cyan
                    });
                }

                // Train 2: Mid Boulevard Central Line (Overslung, Y = 16.50m)
                Transform c2 = FindTransform("SM_Veh_Train_Cockpit_01 (1)");
                Transform m2_1 = FindTransform("SM_Veh_Train_Middle_01 (2)");
                Transform m2_2 = FindTransform("SM_Veh_Train_Middle_01 (3)");
                Transform seed2 = FindTransform("SM_Bld_Train_Rail_Straight_01");

                if (c2 != null && seed2 != null)
                {
                    trainFleet.Add(new TrainConfiguration
                    {
                        lineName = "Boulevard Metro (Mid Level)",
                        cockpit = c2,
                        middleCar1 = m2_1,
                        middleCar2 = m2_2,
                        seedRail = seed2,
                        verticalOffset = 1.38f, // Overslung on rail
                        cruiseSpeed = 20.0f,
                        dwellDuration = 6.0f,
                        headlightColor = new Color(1.0f, 0.75f, 0.2f) // Amber Gold
                    });
                }

                // Train 3: Lower Deck Industrial Line (Underslung, Y = -10.25m)
                Transform c3 = FindTransform("SM_Veh_Train_Cockpit_01");
                Transform m3_1 = FindTransform("SM_Veh_Train_Middle_01");
                Transform m3_2 = FindTransform("SM_Veh_Train_Middle_01 (1)");
                Transform seed3 = FindTransform("SM_Bld_Train_Rail_Straight_01 (3)");

                if (c3 != null && seed3 != null)
                {
                    trainFleet.Add(new TrainConfiguration
                    {
                        lineName = "Lower Canal Express (Lower Deck)",
                        cockpit = c3,
                        middleCar1 = m3_1,
                        middleCar2 = m3_2,
                        seedRail = seed3,
                        verticalOffset = -4.58f,
                        cruiseSpeed = 22.0f,
                        dwellDuration = 5.0f,
                        headlightColor = new Color(0.4f, 1.0f, 0.5f) // Neon Emerald
                    });
                }
            }
        }

        public void InitializeAllTrains()
        {
            if (railsRoot == null)
            {
                AutoDiscoverTrains();
            }

            if (trainFleet.Count == 0)
            {
                AutoDiscoverTrains();
            }

            if (railsRoot == null)
            {
                Debug.LogWarning("[CyberCityTrainManager] Rails root not found in scene!");
                return;
            }

            foreach (var train in trainFleet)
            {
                InitializeTrain(train);
            }

            Debug.Log($"[CyberCityTrainManager] Successfully initialized {trainFleet.Count} monorail trains across the city!");
        }

        private void InitializeTrain(TrainConfiguration config)
        {
            if (config.cockpit == null || config.seedRail == null)
            {
                Debug.LogWarning($"[CyberCityTrainManager] Skipping train '{config.lineName}': missing cockpit or seed rail.");
                return;
            }

            // Build parametric track spline
            config.path = CyberTrackBuilder.BuildPathFromSeed(config.seedRail, railsRoot, 14);
            if (config.path == null || !config.path.IsValid)
            {
                Debug.LogError($"[CyberCityTrainManager] Failed to construct track path for '{config.lineName}'");
                return;
            }

            // Find closest distance on the path to current cockpit position
            float initialDistance = config.path.FindClosestDistance(config.cockpit.position);

            // Attach or get CyberTrainConsist
            CyberTrainConsist consist = config.cockpit.GetComponent<CyberTrainConsist>();
            if (consist == null)
            {
                consist = config.cockpit.gameObject.AddComponent<CyberTrainConsist>();
            }

            consist.cockpit = config.cockpit;
            consist.middleCar1 = config.middleCar1;
            consist.middleCar2 = config.middleCar2;
            consist.cruiseSpeed = config.cruiseSpeed * speedMultiplier;
            consist.stationDwellDuration = config.dwellDuration;
            consist.headlightColor = config.headlightColor;
            consist.engineHumClip = trainAudioClip;
            consist.terminusBuffer = 26.0f;

            // Initialize consist on path with designated vertical offset
            consist.Initialize(config.path, initialDistance, config.verticalOffset);
            config.consist = consist;
        }

        private Transform FindTransform(string name)
        {
            GameObject obj = GameObject.Find(name);
            return obj != null ? obj.transform : null;
        }

        private void OnDrawGizmos()
        {
            if (trainFleet == null) return;
            foreach (var t in trainFleet)
            {
                if (t.path != null)
                {
                    t.path.DrawGizmos(t.headlightColor);
                }
            }
        }
    }
}

