using UnityEngine;
using UnityEditor;
using Cyberpunk.Traffic.Trains;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        GameObject mgrObj = GameObject.Find("[Train_System_Manager]");
        if (mgrObj == null)
        {
            result.LogError("Could not find [Train_System_Manager]");
            return;
        }

        CyberCityTrainManager mgr = mgrObj.GetComponent<CyberCityTrainManager>();
        mgr.InitializeAllTrains();

        foreach (var t in mgr.trainFleet)
        {
            if (t.path != null && t.path.IsValid)
            {
                result.Log("Train '{0}': Path built! Length = {1:F1}m, Waypoints = {2}, Consist distance = {3:F1}m, Speed = {4:F1}m/s",
                    t.lineName, t.path.TotalLength, t.path.WaypointCount,
                    t.consist != null ? t.path.FindClosestDistance(t.consist.cockpit.position) : 0f,
                    t.cruiseSpeed);
            }
            else
            {
                result.LogError("Train '{0}' path failed to build!", t.lineName);
            }
        }
    }
}

