using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var t1 = GameObject.Find("SM_Veh_Train_Cockpit_01 (7)");
        if (t1 == null)
        {
            result.LogError("SM_Veh_Train_Cockpit_01 (7) not found");
            return;
        }

        GameObject camObj = new GameObject("TempTrainCaptureCam");
        Camera cam = camObj.AddComponent<Camera>();
        cam.clearFlags = CameraClearFlags.Skybox;
        cam.nearClipPlane = 0.3f;
        cam.farClipPlane = 500f;

        // Position camera to get a dramatic cinematic 3/4 view of Train 1 on the monorail track
        Vector3 target = t1.transform.position + Vector3.up * 1.5f;
        camObj.transform.position = target + new Vector3(-20f, 8f, -25f);
        camObj.transform.LookAt(target);

        RenderTexture rt = new RenderTexture(1920, 1080, 24, RenderTextureFormat.ARGB32);
        cam.targetTexture = rt;
        cam.Render();

        RenderTexture.active = rt;
        Texture2D tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
        tex.Apply();

        byte[] png = tex.EncodeToPNG();
        string artifactDir = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17";
        string outPath = Path.Combine(artifactDir, "train_system_preview.png");
        File.WriteAllBytes(outPath, png);

        cam.targetTexture = null;
        RenderTexture.active = null;
        Object.DestroyImmediate(rt);
        Object.DestroyImmediate(tex);
        Object.DestroyImmediate(camObj);

        result.Log("Captured train preview successfully saved to {0} ({1} bytes)", outPath, png.Length);
    }
}

