using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using Cyberpunk.Audio;
using Cyberpunk.Traffic.Trains;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // 1. Setup Background Music
        AudioClip bgmClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/448_Checkpoint_Omega.mp3");
        if (bgmClip == null)
        {
            result.LogError("Audio clip not found at Assets/Audio/Music/448_Checkpoint_Omega.mp3");
            return;
        }

        GameObject bgmObj = GameObject.Find("[BGM_Controller]");
        if (bgmObj == null)
        {
            bgmObj = new GameObject("[BGM_Controller]");
            result.RegisterObjectCreation(bgmObj);
        }
        else
        {
            result.RegisterObjectModification(bgmObj);
        }

        CyberBackgroundMusic bgm = bgmObj.GetComponent<CyberBackgroundMusic>();
        if (bgm == null) bgm = bgmObj.AddComponent<CyberBackgroundMusic>();

        bgm.musicClip = bgmClip;
        bgm.volume = 0.45f;
        bgm.fadeInDuration = 2.0f;
        bgm.loop = true;
        bgm.playOnAwake = true;
        bgm.SetupAudioSource();

        result.Log("Configured CyberBackgroundMusic on [BGM_Controller] with '{0}'", bgmClip.name);

        // 2. Setup Train System Manager
        AudioClip humClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Tron_Drone_Sound.mp3");
        if (humClip == null)
        {
            humClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Drones/sci-fi-drone-sound-effect.mp3");
        }

        GameObject trainMgrObj = GameObject.Find("[Train_System_Manager]");
        if (trainMgrObj == null)
        {
            trainMgrObj = new GameObject("[Train_System_Manager]");
            result.RegisterObjectCreation(trainMgrObj);
        }
        else
        {
            result.RegisterObjectModification(trainMgrObj);
        }

        CyberCityTrainManager trainMgr = trainMgrObj.GetComponent<CyberCityTrainManager>();
        if (trainMgr == null) trainMgr = trainMgrObj.AddComponent<CyberCityTrainManager>();

        GameObject railsRoot = GameObject.Find("Trains");
        if (railsRoot != null)
        {
            trainMgr.railsRoot = railsRoot.transform;
        }

        trainMgr.trainAudioClip = humClip;
        trainMgr.autoInitialize = true;
        trainMgr.speedMultiplier = 1.0f;

        trainMgr.trainFleet.Clear();
        trainMgr.AutoDiscoverTrains();

        result.Log("Configured CyberCityTrainManager with {0} train fleets:", trainMgr.trainFleet.Count);
        foreach (var t in trainMgr.trainFleet)
        {
            result.Log(" - Train: '{0}', Cockpit: '{1}', Y-Offset: {2:F2}m, Speed: {3}m/s",
                t.lineName, t.cockpit != null ? t.cockpit.name : "null", t.verticalOffset, t.cruiseSpeed);
        }

        // Test initialize paths
        trainMgr.InitializeAllTrains();

        // 3. Mark dirty and save Demo_City scene
        EditorUtility.SetDirty(bgmObj);
        EditorUtility.SetDirty(trainMgrObj);
        EditorSceneManager.MarkSceneDirty(EditorSceneManager.GetActiveScene());
        EditorSceneManager.SaveOpenScenes();
        AssetDatabase.SaveAssets();

        result.Log("Demo_City scene saved with BGM and Train simulation system!");
    }
}

