using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using SyntyCombined;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.Find("PF_PolygonPlayer");
        if (player == null)
        {
            result.LogError("PF_PolygonPlayer not found");
            return;
        }

        result.RegisterObjectModification(player);

        var loc = player.GetComponent<SyntySwordLocomotionController>();
        if (loc == null)
        {
            result.LogError("SyntySwordLocomotionController not found on PF_PolygonPlayer");
            return;
        }

        // 1. Deactivate or clean up old PolygonSyntyCharacter
        Transform oldModel = player.transform.Find("PolygonSyntyCharacter");
        if (oldModel != null)
        {
            oldModel.gameObject.SetActive(false);
            result.Log("Deactivated old character model '{0}'", oldModel.name);
        }

        // 2. Load Alita Nano Berserker prefab
        GameObject alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab");
        if (alitaPrefab == null)
        {
            result.LogError("Could not find Alita_03_Final_NanoBerserker prefab");
            return;
        }

        // Check if Alita is already instantiated under player
        Transform existingAlita = player.transform.Find("Alita_Character_Mesh");
        GameObject alitaInstance;
