internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.Find("PF_PolygonPlayer");
        if (player == null)
        {
            result.LogError("PF_PolygonPlayer not found");
            return;
        }

        var cc = player.GetComponent<CharacterController>();
        var loc = player.GetComponent<SyntySwordLocomotionController>();
        var anim = loc.animator;

        result.Log("Player pos: {0}", player.transform.position);
        result.Log("CharacterController: height={0}, radius={1}, center={2}, isGrounded={3}, stepOffset={4}, skinWidth={5}",
            cc.height, cc.radius, cc.center, cc.isGrounded, cc.stepOffset, cc.skinWidth);

        if (loc.characterMesh != null)
        {
            result.Log("characterMesh: '{0}', localPos={1}, localScale={2}",
                loc.characterMesh.name, loc.characterMesh.localPosition, loc.characterMesh.localScale);
        }

        if (anim != null)
        {
            result.Log("Animator: isHuman={0}, hasTransformHierarchy={1}",
                anim.isHuman, anim.hasTransformHierarchy);
            if (anim.runtimeAnimatorController != null)
            {
                result.Log("RuntimeAnimatorController: {0}", anim.runtimeAnimatorController.name);
            }
            // Check current state info on layer 0
            var state = anim.GetCurrentAnimatorStateInfo(0);
            result.Log("Layer 0 state hash: {0}, normalizedTime: {1}", state.shortNameHash, state.normalizedTime);
        }

        // Raycast down from player to see ground distance
        if (Physics.Raycast(player.transform.position + Vector3.up * 1f, Vector3.down, out RaycastHit hit, 20f))
        {
            result.Log("Ground hit below player: '{0}' at dist={1:F2}m (hit.point.y = {2:F2})",
                hit.collider.name, hit.distance, hit.point.y);
        }
    }
}

