using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var currentScene = EditorSceneManager.GetActiveScene();
        result.Log("Active scene: {0}", currentScene.path);

        // 1. Detach MainCamera from any parent before cleanup
        var mainCam = Camera.main;
        if (mainCam == null)
        {
            var camGo = GameObject.FindWithTag("MainCamera") ?? GameObject.Find("MainCamera");
            if (camGo != null) mainCam = camGo.GetComponent<Camera>();
        }

        if (mainCam != null)
        {
            mainCam.transform.SetParent(null);
            result.Log("MainCamera unparented to root.");

            // Remove legacy sample camera controllers
            var oldSampleCam = mainCam.GetComponent("SampleCameraController");
            if (oldSampleCam != null) Object.DestroyImmediate(oldSampleCam);
        }

        // 2. Destroy legacy player instances
        var oldPlayer = GameObject.Find("PF_PolygonPlayer");
        if (oldPlayer != null)
        {
            Object.DestroyImmediate(oldPlayer);
            result.Log("Destroyed old PF_PolygonPlayer.");
        }

        var oldHero = GameObject.Find("Alita_BattleAngel_Hero");
        if (oldHero != null)
        {
            Object.DestroyImmediate(oldHero);
            result.Log("Destroyed previous Alita_BattleAngel_Hero.");
        }

        // 3. Instantiate Alita URM Berserker Nano Armor Prefab
        string prefabPath = "Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab";
        GameObject alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
        if (alitaPrefab == null)
        {
            result.LogError("Could not load Alita prefab from {0}", prefabPath);
            return;
        }

        Vector3 spawnPos = new Vector3(12.55f, -17.98f, 57.12f);
        Quaternion spawnRot = Quaternion.Euler(0f, 130f, 0f);

        GameObject hero = Object.Instantiate(alitaPrefab, spawnPos, spawnRot);
        hero.name = "Alita_BattleAngel_Hero";
        hero.tag = "Player";
        hero.layer = 8; // Layer 8 = Player

        foreach (Transform child in hero.GetComponentsInChildren<Transform>(true))
        {
            child.gameObject.layer = 8;
        }

        // 4. CharacterController
        var cc = hero.GetComponent<CharacterController>();
        if (cc == null) cc = hero.AddComponent<CharacterController>();
        cc.center = new Vector3(0f, 0.93f, 0f);
        cc.height = 1.80f;
        cc.radius = 0.35f;
        cc.skinWidth = 0.08f;
        cc.stepOffset = 0.35f;

        // 5. Animator with AC_InsaneGun_Sidekick_Girl
        var girlController = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/InsaneGun_Sword_Set/AC_InsaneGun_Sidekick_Girl.controller");
        var anim = hero.GetComponent<Animator>();
        if (anim == null) anim = hero.GetComponentInChildren<Animator>();
        if (anim == null) anim = hero.AddComponent<Animator>();
        anim.runtimeAnimatorController = girlController;
        anim.applyRootMotion = false;

        // 6. InsaneGunSwordController
        var swordCtrl = hero.GetComponent<InsaneGunSwordController>();
        if (swordCtrl == null) swordCtrl = hero.AddComponent<InsaneGunSwordController>();
        swordCtrl.controlMode = InsaneGunSwordController.ControlMode.PlayerControlled;
        swordCtrl.enemyLayers = 1 << 9; // Target Enemy layer
        swordCtrl.maxHealth = 350f;
        swordCtrl.currentHealth = 350f;
        swordCtrl.attackDamage = 45f;
        swordCtrl.heavyAttackDamage = 95f;
        swordCtrl.walkSpeed = 3.0f;
        swordCtrl.runSpeed = 7.0f;
        swordCtrl.dodgeDistance = 3.2f;
        swordCtrl.enableSlowMotion = true;
        swordCtrl.showCombatHUD = true;

        // 7. Equip Weapons
        Transform rHand = anim.GetBoneTransform(HumanBodyBones.RightHand);
        Transform lHand = anim.GetBoneTransform(HumanBodyBones.LeftHand);
        if (rHand == null) rHand = FindChildRecursive(hero.transform, "hand_r");
        if (lHand == null) lHand = FindChildRecursive(hero.transform, "hand_l");

        swordCtrl.rightHandSocket = rHand;
        swordCtrl.leftHandSocket = lHand;

        // Equip Damascus Blade
        GameObject katana = null;
        string swordPrefabPath = "Assets/PolygonCyberCity/Prefabs/Weapons/SM_Wep_Sword_02.prefab";
        GameObject swordAsset = AssetDatabase.LoadAssetAtPath<GameObject>(swordPrefabPath);
        if (swordAsset != null)
        {
            katana = Object.Instantiate(swordAsset, rHand, false);
            katana.name = "Alita_Damascus_Blade";
            katana.transform.localPosition = new Vector3(0.04f, 0.05f, 0.01f);
            katana.transform.localRotation = Quaternion.Euler(0f, 180f, 90f);
        }

        // Blade tip & TrailRenderer
        if (katana != null)
        {
            var tipGo = new GameObject("Blade_Tip");
            tipGo.transform.SetParent(katana.transform, false);
            tipGo.transform.localPosition = new Vector3(0f, 0.75f, 0f);

            var trail = tipGo.AddComponent<TrailRenderer>();
            AAACyberCombatVFX.ConfigureBladeTrail(trail, true);
            swordCtrl.swordTrail = trail;
            swordCtrl.swordInstance = katana.transform;
            swordCtrl.isSwordDrawn = true;
            swordCtrl.swordHandLocalPos = katana.transform.localPosition;
            swordCtrl.swordHandLocalRot = katana.transform.localEulerAngles;
        }

        // Hip Sheath Socket
        Transform hip = anim.GetBoneTransform(HumanBodyBones.Hips) ?? FindChildRecursive(hero.transform, "pelvis");
        if (hip != null)
        {
            var hsGo = new GameObject("Hip_Sheath_Socket");
            hsGo.transform.SetParent(hip, false);
            hsGo.transform.localPosition = new Vector3(-0.16f, -0.05f, 0.05f);
            hsGo.transform.localRotation = Quaternion.Euler(20f, 10f, 115f);
            swordCtrl.hipSocket = hsGo.transform;
            swordCtrl.swordHipLocalPos = hsGo.transform.localPosition;
            swordCtrl.swordHipLocalRot = hsGo.transform.localEulerAngles;
        }

        // Gun in Left Hand (Sidearm Blaster)
        if (lHand != null)
        {
            string pistolPath = "Assets/PolygonCyberCity/Prefabs/Weapons/SM_Wep_Pistol_01.prefab";
            GameObject pistolAsset = AssetDatabase.LoadAssetAtPath<GameObject>(pistolPath);
            if (pistolAsset != null)
            {
                var pistol = Object.Instantiate(pistolAsset, lHand, false);
                pistol.name = "Sidearm_Blaster";
                pistol.transform.localPosition = new Vector3(-0.02f, 0.06f, 0.01f);
                pistol.transform.localRotation = Quaternion.Euler(0f, -90f, 90f);
            }
        }

        // 8. Ghost Emitter & Ragdoll
        var ghost = hero.GetComponent<HolographicGhostEmitter>();
        if (ghost == null) ghost = hero.AddComponent<HolographicGhostEmitter>();

        var ragdoll = hero.GetComponent<EuphoriaRagdollController>();
        if (ragdoll == null) ragdoll = hero.AddComponent<EuphoriaRagdollController>();
        ragdoll.ragdollForceMultiplier = 1.35f;
        ragdoll.autoRecoverDelay = 2.2f;
        ragdoll.autoRecover = true;
        ragdoll.SetupRagdollBones();

        // 9. Camera setup with SmoothOrbitCamera
        if (mainCam == null)
        {
            var camGo = new GameObject("MainCamera");
            mainCam = camGo.AddComponent<Camera>();
            camGo.AddComponent<AudioListener>();
        }
        mainCam.tag = "MainCamera";
        mainCam.gameObject.SetActive(true);

        var follow = mainCam.GetComponent<SmoothOrbitCamera>();
        if (follow == null) follow = mainCam.AddComponent<SmoothOrbitCamera>();
        follow.target = hero.transform;
        follow.targetOffset = new Vector3(0f, 1.4f, 0f);
        follow.cameraOffset = new Vector3(0f, 0.35f, -3.6f);
        follow.smoothSpeed = 14f;
        follow.mouseSensitivityX = 3.5f;
        follow.mouseSensitivityY = 2.5f;
        follow.minPitch = -25f;
        follow.maxPitch = 65f;

        mainCam.transform.position = hero.transform.position - (hero.transform.forward * 3.6f) + Vector3.up * 1.7f;
        mainCam.transform.rotation = Quaternion.Euler(14f, hero.transform.eulerAngles.y, 0f);

        // 10. Update FadePlaneRespawn
        var fadeRespawn = Object.FindAnyObjectByType<SyntyCombined.FadePlaneRespawn>();
        if (fadeRespawn != null)
        {
            fadeRespawn.fallbackSpawnPosition = spawnPos;
            fadeRespawn.fallbackSpawnYaw = 130f;
            fadeRespawn.useLastSafeGroundedPosition = false;
        }

        // 11. Street Safety Collider
        var oldSafety = GameObject.Find("Street_Plaza_Safety_Collider");
        if (oldSafety != null) Object.DestroyImmediate(oldSafety);

        GameObject safety = new GameObject("Street_Plaza_Safety_Collider");
        safety.transform.position = new Vector3(spawnPos.x, spawnPos.y - 0.15f, spawnPos.z);
        var box = safety.AddComponent<BoxCollider>();
        box.size = new Vector3(60f, 0.15f, 60f);
        box.center = Vector3.zero;

        // Save scene
        EditorSceneManager.MarkSceneDirty(currentScene);
        EditorSceneManager.SaveScene(currentScene);
        result.Log("Alita Battle Angel Hero successfully configured with Insane Gun Sword Combat System!");
    }

    private static Transform FindChildRecursive(Transform parent, string childName)
    {
        foreach (Transform child in parent)
        {
            if (child.name == childName) return child;
            var found = FindChildRecursive(child, childName);
            if (found != null) return found;
        }
        return null;
    }
}

