using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // 1. Fix sunbeams
        var sunbeamMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/FX_Mats/FX_Sunbeam.mat");
        if (sunbeamMat != null)
        {
            for (int i = 1; i <= 7; i++)
            {
                var sb = GameObject.Find($"FX_SunBeam_City_{i}");
                if (sb != null)
                {
                    var psr = sb.GetComponent<ParticleSystemRenderer>();
                    if (psr != null)
                    {
                        psr.sharedMaterial = sunbeamMat;
                        result.Log("Fixed material on FX_SunBeam_City_{0}", i);
                    }
                }
            }
        }

        // 2. Fix Alita eye stripes with blood red war paint material
        var hero = GameObject.Find("Alita_BattleAngel_Hero");
        if (hero != null)
        {
            var stripeMat = new Material(Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard"));
            stripeMat.color = new Color(0.65f, 0.05f, 0.08f, 1f); // Authentic Alita Berserker blood red
            stripeMat.name = "M_Alita_WarStripes_Blood";
            AssetDatabase.CreateAsset(stripeMat, "Assets/Prefabs/Alita_Sidekick/Materials/M_Alita_WarStripes_Blood.mat");

            var stripes = hero.GetComponentsInChildren<MeshRenderer>(true);
            foreach (var r in stripes)
            {
                if (r.name.Contains("Stripe"))
                {
                    r.sharedMaterial = stripeMat;
                    result.Log("Assigned blood war paint to {0}", r.name);
                }
            }

            // Align Scene View camera right behind Alita looking at her and the neon street
            var sv = SceneView.lastActiveSceneView;
            if (sv != null)
            {
                Vector3 lookTarget = hero.transform.position + Vector3.up * 1.3f;
                Vector3 camPos = lookTarget - hero.transform.forward * 3.2f + Vector3.up * 0.45f;
                sv.pivot = lookTarget;
                sv.rotation = hero.transform.rotation * Quaternion.Euler(8f, 0f, 0f);
                sv.size = 2.5f;
                sv.Repaint();
                result.Log("Scene view aligned to Alita!");
            }
        }

        var scene = EditorSceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
    }
}

