using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hero = GameObject.Find("Alita_BattleAngel_Hero");
        if (hero == null)
        {
            result.LogError("Alita_BattleAngel_Hero not found");
            return;
        }

        var mainCam = Camera.main;
        if (mainCam != null)
        {
            mainCam.fieldOfView = 68f;

            var uad = mainCam.GetComponent<UniversalAdditionalCameraData>();
            if (uad == null) uad = mainCam.gameObject.AddComponent<UniversalAdditionalCameraData>();
            uad.renderPostProcessing = true;
            uad.antialiasing = AntialiasingMode.SubpixelMorphologicalAntiAliasing;
            uad.antialiasingQuality = AntialiasingQuality.High;

            var follow = mainCam.GetComponent<SmoothOrbitCamera>();
            if (follow == null) follow = mainCam.gameObject.AddComponent<SmoothOrbitCamera>();
            follow.target = hero.transform;
            follow.targetOffset = new Vector3(0f, 1.45f, 0f);
            follow.cameraOffset = new Vector3(0f, 0.40f, -5.2f);
            follow.minDistance = 2.2f;
            follow.maxDistance = 9.5f;
            follow.zoomSpeed = 3.5f;
            follow.smoothSpeed = 14f;
            follow.mouseSensitivityX = 3.5f;
            follow.mouseSensitivityY = 2.5f;
            follow.minPitch = -30f;
            follow.maxPitch = 70f;
            follow.obstacleLayers = 0; // prevent false close-up clipping on railing/bridge triggers

            // Position camera behind Alita at 5.2m distance
            Vector3 camPos = hero.transform.position - (hero.transform.forward * 5.2f) + Vector3.up * 1.85f;
            mainCam.transform.position = camPos;
            mainCam.transform.rotation = Quaternion.Euler(14f, hero.transform.eulerAngles.y, 0f);

            result.Log("MainCamera updated: FOV=68, distance=5.2m, SMAA=High, zoom enabled!");
        }

        // Set URP Asset MSAA to 4x for crystal clear edges
        var urpAsset = UniversalRenderPipeline.asset;
        if (urpAsset != null)
        {
            SerializedObject so = new SerializedObject(urpAsset);
            var msaaProp = so.FindProperty("m_MSAA");
            if (msaaProp != null)
            {
                msaaProp.intValue = 4; // 4x MSAA
                so.ApplyModifiedProperties();
                result.Log("URP Asset MSAA set to 4x");
            }
        }

        // Save scene
        var scene = EditorSceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        result.Log("Demo_City saved with high-res zoomed-out action camera!");
    }
}

