using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var cam = Camera.main;
        if (cam == null)
        {
            result.LogError("MainCamera not found");
            return;
        }

        int width = 1920;
        int height = 1080;
        RenderTexture rt = new RenderTexture(width, height, 24);
        var prevRT = cam.targetTexture;
        cam.targetTexture = rt;
        cam.Render();

        RenderTexture.active = rt;
        Texture2D tex = new Texture2D(width, height, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, width, height), 0, 0);
        tex.Apply();

        cam.targetTexture = prevRT;
        RenderTexture.active = null;
        Object.DestroyImmediate(rt);

        byte[] bytes = tex.EncodeToPNG();
        Object.DestroyImmediate(tex);

        string artifactPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\alita_action_camera_wide.png";
        File.WriteAllBytes(artifactPath, bytes);
        result.Log("Saved updated wide combat view: {0}", artifactPath);
    }
}

