using System.Reflection;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var gameViewType = typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView");
        if (gameViewType != null)
        {
            var windows = Resources.FindObjectsOfTypeAll(gameViewType);
            result.Log("Found {0} GameView windows", windows.Length);
            foreach (EditorWindow gv in windows)
            {
                var snapZoomProp = gameViewType.GetProperty("snapZoom", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                var zoomAreaField = gameViewType.GetField("m_ZoomArea", BindingFlags.Instance | BindingFlags.NonPublic);
                if (zoomAreaField != null)
                {
                    var zoomArea = zoomAreaField.GetValue(gv);
                    if (zoomArea != null)
                    {
                        var scaleProp = zoomArea.GetType().GetProperty("scale", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                        if (scaleProp != null)
                        {
                            Vector2 currentScale = (Vector2)scaleProp.GetValue(zoomArea);
                            result.Log("Current GameView scale: {0}", currentScale);
                            scaleProp.SetValue(zoomArea, Vector2.one);
                            result.Log("Reset GameView scale to 1.0x!");
                        }
                    }
                }

                // Also check method SnapZoom
                var snapZoomMethod = gameViewType.GetMethod("SnapZoom", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (snapZoomMethod != null)
                {
                    snapZoomMethod.Invoke(gv, new object[] { 1.0f });
                    result.Log("Invoked SnapZoom(1.0f)");
                }

                gv.Repaint();
            }
        }
    }
}

