using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hero = GameObject.Find("Alita_BattleAngel_Hero") ?? GameObject.FindWithTag("Player");
        if (hero == null)
        {
            result.LogError("Hero not found");
            return;
        }

        var swordCtrl = hero.GetComponent<InsaneGunSwordController>();
        if (swordCtrl == null)
        {
            result.LogError("InsaneGunSwordController not found");
            return;
        }

        Transform rHand = hero.transform.Find("root/pelvis/spine_01/spine_02/spine_03/clavicle_r/upperarm_r/lowerarm_r/hand_r");
        if (rHand == null)
        {
            result.LogError("hand_r not found");
            return;
        }

        Transform blade = rHand.Find("Damascus_Blade") ?? rHand.Find("Alita_Damascus_Blade");
        if (blade == null)
        {
            result.LogError("No blade found in hand_r");
            return;
        }

        // Lock in user's exact hand alignment
        blade.localPosition = new Vector3(0.11780f, 0.03410f, -0.00920f);
        blade.localEulerAngles = new Vector3(341.39560f, 99.66290f, 276.94530f);
        blade.localScale = new Vector3(0.95000f, 0.95000f, 0.95000f);

        // Ensure Blade_Tip with TrailRenderer exists
        Transform tip = blade.Find("Blade_Tip");
        if (tip == null)
        {
            var tipGo = new GameObject("Blade_Tip");
            tipGo.transform.SetParent(blade, false);
            tipGo.transform.localPosition = new Vector3(0f, 0.75f, 0f);
            tip = tipGo.transform;
        }

        var trail = tip.GetComponent<TrailRenderer>();
        if (trail == null) trail = tip.gameObject.AddComponent<TrailRenderer>();
        AAACyberCombatVFX.ConfigureBladeTrail(trail, true);

        // Wire into swordCtrl
        swordCtrl.rightHandSocket = rHand;
        swordCtrl.swordInstance = blade;
        swordCtrl.swordTrail = trail;
        swordCtrl.isSwordDrawn = true;
        swordCtrl.swordHandLocalPos = blade.localPosition;
        swordCtrl.swordHandLocalRot = blade.localEulerAngles;

        // Save scene
        var scene = EditorSceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);

        result.Log("Saved user's custom sword grip as default in Demo_City.unity!");
        result.Log("blade.localPosition: {0}", blade.localPosition);
        result.Log("blade.localEulerAngles: {0}", blade.localEulerAngles);
        result.Log("blade.localScale: {0}", blade.localScale);
    }
}

