using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Scene activeScene = SceneManager.GetActiveScene();
        result.Log("Active Scene: {0}", activeScene.name);

        Camera[] cameras = Object.FindObjectsByType<Camera>(FindObjectsSortMode.None);
        foreach (var cam in cameras)
        {
            result.Log("Camera: {0}, pos: {1}", cam.gameObject.name, cam.transform.position);
            var orbit = cam.GetComponent<SmoothOrbitCamera>();
            result.Log(" - SmoothOrbitCamera: {0}", orbit != null ? "Present" : "None");
            var uad = cam.GetComponent<UniversalAdditionalCameraData>();
            if (uad != null)
            {
                result.Log(" - Antialiasing: {0}, PostProcessing: {1}", uad.antialiasing, uad.renderPostProcessing);
            }
        }

        Volume[] volumes = Object.FindObjectsByType<Volume>(FindObjectsSortMode.None);
        foreach (var v in volumes)
        {
            result.Log("Volume: {0}, isGlobal: {1}, profile: {2}", v.gameObject.name, v.isGlobal, v.sharedProfile != null ? v.sharedProfile.name : "null");
            if (v.sharedProfile != null)
            {
                foreach (var comp in v.sharedProfile.components)
                {
                    if (comp != null)
                    {
                        result.Log("   Component: {0}, active: {1}", comp.name, comp.active);
                    }
                }
            }
        }

        var graphicsMaster = Object.FindAnyObjectByType<AAACyberpunkGraphicsMaster>();
        result.Log("AAACyberpunkGraphicsMaster: {0}", graphicsMaster != null ? graphicsMaster.gameObject.name : "None");

        var hero = Object.FindAnyObjectByType<InsaneGunSwordController>();
        if (hero != null)
        {
            result.Log("Hero: {0}, at: {1}", hero.gameObject.name, hero.transform.position);
            var smrs = hero.GetComponentsInChildren<SkinnedMeshRenderer>(true);
            foreach (var smr in smrs)
            {
                result.Log(" - SkinnedMeshRenderer: {0}, skinnedMotionVectors: {1}", smr.gameObject.name, smr.skinnedMotionVectors);
            }
        }
    }
}

