using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var urpAsset = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
        result.Log("Current URP Asset: {0}", urpAsset != null ? urpAsset.name : "null");
        if (urpAsset != null)
        {
            var serializedObj = new SerializedObject(urpAsset);
            var propVolume = serializedObj.FindProperty("m_VolumeProfile");
            if (propVolume != null && propVolume.objectReferenceValue != null)
            {
                result.Log("URP Asset Volume Profile: {0}", propVolume.objectReferenceValue.name);
            }
        }

        var globalSettings = UniversalRenderPipelineGlobalSettings.instance;
        if (globalSettings != null)
        {
            result.Log("URP Global Settings: {0}", globalSettings.name);
        }

        // Check all volume profiles in project that have Motion Blur
        string[] guids = AssetDatabase.FindAssets("t:VolumeProfile");
        foreach (var guid in guids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            var profile = AssetDatabase.LoadAssetAtPath<VolumeProfile>(path);
            if (profile != null && profile.TryGet<MotionBlur>(out var mb))
            {
                result.Log("Profile with MotionBlur: {0} ({1}), active: {2}, mode: {3}, intensity: {4}", 
                    profile.name, path, mb.active, mb.mode.value, mb.intensity.value);
            }
        }
    }
}

