using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh();

        // 1. Update Hero in Scene
        var hero = Object.FindAnyObjectByType<InsaneGunSwordController>();
        if (hero != null)
        {
            var smrs = hero.GetComponentsInChildren<SkinnedMeshRenderer>(true);
            foreach (var smr in smrs)
            {
                result.RegisterObjectModification(smr);
                smr.skinnedMotionVectors = false;
                result.Log("Hero SkinnedMeshRenderer: {0}, skinnedMotionVectors set to: {1}", smr.gameObject.name, smr.skinnedMotionVectors);
            }
        }

        // 2. Update SmoothOrbitCamera
        var orbitCam = Object.FindAnyObjectByType<SmoothOrbitCamera>();
        if (orbitCam != null)
        {
            result.RegisterObjectModification(orbitCam);
            orbitCam.tightPositionFollow = true;
            result.Log("SmoothOrbitCamera tightPositionFollow set to: {0}", orbitCam.tightPositionFollow);
        }

        // 3. Check All Volumes and Profiles
        var urpAsset = GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;
        if (urpAsset != null)
        {
            var serializedObj = new SerializedObject(urpAsset);
            var propVolume = serializedObj.FindProperty("m_VolumeProfile");
            if (propVolume != null && propVolume.objectReferenceValue is VolumeProfile defaultProfile)
            {
                if (defaultProfile.TryGet<MotionBlur>(out var mb))
                {
                    result.RegisterObjectModification(defaultProfile);
                    mb.active = false;
                    mb.intensity.value = 0f;
                    EditorUtility.SetDirty(defaultProfile);
                    result.Log("URP default VolumeProfile MotionBlur disabled: {0}", defaultProfile.name);
                }
            }
        }

        // Mark scene dirty and save
        Scene activeScene = SceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(activeScene);
        EditorSceneManager.SaveScene(activeScene);
        AssetDatabase.SaveAssets();

        result.Log("Demo_City scene & assets successfully saved with zero-motion-blur settings!");
    }
}

