using UnityEditor;
using SyntyCombined;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var respawns = Object.FindObjectsByType<FadePlaneRespawn>(FindObjectsSortMode.None);
        result.Log("Found {0} FadePlaneRespawn instances", respawns.Length);
        foreach (var r in respawns)
        {
            result.Log("FadePlaneRespawn on: {0}, pos: {1}", r.gameObject.name, r.transform.position);
            var colliders = r.GetComponents<Collider>();
            foreach (var c in colliders)
            {
                result.Log(" - Collider: {0}, isTrigger: {1}, bounds: {2}", c.GetType().Name, c.isTrigger, c.bounds);
            }
        }

        // Also check any other death zones / triggers in scene
        var allTriggers = Object.FindObjectsByType<Collider>(FindObjectsSortMode.None);
        var hero = Object.FindAnyObjectByType<InsaneGun.Combat.InsaneGunSwordController>();
        if (hero != null)
        {
            result.Log("Hero position: {0}", hero.transform.position);
            foreach (var col in allTriggers)
            {
                if (col.isTrigger && col.bounds.Contains(hero.transform.position))
                {
                    result.Log("TRIGGER CONTAINING HERO: {0} ({1}), bounds: {2}", col.gameObject.name, col.GetType().Name, col.bounds);
                }
            }
        }
    }
}

