using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using SyntyCombined;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh();

        var fadePlane = GameObject.Find("Fade Plane");
        if (fadePlane != null)
        {
            var boxes = fadePlane.GetComponents<BoxCollider>();
            foreach (var b in boxes)
            {
                result.Log("Destroying rogue BoxCollider on Fade Plane: size={0}", b.size);
                result.DestroyObject(b);
            }
        }

        // Verify triggers containing Hero
        var hero = Object.FindAnyObjectByType<InsaneGun.Combat.InsaneGunSwordController>();
        if (hero != null)
        {
            result.Log("Hero position: {0}", hero.transform.position);
            var allColliders = Object.FindObjectsByType<Collider>(FindObjectsSortMode.None);
            int touchingTriggers = 0;
            foreach (var col in allColliders)
            {
                if (col.isTrigger && col.bounds.Contains(hero.transform.position))
                {
                    touchingTriggers++;
                    result.LogWarning("Trigger still containing hero: {0} ({1})", col.gameObject.name, col.GetType().Name);
                }
            }
            result.Log("Total triggers containing Hero: {0} (Should be 0)", touchingTriggers);
        }

        // Mark scene dirty and save
        Scene activeScene = SceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(activeScene);
        EditorSceneManager.SaveScene(activeScene);
        AssetDatabase.SaveAssets();

        result.Log("Cleaned up Fade Plane colliders and saved Demo_City scene successfully!");
    }
}

