using UnityEngine;
using UnityEditor;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hero = Object.FindAnyObjectByType<InsaneGunSwordController>();
        if (hero == null)
        {
            result.LogError("Hero not found");
            return;
        }

        Vector3 startPos = hero.transform.position;
        var cc = hero.GetComponent<CharacterController>();
        if (cc != null)
        {
            // Simulate moving forward 2 meters
            cc.Move(hero.transform.forward * 2.0f);
            result.Log("Moved hero forward from {0} to {1}", startPos, hero.transform.position);

            // Move back to initial spawn
            cc.Move(-hero.transform.forward * 2.0f);
            result.Log("Moved hero back to {0}", hero.transform.position);
        }
    }
}

