using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] audioGuids = AssetDatabase.FindAssets("t:AudioClip");
        result.Log("Total AudioClips in project: {0}", audioGuids.Length);

        string[] keywords = new string[] { "crowd", "cheer", "applause", "ambient", "club", "arena", "hype", "shout", "fight" };
        var matches = audioGuids.Select(AssetDatabase.GUIDToAssetPath)
            .Where(p => keywords.Any(k => p.ToLower().Contains(k)))
            .ToArray();

        result.Log("Matched audio clips: {0}", matches.Length);
        foreach (var m in matches.Take(25))
        {
            result.Log(" - {0}", m);
        }
    }
}

