using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace InsaneGun.Arena
{
    /// <summary>
    /// Controls a spectator NPC outside the combat arena cage.
    /// Handles randomized cheering/hype animation playback, cycle desynchronization,
    /// dynamic look-at tracking toward the central duelists, and crowd audio chatter.
    /// </summary>
    [RequireComponent(typeof(Animator))]
    public class ArenaSpectatorNPC : MonoBehaviour
    {
        public enum SpectatorCheerType
        {
            DoubleWaveCheer,
            FistPumpCheer,
            SmallWaveCheer,
            AggressiveHype,
            VideoRecording,
            DrinkWatching,
            RailingLean
        }

        [Header("Spectator Persona")]
        public SpectatorCheerType cheerType = SpectatorCheerType.DoubleWaveCheer;
        [Range(0.80f, 1.25f)] public float playbackSpeed = 1.0f;
        public bool lookAtArenaCenter = true;

        [Header("Target Tracking")]
        public Transform fightFocusTarget;

        [Header("Audio Murmurs")]
        public AudioClip[] chatterClips;
        [Range(0.1f, 1.0f)] public float chatterVolume = 0.45f;
        public float minChatterInterval = 8.0f;
        public float maxChatterInterval = 22.0f;

        private Animator _animator;
        private AudioSource _audioSource;
        private Vector3 _lookCenter = Vector3.zero;

        private void Awake()
        {
            _animator = GetComponent<Animator>();
            if (_animator != null)
            {
                // Desynchronize playback speed so crowd doesn't animate like robots
                playbackSpeed = Random.Range(0.88f, 1.18f);
                _animator.speed = playbackSpeed;
            }

            _audioSource = GetComponent<AudioSource>();
            if (_audioSource == null && chatterClips != null && chatterClips.Length > 0)
            {
                _audioSource = gameObject.AddComponent<AudioSource>();
                _audioSource.spatialBlend = 1.0f; // 3D spatial sound
                _audioSource.minDistance = 2.0f;
                _audioSource.maxDistance = 18.0f;
                _audioSource.rolloffMode = AudioRolloffMode.Linear;
                _audioSource.playOnAwake = false;
            }
        }

        private void Start()
        {
            if (_animator != null)
            {
                // Random normalized time start offset so every NPC is at a different point in the loop
                float randomOffset = Random.Range(0.0f, 1.0f);
                _animator.Play(0, 0, randomOffset);
            }

            if (chatterClips != null && chatterClips.Length > 0 && _audioSource != null)
            {
                StartCoroutine(RandomChatterRoutine());
            }
        }

        private void Update()
        {
            if (lookAtArenaCenter)
            {
                Vector3 targetPos = (fightFocusTarget != null) ? fightFocusTarget.position : _lookCenter;
                Vector3 dir = targetPos - transform.position;
                dir.y = 0f;
                if (dir.sqrMagnitude > 0.05f)
                {
                    Quaternion desiredRot = Quaternion.LookRotation(dir);
                    transform.rotation = Quaternion.Slerp(transform.rotation, desiredRot, Time.deltaTime * 3.5f);
                }
            }
        }

        public void SetArenaFocus(Vector3 center, Transform dynamicTarget = null)
        {
            _lookCenter = center;
            fightFocusTarget = dynamicTarget;
        }

        private IEnumerator RandomChatterRoutine()
        {
            // Initial random delay
            yield return new WaitForSeconds(Random.Range(1.5f, 8.0f));

            while (true)
            {
                float wait = Random.Range(minChatterInterval, maxChatterInterval);
                yield return new WaitForSeconds(wait);

                if (_audioSource != null && chatterClips != null && chatterClips.Length > 0)
                {
                    AudioClip clip = chatterClips[Random.Range(0, chatterClips.Length)];
                    if (clip != null && !_audioSource.isPlaying)
                    {
                        _audioSource.pitch = Random.Range(0.92f, 1.08f);
                        _audioSource.PlayOneShot(clip, chatterVolume);
                    }
                }
            }
        }

        /// <summary>
        /// Trigger a burst of excited cheering when a heavy impact / finisher lands in the ring.
        /// </summary>
        public void CheerBurst(float boostDuration = 2.5f)
        {
            if (_animator != null)
            {
                StartCoroutine(CheerBurstRoutine(boostDuration));
            }
        }

        private IEnumerator CheerBurstRoutine(float duration)
        {
            float prevSpeed = _animator.speed;
            _animator.speed = prevSpeed * 1.35f;
            yield return new WaitForSeconds(duration);
            if (_animator != null) _animator.speed = prevSpeed;
        }
    }
}

using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;
using InsaneGun.Testing;
using InsaneGun.Arena;

namespace InsaneGun.EditorTools
{
    public static class CyberpunkIndoorArenaBuilder
    {
        private const string ScenePath = "Assets/Scenes/Cyberpunk_Indoor_Combat_Arena.unity";
        private const string TestArenaPath = "Assets/Scenes/InsaneGun_Combat_TestArena.unity";
        private const string ControllerDir = "Assets/Animations/Spectators";

        [MenuItem("Tools/Cyberpunk/Build Indoor Fight Arena (Closed Building + Cheering Crowd)")]
        public static void BuildIndoorArenaMenu()
        {
            BuildAndSaveScene(ScenePath);
            // Also update the TestArena scene so opening either scene has the new closed arena
            BuildAndSaveScene(TestArenaPath);
        }

        public static void BuildAndSaveScene(string targetScenePath)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = Path.GetFileNameWithoutExtension(targetScenePath);

            EnsureDirectories();
            var spectatorControllers = EnsureSpectatorControllers();

            // 1. Root Architecture: Indoor Closed Building & Lighting
            GameObject buildingRoot = BuildEnclosedBuilding();

            // 2. Central Fight Ring (Octagon/Square Cage Pit with Railings)
            GameObject arenaPit = BuildCombatRing(buildingRoot.transform);

            // 3. Overhead Industrial Truss Rig & Spotlight Lighting
            BuildLightingAndAtmosphere(buildingRoot.transform);

            // 4. Cheering Spectator Crowd outside the arena railings
            GameObject crowdRoot = BuildSpectatorCrowd(buildingRoot.transform, spectatorControllers);

            // 5. Spawn Combatants inside the ring (Alita Player + Rival Duelist)
            var (player, rival) = SpawnCombatants(buildingRoot.transform);

            // 6. Connect Spectators to Combatants
            ConnectSpectatorsToCombat(crowdRoot, rival != null ? rival.transform : null);

            // 7. Setup Smooth Orbit Camera for Indoor Ring
            SetupIndoorCamera(player.transform, buildingRoot.transform);

            // 8. Add Arena Combat Manager & Audio
            SetupArenaManager(player, rival, buildingRoot.transform);

            // 9. Mark and Save Scene
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, targetScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log($"<color=#00FFFF>[CyberpunkArena] Indoor Enclosed Fight Arena successfully built at: {targetScenePath}</color>");
        }

        private static void EnsureDirectories()
        {
            if (!Directory.Exists("Assets/Scenes")) Directory.CreateDirectory("Assets/Scenes");
            if (!Directory.Exists(ControllerDir)) Directory.CreateDirectory(ControllerDir);
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. ENCLOSED BUILDING ARCHITECTURE (WALLS, CEILING, FLOOR)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildEnclosedBuilding()
        {
            GameObject root = new GameObject("Indoor_Arena_Building_Complex");

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            // --- Floor Slab (36m x 36m) ---
            GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            floor.name = "Building_Floor_Ground";
            floor.transform.SetParent(root.transform);
            floor.transform.position = new Vector3(0f, -0.25f, 0f);
            floor.transform.localScale = new Vector3(36f, 0.5f, 36f);

            var floorMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat")
                        ?? AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            if (floorMat != null) floor.GetComponent<Renderer>().sharedMaterial = floorMat;

            // --- Ceiling / Roof (36m x 36m at Y = 11.5m) ---
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ceiling.name = "Industrial_Ceiling_Roof";
            ceiling.transform.SetParent(root.transform);
            ceiling.transform.position = new Vector3(0f, 11.5f, 0f);
            ceiling.transform.localScale = new Vector3(36f, 0.6f, 36f);

            var ceilingMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Ceiling_01.mat")
                          ?? floorMat;
            if (ceilingMat != null) ceiling.GetComponent<Renderer>().sharedMaterial = ceilingMat;

            // --- 4 Enclosing Perimeter Concrete/Steel Walls (Closed Box) ---
            float wallH = 12f;
            float wallThick = 0.8f;
            float halfDist = 18f;

            var wallMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Wall_01.mat")
                       ?? floorMat;

            // North Wall (+Z)
            CreateWall(root.transform, "Wall_North", new Vector3(0f, wallH * 0.5f - 0.25f, halfDist), new Vector3(36f, wallH, wallThick), wallMat);
            // South Wall (-Z)
            CreateWall(root.transform, "Wall_South", new Vector3(0f, wallH * 0.5f - 0.25f, -halfDist), new Vector3(36f, wallH, wallThick), wallMat);
            // East Wall (+X)
            CreateWall(root.transform, "Wall_East", new Vector3(halfDist, wallH * 0.5f - 0.25f, 0f), new Vector3(wallThick, wallH, 36f), wallMat);
            // West Wall (-X)
            CreateWall(root.transform, "Wall_West", new Vector3(-halfDist, wallH * 0.5f - 0.25f, 0f), new Vector3(wallThick, wallH, 36f), wallMat);

            // --- 4 Corner Heavy Structural Steel Columns ---
            Vector3[] colPositions = new Vector3[]
            {
                new Vector3(17f, 5.75f, 17f),
                new Vector3(-17f, 5.75f, 17f),
                new Vector3(17f, 5.75f, -17f),
                new Vector3(-17f, 5.75f, -17f)
            };
            foreach (var cp in colPositions)
            {
                GameObject col = GameObject.CreatePrimitive(PrimitiveType.Cube);
                col.name = "Structural_Pillar";
                col.transform.SetParent(root.transform);
                col.transform.position = cp;
                col.transform.localScale = new Vector3(2.0f, 12f, 2.0f);
                if (wallMat != null) col.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- Ceiling Steel Trusses / Girders ---
            for (int ti = -2; ti <= 2; ti++)
            {
                GameObject truss = GameObject.CreatePrimitive(PrimitiveType.Cube);
                truss.name = $"Overhead_Steel_Truss_{ti}";
                truss.transform.SetParent(root.transform);
                truss.transform.position = new Vector3(ti * 6.5f, 10.8f, 0f);
                truss.transform.localScale = new Vector3(0.6f, 0.9f, 35.5f);
                if (wallMat != null) truss.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- Wall Neon Advertisements / Fight Club Holographic Signs ---
            string holo1 = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_01.prefab";
            string holo2 = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_04.prefab";
            var hPref1 = AssetDatabase.LoadAssetAtPath<GameObject>(holo1);
            var hPref2 = AssetDatabase.LoadAssetAtPath<GameObject>(holo2);

            if (hPref1 != null)
            {
                var hg1 = Object.Instantiate(hPref1, new Vector3(0f, 6.5f, 17.4f), Quaternion.Euler(0f, 180f, 0f), root.transform);
                hg1.name = "Arena_Holo_Sign_North";
                hg1.transform.localScale = new Vector3(2.2f, 2.2f, 2.2f);
            }
            if (hPref2 != null)
            {
                var hg2 = Object.Instantiate(hPref2, new Vector3(0f, 6.5f, -17.4f), Quaternion.Euler(0f, 0f, 0f), root.transform);
                hg2.name = "Arena_Holo_Sign_South";
                hg2.transform.localScale = new Vector3(2.2f, 2.2f, 2.2f);
            }

            return root;
        }

        private static GameObject CreateWall(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject wall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            wall.name = name;
            wall.transform.SetParent(parent);
            wall.transform.position = pos;
            wall.transform.localScale = scale;
            if (mat != null) wall.GetComponent<Renderer>().sharedMaterial = mat;
            return wall;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. CENTRAL FIGHT RING (16m x 16m CAGE PIT & MEZZANINE)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildCombatRing(Transform parent)
        {
            GameObject ringRoot = new GameObject("Central_Combat_Ring");
            ringRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            // Raised Mezzanine Walkway around the arena (outer 28m x 28m with center 16m hollow cutout)
            // Left platform (-X)
            CreatePlatform(ringRoot.transform, "Mezzanine_West", new Vector3(-11f, 0.30f, 0f), new Vector3(6f, 0.60f, 28f));
            // Right platform (+X)
            CreatePlatform(ringRoot.transform, "Mezzanine_East", new Vector3(11f, 0.30f, 0f), new Vector3(6f, 0.60f, 28f));
            // North platform (+Z)
            CreatePlatform(ringRoot.transform, "Mezzanine_North", new Vector3(0f, 0.30f, 11f), new Vector3(16f, 0.60f, 6f));
            // South platform (-Z)
            CreatePlatform(ringRoot.transform, "Mezzanine_South", new Vector3(0f, 0.30f, -11f), new Vector3(16f, 0.60f, 6f));

            // Central Ring Duel Decals (Emissive Neon Combat Circle)
            GameObject outerCircle = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            outerCircle.name = "Ring_Neon_OuterCircle";
            outerCircle.transform.SetParent(ringRoot.transform);
            outerCircle.transform.position = new Vector3(0f, 0.005f, 0f);
            outerCircle.transform.localScale = new Vector3(14f, 0.005f, 14f);
            Object.DestroyImmediate(outerCircle.GetComponent<Collider>());

            var outerMat = new Material(litShader);
            outerMat.color = new Color(0.04f, 0.12f, 0.22f, 0.85f);
            outerMat.EnableKeyword("_EMISSION");
            outerMat.SetColor("_EmissionColor", new Color(0f, 0.90f, 1f) * 2.2f);
            outerCircle.GetComponent<Renderer>().sharedMaterial = outerMat;

            GameObject innerCircle = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            innerCircle.name = "Ring_Neon_InnerCircle";
            innerCircle.transform.SetParent(ringRoot.transform);
            innerCircle.transform.position = new Vector3(0f, 0.008f, 0f);
            innerCircle.transform.localScale = new Vector3(7.0f, 0.005f, 7.0f);
            Object.DestroyImmediate(innerCircle.GetComponent<Collider>());

            var innerMat = new Material(litShader);
            innerMat.color = new Color(0.22f, 0.02f, 0.16f, 0.85f);
            innerMat.EnableKeyword("_EMISSION");
            innerMat.SetColor("_EmissionColor", new Color(1f, 0.12f, 0.70f) * 2.2f);
            innerCircle.GetComponent<Renderer>().sharedMaterial = innerMat;

            // 4 Corner Arena Turnbuckle Posts with Warning Beacons
            Vector3[] corners = new Vector3[]
            {
                new Vector3(8.0f, 0f, 8.0f),
                new Vector3(-8.0f, 0f, 8.0f),
                new Vector3(8.0f, 0f, -8.0f),
                new Vector3(-8.0f, 0f, -8.0f)
            };

            for (int i = 0; i < corners.Length; i++)
            {
                GameObject post = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                post.name = $"Ring_Corner_Post_{i + 1}";
                post.transform.SetParent(ringRoot.transform);
                post.transform.position = corners[i] + Vector3.up * 1.5f;
                post.transform.localScale = new Vector3(0.40f, 1.5f, 0.40f);

                var postMat = new Material(litShader);
                postMat.color = Color.black;
                postMat.EnableKeyword("_EMISSION");
                postMat.SetColor("_EmissionColor", (i % 2 == 0) ? new Color(0f, 0.95f, 1f) * 3.5f : new Color(1f, 0.15f, 0.85f) * 3.5f);
                post.GetComponent<Renderer>().sharedMaterial = postMat;

                // Flashing beacon light on top of post
                var beaconLightGo = new GameObject($"Corner_Beacon_Light_{i + 1}");
                beaconLightGo.transform.SetParent(post.transform);
                beaconLightGo.transform.position = corners[i] + Vector3.up * 3.1f;
                var bLight = beaconLightGo.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = (i % 2 == 0) ? new Color(0f, 0.95f, 1f) : new Color(1f, 0.15f, 0.85f);
                bLight.intensity = 2.2f;
                bLight.range = 8.0f;
            }

            // Security Railings along the 4 edges of the Mezzanine (separating crowd from fighters)
            string railPrefabPath = "Assets/PolygonCyberCity/Prefabs/Buildings/SM_Bld_Railing_Straight_01.prefab";
            var railPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(railPrefabPath);

            float ringHalf = 8.0f;
            // North edge (+Z)
            BuildRailingEdge(ringRoot.transform, railPrefab, new Vector3(-ringHalf, 0.60f, ringHalf), new Vector3(ringHalf, 0.60f, ringHalf), 180f);
            // South edge (-Z)
            BuildRailingEdge(ringRoot.transform, railPrefab, new Vector3(-ringHalf, 0.60f, -ringHalf), new Vector3(ringHalf, 0.60f, -ringHalf), 0f);
            // East edge (+X)
            BuildRailingEdge(ringRoot.transform, railPrefab, new Vector3(ringHalf, 0.60f, -ringHalf), new Vector3(ringHalf, 0.60f, ringHalf), 270f);
            // West edge (-X) (with an opening for fighter entrance)
            BuildRailingEdge(ringRoot.transform, railPrefab, new Vector3(-ringHalf, 0.60f, -ringHalf), new Vector3(-ringHalf, 0.60f, -2.5f), 90f);
            BuildRailingEdge(ringRoot.transform, railPrefab, new Vector3(-ringHalf, 0.60f, 2.5f), new Vector3(-ringHalf, 0.60f, ringHalf), 90f);

            return ringRoot;
        }

        private static GameObject CreatePlatform(Transform parent, string name, Vector3 pos, Vector3 scale)
        {
            GameObject plat = GameObject.CreatePrimitive(PrimitiveType.Cube);
            plat.name = name;
            plat.transform.SetParent(parent);
            plat.transform.position = pos;
            plat.transform.localScale = scale;
            var platMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            if (platMat != null) plat.GetComponent<Renderer>().sharedMaterial = platMat;
            return plat;
        }

        private static void BuildRailingEdge(Transform parent, GameObject railPrefab, Vector3 start, Vector3 end, float yRot)
        {
            if (railPrefab == null) return;
            float dist = Vector3.Distance(start, end);
            Vector3 dir = (end - start).normalized;
            float step = 2.4f;
            int count = Mathf.Max(1, Mathf.RoundToInt(dist / step));

            for (int i = 0; i < count; i++)
            {
                Vector3 p = start + dir * (i * step + step * 0.5f);
                var r = Object.Instantiate(railPrefab, p, Quaternion.Euler(0f, yRot, 0f), parent);
                r.name = "Arena_Safety_Railing";
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. LIGHTING & ENCLOSED ATMOSPHERE
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildLightingAndAtmosphere(Transform parent)
        {
            GameObject lightRoot = new GameObject("Arena_Lighting_Rig");
            lightRoot.transform.SetParent(parent);

            // Ambient fill (dim industrial underground mood)
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.04f, 0.06f, 0.10f);

            // 4 High-Intensity Stadium Downward Spotlights focused on Center Ring
            Vector3[] spotPositions = new Vector3[]
            {
                new Vector3(6.5f, 9.8f, 6.5f),
                new Vector3(-6.5f, 9.8f, 6.5f),
                new Vector3(6.5f, 9.8f, -6.5f),
                new Vector3(-6.5f, 9.8f, -6.5f)
            };

            for (int i = 0; i < spotPositions.Length; i++)
            {
                var spotGo = new GameObject($"Center_Ring_Stadium_Spot_{i + 1}");
                spotGo.transform.SetParent(lightRoot.transform);
                spotGo.transform.position = spotPositions[i];
                spotGo.transform.LookAt(Vector3.zero + Vector3.up * 0.5f);

                var spot = spotGo.AddComponent<Light>();
                spot.type = LightType.Spot;
                spot.color = (i % 2 == 0) ? new Color(0.92f, 0.96f, 1.0f) : new Color(0.15f, 0.85f, 1.0f);
                spot.intensity = 18.0f;
                spot.range = 22.0f;
                spot.spotAngle = 62.0f;
                spot.innerSpotAngle = 38.0f;
                spot.shadows = LightShadows.Soft;
            }

            // Overhead Hanging Centerpiece Hologram Dragon
            string dragonPath = "Assets/PolygonCyberCity/Prefabs/FX/Hologram_Dragon_01.prefab";
            var dragonPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(dragonPath);
            if (dragonPrefab != null)
            {
                var dragon = Object.Instantiate(dragonPrefab, new Vector3(0f, 7.8f, 0f), Quaternion.Euler(0f, 40f, 0f), lightRoot.transform);
                dragon.name = "Overhead_Holo_Dragon";
                dragon.transform.localScale = new Vector3(1.15f, 1.15f, 1.15f);
            }

            // Central Soft Warm Flood (Ensures characters are beautifully lit)
            var centerFillGo = new GameObject("Center_Arena_FillLight");
            centerFillGo.transform.SetParent(lightRoot.transform);
            centerFillGo.transform.position = new Vector3(0f, 8.5f, 0f);
            var centerFill = centerFillGo.AddComponent<Light>();
            centerFill.type = LightType.Point;
            centerFill.color = new Color(0.85f, 0.92f, 1.0f);
            centerFill.intensity = 4.5f;
            centerFill.range = 24.0f;
            centerFill.shadows = LightShadows.None;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 4. CHEERING SPECTATOR CROWD (OUTSIDE ARENA RAILING)
        // ─────────────────────────────────────────────────────────────────────
        private static Dictionary<ArenaSpectatorNPC.SpectatorCheerType, RuntimeAnimatorController[]> EnsureSpectatorControllers()
        {
            var dict = new Dictionary<ArenaSpectatorNPC.SpectatorCheerType, RuntimeAnimatorController[]>();

            var cheerDefs = new (ArenaSpectatorNPC.SpectatorCheerType type, string femnFbx, string mascFbx)[]
            {
                (
                    ArenaSpectatorNPC.SpectatorCheerType.DoubleWaveCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Double_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Double_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.FistPumpCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Large_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Large_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.SmallWaveCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Small_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Small_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.AggressiveHype,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Posture/Stances/A_POLY_IDL_Posture_Aggressive_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Posture/Stances/A_POLY_IDL_Posture_Aggressive_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.DrinkWatching,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Drink/Stances/A_POLY_IDL_Drink_Hold_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Drink/Stances/A_POLY_IDL_Drink_Hold_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.RailingLean,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Lean/Stances/ArmsFolded/A_POLY_IDL_Lean_B_ArmsFolded_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Lean/Stances/ArmsFolded/A_POLY_IDL_Lean_B_ArmsFolded_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.VideoRecording,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/UsePhone/Stances/Video/A_POLY_IDL_UsePhone_OneHand_Video_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/UsePhone/Stances/Video/A_POLY_IDL_UsePhone_OneHand_Video_Loop_Masc.fbx"
                )
            };

            foreach (var def in cheerDefs)
            {
                string femnPath = $"{ControllerDir}/AC_Spectator_{def.type}_Femn.controller";
                string mascPath = $"{ControllerDir}/AC_Spectator_{def.type}_Masc.controller";

                var femnCtrl = BuildSingleClipController(femnPath, def.femnFbx);
                var mascCtrl = BuildSingleClipController(mascPath, def.mascFbx);

                dict[def.type] = new RuntimeAnimatorController[] { femnCtrl, mascCtrl };
            }

            return dict;
        }

        private static RuntimeAnimatorController BuildSingleClipController(string controllerPath, string fbxPath)
        {
            var existing = AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);
            if (existing != null) return existing;

            var ctrl = AnimatorController.CreateAnimatorControllerAtPath(controllerPath);
            var clip = LoadClipFromFbx(fbxPath);
            if (clip != null)
            {
                var state = ctrl.layers[0].stateMachine.AddState("CheeringLoop");
                state.motion = clip;
                ctrl.layers[0].stateMachine.defaultState = state;
            }
            return ctrl;
        }

        private static AnimationClip LoadClipFromFbx(string fbxPath)
        {
            var assets = AssetDatabase.LoadAllAssetsAtPath(fbxPath);
            if (assets == null) return null;
            foreach (var a in assets)
            {
                if (a is AnimationClip c && !c.name.StartsWith("__preview__")) return c;
            }
            return null;
        }

        private static GameObject BuildSpectatorCrowd(Transform parent, Dictionary<ArenaSpectatorNPC.SpectatorCheerType, RuntimeAnimatorController[]> controllers)
        {
            GameObject crowdRoot = new GameObject("Spectator_Crowd_Outside_Arena");
            crowdRoot.transform.SetParent(parent);

            string[] characterPrefabs = new string[]
            {
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Mercenary_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Mercenary_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Cyborg_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Cyborg_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Female_Soldier_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Male_Soldier_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Street_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Robot_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Robot_Mercenary_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Fancy_Bot_01.prefab"
            };

            AudioClip[] chatterClips = new AudioClip[]
            {
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_01.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_02.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_03.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_merc_grunt_01.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_merc_grunt_02.wav")
            };

            var cheerTypes = new ArenaSpectatorNPC.SpectatorCheerType[]
            {
                ArenaSpectatorNPC.SpectatorCheerType.DoubleWaveCheer,
                ArenaSpectatorNPC.SpectatorCheerType.FistPumpCheer,
                ArenaSpectatorNPC.SpectatorCheerType.SmallWaveCheer,
                ArenaSpectatorNPC.SpectatorCheerType.AggressiveHype,
                ArenaSpectatorNPC.SpectatorCheerType.VideoRecording,
                ArenaSpectatorNPC.SpectatorCheerType.DrinkWatching,
                ArenaSpectatorNPC.SpectatorCheerType.RailingLean
            };

            float standY = 0.60f; // On the mezzanine walkway
            float railOffset = 9.15f; // Standing just outside the 8.0m railing

            // Generate crowd positions along the 4 sides of the arena ring
            List<(Vector3 pos, float yaw)> crowdSpots = new List<(Vector3, float)>();

            // North Side (looking South: yaw = 180)
            for (float x = -7.0f; x <= 7.0f; x += 1.8f) crowdSpots.Add((new Vector3(x, standY, railOffset), 180f));

            // South Side (looking North: yaw = 0)
            for (float x = -7.0f; x <= 7.0f; x += 1.8f) crowdSpots.Add((new Vector3(x, standY, -railOffset), 0f));

            // East Side (looking West: yaw = 270)
            for (float z = -6.5f; z <= 6.5f; z += 1.9f) crowdSpots.Add((new Vector3(railOffset, standY, z), 270f));

            // West Side (looking East: yaw = 90) (skipping the entrance gate at Z = [-2, 2])
            for (float z = -6.5f; z <= -3.0f; z += 1.8f) crowdSpots.Add((new Vector3(-railOffset, standY, z), 90f));
            for (float z = 3.0f; z <= 6.5f; z += 1.8f) crowdSpots.Add((new Vector3(-railOffset, standY, z), 90f));

            int spotIdx = 0;
            foreach (var spot in crowdSpots)
            {
                string prefabPath = characterPrefabs[spotIdx % characterPrefabs.Length];
                var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
                if (prefab == null) continue;

                var npc = Object.Instantiate(prefab, spot.pos, Quaternion.Euler(0f, spot.yaw, 0f), crowdRoot.transform);
                npc.name = $"Spectator_{spotIdx + 1:D2}_{prefab.name}";

                // Ensure NPC doesn't have fighting controllers
                var insaneCtrl = npc.GetComponent<InsaneGunSwordController>();
                if (insaneCtrl != null) Object.DestroyImmediate(insaneCtrl);
                var charCtrl = npc.GetComponent<CharacterController>();
                if (charCtrl != null) charCtrl.enabled = false;

                // Pick cheer persona
                var cheer = cheerTypes[spotIdx % cheerTypes.Length];
                bool isFemn = prefab.name.ToLower().Contains("female");

                var anim = npc.GetComponent<Animator>();
                if (anim == null) anim = npc.AddComponent<Animator>();

                if (controllers.TryGetValue(cheer, out var pair) && pair.Length >= 2)
                {
                    anim.runtimeAnimatorController = isFemn ? pair[0] : pair[1];
                }

                // Add Spectator NPC Component
                var specComp = npc.AddComponent<ArenaSpectatorNPC>();
                specComp.cheerType = cheer;
                specComp.chatterClips = chatterClips;
                specComp.lookAtArenaCenter = true;

                spotIdx++;
            }

            return crowdRoot;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 5. SPAWN COMBATANTS (ALITA HERO + RIVAL COMBATANT)
        // ─────────────────────────────────────────────────────────────────────
        private static (InsaneGunSwordController player, InsaneGunSwordController rival) SpawnCombatants(Transform parent)
        {
            // Spawn Alita Battle Angel Player
            string alitaPath = "Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab";
            var alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(alitaPath);
            GameObject alitaGo = null;

            if (alitaPrefab != null)
            {
                alitaGo = Object.Instantiate(alitaPrefab, new Vector3(0f, 0.05f, -3.5f), Quaternion.Euler(0f, 0f, 0f), parent);
                alitaGo.name = "Alita_BattleAngel_Hero";
                alitaGo.tag = "Player";
                alitaGo.layer = LayerMask.NameToLayer("Player");
            }
            else
            {
                alitaGo = new GameObject("Alita_BattleAngel_Hero");
                alitaGo.transform.position = new Vector3(0f, 0.05f, -3.5f);
            }

            var playerCtrl = alitaGo.GetComponent<InsaneGunSwordController>();
            if (playerCtrl == null) playerCtrl = alitaGo.AddComponent<InsaneGunSwordController>();
            playerCtrl.controlMode = InsaneGunSwordController.ControlMode.PlayerControlled;
            playerCtrl.maxHealth = 300f;
            playerCtrl.currentHealth = 300f;

            // Spawn Rival Combatant Duelist inside the ring
            string boyPrefabPath = "Assets/Synty/SidekickCharacters/Prefabs/Characters/SM_Chr_Sidekick_Male_Boy_01.prefab";
            var boyPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(boyPrefabPath);
            GameObject rivalGo = null;

            if (boyPrefab != null)
            {
                rivalGo = Object.Instantiate(boyPrefab, new Vector3(0f, 0.05f, 3.5f), Quaternion.Euler(0f, 180f, 0f), parent);
                rivalGo.name = "Rival_Arena_Duelist";
                rivalGo.tag = "Enemy";
                rivalGo.layer = LayerMask.NameToLayer("Enemy");

                var rivalCtrl = rivalGo.GetComponent<InsaneGunSwordController>();
                if (rivalCtrl == null) rivalCtrl = rivalGo.AddComponent<InsaneGunSwordController>();
                rivalCtrl.controlMode = InsaneGunSwordController.ControlMode.AICirclingEnemy;
                rivalCtrl.maxHealth = 280f;
                rivalCtrl.currentHealth = 280f;

                // Load combat controller for rival
                string animCtrlPath = "Assets/InsaneGun_Sword_Set/Animation/Controller/AC_InsaneGun_Sidekick_Boy.controller";
                var anim = rivalGo.GetComponent<Animator>();
                if (anim != null) anim.runtimeAnimatorController = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(animCtrlPath);

                return (playerCtrl, rivalCtrl);
            }

            return (playerCtrl, null);
        }

        private static void ConnectSpectatorsToCombat(GameObject crowdRoot, Transform rival)
        {
            if (crowdRoot == null) return;
            var spectators = crowdRoot.GetComponentsInChildren<ArenaSpectatorNPC>();
            foreach (var s in spectators)
            {
                s.SetArenaFocus(Vector3.zero, rival);
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 6. INDOOR ORBIT CAMERA SETUP
        // ─────────────────────────────────────────────────────────────────────
        private static void SetupIndoorCamera(Transform playerTarget, Transform parent)
        {
            Camera mainCam = Camera.main;
            if (mainCam == null)
            {
                var camGo = new GameObject("MainCamera");
                mainCam = camGo.AddComponent<Camera>();
                camGo.tag = "MainCamera";
                camGo.transform.SetParent(parent);
            }

            mainCam.transform.position = new Vector3(0f, 2.2f, -8.2f);
            mainCam.transform.LookAt(playerTarget.position + Vector3.up * 1.45f);

            var orbit = mainCam.GetComponent<SmoothOrbitCamera>();
            if (orbit == null) orbit = mainCam.gameObject.AddComponent<SmoothOrbitCamera>();
            orbit.target = playerTarget;
            orbit.tightPositionFollow = true; // Zero lag / zero motion smearing
            orbit.targetOffset = new Vector3(0f, 1.45f, 0f);
            orbit.cameraOffset = new Vector3(0f, 0.35f, -4.5f);
            orbit.minDistance = 2.2f;
            orbit.maxDistance = 7.5f;

            var uad = mainCam.GetComponent<UniversalAdditionalCameraData>();
            if (uad == null) uad = mainCam.gameObject.AddComponent<UniversalAdditionalCameraData>();
            uad.renderPostProcessing = true;
            uad.antialiasing = AntialiasingMode.None;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 7. ARENA COMBAT MANAGER & BGM AUDIO
        // ─────────────────────────────────────────────────────────────────────
        private static void SetupArenaManager(InsaneGunSwordController player, InsaneGunSwordController rival, Transform parent)
        {
            var mgrGo = new GameObject("Arena_Combat_Manager");
            mgrGo.transform.SetParent(parent);

            var testMgr = mgrGo.AddComponent<InsaneGunCombatTestManager>();
            testMgr.player = player;
            testMgr.enemy = rival;
            testMgr.enemySpawnPos = new Vector3(0f, 0.05f, 3.5f);
            testMgr.enemySpawnRot = Quaternion.Euler(0f, 180f, 0f);

            // Background Industrial Cyberpunk Combat Music
            var bgmClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Cyberpunk_Combat_Metal_Heart.mp3")
                       ?? AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/paulyudin-intense-intense-music-574004.mp3");
            if (bgmClip != null)
            {
                var audio = mgrGo.AddComponent<AudioSource>();
                audio.clip = bgmClip;
                audio.volume = 0.55f;
                audio.loop = true;
                audio.playOnAwake = true;
                audio.Play();
            }
        }
    }
}

