using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;
using InsaneGun.Testing;
using InsaneGun.Arena;

namespace InsaneGun.EditorTools
{
    /// <summary>
    /// Builds a massive indoor cyberpunk fight colosseum / stadium.
    /// Features:
    /// - 34m x 34m spacious central combat pit.
    /// - 4-Tier stepped stadium bleachers (stairs-like platforms) surrounding all 4 sides.
    /// - 70+ diverse Cyberpunk spectator NPCs placed across the bleacher tiers.
    /// - Authentic looping cheering, fist-pumping, hyping, phone-recording, and drink-holding animations.
    /// - Immediate Edit-Mode animation pose sampling (no T-poses!).
    /// - Enclosed industrial roof with steel trusses, overhead catwalks, and hanging stadium floodlight rigs.
    /// - Sleek neon combat ring (thin cyber border decals, corner turnbuckle posts with rotating beacons).
    /// </summary>
    public static class CyberpunkIndoorArenaBuilder
    {
        private const string ScenePath = "Assets/Scenes/Cyberpunk_Indoor_Combat_Arena.unity";
        private const string TestArenaPath = "Assets/Scenes/InsaneGun_Combat_TestArena.unity";
        private const string ControllerDir = "Assets/Animations/Spectators";

        [MenuItem("Tools/Cyberpunk/Build Indoor Fight Arena (Closed Building + Cheering Crowd)")]
        public static void BuildIndoorArenaMenu()
        {
            BuildAndSaveScene(ScenePath);
            BuildAndSaveScene(TestArenaPath);
        }

        public static void BuildAndSaveScene(string targetScenePath)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = Path.GetFileNameWithoutExtension(targetScenePath);

            EnsureDirectories();
            var spectatorControllers = EnsureSpectatorControllers();

            // 1. Root Complex & Building Enclosure (68m x 68m x 20m high)
            GameObject buildingRoot = BuildEnclosedBuilding();

            // 2. Central Combat Ring (34m x 34m pit with subtle neon decals & corner turnbuckles)
            GameObject arenaPit = BuildCombatRing(buildingRoot.transform);

            // 3. 4-Tier Stepped Stadium Bleachers (Stairs-like platforms on North, South, East, West)
            GameObject bleachersRoot = BuildSteppedBleachers(buildingRoot.transform);

            // 4. Overhead Industrial Lighting & Stadium Floodlight Rig
            BuildLightingAndAtmosphere(buildingRoot.transform);

            // 5. 70+ Cheering Spectator NPCs placed across the Bleacher Tiers
            GameObject crowdRoot = BuildSpectatorCrowdOnBleachers(buildingRoot.transform, spectatorControllers);

            // 6. Spawn Combatants inside the center ring (Alita Player + Rival Duelist)
            var (player, rival) = SpawnCombatants(buildingRoot.transform);

            // 7. Connect Spectators to Combatants
            ConnectSpectatorsToCombat(crowdRoot, rival != null ? rival.transform : null);

            // 8. Setup Smooth Orbit Camera for Big Arena
            SetupIndoorCamera(player.transform, buildingRoot.transform);

            // 9. Add Arena Combat Manager & BGM Audio
            SetupArenaManager(player, rival, buildingRoot.transform);

            // 10. Mark and Save Scene
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, targetScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log($"<color=#00FFFF>[CyberpunkArena] Massive Indoor Fight Stadium successfully built at: {targetScenePath}</color>");
        }

        private static void EnsureDirectories()
        {
            if (!Directory.Exists("Assets/Scenes")) Directory.CreateDirectory("Assets/Scenes");
            if (!Directory.Exists(ControllerDir)) Directory.CreateDirectory(ControllerDir);
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. ENCLOSED BUILDING ARCHITECTURE (68m x 68m x 20m HIGH)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildEnclosedBuilding()
        {
            GameObject root = new GameObject("Indoor_Arena_Building_Complex");

            var floorMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat")
                        ?? AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            var wallMat  = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Wall_01.mat")
                        ?? floorMat;
            var ceilingMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Ceiling_01.mat")
                          ?? floorMat;

            float buildW = 68f;
            float buildH = 20f;
            float halfDist = buildW * 0.5f;

            // --- Floor Ground Slab (68m x 68m) ---
            GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            floor.name = "Building_Floor_Ground";
            floor.transform.SetParent(root.transform);
            floor.transform.position = new Vector3(0f, -0.25f, 0f);
            floor.transform.localScale = new Vector3(buildW, 0.5f, buildW);
            if (floorMat != null) floor.GetComponent<Renderer>().sharedMaterial = floorMat;

            // --- Ceiling / Roof (68m x 68m at Y = 19.5m) ---
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ceiling.name = "Industrial_Ceiling_Roof";
            ceiling.transform.SetParent(root.transform);
            ceiling.transform.position = new Vector3(0f, 19.5f, 0f);
            ceiling.transform.localScale = new Vector3(buildW, 0.8f, buildW);
            if (ceilingMat != null) ceiling.GetComponent<Renderer>().sharedMaterial = ceilingMat;

            // --- 4 Perimeter Enclosing Brutalist Concrete/Steel Walls ---
            float wallThick = 1.0f;
            float wallCenterY = buildH * 0.5f - 0.25f;

            CreateWall(root.transform, "Wall_North", new Vector3(0f, wallCenterY, halfDist), new Vector3(buildW, buildH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_South", new Vector3(0f, wallCenterY, -halfDist), new Vector3(buildW, buildH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_East",  new Vector3(halfDist, wallCenterY, 0f), new Vector3(wallThick, buildH, buildW), wallMat);
            CreateWall(root.transform, "Wall_West",  new Vector3(-halfDist, wallCenterY, 0f), new Vector3(wallThick, buildH, buildW), wallMat);

            // --- Heavy Corner Columns ---
            float colOffset = halfDist - 1.5f;
            Vector3[] colPositions = new Vector3[]
            {
                new Vector3(colOffset, wallCenterY, colOffset),
                new Vector3(-colOffset, wallCenterY, colOffset),
                new Vector3(colOffset, wallCenterY, -colOffset),
                new Vector3(-colOffset, wallCenterY, -colOffset)
            };
            foreach (var cp in colPositions)
            {
                GameObject col = GameObject.CreatePrimitive(PrimitiveType.Cube);
                col.name = "Structural_Pillar";
                col.transform.SetParent(root.transform);
                col.transform.position = cp;
                col.transform.localScale = new Vector3(3.0f, buildH, 3.0f);
                if (wallMat != null) col.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- Overhead Structural Steel Trusses Across Roof ---
            for (int ti = -3; ti <= 3; ti++)
            {
                GameObject truss = GameObject.CreatePrimitive(PrimitiveType.Cube);
                truss.name = $"Overhead_Steel_Truss_{ti}";
                truss.transform.SetParent(root.transform);
                truss.transform.position = new Vector3(ti * 8.5f, 18.2f, 0f);
                truss.transform.localScale = new Vector3(0.8f, 1.4f, buildW - 2f);
                if (wallMat != null) truss.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- Giant Wall Holographic Neon Signs (Fight Club / Blackwall Arena) ---
            string holo1 = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_01.prefab";
            string holo2 = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_04.prefab";
            var hPref1 = AssetDatabase.LoadAssetAtPath<GameObject>(holo1);
            var hPref2 = AssetDatabase.LoadAssetAtPath<GameObject>(holo2);

            if (hPref1 != null)
            {
                var hg1 = Object.Instantiate(hPref1, new Vector3(0f, 11.5f, halfDist - 0.8f), Quaternion.Euler(0f, 180f, 0f), root.transform);
                hg1.name = "Arena_Holo_Billboard_North";
                hg1.transform.localScale = new Vector3(3.5f, 3.5f, 3.5f);
            }
            if (hPref2 != null)
            {
                var hg2 = Object.Instantiate(hPref2, new Vector3(0f, 11.5f, -halfDist + 0.8f), Quaternion.Euler(0f, 0f, 0f), root.transform);
                hg2.name = "Arena_Holo_Billboard_South";
                hg2.transform.localScale = new Vector3(3.5f, 3.5f, 3.5f);
            }

            return root;
        }

        private static GameObject CreateWall(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject wall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            wall.name = name;
            wall.transform.SetParent(parent);
            wall.transform.position = pos;
            wall.transform.localScale = scale;
            if (mat != null) wall.GetComponent<Renderer>().sharedMaterial = mat;
            return wall;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. CENTRAL FIGHT RING (34m x 34m COMBAT PIT)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildCombatRing(Transform parent)
        {
            GameObject ringRoot = new GameObject("Central_Combat_Arena_Ring");
            ringRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            // --- Elegant Cyber Combat Octagon Ring Borders (Thin Emissive Wireframes, NO Solid Pink Disc!) ---
            // Outer Octagon Ring Border (Cyan)
            GameObject outerRing = CreateWireframeCircle(ringRoot.transform, "Combat_Ring_Border_Cyan", 22.0f, new Color(0f, 0.90f, 1f), 0.12f);
            // Inner Octagon Ring Border (Magenta)
            GameObject innerRing = CreateWireframeCircle(ringRoot.transform, "Combat_Ring_Center_Magenta", 11.0f, new Color(1f, 0.12f, 0.75f), 0.10f);

            // 4 Corner Steel Turnbuckles with Warning Beacons (at +/- 16m)
            float cornerDist = 16.5f;
            Vector3[] corners = new Vector3[]
            {
                new Vector3(cornerDist, 0f, cornerDist),
                new Vector3(-cornerDist, 0f, cornerDist),
                new Vector3(cornerDist, 0f, -cornerDist),
                new Vector3(-cornerDist, 0f, -cornerDist)
            };

            for (int i = 0; i < corners.Length; i++)
            {
                GameObject post = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                post.name = $"Arena_Turnbuckle_Post_{i + 1}";
                post.transform.SetParent(ringRoot.transform);
                post.transform.position = corners[i] + Vector3.up * 1.8f;
                post.transform.localScale = new Vector3(0.55f, 1.8f, 0.55f);

                var postMat = new Material(litShader);
                postMat.color = new Color(0.08f, 0.08f, 0.10f);
                postMat.EnableKeyword("_EMISSION");
                Color glowCol = (i % 2 == 0) ? new Color(0f, 0.95f, 1f) : new Color(1f, 0.20f, 0.85f);
                postMat.SetColor("_EmissionColor", glowCol * 3.5f);
                post.GetComponent<Renderer>().sharedMaterial = postMat;

                // Beacon light
                var beaconLightGo = new GameObject($"Corner_Beacon_{i + 1}");
                beaconLightGo.transform.SetParent(post.transform);
                beaconLightGo.transform.position = corners[i] + Vector3.up * 3.8f;
                var bLight = beaconLightGo.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = glowCol;
                bLight.intensity = 3.5f;
                bLight.range = 10.0f;
            }

            return ringRoot;
        }

        private static GameObject CreateWireframeCircle(Transform parent, string name, float diameter, Color emissiveColor, float thickness)
        {
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var mat = new Material(litShader);
            mat.color = new Color(0.02f, 0.02f, 0.03f, 0.9f);
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", emissiveColor * 2.8f);

            GameObject circle = new GameObject(name);
            circle.transform.SetParent(parent);
            circle.transform.position = new Vector3(0f, 0.015f, 0f);

            int segments = 16;
            float radius = diameter * 0.5f;
            float angleStep = 360f / segments;

            for (int i = 0; i < segments; i++)
            {
                float a1 = i * angleStep * Mathf.Deg2Rad;
                float a2 = (i + 1) * angleStep * Mathf.Deg2Rad;
                Vector3 p1 = new Vector3(Mathf.Sin(a1) * radius, 0f, Mathf.Cos(a1) * radius);
                Vector3 p2 = new Vector3(Mathf.Sin(a2) * radius, 0f, Mathf.Cos(a2) * radius);

                Vector3 mid = (p1 + p2) * 0.5f;
                float segLen = Vector3.Distance(p1, p2);

                GameObject bar = GameObject.CreatePrimitive(PrimitiveType.Cube);
                bar.name = $"Seg_{i}";
                bar.transform.SetParent(circle.transform);
                bar.transform.position = mid + Vector3.up * 0.01f;
                bar.transform.LookAt(circle.transform.position + p2 + Vector3.up * 0.01f);
                bar.transform.localScale = new Vector3(thickness, 0.02f, segLen);
                bar.GetComponent<Renderer>().sharedMaterial = mat;
                Object.DestroyImmediate(bar.GetComponent<Collider>());
            }

            return circle;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. 4-TIER STEPPED STADIUM BLEACHERS (STAIRS-LIKE PLATFORMS)
        // ─────────────────────────────────────────────────────────────────────
        public struct BleacherTierInfo
        {
            public int tierIndex;
            public Vector3 center;
            public Vector3 forwardDir;
            public float width;
            public float height;
        }

        private static List<BleacherTierInfo> _allBleacherTiers = new List<BleacherTierInfo>();

        private static GameObject BuildSteppedBleachers(Transform parent)
        {
            _allBleacherTiers.Clear();

            GameObject bleachersRoot = new GameObject("Arena_Stadium_Bleachers_Stairs");
            bleachersRoot.transform.SetParent(parent);

            var stepMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            string railPrefabPath = "Assets/PolygonCyberCity/Prefabs/Buildings/SM_Bld_Railing_Straight_01.prefab";
            var railPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(railPrefabPath);

            // Bleacher Configuration: 4 Tiers of Stepped Stadium Stairs
            // Step depth = 2.4m, step rise = 1.15m per tier
            int tierCount = 4;
            float stepDepth = 2.4f;
            float stepRise = 1.15f;
            float pitHalf = 17.5f; // Starts right outside the 34m arena pit

            // North Bleachers (+Z side, looking South: forward = -Z)
            BuildBleacherSide(bleachersRoot.transform, "Bleachers_North", 0f, pitHalf, stepDepth, stepRise, tierCount, 40f, Vector3.forward, Vector3.back, stepMat, railPrefab);

            // South Bleachers (-Z side, looking North: forward = +Z)
            BuildBleacherSide(bleachersRoot.transform, "Bleachers_South", 0f, -pitHalf, stepDepth, stepRise, tierCount, 40f, Vector3.back, Vector3.forward, stepMat, railPrefab);

            // East Bleachers (+X side, looking West: forward = -X)
            BuildBleacherSide(bleachersRoot.transform, "Bleachers_East", pitHalf, 0f, stepDepth, stepRise, tierCount, 36f, Vector3.right, Vector3.left, stepMat, railPrefab);

            // West Bleachers (-X side, looking East: forward = +X)
            BuildBleacherSide(bleachersRoot.transform, "Bleachers_West", -pitHalf, 0f, stepDepth, stepRise, tierCount, 36f, Vector3.left, Vector3.right, stepMat, railPrefab);

            return bleachersRoot;
        }

        private static void BuildBleacherSide(
            Transform parent, string sideName,
            float startX, float startZ,
            float stepDepth, float stepRise,
            int tierCount, float baseWidth,
            Vector3 outwardsDir, Vector3 lookInwardDir,
            Material mat, GameObject railPrefab)
        {
            GameObject sideRoot = new GameObject(sideName);
            sideRoot.transform.SetParent(parent);

            bool isZAxis = Mathf.Abs(outwardsDir.z) > 0.5f;

            for (int t = 0; t < tierCount; t++)
            {
                float tierDist = (t + 0.5f) * stepDepth;
                float tierHeight = (t + 1) * stepRise;
                float tierW = baseWidth + t * 2.8f;

                Vector3 tierPos;
                Vector3 tierScale;

                if (isZAxis)
                {
                    float z = startZ + outwardsDir.z * tierDist;
                    tierPos = new Vector3(startX, tierHeight * 0.5f, z);
                    tierScale = new Vector3(tierW, tierHeight, stepDepth);
                }
                else
                {
                    float x = startX + outwardsDir.x * tierDist;
                    tierPos = new Vector3(x, tierHeight * 0.5f, startZ);
                    tierScale = new Vector3(stepDepth, tierHeight, tierW);
                }

                GameObject step = GameObject.CreatePrimitive(PrimitiveType.Cube);
                step.name = $"Tier_{t + 1}_Platform";
                step.transform.SetParent(sideRoot.transform);
                step.transform.position = tierPos;
                step.transform.localScale = tierScale;
                if (mat != null) step.GetComponent<Renderer>().sharedMaterial = mat;

                // Record tier for spectator placement
                Vector3 standingCenter = tierPos + Vector3.up * (tierHeight * 0.5f);
                _allBleacherTiers.Add(new BleacherTierInfo
                {
                    tierIndex = t,
                    center = standingCenter,
                    forwardDir = lookInwardDir,
                    width = tierW,
                    height = tierHeight
                });

                // Front safety railing on Tier 1 (separating crowd from the arena pit)
                if (t == 0 && railPrefab != null)
                {
                    float railZ = isZAxis ? startZ : startZ - tierW * 0.5f;
                    float railX = isZAxis ? startX - tierW * 0.5f : startX;
                    float yRot = (lookInwardDir == Vector3.back) ? 180f :
                                 (lookInwardDir == Vector3.forward) ? 0f :
                                 (lookInwardDir == Vector3.left) ? 270f : 90f;

                    int railCount = Mathf.RoundToInt(tierW / 2.4f);
                    for (int ri = 0; ri < railCount; ri++)
                    {
                        Vector3 rp;
                        if (isZAxis)
                        {
                            rp = new Vector3(railX + ri * 2.4f + 1.2f, tierHeight, startZ);
                        }
                        else
                        {
                            rp = new Vector3(startX, tierHeight, railZ + ri * 2.4f + 1.2f);
                        }
                        var rail = Object.Instantiate(railPrefab, rp, Quaternion.Euler(0f, yRot, 0f), sideRoot.transform);
                        rail.name = "Front_Safety_Railing";
                    }
                }
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 4. OVERHEAD LIGHTING & STADIUM FLOODLIGHT RIG
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildLightingAndAtmosphere(Transform parent)
        {
            GameObject lightRoot = new GameObject("Arena_Stadium_Lighting_Rig");
            lightRoot.transform.SetParent(parent);

            // Ambient fill (dark moody cyberpunk underground warehouse mood)
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.04f, 0.06f, 0.11f);

            // 8 Angled Stadium Floodlights hanging from overhead trusses pointing down into the ring
            float floodH = 16.5f;
            float floodRadius = 13.5f;

            for (int i = 0; i < 8; i++)
            {
                float angle = i * 45f * Mathf.Deg2Rad;
                Vector3 spotPos = new Vector3(Mathf.Sin(angle) * floodRadius, floodH, Mathf.Cos(angle) * floodRadius);

                var spotGo = new GameObject($"Stadium_Floodlight_{i + 1}");
                spotGo.transform.SetParent(lightRoot.transform);
                spotGo.transform.position = spotPos;
                spotGo.transform.LookAt(Vector3.zero + Vector3.up * 0.5f);

                var spot = spotGo.AddComponent<Light>();
                spot.type = LightType.Spot;
                spot.color = (i % 2 == 0) ? new Color(0.95f, 0.98f, 1.0f) : new Color(0.20f, 0.90f, 1.0f);
                spot.intensity = 26.0f;
                spot.range = 32.0f;
                spot.spotAngle = 65.0f;
                spot.innerSpotAngle = 38.0f;
                spot.shadows = LightShadows.Soft;
            }

            // Overhead Hanging Centerpiece Hologram Dragon
            string dragonPath = "Assets/PolygonCyberCity/Prefabs/FX/Hologram_Dragon_01.prefab";
            var dragonPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(dragonPath);
            if (dragonPrefab != null)
            {
                var dragon = Object.Instantiate(dragonPrefab, new Vector3(0f, 12.0f, 0f), Quaternion.Euler(0f, 40f, 0f), lightRoot.transform);
                dragon.name = "Overhead_Holo_Dragon";
                dragon.transform.localScale = new Vector3(1.8f, 1.8f, 1.8f);
            }

            // Bleacher Ambient Uplighting (Subtle Neon Rim along the tiers)
            Color[] rimColors = new Color[] { new Color(0f, 0.85f, 1f), new Color(1f, 0.15f, 0.75f) };
            for (int r = 0; r < 4; r++)
            {
                float rad = 22.0f;
                float a = (r * 90f + 45f) * Mathf.Deg2Rad;
                var bleacherRimGo = new GameObject($"Bleacher_Accent_RimLight_{r + 1}");
                bleacherRimGo.transform.SetParent(lightRoot.transform);
                bleacherRimGo.transform.position = new Vector3(Mathf.Sin(a) * rad, 4.5f, Mathf.Cos(a) * rad);

                var rimLight = bleacherRimGo.AddComponent<Light>();
                rimLight.type = LightType.Point;
                rimLight.color = rimColors[r % 2];
                rimLight.intensity = 3.2f;
                rimLight.range = 18.0f;
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 5. 70+ SPECTATORS ARRANGED ACROSS THE BLEACHER TIERS
        // ─────────────────────────────────────────────────────────────────────
        private static Dictionary<ArenaSpectatorNPC.SpectatorCheerType, (RuntimeAnimatorController ctrl, AnimationClip clip)[]> EnsureSpectatorControllers()
        {
            var dict = new Dictionary<ArenaSpectatorNPC.SpectatorCheerType, (RuntimeAnimatorController, AnimationClip)[]>();

            var cheerDefs = new (ArenaSpectatorNPC.SpectatorCheerType type, string femnFbx, string mascFbx)[]
            {
                (
                    ArenaSpectatorNPC.SpectatorCheerType.DoubleWaveCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Double_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Double_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.FistPumpCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Large_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Large_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.SmallWaveCheer,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Wave/Stances/A_POLY_IDL_Wave_Small_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Wave/Stances/A_POLY_IDL_Wave_Small_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.AggressiveHype,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Posture/Stances/A_POLY_IDL_Posture_Aggressive_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Posture/Stances/A_POLY_IDL_Posture_Aggressive_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.DrinkWatching,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Drink/Stances/A_POLY_IDL_Drink_Hold_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Drink/Stances/A_POLY_IDL_Drink_Hold_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.RailingLean,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/Lean/Stances/ArmsFolded/A_POLY_IDL_Lean_B_ArmsFolded_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/Lean/Stances/ArmsFolded/A_POLY_IDL_Lean_B_ArmsFolded_Loop_Masc.fbx"
                ),
                (
                    ArenaSpectatorNPC.SpectatorCheerType.VideoRecording,
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Feminine/UsePhone/Stances/Video/A_POLY_IDL_UsePhone_OneHand_Video_Loop_Femn.fbx",
                    "Assets/Synty/AnimationIdles/Animations/Polygon/Masculine/UsePhone/Stances/Video/A_POLY_IDL_UsePhone_OneHand_Video_Loop_Masc.fbx"
                )
            };

            foreach (var def in cheerDefs)
            {
                string femnPath = $"{ControllerDir}/AC_Spectator_{def.type}_Femn.controller";
                string mascPath = $"{ControllerDir}/AC_Spectator_{def.type}_Masc.controller";

                var femnClip = LoadClipFromFbx(def.femnFbx);
                var mascClip = LoadClipFromFbx(def.mascFbx);

                var femnCtrl = BuildSingleClipController(femnPath, femnClip);
                var mascCtrl = BuildSingleClipController(mascPath, mascClip);

                dict[def.type] = new (RuntimeAnimatorController, AnimationClip)[]
                {
                    (femnCtrl, femnClip),
                    (mascCtrl, mascClip)
                };
            }

            return dict;
        }

        private static RuntimeAnimatorController BuildSingleClipController(string controllerPath, AnimationClip clip)
        {
            var existing = AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);
            if (existing != null) return existing;

            var ctrl = AnimatorController.CreateAnimatorControllerAtPath(controllerPath);
            if (clip != null)
            {
                var state = ctrl.layers[0].stateMachine.AddState("CheeringLoop");
                state.motion = clip;
                ctrl.layers[0].stateMachine.defaultState = state;
            }
            return ctrl;
        }

        private static AnimationClip LoadClipFromFbx(string fbxPath)
        {
            var assets = AssetDatabase.LoadAllAssetsAtPath(fbxPath);
            if (assets == null) return null;
            foreach (var a in assets)
            {
                if (a is AnimationClip c && !c.name.StartsWith("__preview__")) return c;
            }
            return null;
        }

        private static GameObject BuildSpectatorCrowdOnBleachers(
            Transform parent,
            Dictionary<ArenaSpectatorNPC.SpectatorCheerType, (RuntimeAnimatorController ctrl, AnimationClip clip)[]> controllers)
        {
            GameObject crowdRoot = new GameObject("Spectator_Crowd_Stadium_Bleachers");
            crowdRoot.transform.SetParent(parent);

            string[] characterPrefabs = new string[]
            {
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Mercenary_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Mercenary_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Cyborg_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Cyborg_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Female_Soldier_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Male_Soldier_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Street_Male_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Robot_Female_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Robot_Mercenary_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Fancy_Bot_01.prefab"
            };

            AudioClip[] chatterClips = new AudioClip[]
            {
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_01.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_02.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_civilian_murmur_03.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_merc_grunt_01.wav"),
                AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/NPC_Chatter/npc_merc_grunt_02.wav")
            };

            var cheerTypes = new ArenaSpectatorNPC.SpectatorCheerType[]
            {
                ArenaSpectatorNPC.SpectatorCheerType.DoubleWaveCheer,
                ArenaSpectatorNPC.SpectatorCheerType.FistPumpCheer,
                ArenaSpectatorNPC.SpectatorCheerType.AggressiveHype,
                ArenaSpectatorNPC.SpectatorCheerType.SmallWaveCheer,
                ArenaSpectatorNPC.SpectatorCheerType.VideoRecording,
                ArenaSpectatorNPC.SpectatorCheerType.DrinkWatching,
                ArenaSpectatorNPC.SpectatorCheerType.RailingLean
            };

            int globalNpcCount = 0;

            // Populate all 4 sides of the bleachers across all tiers
            foreach (var tier in _allBleacherTiers)
            {
                bool isZAxis = Mathf.Abs(tier.forwardDir.z) > 0.5f;
                float halfW = tier.width * 0.44f;
                float spacing = 2.0f; // 2m spacing between spectator fans

                for (float offset = -halfW; offset <= halfW; offset += spacing)
                {
                    // Add slight natural jitter so fans aren't in a perfectly rigid grid
                    float jitterX = isZAxis ? offset + Random.Range(-0.18f, 0.18f) : tier.center.x;
                    float jitterZ = isZAxis ? tier.center.z : offset + Random.Range(-0.18f, 0.18f);
                    Vector3 npcPos = new Vector3(jitterX, tier.center.y, jitterZ);

                    string prefabPath = characterPrefabs[globalNpcCount % characterPrefabs.Length];
                    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
                    if (prefab == null) continue;

                    // Face inward toward the center arena ring with slight natural gaze variation
                    Vector3 lookTarget = Vector3.zero + new Vector3(Random.Range(-2f, 2f), 0f, Random.Range(-2f, 2f));
                    Vector3 faceDir = (lookTarget - npcPos).normalized;
                    faceDir.y = 0f;
                    Quaternion rot = Quaternion.LookRotation(faceDir);

                    var npc = Object.Instantiate(prefab, npcPos, rot, crowdRoot.transform);
                    npc.name = $"Spectator_T{tier.tierIndex + 1}_{globalNpcCount + 1:D2}_{prefab.name}";

                    // Remove combat components
                    var insaneCtrl = npc.GetComponent<InsaneGunSwordController>();
                    if (insaneCtrl != null) Object.DestroyImmediate(insaneCtrl);
                    var charCtrl = npc.GetComponent<CharacterController>();
                    if (charCtrl != null) charCtrl.enabled = false;

                    // Assign Cheer Persona & Animation Controller
                    var cheer = cheerTypes[globalNpcCount % cheerTypes.Length];
                    bool isFemn = prefab.name.ToLower().Contains("female");

                    var anim = npc.GetComponent<Animator>();
                    if (anim == null) anim = npc.AddComponent<Animator>();

                    if (controllers.TryGetValue(cheer, out var pair) && pair.Length >= 2)
                    {
                        var selected = isFemn ? pair[0] : pair[1];
                        anim.runtimeAnimatorController = selected.ctrl;

                        // EDIT-MODE POSE SAMPLING: Pose skeleton immediately in the editor so NO T-POSES!
                        if (selected.clip != null)
                        {
                            float sampleT = Random.Range(0.2f, Mathf.Max(0.5f, selected.clip.length - 0.2f));
                            selected.clip.SampleAnimation(npc, sampleT);
                        }
                    }

                    // Add Spectator NPC Behaviour Script
                    var specComp = npc.AddComponent<ArenaSpectatorNPC>();
                    specComp.cheerType = cheer;
                    specComp.chatterClips = chatterClips;
                    specComp.lookAtArenaCenter = true;

                    globalNpcCount++;
                }
            }

            Debug.Log($"<color=#00FFFF>[CyberpunkArena] Generated {globalNpcCount} Spectators across 4 Stadium Bleacher Tiers!</color>");
            return crowdRoot;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 6. SPAWN COMBATANTS (ALITA HERO + RIVAL COMBATANT)
        // ─────────────────────────────────────────────────────────────────────
        private static (InsaneGunSwordController player, InsaneGunSwordController rival) SpawnCombatants(Transform parent)
        {
            // Spawn Alita Battle Angel Player
            string alitaPath = "Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab";
            var alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(alitaPath);
            GameObject alitaGo = null;

            if (alitaPrefab != null)
            {
                alitaGo = Object.Instantiate(alitaPrefab, new Vector3(0f, 0.05f, -6.0f), Quaternion.Euler(0f, 0f, 0f), parent);
                alitaGo.name = "Alita_BattleAngel_Hero";
                alitaGo.tag = "Player";
                alitaGo.layer = LayerMask.NameToLayer("Player");
            }
            else
            {
                alitaGo = new GameObject("Alita_BattleAngel_Hero");
                alitaGo.transform.position = new Vector3(0f, 0.05f, -6.0f);
            }

            var playerCtrl = alitaGo.GetComponent<InsaneGunSwordController>();
            if (playerCtrl == null) playerCtrl = alitaGo.AddComponent<InsaneGunSwordController>();
            playerCtrl.controlMode = InsaneGunSwordController.ControlMode.PlayerControlled;
            playerCtrl.maxHealth = 300f;
            playerCtrl.currentHealth = 300f;

            // Spawn Rival Combatant Duelist inside the ring
            string boyPrefabPath = "Assets/Synty/SidekickCharacters/Prefabs/Characters/SM_Chr_Sidekick_Male_Boy_01.prefab";
            var boyPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(boyPrefabPath);
            GameObject rivalGo = null;

            if (boyPrefab != null)
            {
                rivalGo = Object.Instantiate(boyPrefab, new Vector3(0f, 0.05f, 6.0f), Quaternion.Euler(0f, 180f, 0f), parent);
                rivalGo.name = "Rival_Arena_Duelist";
                rivalGo.tag = "Enemy";
                rivalGo.layer = LayerMask.NameToLayer("Enemy");

                var rivalCtrl = rivalGo.GetComponent<InsaneGunSwordController>();
                if (rivalCtrl == null) rivalCtrl = rivalGo.AddComponent<InsaneGunSwordController>();
                rivalCtrl.controlMode = InsaneGunSwordController.ControlMode.AICirclingEnemy;
                rivalCtrl.maxHealth = 300f;
                rivalCtrl.currentHealth = 300f;

                string animCtrlPath = "Assets/InsaneGun_Sword_Set/Animation/Controller/AC_InsaneGun_Sidekick_Boy.controller";
                var anim = rivalGo.GetComponent<Animator>();
                if (anim != null) anim.runtimeAnimatorController = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(animCtrlPath);

                return (playerCtrl, rivalCtrl);
            }

            return (playerCtrl, null);
        }

        private static void ConnectSpectatorsToCombat(GameObject crowdRoot, Transform rival)
        {
            if (crowdRoot == null) return;
            var spectators = crowdRoot.GetComponentsInChildren<ArenaSpectatorNPC>();
            foreach (var s in spectators)
            {
                s.SetArenaFocus(Vector3.zero, rival);
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 7. INDOOR ORBIT CAMERA SETUP (OPTIMIZED FOR BIG ARENA)
        // ─────────────────────────────────────────────────────────────────────
        private static void SetupIndoorCamera(Transform playerTarget, Transform parent)
        {
            Camera mainCam = Camera.main;
            if (mainCam == null)
            {
                var camGo = new GameObject("MainCamera");
                mainCam = camGo.AddComponent<Camera>();
                camGo.tag = "MainCamera";
                camGo.transform.SetParent(parent);
            }

            mainCam.transform.position = new Vector3(0f, 3.2f, -11.5f);
            mainCam.transform.LookAt(playerTarget.position + Vector3.up * 1.45f);

            var orbit = mainCam.GetComponent<SmoothOrbitCamera>();
            if (orbit == null) orbit = mainCam.gameObject.AddComponent<SmoothOrbitCamera>();
            orbit.target = playerTarget;
            orbit.tightPositionFollow = true; // Zero lag / zero motion smearing
            orbit.targetOffset = new Vector3(0f, 1.45f, 0f);
            orbit.cameraOffset = new Vector3(0f, 0.45f, -6.5f);
            orbit.minDistance = 2.5f;
            orbit.maxDistance = 14.0f; // Can zoom way out to admire the full packed stadium

            var uad = mainCam.GetComponent<UniversalAdditionalCameraData>();
            if (uad == null) uad = mainCam.gameObject.AddComponent<UniversalAdditionalCameraData>();
            uad.renderPostProcessing = true;
            uad.antialiasing = AntialiasingMode.None;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 8. ARENA COMBAT MANAGER & BGM AUDIO
        // ─────────────────────────────────────────────────────────────────────
        private static void SetupArenaManager(InsaneGunSwordController player, InsaneGunSwordController rival, Transform parent)
        {
            var mgrGo = new GameObject("Arena_Combat_Manager");
            mgrGo.transform.SetParent(parent);

            var testMgr = mgrGo.AddComponent<InsaneGunCombatTestManager>();
            testMgr.player = player;
            testMgr.enemy = rival;
            testMgr.enemySpawnPos = new Vector3(0f, 0.05f, 6.0f);
            testMgr.enemySpawnRot = Quaternion.Euler(0f, 180f, 0f);

            var bgmClip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/Cyberpunk_Combat_Metal_Heart.mp3")
                       ?? AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/paulyudin-intense-intense-music-574004.mp3");
            if (bgmClip != null)
            {
                var audio = mgrGo.AddComponent<AudioSource>();
                audio.clip = bgmClip;
                audio.volume = 0.55f;
                audio.loop = true;
                audio.playOnAwake = true;
                audio.Play();
            }
        }
    }
