// Soft Stadium Directional Key Light from overhead trusses (provides realistic stadium colosseum fill)
var dirLightGo = new GameObject("Stadium_Truss_Directional_Fill");
dirLightGo.transform.SetParent(lightRoot.transform);
dirLightGo.transform.rotation = Quaternion.Euler(58f, 30f, 0f);
var dirLight = dirLightGo.AddComponent<Light>();
dirLight.type = LightType.Directional;
dirLight.color = new Color(0.90f, 0.94f, 1.0f);
dirLight.intensity = 0.85f;
dirLight.shadows = LightShadows.Soft;

// --- 12 Dedicated Stadium Grandstand Wash Lights (Illuminating the Spectator Crowd!) ---
// 3 lights per side pointing down at the tiers so spectators are brightly lit and visible
(string sideName, Vector3[] lightPositions, Vector3 lookTarget)[] sideLights = new[]
{
    ("NorthCrowd", new[] { new Vector3(-14f, 17f, 10f), new Vector3(0f, 17f, 10f), new Vector3(14f, 17f, 10f) }, new Vector3(0f, 4.0f, 22f)),
    ("SouthCrowd", new[] { new Vector3(-14f, 17f, -10f), new Vector3(0f, 17f, -10f), new Vector3(14f, 17f, -10f) }, new Vector3(0f, 4.0f, -22f)),
    ("EastCrowd",  new[] { new Vector3(10f, 17f, -14f), new Vector3(10f, 17f, 0f), new Vector3(10f, 17f, 14f) }, new Vector3(22f, 4.0f, 0f)),
    ("WestCrowd",  new[] { new Vector3(-10f, 17f, -14f), new Vector3(-10f, 17f, 0f), new Vector3(-10f, 17f, 14f) }, new Vector3(-22f, 4.0f, 0f))
};

foreach (var side in sideLights)
{
    for (int li = 0; li < side.lightPositions.Length; li++)
    {
        var washGo = new GameObject($"Crowd_WashLight_{side.sideName}_{li + 1}");
        washGo.transform.SetParent(lightRoot.transform);
        washGo.transform.position = side.lightPositions[li];
        washGo.transform.LookAt(side.lookTarget);

        var spot = washGo.AddComponent<Light>();
        spot.type = LightType.Spot;
        spot.color = new Color(0.98f, 0.94f, 0.90f); // Warm crisp stadium spectator flood
        spot.intensity = 32.0f;
        spot.range = 42.0f;
        spot.spotAngle = 75.0f;
        spot.innerSpotAngle = 42.0f;
        spot.shadows = LightShadows.None; // None for crowd fill performance
    }
}

