using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;
using InsaneGun.Testing;
using InsaneGun.Arena;

namespace InsaneGun.EditorTools
{
    /// <summary>
    /// Builds a colossal, competition-grade Cyberpunk Indoor Fight Stadium / Colosseum.
    /// 
    /// Architecture:
    /// - 140m x 140m x 32m brutalist enclosed stadium arena.
    /// - 56m x 56m massive combat floor with raised 44m cyber octagon fighting stage.
    /// - 10-Tier stepped stadium amphitheater bowl (1.2m to 12.2m height) wrapping all 4 sides.
    /// - 8 Stepped access stairways / aisles dividing grandstand sections.
    /// - 360-Degree glowing LED ribbon board running along the stadium tier rim.
    /// - 4 Massive 18m high corner pylon floodlight towers with rotating beacons and vertical neon channels.
    /// - Gigantic 4-sided hanging center Jumbotron scoreboard (14m wide) with match displays.
    /// - Red Corner and Blue Corner fighter entrance tunnels with neon runway strips.
    /// - 500+ Diverse Cyberpunk spectator NPCs cheering, pumping fists, recording, and leaning on railings.
    /// - Professional stadium broadcast lighting: 16 central ring floodlights, 16 crowd wash floodlights,
    ///   4 corner laser searchlights, and roof truss key illumination.
    /// - Over 16 holographic wall billboards and overhead centerpiece dragon hologram.
    /// </summary>
    public static class CyberpunkIndoorArenaBuilder
    {
        private const string ScenePath = "Assets/Scenes/Cyberpunk_Indoor_Combat_Arena.unity";
        private const string TestArenaPath = "Assets/Scenes/InsaneGun_Combat_TestArena.unity";
        private const string ControllerDir = "Assets/Animations/Spectators";

        [MenuItem("Tools/Cyberpunk/Build Indoor Fight Arena (Closed Building + Cheering Crowd)")]
        public static void BuildIndoorArenaMenu()
        {
            BuildAndSaveScene(ScenePath);
            BuildAndSaveScene(TestArenaPath);
        }

        public static void BuildAndSaveScene(string targetScenePath)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = Path.GetFileNameWithoutExtension(targetScenePath);

            EnsureDirectories();
            var spectatorControllers = EnsureSpectatorControllers();

            // 1. Root Stadium Complex & Massive Building Enclosure (140m x 140m x 32m)
            GameObject stadiumRoot = BuildStadiumEnclosure();

            // 2. Colossal 56m Combat Floor & 44m Raised Octagon Stage
            GameObject combatFloor = BuildCombatStage(stadiumRoot.transform);

            // 3. 10-Tier Stepped Stadium Amphitheater Grandstands (Stairs Bowl with Aisles & Ribbon Ticker)
            GameObject grandstandsRoot = BuildStadiumGrandstands(stadiumRoot.transform);

            // 4. 4 Massive 18m Corner Pylon Light Towers & Fighter Entrance Tunnels
            BuildCornerPylonsAndTunnels(stadiumRoot.transform);

            // 5. Hanging Central 4-Sided Jumbotron Rig & Overhead Roof Trusses
            BuildJumbotronAndTrusses(stadiumRoot.transform);

            // 6. Professional Stadium Broadcast Lighting Rig
            BuildStadiumLighting(stadiumRoot.transform);

            // 7. 500+ Cheering Spectators placed across the Stadium Tiers
            GameObject crowdRoot = BuildSpectatorCrowd(stadiumRoot.transform, spectatorControllers);

            // 8. Spawn Combatants (Alita Hero + Rival Duelist)
            var (player, rival) = SpawnCombatants(stadiumRoot.transform);

            // 9. Connect Spectators to Combatants
            ConnectSpectatorsToCombat(crowdRoot, rival != null ? rival.transform : null);

            // 10. Configure Smooth Orbit Camera for Colossal Stadium
            SetupIndoorCamera(player.transform, stadiumRoot.transform);

            // 11. Add Arena Combat Manager & BGM Audio
            SetupArenaManager(player, rival, stadiumRoot.transform);

            // 12. Mark and Save Scene
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, targetScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log($"<color=#00FFFF>[CyberpunkArena] Colossal Competition Stadium successfully built at: {targetScenePath}</color>");
        }

        private static void EnsureDirectories()
        {
            if (!Directory.Exists("Assets/Scenes")) Directory.CreateDirectory("Assets/Scenes");
            if (!Directory.Exists(ControllerDir)) Directory.CreateDirectory(ControllerDir);
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. MASSIVE STADIUM BUILDING ENCLOSURE (140m x 140m x 32m HIGH)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildStadiumEnclosure()
        {
            GameObject root = new GameObject("Colosseum_Stadium_Complex");

            var floorMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat")
                        ?? AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            var wallMat  = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Wall_01.mat")
                        ?? floorMat;
            var ceilingMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Ceiling_01.mat")
                          ?? floorMat;

            float stadiumW = 140f;
            float stadiumH = 32f;
            float halfDist = stadiumW * 0.5f;

            // --- Floor Ground Slab (140m x 140m) ---
            GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            floor.name = "Stadium_Foundation_Floor";
            floor.transform.SetParent(root.transform);
            floor.transform.position = new Vector3(0f, -0.5f, 0f);
            floor.transform.localScale = new Vector3(stadiumW, 1.0f, stadiumW);
            if (floorMat != null) floor.GetComponent<Renderer>().sharedMaterial = floorMat;

            // --- High Stadium Dome / Ceiling (Y = 31.5m) ---
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ceiling.name = "Stadium_Dome_Ceiling";
            ceiling.transform.SetParent(root.transform);
            ceiling.transform.position = new Vector3(0f, stadiumH, 0f);
            ceiling.transform.localScale = new Vector3(stadiumW, 1.5f, stadiumW);
            if (ceilingMat != null) ceiling.GetComponent<Renderer>().sharedMaterial = ceilingMat;

            // --- 4 Perimeter Stadium Walls ---
            float wallThick = 2.0f;
            float wallCenterY = stadiumH * 0.5f;

            CreateWall(root.transform, "Wall_North", new Vector3(0f, wallCenterY, halfDist), new Vector3(stadiumW, stadiumH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_South", new Vector3(0f, wallCenterY, -halfDist), new Vector3(stadiumW, stadiumH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_East",  new Vector3(halfDist, wallCenterY, 0f), new Vector3(wallThick, stadiumH, stadiumW), wallMat);
            CreateWall(root.transform, "Wall_West",  new Vector3(-halfDist, wallCenterY, 0f), new Vector3(wallThick, stadiumH, stadiumW), wallMat);

            // --- 4 Giant Corner Stadium Pylons ---
            float colOffset = halfDist - 2.5f;
            Vector3[] colPositions = new Vector3[]
            {
                new Vector3(colOffset, wallCenterY, colOffset),
                new Vector3(-colOffset, wallCenterY, colOffset),
                new Vector3(colOffset, wallCenterY, -colOffset),
                new Vector3(-colOffset, wallCenterY, -colOffset)
            };
            foreach (var cp in colPositions)
            {
                GameObject col = GameObject.CreatePrimitive(PrimitiveType.Cube);
                col.name = "Stadium_Corner_Colossus_Pillar";
                col.transform.SetParent(root.transform);
                col.transform.position = cp;
                col.transform.localScale = new Vector3(6.0f, stadiumH, 6.0f);
                if (wallMat != null) col.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- Upper VIP Luxury Suites along the Upper Perimeter (Y = 17m to 24m) ---
            BuildVIPSuites(root.transform, stadiumW, stadiumH);

            return root;
        }

        private static void BuildVIPSuites(Transform parent, float stadiumW, float stadiumH)
        {
            var glassMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Glass_01_A.mat");
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            var vipMat = new Material(litShader);
            vipMat.color = new Color(0.08f, 0.12f, 0.18f);
            vipMat.EnableKeyword("_EMISSION");
            vipMat.SetColor("_EmissionColor", new Color(0f, 0.55f, 0.90f) * 1.5f);

            float halfDist = stadiumW * 0.5f - 1.5f;
            float vipY = 19.5f;

            // 4 VIP Glass Balconies along the upper walls
            Vector3[] vipPos = new[]
            {
                new Vector3(0f, vipY, halfDist),
                new Vector3(0f, vipY, -halfDist),
                new Vector3(halfDist, vipY, 0f),
                new Vector3(-halfDist, vipY, 0f)
            };

            for (int i = 0; i < vipPos.Length; i++)
            {
                bool isZ = (i < 2);
                GameObject suite = GameObject.CreatePrimitive(PrimitiveType.Cube);
                suite.name = $"VIP_Luxury_Boxes_{i + 1}";
                suite.transform.SetParent(parent);
                suite.transform.position = vipPos[i];
                suite.transform.localScale = isZ ? new Vector3(90f, 5.0f, 2.5f) : new Vector3(2.5f, 5.0f, 90f);
                suite.GetComponent<Renderer>().sharedMaterial = vipMat;
            }

            // Upper Wall Holographic Advertisements & Jumbotron Billboards
            string[] holoPrefabs = new[]
            {
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_04.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_07.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_10.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_13.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_16.prefab"
            };

            for (int s = 0; s < 4; s++)
            {
                float rotY = s * 90f;
                float dist = stadiumW * 0.5f - 2.8f;
                float angleRad = (s * 90f + 90f) * Mathf.Deg2Rad;

                for (int h = -2; h <= 2; h++)
                {
                    if (h == 0) continue;
                    string hPath = holoPrefabs[Mathf.Abs(s * 2 + h) % holoPrefabs.Length];
                    var pref = AssetDatabase.LoadAssetAtPath<GameObject>(hPath);
                    if (pref != null)
                    {
                        Vector3 hp;
                        if (s == 0) hp = new Vector3(h * 24f, 24.5f, dist);
                        else if (s == 1) hp = new Vector3(dist, 24.5f, h * 24f);
                        else if (s == 2) hp = new Vector3(h * 24f, 24.5f, -dist);
                        else hp = new Vector3(-dist, 24.5f, h * 24f);

                        var go = Object.Instantiate(pref, hp, Quaternion.Euler(0f, rotY + 180f, 0f), parent);
                        go.name = $"Wall_Holo_Billboard_{s}_{h}";
                        go.transform.localScale = Vector3.one * 4.5f;
                    }
                }
            }
        }

        private static GameObject CreateWall(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject wall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            wall.name = name;
            wall.transform.SetParent(parent);
            wall.transform.position = pos;
            wall.transform.localScale = scale;
            if (mat != null) wall.GetComponent<Renderer>().sharedMaterial = mat;
            return wall;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. COLOSSAL 56m COMBAT FLOOR & 44m RAISED OCTAGON STAGE
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildCombatStage(Transform parent)
        {
            GameObject stageRoot = new GameObject("Central_Combat_Arena_Stage");
            stageRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var stageMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat");

            // --- 1. Base Combat Arena Ground (56m x 56m) ---
            float floorSize = 56.0f;
            GameObject baseFloor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            baseFloor.name = "Combat_Ground_Base";
            baseFloor.transform.SetParent(stageRoot.transform);
            baseFloor.transform.position = new Vector3(0f, 0.10f, 0f);
            baseFloor.transform.localScale = new Vector3(floorSize, 0.20f, floorSize);
            if (stageMat != null) baseFloor.GetComponent<Renderer>().sharedMaterial = stageMat;

            // --- 2. Raised Central Fighting Octagon Platform (44m diameter, 0.45m high) ---
            float stageSize = 44.0f;
            float stageH = 0.45f;
            GameObject raisedOctagon = GameObject.CreatePrimitive(PrimitiveType.Cube);
            raisedOctagon.name = "Raised_Octagon_Stage_Mat";
            raisedOctagon.transform.SetParent(stageRoot.transform);
            raisedOctagon.transform.position = new Vector3(0f, stageH * 0.5f, 0f);
            raisedOctagon.transform.localScale = new Vector3(stageSize, stageH, stageSize);
            if (stageMat != null) raisedOctagon.GetComponent<Renderer>().sharedMaterial = stageMat;

            // --- 3. Neon Cyber Ring Borders & Center Octagon Markings ---
            float ringY = stageH + 0.02f;
            // Outer Octagon Ring Border (Vibrant Cyan, 40m diameter)
            CreateWireframeCircle(stageRoot.transform, "Octagon_Border_Outer_Cyan", 40.0f, ringY, new Color(0f, 0.95f, 1f), 0.22f);
            // Middle Combat Ring (Electric Magenta, 24m diameter)
            CreateWireframeCircle(stageRoot.transform, "Octagon_Border_Mid_Magenta", 24.0f, ringY, new Color(1f, 0.12f, 0.78f), 0.18f);
            // Center Duel Circle (Golden Amber, 10m diameter)
            CreateWireframeCircle(stageRoot.transform, "Octagon_Center_Duel_Amber", 10.0f, ringY, new Color(1f, 0.65f, 0.05f), 0.16f);

            // --- 4. 8 In-Floor Flush Neon Runway Lines radiating from center to corners ---
            for (int r = 0; r < 8; r++)
            {
                float ang = r * 45f * Mathf.Deg2Rad;
                Vector3 start = new Vector3(Mathf.Sin(ang) * 5.0f, ringY, Mathf.Cos(ang) * 5.0f);
                Vector3 end   = new Vector3(Mathf.Sin(ang) * 20.0f, ringY, Mathf.Cos(ang) * 20.0f);
                Vector3 mid   = (start + end) * 0.5f;

                GameObject line = GameObject.CreatePrimitive(PrimitiveType.Cube);
                line.name = $"Floor_Runway_Strip_{r + 1}";
                line.transform.SetParent(stageRoot.transform);
                line.transform.position = mid;
                line.transform.LookAt(end);
                line.transform.localScale = new Vector3(0.12f, 0.02f, 15.0f);

                var rMat = new Material(litShader);
                rMat.color = new Color(0.04f, 0.06f, 0.08f);
                rMat.EnableKeyword("_EMISSION");
                Color rCol = (r % 2 == 0) ? new Color(0f, 0.92f, 1f) : new Color(1f, 0.20f, 0.85f);
                rMat.SetColor("_EmissionColor", rCol * 3.0f);
                line.GetComponent<Renderer>().sharedMaterial = rMat;
                Object.DestroyImmediate(line.GetComponent<Collider>());
            }

            // --- 5. Perimeter Heavy Hazard Barrier Curb (Border of 56m combat floor) ---
            float curbHalf = floorSize * 0.5f;
            float curbThick = 0.6f;
            float curbH = 0.5f;

            var curbMat = new Material(litShader);
            curbMat.color = new Color(0.12f, 0.12f, 0.14f);
            curbMat.EnableKeyword("_EMISSION");
            curbMat.SetColor("_EmissionColor", new Color(1f, 0.50f, 0f) * 2.2f); // Hazard amber curb

            CreateCurb(stageRoot.transform, "Curb_North", new Vector3(0f, curbH * 0.5f, curbHalf), new Vector3(floorSize, curbH, curbThick), curbMat);
            CreateCurb(stageRoot.transform, "Curb_South", new Vector3(0f, curbH * 0.5f, -curbHalf), new Vector3(floorSize, curbH, curbThick), curbMat);
            CreateCurb(stageRoot.transform, "Curb_East",  new Vector3(curbHalf, curbH * 0.5f, 0f), new Vector3(curbThick, curbH, floorSize), curbMat);
            CreateCurb(stageRoot.transform, "Curb_West",  new Vector3(-curbHalf, curbH * 0.5f, 0f), new Vector3(curbThick, curbH, floorSize), curbMat);

            return stageRoot;
        }

        private static void CreateCurb(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject curb = GameObject.CreatePrimitive(PrimitiveType.Cube);
            curb.name = name;
            curb.transform.SetParent(parent);
            curb.transform.position = pos;
            curb.transform.localScale = scale;
            curb.GetComponent<Renderer>().sharedMaterial = mat;
        }

        private static GameObject CreateWireframeCircle(Transform parent, string name, float diameter, float yPos, Color emissiveColor, float thickness)
        {
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var mat = new Material(litShader);
            mat.color = new Color(0.02f, 0.02f, 0.03f, 0.9f);
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", emissiveColor * 3.2f);

            GameObject circle = new GameObject(name);
            circle.transform.SetParent(parent);
            circle.transform.position = new Vector3(0f, yPos, 0f);

            int segments = 24;
            float radius = diameter * 0.5f;
            float angleStep = 360f / segments;

            for (int i = 0; i < segments; i++)
            {
                float a1 = i * angleStep * Mathf.Deg2Rad;
                float a2 = (i + 1) * angleStep * Mathf.Deg2Rad;
                Vector3 p1 = new Vector3(Mathf.Sin(a1) * radius, 0f, Mathf.Cos(a1) * radius);
                Vector3 p2 = new Vector3(Mathf.Sin(a2) * radius, 0f, Mathf.Cos(a2) * radius);

                Vector3 mid = (p1 + p2) * 0.5f;
                float segLen = Vector3.Distance(p1, p2);

                GameObject bar = GameObject.CreatePrimitive(PrimitiveType.Cube);
                bar.name = $"Seg_{i}";
                bar.transform.SetParent(circle.transform);
                bar.transform.position = mid + Vector3.up * 0.005f;
                bar.transform.LookAt(circle.transform.position + p2 + Vector3.up * 0.005f);
                bar.transform.localScale = new Vector3(thickness, 0.02f, segLen);
                bar.GetComponent<Renderer>().sharedMaterial = mat;
                Object.DestroyImmediate(bar.GetComponent<Collider>());
            }

            return circle;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. 10-TIER STEPPED STADIUM GRANDSTANDS (STAIRS BOWL WITH AISLES)
        // ─────────────────────────────────────────────────────────────────────
        public struct StadiumTierInfo
        {
            public int tierIndex;
            public Vector3 center;
            public Vector3 forwardDir;
            public float width;
            public float height;
        }

        private static List<StadiumTierInfo> _allBleacherTiers = new List<StadiumTierInfo>();

        private static GameObject BuildStadiumGrandstands(Transform parent)
        {
            _allBleacherTiers.Clear();

            GameObject grandstandRoot = new GameObject("Stadium_Grandstands_Amphitheater_Bowl");
            grandstandRoot.transform.SetParent(parent);

            var stepMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            string railPrefabPath = "Assets/PolygonCyberCity/Prefabs/Buildings/SM_Bld_Railing_Straight_01.prefab";
            var railPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(railPrefabPath);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            // Tier LED edge materials (alternating Cyan and Amber for sharp stadium readability)
            var ledCyanMat = new Material(litShader);
            ledCyanMat.color = new Color(0.04f, 0.08f, 0.12f);
            ledCyanMat.EnableKeyword("_EMISSION");
            ledCyanMat.SetColor("_EmissionColor", new Color(0f, 0.90f, 1f) * 3.5f);

            var ledAmberMat = new Material(litShader);
            ledAmberMat.color = new Color(0.12f, 0.06f, 0.02f);
            ledAmberMat.EnableKeyword("_EMISSION");
            ledAmberMat.SetColor("_EmissionColor", new Color(1f, 0.45f, 0.05f) * 3.5f);

            // 360-Degree Glowing Stadium Ribbon Board Material
            var ribbonMat = new Material(litShader);
            ribbonMat.color = new Color(0.05f, 0.02f, 0.10f);
            ribbonMat.EnableKeyword("_EMISSION");
            ribbonMat.SetColor("_EmissionColor", new Color(1f, 0.15f, 0.85f) * 3.8f); // Hot Magenta Ribbon Ticker

            // 10 Tiers of Stadium Seating
            // Step depth = 2.6m, step rise = 1.1m (Tier 1 is at 1.1m, Tier 10 is at 11.0m height!)
            int tierCount = 10;
            float stepDepth = 2.6f;
            float stepRise = 1.1f;
            float pitHalf = 28.5f; // Starts immediately outside the 56m combat floor

            // North Bleachers (+Z side, looking South: forward = -Z)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_North", 0f, pitHalf, stepDepth, stepRise, tierCount, 72f, Vector3.forward, Vector3.back, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // South Bleachers (-Z side, looking North: forward = +Z)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_South", 0f, -pitHalf, stepDepth, stepRise, tierCount, 72f, Vector3.back, Vector3.forward, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // East Bleachers (+X side, looking West: forward = -X)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_East", pitHalf, 0f, stepDepth, stepRise, tierCount, 68f, Vector3.right, Vector3.left, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // West Bleachers (-X side, looking East: forward = +X)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_West", -pitHalf, 0f, stepDepth, stepRise, tierCount, 68f, Vector3.left, Vector3.right, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            return grandstandRoot;
        }

        private static void BuildGrandstandSide(
            Transform parent, string sideName,
            float startX, float startZ,
            float stepDepth, float stepRise,
            int tierCount, float baseWidth,
            Vector3 outwardsDir, Vector3 lookInwardDir,
            Material stepMat, GameObject railPrefab,
            Material ledCyanMat, Material ledAmberMat,
            Material ribbonMat)
        {
            GameObject sideRoot = new GameObject(sideName);
            sideRoot.transform.SetParent(parent);

            bool isZAxis = Mathf.Abs(outwardsDir.z) > 0.5f;

            for (int t = 0; t < tierCount; t++)
            {
                float tierDist = (t + 0.5f) * stepDepth;
                float tierHeight = (t + 1) * stepRise;
                float tierW = baseWidth + t * 2.4f;

                Vector3 tierPos;
                Vector3 tierScale;

                if (isZAxis)
                {
                    float z = startZ + outwardsDir.z * tierDist;
                    tierPos = new Vector3(startX, tierHeight * 0.5f, z);
                    tierScale = new Vector3(tierW, tierHeight, stepDepth);
                }
                else
                {
                    float x = startX + outwardsDir.x * tierDist;
                    tierPos = new Vector3(x, tierHeight * 0.5f, startZ);
                    tierScale = new Vector3(stepDepth, tierHeight, tierW);
                }

                GameObject step = GameObject.CreatePrimitive(PrimitiveType.Cube);
                step.name = $"Tier_{t + 1}_Platform";
                step.transform.SetParent(sideRoot.transform);
                step.transform.position = tierPos;
                step.transform.localScale = tierScale;
                if (stepMat != null) step.GetComponent<Renderer>().sharedMaterial = stepMat;

                // --- Glowing LED Edge Strip along the front lip of each stair tier ---
                GameObject ledStrip = GameObject.CreatePrimitive(PrimitiveType.Cube);
                ledStrip.name = $"Tier_{t + 1}_LED_Edge";
                ledStrip.transform.SetParent(step.transform);

                float lipY = tierHeight;
                Vector3 ledPos;
                Vector3 ledScale;

                if (isZAxis)
                {
                    float frontZ = startZ + outwardsDir.z * (t * stepDepth);
                    ledPos = new Vector3(startX, lipY, frontZ);
                    ledScale = new Vector3(tierW, 0.08f, 0.10f);
                }
                else
                {
                    float frontX = startX + outwardsDir.x * (t * stepDepth);
                    ledPos = new Vector3(frontX, lipY, startZ);
                    ledScale = new Vector3(0.10f, 0.08f, tierW);
                }

                ledStrip.transform.position = ledPos;
                ledStrip.transform.localScale = ledScale;
                ledStrip.GetComponent<Renderer>().sharedMaterial = (t % 2 == 0) ? ledCyanMat : ledAmberMat;
                Object.DestroyImmediate(ledStrip.GetComponent<Collider>());

                // Record tier for spectator placement
                Vector3 standingCenter = tierPos + Vector3.up * (tierHeight * 0.5f);
                _allBleacherTiers.Add(new StadiumTierInfo
                {
                    tierIndex = t,
                    center = standingCenter,
                    forwardDir = lookInwardDir,
                    width = tierW,
                    height = tierHeight
                });

                // Front safety railing on Tier 1
                if (t == 0 && railPrefab != null)
                {
                    float railZ = isZAxis ? startZ : startZ - tierW * 0.5f;
                    float railX = isZAxis ? startX - tierW * 0.5f : startX;
                    float yRot = (lookInwardDir == Vector3.back) ? 180f :
                                 (lookInwardDir == Vector3.forward) ? 0f :
                                 (lookInwardDir == Vector3.left) ? 270f : 90f;

                    int railCount = Mathf.RoundToInt(tierW / 2.4f);
                    for (int ri = 0; ri < railCount; ri++)
                    {
                        Vector3 rp;
                        if (isZAxis)
                        {
                            rp = new Vector3(railX + ri * 2.4f + 1.2f, tierHeight, startZ);
                        }
                        else
                        {
                            rp = new Vector3(startX, tierHeight, railZ + ri * 2.4f + 1.2f);
                        }
                        var rail = Object.Instantiate(railPrefab, rp, Quaternion.Euler(0f, yRot, 0f), sideRoot.transform);
                        rail.name = "Front_Safety_Railing";
                    }
                }

                // Top Fascia Glowing Stadium Ribbon Board on Tier 10
                if (t == tierCount - 1)
                {
                    GameObject ribbonBoard = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    ribbonBoard.name = "Stadium_LED_Ribbon_Ticker";
                    ribbonBoard.transform.SetParent(sideRoot.transform);

                    float ribbonY = tierHeight + 0.8f;
                    if (isZAxis)
                    {
                        float backZ = startZ + outwardsDir.z * (tierCount * stepDepth);
                        ribbonBoard.transform.position = new Vector3(startX, ribbonY, backZ);
                        ribbonBoard.transform.localScale = new Vector3(tierW + 4f, 1.6f, 0.4f);
                    }
                    else
                    {
                        float backX = startX + outwardsDir.x * (tierCount * stepDepth);
                        ribbonBoard.transform.position = new Vector3(backX, ribbonY, startZ);
                        ribbonBoard.transform.localScale = new Vector3(0.4f, 1.6f, tierW + 4f);
                    }
                    ribbonBoard.GetComponent<Renderer>().sharedMaterial = ribbonMat;
                }
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 4. 4 MASSIVE 18m CORNER PYLON LIGHT TOWERS & FIGHTER ENTRANCE TUNNELS
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildCornerPylonsAndTunnels(Transform parent)
        {
            GameObject pylonsRoot = new GameObject("Arena_Corner_Pylons_And_Tunnels");
            pylonsRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            float pylonDist = 25.5f; // Corners of the 56m combat floor
            float pylonH = 18.0f;

            Vector3[] pylonPositions = new Vector3[]
            {
                new Vector3(pylonDist, 0f, pylonDist),
                new Vector3(-pylonDist, 0f, pylonDist),
                new Vector3(pylonDist, 0f, -pylonDist),
                new Vector3(-pylonDist, 0f, -pylonDist)
            };

            for (int i = 0; i < pylonPositions.Length; i++)
            {
                Vector3 basePos = pylonPositions[i];
                GameObject tower = new GameObject($"Arena_Pylon_Tower_{i + 1}");
                tower.transform.SetParent(pylonsRoot.transform);

                // Heavy Steel Lattice Column
                GameObject col = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                col.name = "Tower_Lattice_Pillar";
                col.transform.SetParent(tower.transform);
                col.transform.position = basePos + Vector3.up * (pylonH * 0.5f);
                col.transform.localScale = new Vector3(1.2f, pylonH * 0.5f, 1.2f);

                var towerMat = new Material(litShader);
                towerMat.color = new Color(0.06f, 0.08f, 0.10f);
                towerMat.EnableKeyword("_EMISSION");
                Color glowCol = (i % 2 == 0) ? new Color(0f, 0.95f, 1f) : new Color(1f, 0.20f, 0.85f);
                towerMat.SetColor("_EmissionColor", glowCol * 3.5f);
                col.GetComponent<Renderer>().sharedMaterial = towerMat;

                // Rotating Warning Beacon
                var beaconLightGo = new GameObject($"Tower_Beacon_{i + 1}");
                beaconLightGo.transform.SetParent(tower.transform);
                beaconLightGo.transform.position = basePos + Vector3.up * (pylonH + 0.5f);
                var bLight = beaconLightGo.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = glowCol;
                bLight.intensity = 6.0f;
                bLight.range = 20.0f;

                // Angled Corner Floodlight Head aimed down at the fighters
                var headGo = new GameObject($"Tower_Spotlight_Head_{i + 1}");
                headGo.transform.SetParent(tower.transform);
                headGo.transform.position = basePos + Vector3.up * (pylonH - 1.0f);
                headGo.transform.LookAt(Vector3.zero + Vector3.up * 0.5f);

                var sLight = headGo.AddComponent<Light>();
                sLight.type = LightType.Spot;
                sLight.color = glowCol;
                sLight.intensity = 28.0f;
                sLight.range = 45.0f;
                sLight.spotAngle = 45.0f;
                sLight.innerSpotAngle = 25.0f;
                sLight.shadows = LightShadows.Soft;
            }

            // --- Red Corner (South-West) & Blue Corner (North-East) Fighter Entrance Tunnels ---
            BuildFighterTunnel(pylonsRoot.transform, "Red_Corner_Fighter_Entrance", new Vector3(-20f, 0f, -28.5f), new Color(1f, 0.10f, 0.15f), "RED CORNER");
            BuildFighterTunnel(pylonsRoot.transform, "Blue_Corner_Fighter_Entrance", new Vector3(20f, 0f, 28.5f), new Color(0.10f, 0.50f, 1f), "BLUE CORNER");
        }

