            // Tunnel Entrance Spot
            var lightGo = new GameObject("Tunnel_Spot");
            lightGo.transform.SetParent(tunnel.transform);
            lightGo.transform.position = pos + new Vector3(0f, 4.0f, 0f);
            var spot = lightGo.AddComponent<Light>();
            spot.type = LightType.Spot;
            spot.color = teamColor;
            spot.intensity = 15.0f;
            spot.range = 14.0f;
            spot.spotAngle = 70.0f;
