        private static void BuildJumbotronAndTrusses(Transform parent)
        {
            GameObject rigRoot = new GameObject("Arena_Overhead_Jumbotron_And_Trusses");
            rigRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
