            // --- 1. Overhead Structural Steel Trusses (9 massive bridge trusses across the 140m roof) ---
            for (int ti = -4; ti <= 4; ti++)
            {
                GameObject truss = GameObject.CreatePrimitive(PrimitiveType.Cube);
                truss.name = $"Overhead_Truss_{ti}";
                truss.transform.SetParent(rigRoot.transform);
                truss.transform.position = new Vector3(ti * 14.0f, 29.5f, 0f);
                truss.transform.localScale = new Vector3(1.2f, 2.4f, 136f);
                if (wallMat != null) truss.GetComponent<Renderer>().sharedMaterial = wallMat;
            }

            // --- 2. Hanging Central 4-Sided Jumbotron Scoreboard Rig (Y = 19m to 25m) ---
            GameObject jumbotron = new GameObject("Center_Hanging_Jumbotron_Cube");
            jumbotron.transform.SetParent(rigRoot.transform);
            jumbotron.transform.position = new Vector3(0f, 21.0f, 0f);

            float jboxSize = 14.0f;
            float jboxHeight = 6.0f;

            // Core Housing
            GameObject jCore = GameObject.CreatePrimitive(PrimitiveType.Cube);
            jCore.name = "Jumbotron_Housing_Core";
            jCore.transform.SetParent(jumbotron.transform);
            jCore.transform.position = new Vector3(0f, 21.0f, 0f);
            jCore.transform.localScale = new Vector3(jboxSize, jboxHeight, jboxSize);
            if (wallMat != null) jCore.GetComponent<Renderer>().sharedMaterial = wallMat;

            // 4 Giant Digital LED Video Screens facing North, South, East, West
            var screenMat = new Material(litShader);
            screenMat.color = new Color(0.02f, 0.05f, 0.12f);
            screenMat.EnableKeyword("_EMISSION");
            screenMat.SetColor("_EmissionColor", new Color(0f, 0.85f, 1f) * 3.2f); // Electric Cyan Broadcast Screen

            float screenThick = 0.15f;
            float screenOffset = jboxSize * 0.5f + 0.1f;

            CreateJumbotronScreen(jumbotron.transform, "Screen_North", new Vector3(0f, 21.0f, screenOffset), new Vector3(jboxSize - 1.2f, jboxHeight - 1.0f, screenThick), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_South", new Vector3(0f, 21.0f, -screenOffset), new Vector3(jboxSize - 1.2f, jboxHeight - 1.0f, screenThick), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_East",  new Vector3(screenOffset, 21.0f, 0f), new Vector3(screenThick, jboxHeight - 1.0f, jboxSize - 1.2f), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_West",  new Vector3(-screenOffset, 21.0f, 0f), new Vector3(screenThick, jboxHeight - 1.0f, jboxSize - 1.2f), screenMat);

            // Jumbotron Ring Loudspeaker / Underglow Accent
            var ringMat = new Material(litShader);
            ringMat.color = new Color(0.04f, 0.02f, 0.08f);
            ringMat.EnableKeyword("_EMISSION");
            ringMat.SetColor("_EmissionColor", new Color(1f, 0.15f, 0.75f) * 4.0f);

            GameObject underglowRing = GameObject.CreatePrimitive(PrimitiveType.Cube);
            underglowRing.name = "Jumbotron_Underglow_Ring";
            underglowRing.transform.SetParent(jumbotron.transform);
            underglowRing.transform.position = new Vector3(0f, 17.8f, 0f);
            underglowRing.transform.localScale = new Vector3(jboxSize + 1.2f, 0.35f, jboxSize + 1.2f);
            underglowRing.GetComponent<Renderer>().sharedMaterial = ringMat;
            Object.DestroyImmediate(underglowRing.GetComponent<Collider>());

            // Suspended Holographic Dragon hovering above the Jumbotron
            string dragonPath = "Assets/PolygonCyberCity/Prefabs/FX/Hologram_Dragon_01.prefab";
            var dragonPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(dragonPath);
            if (dragonPrefab != null)
            {
                var dragon = Object.Instantiate(dragonPrefab, new Vector3(0f, 25.5f, 0f), Quaternion.Euler(0f, 45f, 0f), jumbotron.transform);
