using UnityEngine.Rendering.Universal;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Check if there is a Volume in the current scene
        var vol = Object.FindFirstObjectByType<Volume>();
        if (vol == null)
        {
            var volGo = new GameObject("Stadium_Global_PostProcess_Volume");
            vol = volGo.AddComponent<Volume>();
            vol.isGlobal = true;
            vol.priority = 100;

            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            profile.name = "Stadium_Live_VolumeProfile";

            // Add Bloom
            var bloom = profile.Add<Bloom>(true);
            bloom.intensity.value = 1.4f;
            bloom.threshold.value = 0.85f;
            bloom.scatter.value = 0.70f;

            // Add Color Adjustments
            var ca = profile.Add<ColorAdjustments>(true);
            ca.contrast.value = 22f;
            ca.saturation.value = 18f;
            ca.postExposure.value = 0.35f;

            // Add Tonemapping
            var tm = profile.Add<Tonemapping>(true);
            tm.mode.value = TonemappingMode.ACES;

            vol.profile = profile;
            result.Log("Created Stadium_Global_PostProcess_Volume with Bloom & ACES Tonemapping!");
        }
        else
        {
            result.Log("Found existing Volume: {0}", vol.name);
        }
    }
}

