using System.Collections.Generic;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using InsaneGun.Combat;
using InsaneGun.Testing;
using InsaneGun.Arena;

namespace InsaneGun.EditorTools
{
    /// <summary>
    /// Builds a world-class, AAA-quality Cyberpunk Championship Fight Stadium / Colosseum.
    /// 
    /// Features:
    /// - 110m x 110m x 30m brutalist stadium enclosure with roof shadow casting disabled for full lighting.
    /// - 22m x 22m raised combat ring (0.8m high) with corner turnbuckles, glowing neon ring ropes,
    ///   metal access stairs, and central cyber octagon emblem canvas.
    /// - Ringside perimeter with heavy crowd control barricades and broadcast equipment.
    /// - 10-Tier steep amphitheater grandstand bowl (15m to 46m distance, rising to 11.5m height)
    ///   so the cheering crowd wraps intimately around the fighting ring!
    /// - Every single tier step features illuminated dual-tone neon LED edge strips (Cyan & Amber).
    /// - 360-degree digital LED ribbon board running along the grandstand upper fascia.
    /// - Center-hung 4-sided digital Jumbotron scoreboard (10m wide) hanging at Y = 13.5m over the ring.
    /// - Hanging circular lighting truss ring with 12 high-powered stadium spotlights illuminating the ring canvas.
    /// - 8 Dedicated stadium crowd floodlights illuminating all 10 spectator tiers.
    /// - 4 Massive 16m corner pylon towers with searchlight beams and rotating beacons.
    /// - 500+ Diverse Cyberpunk spectator NPCs placed on the tiers in active cheering/fist-pumping/recording poses.
    /// - Full URP Global Post-Processing Volume with Bloom (1.35) and ACES Tonemapping for glowing neon aesthetics.
    /// - Alita Battle Angel player combatant with Damascus Blade and SmoothOrbitCamera calibrated for combat.
    /// </summary>
    public static class CyberpunkIndoorArenaBuilder
    {
        private const string ScenePath = "Assets/Scenes/Cyberpunk_Indoor_Combat_Arena.unity";
        private const string TestArenaPath = "Assets/Scenes/InsaneGun_Combat_TestArena.unity";
        private const string ControllerDir = "Assets/Animations/Spectators";

        [MenuItem("Tools/Cyberpunk/Build Indoor Fight Arena (Closed Building + Cheering Crowd)")]
        public static void BuildIndoorArenaMenu()
        {
            BuildAndSaveScene(ScenePath);
            BuildAndSaveScene(TestArenaPath);
        }

        public static void BuildAndSaveScene(string targetScenePath)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            scene.name = Path.GetFileNameWithoutExtension(targetScenePath);

            EnsureDirectories();
            var spectatorControllers = EnsureSpectatorControllers();

            // 1. Building Enclosure (110m x 110m x 30m)
            GameObject stadiumRoot = BuildStadiumEnclosure();

            // 2. Global Post-Processing Volume (Bloom, ACES Tonemapping, Color Grading)
            BuildPostProcessingVolume(stadiumRoot.transform);

            // 3. Central Competition Fighting Ring (22m x 22m raised platform with neon ropes & turnbuckles)
            GameObject ringRoot = BuildCompetitionFightRing(stadiumRoot.transform);

            // 4. Ringside Barricades & Broadcast Zone (around 13m perimeter)
            BuildRingsideBarricades(stadiumRoot.transform);

            // 5. 10-Tier Stepped Stadium Grandstands (wrapping from 15m to 46m)
            GameObject grandstandsRoot = BuildStadiumGrandstands(stadiumRoot.transform);

            // 6. Center-Hung Overhead Jumbotron Scoreboard Rig (Y = 13.5m) & Truss Ring
            BuildCenterHungJumbotronAndTrusses(stadiumRoot.transform);

            // 7. 4 Massive Corner Pylon Lighting Towers (at 20m corners)
            BuildCornerPylonTowers(stadiumRoot.transform);

            // 8. Professional Stadium Broadcast Lighting Rig
            BuildStadiumLighting(stadiumRoot.transform);

            // 9. 500+ Spectator NPCs placed across the Grandstands
            GameObject crowdRoot = BuildSpectatorCrowd(stadiumRoot.transform, spectatorControllers);

            // 10. Spawn Combatants (Alita Hero + Rival Duelist inside the ring)
            var (player, rival) = SpawnCombatants(ringRoot.transform);

            // 11. Connect Spectators to Combatants
            ConnectSpectatorsToCombat(crowdRoot, rival != null ? rival.transform : null);

            // 12. Setup Smooth Orbit Camera
            SetupIndoorCamera(player.transform, stadiumRoot.transform);

            // 13. Add Arena Combat Manager & BGM Audio
            SetupArenaManager(player, rival, stadiumRoot.transform);

            // 14. Mark and Save Scene
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, targetScenePath);
            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log($"<color=#00FFFF>[CyberpunkArena] World-Class Championship Fight Stadium successfully built at: {targetScenePath}</color>");
        }

        private static void EnsureDirectories()
        {
            if (!Directory.Exists("Assets/Scenes")) Directory.CreateDirectory("Assets/Scenes");
            if (!Directory.Exists(ControllerDir)) Directory.CreateDirectory(ControllerDir);
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. STADIUM ENCLOSURE (110m x 110m x 30m)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildStadiumEnclosure()
        {
            GameObject root = new GameObject("Championship_Stadium_Complex");

            var floorMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat")
                        ?? AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            var wallMat  = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Wall_01.mat")
                        ?? floorMat;
            var ceilingMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Ceiling_01.mat")
                          ?? floorMat;

            float stadiumW = 110f;
            float stadiumH = 30f;
            float halfDist = stadiumW * 0.5f;

            // --- Floor Slab (110m x 110m) ---
            GameObject floor = GameObject.CreatePrimitive(PrimitiveType.Cube);
            floor.name = "Stadium_Foundation_Floor";
            floor.transform.SetParent(root.transform);
            floor.transform.position = new Vector3(0f, -0.5f, 0f);
            floor.transform.localScale = new Vector3(stadiumW, 1.0f, stadiumW);
            if (floorMat != null) floor.GetComponent<Renderer>().sharedMaterial = floorMat;

            // --- Roof / Ceiling (Shadow Casting OFF so interior receives directional fill!) ---
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ceiling.name = "Stadium_Dome_Ceiling";
            ceiling.transform.SetParent(root.transform);
            ceiling.transform.position = new Vector3(0f, stadiumH, 0f);
            ceiling.transform.localScale = new Vector3(stadiumW, 1.2f, stadiumW);
            if (ceilingMat != null) ceiling.GetComponent<Renderer>().sharedMaterial = ceilingMat;
            var cRend = ceiling.GetComponent<Renderer>();
            if (cRend != null) cRend.shadowCastingMode = ShadowCastingMode.Off; // Critical for indoor directional light!

            // --- 4 Perimeter Stadium Walls ---
            float wallThick = 2.0f;
            float wallCenterY = stadiumH * 0.5f;

            CreateWall(root.transform, "Wall_North", new Vector3(0f, wallCenterY, halfDist), new Vector3(stadiumW, stadiumH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_South", new Vector3(0f, wallCenterY, -halfDist), new Vector3(stadiumW, stadiumH, wallThick), wallMat);
            CreateWall(root.transform, "Wall_East",  new Vector3(halfDist, wallCenterY, 0f), new Vector3(wallThick, stadiumH, stadiumW), wallMat);
            CreateWall(root.transform, "Wall_West",  new Vector3(-halfDist, wallCenterY, 0f), new Vector3(wallThick, stadiumH, stadiumW), wallMat);

            // --- Wall Holographic Advertisements & Jumbotron Billboards ---
            string[] holoPrefabs = new[]
            {
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_01.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_04.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_07.prefab",
                "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_10.prefab"
            };

            for (int s = 0; s < 4; s++)
            {
                float rotY = s * 90f;
                float dist = stadiumW * 0.5f - 2.5f;

                for (int h = -1; h <= 1; h++)
                {
                    string hPath = holoPrefabs[Mathf.Abs(s + h + 4) % holoPrefabs.Length];
                    var pref = AssetDatabase.LoadAssetAtPath<GameObject>(hPath);
                    if (pref != null)
                    {
                        Vector3 hp;
                        if (s == 0) hp = new Vector3(h * 28f, 21.0f, dist);
                        else if (s == 1) hp = new Vector3(dist, 21.0f, h * 28f);
                        else if (s == 2) hp = new Vector3(h * 28f, 21.0f, -dist);
                        else hp = new Vector3(-dist, 21.0f, h * 28f);

                        var go = Object.Instantiate(pref, hp, Quaternion.Euler(0f, rotY + 180f, 0f), root.transform);
                        go.name = $"Wall_Holo_Billboard_{s}_{h}";
                        go.transform.localScale = Vector3.one * 5.0f;
                    }
                }
            }

            return root;
        }

        private static GameObject CreateWall(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject wall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            wall.name = name;
            wall.transform.SetParent(parent);
            wall.transform.position = pos;
            wall.transform.localScale = scale;
            if (mat != null) wall.GetComponent<Renderer>().sharedMaterial = mat;
            var r = wall.GetComponent<Renderer>();
            if (r != null) r.shadowCastingMode = ShadowCastingMode.Off;
            return wall;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. GLOBAL POST-PROCESSING VOLUME (BLOOM & ACES TONEMAPPING)
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildPostProcessingVolume(Transform parent)
        {
            var volGo = new GameObject("Stadium_Global_PostProcess_Volume");
            volGo.transform.SetParent(parent);

            var vol = volGo.AddComponent<Volume>();
            vol.isGlobal = true;
            vol.priority = 100;

            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            profile.name = "Stadium_Championship_VolumeProfile";

            // Bloom for glowing neon lines, jumbotron, and lights
            var bloom = profile.Add<Bloom>(true);
            bloom.intensity.value = 1.35f;
            bloom.threshold.value = 0.85f;
            bloom.scatter.value = 0.70f;

            // Rich contrast & saturation
            var ca = profile.Add<ColorAdjustments>(true);
            ca.contrast.value = 22f;
            ca.saturation.value = 18f;
            ca.postExposure.value = 0.40f;

            // ACES Cinematic Tonemapping
            var tm = profile.Add<Tonemapping>(true);
            tm.mode.value = TonemappingMode.ACES;

            vol.profile = profile;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. CENTRAL COMPETITION FIGHTING RING (22m x 22m RAISED OCTAGON)
        // ─────────────────────────────────────────────────────────────────────
        private static GameObject BuildCompetitionFightRing(Transform parent)
        {
            GameObject ringRoot = new GameObject("Competition_Fight_Ring_Octagon");
            ringRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var canvasMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_02.mat");

            float ringSize = 22.0f;
            float stageHeight = 0.80f;

            // --- 1. Raised Fighting Ring Platform (22m x 22m, 0.8m high) ---
            GameObject ringStage = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ringStage.name = "Raised_Ring_Stage_Platform";
            ringStage.transform.SetParent(ringRoot.transform);
            ringStage.transform.position = new Vector3(0f, stageHeight * 0.5f, 0f);
            ringStage.transform.localScale = new Vector3(ringSize, stageHeight, ringSize);
            if (canvasMat != null) ringStage.GetComponent<Renderer>().sharedMaterial = canvasMat;

            // Ring Apron Skirt (Dark Carbon with Glowing Hazard Warning Border)
            var apronMat = new Material(litShader);
            apronMat.color = new Color(0.10f, 0.10f, 0.12f);
            apronMat.EnableKeyword("_EMISSION");
            apronMat.SetColor("_EmissionColor", new Color(1f, 0.45f, 0f) * 2.8f);

            GameObject apronBorder = GameObject.CreatePrimitive(PrimitiveType.Cube);
            apronBorder.name = "Ring_Apron_Hazard_Border";
            apronBorder.transform.SetParent(ringRoot.transform);
            apronBorder.transform.position = new Vector3(0f, stageHeight + 0.02f, 0f);
            apronBorder.transform.localScale = new Vector3(ringSize + 0.4f, 0.04f, ringSize + 0.4f);
            apronBorder.GetComponent<Renderer>().sharedMaterial = apronMat;
            Object.DestroyImmediate(apronBorder.GetComponent<Collider>());

            // --- 2. In-Ring Glowing Cyber Octagon Markings ---
            float ringY = stageHeight + 0.03f;
            CreateWireframeCircle(ringRoot.transform, "Octagon_Canvas_Outer_Cyan", 18.0f, ringY, new Color(0f, 0.95f, 1f), 0.18f);
            CreateWireframeCircle(ringRoot.transform, "Octagon_Canvas_Mid_Magenta", 11.0f, ringY, new Color(1f, 0.12f, 0.78f), 0.15f);
            CreateWireframeCircle(ringRoot.transform, "Octagon_Canvas_Center_Amber", 5.0f, ringY, new Color(1f, 0.65f, 0.05f), 0.12f);

            // --- 3. 4 Heavy Corner Turnbuckle Posts & Glowing Ring Ropes ---
            float halfR = ringSize * 0.5f - 0.5f;
            Vector3[] postCorners = new[]
            {
                new Vector3(halfR, stageHeight, halfR),
                new Vector3(-halfR, stageHeight, halfR),
                new Vector3(-halfR, stageHeight, -halfR),
                new Vector3(halfR, stageHeight, -halfR)
            };

            Color[] cornerColors = new[]
            {
                new Color(0.10f, 0.60f, 1f), // Blue Corner (North-East)
                new Color(1f, 0.15f, 0.75f), // Purple Corner (North-West)
                new Color(1f, 0.10f, 0.15f), // Red Corner (South-West)
                new Color(0f, 0.95f, 1f)     // Cyan Corner (South-East)
            };

            for (int i = 0; i < 4; i++)
            {
                Vector3 pPos = postCorners[i];
                Color cCol = cornerColors[i];

                // Turnbuckle Steel Post (3.2m high from canvas)
                GameObject post = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                post.name = $"Ring_Turnbuckle_Post_{i + 1}";
                post.transform.SetParent(ringRoot.transform);
                post.transform.position = pPos + Vector3.up * 1.6f;
                post.transform.localScale = new Vector3(0.55f, 1.6f, 0.55f);

                var pMat = new Material(litShader);
                pMat.color = new Color(0.08f, 0.08f, 0.10f);
                pMat.EnableKeyword("_EMISSION");
                pMat.SetColor("_EmissionColor", cCol * 3.5f);
                post.GetComponent<Renderer>().sharedMaterial = pMat;

                // Corner Top Beacon
                var beaconGo = new GameObject($"Corner_Beacon_{i + 1}");
                beaconGo.transform.SetParent(post.transform);
                beaconGo.transform.position = pPos + Vector3.up * 3.4f;
                var bLight = beaconGo.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = cCol;
                bLight.intensity = 4.5f;
                bLight.range = 10.0f;

                // 3 Tiers of Glowing Ring Tension Ropes (at 0.8m, 1.6m, 2.4m height above canvas)
                Vector3 nextPos = postCorners[(i + 1) % 4];
                for (int r = 1; r <= 3; r++)
                {
                    float ropeH = stageHeight + r * 0.75f;
                    Vector3 rStart = new Vector3(pPos.x, ropeH, pPos.z);
                    Vector3 rEnd   = new Vector3(nextPos.x, ropeH, nextPos.z);
                    Vector3 rMid   = (rStart + rEnd) * 0.5f;
                    float rLen     = Vector3.Distance(rStart, rEnd);

                    GameObject rope = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    rope.name = $"Ring_Rope_Side_{i}_Tier_{r}";
                    rope.transform.SetParent(ringRoot.transform);
                    rope.transform.position = rMid;
                    rope.transform.LookAt(rEnd);
                    rope.transform.localScale = new Vector3(0.06f, 0.06f, rLen);

                    var ropeMat = new Material(litShader);
                    ropeMat.color = new Color(0.05f, 0.05f, 0.08f);
                    ropeMat.EnableKeyword("_EMISSION");
                    ropeMat.SetColor("_EmissionColor", (r % 2 == 1 ? new Color(0f, 0.95f, 1f) : new Color(1f, 0.15f, 0.80f)) * 3.5f);
                    rope.GetComponent<Renderer>().sharedMaterial = ropeMat;
                    Object.DestroyImmediate(rope.GetComponent<Collider>());
                }
            }

            // --- 4. Metal Access Stairs leading up to the ring (North and South) ---
            BuildRingStairs(ringRoot.transform, new Vector3(0f, 0f, halfR + 0.9f), Quaternion.identity, stageHeight);
            BuildRingStairs(ringRoot.transform, new Vector3(0f, 0f, -halfR - 0.9f), Quaternion.Euler(0f, 180f, 0f), stageHeight);

            return ringRoot;
        }

        private static void BuildRingStairs(Transform parent, Vector3 pos, Quaternion rot, float targetHeight)
        {
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var mat = new Material(litShader);
            mat.color = new Color(0.12f, 0.14f, 0.18f);

            GameObject stairsRoot = new GameObject("Ring_Access_Stairs");
            stairsRoot.transform.SetParent(parent);
            stairsRoot.transform.position = pos;
            stairsRoot.transform.rotation = rot;

            int steps = 3;
            float stepRise = targetHeight / steps;
            float stepRun = 0.45f;
            float width = 3.2f;

            for (int s = 0; s < steps; s++)
            {
                GameObject step = GameObject.CreatePrimitive(PrimitiveType.Cube);
                step.name = $"Step_{s + 1}";
                step.transform.SetParent(stairsRoot.transform);
                step.transform.localPosition = new Vector3(0f, (s + 0.5f) * stepRise, (steps - 1 - s) * stepRun);
                step.transform.localScale = new Vector3(width, stepRise, stepRun);
                step.GetComponent<Renderer>().sharedMaterial = mat;
            }
        }

        private static GameObject CreateWireframeCircle(Transform parent, string name, float diameter, float yPos, Color emissiveColor, float thickness)
        {
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var mat = new Material(litShader);
            mat.color = new Color(0.02f, 0.02f, 0.03f, 0.9f);
            mat.EnableKeyword("_EMISSION");
            mat.SetColor("_EmissionColor", emissiveColor * 3.8f);

            GameObject circle = new GameObject(name);
            circle.transform.SetParent(parent);
            circle.transform.position = new Vector3(0f, yPos, 0f);

            int segments = 24;
            float radius = diameter * 0.5f;
            float angleStep = 360f / segments;

            for (int i = 0; i < segments; i++)
            {
                float a1 = i * angleStep * Mathf.Deg2Rad;
                float a2 = (i + 1) * angleStep * Mathf.Deg2Rad;
                Vector3 p1 = new Vector3(Mathf.Sin(a1) * radius, 0f, Mathf.Cos(a1) * radius);
                Vector3 p2 = new Vector3(Mathf.Sin(a2) * radius, 0f, Mathf.Cos(a2) * radius);

                Vector3 mid = (p1 + p2) * 0.5f;
                float segLen = Vector3.Distance(p1, p2);

                GameObject bar = GameObject.CreatePrimitive(PrimitiveType.Cube);
                bar.name = $"Seg_{i}";
                bar.transform.SetParent(circle.transform);
                bar.transform.position = mid + Vector3.up * 0.005f;
                bar.transform.LookAt(circle.transform.position + p2 + Vector3.up * 0.005f);
                bar.transform.localScale = new Vector3(thickness, 0.02f, segLen);
                bar.GetComponent<Renderer>().sharedMaterial = mat;
                Object.DestroyImmediate(bar.GetComponent<Collider>());
            }

            return circle;
        }

