        // ─────────────────────────────────────────────────────────────────────
        // 5. 10-TIER STADIUM GRANDSTANDS (WRAPPING FROM 15m TO 46m)
        // ─────────────────────────────────────────────────────────────────────
        public struct GrandstandTierInfo
        {
            public int tierIndex;
            public Vector3 center;
            public Vector3 forwardDir;
            public float width;
            public float height;
        }

        private static List<GrandstandTierInfo> _allBleacherTiers = new List<GrandstandTierInfo>();

        private static GameObject BuildStadiumGrandstands(Transform parent)
        {
            _allBleacherTiers.Clear();

            GameObject grandstandRoot = new GameObject("Stadium_Grandstands_Amphitheater_Bowl");
            grandstandRoot.transform.SetParent(parent);

            var stepMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/PolygonCyberCity/Materials/Building/Floor_01.mat");
            string railPrefabPath = "Assets/PolygonCyberCity/Prefabs/Buildings/SM_Bld_Railing_Straight_01.prefab";
            var railPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(railPrefabPath);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            // Alternating Glowing LED Edge Strips for EVERY tier step!
            var ledCyanMat = new Material(litShader);
            ledCyanMat.color = new Color(0.04f, 0.08f, 0.12f);
            ledCyanMat.EnableKeyword("_EMISSION");
            ledCyanMat.SetColor("_EmissionColor", new Color(0f, 0.95f, 1f) * 4.2f);

            var ledAmberMat = new Material(litShader);
            ledAmberMat.color = new Color(0.12f, 0.06f, 0.02f);
            ledAmberMat.EnableKeyword("_EMISSION");
            ledAmberMat.SetColor("_EmissionColor", new Color(1f, 0.50f, 0.05f) * 4.2f);

            // 360-degree Stadium Digital Ribbon Ticker
            var ribbonMat = new Material(litShader);
            ribbonMat.color = new Color(0.05f, 0.02f, 0.10f);
            ribbonMat.EnableKeyword("_EMISSION");
            ribbonMat.SetColor("_EmissionColor", new Color(1f, 0.12f, 0.85f) * 4.5f);

            // Grandstands: 10 Tiers rising from 15m out to 46m!
            // Depth = 3.0m, Rise = 1.15m per tier (Tier 1 is at 1.15m, Tier 10 is at 11.5m!)
            int tierCount = 10;
            float stepDepth = 3.0f;
            float stepRise = 1.15f;
            float pitHalf = 15.0f; // Intimate 15m distance from ring center!

            // North Bleachers (+Z side, looking South: forward = -Z)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_North", 0f, pitHalf, stepDepth, stepRise, tierCount, 38f, Vector3.forward, Vector3.back, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // South Bleachers (-Z side, looking North: forward = +Z)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_South", 0f, -pitHalf, stepDepth, stepRise, tierCount, 38f, Vector3.back, Vector3.forward, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // East Bleachers (+X side, looking West: forward = -X)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_East", pitHalf, 0f, stepDepth, stepRise, tierCount, 38f, Vector3.right, Vector3.left, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            // West Bleachers (-X side, looking East: forward = +X)
            BuildGrandstandSide(grandstandRoot.transform, "Grandstand_West", -pitHalf, 0f, stepDepth, stepRise, tierCount, 38f, Vector3.left, Vector3.right, stepMat, railPrefab, ledCyanMat, ledAmberMat, ribbonMat);

            return grandstandRoot;
        }

        private static void BuildGrandstandSide(
            Transform parent, string sideName,
            float startX, float startZ,
            float stepDepth, float stepRise,
            int tierCount, float baseWidth,
            Vector3 outwardsDir, Vector3 lookInwardDir,
            Material stepMat, GameObject railPrefab,
            Material ledCyanMat, Material ledAmberMat,
            Material ribbonMat)
        {
            GameObject sideRoot = new GameObject(sideName);
            sideRoot.transform.SetParent(parent);

            bool isZAxis = Mathf.Abs(outwardsDir.z) > 0.5f;

            for (int t = 0; t < tierCount; t++)
            {
                float tierDist = (t + 0.5f) * stepDepth;
                float tierHeight = (t + 1) * stepRise;
                float tierW = baseWidth + t * 4.8f; // Expands outward like a true amphitheater!

                Vector3 tierPos;
                Vector3 tierScale;

                if (isZAxis)
                {
                    float z = startZ + outwardsDir.z * tierDist;
                    tierPos = new Vector3(startX, tierHeight * 0.5f, z);
                    tierScale = new Vector3(tierW, tierHeight, stepDepth);
                }
                else
                {
                    float x = startX + outwardsDir.x * tierDist;
                    tierPos = new Vector3(x, tierHeight * 0.5f, startZ);
                    tierScale = new Vector3(stepDepth, tierHeight, tierW);
                }

                GameObject step = GameObject.CreatePrimitive(PrimitiveType.Cube);
                step.name = $"Tier_{t + 1}_Platform";
                step.transform.SetParent(sideRoot.transform);
                step.transform.position = tierPos;
                step.transform.localScale = tierScale;
                if (stepMat != null) step.GetComponent<Renderer>().sharedMaterial = stepMat;

                // --- Glowing LED Edge Strip along the front lip of each tier step ---
                GameObject ledStrip = GameObject.CreatePrimitive(PrimitiveType.Cube);
                ledStrip.name = $"Tier_{t + 1}_LED_Edge";
                ledStrip.transform.SetParent(sideRoot.transform); // Parent to sideRoot to avoid parent scale distortion!

                float lipY = tierHeight + 0.04f;
                Vector3 ledPos;
                Vector3 ledScale;

                if (isZAxis)
                {
                    float frontZ = startZ + outwardsDir.z * (t * stepDepth);
                    ledPos = new Vector3(startX, lipY, frontZ);
                    ledScale = new Vector3(tierW, 0.08f, 0.12f);
                }
                else
                {
                    float frontX = startX + outwardsDir.x * (t * stepDepth);
                    ledPos = new Vector3(frontX, lipY, startZ);
                    ledScale = new Vector3(0.12f, 0.08f, tierW);
                }

                ledStrip.transform.position = ledPos;
                ledStrip.transform.localScale = ledScale;
                ledStrip.GetComponent<Renderer>().sharedMaterial = (t % 2 == 0) ? ledCyanMat : ledAmberMat;
                Object.DestroyImmediate(ledStrip.GetComponent<Collider>());

                // Record tier info for spectator placement
                Vector3 standingCenter = tierPos + Vector3.up * (tierHeight * 0.5f);
                _allBleacherTiers.Add(new GrandstandTierInfo
                {
                    tierIndex = t,
                    center = standingCenter,
                    forwardDir = lookInwardDir,
                    width = tierW,
                    height = tierHeight
                });

                // Front safety railing on Tier 1
                if (t == 0 && railPrefab != null)
                {
                    float railZ = isZAxis ? startZ : startZ - tierW * 0.5f;
                    float railX = isZAxis ? startX - tierW * 0.5f : startX;
                    float yRot = (lookInwardDir == Vector3.back) ? 180f :
                                 (lookInwardDir == Vector3.forward) ? 0f :
                                 (lookInwardDir == Vector3.left) ? 270f : 90f;

                    int railCount = Mathf.RoundToInt(tierW / 2.4f);
                    for (int ri = 0; ri < railCount; ri++)
                    {
                        Vector3 rp;
                        if (isZAxis)
                        {
                            rp = new Vector3(railX + ri * 2.4f + 1.2f, tierHeight, startZ);
                        }
                        else
                        {
                            rp = new Vector3(startX, tierHeight, railZ + ri * 2.4f + 1.2f);
                        }
                        var rail = Object.Instantiate(railPrefab, rp, Quaternion.Euler(0f, yRot, 0f), sideRoot.transform);
                        rail.name = "Front_Safety_Railing";
                    }
                }

                // 360-Degree Digital LED Ribbon Ticker along Tier 10 Parapet
                if (t == tierCount - 1)
                {
                    GameObject ribbonBoard = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    ribbonBoard.name = "Stadium_LED_Ribbon_Ticker";
                    ribbonBoard.transform.SetParent(sideRoot.transform);

                    float ribbonY = tierHeight + 0.9f;
                    if (isZAxis)
                    {
                        float backZ = startZ + outwardsDir.z * (tierCount * stepDepth);
                        ribbonBoard.transform.position = new Vector3(startX, ribbonY, backZ);
                        ribbonBoard.transform.localScale = new Vector3(tierW + 6f, 1.8f, 0.4f);
                    }
                    else
                    {
                        float backX = startX + outwardsDir.x * (tierCount * stepDepth);
                        ribbonBoard.transform.position = new Vector3(backX, ribbonY, startZ);
                        ribbonBoard.transform.localScale = new Vector3(0.4f, 1.8f, tierW + 6f);
                    }
                    ribbonBoard.GetComponent<Renderer>().sharedMaterial = ribbonMat;
                }
            }
        }

