            CreateJumbotronScreen(jumbotron.transform, "Screen_North", new Vector3(0f, 13.5f, sOffset), new Vector3(jSize - 1.0f, jHeight - 0.8f, sThick), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_South", new Vector3(0f, 13.5f, -sOffset), new Vector3(jSize - 1.0f, jHeight - 0.8f, sThick), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_East",  new Vector3(sOffset, 13.5f, 0f), new Vector3(sThick, jHeight - 0.8f, jSize - 1.0f), screenMat);
            CreateJumbotronScreen(jumbotron.transform, "Screen_West",  new Vector3(-sOffset, 13.5f, 0f), new Vector3(sThick, jHeight - 0.8f, jSize - 1.0f), screenMat);

            // Jumbotron Bottom Halo Ring (Hot Magenta Underglow)
            var haloMat = new Material(litShader);
            haloMat.color = new Color(0.05f, 0.02f, 0.08f);
