        private static void CreateJumbotronScreen(Transform parent, string name, Vector3 pos, Vector3 scale, Material mat)
        {
            GameObject screen = GameObject.CreatePrimitive(PrimitiveType.Cube);
            screen.name = name;
            screen.transform.SetParent(parent);
            screen.transform.position = pos;
            screen.transform.localScale = scale;
            screen.GetComponent<Renderer>().sharedMaterial = mat;
            Object.DestroyImmediate(screen.GetComponent<Collider>());
        }

        // ─────────────────────────────────────────────────────────────────────
        // 7. 4 CORNER PYLON LIGHTING TOWERS (16m HIGH AT 20m CORNERS)
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildCornerPylonTowers(Transform parent)
        {
            GameObject pylonsRoot = new GameObject("Arena_Corner_Lighting_Pylons");
            pylonsRoot.transform.SetParent(parent);

            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");

            float pylonDist = 18.5f;
            float pylonH = 16.0f;

            Vector3[] pylonPositions = new[]
            {
                new Vector3(pylonDist, 0f, pylonDist),
                new Vector3(-pylonDist, 0f, pylonDist),
                new Vector3(-pylonDist, 0f, -pylonDist),
                new Vector3(pylonDist, 0f, -pylonDist)
            };

            Color[] pylonColors = new[]
            {
                new Color(0f, 0.95f, 1f),
                new Color(1f, 0.15f, 0.85f),
                new Color(1f, 0.50f, 0.05f),
                new Color(0f, 0.95f, 1f)
            };

            for (int i = 0; i < 4; i++)
            {
                Vector3 pPos = pylonPositions[i];
                Color pCol = pylonColors[i];

                GameObject tower = new GameObject($"Corner_Pylon_{i + 1}");
                tower.transform.SetParent(pylonsRoot.transform);

                // Steel Column
                GameObject col = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                col.name = "Pylon_Steel_Truss";
                col.transform.SetParent(tower.transform);
                col.transform.position = pPos + Vector3.up * (pylonH * 0.5f);
                col.transform.localScale = new Vector3(1.2f, pylonH * 0.5f, 1.2f);

                var tMat = new Material(litShader);
                tMat.color = new Color(0.06f, 0.08f, 0.10f);
                tMat.EnableKeyword("_EMISSION");
                tMat.SetColor("_EmissionColor", pCol * 3.8f);
                col.GetComponent<Renderer>().sharedMaterial = tMat;

                // Rotating Beacon
                var beaconGo = new GameObject($"Pylon_Beacon_{i + 1}");
                beaconGo.transform.SetParent(tower.transform);
                beaconGo.transform.position = pPos + Vector3.up * (pylonH + 0.6f);
                var bLight = beaconGo.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = pCol;
                bLight.intensity = 6.0f;
                bLight.range = 18.0f;

                // Angled Corner Floodlight Head aimed at the fighters
                var headGo = new GameObject($"Pylon_Spotlight_{i + 1}");
                headGo.transform.SetParent(tower.transform);
                headGo.transform.position = pPos + Vector3.up * (pylonH - 1.0f);
                headGo.transform.LookAt(Vector3.zero + Vector3.up * 1.0f);

                var sLight = headGo.AddComponent<Light>();
                sLight.type = LightType.Spot;
                sLight.color = pCol;
                sLight.intensity = 35.0f;
                sLight.range = 40.0f;
                sLight.spotAngle = 55.0f;
                sLight.innerSpotAngle = 30.0f;
                sLight.shadows = LightShadows.Soft;
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 8. PROFESSIONAL STADIUM BROADCAST LIGHTING RIG
        // ─────────────────────────────────────────────────────────────────────
        private static void BuildStadiumLighting(Transform parent)
        {
            GameObject lightRoot = new GameObject("Arena_Stadium_Lighting_Rig");
            lightRoot.transform.SetParent(parent);

            // Rich Stadium Ambient Fill
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.24f, 0.28f, 0.38f);

            // --- Primary Directional Stadium Sky Key (Broadcast Lighting, shadowCasting on roof disabled) ---
            var dirLightGo = new GameObject("Stadium_Overhead_Broadcast_KeyLight");
            dirLightGo.transform.SetParent(lightRoot.transform);
            dirLightGo.transform.rotation = Quaternion.Euler(58f, 32f, 0f);
            var dirLight = dirLightGo.AddComponent<Light>();
            dirLight.type = LightType.Directional;
            dirLight.color = new Color(0.96f, 0.98f, 1.0f);
            dirLight.intensity = 1.65f;
            dirLight.shadows = LightShadows.Soft;

            // --- Secondary Directional Stadium Rim Light (Cyan/Violet contrast) ---
            var dirRimGo = new GameObject("Stadium_Rim_Contrast_KeyLight");
            dirRimGo.transform.SetParent(lightRoot.transform);
            dirRimGo.transform.rotation = Quaternion.Euler(45f, 210f, 0f);
            var dirRim = dirRimGo.AddComponent<Light>();
            dirRim.type = LightType.Directional;
            dirRim.color = new Color(0.25f, 0.85f, 1.0f);
            dirRim.intensity = 0.65f;
            dirRim.shadows = LightShadows.None;

            // --- 12 High-Powered Ring Downlights mounted on an overhead truss circle at Y = 12m ---
            float ringRadius = 9.0f;
            float ringH = 12.0f;

            for (int i = 0; i < 12; i++)
            {
                float angle = i * (360f / 12f) * Mathf.Deg2Rad;
                Vector3 spotPos = new Vector3(Mathf.Sin(angle) * ringRadius, ringH, Mathf.Cos(angle) * ringRadius);

                var spotGo = new GameObject($"Ring_Canvas_Spotlight_{i + 1}");
                spotGo.transform.SetParent(lightRoot.transform);
                spotGo.transform.position = spotPos;
                spotGo.transform.LookAt(Vector3.zero + Vector3.up * 0.8f);

                var spot = spotGo.AddComponent<Light>();
                spot.type = LightType.Spot;
                spot.color = (i % 2 == 0) ? new Color(0.98f, 0.99f, 1.0f) : new Color(0.40f, 0.95f, 1.0f);
                spot.intensity = 35.0f;
                spot.range = 28.0f;
                spot.spotAngle = 60.0f;
                spot.innerSpotAngle = 32.0f;
                spot.shadows = LightShadows.Soft;
            }

            // --- 8 Dedicated Grandstand Wash Lights (Illuminating the Spectator Crowd!) ---
            (string sideName, Vector3[] lightPositions, Vector3 lookTarget)[] sideLights = new[]
            {
                ("NorthCrowd", new[] { new Vector3(-12f, 16f, 10f), new Vector3(12f, 16f, 10f) }, new Vector3(0f, 5.0f, 28f)),
                ("SouthCrowd", new[] { new Vector3(-12f, 16f, -10f), new Vector3(12f, 16f, -10f) }, new Vector3(0f, 5.0f, -28f)),
                ("EastCrowd",  new[] { new Vector3(10f, 16f, -12f), new Vector3(10f, 16f, 12f) }, new Vector3(28f, 5.0f, 0f)),
                ("WestCrowd",  new[] { new Vector3(-10f, 16f, -12f), new Vector3(-10f, 16f, 12f) }, new Vector3(-28f, 5.0f, 0f))
            };

            foreach (var side in sideLights)
            {
                for (int li = 0; li < side.lightPositions.Length; li++)
                {
                    var washGo = new GameObject($"Crowd_WashLight_{side.sideName}_{li + 1}");
                    washGo.transform.SetParent(lightRoot.transform);
                    washGo.transform.position = side.lightPositions[li];
                    washGo.transform.LookAt(side.lookTarget);

                    var spot = washGo.AddComponent<Light>();
                    spot.type = LightType.Spot;
                    spot.color = new Color(1.0f, 0.95f, 0.88f); // Warm crisp spectator illumination
                    spot.intensity = 42.0f;
                    spot.range = 45.0f;
                    spot.spotAngle = 80.0f;
                    spot.innerSpotAngle = 45.0f;
                    spot.shadows = LightShadows.None;
                }
            }
        }

