// ── 0. WEAPON RIBBON TRAIL CONFIGURATION ─────────────────────────────
/// <summary>
/// Configures weapon TrailRenderer with luminous Tron laser ribbon geometry,
/// Additive HDR blending, and tapered katana silhouette curve for high-velocity swings.
/// </summary>
public static void ConfigureBladeTrail(TrailRenderer trail, bool isPlayer)
{
    if (trail == null) return;
    trail.time = 0.24f; // 0.24s luminous ribbon hang time
    trail.minVertexDistance = 0.015f;
    trail.autodestruct = false;
    trail.alignment = LineAlignment.View;

    // Sleek tapered katana silhouette curve: wide near cutting edge, narrowing to tip
    AnimationCurve widthCurve = new AnimationCurve();
    widthCurve.AddKey(0f, 0.48f);   // 0.48m luminous light-cycle ribbon
    widthCurve.AddKey(0.25f, 0.35f);
    widthCurve.AddKey(0.65f, 0.16f);
    widthCurve.AddKey(1f, 0.01f);
    trail.widthCurve = widthCurve;

    // Tron Electric Cyan (Player) vs Tron Laser Amber/Orange (Enemy)
    Color neonColor = isPlayer ? new Color(0f, 0.95f, 1.0f) : new Color(1.0f, 0.45f, 0.05f);
    Color coreColor = Color.white;

    // Incandescent white-hot laser core fading into rich Tron neon
    Gradient colorGrad = new Gradient();
    colorGrad.SetKeys(
        new GradientColorKey[] {
            new GradientColorKey(coreColor, 0f),
            new GradientColorKey(neonColor, 0.18f),
            new GradientColorKey(neonColor, 1f)
        },
        new GradientAlphaKey[] {
            new GradientAlphaKey(1.0f, 0f),
            new GradientAlphaKey(0.90f, 0.60f),
            new GradientAlphaKey(0.0f, 1f)
        }
    );
    trail.colorGradient = colorGrad;

    Shader shader = Shader.Find("Universal Render Pipeline/Particles/Unlit") 
                 ?? Shader.Find("Particles/Standard Unlit") 
                 ?? Shader.Find("Sprites/Default");

    Material m = trail.sharedMaterial;
    if (m == null || !m.name.Contains("TronBladeTrail"))
    {
        m = new Material(shader);
        m.name = isPlayer ? "M_Player_TronBladeTrail" : "M_Enemy_TronBladeTrail";
    }
    m.SetFloat("_Surface", 1); // Transparent
    m.SetFloat("_Blend", 1);   // 1 = Additive (ICONIC TRON NEON LASER GLOW!)
    m.SetColor("_BaseColor", neonColor * 2.8f); // HDR intensity for URP Bloom synergy
    m.renderQueue = (int)UnityEngine.Rendering.RenderQueue.Transparent + 100;
    trail.sharedMaterial = m;
}

// ── 1. SWORD SLASH ARCS & COMBOS ─────────────────────────────────────
/// <summary>
/// Spawns high-voltage Tron crescent slash arcs on EVERY melee swing (Combo 1-7).
/// </summary>
public static void SpawnSlashArc(Transform attacker, int comboIndex, bool isFinisher)
{
    LoadPrefabs();
    if (attacker == null) return;

    bool isPlayer = attacker.CompareTag("Player") || attacker.name.Contains("Hero") || attacker.name.Contains("Alita");
    Color themeColor = isPlayer 
        ? (isFinisher ? new Color(0.2f, 3.2f, 4.5f) : new Color(0.0f, 2.5f, 3.8f)) 
        : (isFinisher ? new Color(4.0f, 1.5f, 0.2f) : new Color(3.5f, 0.45f, 0.15f));

    GameObject chosenPrefab = _prefabSwordSlash ?? _prefabSlashSmall;
    Vector3 spawnOrigin = attacker.position + Vector3.up * 1.15f + attacker.forward * 0.95f;
    Quaternion swingRot = attacker.rotation;
    float scaleMultiplier = 1.35f;

    // Directional choreography for the full 7-hit combo sequence
    switch (comboIndex)
    {
        case 1: // Right-to-Left horizontal swipe
            swingRot = attacker.rotation * Quaternion.Euler(0f, -15f, 12f);
            spawnOrigin += attacker.right * 0.2f;
            scaleMultiplier = 1.25f;
            break;
        case 2: // Backhand diagonal slash (left to right)
            swingRot = attacker.rotation * Quaternion.Euler(0f, 25f, -35f);
            spawnOrigin += -attacker.right * 0.25f;
            scaleMultiplier = 1.35f;
            break;
        case 3: // Rising uppercut diagonal slash
            swingRot = attacker.rotation * Quaternion.Euler(-25f, 0f, 55f);
            spawnOrigin += Vector3.up * 0.2f;
            scaleMultiplier = 1.45f;
            break;
        case 4: // High-velocity forward thrust
            if (_prefabSwordStab != null) chosenPrefab = _prefabSwordStab;
            spawnOrigin += attacker.forward * 0.35f;
            scaleMultiplier = 1.50f;
            break;
        case 5: // Heavy overhead downward vertical cleave
            swingRot = attacker.rotation * Quaternion.Euler(90f, 0f, 0f);
            spawnOrigin += Vector3.up * 0.35f;
            scaleMultiplier = 1.60f;
            break;
        case 6: // 360-degree whirling blade spin
            swingRot = attacker.rotation * Quaternion.Euler(0f, 180f, 0f);
            scaleMultiplier = 1.80f;
            break;
        case 7: // Finisher: Colossal Tron chromatic rupture crescent
        default:
            if (isFinisher && _prefabSlashLarge != null) chosenPrefab = _prefabSlashLarge;
            swingRot = attacker.rotation * Quaternion.Euler(0f, 0f, 85f);
            spawnOrigin += attacker.forward * 0.4f + Vector3.up * 0.15f;
            scaleMultiplier = 2.2f;
            break;
    }

    if (chosenPrefab != null)
    {
        GameObject fx = Instantiate(chosenPrefab, spawnOrigin, swingRot);
        fx.name = $"Tron_Slash_FX_{comboIndex}";
        fx.transform.localScale = Vector3.one * scaleMultiplier;

        // Tint particle systems to match Tron theme
        TintParticleSystems(fx, themeColor);

        // Play all particle systems
        var systems = fx.GetComponentsInChildren<ParticleSystem>();
        foreach (var ps in systems) ps.Play();

        // Dynamic Tron Point-Light Flash casting real-time cyan illumination on ground and duelists
        SpawnPointLightFlash(spawnOrigin, themeColor, isFinisher ? 7.5f : 4.5f, 6.0f, 0.08f);

        SafeDestroy(fx, 0.85f);
    }
}

