internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var roots = SceneManager.GetActiveScene().GetRootGameObjects();
        foreach (var r in roots)
        {
            var crowd = r.transform.Find("Spectator_Crowd_Stadium_Bleachers");
            if (crowd != null)
            {
                result.Log("Destroying Spectator_Crowd_Stadium_Bleachers from {0}...", r.name);
                Object.DestroyImmediate(crowd.gameObject);
            }
        }
        var scene = SceneManager.GetActiveScene();
        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        result.Log("Saved scene, remaining transforms: {0}", scene.GetRootGameObjects()[0].GetComponentsInChildren<Transform>(true).Length);
    }
}

