using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var allControllers = Object.FindObjectsOfType<InsaneGun.Combat.InsaneGunSwordController>();
        result.Log("Found {0} InsaneGunSwordControllers:", allControllers.Length);
        foreach (var c in allControllers)
        {
            result.Log("  Controller on: {0}, path: {1}", c.gameObject.name, GetPath(c.transform));
        }

        var ring = GameObject.Find("Championship_Combat_Ring");
        if (ring != null)
        {
            for (int i = 0; i < ring.transform.childCount; i++)
            {
                result.Log("  Ring child: {0}", ring.transform.GetChild(i).name);
            }
        }
    }

    private string GetPath(Transform t)
    {
        if (t.parent == null) return t.name;
        return GetPath(t.parent) + "/" + t.name;
    }
}

