using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var alita = GameObject.Find("Alita_BattleAngel_Hero");
        if (alita == null) return;

        var slashPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonParticles/Prefabs/FX_SwordSlash_01.prefab");
        var fx = Object.Instantiate(slashPrefab, alita.transform.position + Vector3.up * 1.15f + alita.transform.forward * 0.95f, alita.transform.rotation);
        fx.name = "Test_Tron_Slash_Arc";
        fx.transform.localScale = Vector3.one * 1.5f;

        // Frame close-up on the slash and Alita
        if (SceneView.lastActiveSceneView != null)
        {
            SceneView.lastActiveSceneView.LookAt(
                alita.transform.position + Vector3.up * 1.15f,
                Quaternion.LookRotation(-alita.transform.forward + Vector3.up * 0.2f),
                2.2f
            );
            SceneView.lastActiveSceneView.Repaint();
        }
        result.Log("Spawned test slash arc at {0}", fx.transform.position);
    }
}

