    if (rightHand != null)
    {
        var blade = Object.Instantiate(swordPrefab, rightHand);
        blade.name = "Alita_Damascus_Blade";
        blade.transform.localPosition = new Vector3(0.11780f, 0.03410f, -0.00920f);
        blade.transform.localEulerAngles = new Vector3(341.3956f, 99.6629f, 276.9453f);
        blade.transform.localScale = Vector3.one * 1.05f;

        // Luminous Tron Katana Blade Material (Electric Cyan HDR Glow)
        var mr = blade.GetComponentInChildren<MeshRenderer>();
        if (mr != null)
        {
            var bladeMat = new Material(Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard"));
            bladeMat.name = "M_Tron_Katana_Alita";
            bladeMat.SetColor("_BaseColor", new Color(0.04f, 0.08f, 0.12f, 1f));
            bladeMat.SetFloat("_Metallic", 0.95f);
            bladeMat.SetFloat("_Smoothness", 0.88f);
            bladeMat.EnableKeyword("_EMISSION");
            bladeMat.SetColor("_EmissionColor", new Color(0f, 3.8f, 5.0f, 1f)); // Blazing Tron Cyan
            mr.material = bladeMat;
        }

        // Dynamic Point Light casting real-time cyan illumination around Alita's weapon
        var bladeLight = new GameObject("Tron_Blade_Neon_Light");
        bladeLight.transform.SetParent(blade.transform, false);
        bladeLight.transform.localPosition = new Vector3(0f, 0f, -0.55f);
        var light = bladeLight.AddComponent<Light>();
        light.type = LightType.Point;
        light.color = new Color(0f, 0.95f, 1.0f);
        light.range = 2.4f;
        light.intensity = 1.25f;

        // 1. Blade Tip Ribbon Trail (wide outer kinetic sweep)
        var tipTrailGo = new GameObject("Tron_Blade_Tip_Trail");
        tipTrailGo.transform.SetParent(blade.transform, false);
        tipTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.92f);
        var tipTrail = tipTrailGo.AddComponent<TrailRenderer>();
        AAACyberCombatVFX.ConfigureBladeTrail(tipTrail, true);
        tipTrail.emitting = false;

        // 2. Blade Mid Ribbon Trail (dense inner luminous core)
        var midTrailGo = new GameObject("Tron_Blade_Mid_Trail");
        midTrailGo.transform.SetParent(blade.transform, false);
        midTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.48f);
        var midTrail = midTrailGo.AddComponent<TrailRenderer>();
        AAACyberCombatVFX.ConfigureBladeTrail(midTrail, true);
        midTrail.emitting = false;

        playerCtrl.swordTrail = tipTrail;
        playerCtrl.swordInstance = blade.transform;
    }
}

