using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var alita = GameObject.Find("Alita_BattleAngel_Hero");
        var rival = GameObject.Find("Rival_Cyber_Duelist");
        string swordPrefabPath = "Assets/CombatGirlsCharacterPack/CombatGirls_DualKatana/Prefab/Weapon_Katana_R.prefab";
        var swordPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(swordPrefabPath);

        if (alita != null && swordPrefab != null)
        {
            var anim = alita.GetComponent<Animator>();
            var rightHand = anim.GetBoneTransform(HumanBodyBones.RightHand);
            var playerCtrl = alita.GetComponent<InsaneGunSwordController>();

            // Destroy existing blade if any
            var existing = rightHand.Find("Alita_Damascus_Blade");
            if (existing != null) Object.DestroyImmediate(existing.gameObject);

            var blade = Object.Instantiate(swordPrefab, rightHand);
            blade.name = "Alita_Damascus_Blade";
            blade.transform.localPosition = new Vector3(0.11780f, 0.03410f, -0.00920f);
            blade.transform.localEulerAngles = new Vector3(341.3956f, 99.6629f, 276.9453f);
            blade.transform.localScale = Vector3.one * 1.05f;

            var mr = blade.GetComponentInChildren<MeshRenderer>();
            if (mr != null)
            {
                var bladeMat = new Material(Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard"));
                bladeMat.name = "M_Tron_Katana_Alita";
                bladeMat.SetColor("_BaseColor", new Color(0.04f, 0.08f, 0.12f, 1f));
                bladeMat.SetFloat("_Metallic", 0.95f);
                bladeMat.SetFloat("_Smoothness", 0.88f);
                bladeMat.EnableKeyword("_EMISSION");
                bladeMat.SetColor("_EmissionColor", new Color(0f, 3.8f, 5.0f, 1f));
                mr.material = bladeMat;
            }

            var bladeLight = new GameObject("Tron_Blade_Neon_Light");
            bladeLight.transform.SetParent(blade.transform, false);
            bladeLight.transform.localPosition = new Vector3(0f, 0f, -0.55f);
            var light = bladeLight.AddComponent<Light>();
            light.type = LightType.Point;
            light.color = new Color(0f, 0.95f, 1.0f);
            light.range = 2.4f;
            light.intensity = 1.25f;

            var tipTrailGo = new GameObject("Tron_Blade_Tip_Trail");
            tipTrailGo.transform.SetParent(blade.transform, false);
            tipTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.92f);
            var tipTrail = tipTrailGo.AddComponent<TrailRenderer>();
            AAACyberCombatVFX.ConfigureBladeTrail(tipTrail, true);
            tipTrail.emitting = false;

            var midTrailGo = new GameObject("Tron_Blade_Mid_Trail");
            midTrailGo.transform.SetParent(blade.transform, false);
            midTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.48f);
            var midTrail = midTrailGo.AddComponent<TrailRenderer>();
            AAACyberCombatVFX.ConfigureBladeTrail(midTrail, true);
            midTrail.emitting = false;

            playerCtrl.swordTrail = tipTrail;
            playerCtrl.swordInstance = blade.transform;
            result.Log("Alita Tron Katana and Dual Trails configured successfully");
        }

        if (rival != null && swordPrefab != null)
        {
            var anim = rival.GetComponent<Animator>();
            var rightHand = anim.GetBoneTransform(HumanBodyBones.RightHand);
            var rivalCtrl = rival.GetComponent<InsaneGunSwordController>();

            var existing = rightHand.Find("Rival_Cyber_Katana");
            if (existing != null) Object.DestroyImmediate(existing.gameObject);

            var rBlade = Object.Instantiate(swordPrefab, rightHand);
            rBlade.name = "Rival_Cyber_Katana";
            rBlade.transform.localPosition = new Vector3(0.11780f, 0.03410f, -0.00920f);
            rBlade.transform.localEulerAngles = new Vector3(341.3956f, 99.6629f, 276.9453f);
            rBlade.transform.localScale = Vector3.one * 1.05f;

            var rMr = rBlade.GetComponentInChildren<MeshRenderer>();
            if (rMr != null)
            {
                var rBladeMat = new Material(Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard"));
                rBladeMat.name = "M_Tron_Katana_Rival";
                rBladeMat.SetColor("_BaseColor", new Color(0.12f, 0.06f, 0.02f, 1f));
                rBladeMat.SetFloat("_Metallic", 0.95f);
                rBladeMat.SetFloat("_Smoothness", 0.88f);
                rBladeMat.EnableKeyword("_EMISSION");
                rBladeMat.SetColor("_EmissionColor", new Color(5.0f, 1.4f, 0.1f, 1f));
                rMr.material = rBladeMat;
            }

            var rBladeLight = new GameObject("Tron_Blade_Neon_Light");
            rBladeLight.transform.SetParent(rBlade.transform, false);
            rBladeLight.transform.localPosition = new Vector3(0f, 0f, -0.55f);
            var rLight = rBladeLight.AddComponent<Light>();
            rLight.type = LightType.Point;
            rLight.color = new Color(1.0f, 0.45f, 0.05f);
            rLight.range = 2.4f;
            rLight.intensity = 1.25f;

            var rTipTrailGo = new GameObject("Tron_Blade_Tip_Trail");
            rTipTrailGo.transform.SetParent(rBlade.transform, false);
            rTipTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.92f);
            var rTipTrail = rTipTrailGo.AddComponent<TrailRenderer>();
            AAACyberCombatVFX.ConfigureBladeTrail(rTipTrail, false);
            rTipTrail.emitting = false;

            var rMidTrailGo = new GameObject("Tron_Blade_Mid_Trail");
            midTrailGo(rMidTrailGo, rBlade.transform, false);
            rMidTrailGo.transform.localPosition = new Vector3(0f, 0f, -0.48f);
            var rMidTrail = rMidTrailGo.AddComponent<TrailRenderer>();
            AAACyberCombatVFX.ConfigureBladeTrail(rMidTrail, false);
            rMidTrail.emitting = false;

            rivalCtrl.swordTrail = rTipTrail;
            rivalCtrl.swordInstance = rBlade.transform;
            result.Log("Rival Tron Katana and Dual Trails configured successfully");
        }

        EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
        EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
        result.Log("Scene saved successfully. File size: {0} bytes", new System.IO.FileInfo(SceneManager.GetActiveScene().path).Length);
    }

    private void midTrailGo(GameObject go, Transform parent, bool p)
    {
        go.transform.SetParent(parent, p);
    }
}

