using UnityEngine;
using UnityEditor;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var alita = GameObject.Find("Alita_BattleAngel_Hero");
        if (alita == null) return;

        var anim = alita.GetComponent<Animator>();
        var ctrl = alita.GetComponent<InsaneGunSwordController>();
        AnimationClip swingClip = null;
        foreach (var c in anim.runtimeAnimatorController.animationClips)
        {
            if (c.name == "atk_sword_01") { swingClip = c; break; }
        }

        if (swingClip != null)
        {
            Vector3 originalPos = alita.transform.position;
            Quaternion originalRot = alita.transform.rotation;

            // Enable trails
            var trails = alita.GetComponentsInChildren<TrailRenderer>(true);
            foreach (var t in trails)
            {
                t.Clear();
                t.emitting = true;
            }

            // Step through 10 animation samples across the swing arc to build the ribbon
            float startT = 0.12f;
            float endT = 0.32f;
            int steps = 12;
            for (int i = 0; i <= steps; i++)
            {
                float t = Mathf.Lerp(startT, endT, (float)i / steps);
                swingClip.SampleAnimation(alita, t);
                alita.transform.position = originalPos;
                alita.transform.rotation = originalRot;
                // Force trail update
                foreach (var tr in trails) tr.transform.position = tr.transform.position;
            }

            if (SceneView.lastActiveSceneView != null)
            {
                SceneView.lastActiveSceneView.LookAt(
                    alita.transform.position + Vector3.up * 1.1f,
                    Quaternion.Euler(15f, 150f, 0f),
                    2.8f
                );
                SceneView.lastActiveSceneView.Repaint();
            }
            result.Log("Sampled swing clip and generated trail with {0} points", trails.Length > 0 ? trails[0].positionCount : 0);
        }
    }
}

