using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using UnityEditor.SceneManagement;
using InsaneGun.Combat;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trails = Object.FindObjectsByType<TrailRenderer>(FindObjectsSortMode.None);
        foreach (var tr in trails)
        {
            tr.Clear();
            tr.emitting = false;
            AAACyberCombatVFX.ConfigureBladeTrail(tr, !tr.transform.parent.name.ToLower().Contains("enemy"));
            result.Log("Updated trail {0} on {1}: time={2}, emitting={3}",
                tr.name, tr.transform.parent.name, tr.time, tr.emitting);
        }

        var players = Object.FindObjectsByType<InsaneGunSwordController>(FindObjectsSortMode.None);
        foreach (var p in players)
        {
            var tr = p.GetComponentInChildren<TrailRenderer>(true);
            if (tr != null)
            {
                p.swordTrail = tr;
                tr.emitting = false;
                tr.Clear();
            }
        }

        EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
        EditorSceneManager.SaveScene(SceneManager.GetActiveScene());
        result.Log("Saved {0}", SceneManager.GetActiveScene().name);
    }
}

