float lineMask = max(aa.x, aa.y);

// Subtle neon laser glow fringe around lines
float minEdge = min(grid.x, grid.y);
float glow = smoothstep(_LineWidth * 4.0, _LineWidth, minEdge) * 0.28;

float finalLine = saturate(lineMask + glow);

