// High HDR Laser Red core with neon fringe over deep obsidian black backdrop
float3 col = _GridColor.rgb * (lineMask * 1.5 + glow * 0.6) * distFade * wave;
float alpha = saturate(finalLine + _BaseAlpha);
return float4(col, alpha);

