using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string scenePath = "Assets/Scenes/Alita_Tron_Awakening.unity";
        Scene currentScene = SceneManager.GetActiveScene();
        if (currentScene.path != scenePath)
        {
            currentScene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
        }

        result.Log("Active scene is {0}", currentScene.name);

        // 1. Update Material Mat_Tron_Red_Cube_Grid
        var redGridShader = Shader.Find("Cyberpunk/Tron_Red_Cube_Grid");
        var redGridMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/Tron/Mat_Tron_Red_Cube_Grid.mat");
        if (redGridMat != null)
        {
            result.RegisterObjectModification(redGridMat);
            if (redGridShader != null) redGridMat.shader = redGridShader;
            redGridMat.SetColor("_GridColor", new Color(5.5f, 0.08f, 0.16f, 1f));
            redGridMat.SetFloat("_GridSpacing", 1.0f);
            redGridMat.SetFloat("_LineWidth", 0.025f);
            redGridMat.SetFloat("_FadeStart", 40f);
            redGridMat.SetFloat("_FadeEnd", 200f);
            redGridMat.SetFloat("_BaseAlpha", 1.0f);
            EditorUtility.SetDirty(redGridMat);
            result.Log("Updated Mat_Tron_Red_Cube_Grid: GridSpacing=1.0, LineWidth=0.025");
        }

        // 2. Update Material Mat_Tron_Obsidian_Mirror
        var mirrorShader = Shader.Find("Cyberpunk/Cyberspace_Mirror_Floor");
        var mirrorMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Materials/Tron/Mat_Tron_Obsidian_Mirror.mat");
        if (mirrorMat != null && mirrorShader != null)
        {
            result.RegisterObjectModification(mirrorMat);
            mirrorMat.shader = mirrorShader;
            mirrorMat.SetColor("_BaseColor", new Color(0.001f, 0.001f, 0.002f, 1f));
            mirrorMat.SetFloat("_MirrorReflectivity", 0.98f);
            mirrorMat.SetFloat("_DistortionStrength", 0.0008f);
            mirrorMat.SetFloat("_FresnelPower", 1.8f);
            mirrorMat.SetFloat("_SpecularGloss", 0.98f);
            mirrorMat.SetFloat("_SpecularIntensity", 2.0f);
            EditorUtility.SetDirty(mirrorMat);
            result.Log("Updated Mat_Tron_Obsidian_Mirror with Cyberspace_Mirror_Floor shader");
        }

        // 3. Locate chamber enclosure
        GameObject chamberGridRoot = GameObject.Find("Chamber_Grid_Enclosure");
        if (chamberGridRoot == null)
        {
            result.LogError("Chamber_Grid_Enclosure not found!");
            return;
        }

        // 4. Remove Floor_Red_Grid if present
        Transform floorRedGridT = chamberGridRoot.transform.Find("Floor_Red_Grid");
        if (floorRedGridT != null)
        {
            result.DestroyObject(floorRedGridT.gameObject);
            result.Log("Destroyed Floor_Red_Grid");
        }

        // 5. Remove fake reflection Ares_Awakening_Slab_Reflection if present
        Transform slabRefT = chamberGridRoot.transform.Find("Ares_Awakening_Slab_Reflection");
        if (slabRefT != null)
        {
            result.DestroyObject(slabRefT.gameObject);
            result.Log("Destroyed Ares_Awakening_Slab_Reflection (replaced by true planar mirror)");
        }

        // 6. Configure Floor_Obsidian_Base
        Transform floorBaseT = chamberGridRoot.transform.Find("Floor_Obsidian_Base");
        if (floorBaseT != null)
        {
            result.RegisterObjectModification(floorBaseT.gameObject);
            floorBaseT.localPosition = Vector3.zero;
            floorBaseT.localRotation = Quaternion.identity;
            floorBaseT.localScale = Vector3.one; // 10m x 10m Plane

            var mr = floorBaseT.GetComponent<MeshRenderer>();
            if (mr != null && mirrorMat != null)
            {
                mr.sharedMaterial = mirrorMat;
            }

            // Setup CyberspacePlanarMirror component
            var planarMirror = floorBaseT.GetComponent<SyntyCombined.CyberspacePlanarMirror>();
            if (planarMirror == null)
            {
                planarMirror = floorBaseT.gameObject.AddComponent<SyntyCombined.CyberspacePlanarMirror>();
            }
            planarMirror.planeHeight = 0.0f;
            planarMirror.clipPlaneOffset = 0.02f;
            planarMirror.floorRenderer = mr;
            planarMirror.mirrorMaterial = mirrorMat;
            planarMirror.renderInEditor = true;
            planarMirror.textureResolution = 1024;
            planarMirror.renderScale = 1.0f;
            planarMirror.reflectionLayers = ~0;
            EditorUtility.SetDirty(floorBaseT.gameObject);
            result.Log("Configured Floor_Obsidian_Base at (1,1,1) with CyberspacePlanarMirror");
        }

        // 7. Configure Ceiling_Red_Grid
        Transform ceilingT = chamberGridRoot.transform.Find("Ceiling_Red_Grid");
        if (ceilingT != null)
        {
            result.RegisterObjectModification(ceilingT.gameObject);
            ceilingT.localPosition = new Vector3(0f, 4.0f, 0f);
            ceilingT.localRotation = Quaternion.Euler(180f, 0f, 0f);
            ceilingT.localScale = Vector3.one; // 10m x 10m Plane
            var mr = ceilingT.GetComponent<MeshRenderer>();
            if (mr != null && redGridMat != null)
            {
                mr.sharedMaterial = redGridMat;
            }
            EditorUtility.SetDirty(ceilingT.gameObject);
            result.Log("Configured Ceiling_Red_Grid at Y=4.0m, scale 10m x 10m");
        }

        // 8. Configure 4 Walls
        // Wall_North (Z = +5.0m, facing inward -Z)
        Transform wallNorthT = chamberGridRoot.transform.Find("Wall_North");
        if (wallNorthT != null)
        {
            result.RegisterObjectModification(wallNorthT.gameObject);
            wallNorthT.localPosition = new Vector3(0f, 2.0f, 5.0f);
            wallNorthT.localRotation = Quaternion.Euler(90f, 180f, 0f);
            wallNorthT.localScale = new Vector3(1.0f, 1.0f, 0.4f); // width 10m, height 4m
            var mr = wallNorthT.GetComponent<MeshRenderer>();
            if (mr != null && redGridMat != null) mr.sharedMaterial = redGridMat;
            EditorUtility.SetDirty(wallNorthT.gameObject);
        }

        // Wall_South (Z = -5.0m, facing inward +Z)
        Transform wallSouthT = chamberGridRoot.transform.Find("Wall_South");
        if (wallSouthT != null)
        {
            result.RegisterObjectModification(wallSouthT.gameObject);
            wallSouthT.localPosition = new Vector3(0f, 2.0f, -5.0f);
            wallSouthT.localRotation = Quaternion.Euler(-90f, 0f, 0f);
            wallSouthT.localScale = new Vector3(1.0f, 1.0f, 0.4f); // width 10m, height 4m
            var mr = wallSouthT.GetComponent<MeshRenderer>();
            if (mr != null && redGridMat != null) mr.sharedMaterial = redGridMat;
            EditorUtility.SetDirty(wallSouthT.gameObject);
        }

        // Wall_East (X = +5.0m, facing inward -X)
        Transform wallEastT = chamberGridRoot.transform.Find("Wall_East");
        if (wallEastT != null)
        {
            result.RegisterObjectModification(wallEastT.gameObject);
            wallEastT.localPosition = new Vector3(5.0f, 2.0f, 0f);
            wallEastT.localRotation = Quaternion.Euler(0f, 0f, 90f);
            wallEastT.localScale = new Vector3(0.4f, 1.0f, 1.0f); // height 4m, depth 10m
            var mr = wallEastT.GetComponent<MeshRenderer>();
            if (mr != null && redGridMat != null) mr.sharedMaterial = redGridMat;
            EditorUtility.SetDirty(wallEastT.gameObject);
        }

        // Wall_West (X = -5.0m, facing inward +X)
        Transform wallWestT = chamberGridRoot.transform.Find("Wall_West");
        if (wallWestT != null)
        {
            result.RegisterObjectModification(wallWestT.gameObject);
            wallWestT.localPosition = new Vector3(-5.0f, 2.0f, 0f);
            wallWestT.localRotation = Quaternion.Euler(0f, 0f, -90f);
            wallWestT.localScale = new Vector3(0.4f, 1.0f, 1.0f); // height 4m, depth 10m
            var mr = wallWestT.GetComponent<MeshRenderer>();
            if (mr != null && redGridMat != null) mr.sharedMaterial = redGridMat;
            EditorUtility.SetDirty(wallWestT.gameObject);
        }

        // 9. Configure Horizon_Laser_Beam
        Transform beamT = chamberGridRoot.transform.Find("Horizon_Laser_Beam");
        if (beamT != null)
        {
            result.RegisterObjectModification(beamT.gameObject);
            beamT.localPosition = new Vector3(-4.95f, 0.65f, 0f);
            beamT.localScale = new Vector3(0.05f, 0.04f, 10.0f);
            EditorUtility.SetDirty(beamT.gameObject);
            result.Log("Configured Horizon_Laser_Beam along West Wall");
        }

        AssetDatabase.SaveAssets();
        EditorSceneManager.MarkSceneDirty(currentScene);
        EditorSceneManager.SaveScene(currentScene);
        result.Log("Successfully redesigned TRON room to 10m x 10m x 4m with reflective mirror floor and red grid walls/ceiling!");
    }
}

