using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Camera cam = Camera.main;
        if (cam == null)
        {
            cam = Object.FindObjectOfType<Camera>();
        }

        if (cam != null)
        {
            result.RegisterObjectModification(cam.gameObject);
            cam.transform.position = new Vector3(3.9f, 1.05f, 0.05f);
            cam.transform.LookAt(new Vector3(0f, 0.65f, 0f));
            cam.fieldOfView = 40f;
            result.Log("Main Camera placed at {0}, rotation {1}, InstanceID={2}", cam.transform.position, cam.transform.rotation.eulerAngles, cam.gameObject.GetInstanceID());
        }
        else
        {
            result.LogError("No camera found in scene");
        }
    }
}

