using UnityEngine;

namespace Alita
{
    /// <summary>
    /// Procedural AAA Floating Megastructure representing ZALEM (Tiphares)
    /// suspended high above the smog in Iron City (Demo_City).
    /// Features:
    /// - Colossal inverted central saucer & orbital space tether spire
    /// - Glowing concentric golden city tier rings & window lights
    /// - Heavy vertical disposal conduits dropping waste down into the Scrapyard
    /// - Pulsing red aviation beacons & downward warm sunbeam spotlight
    /// - Slow monumental orbital rotation
    /// </summary>
    [ExecuteAlways]
    public class ZalemSkyCityOverhead : MonoBehaviour
    {
        [Header("Megastructure Position")]
        public Vector3 zalemWorldPosition = new Vector3(-15f, 260f, 40f);
        public float baseRadius = 140f;
        public float rotationSpeed = 0.25f; // Deg/sec

        [Header("Lighting")]
        public Color zalemCityGlowColor = new Color(5.5f, 3.8f, 1.2f, 1f); // Warm incandescent golden city
        public Color beaconGlowColor = new Color(4.5f, 0.2f, 0.1f, 1f);   // Red aviation warning lights
        public Color conduitCyanColor = new Color(0.2f, 2.5f, 3.5f, 1f);  // Cyan magnetic conduit rings

        private Transform _rotatingCore;

        private void Awake()
        {
            if (transform.childCount == 0)
            {
                BuildZalemGeometry();
            }
        }

        public void BuildZalemGeometry()
        {
            // Clear existing children
            while (transform.childCount > 0)
            {
                DestroyImmediate(transform.GetChild(0).gameObject);
            }

            transform.position = zalemWorldPosition;

            // Materials
            Material darkHullMat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
            darkHullMat.SetColor("_BaseColor", new Color(0.06f, 0.07f, 0.09f, 1f));
            darkHullMat.SetFloat("_Metallic", 0.85f);
            darkHullMat.SetFloat("_Smoothness", 0.65f);

            Material goldCityMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
            goldCityMat.SetColor("_BaseColor", zalemCityGlowColor);

            Material redBeaconMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
            redBeaconMat.SetColor("_BaseColor", beaconGlowColor);

            Material cyanConduitMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
            cyanConduitMat.SetColor("_BaseColor", conduitCyanColor);

            // 1. Rotating Core Root
            GameObject coreGO = new GameObject("Zalem_Rotating_Megastructure");
            coreGO.transform.SetParent(transform, false);
            _rotatingCore = coreGO.transform;

            // 2. Colossal Inverted Saucer / Apex Disc (Main Floating City Platform)
            GameObject mainSaucer = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            mainSaucer.name = "Zalem_Main_Saucer";
            mainSaucer.transform.SetParent(_rotatingCore, false);
            mainSaucer.transform.localPosition = Vector3.zero;
            mainSaucer.transform.localScale = new Vector3(baseRadius * 2f, 12f, baseRadius * 2f);
            mainSaucer.GetComponent<MeshRenderer>().sharedMaterial = darkHullMat;
            Collider c1 = mainSaucer.GetComponent<Collider>();
            if (c1 != null) DestroyImmediate(c1);

            // 3. Central Upward Spire (Orbital Elevator Space Tether)
            GameObject tetherSpire = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
            tetherSpire.name = "Zalem_Orbital_Tether_Spire";
            tetherSpire.transform.SetParent(_rotatingCore, false);
            tetherSpire.transform.localPosition = new Vector3(0f, 150f, 0f);
            tetherSpire.transform.localScale = new Vector3(16f, 300f, 16f);
            tetherSpire.GetComponent<MeshRenderer>().sharedMaterial = darkHullMat;
            Collider c2 = tetherSpire.GetComponent<Collider>();
            if (c2 != null) DestroyImmediate(c2);

            // 4. Concentric Glowing City Tier Rings on Underbelly
            float[] ringRadii = new float[] { baseRadius * 0.95f, baseRadius * 0.75f, baseRadius * 0.52f, baseRadius * 0.32f };
            float[] ringY = new float[] { -6.2f, -8.5f, -11.0f, -14.0f };

            for (int r = 0; r < ringRadii.Length; r++)
            {
                float rad = ringRadii[r];
                int segments = 48 + r * 12;

                GameObject ringRoot = new GameObject($"City_Ring_Tier_{r}");
                ringRoot.transform.SetParent(_rotatingCore, false);

                for (int s = 0; s < segments; s++)
                {
                    float angle = (s / (float)segments) * Mathf.PI * 2f;
                    Vector3 pos = new Vector3(Mathf.Cos(angle) * rad, ringY[r], Mathf.Sin(angle) * rad);

                    GameObject block = GameObject.CreatePrimitive(PrimitiveType.Cube);
                    block.name = $"CityBlock_{r}_{s}";
                    block.transform.SetParent(ringRoot.transform, false);
                    block.transform.localPosition = pos;
                    block.transform.localRotation = Quaternion.Euler(0f, -angle * Mathf.Rad2Deg, 0f);

                    float blockW = (rad * Mathf.PI * 2f / segments) * 0.85f;
                    float blockH = Random.Range(3.5f, 9.0f);
                    block.transform.localScale = new Vector3(blockW, blockH, Random.Range(6f, 14f));

                    // Interleave glowing city windows with hull plating
                    block.GetComponent<MeshRenderer>().sharedMaterial = (s % 3 == 0) ? goldCityMat : darkHullMat;
                    Collider cb = block.GetComponent<Collider>();
                    if (cb != null) DestroyImmediate(cb);
                }
            }

            // 5. Heavy Vertical Disposal Conduits (Garbage chutes that dump scrap to Scrapyard)
            int chuteCount = 4;
            for (int ch = 0; ch < chuteCount; ch++)
            {
                float ang = (ch / (float)chuteCount) * Mathf.PI * 2f + 0.35f;
                float dist = baseRadius * 0.42f;
                Vector3 chutePos = new Vector3(Mathf.Cos(ang) * dist, -50f, Mathf.Sin(ang) * dist);

                GameObject chute = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                chute.name = $"Zalem_Disposal_Chute_{ch}";
                chute.transform.SetParent(_rotatingCore, false);
                chute.transform.localPosition = chutePos;
                chute.transform.localScale = new Vector3(7.5f, 85f, 7.5f);
                chute.GetComponent<MeshRenderer>().sharedMaterial = darkHullMat;
                Collider cc = chute.GetComponent<Collider>();
                if (cc != null) DestroyImmediate(cc);

                // Magnetic Accelerator Ring on chute
                for (int cr = 0; cr < 3; cr++)
                {
                    GameObject cRing = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
                    cRing.name = $"MagRing_{cr}";
                    cRing.transform.SetParent(chute.transform, false);
                    cRing.transform.localPosition = new Vector3(0f, -0.4f + cr * 0.35f, 0f);
                    cRing.transform.localScale = new Vector3(1.35f, 0.04f, 1.35f);
                    cRing.GetComponent<MeshRenderer>().sharedMaterial = cyanConduitMat;
                    Collider crC = cRing.GetComponent<Collider>();
                    if (crC != null) DestroyImmediate(crC);
                }
            }

            // 6. Perimeter Aviation Warning Beacons (Slow pulsing red lights)
            for (int b = 0; b < 16; b++)
            {
                float bAng = (b / 16f) * Mathf.PI * 2f;
                Vector3 bPos = new Vector3(Mathf.Cos(bAng) * (baseRadius + 2f), 1f, Mathf.Sin(bAng) * (baseRadius + 2f));

                GameObject beacon = GameObject.CreatePrimitive(PrimitiveType.Sphere);
                beacon.name = $"AviationBeacon_{b}";
                beacon.transform.SetParent(_rotatingCore, false);
                beacon.transform.localPosition = bPos;
                beacon.transform.localScale = Vector3.one * 3.5f;
                beacon.GetComponent<MeshRenderer>().sharedMaterial = redBeaconMat;
                Collider bc = beacon.GetComponent<Collider>();
                if (bc != null) DestroyImmediate(bc);
            }

            // 7. Golden Sunbeam Spotlight Piercing Downward Through Smog
            GameObject sunLightGO = new GameObject("Zalem_Sunbeam_Shaft");
            sunLightGO.transform.SetParent(transform, false);
            sunLightGO.transform.localPosition = new Vector3(0f, -15f, 0f);
            sunLightGO.transform.localRotation = Quaternion.Euler(78f, -20f, 0f);
            Light sunLight = sunLightGO.AddComponent<Light>();
            sunLight.type = LightType.Spot;
            sunLight.color = new Color(1.0f, 0.88f, 0.65f);
            sunLight.intensity = 8.5f;
            sunLight.range = 380f;
            sunLight.spotAngle = 65f;
            sunLight.innerSpotAngle = 35f;
            sunLight.shadows = LightShadows.None;
        }

        private void Update()
        {
            if (_rotatingCore != null)
            {
                _rotatingCore.Rotate(Vector3.up, rotationSpeed * Time.deltaTime, Space.Self);
            }
        }
    }
}

using System;
using System.Collections;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

namespace Alita
{
    /// <summary>
    /// Cyberpunk 2077 / TRON inspired Holographic Comms Dialogue HUD
    /// for Dr. Dyson Ido's Iron City Walkthrough Prologue.
    /// Features:
    /// - Emissive cyber frame with frosted dark glass backdrop
    /// - Holo-comms Doctor Ido portrait with cyan glitch scanline overlay
    /// - Smooth animated typewriter text with cyber audio chirps
    /// - Interactive landmark prompt badge [E] and [SPACE] Continue prompt
    /// </summary>
    public class AlitaPrologueDialogueHUD : MonoBehaviour
    {
        public static AlitaPrologueDialogueHUD Instance { get; private set; }

        [Header("UI References")]
        public Canvas canvas;
        public CanvasGroup canvasGroup;
        public Image portraitImage;
        public TextMeshProUGUI speakerNameText;
        public TextMeshProUGUI speakerTitleText;
        public TextMeshProUGUI dialogueBodyText;
        public GameObject promptContainer;
        public TextMeshProUGUI promptText;
        public TextMeshProUGUI skipKeyText;
        public AudioSource audioSource;

        [Header("Tuning")]
        public float typeSpeed = 0.022f; // Seconds per character
        public Sprite defaultDoctorPortrait;

        private Coroutine _typewriterCoroutine;
        private Action _onDialogueFinished;
        private bool _isTyping = false;
        private string _currentFullText = "";

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;

            EnsureCanvasAndComponents();
            HideImmediate();
        }

        public void EnsureCanvasAndComponents()
        {
            if (canvas == null)
            {
                canvas = GetComponent<Canvas>();
                if (canvas == null) canvas = gameObject.AddComponent<Canvas>();
                canvas.renderMode = RenderMode.ScreenSpaceOverlay;
                canvas.sortingOrder = 250;

                var scaler = GetComponent<CanvasScaler>() ?? gameObject.AddComponent<CanvasScaler>();
                scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
                scaler.referenceResolution = new Vector2(1920f, 1080f);
                scaler.matchWidthOrHeight = 0.5f;

                if (GetComponent<GraphicRaycaster>() == null) gameObject.AddComponent<GraphicRaycaster>();
            }

            if (canvasGroup == null)
            {
                canvasGroup = GetComponent<CanvasGroup>() ?? gameObject.AddComponent<CanvasGroup>();
            }

            if (audioSource == null)
            {
                audioSource = GetComponent<AudioSource>() ?? gameObject.AddComponent<AudioSource>();
                audioSource.playOnAwake = false;
                audioSource.spatialBlend = 0f; // 2D UI
                audioSource.volume = 0.65f;
            }

            if (portraitImage == null || dialogueBodyText == null)
            {
                BuildVisualHierarchy();
            }
        }

        private void BuildVisualHierarchy()
        {
            // Root panel (Bottom of screen)
            GameObject panelGO = new GameObject("Dialogue_Panel_Root");
            panelGO.transform.SetParent(transform, false);
            var panelRect = panelGO.AddComponent<RectTransform>();
            panelRect.anchorMin = new Vector2(0.5f, 0f);
            panelRect.anchorMax = new Vector2(0.5f, 0f);
            panelRect.pivot = new Vector2(0.5f, 0f);
            panelRect.anchoredPosition = new Vector2(0f, 38f);
            panelRect.sizeDelta = new Vector2(1180f, 210f);

            var bgImg = panelGO.AddComponent<Image>();
            bgImg.color = new Color(0.015f, 0.022f, 0.035f, 0.92f); // Dark obsidian cyber glass

            // Neon Cyan Top & Bottom Border Accents
            GameObject borderTop = new GameObject("Border_Top_Cyan");
            borderTop.transform.SetParent(panelGO.transform, false);
            var btRect = borderTop.AddComponent<RectTransform>();
            btRect.anchorMin = new Vector2(0f, 1f);
            btRect.anchorMax = new Vector2(1f, 1f);
            btRect.sizeDelta = new Vector2(0f, 2.5f);
            btRect.anchoredPosition = new Vector2(0f, -1.25f);
            var btImg = borderTop.AddComponent<Image>();
            btImg.color = new Color(0f, 0.90f, 1f, 0.95f); // Glowing Cyan

            // Doctor Holo Portrait Box (Left)
            GameObject portBox = new GameObject("Portrait_Box");
            portBox.transform.SetParent(panelGO.transform, false);
            var portRect = portBox.AddComponent<RectTransform>();
            portRect.anchorMin = new Vector2(0f, 0.5f);
            portRect.anchorMax = new Vector2(0f, 0.5f);
            portRect.pivot = new Vector2(0f, 0.5f);
            portRect.anchoredPosition = new Vector2(24f, 0f);
            portRect.sizeDelta = new Vector2(150f, 165f);

            var portBorder = portBox.AddComponent<Image>();
            portBorder.color = new Color(0.04f, 0.12f, 0.20f, 0.85f);

            GameObject portImgGO = new GameObject("Doctor_Portrait_Image");
            portImgGO.transform.SetParent(portBox.transform, false);
            var piRect = portImgGO.AddComponent<RectTransform>();
            piRect.anchorMin = Vector2.zero;
            piRect.anchorMax = Vector2.one;
            piRect.sizeDelta = new Vector2(-6f, -6f);
            portraitImage = portImgGO.AddComponent<Image>();
            portraitImage.color = Color.white;

            if (defaultDoctorPortrait != null)
            {
                portraitImage.sprite = defaultDoctorPortrait;
            }

            // Text Content Root (Right of portrait)
            GameObject contentGO = new GameObject("Text_Content_Root");
            contentGO.transform.SetParent(panelGO.transform, false);
            var cRect = contentGO.AddComponent<RectTransform>();
            cRect.anchorMin = new Vector2(0f, 0f);
            cRect.anchorMax = new Vector2(1f, 1f);
            cRect.offsetMin = new Vector2(200f, 15f);
            cRect.offsetMax = new Vector2(-24f, -15f);

            // Speaker Header
            GameObject nameGO = new GameObject("Speaker_Name");
            nameGO.transform.SetParent(contentGO.transform, false);
            var nameRect = nameGO.AddComponent<RectTransform>();
            nameRect.anchorMin = new Vector2(0f, 1f);
            nameRect.anchorMax = new Vector2(1f, 1f);
            nameRect.pivot = new Vector2(0f, 1f);
            nameRect.anchoredPosition = new Vector2(0f, 0f);
            nameRect.sizeDelta = new Vector2(0f, 26f);

            speakerNameText = nameGO.AddComponent<TextMeshProUGUI>();
            speakerNameText.text = "DR. DYSON IDO";
            speakerNameText.fontSize = 20f;
            speakerNameText.fontStyle = FontStyles.Bold;
            speakerNameText.color = new Color(0.1f, 0.95f, 1.0f); // Bright cyber cyan

            // Speaker Subtitle / Title
            GameObject titleGO = new GameObject("Speaker_Title");
            titleGO.transform.SetParent(contentGO.transform, false);
            var titleRect = titleGO.AddComponent<RectTransform>();
            titleRect.anchorMin = new Vector2(0f, 1f);
            titleRect.anchorMax = new Vector2(1f, 1f);
            titleRect.pivot = new Vector2(0f, 1f);
            titleRect.anchoredPosition = new Vector2(175f, 0f);
            titleRect.sizeDelta = new Vector2(0f, 26f);

            speakerTitleText = titleGO.AddComponent<TextMeshProUGUI>();
            speakerTitleText.text = "// HUNTER-WARRIOR & CYBER-SURGEON";
            speakerTitleText.fontSize = 14f;
            speakerTitleText.fontStyle = FontStyles.Normal;
            speakerTitleText.color = new Color(0.85f, 0.65f, 0.2f); // Warm TRON Amber

            // Dialogue Body Text
            GameObject bodyGO = new GameObject("Dialogue_Body_Text");
            bodyGO.transform.SetParent(contentGO.transform, false);
            var bodyRect = bodyGO.AddComponent<RectTransform>();
            bodyRect.anchorMin = new Vector2(0f, 0f);
            bodyRect.anchorMax = new Vector2(1f, 1f);
            bodyRect.offsetMin = new Vector2(0f, 32f);
            bodyRect.offsetMax = new Vector2(0f, -32f);

            dialogueBodyText = bodyGO.AddComponent<TextMeshProUGUI>();
            dialogueBodyText.text = "";
            dialogueBodyText.fontSize = 17f;
            dialogueBodyText.color = new Color(0.92f, 0.94f, 0.98f);
            dialogueBodyText.lineSpacing = 12f;

            // Bottom Footer Row (Prompts)
            promptContainer = new GameObject("Prompts_Footer_Row");
            promptContainer.transform.SetParent(contentGO.transform, false);
            var fRect = promptContainer.AddComponent<RectTransform>();
            fRect.anchorMin = new Vector2(0f, 0f);
            fRect.anchorMax = new Vector2(1f, 0f);
            fRect.pivot = new Vector2(0f, 0f);
            fRect.sizeDelta = new Vector2(0f, 26f);
            fRect.anchoredPosition = Vector2.zero;

            // Interactive Landmark Prompt (Left Footer)
            GameObject pTextGO = new GameObject("Interactive_Prompt_Text");
            pTextGO.transform.SetParent(promptContainer.transform, false);
            var ptRect = pTextGO.AddComponent<RectTransform>();
            ptRect.anchorMin = new Vector2(0f, 0f);
            ptRect.anchorMax = new Vector2(0.7f, 1f);
            promptText = pTextGO.AddComponent<TextMeshProUGUI>();
            promptText.text = "[E] GAZE UP AT ZALEM";
            promptText.fontSize = 14f;
            promptText.fontStyle = FontStyles.Bold;
            promptText.color = new Color(1.0f, 0.85f, 0.2f); // Glowing Amber

            // Skip Prompt (Right Footer)
            GameObject sTextGO = new GameObject("Skip_Key_Text");
            sTextGO.transform.SetParent(promptContainer.transform, false);
            var stRect = sTextGO.AddComponent<RectTransform>();
            stRect.anchorMin = new Vector2(0.7f, 0f);
            stRect.anchorMax = new Vector2(1f, 1f);
            skipKeyText = sTextGO.AddComponent<TextMeshProUGUI>();
            skipKeyText.alignment = TextAlignmentOptions.Right;
            skipKeyText.text = "[SPACE] CONTINUE";
            skipKeyText.fontSize = 13f;
            skipKeyText.color = new Color(0.6f, 0.65f, 0.75f, 0.85f);
        }

        public void DisplayBeat(PrologueDialogueBeat beat, Action onFinished = null)
        {
            if (beat == null) return;

            _onDialogueFinished = onFinished;
            _currentFullText = beat.dialogueText;

            if (speakerNameText != null) speakerNameText.text = beat.speakerName;
            if (speakerTitleText != null) speakerTitleText.text = $"// {beat.speakerTitle}";

            // Interactive Look-At Prompt badge
            if (promptContainer != null)
            {
                promptContainer.SetActive(true);
                if (promptText != null)
                {
                    promptText.gameObject.SetActive(beat.hasInteractiveLookAt);
                    promptText.text = beat.lookAtPromptText;
                }
            }

            // Voice audio playback
            if (beat.voiceClip != null && audioSource != null)
            {
                audioSource.clip = beat.voiceClip;
                audioSource.Play();
            }

            // Show HUD
            StartCoroutine(FadeHUD(1f, 0.25f));

            // Start Typewriter
            if (_typewriterCoroutine != null) StopCoroutine(_typewriterCoroutine);
            _typewriterCoroutine = StartCoroutine(TypewriterRoutine(beat.dialogueText));
        }

        private IEnumerator TypewriterRoutine(string fullText)
        {
            _isTyping = true;
            if (dialogueBodyText != null) dialogueBodyText.text = "";

            for (int i = 0; i <= fullText.Length; i++)
            {
                if (dialogueBodyText != null)
                {
                    dialogueBodyText.text = fullText.Substring(0, i);
                }

                // Procedural audio chirp every 3 characters
                if (i % 3 == 0 && audioSource != null && audioSource.clip == null)
                {
                    PlayProceduralChirp();
                }

                yield return new WaitForSeconds(typeSpeed);
            }

            _isTyping = false;
        }

        public void CompleteCurrentTextInstant()
        {
            if (_isTyping)
            {
                if (_typewriterCoroutine != null) StopCoroutine(_typewriterCoroutine);
                _isTyping = false;
                if (dialogueBodyText != null) dialogueBodyText.text = _currentFullText;
            }
            else
            {
                // Advance to next dialogue beat
                _onDialogueFinished?.Invoke();
            }
        }

        public void Hide(float fadeDuration = 0.3f)
        {
            if (_typewriterCoroutine != null) StopCoroutine(_typewriterCoroutine);
            StartCoroutine(FadeHUD(0f, fadeDuration));
        }

        public void HideImmediate()
        {
            if (canvasGroup != null)
            {
                canvasGroup.alpha = 0f;
                canvasGroup.interactable = false;
                canvasGroup.blocksRaycasts = false;
            }
        }

        private IEnumerator FadeHUD(float targetAlpha, float duration)
        {
            if (canvasGroup == null) yield break;

            float startAlpha = canvasGroup.alpha;
            float elapsed = 0f;

            canvasGroup.interactable = targetAlpha > 0.5f;
            canvasGroup.blocksRaycasts = targetAlpha > 0.5f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                canvasGroup.alpha = Mathf.Lerp(startAlpha, targetAlpha, elapsed / duration);
                yield return null;
            }
            canvasGroup.alpha = targetAlpha;
        }

        private void PlayProceduralChirp()
        {
            // Gentle high-tech radio frequency blip
            float pitch = UnityEngine.Random.Range(1.8f, 2.2f);
            audioSource.pitch = pitch;
            // Play a 12ms synthesized click
            audioSource.PlayOneShot(GetOrCreateClickClip());
        }

        private static AudioClip _clickClip;
        private static AudioClip GetOrCreateClickClip()
        {
            if (_clickClip == null)
            {
                int samples = 512;
                _clickClip = AudioClip.Create("CyberChirp", samples, 1, 44100, false);
                float[] data = new float[samples];
                for (int i = 0; i < samples; i++)
                {
                    float t = i / (float)samples;
                    data[i] = Mathf.Sin(t * Mathf.PI * 16f) * (1f - t) * 0.15f;
                }
                _clickClip.SetData(data, 0);
            }
            return _clickClip;
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;
using InsaneGun.Combat;
using SyntyCombined;
using Cyberpunk.Missions;

namespace Alita
{
    /// <summary>
    /// Master Director for the Iron City Walkthrough Prologue.
    /// Manages:
    /// 1. Cinematic establishing camera crane shot looking down from Zalem to the clinic threshold.
    /// 2. Interactive Escort AI for Dr. Dyson Ido: matched walking speed, waiting when Alita is behind.
    /// 3. Narrative waypoints explaining:
    ///    - Beat 1: Motor recalibration & Iron City overview.
    ///    - Beat 2: The Sky City Zalem overhead & The Fall 300 years ago ([E] Gaze Up at Zalem).
    ///    - Beat 3: The Scrapyard economy & finding Alita's core ([E] Inspect Scrap Chutes).
    ///    - Beat 4: Law of the streets & Hunter-Warriors ([E] Scan Bounty Terminal).
    ///    - Beat 5: Alita's Berserker Panzer Kunst heritage & hand-off to Mission 1 combat.
    /// </summary>
    public class AlitaCityPrologueDirector : MonoBehaviour
    {
        public static AlitaCityPrologueDirector Instance { get; private set; }

        public enum ProloguePhase
        {
            CinematicIntro,
            WalkingToWaypoint,
            DialogueAtWaypoint,
            InteractiveLookAt,
            HandoffToCombat,
            Completed
        }

        [Header("Director State")]
        public ProloguePhase currentPhase = ProloguePhase.CinematicIntro;
        public int currentWaypointIndex = 0;
        public bool autoStartPrologueOnAwake = true;

        [Header("Actor References")]
        public GameObject playerObject;
        public Transform playerTransform;
        public GameObject doctorActor;
        public Transform doctorTransform;
        public NavMeshAgent doctorAgent;
        public Animator doctorAnimator;

        [Header("Zalem Sky City")]
        public ZalemSkyCityOverhead zalemMegastructure;
        public Vector3 zalemLookTarget = new Vector3(-15f, 260f, 40f);

        [Header("Camera & Controls")]
        public Camera mainCamera;
        public SmoothOrbitCamera smoothOrbitCamera;
        private bool _isCinematicCameraActive = false;

        [Header("Dialogue UI Reference")]
        public AlitaPrologueDialogueHUD dialogueHUD;

        [Header("Narrative Waypoint Beats")]
        public List<PrologueDialogueBeat> narrativeBeats = new List<PrologueDialogueBeat>();

        // Escort parameters
        public float walkSpeed = 2.4f;
        public float followCatchupDist = 3.8f;
        public float waitDistance = 7.0f; // If Alita falls >7m behind, Ido waits
        public float waypointRadius = 2.0f;

        private Coroutine _cameraTransitionRoutine;
        private bool _waitingForPlayer = false;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;

            InitializeNarrativeBeatsIfEmpty();
        }

        private void Start()
        {
            if (autoStartPrologueOnAwake)
            {
                StartCoroutine(BootPrologueRoutine());
            }
        }

        private IEnumerator BootPrologueRoutine()
        {
            // Wait 2 frames for scene initialization
            yield return null;
            yield return null;

            AcquireReferences();

            // Suppress Mission1's automatic 7s phone call so our prologue walkthrough leads naturally into it
            if (Mission1_StreetTrialManager.Instance != null)
            {
                // Set state so Mission1 waits for our handoff
                Mission1_StreetTrialManager.Instance.state = Mission1_StreetTrialManager.MissionState.Awakening;
            }

            if (currentPhase == ProloguePhase.CinematicIntro)
            {
                yield return StartCoroutine(PlayCinematicIntroRoutine());
            }

            StartWalkToNextWaypoint();
        }

        public void AcquireReferences()
        {
            // 1. Find Player
            if (playerObject == null)
            {
                playerObject = GameObject.FindWithTag("Player");
            }
            if (playerObject != null)
            {
                playerTransform = playerObject.transform;
            }

            // 2. Find Camera
            if (mainCamera == null)
            {
                mainCamera = Camera.main;
            }
            if (mainCamera != null)
            {
                smoothOrbitCamera = mainCamera.GetComponent<SmoothOrbitCamera>();
            }

            // 3. Find or Spawn Zalem
            if (zalemMegastructure == null)
            {
                zalemMegastructure = Object.FindAnyObjectByType<ZalemSkyCityOverhead>();
                if (zalemMegastructure == null)
                {
                    GameObject zalemGO = new GameObject("Zalem_SkyCity_Overhead");
                    zalemMegastructure = zalemGO.AddComponent<ZalemSkyCityOverhead>();
                    zalemMegastructure.BuildZalemGeometry();
                }
            }
            if (zalemMegastructure != null)
            {
                zalemLookTarget = zalemMegastructure.zalemWorldPosition;
            }

            // 4. Find Doctor Actor
            if (doctorActor == null)
            {
                doctorActor = GameObject.Find("Doctor_Actor") ?? GameObject.Find("Doctor");
            }
            if (doctorActor != null)
            {
                doctorTransform = doctorActor.transform;
                doctorAgent = doctorActor.GetComponent<NavMeshAgent>() ?? doctorActor.GetComponentInChildren<NavMeshAgent>();
                doctorAnimator = doctorActor.GetComponent<Animator>() ?? doctorActor.GetComponentInChildren<Animator>();
            }

            // 5. Dialogue HUD
            if (dialogueHUD == null)
            {
                dialogueHUD = AlitaPrologueDialogueHUD.Instance ?? Object.FindAnyObjectByType<AlitaPrologueDialogueHUD>();
                if (dialogueHUD == null)
                {
                    GameObject hudGO = new GameObject("Alita_Prologue_Dialogue_HUD");
                    dialogueHUD = hudGO.AddComponent<AlitaPrologueDialogueHUD>();
                }
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. CINEMATIC OPENING (IMAX CRANE DOWN FROM ZALEM)
        // ─────────────────────────────────────────────────────────────────────
        private IEnumerator PlayCinematicIntroRoutine()
        {
            _isCinematicCameraActive = true;
            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = false;
            LockPlayerMovement(true);

            Vector3 zalemCamPos = new Vector3(5f, 160f, 75f);
            Quaternion zalemCamRot = Quaternion.Euler(-55f, 15f, 0f); // Looking steeply up at Zalem

            Vector3 streetCamPos = new Vector3(8.5f, -16.2f, 60.5f);
            Vector3 lookAtClinic = new Vector3(12.5f, -17.5f, 57.0f);
            Quaternion streetCamRot = Quaternion.LookRotation(lookAtClinic - streetCamPos);

            if (mainCamera != null)
            {
                mainCamera.transform.position = zalemCamPos;
                mainCamera.transform.rotation = zalemCamRot;
                mainCamera.fieldOfView = 58f;
            }

            // Hold on Zalem for 1.8 seconds with grand title toast
            if (CyberpunkHUDController.Instance != null)
            {
                CyberpunkHUDController.Instance.ShowToast("IRON CITY // 300 YEARS POST-THE FALL", 5.0f);
            }

            float duration = 4.5f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / duration);

                if (mainCamera != null)
                {
                    mainCamera.transform.position = Vector3.Lerp(zalemCamPos, streetCamPos, t);
                    mainCamera.transform.rotation = Quaternion.Slerp(zalemCamRot, streetCamRot, t);
                    mainCamera.fieldOfView = Mathf.Lerp(58f, 50f, t);
                }

                // Press Space to skip intro shot
                if (Input.GetKeyDown(KeyCode.Space)) break;

                yield return null;
            }

            // Restore smooth orbit camera
            if (smoothOrbitCamera != null)
            {
                smoothOrbitCamera.enabled = true;
            }
            _isCinematicCameraActive = false;
            LockPlayerMovement(false);

            // Display Beat 0 (Welcome to Iron City)
            if (narrativeBeats.Count > 0)
            {
                currentPhase = ProloguePhase.DialogueAtWaypoint;
                TriggerDialogueBeat(narrativeBeats[0], () =>
                {
                    currentWaypointIndex = 1;
                    StartWalkToNextWaypoint();
                });
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. ESCORT NAVIGATION & PACING
        // ─────────────────────────────────────────────────────────────────────
        private void Update()
        {
            if (currentPhase == ProloguePhase.WalkingToWaypoint)
            {
                UpdateEscortWalk();
            }
            else if (currentPhase == ProloguePhase.DialogueAtWaypoint)
            {
                UpdateDialogueInteraction();
            }
        }

        private void UpdateEscortWalk()
        {
            if (doctorAgent == null || currentWaypointIndex >= narrativeBeats.Count) return;

            var currentBeat = narrativeBeats[currentWaypointIndex];
            Vector3 dest = currentBeat.waypointPosition;

            float distToWaypoint = Vector3.Distance(doctorTransform.position, dest);
            float distToAlita = (playerTransform != null) ? Vector3.Distance(doctorTransform.position, playerTransform.position) : 0f;

            // Pacing Logic: Check if Alita has fallen behind
            if (distToAlita > waitDistance && !_waitingForPlayer)
            {
                _waitingForPlayer = true;
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);

                // Face Alita and gesture to catch up
                Vector3 toAlita = (playerTransform.position - doctorTransform.position).normalized;
                toAlita.y = 0f;
                if (toAlita != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(toAlita);
                TriggerDoctorGesture("Idle_Wave");
            }
            else if (distToAlita <= followCatchupDist && _waitingForPlayer)
            {
                _waitingForPlayer = false;
                doctorAgent.isStopped = false;
                doctorAgent.SetDestination(dest);
                SetDoctorAnimatorState(true, 1.0f);
            }

            // Check arrival at narrative waypoint
            if (distToWaypoint <= waypointRadius)
            {
                OnArrivedAtWaypoint(currentBeat);
            }
        }

        private void StartWalkToNextWaypoint()
        {
            if (currentWaypointIndex >= narrativeBeats.Count)
            {
                TriggerCombatHandoff();
                return;
            }

            var nextBeat = narrativeBeats[currentWaypointIndex];
            currentPhase = ProloguePhase.WalkingToWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = false;
                doctorAgent.speed = walkSpeed;
                doctorAgent.SetDestination(nextBeat.waypointPosition);
                SetDoctorAnimatorState(true, 1.0f);
            }

            if (dialogueHUD != null) dialogueHUD.Hide();
        }

        private void OnArrivedAtWaypoint(PrologueDialogueBeat beat)
        {
            currentPhase = ProloguePhase.DialogueAtWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);
            }

            // Turn Doctor towards Alita
            if (playerTransform != null && doctorTransform != null)
            {
                Vector3 dir = (playerTransform.position - doctorTransform.position).normalized;
                dir.y = 0f;
                if (dir != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(dir);
            }

            // Play Doctor gesture (e.g. Idle_Look_Sky, Point, etc.)
            if (!string.IsNullOrEmpty(beat.idoAnimTrigger))
            {
                TriggerDoctorGesture(beat.idoAnimTrigger);
            }

            // Trigger dialogue on HUD
            TriggerDialogueBeat(beat, () =>
            {
                currentWaypointIndex++;
                if (currentWaypointIndex >= narrativeBeats.Count)
                {
                    TriggerCombatHandoff();
                }
                else
                {
                    StartWalkToNextWaypoint();
                }
            });
        }

        private void TriggerDialogueBeat(PrologueDialogueBeat beat, System.Action onComplete)
        {
            if (dialogueHUD != null)
            {
                dialogueHUD.DisplayBeat(beat, onComplete);
            }
        }

        private void UpdateDialogueInteraction()
        {
            if (currentWaypointIndex >= narrativeBeats.Count) return;
            var beat = narrativeBeats[currentWaypointIndex];

            // Space: Advance text / dialogue
            if (Input.GetKeyDown(KeyCode.Space))
            {
                if (dialogueHUD != null) dialogueHUD.CompleteCurrentTextInstant();
            }

            // E: Interactive Landmark Look-At Camera
            if (beat.hasInteractiveLookAt && Input.GetKeyDown(KeyCode.E))
            {
                if (currentPhase == ProloguePhase.DialogueAtWaypoint)
                {
                    StartCoroutine(PerformInteractiveLookAt(beat));
                }
            }
        }

        private IEnumerator PerformInteractiveLookAt(PrologueDialogueBeat beat)
        {
            currentPhase = ProloguePhase.InteractiveLookAt;
            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = false;

            Vector3 startPos = mainCamera.transform.position;
            Quaternion startRot = mainCamera.transform.rotation;
            float startFov = mainCamera.fieldOfView;

            Vector3 lookTarget = beat.lookAtWorldTarget != Vector3.zero ? beat.lookAtWorldTarget : zalemLookTarget;
            Quaternion targetRot = Quaternion.LookRotation(lookTarget - startPos);

            float blendDuration = 0.8f;
            float elapsed = 0f;

            // Pan towards landmark
            while (elapsed < blendDuration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / blendDuration);
                mainCamera.transform.rotation = Quaternion.Slerp(startRot, targetRot, t);
                mainCamera.fieldOfView = Mathf.Lerp(startFov, beat.lookAtFov, t);
                yield return null;
            }

            // Hold look-at
            float holdTime = 0f;
            while (holdTime < beat.lookAtDuration)
            {
                holdTime += Time.deltaTime;
                if (Input.GetKeyDown(KeyCode.E) || Input.GetKeyDown(KeyCode.Space)) break;
                yield return null;
            }

            // Return to player view
            elapsed = 0f;
            while (elapsed < blendDuration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / blendDuration);
                mainCamera.transform.rotation = Quaternion.Slerp(targetRot, startRot, t);
                mainCamera.fieldOfView = Mathf.Lerp(beat.lookAtFov, startFov, t);
                yield return null;
            }

            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = true;
            currentPhase = ProloguePhase.DialogueAtWaypoint;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. COMBAT HAND-OFF TO MISSION 1 (STREET TRIAL)
        // ─────────────────────────────────────────────────────────────────────
        private void TriggerCombatHandoff()
        {
            currentPhase = ProloguePhase.HandoffToCombat;
            if (dialogueHUD != null) dialogueHUD.Hide();

            // Set doctor to idle safety stance near bridge railing
            if (doctorAgent != null)
            {
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);
            }
            TriggerDoctorGesture("Idle_ArmsFolded");

            Debug.Log("[AlitaPrologue] Reached Sector 7 Skybridge! Seamlessly handing off to Mission 1: Street Trial...");

            if (Mission1_StreetTrialManager.Instance != null)
            {
                Mission1_StreetTrialManager.Instance.EnterBridgeArenaCombat();
            }

            if (CyberpunkHUDController.Instance != null)
            {
                CyberpunkHUDController.Instance.ShowToast("MISSION 1 ACTIVE // ELIMINATE RAZOR PUNK RAIDERS", 4.5f);
            }

            currentPhase = ProloguePhase.Completed;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 4. ANIMATION & CONTROL HELPERS
        // ─────────────────────────────────────────────────────────────────────
        private void SetDoctorAnimatorState(bool isWalking, float speed)
        {
            if (doctorAnimator == null) return;
            doctorAnimator.SetBool("IsWalking", isWalking);
            doctorAnimator.SetFloat("MoveSpeed", speed);
            doctorAnimator.SetFloat("Speed", speed);
        }

        private void TriggerDoctorGesture(string triggerName)
        {
            if (doctorAnimator == null || string.IsNullOrEmpty(triggerName)) return;
            doctorAnimator.Play(triggerName);
        }

        private void LockPlayerMovement(bool locked)
        {
            var synty = playerObject != null ? playerObject.GetComponent<SyntySwordLocomotionController>() : null;
            if (synty != null) synty.inputLocked = locked;

            var insane = playerObject != null ? playerObject.GetComponent<InsaneGunSwordController>() : null;
            if (insane != null) insane.inputLocked = locked;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 5. DEFAULT LORE DATA INITIALIZATION
        // ─────────────────────────────────────────────────────────────────────
        public void InitializeNarrativeBeatsIfEmpty()
        {
            if (narrativeBeats.Count > 0) return;

            // Beat 0: Clinic Threshold (Spawn Plaza)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Steady on your feet, Alita. Your motor relays are still calibrating to that Doll Body. Look around you... this is Iron City. The world beneath the sky.",
                waypointPosition = new Vector3(12.55f, -17.92f, 56.83f),
                idoAnimTrigger = "Idle_HeadNod",
                hasInteractiveLookAt = false
            });

            // Beat 1: Plaza Overlook (Zalem Overhead & The Fall)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Look straight up, Alita. That's Zalem. The last of the legendary floating cities. Three hundred years ago, during The Fall, all the other sky cities crashed down in the Great War. Zalem is all that survived... and everything down here exists to feed it.",
                waypointPosition = new Vector3(-12.83f, -17.92f, 55.67f),
                idoAnimTrigger = "Idle_Look_Sky",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] GAZE UP AT ZALEM",
                lookAtWorldTarget = new Vector3(-15f, 260f, 40f),
                lookAtFov = 35f,
                lookAtDuration = 4.5f
            });

            // Beat 2: Lower Industrial Ramps (Scrapyard Economy)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Down here, we live beneath Zalem's garbage chutes. Hundreds of tons of discarded machinery and rejected tech dumped on us every week. That's where I found your core, Alita... buried under three centuries of debris.",
                waypointPosition = new Vector3(-25.67f, -11.92f, 35.83f),
                idoAnimTrigger = "Idle_Thoughtful",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] INSPECT SCRAP TRANSIT TUBES",
                lookAtWorldTarget = new Vector3(-45f, 30f, 25f),
                lookAtFov = 42f,
                lookAtDuration = 3.5f
            });

            // Beat 3: Mid-Level Skywalk (Hunter-Warriors & The Factory)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "There are no police in Iron City. The Factory rules from the shadows, enforcing order through licensed Hunter-Warriors—bounty hunters like me. Rogue cyborgs will rip limbs off living people for black-market credits. Out here, trust few, and always keep your guard up.",
                waypointPosition = new Vector3(-14.50f, -5.92f, 14.17f),
                idoAnimTrigger = "Idle_HandsOnHips",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] SCAN FACTORY BOUNTY TERMINAL",
                lookAtWorldTarget = new Vector3(-8f, -4f, 18f),
                lookAtFov = 38f,
                lookAtDuration = 3.5f
            });

            // Beat 4: Sector 7 Skybridge Entrance (Panzer Kunst & Combat Handoff)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Your core isn't ordinary scrap, Alita. It's a 300-year-old Berserker artifact from the United Protectorates of Mars. You may not remember your past, but your body remembers Panzer Kunst—the lost martial art. Look ahead: Razor Punk scavengers are patrolling this bridge. Show me what you can do!",
                waypointPosition = new Vector3(-4.50f, 0.08f, -8.75f),
                idoAnimTrigger = "Idle_Base",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] OVERLOOK SKYBRIDGE ARENA",
                lookAtWorldTarget = new Vector3(0f, 0.5f, -8.75f),
                lookAtFov = 40f,
                lookAtDuration = 3.5f
            });
        }
    }
