using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.AI;
using Alita;

namespace Alita.Editor
{
    public static class AlitaCityPrologueSceneSetup
    {
        public const string DemoCityScenePath = "Assets/PolygonCyberCity/Scenes/Demo_City.unity";
        public const string DoctorPrefabPath = "Assets/Characters/Doctor/Doctor.prefab";
        public const string DoctorFallbackPath = "Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Male_01.prefab";
        public const string DoctorPortraitPath = "Assets/Characters/Doctor/Textures/T_Doctor_Ido_HoloPortrait.png";

        [MenuItem("Tools/Alita Battle Angel/Setup Iron City Walkthrough Prologue (Demo_City)", false, 3)]
        public static void SetupCityPrologue()
        {
            Debug.Log("[AlitaCityPrologue] Setting up Iron City Walkthrough Prologue in Demo_City.unity...");

            Scene cityScene = SceneManager.GetActiveScene();
            if (cityScene.path != DemoCityScenePath)
            {
                cityScene = EditorSceneManager.OpenScene(DemoCityScenePath, OpenSceneMode.Single);
            }

            // 1. Setup Zalem Sky City Overhead
            var zalem = Object.FindAnyObjectByType<ZalemSkyCityOverhead>();
            if (zalem == null)
            {
                GameObject zalemGO = new GameObject("Zalem_SkyCity_Overhead");
                zalem = zalemGO.AddComponent<ZalemSkyCityOverhead>();
                zalem.BuildZalemGeometry();
                Undo.RegisterCreatedObjectUndo(zalemGO, "Create Zalem Sky City");
                Debug.Log("[AlitaCityPrologue] Spawned Zalem Sky City Megastructure at Y=260m!");
            }

            // 2. Setup Doctor Ido Actor
            GameObject doctorActor = GameObject.Find("Doctor_Actor");
            if (doctorActor == null)
            {
                doctorActor = new GameObject("Doctor_Actor");
                Vector3 docSpawnPos = new Vector3(14.2f, -17.92f, 57.5f);
                doctorActor.transform.position = docSpawnPos;
                doctorActor.transform.rotation = Quaternion.Euler(0f, 130f, 0f);

                GameObject docPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(DoctorPrefabPath)
                                    ?? AssetDatabase.LoadAssetAtPath<GameObject>(DoctorFallbackPath);

                GameObject docModel;
                if (docPrefab != null)
                {
                    docModel = (GameObject)PrefabUtility.InstantiatePrefab(docPrefab, doctorActor.transform);
                }
                else
                {
                    docModel = GameObject.CreatePrimitive(PrimitiveType.Capsule);
                    docModel.transform.SetParent(doctorActor.transform, false);
                }
                docModel.name = "Doctor_Model";
                docModel.transform.localPosition = Vector3.zero;
                docModel.transform.localRotation = Quaternion.identity;

                // NavMeshAgent for escort navigation
                var agent = doctorActor.AddComponent<NavMeshAgent>();
                agent.speed = 2.4f;
                agent.angularSpeed = 240f;
                agent.acceleration = 8f;
                agent.stoppingDistance = 0.5f;
                agent.radius = 0.45f;
                agent.height = 1.85f;

                // Animator
                var anim = docModel.GetComponent<Animator>();
                if (anim != null && anim.runtimeAnimatorController == null)
                {
                    var ac = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_CyberNPC.controller")
                          ?? AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_Ido_Discovery.controller");
                    if (ac != null) anim.runtimeAnimatorController = ac;
                }

                Undo.RegisterCreatedObjectUndo(doctorActor, "Create Doctor Actor");
                Debug.Log("[AlitaCityPrologue] Spawned Dr. Dyson Ido at Clinic Exit!");
            }

            // 3. Setup Dialogue HUD
            var dialogueHUD = Object.FindAnyObjectByType<AlitaPrologueDialogueHUD>();
            if (dialogueHUD == null)
            {
                GameObject hudGO = new GameObject("Alita_Prologue_Dialogue_HUD");
                dialogueHUD = hudGO.AddComponent<AlitaPrologueDialogueHUD>();

                // Assign portrait sprite
                var portraitSprite = AssetDatabase.LoadAssetAtPath<Sprite>(DoctorPortraitPath);
                if (portraitSprite != null)
                {
                    dialogueHUD.defaultDoctorPortrait = portraitSprite;
                    if (dialogueHUD.portraitImage != null) dialogueHUD.portraitImage.sprite = portraitSprite;
                }

                Undo.RegisterCreatedObjectUndo(hudGO, "Create Dialogue HUD");
                Debug.Log("[AlitaCityPrologue] Created Holographic Dialogue HUD!");
            }

            // 4. Setup Master Director
            var director = Object.FindAnyObjectByType<AlitaCityPrologueDirector>();
            if (director == null)
            {
                GameObject dirGO = new GameObject("Alita_City_Prologue_Director");
                director = dirGO.AddComponent<AlitaCityPrologueDirector>();
                Undo.RegisterCreatedObjectUndo(dirGO, "Create Prologue Director");
            }

            director.zalemMegastructure = zalem;
            director.doctorActor = doctorActor;
            director.dialogueHUD = dialogueHUD;
            director.autoStartPrologueOnAwake = true;
            director.InitializeNarrativeBeatsIfEmpty();

            // 5. Save Scene
            EditorUtility.SetDirty(director);
            EditorSceneManager.MarkSceneDirty(cityScene);
            EditorSceneManager.SaveScene(cityScene);
            AssetDatabase.SaveAssets();

            Debug.Log("[AlitaCityPrologue] SUCCESS! Iron City Walkthrough Prologue is fully configured in Demo_City.unity!");
        }
    }
}

