rimBand.transform.localPosition = new Vector3(0f, -0.5f, 0f);
rimBand.transform.localScale = new Vector3(baseRadius * 2.02f, 3.5f, baseRadius * 2.02f);
rimBand.GetComponent<MeshRenderer>().sharedMaterial = goldCityMat;
Collider crb = rimBand.GetComponent<Collider>();
if (crb != null) DestroyImmediate(crb);

// 3. Central Upward Spire (Orbital Elevator Space Tether)
GameObject tetherSpire = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
tetherSpire.name = "Zalem_Orbital_Tether_Spire";
tetherSpire.transform.SetParent(_rotatingCore, false);
tetherSpire.transform.localPosition = new Vector3(0f, 150f, 0f);
tetherSpire.transform.localScale = new Vector3(16f, 300f, 16f);
tetherSpire.GetComponent<MeshRenderer>().sharedMaterial = darkHullMat;
Collider c2 = tetherSpire.GetComponent<Collider>();
if (c2 != null) DestroyImmediate(c2);

// Tether Spire Neon Ribbons (Vertical amber conduit)
for (int sr = 0; sr < 4; sr++)
{
    float sAng = sr * Mathf.PI * 0.5f;
    Vector3 sPos = new Vector3(Mathf.Cos(sAng) * 8.5f, 150f, Mathf.Sin(sAng) * 8.5f);
    GameObject sRib = GameObject.CreatePrimitive(PrimitiveType.Cube);
    sRib.name = $"Tether_Conduit_{sr}";
    sRib.transform.SetParent(_rotatingCore, false);
    sRib.transform.localPosition = sPos;
    sRib.transform.localScale = new Vector3(1.2f, 300f, 1.2f);
    sRib.GetComponent<MeshRenderer>().sharedMaterial = cyanConduitMat;
    Collider sc = sRib.GetComponent<Collider>();
    if (sc != null) DestroyImmediate(sc);
}

// 4. Concentric Glowing City Tier Rings on Underbelly
float[] ringRadii = new float[] { baseRadius * 0.88f, baseRadius * 0.68f, baseRadius * 0.48f, baseRadius * 0.28f };
