    GameObject ringRoot = new GameObject($"City_Ring_Tier_{r}");
    ringRoot.transform.SetParent(_rotatingCore, false);

    // Continuous glowing tier ring
    GameObject tierCyl = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
    tierCyl.name = $"TierCylinder_{r}";
    tierCyl.transform.SetParent(ringRoot.transform, false);
    tierCyl.transform.localPosition = new Vector3(0f, ringY[r], 0f);
    tierCyl.transform.localScale = new Vector3(rad * 2f, 2.5f, rad * 2f);
    tierCyl.GetComponent<MeshRenderer>().sharedMaterial = (r % 2 == 0) ? goldCityMat : cyanConduitMat;
    Collider tcc = tierCyl.GetComponent<Collider>();
    if (tcc != null) DestroyImmediate(tcc);

    for (int s = 0; s < segments; s++)
    {
        float angle = (s / (float)segments) * Mathf.PI * 2f;
        Vector3 pos = new Vector3(Mathf.Cos(angle) * rad, ringY[r] - 2f, Mathf.Sin(angle) * rad);

        GameObject block = GameObject.CreatePrimitive(PrimitiveType.Cube);
        block.name = $"CityBlock_{r}_{s}";
        block.transform.SetParent(ringRoot.transform, false);
        block.transform.localPosition = pos;
        block.transform.localRotation = Quaternion.Euler(0f, -angle * Mathf.Rad2Deg, 0f);

        float blockW = (rad * Mathf.PI * 2f / segments) * 0.85f;
