using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AI;
using InsaneGun.Combat;
using SyntyCombined;
using Cyberpunk.Missions;

namespace Alita
{
    /// <summary>
    /// Master Runtime Director for the Iron City Walkthrough Prologue.
    /// Operates PURELY in memory at runtime without adding any objects, geometry,
    /// or props to the Demo_City map file.
    /// 
    /// Manages:
    /// 1. Dynamic in-memory spawning of Dr. Dyson Ido at the street plaza next to Alita.
    /// 2. Smart Escort AI: matched walking speed, waiting when Alita falls behind (>7m).
    /// 3. Five narrative beats with holographic dialogue HUD:
    ///    - Beat 0: Motor recalibration & Iron City overview.
    ///    - Beat 1: The Sky City Zalem overhead & The Fall 300 years ago ([E] Gaze Up at Zalem).
    ///    - Beat 2: The Scrapyard economy & finding Alita's core ([E] Inspect Scrap Transit Tubes).
    ///    - Beat 3: Law of the streets & Hunter-Warriors ([E] Scan Bounty Terminal).
    ///    - Beat 4: Alita's Berserker Panzer Kunst heritage & hand-off to Mission 1 combat.
    /// 4. Seamless combat hand-off to Mission 1: Street Trial on the Sector 7 Skybridge.
    /// </summary>
    public class AlitaCityPrologueDirector : MonoBehaviour
    {
        public static AlitaCityPrologueDirector Instance { get; private set; }

        public enum ProloguePhase
        {
            CinematicIntro,
            WalkingToWaypoint,
            DialogueAtWaypoint,
            InteractiveLookAt,
            HandoffToCombat,
            Completed
        }

        [Header("Director State")]
        public ProloguePhase currentPhase = ProloguePhase.CinematicIntro;
        public int currentWaypointIndex = 0;
        public bool autoStartPrologueOnAwake = true;

        [Header("Actor References (Spawned at Runtime)")]
        public GameObject playerObject;
        public Transform playerTransform;
        public GameObject doctorActor;
        public Transform doctorTransform;
        public NavMeshAgent doctorAgent;
        public Animator doctorAnimator;
        public GameObject doctorPrefab;

        [Header("Camera & Controls")]
        public Camera mainCamera;
        public SmoothOrbitCamera smoothOrbitCamera;
        [HideInInspector] public bool isCinematicCameraActive = false;

        [Header("Dialogue UI Reference (Runtime Canvas)")]
        public AlitaPrologueDialogueHUD dialogueHUD;

        [Header("Narrative Waypoint Beats")]
        public List<PrologueDialogueBeat> narrativeBeats = new List<PrologueDialogueBeat>();

        // Escort parameters
        public float walkSpeed = 2.4f;
        public float followCatchupDist = 3.8f;
        public float waitDistance = 7.0f; // If Alita falls >7m behind, Ido pauses
        public float waypointRadius = 2.2f;

        private bool _waitingForPlayer = false;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;

            InitializeNarrativeBeats();
        }

        private void Start()
        {
            if (autoStartPrologueOnAwake)
            {
                StartCoroutine(BootPrologueRoutine());
            }
        }

        private IEnumerator BootPrologueRoutine()
        {
            // Wait 2 frames for scene initialization
            yield return null;
            yield return null;

            AcquireReferencesAndSpawnDoctor();

            if (currentPhase == ProloguePhase.CinematicIntro)
            {
                yield return StartCoroutine(PlayCinematicIntroRoutine());
            }

            StartWalkToNextWaypoint();
        }

        public void AcquireReferencesAndSpawnDoctor()
        {
            // 1. Find Player
            if (playerObject == null)
            {
                playerObject = GameObject.FindWithTag("Player");
            }
            if (playerObject != null)
            {
                playerTransform = playerObject.transform;
            }

            // 2. Find Camera
            if (mainCamera == null)
            {
                mainCamera = Camera.main;
            }
            if (mainCamera != null)
            {
                smoothOrbitCamera = mainCamera.GetComponent<SmoothOrbitCamera>();
            }

            // 3. Spawn Dr. Dyson Ido dynamically in memory if not already in scene
            if (doctorActor == null)
            {
                Vector3 playerPos = playerTransform != null ? playerTransform.position : new Vector3(12.55f, -17.92f, 56.83f);
                Vector3 spawnPos = playerPos + new Vector3(1.8f, 0f, 0.4f);

                // Sample NavMesh to ensure clean footing
                if (NavMesh.SamplePosition(spawnPos, out NavMeshHit hit, 4f, NavMesh.AllAreas))
                {
                    spawnPos = hit.position;
                }

                doctorActor = new GameObject("Doctor_Actor_Runtime");
                doctorActor.transform.position = spawnPos;
                doctorActor.transform.rotation = Quaternion.Euler(0f, 130f, 0f);

                // Load Doctor Model
                GameObject prefab = doctorPrefab;
#if UNITY_EDITOR
                if (prefab == null)
                {
                    prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Characters/Doctor/Doctor.prefab")
                          ?? UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Male_01.prefab");
                }
#endif
                GameObject modelInstance;
                if (prefab != null)
                {
                    modelInstance = Instantiate(prefab, doctorActor.transform);
                }
                else
                {
                    modelInstance = GameObject.CreatePrimitive(PrimitiveType.Capsule);
                    modelInstance.transform.SetParent(doctorActor.transform, false);
                }

                modelInstance.name = "Doctor_Model";
                modelInstance.transform.localPosition = Vector3.zero;
                modelInstance.transform.localRotation = Quaternion.identity;

                // NavMeshAgent for escort locomotion
                doctorAgent = doctorActor.AddComponent<NavMeshAgent>();
                doctorAgent.speed = walkSpeed;
                doctorAgent.angularSpeed = 240f;
                doctorAgent.acceleration = 8f;
                doctorAgent.stoppingDistance = 0.5f;
                doctorAgent.radius = 0.45f;
                doctorAgent.height = 1.85f;

                // Animator
                doctorAnimator = modelInstance.GetComponent<Animator>();
#if UNITY_EDITOR
                if (doctorAnimator != null && doctorAnimator.runtimeAnimatorController == null)
                {
                    var ac = UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_CyberNPC.controller")
                          ?? UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_Ido_Discovery.controller");
                    if (ac != null) doctorAnimator.runtimeAnimatorController = ac;
                }
#endif
            }

            if (doctorActor != null)
            {
                doctorTransform = doctorActor.transform;
            }

            // 4. Ensure Dialogue HUD is active
            if (dialogueHUD == null)
            {
                dialogueHUD = AlitaPrologueDialogueHUD.Instance ?? FindAnyObjectByType<AlitaPrologueDialogueHUD>();
                if (dialogueHUD == null)
                {
                    GameObject hudGO = new GameObject("Alita_Prologue_Dialogue_HUD_Runtime");
                    dialogueHUD = hudGO.AddComponent<AlitaPrologueDialogueHUD>();
#if UNITY_EDITOR
                    var portrait = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Characters/Doctor/Textures/T_Doctor_Ido_HoloPortrait.png");
                    if (portrait != null)
                    {
                        dialogueHUD.defaultDoctorPortrait = portrait;
                        if (dialogueHUD.portraitImage != null) dialogueHUD.portraitImage.sprite = portrait;
                    }
#endif
                }
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. CINEMATIC OPENING (ESTABLISHING SHOT OF EXISTING CITY)
        // ─────────────────────────────────────────────────────────────────────
        private IEnumerator PlayCinematicIntroRoutine()
        {
            isCinematicCameraActive = true;
            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = false;
            LockPlayerMovement(true);

            Vector3 skylineCamPos = new Vector3(8f, 35f, 65f);
            Quaternion skylineCamRot = Quaternion.Euler(-30f, 10f, 0f); // Looking up at towering skyscrapers & skybox

            Vector3 streetCamPos = new Vector3(8.5f, -16.2f, 60.5f);
            Vector3 lookAtClinic = new Vector3(12.5f, -17.5f, 57.0f);
            Quaternion streetCamRot = Quaternion.LookRotation(lookAtClinic - streetCamPos);

            if (mainCamera != null)
            {
                mainCamera.transform.position = skylineCamPos;
                mainCamera.transform.rotation = skylineCamRot;
                mainCamera.fieldOfView = 58f;
            }

            if (CyberpunkHUDController.Instance != null)
            {
                CyberpunkHUDController.Instance.ShowToast("IRON CITY // 300 YEARS POST-THE FALL", 5.0f);
            }

            float duration = 3.8f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / duration);

                if (mainCamera != null)
                {
                    mainCamera.transform.position = Vector3.Lerp(skylineCamPos, streetCamPos, t);
                    mainCamera.transform.rotation = Quaternion.Slerp(skylineCamRot, streetCamRot, t);
                    mainCamera.fieldOfView = Mathf.Lerp(58f, 50f, t);
                }

                if (Input.GetKeyDown(KeyCode.Space)) break;

                yield return null;
            }

            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = true;
            isCinematicCameraActive = false;
            LockPlayerMovement(false);

            // Display Beat 0 (Welcome to Iron City)
            if (narrativeBeats.Count > 0)
            {
                currentPhase = ProloguePhase.DialogueAtWaypoint;
                TriggerDialogueBeat(narrativeBeats[0], () =>
                {
                    currentWaypointIndex = 1;
                    StartWalkToNextWaypoint();
                });
            }
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. ESCORT PACING & NAVIGATION
        // ─────────────────────────────────────────────────────────────────────
        private void Update()
        {
            if (currentPhase == ProloguePhase.WalkingToWaypoint)
            {
                UpdateEscortWalk();
            }
            else if (currentPhase == ProloguePhase.DialogueAtWaypoint)
            {
                UpdateDialogueInteraction();
            }
        }

        private void UpdateEscortWalk()
        {
            if (doctorAgent == null || currentWaypointIndex >= narrativeBeats.Count) return;

            var currentBeat = narrativeBeats[currentWaypointIndex];
            Vector3 dest = currentBeat.waypointPosition;

            float distToWaypoint = Vector3.Distance(doctorTransform.position, dest);
            float distToAlita = (playerTransform != null) ? Vector3.Distance(doctorTransform.position, playerTransform.position) : 0f;

            // Pacing Logic: Check if Alita has fallen behind (>7m)
            if (distToAlita > waitDistance && !_waitingForPlayer)
            {
                _waitingForPlayer = true;
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);

                Vector3 toAlita = (playerTransform.position - doctorTransform.position).normalized;
                toAlita.y = 0f;
                if (toAlita != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(toAlita);
                TriggerDoctorGesture("Idle_Wave");
            }
            else if (distToAlita <= followCatchupDist && _waitingForPlayer)
            {
                _waitingForPlayer = false;
                doctorAgent.isStopped = false;
                doctorAgent.SetDestination(dest);
                SetDoctorAnimatorState(true, 1.0f);
            }

            // Check arrival at narrative waypoint
            if (distToWaypoint <= waypointRadius)
            {
                OnArrivedAtWaypoint(currentBeat);
            }
        }

        private void StartWalkToNextWaypoint()
        {
            if (currentWaypointIndex >= narrativeBeats.Count)
            {
                TriggerCombatHandoff();
                return;
            }

            var nextBeat = narrativeBeats[currentWaypointIndex];
            currentPhase = ProloguePhase.WalkingToWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = false;
                doctorAgent.speed = walkSpeed;
                doctorAgent.SetDestination(nextBeat.waypointPosition);
                SetDoctorAnimatorState(true, 1.0f);
            }

            if (dialogueHUD != null) dialogueHUD.Hide();
        }

        private void OnArrivedAtWaypoint(PrologueDialogueBeat beat)
        {
            currentPhase = ProloguePhase.DialogueAtWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);
            }

            // Turn Doctor towards Alita
            if (playerTransform != null && doctorTransform != null)
            {
                Vector3 dir = (playerTransform.position - doctorTransform.position).normalized;
                dir.y = 0f;
                if (dir != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(dir);
            }

            // Play Doctor contextual gesture
            if (!string.IsNullOrEmpty(beat.idoAnimTrigger))
            {
                TriggerDoctorGesture(beat.idoAnimTrigger);
            }

            // Trigger dialogue on HUD
            TriggerDialogueBeat(beat, () =>
            {
                currentWaypointIndex++;
                if (currentWaypointIndex >= narrativeBeats.Count)
                {
                    TriggerCombatHandoff();
                }
                else
                {
                    StartWalkToNextWaypoint();
                }
            });
        }

        private void TriggerDialogueBeat(PrologueDialogueBeat beat, Action onComplete)
        {
            if (dialogueHUD != null)
            {
                dialogueHUD.DisplayBeat(beat, onComplete);
            }
        }

        private void UpdateDialogueInteraction()
        {
            if (currentWaypointIndex >= narrativeBeats.Count) return;
            var beat = narrativeBeats[currentWaypointIndex];

            // Space: Advance typewriter text / next line
            if (Input.GetKeyDown(KeyCode.Space))
            {
                if (dialogueHUD != null) dialogueHUD.CompleteCurrentTextInstant();
            }

            // E: Interactive Landmark Look-At Camera
            if (beat.hasInteractiveLookAt && Input.GetKeyDown(KeyCode.E))
            {
                if (currentPhase == ProloguePhase.DialogueAtWaypoint)
                {
                    StartCoroutine(PerformInteractiveLookAt(beat));
                }
            }
        }

        private IEnumerator PerformInteractiveLookAt(PrologueDialogueBeat beat)
        {
            currentPhase = ProloguePhase.InteractiveLookAt;
            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = false;

            Vector3 startPos = mainCamera.transform.position;
            Quaternion startRot = mainCamera.transform.rotation;
            float startFov = mainCamera.fieldOfView;

            Vector3 lookTarget = beat.lookAtWorldTarget;
            Quaternion targetRot = Quaternion.LookRotation(lookTarget - startPos);

            float blendDuration = 0.8f;
            float elapsed = 0f;

            // Pan towards landmark
            while (elapsed < blendDuration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / blendDuration);
                mainCamera.transform.rotation = Quaternion.Slerp(startRot, targetRot, t);
                mainCamera.fieldOfView = Mathf.Lerp(startFov, beat.lookAtFov, t);
                yield return null;
            }

            // Hold look-at
            float holdTime = 0f;
            while (holdTime < beat.lookAtDuration)
            {
                holdTime += Time.deltaTime;
                if (Input.GetKeyDown(KeyCode.E) || Input.GetKeyDown(KeyCode.Space)) break;
                yield return null;
            }

            // Return to player view
            elapsed = 0f;
            while (elapsed < blendDuration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / blendDuration);
                mainCamera.transform.rotation = Quaternion.Slerp(targetRot, startRot, t);
                mainCamera.fieldOfView = Mathf.Lerp(beat.lookAtFov, startFov, t);
                yield return null;
            }

            if (smoothOrbitCamera != null) smoothOrbitCamera.enabled = true;
            currentPhase = ProloguePhase.DialogueAtWaypoint;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. COMBAT HAND-OFF TO MISSION 1 (STREET TRIAL)
        // ─────────────────────────────────────────────────────────────────────
        private void TriggerCombatHandoff()
        {
            currentPhase = ProloguePhase.HandoffToCombat;
            if (dialogueHUD != null) dialogueHUD.Hide();

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);
            }
            TriggerDoctorGesture("Idle_ArmsFolded");

            Debug.Log("[AlitaPrologue] Reached Sector 7 Skybridge! Seamlessly handing off to Mission 1: Street Trial...");

            if (Mission1_StreetTrialManager.Instance != null)
            {
                Mission1_StreetTrialManager.Instance.EnterBridgeArenaCombat();
            }

            if (CyberpunkHUDController.Instance != null)
            {
                CyberpunkHUDController.Instance.ShowToast("MISSION 1 ACTIVE // ELIMINATE RAZOR PUNK RAIDERS", 4.5f);
            }

            currentPhase = ProloguePhase.Completed;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 4. ANIMATION & CONTROL HELPERS
        // ─────────────────────────────────────────────────────────────────────
        private void SetDoctorAnimatorState(bool isWalking, float speed)
        {
            if (doctorAnimator == null) return;
            doctorAnimator.SetBool("IsWalking", isWalking);
            doctorAnimator.SetFloat("MoveSpeed", speed);
            doctorAnimator.SetFloat("Speed", speed);
        }

        private void TriggerDoctorGesture(string triggerName)
        {
            if (doctorAnimator == null || string.IsNullOrEmpty(triggerName)) return;
            doctorAnimator.Play(triggerName);
        }

        private void LockPlayerMovement(bool locked)
        {
            var synty = playerObject != null ? playerObject.GetComponent<SyntySwordLocomotionController>() : null;
            if (synty != null) synty.inputLocked = locked;

            var insane = playerObject != null ? playerObject.GetComponent<InsaneGunSwordController>() : null;
            if (insane != null) insane.inputLocked = locked;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 5. NARRATIVE LORE DATA (USING EXISTING CITY SKYLINE & LANDMARKS)
        // ─────────────────────────────────────────────────────────────────────
        public void InitializeNarrativeBeats()
        {
            narrativeBeats.Clear();

            // Beat 0: Clinic Threshold (Spawn Plaza)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Steady on your feet, Alita. Your motor relays are still calibrating to that Doll Body. Look around you... this is Iron City. The world beneath the sky.",
                waypointPosition = new Vector3(12.55f, -17.92f, 56.83f),
                idoAnimTrigger = "Idle_HeadNod",
                hasInteractiveLookAt = false
            });

            // Beat 1: Plaza Overlook (Existing Sky & Towering Skyline)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
                dialogueText = "Look straight up, Alita. Up past the smog, that's where Zalem hangs. The last of the legendary floating cities. Three hundred years ago, during The Fall, all the other sky cities crashed down in the Great War. Zalem is all that survived... and everything down here exists to feed it.",
                waypointPosition = new Vector3(-12.83f, -17.92f, 55.67f),
                idoAnimTrigger = "Idle_Look_Sky",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] GAZE UP AT SKYLINE",
                lookAtWorldTarget = new Vector3(-12.83f, 120.0f, 55.67f), // Looking directly up into the skybox
                lookAtFov = 40f,
                lookAtDuration = 4.0f
            });

            // Beat 2: Lower Industrial Ramps (Scrapyard Economy & Overhead Tubes)
            narrativeBeats.Add(new PrologueDialogueBeat()
            {
                speakerName = "DR. DYSON IDO",
                speakerTitle = "HUNTER-WARRIOR & CYBER-SURGEON",
