args.TargetContent:
// End Fade-out & Chapter I Mission 1 Transition Card
if (_endFadeAlpha > 0.005f)
{
    int sw = Screen.width;
    int sh = Screen.height;
    GUI.color = new Color(0f, 0f, 0f, _endFadeAlpha);
    GUI.DrawTexture(new Rect(0, 0, sw, sh), Texture2D.whiteTexture);

    if (_endFadeAlpha >= 0.65f)
    {
        float titleFade = Mathf.Clamp01((_endFadeAlpha - 0.65f) / 0.35f);
        GUI.color = new Color(1f, 1f, 1f, titleFade);

        GUIStyle titleStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.Clamp(sw / 40, 24, 38),
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter
        };
        GUI.Label(new Rect(0, sh * 0.33f, sw, 46), "ALITA: BATTLE ANGEL", titleStyle);

        GUIStyle subStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.Clamp(sw / 62, 16, 24),
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter
        };
        subStyle.normal.textColor = new Color(0.1f, 0.95f, 1f, titleFade);
        GUI.Label(new Rect(0, sh * 0.33f + 50, sw, 34), "CHAPTER I // STREET TRIAL", subStyle);

        GUIStyle locStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = Mathf.Clamp(sw / 78, 12, 16),
            alignment = TextAnchor.MiddleCenter
        };
        locStyle.normal.textColor = new Color(0.85f, 0.92f, 1f, titleFade * 0.9f);
        GUI.Label(new Rect(0, sh * 0.33f + 94, sw, 26), "OBJECTIVE: SURVIVE THE LOWER DISTRICT", locStyle);

        GUIStyle quoteStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 12,
            fontStyle = FontStyle.Italic,
            alignment = TextAnchor.MiddleCenter
        };
        quoteStyle.normal.textColor = new Color(1f, 0.78f, 0.3f, titleFade * 0.85f);
        GUI.Label(new Rect(0, sh * 0.33f + 126, sw, 24), "Dr. Dyson Ido: \"Be careful out there, Alita. The streets of Iron City are merciless.\"", quoteStyle);

        GUIStyle promptStyle = new GUIStyle(GUI.skin.label)
        {
            fontSize = 13,
            fontStyle = FontStyle.Bold,
            alignment = TextAnchor.MiddleCenter
        };

        if (_isLoadingGameplay)
        {
            promptStyle.normal.textColor = new Color(0.2f, 1.0f, 0.6f, titleFade);
            int pct = Mathf.Clamp(Mathf.RoundToInt(_gameplayLoadProgress * 100f), 0, 100);
            GUI.Label(new Rect(0, sh * 0.33f + 172, sw, 28), $"◈ INITIALIZING CYBER CITY COMBAT SIMULATION... [ {pct}% ] ◈", promptStyle);
        }
        else
        {
            float pulse = Mathf.PingPong(Time.time * 2.2f, 0.4f) + 0.6f;
            promptStyle.normal.textColor = new Color(0f, 0.95f, 1f, titleFade * pulse);
            int rem = Mathf.Max(1, Mathf.CeilToInt(endTransitionCardDuration - _endingTimer));
            GUI.Label(new Rect(0, sh * 0.33f + 172, sw, 28), $"[ PRESS SPACE TO ENTER CYBER CITY ]  ({rem}s)", promptStyle);
        }
    }
}

