[Serializable]
public struct AwakeningDialogueLine
{
    public float startTime;
    public float endTime;
    public string speakerName;
    public string subtitleText;

    public AwakeningDialogueLine(float s, float e, string spk, string sub)
    {
        startTime = s; endTime = e; speakerName = spk; subtitleText = sub;
    }
}

private static readonly AwakeningDialogueLine[] _awakeningDialogue = new AwakeningDialogueLine[]
{
    new AwakeningDialogueLine(80.5f, 86.5f, "ALITA", "Where... where am I? What year is this...?"),
    new AwakeningDialogueLine(86.5f, 94.5f, "DR. DYSON IDO", "You're safe now. You are in Iron City, below Zalem. The year is 2563... three centuries after The Great Fall."),
    new AwakeningDialogueLine(94.5f, 100.5f, "ALITA", "Three hundred years...? I don't remember anything... except the name Alita."),
    new AwakeningDialogueLine(100.5f, 108.5f, "DR. DYSON IDO", "Your Martian Berserker core was dormant in the scrap heaps. It took weeks to rebuild your body in this cyber-surgery lab... but you survived."),
    new AwakeningDialogueLine(108.5f, 114.5f, "ALITA", "What happened to the world above? Why is everything down here like this?"),
    new AwakeningDialogueLine(114.5f, 122.0f, "DR. DYSON IDO", "Come with me, Alita. Let's step outside into the city... and I'll show you what has become of our world.")
};

private void AdvanceAwakeningDialogueLine()
{
    for (int i = 0; i < _awakeningDialogue.Length; i++)
    {
        if (currentTime >= _awakeningDialogue[i].startTime && currentTime < _awakeningDialogue[i].endTime)
        {
            if (i + 1 < _awakeningDialogue.Length)
            {
                currentTime = _awakeningDialogue[i + 1].startTime;
            }
            else
            {
                currentTime = totalDuration;
                FinishCutsceneAndPromptGameplay();
            }
            return;
        }
    }
}

private void DrawAwakeningSubtitles()
{
    AwakeningDialogueLine activeLine = default;
