// ─────────────────────────────────────────────────────────────────────
// 5. RUNTIME CLINIC LAB & CONNECTED RED GRID ROOM (ZERO MAP PERSISTENCE)
// ─────────────────────────────────────────────────────────────────────
private void SpawnClinicLabEnvironmentRuntime()
{
    GameObject clinicRoot = new GameObject("Ido_Cyber_Clinic_Runtime");
    clinicRoot.transform.position = new Vector3(12.55f, -17.92f, 56.83f);
    clinicRoot.transform.rotation = Quaternion.Euler(0f, 180f, 0f);

    // Glowing Cyan Cyber Sign
    GameObject signGO = new GameObject("Neon_Sign_Clinic");
    signGO.transform.SetParent(clinicRoot.transform, false);
    signGO.transform.localPosition = new Vector3(0f, 3.8f, 0f);
    var signLight = signGO.AddComponent<Light>();
    signLight.type = LightType.Point;
    signLight.color = new Color(0.1f, 0.95f, 1f); // Neon Cyan
    signLight.intensity = 3.5f;
    signLight.range = 10f;

    // Interior Grid Room illumination behind clinic entrance portal
    GameObject gridChamberIllum = new GameObject("Interior_Grid_Chamber_Glow");
    gridChamberIllum.transform.SetParent(clinicRoot.transform, false);
    gridChamberIllum.transform.localPosition = new Vector3(0f, 1.8f, -2.5f);
    var redGridLight = gridChamberIllum.AddComponent<Light>();
    redGridLight.type = LightType.Point;
    redGridLight.color = new Color(1f, 0.15f, 0.1f); // TRON Red Grid glow matching Cutscene 2
    redGridLight.intensity = 4.0f;
    redGridLight.range = 12f;

    // Floating reconstruction slab replica inside clinic interior
    GameObject slabGO = GameObject.CreatePrimitive(PrimitiveType.Cube);
    slabGO.name = "Reconstruction_Slab_Replica";
    slabGO.transform.SetParent(clinicRoot.transform, false);
    slabGO.transform.localPosition = new Vector3(0f, 0.65f, -2.5f);
    slabGO.transform.localScale = new Vector3(0.75f, 0.25f, 2.0f);
    var slabCol = slabGO.GetComponent<Collider>();
    if (slabCol != null) Destroy(slabCol);
    var slabRend = slabGO.GetComponent<Renderer>();
    if (slabRend != null)
    {
        slabRend.material.color = new Color(0.04f, 0.04f, 0.06f);
    }
}

