// 6. NARRATIVE LORE DATA (CONVERSATIONS BETWEEN ALITA & DR. IDO)
// ─────────────────────────────────────────────────────────────────────
public void InitializeNarrativeBeats()
{
    narrativeBeats.Clear();

    // Beat 0: Clinic Threshold (Spawn Plaza)
    var beat0 = new PrologueDialogueBeat()
    {
        beatTitle = "Clinic Threshold // Motor Calibration",
        waypointPosition = new Vector3(12.55f, -17.92f, 56.83f),
        idoAnimTrigger = "Idle_HeadNod",
