public struct AwakeningDialogueLine
{
    public float startTime;
    public float endTime;
    public string speakerName;
    public string subtitleText;

    public AwakeningDialogueLine(float s, float e, string spk, string sub)
    {
        startTime = s; endTime = e; speakerName = spk; subtitleText = sub;
    }
}

private static readonly AwakeningDialogueLine[] _awakeningDialogue = new AwakeningDialogueLine[]
{
    new AwakeningDialogueLine(80.5f, 86.5f, "ALITA", "Where... where am I? What year is this...?"),
    new AwakeningDialogueLine(86.5f, 94.5f, "DR. DYSON IDO", "You're safe now. You are in Iron City, below Zalem. The year is 2563... three centuries after The Great Fall."),
    new AwakeningDialogueLine(94.5f, 100.5f, "ALITA", "Three hundred years...? I don't remember anything... except the name Alita."),
    new AwakeningDialogueLine(100.5f, 108.5f, "DR. DYSON IDO", "Your Martian Berserker core was dormant in the scrap heaps. It took weeks to rebuild your body in this cyber-surgery lab... but you survived."),
    new AwakeningDialogueLine(108.5f, 114.5f, "ALITA", "What happened to the world above? Why is everything down here like this?"),
    new AwakeningDialogueLine(114.5f, 122.0f, "DR. DYSON IDO", "Come with me, Alita. Let's step outside into the city... and I'll show you what has become of our world.")
};

private void AdvanceAwakeningDialogueLine()
{
    for (int i = 0; i < _awakeningDialogue.Length; i++)
    {
        if (currentTime >= _awakeningDialogue[i].startTime && currentTime < _awakeningDialogue[i].endTime)
        {
            if (i + 1 < _awakeningDialogue.Length)
            {
                currentTime = _awakeningDialogue[i + 1].startTime;
            }
            else
            {
                currentTime = totalDuration;
                FinishCutsceneAndPromptGameplay();
            }
            return;
        }
    }
}

private void DrawAwakeningSubtitles()
{
    AwakeningDialogueLine activeLine = default;
    bool found = false;
    for (int i = 0; i < _awakeningDialogue.Length; i++)
    {
        if (currentTime >= _awakeningDialogue[i].startTime && currentTime < _awakeningDialogue[i].endTime)
        {
            activeLine = _awakeningDialogue[i];
            found = true;
            break;
        }
    }

    if (!found) return;

    int sw = Screen.width;
    int sh = Screen.height;
    int boxWidth = Mathf.Min(960, (int)(sw * 0.78f));
    int boxHeight = 110;
    int boxX = (sw - boxWidth) / 2;
    int boxY = sh - boxHeight - 48;

    // Semi-transparent dark frosted glass backing
    if (_blackPixel != null)
    {
        GUI.color = new Color(0.015f, 0.02f, 0.035f, 0.88f);
        GUI.DrawTexture(new Rect(boxX, boxY, boxWidth, boxHeight), _blackPixel);

        // Cyan or Gold Top Accent line
        bool isAlita = activeLine.speakerName.Contains("ALITA");
        Color accentColor = isAlita ? new Color(0f, 0.95f, 1f, 0.95f) : new Color(1f, 0.75f, 0.25f, 0.95f);
        GUI.color = accentColor;
        GUI.DrawTexture(new Rect(boxX, boxY, boxWidth, 2.5f), _whitePixel);
    }

    // Speaker Tag
    bool isAlitaSpeaker = activeLine.speakerName.Contains("ALITA");
    GUIStyle speakerStyle = new GUIStyle(GUI.skin.label)
    {
        fontSize = 15,
        fontStyle = FontStyle.Bold,
        alignment = TextAnchor.MiddleLeft
    };
    speakerStyle.normal.textColor = isAlitaSpeaker ? new Color(0.1f, 0.95f, 1f) : new Color(1f, 0.78f, 0.28f);
    GUI.color = Color.white;
    GUI.Label(new Rect(boxX + 24, boxY + 12, 350, 24), activeLine.speakerName, speakerStyle);

    // Subtitle Text (Crisp 4-way drop shadow)
    GUIStyle subStyle = new GUIStyle(GUI.skin.label)
    {
        fontSize = Mathf.Clamp(sw / 74, 15, 20),
        fontStyle = FontStyle.Normal,
        alignment = TextAnchor.UpperLeft,
        wordWrap = true
    };

    Rect textRect = new Rect(boxX + 24, boxY + 40, boxWidth - 48, 60);

    // Shadows
    subStyle.normal.textColor = new Color(0f, 0f, 0f, 0.95f);
    GUI.Label(new Rect(textRect.x + 1, textRect.y + 1, textRect.width, textRect.height), activeLine.subtitleText, subStyle);
    GUI.Label(new Rect(textRect.x - 1, textRect.y - 1, textRect.width, textRect.height), activeLine.subtitleText, subStyle);

    // Main Text
    subStyle.normal.textColor = Color.white;
    GUI.Label(textRect, activeLine.subtitleText, subStyle);

    // Subtle Prompt on lower right
    GUIStyle promptStyle = new GUIStyle(GUI.skin.label)
    {
        fontSize = 11,
        fontStyle = FontStyle.Normal,
        alignment = TextAnchor.LowerRight
    };
    promptStyle.normal.textColor = new Color(0.7f, 0.8f, 0.9f, 0.6f);
    GUI.Label(new Rect(boxX, boxY + boxHeight - 22, boxWidth - 16, 18), "[SPACE] Continue", promptStyle);
}

