        private GameObject CreatePrimitiveChild(GameObject parent, PrimitiveType type, string name,
            Vector3 localPos, Vector3 localScale, Material mat)
        {
            GameObject obj = GameObject.CreatePrimitive(type);
            obj.name = name;
            obj.transform.SetParent(parent.transform, false);
            obj.transform.localPosition = localPos;
            obj.transform.localScale = localScale;
            var rend = obj.GetComponent<Renderer>();
            if (rend != null && mat != null) rend.material = mat;
            return obj;
        }

        private void TryInstantiateSyntyProp(string assetPath, Vector3 localPos, Quaternion localRot)
        {
#if UNITY_EDITOR
            var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            if (prefab != null && _clinicRoot != null)
            {
                GameObject instance = Instantiate(prefab, _clinicRoot.transform);
                instance.transform.localPosition = localPos;
                instance.transform.localRotation = localRot;
            }
#endif
        }

