        private IEnumerator TransitionToCityWalkRoutine()
        {
            currentPhase = ProloguePhase.DoorsOpening;

            // Open the clinic sliding doors
            yield return StartCoroutine(OpenClinicDoorsRoutine());

            // Advance to Waypoint 1 (Street Plaza outside)
            currentWaypointIndex = 1;
            StartWalkToNextWaypoint();
        }

        private IEnumerator OpenClinicDoorsRoutine()
        {
            if (_isDoorsOpen) yield break;
            _isDoorsOpen = true;

            float duration = 1.6f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / duration);

                if (_doorLeft != null) _doorLeft.localPosition = Vector3.Lerp(_doorLeftClosedPos, _doorLeftOpenPos, t);
                if (_doorRight != null) _doorRight.localPosition = Vector3.Lerp(_doorRightClosedPos, _doorRightOpenPos, t);

                yield return null;
            }

            if (_doorLeft != null) _doorLeft.localPosition = _doorLeftOpenPos;
            if (_doorRight != null) _doorRight.localPosition = _doorRightOpenPos;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 2. ESCORT PACING & CITY NAVIGATION
        // ─────────────────────────────────────────────────────────────────────
        private void Update()
        {
            // Intro fade from black
            if (_introFadeAlpha > 0f)
            {
                _introFadeAlpha = Mathf.MoveTowards(_introFadeAlpha, 0f, Time.deltaTime * 1.5f);
            }

            // Dialogue keyboard advance ([SPACE] advances to next line instantly)
            if (_activeDialogueLine != null)
            {
                _lineTimer += Time.deltaTime;

                if (Input.GetKeyDown(KeyCode.Space) || Input.GetMouseButtonDown(0))
                {
                    AdvanceToNextDialogueLine();
                }
                else if (_lineTimer >= _lineDuration)
                {
                    AdvanceToNextDialogueLine();
                }
            }

            // Escort walk navigation
            if (currentPhase == ProloguePhase.WalkingToWaypoint)
            {
                UpdateEscortWalk();
            }
        }

        private void UpdateEscortWalk()
        {
            if (doctorAgent == null || currentWaypointIndex >= narrativeBeats.Count) return;

            var currentBeat = narrativeBeats[currentWaypointIndex];
            Vector3 dest = currentBeat.waypointPosition;

            float distToWaypoint = Vector3.Distance(doctorTransform.position, dest);
            float distToAlita = (playerTransform != null) ? Vector3.Distance(doctorTransform.position, playerTransform.position) : 0f;

            // Pacing: Check if Alita falls behind (>7m)
            if (distToAlita > waitDistance && !_waitingForPlayer)
            {
                _waitingForPlayer = true;
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);

                Vector3 toAlita = (playerTransform.position - doctorTransform.position).normalized;
                toAlita.y = 0f;
                if (toAlita != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(toAlita);
                TriggerDoctorGesture("Idle_Wave");
            }
            else if (distToAlita <= followCatchupDist && _waitingForPlayer)
            {
                _waitingForPlayer = false;
                doctorAgent.isStopped = false;
                doctorAgent.SetDestination(dest);
                SetDoctorAnimatorState(true, 1.0f);
            }

            // Arrival at narrative waypoint
            if (distToWaypoint <= waypointRadius)
            {
                OnArrivedAtWaypoint(currentBeat);
            }
        }

        private void StartWalkToNextWaypoint()
        {
            if (currentWaypointIndex >= narrativeBeats.Count)
            {
                TriggerCombatHandoff();
                return;
            }

            var nextBeat = narrativeBeats[currentWaypointIndex];
            currentPhase = ProloguePhase.WalkingToWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = false;
                doctorAgent.speed = walkSpeed;
                doctorAgent.SetDestination(nextBeat.waypointPosition);
                SetDoctorAnimatorState(true, 1.0f);
            }
        }

        private void OnArrivedAtWaypoint(PrologueDialogueBeat beat)
        {
            currentPhase = ProloguePhase.DialogueAtWaypoint;

            if (doctorAgent != null)
            {
                doctorAgent.isStopped = true;
                SetDoctorAnimatorState(false, 0f);
            }

            // Turn Doctor towards Alita
            if (playerTransform != null && doctorTransform != null)
            {
                Vector3 dir = (playerTransform.position - doctorTransform.position).normalized;
                dir.y = 0f;
                if (dir != Vector3.zero) doctorTransform.rotation = Quaternion.LookRotation(dir);
            }

            if (!string.IsNullOrEmpty(beat.idoAnimTrigger))
            {
                TriggerDoctorGesture(beat.idoAnimTrigger);
            }

            // Trigger narrative dialogue
            TriggerDialogueBeat(beat, () =>
            {
                currentWaypointIndex++;
                if (currentWaypointIndex >= narrativeBeats.Count)
                {
                    TriggerCombatHandoff();
                }
                else
                {
                    StartWalkToNextWaypoint();
                }
            });
        }

        // ─────────────────────────────────────────────────────────────────────
        // 3. DIALOGUE SYSTEM & CUTSCENE-STYLE OnGUI SUBTITLES
        // ─────────────────────────────────────────────────────────────────────
        private void TriggerDialogueBeat(PrologueDialogueBeat beat, Action onComplete)
        {
            if (beat == null || beat.dialogueLines.Count == 0)
            {
                onComplete?.Invoke();
                return;
            }

            _activeBeat = beat;
            _currentBeatLineIndex = 0;
            _onBeatCompletedCallback = onComplete;
            ShowDialogueLine(_activeBeat.dialogueLines[0]);
        }

        private void ShowDialogueLine(DialogueLine line)
        {
            _activeDialogueLine = line;
            _lineTimer = 0f;
            _lineDuration = Mathf.Max(5.0f, line.text.Length * 0.055f);

            if (!string.IsNullOrEmpty(line.animTrigger))
            {
                TriggerDoctorGesture(line.animTrigger);
            }
        }

        private void AdvanceToNextDialogueLine()
        {
            if (_activeBeat == null)
            {
                _activeDialogueLine = null;
                return;
            }

            _currentBeatLineIndex++;
            if (_currentBeatLineIndex < _activeBeat.dialogueLines.Count)
            {
                ShowDialogueLine(_activeBeat.dialogueLines[_currentBeatLineIndex]);
            }
            else
            {
                _activeDialogueLine = null;
                var callback = _onBeatCompletedCallback;
                _onBeatCompletedCallback = null;
                _activeBeat = null;
                callback?.Invoke();
            }
        }

        private void OnGUI()
        {
            // 1. Screen Fade from Black on Scene Start
            if (_introFadeAlpha > 0.005f)
            {
                GUI.color = new Color(0f, 0f, 0f, _introFadeAlpha);
                GUI.DrawTexture(new Rect(0, 0, Screen.width, Screen.height), Texture2D.whiteTexture);
                GUI.color = Color.white;
            }

            // 2. Cutscene-Style Frosted Dark Glass Subtitles
            if (_activeDialogueLine == null) return;

            int sw = Screen.width;
            int sh = Screen.height;
            int boxWidth = Mathf.Min(960, (int)(sw * 0.78f));
            int boxHeight = 110;
            int boxX = (sw - boxWidth) / 2;
            int boxY = sh - boxHeight - 48;

            // Semi-transparent dark frosted glass backing
            if (_blackPixel != null)
            {
                GUI.color = new Color(0.015f, 0.02f, 0.035f, 0.88f);
                GUI.DrawTexture(new Rect(boxX, boxY, boxWidth, boxHeight), _blackPixel);

                // Cyan or Gold Top Accent line
                bool isAlita = _activeDialogueLine.speakerName.Contains("ALITA");
                Color accentColor = isAlita ? new Color(0f, 0.95f, 1f, 0.95f) : new Color(1f, 0.75f, 0.25f, 0.95f);
                GUI.color = accentColor;
                GUI.DrawTexture(new Rect(boxX, boxY, boxWidth, 2.5f), _whitePixel != null ? _whitePixel : Texture2D.whiteTexture);
            }

            // Optional Holo-Portrait
            int textOffsetX = 24;
            Sprite portrait = _activeDialogueLine.customPortrait;
            if (portrait == null)
            {
                bool isAlita = _activeDialogueLine.speakerName.Contains("ALITA");
                portrait = isAlita ? _defaultAlitaPortrait : _defaultDoctorPortrait;
            }
            if (portrait != null && portrait.texture != null)
            {
                GUI.color = Color.white;
                int portSize = 68;
                int portX = boxX + 18;
                int portY = boxY + 21;
                GUI.DrawTexture(new Rect(portX, portY, portSize, portSize), portrait.texture);
                textOffsetX = 98;
            }

            // Speaker Tag + Title
            bool isAlitaSpeaker = _activeDialogueLine.speakerName.Contains("ALITA");
            GUIStyle speakerStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize = 15,
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleLeft
            };
            speakerStyle.normal.textColor = isAlitaSpeaker ? new Color(0.1f, 0.95f, 1f) : new Color(1f, 0.78f, 0.28f);
            GUI.color = Color.white;

            string speakerHeader = _activeDialogueLine.speakerName;
            if (!string.IsNullOrEmpty(_activeDialogueLine.speakerTitle))
            {
                speakerHeader += "  <size=11><color=#88A0B0>" + _activeDialogueLine.speakerTitle + "</color></size>";
            }
            GUI.Label(new Rect(boxX + textOffsetX, boxY + 12, boxWidth - textOffsetX - 20, 24), speakerHeader, speakerStyle);

            // Subtitle Text (Crisp 4-way drop shadow)
            GUIStyle subStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize = Mathf.Clamp(sw / 74, 15, 20),
                fontStyle = FontStyle.Normal,
                alignment = TextAnchor.UpperLeft,
                wordWrap = true
            };

            Rect textRect = new Rect(boxX + textOffsetX, boxY + 40, boxWidth - textOffsetX - 24, 60);

            // Drop Shadows
            subStyle.normal.textColor = new Color(0f, 0f, 0f, 0.95f);
            GUI.Label(new Rect(textRect.x + 1, textRect.y + 1, textRect.width, textRect.height), _activeDialogueLine.text, subStyle);
            GUI.Label(new Rect(textRect.x - 1, textRect.y - 1, textRect.width, textRect.height), _activeDialogueLine.text, subStyle);

            // Main Text
            subStyle.normal.textColor = Color.white;
            GUI.Label(textRect, _activeDialogueLine.text, subStyle);

            // Subtle Prompt on lower right
            GUIStyle promptStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize = 11,
                fontStyle = FontStyle.Normal,
                alignment = TextAnchor.LowerRight
            };
            promptStyle.normal.textColor = new Color(0.7f, 0.8f, 0.9f, 0.6f);
            GUI.Label(new Rect(boxX, boxY + boxHeight - 22, boxWidth - 16, 18), "[SPACE] Continue", promptStyle);
        }

