        public void InitializeNarrativeBeats()
        {
            narrativeBeats.Clear();

            // Beat 0: Inside Dr. Ido's Lab (Alita asks where she is, who she is, Ido invites outside)
            var beat0 = new PrologueDialogueBeat()
            {
                beatTitle = "Dr. Ido's Clinic Lab // Awakening",
                waypointPosition = new Vector3(12.55f, -17.92f, 56.5f),
                idoAnimTrigger = "Idle_HeadNod"
            };
            beat0.dialogueLines.Add(new DialogueLine("ALITA", "MARTIAN RELIC", "Where... where am I? What is this place?"));
            beat0.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "Easy now. You're safe. This is my cyber-repair clinic. I found your core discarded in the lower scrap district and rebuilt your chassis."));
            beat0.dialogueLines.Add(new DialogueLine("ALITA", "MARTIAN RELIC", "Who am I? Everything in my memory banks is completely blank."));
            beat0.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "I was hoping you could tell me. You had no identity chip, no serial stamp in the corporate registries. In their system, you're a ghost."));
            beat0.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "Your motor neural links look stable. Come on, step outside with me. You need to see what this city has become."));
            narrativeBeats.Add(beat0);

