            {
                beatTitle = "Street Plaza // Corporate Dominion",
                waypointPosition = new Vector3(8.50f, -17.92f, 58.5f),
                idoAnimTrigger = "Idle_Look_Sky",
                hasInteractiveLookAt = true,
