            beat2.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "Up in the high-rise corporate towers, board members trade billions in biometric futures. Down here in the gutter, millions scavenge discarded tech just to afford another day."));
            beat2.dialogueLines.Add(new DialogueLine("ALITA", "MARTIAN RELIC", "High tech, low life. It's cruel."));
            beat2.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "It's corporate feudalism. No government, no human rights, no second chances. Only quarterly profit margins."));
            narrativeBeats.Add(beat2);

            // Beat 3: Mid-Level Skywalk (Corporate Enforcers & Private Hit Squads)
            var beat3 = new PrologueDialogueBeat()
            {
                beatTitle = "Mid-Level Skywalk // Corpo Enforcers",
                waypointPosition = new Vector3(-14.50f, -5.92f, 14.17f),
                idoAnimTrigger = "Idle_HandsOnHips",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] SCAN ROOFTOP GUARDS",
                lookAtWorldTarget = new Vector3(-10f, 8f, 22f),
                lookAtFov = 38f,
                lookAtDuration = 3.5f
            };
            beat3.dialogueLines.Add(new DialogueLine("ALITA", "MARTIAN RELIC", "There are heavily armed mercenaries patrolling the catwalks. Corporate security?"));
            beat3.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "Corpo Enforcers. Razor-Corp's private hit squads. They execute anyone who disrupts corporate supply lines, and bill the victim's family for the ammunition."));
            narrativeBeats.Add(beat3);

            // Beat 4: Sector 7 Skybridge Entrance (Martian Reflex Indexing & Combat Trial)
            var beat4 = new PrologueDialogueBeat()
            {
                beatTitle = "Sector 7 Skybridge // Combat Trial",
                waypointPosition = new Vector3(-4.50f, 0.08f, -8.75f),
                idoAnimTrigger = "Idle_Base",
                hasInteractiveLookAt = true,
                lookAtPromptText = "[E] OVERLOOK SKYBRIDGE ARENA",
                lookAtWorldTarget = new Vector3(0f, 0.5f, -8.75f),
                lookAtFov = 40f,
                lookAtDuration = 3.5f
            };
            beat4.dialogueLines.Add(new DialogueLine("ALITA", "MARTIAN RELIC", "Looking at them... my combat subroutines are engaging automatically. My servos are locking into attack stances."));
            beat4.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "That's military-grade reflex indexing. Whoever built you before the corporate collapse... you were designed to tear corporate machines apart."));
            beat4.dialogueLines.Add(new DialogueLine("DR. DYSON IDO", "CYBER-SURGEON & REPAIR SPECIALIST", "Corpo Syndicate thugs are patrolling the skybridge ahead. Let's see what that body of yours can really do. Show them you're no one's property!"));
            narrativeBeats.Add(beat4);
        }
    }
