        private static Material _sharedFloorMat;
        private static Material _sharedGlassMat;

        private IEnumerator SpawnClinicLabCoroutine()
        {
            if (_clinicRoot != null) yield break;

            // Create shared materials ONCE (prevents GPU crash from many new Material() calls)
            if (_sharedWallMat == null)
            {
                _sharedWallMat = CreateCyberWallMaterial();
                _sharedFloorMat = CreateCyberFloorMaterial();
                _sharedGlassMat = CreateCyberGlassMaterial();
            }

