            _clinicRoot.transform.position = new Vector3(12.55f, -17.92f, 57.0f);
            _clinicRoot.transform.rotation = Quaternion.identity;

            // Spread geometry across frames to avoid GPU Resident Drawer race condition
            // Frame 1: Floor + Ceiling
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Floor",
                new Vector3(0f, -0.05f, 0f), new Vector3(12f, 0.1f, 10f), _sharedFloorMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Ceiling",
