            yield return null;

            // Frame 3: Front wall with doorway gap
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Front_Left",
                new Vector3(-3.75f, 2.1f, -5.0f), new Vector3(4.5f, 4.2f, 0.2f), _sharedWallMat);
