using System;
using System.Collections;
using UnityEngine;

namespace Alita
{
    /// <summary>
    /// Cyberpunk-style fullscreen loading screen rendered in OnGUI.
    /// Zero external asset dependencies — all geometry and text drawn procedurally.
    /// 
    /// Usage:
    ///   CyberpunkLoadingScreen.Show("INITIALIZING IRON CITY...", onDone: () => { ... });
    ///   CyberpunkLoadingScreen.SetProgress(0f..1f);
    ///   CyberpunkLoadingScreen.Hide();
    /// </summary>
    public class CyberpunkLoadingScreen : MonoBehaviour
    {
        // ─── Singleton ────────────────────────────────────────────────────────
        public static CyberpunkLoadingScreen Instance { get; private set; }

        // ─── State ────────────────────────────────────────────────────────────
        private bool   _visible      = false;
        private float  _progress     = 0f;          // 0..1
        private float  _targetProgress = 0f;
        private string _statusLine   = "INITIALIZING...";
        private Action _onHideComplete;

        // ─── Animation ────────────────────────────────────────────────────────
        private float _time          = 0f;
        private float _glitchTimer   = 0f;
        private float _glitchOffsetX = 0f;
        private float _glitchOffsetY = 0f;
        private float _fadeAlpha     = 1f;          // 1 = fully shown, 0 = hidden
        private bool  _fading        = false;

        // ─── Lore Lines ───────────────────────────────────────────────────────
        private static readonly string[] LoreLines =
        {
            "IRON CITY — MEGACORP CONTROL ZONE ALPHA-9",
            "RAZOR-CORP DOMINION  |  POPULATION: 31.4 MILLION",
            "CYBERWARE DEBT OUTSTANDING: 847 TRILLION CREDITS",
            "CORPO ENFORCEMENT STATUS: ACTIVE  [LETHAL AUTHORIZED]",
            "CITIZEN COMPLIANCE INDEX: 99.97%  [FORCED]",
            "NETLINK BLACKOUT: 17 CONSECUTIVE YEARS",
            "LAST INDEPENDENT BROADCAST: TERMINATED",
            "ALITA-UNIT: IDENTITY UNKNOWN  |  THREAT LEVEL: UNKNOWN",
        };
        private int _loreIndex = 0;
        private float _loreTimer = 0f;

        // ─── Textures (procedural) ────────────────────────────────────────────
        private Texture2D _black;
        private Texture2D _cyan;
        private Texture2D _gold;
        private Texture2D _darkPanel;

        // ─── API ──────────────────────────────────────────────────────────────
        public static void Show(string statusLine = "LOADING...", Action onDone = null)
        {
            Ensure();
            Instance._statusLine    = statusLine;
            Instance._onHideComplete = onDone;
            Instance._progress      = 0f;
            Instance._targetProgress = 0f;
            Instance._fadeAlpha     = 1f;
            Instance._fading        = false;
            Instance._visible       = true;
            Instance._loreIndex     = 0;
            Instance._loreTimer     = 0f;
        }

        public static void SetProgress(float t)
        {
            if (Instance == null) return;
            Instance._targetProgress = Mathf.Clamp01(t);
        }

        public static void SetStatus(string line)
        {
            if (Instance == null) return;
            Instance._statusLine = line;
        }

        public static void Hide()
        {
            if (Instance == null) return;
            Instance.StartCoroutine(Instance.FadeOutRoutine());
        }

        // ─── Lifecycle ────────────────────────────────────────────────────────
        private void Awake()
        {
            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
            Instance = this;
            DontDestroyOnLoad(gameObject);
            BuildTextures();
        }

        private static void Ensure()
        {
            if (Instance != null) return;
            var go = new GameObject("CyberpunkLoadingScreen");
            go.AddComponent<CyberpunkLoadingScreen>();
        }

        private void BuildTextures()
        {
            _black = MakeTex(new Color(0f, 0f, 0f, 1f));
            _cyan  = MakeTex(new Color(0.05f, 0.95f, 1f, 1f));
            _gold  = MakeTex(new Color(1f, 0.78f, 0.2f, 1f));
            _darkPanel = MakeTex(new Color(0.02f, 0.04f, 0.06f, 0.96f));
        }

        private Texture2D MakeTex(Color c)
        {
            var t = new Texture2D(1, 1);
            t.SetPixel(0, 0, c);
            t.Apply();
            return t;
        }

        private void Update()
        {
            if (!_visible && !_fading) return;
            _time += Time.unscaledDeltaTime;

            // Smooth progress bar
            _progress = Mathf.MoveTowards(_progress, _targetProgress, Time.unscaledDeltaTime * 0.4f);

            // Glitch every 2-4 seconds
            _glitchTimer -= Time.unscaledDeltaTime;
            if (_glitchTimer <= 0f)
            {
                _glitchTimer   = UnityEngine.Random.Range(1.5f, 3.5f);
                _glitchOffsetX = UnityEngine.Random.Range(-6f, 6f);
                _glitchOffsetY = UnityEngine.Random.Range(-2f, 2f);
            }
            else if (_glitchTimer > 0.12f)
            {
                _glitchOffsetX = Mathf.Lerp(_glitchOffsetX, 0f, Time.unscaledDeltaTime * 12f);
                _glitchOffsetY = Mathf.Lerp(_glitchOffsetY, 0f, Time.unscaledDeltaTime * 12f);
            }

            // Cycle lore lines
            _loreTimer += Time.unscaledDeltaTime;
            if (_loreTimer > 2.2f)
            {
                _loreTimer = 0f;
                _loreIndex = (_loreIndex + 1) % LoreLines.Length;
            }
        }

        private IEnumerator FadeOutRoutine()
        {
            _fading = true;
            float t = 0f;
            float startAlpha = _fadeAlpha;
            while (t < 1f)
            {
                t += Time.unscaledDeltaTime / 0.85f;
                _fadeAlpha = Mathf.Lerp(startAlpha, 0f, t);
                yield return null;
            }
            _fadeAlpha = 0f;
            _visible   = false;
            _fading    = false;
            _onHideComplete?.Invoke();
        }

        // ─── Rendering ────────────────────────────────────────────────────────
        private void OnGUI()
        {
            if (!_visible && !_fading) return;

            int sw = Screen.width;
            int sh = Screen.height;

            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);

            // ── 1. Black background ──────────────────────────────────────────
            GUI.DrawTexture(new Rect(0, 0, sw, sh), _black);

            // ── 2. Animated scanlines ─────────────────────────────────────────
            DrawScanlines(sw, sh);

            // ── 3. Animated hex grid background ──────────────────────────────
            DrawHexGrid(sw, sh);

            // ── 4. Top left corner brackets ──────────────────────────────────
            DrawCornerBrackets(sw, sh);

            // ── 5. Central loading panel ─────────────────────────────────────
            DrawCentralPanel(sw, sh);

            // ── 6. Bottom lore ticker ─────────────────────────────────────────
            DrawLoreTicker(sw, sh);

            GUI.color = Color.white;
        }

        private void DrawScanlines(int sw, int sh)
        {
            // Every 4px draw a dark line for CRT effect
            var lineColor = new Color(0f, 0f, 0f, 0.18f * _fadeAlpha);
            GUI.color = lineColor;
            for (int y = 0; y < sh; y += 4)
                GUI.DrawTexture(new Rect(0, y, sw, 1), _black);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
        }

        private void DrawHexGrid(int sw, int sh)
        {
            // Draw a simple animated dot grid (no GL required)
            float gridSize = 48f;
            float pulse = (Mathf.Sin(_time * 1.2f) + 1f) * 0.5f;
            var dotColor = new Color(0.05f, 0.95f, 1f, 0.04f + pulse * 0.04f);
            dotColor.a *= _fadeAlpha;
            GUI.color = dotColor;

            for (float x = 0; x < sw; x += gridSize)
            {
                for (float y = 0; y < sh; y += gridSize)
                {
                    float dx = x + (Mathf.Sin(y * 0.03f + _time * 0.4f) * 6f);
                    GUI.DrawTexture(new Rect(dx, y, 2, 2), _cyan);
                }
            }
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
        }

        private void DrawCornerBrackets(int sw, int sh)
        {
            float thick = 2f;
            float len   = 40f;
            var col = new Color(0.05f, 0.95f, 1f, 0.6f * _fadeAlpha);
            GUI.color = col;
            // TL
            GUI.DrawTexture(new Rect(20, 20, len, thick), _cyan);
            GUI.DrawTexture(new Rect(20, 20, thick, len), _cyan);
            // TR
            GUI.DrawTexture(new Rect(sw - 20 - len, 20, len, thick), _cyan);
            GUI.DrawTexture(new Rect(sw - 22, 20, thick, len), _cyan);
            // BL
            GUI.DrawTexture(new Rect(20, sh - 22, len, thick), _cyan);
            GUI.DrawTexture(new Rect(20, sh - 20 - len, thick, len), _cyan);
            // BR
            GUI.DrawTexture(new Rect(sw - 20 - len, sh - 22, len, thick), _cyan);
            GUI.DrawTexture(new Rect(sw - 22, sh - 20 - len, thick, len), _cyan);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
        }

        private void DrawCentralPanel(int sw, int sh)
        {
            int panelW = Mathf.Min(820, (int)(sw * 0.72f));
            int panelH = 280;
            int panelX = (sw - panelW) / 2 + (int)_glitchOffsetX;
            int panelY = (sh - panelH) / 2 + (int)_glitchOffsetY;

            // Panel backdrop
            GUI.color = new Color(0.02f, 0.04f, 0.06f, 0.96f * _fadeAlpha);
            GUI.DrawTexture(new Rect(panelX, panelY, panelW, panelH), _darkPanel);

            // Top cyan accent bar
            GUI.color = new Color(0.05f, 0.95f, 1f, 0.9f * _fadeAlpha);
            GUI.DrawTexture(new Rect(panelX, panelY, panelW, 3), _cyan);

            // Bottom gold accent bar
            GUI.color = new Color(1f, 0.78f, 0.2f, 0.7f * _fadeAlpha);
            GUI.DrawTexture(new Rect(panelX, panelY + panelH - 3, panelW, 3), _gold);

            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);

            // ── Title: "IRON CITY // 2563" ────────────────────────────────────
            var titleStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = Mathf.Clamp(sw / 24, 32, 52),
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleCenter,
            };
            titleStyle.normal.textColor = new Color(0.05f, 0.95f, 1f);
            float glitchShift = Mathf.Sin(_time * 18f) * _glitchOffsetX * 0.3f;
            GUI.Label(new Rect(panelX + glitchShift, panelY + 22, panelW, 56), "IRON CITY  //  2563", titleStyle);

            // ── Divider ───────────────────────────────────────────────────────
            GUI.color = new Color(0.05f, 0.95f, 1f, 0.25f * _fadeAlpha);
            GUI.DrawTexture(new Rect(panelX + 40, panelY + 82, panelW - 80, 1), _cyan);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);

            // ── Status line ───────────────────────────────────────────────────
            var statusStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = 14,
                fontStyle = FontStyle.Normal,
                alignment = TextAnchor.MiddleCenter,
            };
            statusStyle.normal.textColor = new Color(0.6f, 0.85f, 0.95f);
            GUI.Label(new Rect(panelX, panelY + 92, panelW, 24), _statusLine, statusStyle);

            // ── Progress bar track ────────────────────────────────────────────
            int barX = panelX + 50;
            int barY = panelY + 128;
            int barW = panelW - 100;
            int barH = 10;

            GUI.color = new Color(0.05f, 0.12f, 0.16f, 0.9f * _fadeAlpha);
            GUI.DrawTexture(new Rect(barX, barY, barW, barH), _black);

            // Filled portion
            int filled = (int)(barW * _progress);
            if (filled > 0)
            {
                float barPulse = 0.75f + Mathf.Sin(_time * 4f) * 0.25f;
                GUI.color = new Color(0.05f * barPulse, 0.95f * barPulse, 1f * barPulse, _fadeAlpha);
                GUI.DrawTexture(new Rect(barX, barY, filled, barH), _cyan);

                // Bright leading edge
                GUI.color = new Color(0.5f, 1f, 1f, 0.9f * _fadeAlpha);
                GUI.DrawTexture(new Rect(barX + filled - 2, barY, 3, barH), _cyan);
            }

            // Bar border
            GUI.color = new Color(0.05f, 0.95f, 1f, 0.4f * _fadeAlpha);
            GUI.DrawTexture(new Rect(barX, barY, barW, 1), _cyan);
            GUI.DrawTexture(new Rect(barX, barY + barH, barW, 1), _cyan);
            GUI.DrawTexture(new Rect(barX, barY, 1, barH), _cyan);
            GUI.DrawTexture(new Rect(barX + barW, barY, 1, barH + 1), _cyan);

            // ── Progress percent ──────────────────────────────────────────────
            var pctStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = 13,
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleRight,
            };
            pctStyle.normal.textColor = new Color(0.05f, 0.95f, 1f);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
            GUI.Label(new Rect(panelX, barY - 2, panelW - 50, 18),
                $"{(int)(_progress * 100f):D3}%", pctStyle);

            // ── Segment ticks ─────────────────────────────────────────────────
            GUI.color = new Color(0.05f, 0.95f, 1f, 0.3f * _fadeAlpha);
            for (int i = 1; i < 10; i++)
            {
                int tickX = barX + (barW * i / 10);
                GUI.DrawTexture(new Rect(tickX, barY - 3, 1, 4), _cyan);
            }

            // ── Animated dots ────────────────────────────────────────────────
            var dotStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = 18,
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleCenter,
            };
            dotStyle.normal.textColor = new Color(1f, 0.78f, 0.2f);
            int dotCount = (int)(_time * 2f) % 4;
            string dots = new string('.', dotCount);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
            GUI.Label(new Rect(panelX, panelY + 155, panelW, 28), $"PLEASE WAIT{dots}", dotStyle);

            // ── Animated side bars ────────────────────────────────────────────
            float sideH = Mathf.Abs(Mathf.Sin(_time * 1.5f)) * panelH * 0.3f + panelH * 0.1f;
            GUI.color = new Color(0.05f, 0.95f, 1f, 0.12f * _fadeAlpha);
            GUI.DrawTexture(new Rect(panelX - 8, panelY + (panelH - (int)sideH) / 2, 3, (int)sideH), _cyan);
            GUI.DrawTexture(new Rect(panelX + panelW + 5, panelY + (panelH - (int)sideH) / 2, 3, (int)sideH), _cyan);

            // ── Corp watermark ────────────────────────────────────────────────
            var waterStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = 10,
                fontStyle = FontStyle.Normal,
                alignment = TextAnchor.LowerRight,
            };
            waterStyle.normal.textColor = new Color(0.3f, 0.4f, 0.5f, 0.6f);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
            GUI.Label(new Rect(panelX, panelY + panelH - 22, panelW - 12, 18),
                "RAZOR-CORP NET v9.4.1  |  SECTOR 7 GATEWAY  |  ACCESS LEVEL: RESTRICTED", waterStyle);

            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
        }

        private void DrawLoreTicker(int sw, int sh)
        {
            int tickerH = 36;
            int tickerY = sh - tickerH - 12;

            // Ticker background
            GUI.color = new Color(0.02f, 0.05f, 0.08f, 0.88f * _fadeAlpha);
            GUI.DrawTexture(new Rect(0, tickerY, sw, tickerH), _darkPanel);

            // Gold top border
            GUI.color = new Color(1f, 0.78f, 0.2f, 0.55f * _fadeAlpha);
            GUI.DrawTexture(new Rect(0, tickerY, sw, 1), _gold);

            // Lore text
            var loreStyle = new GUIStyle(GUI.skin.label)
            {
                fontSize  = 13,
                fontStyle = FontStyle.Normal,
                alignment = TextAnchor.MiddleCenter,
            };
            loreStyle.normal.textColor = new Color(1f, 0.78f, 0.2f, 0.9f);
            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);

            // Fade lore line based on timer
            float loreFade = Mathf.Clamp01(Mathf.Sin(_loreTimer / 2.2f * Mathf.PI));
            var c = loreStyle.normal.textColor;
            loreStyle.normal.textColor = new Color(c.r, c.g, c.b, c.a * loreFade * _fadeAlpha);
            GUI.Label(new Rect(0, tickerY, sw, tickerH), LoreLines[_loreIndex], loreStyle);

            GUI.color = new Color(1f, 1f, 1f, _fadeAlpha);
        }
    }
}

