private IEnumerator BootPrologueRoutine()
{
    // Wait 2 frames for scene initialization
    yield return null;
    yield return null;

    // ── Show loading screen immediately ──────────────────────────────
    CyberpunkLoadingScreen.Show("INITIALIZING IRON CITY SECTOR 7...");
    CyberpunkLoadingScreen.SetProgress(0.05f);
    yield return null;

    // 1. Build Dr. Ido's Cyber Clinic Lab in memory (deferred across frames to avoid GPU crash)
    CyberpunkLoadingScreen.SetStatus("CONSTRUCTING IDO'S CYBER-REPAIR CLINIC...");
    CyberpunkLoadingScreen.SetProgress(0.15f);
    yield return StartCoroutine(SpawnClinicLabCoroutine());
    CyberpunkLoadingScreen.SetProgress(0.55f);
    yield return null;

    // 2. Acquire Player and position inside clinic beside examination slab
    CyberpunkLoadingScreen.SetStatus("LOCATING ALITA-UNIT...");
    AcquirePlayerAndPositionInClinic();
    CyberpunkLoadingScreen.SetProgress(0.70f);
    yield return null;

    // 3. Spawn Dr. Dyson Ido inside the clinic facing Alita
    CyberpunkLoadingScreen.SetStatus("SPAWNING DR. DYSON IDO...");
    SpawnDoctorInClinic();
    CyberpunkLoadingScreen.SetProgress(0.82f);
    yield return null;

    // 4. Ensure camera is following player and movement is unlocked immediately
    if (mainCamera == null) mainCamera = Camera.main;
    if (mainCamera != null && smoothOrbitCamera == null)
    {
        smoothOrbitCamera = mainCamera.GetComponent<SmoothOrbitCamera>();
    }
    if (smoothOrbitCamera != null)
    {
        smoothOrbitCamera.enabled = true;
        smoothOrbitCamera.target = playerTransform;
    }

    CyberpunkLoadingScreen.SetStatus("CALIBRATING NEURAL LINKS...");
    CyberpunkLoadingScreen.SetProgress(0.94f);
    yield return new WaitForSecondsRealtime(0.4f);

    LockPlayerMovement(false);
    CyberpunkLoadingScreen.SetProgress(1.0f);

    // ── Brief hold at 100% then fade out ─────────────────────────────
    yield return new WaitForSecondsRealtime(0.6f);
    CyberpunkLoadingScreen.Hide();

    // Wait for loading screen fade to finish (0.85s) before starting dialogue
    yield return new WaitForSecondsRealtime(0.9f);

    // 5. Start Beat 0 (Inside Ido's Lab dialogue)
    currentPhase = ProloguePhase.InsideClinicLab;
    if (narrativeBeats.Count > 0)
    {
        TriggerDialogueBeat(narrativeBeats[0], () =>
        {
            // Once inside-clinic dialogue completes, open doors & start city walk
            StartCoroutine(TransitionToCityWalkRoutine());
        });
    }
}

