using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using System.Text;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string interiorScenePath = "Assets/PolygonCyberCity/Scenes/Demo_Interior.unity";
        Scene interiorScene = EditorSceneManager.OpenScene(interiorScenePath, OpenSceneMode.Additive);

        StringBuilder sb = new StringBuilder();
        sb.AppendLine("Detailed Interior Bounds & Doors:");

        string[] interiorNames = new string[] {
            "Apartment", "HackerDen", "TearingDoc", "Convenience Store",
            "Shooting Range", "Weapon Store", "Micro-partment", "Noodle Shop", "Penthouse Apartment"
        };

        foreach (var name in interiorNames)
        {
            GameObject go = GameObject.Find(name);
            if (go == null) continue;

            Renderer[] renderers = go.GetComponentsInChildren<Renderer>();
            Bounds bounds = new Bounds(go.transform.position, Vector3.zero);
            if (renderers.Length > 0)
            {
                bounds = renderers[0].bounds;
                for (int i = 1; i < renderers.Length; i++)
                    bounds.Encapsulate(renderers[i].bounds);
            }

            sb.AppendLine(string.Format("\n--- [{0}] (Children: {1}) ---", name, go.transform.childCount));
            sb.AppendLine(string.Format("Center: {0}, Size: {1}", bounds.center, bounds.size));
            sb.AppendLine(string.Format("Min: {0}, Max: {1}", bounds.min, bounds.max));

            // Find door objects in this interior
            List<string> doors = new List<string>();
            foreach (Transform t in go.GetComponentsInChildren<Transform>())
            {
                if (t.name.Contains("Door") || t.name.Contains("Entrance"))
                {
                    doors.Add(string.Format("  * Door: '{0}' at world pos {1} (local pos {2})", t.name, t.position, t.localPosition));
                }
            }
            if (doors.Count > 0)
            {
                foreach (var d in doors) sb.AppendLine(d);
            }
            else
            {
                sb.AppendLine("  * No explicit door object found.");
            }
        }

        EditorSceneManager.CloseScene(interiorScene, true);
        result.Log(sb.ToString());
    }
}

