using UnityEngine;
using UnityEditor;
using System.Text;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Vector3 alitaPos = new Vector3(12.55f, -17.98f, 57.12f);
        var allRenderers = Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None);

        StringBuilder sb = new StringBuilder();
        sb.AppendLine("Doors and Shopfronts in Demo_City near Alita:");

        List<KeyValuePair<float, GameObject>> nearDoors = new List<KeyValuePair<float, GameObject>>();
        foreach (var r in allRenderers)
        {
            string n = r.gameObject.name;
            if (n.Contains("Door") || n.Contains("Shop") || n.Contains("Entrance"))
            {
                // skip vehicles
                if (n.Contains("Veh") || n.Contains("Train") || n.Contains("Truck") || n.Contains("Car") || n.Contains("SUV")) continue;

                float dist = Vector3.Distance(alitaPos, r.transform.position);
                nearDoors.Add(new KeyValuePair<float, GameObject>(dist, r.gameObject));
            }
        }

        nearDoors.Sort((a, b) => a.Key.CompareTo(b.Key));
        sb.AppendLine(string.Format("Found {0} building doors/shops. Showing closest 30:", nearDoors.Count));
        for (int i = 0; i < Mathf.Min(nearDoors.Count, 30); i++)
        {
            var pair = nearDoors[i];
            var d = pair.Value;
            sb.AppendLine(string.Format("  - Dist {0:F1}m: '{1}' at pos {2} (rot: {3})", 
                pair.Key, d.name, d.transform.position, d.transform.rotation.eulerAngles));
        }

        result.Log(sb.ToString());
    }
}

