using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // 1. Ensure Demo_City is open
        string cityPath = "Assets/PolygonCyberCity/Scenes/Demo_City.unity";
        Scene cityScene = SceneManager.GetActiveScene();
        if (cityScene.path != cityPath)
        {
            cityScene = EditorSceneManager.OpenScene(cityPath, OpenSceneMode.Single);
        }

        // Check if [Interiors_Sublevel] already exists
        GameObject existingSublevel = GameObject.Find("[Interiors_Sublevel]");
        if (existingSublevel != null)
        {
            result.DestroyObject(existingSublevel);
            result.Log("Removed previous [Interiors_Sublevel] for fresh import.");
        }

        // 2. Open Demo_Interior additively
        string interiorScenePath = "Assets/PolygonCyberCity/Scenes/Demo_Interior.unity";
        Scene interiorScene = EditorSceneManager.OpenScene(interiorScenePath, OpenSceneMode.Additive);

        // 3. Create parent in Demo_City
        GameObject sublevel = new GameObject("[Interiors_Sublevel]");
        SceneManager.MoveGameObjectToScene(sublevel, cityScene);
        sublevel.transform.position = new Vector3(0f, -200f, 0f);
        sublevel.transform.rotation = Quaternion.identity;
        sublevel.transform.localScale = Vector3.one;
        result.RegisterObjectCreation(sublevel);

        string[] targetsToCopy = new string[] {
            "Apartment", "HackerDen", "TearingDoc", "Convenience Store",
            "Shooting Range", "Weapon Store", "Micro-partment", "Noodle Shop",
            "Penthouse Apartment", "Lighting"
        };

        HashSet<string> targetSet = new HashSet<string>(targetsToCopy);

        int copiedCount = 0;
        foreach (var rootGO in interiorScene.GetRootGameObjects())
        {
            if (targetSet.Contains(rootGO.name) || rootGO.name.StartsWith("SM_Prop_Medical_Chair") || rootGO.name.StartsWith("SM_Prop_Cuff"))
            {
                // Instantiate a clone in cityScene
                GameObject clone = Object.Instantiate(rootGO);
                clone.name = rootGO.name;
                SceneManager.MoveGameObjectToScene(clone, cityScene);

                // Store original world transform
                Vector3 origPos = rootGO.transform.position;
                Quaternion origRot = rootGO.transform.rotation;
                Vector3 origScale = rootGO.transform.localScale;

                // Parent to sublevel
                clone.transform.SetParent(sublevel.transform, false);
                clone.transform.localPosition = origPos;
                clone.transform.localRotation = origRot;
                clone.transform.localScale = origScale;

                result.RegisterObjectCreation(clone);
                copiedCount++;
            }
        }

        // Close Demo_Interior without saving
        EditorSceneManager.CloseScene(interiorScene, true);

        // Mark cityScene dirty and save
        EditorSceneManager.MarkSceneDirty(cityScene);
        EditorSceneManager.SaveScene(cityScene);

        result.Log("Successfully imported {0} interior groups into Demo_City under [Interiors_Sublevel] at Y = -200! Scene saved.", copiedCount);
    }
}

