    public void Execute(ExecutionResult result)
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine("=== Spawn Point Floor Raycast Validation ===");

        (string name, Vector3 extSpawn, Vector3 intSpawn)[] testPoints = new (string, Vector3, Vector3)[]
        {
            ("IdoClinic", new Vector3(18.0f, -16.0f, 48.5f), new Vector3(-21.0f, -198.0f, 2.5f)),
            ("NoodleShop", new Vector3(27.5f, -16.0f, 60.0f), new Vector3(-10.0f, -198.0f, -10.0f)),
            ("WeaponStore", new Vector3(16.5f, -19.0f, 41.25f), new Vector3(6.5f, -198.0f, -10.5f)),
            ("ShootingRange", new Vector3(19.98f, -16.0f, 33.0f), new Vector3(20.4f, -198.0f, 3.5f)),
            ("HackerDen", new Vector3(-16.0f, -16.0f, 58.75f), new Vector3(1.5f, -198.0f, 3.5f)),
            ("ConvenienceStore", new Vector3(-20.0f, -16.0f, 62.5f), new Vector3(-38.0f, -198.0f, 2.5f)),
            ("Apartment", new Vector3(-22.0f, -16.0f, 62.5f), new Vector3(-10.0f, -198.0f, 0.5f)),
            ("MicroPod", new Vector3(-13.5f, -19.0f, 33.75f), new Vector3(-2.5f, -198.0f, -10.0f)),
            ("Penthouse", new Vector3(-13.5f, -19.0f, 25.88f), new Vector3(-21.0f, -198.0f, -10.5f)),
        };

        foreach (var p in testPoints)
        {
            // Raycast exterior
            bool hitExt = Physics.Raycast(p.extSpawn + Vector3.up * 2f, Vector3.down, out RaycastHit extHit, 15f);
            float extFloorY = hitExt ? extHit.point.y : -999f;
            string extHitObj = hitExt ? extHit.collider.name : "MISS";

            // Raycast interior
            bool hitInt = Physics.Raycast(p.intSpawn + Vector3.up * 2f, Vector3.down, out RaycastHit intHit, 15f);
            float intFloorY = hitInt ? intHit.point.y : -999f;
            string intHitObj = hitInt ? intHit.collider.name : "MISS";

            sb.AppendLine(string.Format("{0}:", p.name));
            sb.AppendLine(string.Format("  Ext Floor: hit={0}, Y={1:F2} (on {2})", hitExt, extFloorY, extHitObj));
            sb.AppendLine(string.Format("  Int Floor: hit={0}, Y={1:F2} (on {2})", hitInt, intFloorY, intHitObj));
        }

        result.Log(sb.ToString());
    }
}

