            var extBeacon = new GameObject("Beacon_EXT_" + p.id);
            extBeacon.transform.SetParent(beaconsRoot.transform);
            extBeacon.transform.position = p.exteriorDoorPos + Vector3.up * 1.8f;
            var extLight = extBeacon.AddComponent<Light>();
            extLight.type = LightType.Point;
            extLight.color = new Color(0.1f, 0.9f, 1.0f); // Cyber cyan
