internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string cityPath = "Assets/PolygonCyberCity/Scenes/Demo_City.unity";
        Scene cityScene = SceneManager.GetActiveScene();
        if (cityScene.path != cityPath)
        {
            cityScene = EditorSceneManager.OpenScene(cityPath, OpenSceneMode.Single);
        }

        var teleSys = Object.FindAnyObjectByType<InteriorTeleportSystem>();
        if (teleSys != null)
        {
            teleSys.PopulateDefaultPortals();
            EditorUtility.SetDirty(teleSys);
            EditorSceneManager.MarkSceneDirty(cityScene);
            EditorSceneManager.SaveScene(cityScene);
            result.Log("Updated and serialized 9 portals in Demo_City with exact floor heights! Scene saved.");
        }
        else
        {
            result.LogError("InteriorTeleportSystem not found in scene!");
        }
    }
}

