{
    public void Execute(ExecutionResult result)
    {
        StringBuilder sb = new StringBuilder();
        var allGOs = Object.FindObjectsByType<GameObject>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        sb.AppendLine("Objects containing 'Clinic' in active scene (" + UnityEngine.SceneManagement.SceneManager.GetActiveScene().name + "):");
        int count = 0;
        foreach (var go in allGOs)
        {
            if (go.name.ToLower().Contains("clinic") || go.name.ToLower().Contains("lab"))
            {
                sb.AppendLine(string.Format("  - '{0}' at pos {1}, active={2}, parent={3}", 
                    go.name, go.transform.position, go.activeSelf, go.transform.parent != null ? go.transform.parent.name : "root"));
                count++;
            }
        }
        sb.AppendLine("Total found: " + count);
        result.Log(sb.ToString());
    }
}

