        private bool _waitingForPlayer = false;

        // Runtime Clinic Environment
        private GameObject _clinicRoot;
        private Transform _doorLeft;
        private Transform _doorRight;
        private Vector3 _doorLeftClosedPos;
        private Vector3 _doorRightClosedPos;
        private Vector3 _doorLeftOpenPos;
        private Vector3 _doorRightOpenPos;
        private bool _isDoorsOpen = false;

        // Subtitle & Dialogue State (Exact Cutscene OnGUI System)
        private DialogueLine _activeDialogueLine = null;
        private float _lineTimer = 0f;
        private float _lineDuration = 6.0f;
        private int _currentBeatLineIndex = 0;
        private PrologueDialogueBeat _activeBeat = null;
        private Action _onBeatCompletedCallback = null;

        // Visual Assets for Cutscene Subtitles
        private Texture2D _blackPixel;
        private Texture2D _whitePixel;
        private Sprite _defaultDoctorPortrait;
        private Sprite _defaultAlitaPortrait;

        // Screen Fade In
        private float _introFadeAlpha = 1.0f;

        private void Awake()
        {
            if (Instance != null && Instance != this)
            {
                Destroy(gameObject);
                return;
            }
            Instance = this;

            InitTextures();
            LoadPortraits();
            InitializeNarrativeBeats();
        }

        private void Start()
        {
            if (autoStartPrologueOnAwake)
            {
                StartCoroutine(BootPrologueRoutine());
            }
        }

        private void InitTextures()
        {
            _blackPixel = new Texture2D(1, 1);
            _blackPixel.SetPixel(0, 0, new Color(0.02f, 0.025f, 0.04f, 0.92f));
            _blackPixel.Apply();

            _whitePixel = new Texture2D(1, 1);
            _whitePixel.SetPixel(0, 0, Color.white);
            _whitePixel.Apply();
        }

        private void LoadPortraits()
        {
#if UNITY_EDITOR
            _defaultDoctorPortrait = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Characters/Doctor/Textures/T_Doctor_Ido_HoloPortrait.png");
            _defaultAlitaPortrait = UnityEditor.AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Characters/Alita/Textures/T_Alita_HoloPortrait.png");
#endif
        }

        private IEnumerator BootPrologueRoutine()
        {
            // Wait 2 frames for scene initialization
            yield return null;
            yield return null;

            // ── Show loading screen immediately ──────────────────────────────
            CyberpunkLoadingScreen.Show("INITIALIZING IRON CITY SECTOR 7...");
            CyberpunkLoadingScreen.SetProgress(0.05f);
            yield return null;

            // 1. Build Dr. Ido's Cyber Clinic Lab in memory (deferred across frames to avoid GPU crash)
            CyberpunkLoadingScreen.SetStatus("CONSTRUCTING IDO'S CYBER-REPAIR CLINIC...");
            CyberpunkLoadingScreen.SetProgress(0.15f);
            yield return StartCoroutine(SpawnClinicLabCoroutine());
            CyberpunkLoadingScreen.SetProgress(0.55f);
            yield return null;

            // 2. Acquire Player and position inside clinic beside examination slab
            CyberpunkLoadingScreen.SetStatus("LOCATING ALITA-UNIT...");
            AcquirePlayerAndPositionInClinic();
            CyberpunkLoadingScreen.SetProgress(0.70f);
            yield return null;

            // 3. Spawn Dr. Dyson Ido inside the clinic facing Alita
            CyberpunkLoadingScreen.SetStatus("SPAWNING DR. DYSON IDO...");
            SpawnDoctorInClinic();
            CyberpunkLoadingScreen.SetProgress(0.82f);
            yield return null;

            // 4. Ensure camera is following player and movement is unlocked immediately
            if (mainCamera == null) mainCamera = Camera.main;
            if (mainCamera != null && smoothOrbitCamera == null)
            {
                smoothOrbitCamera = mainCamera.GetComponent<SmoothOrbitCamera>();
            }
            if (smoothOrbitCamera != null)
            {
                smoothOrbitCamera.enabled = true;
                smoothOrbitCamera.target = playerTransform;
            }

            CyberpunkLoadingScreen.SetStatus("CALIBRATING NEURAL LINKS...");
            CyberpunkLoadingScreen.SetProgress(0.94f);
            yield return new WaitForSecondsRealtime(0.4f);

            LockPlayerMovement(false);
            CyberpunkLoadingScreen.SetProgress(1.0f);

            // ── Brief hold at 100% then fade out ─────────────────────────────
            yield return new WaitForSecondsRealtime(0.6f);
            CyberpunkLoadingScreen.Hide();

            // Wait for loading screen fade to finish (0.85s) before starting dialogue
            yield return new WaitForSecondsRealtime(0.9f);

            // 5. Start Beat 0 (Inside Ido's Lab dialogue)
            currentPhase = ProloguePhase.InsideClinicLab;
            if (narrativeBeats.Count > 0)
            {
                TriggerDialogueBeat(narrativeBeats[0], () =>
                {
                    // Once inside-clinic dialogue completes, open doors & start city walk
                    StartCoroutine(TransitionToCityWalkRoutine());
                });
            }
        }


        private void AcquirePlayerAndPositionInClinic()
        {
            if (playerObject == null) playerObject = GameObject.FindWithTag("Player");
            if (playerObject == null)
            {
                var locomotion = FindAnyObjectByType<SyntySwordLocomotionController>();
                if (locomotion != null) playerObject = locomotion.gameObject;
            }

            if (playerObject != null)
            {
                playerTransform = playerObject.transform;

                // Position player inside clinic beside the surgical table
                Vector3 insideClinicPos = new Vector3(12.55f, -17.92f, 56.5f);

                CharacterController cc = playerObject.GetComponent<CharacterController>();
                if (cc != null) cc.enabled = false;

                playerTransform.position = insideClinicPos;
                playerTransform.rotation = Quaternion.Euler(0f, 180f, 0f);

                if (cc != null) cc.enabled = true;
            }
        }

        private void SpawnDoctorInClinic()
        {
            if (doctorActor != null) return;

            Vector3 idoClinicPos = new Vector3(11.2f, -17.92f, 57.5f);

            doctorActor = new GameObject("Doctor_Actor_Runtime");
            doctorActor.transform.position = idoClinicPos;
            doctorActor.transform.rotation = Quaternion.Euler(0f, 135f, 0f);

            // Load Doctor Model
            GameObject prefab = doctorPrefab;
#if UNITY_EDITOR
            if (prefab == null)
            {
                prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Characters/Doctor/Doctor.prefab")
                      ?? UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PolygonCyberCity/Prefabs/Characters/SM_Chr_Rich_Male_01.prefab");
            }
#endif
            GameObject modelInstance;
            if (prefab != null)
            {
                modelInstance = Instantiate(prefab, doctorActor.transform);
            }
            else
            {
                modelInstance = GameObject.CreatePrimitive(PrimitiveType.Capsule);
                modelInstance.transform.SetParent(doctorActor.transform, false);
            }

            modelInstance.name = "Doctor_Model";
            modelInstance.transform.localPosition = Vector3.zero;
            modelInstance.transform.localRotation = Quaternion.identity;

            // Simple transform escort (no NavMesh required)
            _currentEscortDest = idoClinicPos;
            _escortActive = false;

            // Animator
            doctorAnimator = modelInstance.GetComponent<Animator>();
#if UNITY_EDITOR
            if (doctorAnimator != null && doctorAnimator.runtimeAnimatorController == null)
            {
                var ac = UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_CyberNPC.controller")
                      ?? UnityEditor.AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>("Assets/Animations/Alita/AC_Ido_Discovery.controller");
                if (ac != null) doctorAnimator.runtimeAnimatorController = ac;
            }
#endif
            doctorTransform = doctorActor.transform;
        }

        // ─────────────────────────────────────────────────────────────────────
        // 1. RUNTIME CLINIC LAB & SLIDING DOORS (DEFERRED COROUTINE - GPU SAFE)
        // ─────────────────────────────────────────────────────────────────────

        // Single shared materials to avoid GPU Resident Drawer crash from per-primitive new Material()
        private static Material _sharedWallMat;
        private static Material _sharedFloorMat;
        private static Material _sharedGlassMat;

        private IEnumerator SpawnClinicLabCoroutine()
        {
            if (_clinicRoot != null) yield break;

            // Create shared materials ONCE (prevents GPU crash from many new Material() calls)
            if (_sharedWallMat == null)
            {
                _sharedWallMat = CreateCyberWallMaterial();
                _sharedFloorMat = CreateCyberFloorMaterial();
                _sharedGlassMat = CreateCyberGlassMaterial();
            }

            _clinicRoot = new GameObject("Ido_Cyber_Clinic_Runtime");
            _clinicRoot.transform.position = new Vector3(12.55f, -17.92f, 57.0f);
            _clinicRoot.transform.rotation = Quaternion.identity;

            // Spread geometry across frames to avoid GPU Resident Drawer race condition
            // Frame 1: Floor + Ceiling
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Floor",
                new Vector3(0f, -0.05f, 0f), new Vector3(12f, 0.1f, 10f), _sharedFloorMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Ceiling",
                new Vector3(0f, 4.2f, 0f), new Vector3(12f, 0.1f, 10f), _sharedWallMat);
            yield return null;

            // Frame 2: Walls
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Back",
                new Vector3(0f, 2.1f, 5.0f), new Vector3(12f, 4.2f, 0.2f), _sharedWallMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Left",
                new Vector3(-6.0f, 2.1f, 0f), new Vector3(0.2f, 4.2f, 10f), _sharedWallMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Right",
                new Vector3(6.0f, 2.1f, 0f), new Vector3(0.2f, 4.2f, 10f), _sharedWallMat);
            yield return null;

            // Frame 3: Front wall with doorway gap
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Front_Left",
                new Vector3(-3.75f, 2.1f, -5.0f), new Vector3(4.5f, 4.2f, 0.2f), _sharedWallMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Front_Right",
                new Vector3(3.75f, 2.1f, -5.0f), new Vector3(4.5f, 4.2f, 0.2f), _sharedWallMat);
            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_Wall_Front_Header",
                new Vector3(0f, 3.6f, -5.0f), new Vector3(3.0f, 1.2f, 0.2f), _sharedWallMat);
            yield return null;

            // Frame 4: Doors + Slab
            _doorLeftClosedPos  = new Vector3(-0.75f, 1.5f, -5.0f);
            _doorRightClosedPos = new Vector3( 0.75f, 1.5f, -5.0f);
            _doorLeftOpenPos    = new Vector3(-2.4f,  1.5f, -5.0f);
            _doorRightOpenPos   = new Vector3( 2.4f,  1.5f, -5.0f);

            var doorL = CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_SlidingDoor_Left",
                _doorLeftClosedPos, new Vector3(1.55f, 3.0f, 0.08f), _sharedGlassMat);
            var doorR = CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Clinic_SlidingDoor_Right",
                _doorRightClosedPos, new Vector3(1.55f, 3.0f, 0.08f), _sharedGlassMat);
            _doorLeft  = doorL.transform;
            _doorRight = doorR.transform;

            CreatePrimitiveChild(_clinicRoot, PrimitiveType.Cube, "Surgical_Examination_Bed",
                new Vector3(0f, 0.65f, 1.2f), new Vector3(0.9f, 0.28f, 2.2f), _sharedWallMat);
            yield return null;

            // Frame 5: Lights only
            SpawnClinicLights();
            yield return null;

            // Frame 6: Optional synty props (editor only)
#if UNITY_EDITOR
            TryInstantiateSyntyProp("Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Desk_01.prefab",
                new Vector3(-3.2f, 0f, 2.0f), Quaternion.Euler(0f, 90f, 0f));
            TryInstantiateSyntyProp("Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Server_01.prefab",
                new Vector3(3.5f, 0f, 2.5f), Quaternion.Euler(0f, -90f, 0f));
            TryInstantiateSyntyProp("Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Medical_Chair_01.prefab",
                new Vector3(3.5f, 0f, -1.5f), Quaternion.Euler(0f, -135f, 0f));
            yield return null;
#endif
        }

        private void SpawnClinicLights()
        {
            // Overhead Surgical Spotlight
            var spotGO = new GameObject("Overhead_Surgical_Spotlight");
            spotGO.transform.SetParent(_clinicRoot.transform, false);
            spotGO.transform.localPosition = new Vector3(0f, 3.9f, 1.2f);
            spotGO.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            var spotLight = spotGO.AddComponent<Light>();
            spotLight.type = LightType.Spot;
            spotLight.color = new Color(0.2f, 0.95f, 1f);
            spotLight.range = 8f;
            spotLight.spotAngle = 60f;
            spotLight.intensity = 4.5f;

            // Warm Amber Desk Lamp
            var deskLightGO = new GameObject("Ido_Workbench_Ambient_Lamp");
            deskLightGO.transform.SetParent(_clinicRoot.transform, false);
            deskLightGO.transform.localPosition = new Vector3(-3.2f, 2.0f, 2.0f);
            var deskLight = deskLightGO.AddComponent<Light>();
            deskLight.type = LightType.Point;
            deskLight.color = new Color(1f, 0.72f, 0.28f);
            deskLight.range = 7f;
            deskLight.intensity = 3.0f;

            // Exterior Neon Sign
            var signGO = new GameObject("Neon_Sign_Clinic_Exterior");
            signGO.transform.SetParent(_clinicRoot.transform, false);
            signGO.transform.localPosition = new Vector3(0f, 3.8f, -5.2f);
            var signLight = signGO.AddComponent<Light>();
            signLight.type = LightType.Point;
            signLight.color = new Color(0.1f, 0.95f, 1f);
            signLight.range = 8f;
            signLight.intensity = 3.5f;
        }

        private GameObject CreatePrimitiveChild(GameObject parent, PrimitiveType type, string name,
            Vector3 localPos, Vector3 localScale, Material mat)
        {
            GameObject obj = GameObject.CreatePrimitive(type);
            obj.name = name;
            obj.transform.SetParent(parent.transform, false);
            obj.transform.localPosition = localPos;
            obj.transform.localScale = localScale;
            var rend = obj.GetComponent<Renderer>();
            if (rend != null && mat != null) rend.material = mat;
            return obj;
        }

        private void TryInstantiateSyntyProp(string assetPath, Vector3 localPos, Quaternion localRot)
        {
#if UNITY_EDITOR
            var prefab = UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(assetPath);
            if (prefab != null && _clinicRoot != null)
            {
                GameObject instance = Instantiate(prefab, _clinicRoot.transform);
                instance.transform.localPosition = localPos;
                instance.transform.localRotation = localRot;
            }
#endif
        }

        private Material CreateCyberWallMaterial()
        {
            Shader shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            Material mat = new Material(shader);
            mat.color = new Color(0.05f, 0.06f, 0.08f);
            return mat;
        }

        private Material CreateCyberFloorMaterial()
        {
            Shader shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            Material mat = new Material(shader);
            mat.color = new Color(0.03f, 0.035f, 0.05f);
            return mat;
        }

        private Material CreateCyberGlassMaterial()
        {
            Shader shader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            Material mat = new Material(shader);
            mat.color = new Color(0.1f, 0.35f, 0.45f, 0.65f);
            return mat;
        }

        private IEnumerator TransitionToCityWalkRoutine()
        {
            currentPhase = ProloguePhase.DoorsOpening;

            // Open the clinic sliding doors
            yield return StartCoroutine(OpenClinicDoorsRoutine());

            // Advance to Waypoint 1 (Street Plaza outside)
            currentWaypointIndex = 1;
            StartWalkToNextWaypoint();
        }

        private IEnumerator OpenClinicDoorsRoutine()
        {
            if (_isDoorsOpen) yield break;
            _isDoorsOpen = true;

            float duration = 1.6f;
            float elapsed = 0f;

            while (elapsed < duration)
            {
                elapsed += Time.deltaTime;
                float t = Mathf.SmoothStep(0f, 1f, elapsed / duration);

                if (_doorLeft != null) _doorLeft.localPosition = Vector3.Lerp(_doorLeftClosedPos, _doorLeftOpenPos, t);
                if (_doorRight != null) _doorRight.localPosition = Vector3.Lerp(_doorRightClosedPos, _doorRightOpenPos, t);

                yield return null;
            }

            if (_doorLeft != null) _doorLeft.localPosition = _doorLeftOpenPos;
            if (_doorRight != null) _doorRight.localPosition = _doorRightOpenPos;
        }

