    {
        var cam = Camera.main;
        var player = GameObject.FindWithTag("Player");
        var doc = GameObject.Find("Doctor_Actor_Runtime");
        if (doc == null) doc = GameObject.Find("Doctor_Actor");

        result.Log("Player pos: {0}", player != null ? player.transform.position.ToString() : "null");
        result.Log("Doctor pos: {0}", doc != null ? doc.transform.position.ToString() : "null");
        result.Log("Camera pos: {0}, rot: {1}", 
            cam != null ? cam.transform.position.ToString() : "null",
            cam != null ? cam.transform.rotation.eulerAngles.ToString() : "null");

        // Raycast forward from camera to see what is directly in front
        if (cam != null)
        {
            if (Physics.Raycast(cam.transform.position, cam.transform.forward, out RaycastHit hit, 50f))
            {
                result.Log("Camera looks directly at: '{0}' at dist {1:F1}m, pos {2}", hit.collider.name, hit.distance, hit.point);
            }
            else
            {
                result.Log("Camera looks at open sky / horizon.");
            }
        }
    }
}

