/// <summary>
/// Builds the Datacenter Vault using ONLY server racks, dense server banks,
/// and an extruded central core column radiating crimson red energy into the aisle.
/// </summary>
private static void BuildDatacenterVault(
    GameObject envRoot, 
    GameObject playerGO, 
    GameObject ripplePrefab,
    Material heroTrailMat, 
    Material enemyTrailMat)
{
    GameObject vaultRoot = new GameObject("[Datacenter_BlackRed_Vault]");
    vaultRoot.transform.SetParent(envRoot.transform, false);

    var serverPrefab   = AssetDatabase.LoadAssetAtPath<GameObject>(SERVER_RACK_PATH);
    var consolePrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(CONSOLE_PATH);
    var gatePrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(CORP_GATE_PATH);
    var neon1Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_01_PATH);
    var neon2Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_02_PATH);
    var holoSignPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(HOLO_SIGN_01_PATH);
    var girdersPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(GIRDERS_PATH);

    var enforcerPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_ENFORCER_PATH);
    var ninjaPrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_NINJA_PATH);
    var protoMechPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_MECH_PATH);

    // ── A. Pure Server Banks (Left & Right Flanks) ─────────────────────────
    // We construct two dense multi-tiered rows of servers on each side (Left and Right)
    // Stacked 2-high (Y=0 and Y=2.3) to create monumental 4.8m tall server walls!
    if (serverPrefab != null)
    {
        // Left Server Rows (Inner at X = -3.6, Outer at X = -5.0)
        // Right Server Rows (Inner at X = +3.6, Outer at X = +5.0)
        for (float z = -48f; z <= -2f; z += 1.15f)
        {
            // Leave a small gap around the central core at z in [-24, -20]
            bool isNearCore = (z >= -24.5f && z <= -19.5f);

            for (int tier = 0; tier < 2; tier++)
            {
                float yPos = tier * 2.28f;

                // Left Inner Server Rack (facing X+)
                GameObject lInner = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                lInner.name = $"Server_L_Inner_Z{z:F0}_T{tier}";
                lInner.transform.SetParent(vaultRoot.transform, false);
                lInner.transform.position = new Vector3(-3.6f, yPos, z);
                lInner.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

                // Left Outer Server Rack (facing X-)
                GameObject lOuter = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                lOuter.name = $"Server_L_Outer_Z{z:F0}_T{tier}";
                lOuter.transform.SetParent(vaultRoot.transform, false);
                lOuter.transform.position = new Vector3(-4.8f, yPos, z);
                lOuter.transform.rotation = Quaternion.Euler(0f, -90f, 0f);

                // Right Inner Server Rack (facing X-)
                GameObject rInner = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                rInner.name = $"Server_R_Inner_Z{z:F0}_T{tier}";
                rInner.transform.SetParent(vaultRoot.transform, false);
                rInner.transform.position = new Vector3(3.6f, yPos, z);
                rInner.transform.rotation = Quaternion.Euler(0f, -90f, 0f);

                // Right Outer Server Rack (facing X+)
                GameObject rOuter = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                rOuter.name = $"Server_R_Outer_Z{z:F0}_T{tier}";
                rOuter.transform.SetParent(vaultRoot.transform, false);
                rOuter.transform.position = new Vector3(4.8f, yPos, z);
                rOuter.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
            }
        }
    }

    // Consoles placed along the server walls
    if (consolePrefab != null)
    {
        GameObject con1 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
        con1.transform.SetParent(vaultRoot.transform, false);
        con1.transform.position = new Vector3(-3.0f, 0f, -38f);
        con1.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

        GameObject con2 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
        con2.transform.SetParent(vaultRoot.transform, false);
        con2.transform.position = new Vector3(3.0f, 0f, -14f);
        con2.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
    }

    // Red Ambient Strip Point Lights along the server aisle
    float[] zAisleLights = new float[] { -44f, -34f, -22f, -12f };
    foreach (float zl in zAisleLights)
    {
        GameObject lLightGO = new GameObject($"ServerAisle_Light_L_{zl}");
        lLightGO.transform.SetParent(vaultRoot.transform, false);
        lLightGO.transform.position = new Vector3(-2.8f, 2.6f, zl);
        var lLight = lLightGO.AddComponent<Light>();
        lLight.type = LightType.Point;
        lLight.color = new Color(1.0f, 0.05f, 0.12f, 1f);
        lLight.intensity = 4.0f;
        lLight.range = 8.5f;
        lLight.shadows = LightShadows.None;

        GameObject rLightGO = new GameObject($"ServerAisle_Light_R_{zl}");
        rLightGO.transform.SetParent(vaultRoot.transform, false);
        rLightGO.transform.position = new Vector3(2.8f, 2.6f, zl);
        var rLight = rLightGO.AddComponent<Light>();
        rLight.type = LightType.Point;
        rLight.color = new Color(1.0f, 0.05f, 0.12f, 1f);
        rLight.intensity = 4.0f;
        rLight.range = 8.5f;
        rLight.shadows = LightShadows.None;
    }

    // ── B. The Extruded Central Server Monolith Core (Z = -22) ────────────
    float coreZ = -22.0f;
    GameObject coreRoot = new GameObject("Central_Server_Extrusion_Core");
    coreRoot.transform.SetParent(vaultRoot.transform, false);
    coreRoot.transform.position = new Vector3(0f, 0f, coreZ);

    // Flanking Server Columns forming the central extruded monolith
    if (serverPrefab != null)
    {
        // Left extruded server column (facing inward toward the light aperture)
        for (int ty = 0; ty < 3; ty++)
        {
            float yOffset = ty * 2.28f;
            GameObject sL1 = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
            sL1.transform.SetParent(coreRoot.transform, false);
            sL1.transform.position = new Vector3(-1.0f, yOffset, coreZ);
            sL1.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

            GameObject sR1 = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
            sR1.transform.SetParent(coreRoot.transform, false);
            sR1.transform.position = new Vector3(1.0f, yOffset, coreZ);
            sR1.transform.rotation = Quaternion.Euler(0f, -90f, 0f);

            // Back backing servers enclosing the monolith
            GameObject sBack = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
            sBack.transform.SetParent(coreRoot.transform, false);
            sBack.transform.position = new Vector3(0f, yOffset, coreZ + 0.65f);
            sBack.transform.rotation = Quaternion.Euler(0f, 180f, 0f);
        }
    }

    // The Radiant Crimson Energy Laser/Plasma Extrusion Aperture in the center
    GameObject beamGO = GameObject.CreatePrimitive(PrimitiveType.Cube);
    beamGO.name = "Radiant_Crimson_Laser_Core";
    beamGO.transform.SetParent(coreRoot.transform, false);
    beamGO.transform.position = new Vector3(0f, 3.8f, coreZ);
    beamGO.transform.localScale = new Vector3(0.42f, 7.6f, 0.55f);

    var beamCol = beamGO.GetComponent<Collider>();
    if (beamCol != null) Object.DestroyImmediate(beamCol);

    var beamRenderer = beamGO.GetComponent<MeshRenderer>();
    var beamMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
    beamMat.name = "M_Datacenter_CentralCore_Beam";
    beamMat.SetColor("_BaseColor", new Color(18.0f, 0.15f, 0.28f, 1.0f));
    beamRenderer.sharedMaterial = beamMat;
    beamRenderer.shadowCastingMode = ShadowCastingMode.Off;
    AssetDatabase.CreateAsset(beamMat, "Assets/SyntyCombined/Materials/M_Datacenter_CentralCore_Beam.mat");

    // Stacked vertical point lights inside the central aperture
    List<Light> stackedLights = new List<Light>();
    float[] lightHeights = new float[] { 1.2f, 3.5f, 5.8f };
    foreach (float lh in lightHeights)
    {
        GameObject cLightGO = new GameObject($"Core_Light_Y{lh}");
        cLightGO.transform.SetParent(coreRoot.transform, false);
        cLightGO.transform.position = new Vector3(0f, lh, coreZ - 0.2f);

        var cl = cLightGO.AddComponent<Light>();
        cl.type = LightType.Point;
        cl.color = new Color(1.0f, 0.04f, 0.12f, 1.0f);
        cl.intensity = 7.5f;
        cl.range = 14.0f;
        cl.shadows = LightShadows.None;
        stackedLights.Add(cl);
    }

    // Pulsator component to breathe and pulse the red energy
    var pulsator = coreRoot.AddComponent<DatacenterRedCorePulsator>();
    pulsator.coreLights = stackedLights.ToArray();
    pulsator.coreRenderer = beamRenderer;
    pulsator.baseLightIntensity = 5.5f;
    pulsator.pulseLightIntensity = 10.0f;
    pulsator.baseEmissionColor = new Color(8.0f, 0.08f, 0.15f, 1f);
    pulsator.peakEmissionColor = new Color(20.0f, 0.2f, 0.35f, 1f);
    pulsator.pulseSpeed = 2.2f;

    // Overhead cable bridge gantry across the central core
    if (girdersPrefab != null)
    {
        GameObject gantry = (GameObject)PrefabUtility.InstantiatePrefab(girdersPrefab);
        gantry.name = "Overhead_Cable_Bridge";
        gantry.transform.SetParent(coreRoot.transform, false);
        gantry.transform.position = new Vector3(0f, 5.2f, coreZ);
        gantry.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
        gantry.transform.localScale = new Vector3(1.2f, 0.8f, 1.4f);
    }

    // ── C. Overhead Warning Signs ─────────────────────────────────────────
    if (neon1Prefab != null)
    {
        GameObject s1 = (GameObject)PrefabUtility.InstantiatePrefab(neon1Prefab);
        s1.name = "Neon_Alert_Entrance";
        s1.transform.SetParent(vaultRoot.transform, false);
        s1.transform.position = new Vector3(0f, 4.8f, -42f);
        s1.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
    }

    if (neon2Prefab != null)
    {
        GameObject s2 = (GameObject)PrefabUtility.InstantiatePrefab(neon2Prefab);
        s2.name = "Neon_Alert_Core";
        s2.transform.SetParent(vaultRoot.transform, false);
        s2.transform.position = new Vector3(0f, 6.2f, coreZ);
        s2.transform.localScale = new Vector3(1.2f, 1.2f, 1.2f);
    }

    if (holoSignPrefab != null)
    {
        GameObject hs = (GameObject)PrefabUtility.InstantiatePrefab(holoSignPrefab);
        hs.name = "Holo_HighVoltage_Gate";
        hs.transform.SetParent(vaultRoot.transform, false);
        hs.transform.position = new Vector3(0f, 4.6f, -1.8f);
        hs.transform.localScale = new Vector3(1.0f, 1.0f, 1.0f);
    }

    // ── D. High-Security Gateway Portal to Blackwall (Z = 0) ──────────────
    if (gatePrefab != null)
    {
        GameObject gateGO = (GameObject)PrefabUtility.InstantiatePrefab(gatePrefab);
        gateGO.name = "Corp_Wall_Gate_Blackwall_Portal";
        gateGO.transform.SetParent(vaultRoot.transform, false);
        gateGO.transform.position = new Vector3(0f, 0f, 0f);
        gateGO.transform.rotation = Quaternion.identity;
        gateGO.transform.localScale = new Vector3(1.0f, 1.0f, 1.0f);
    }

    // ── E. Enemies Armed with Insane Gun / Sword Combo Combat Set ────────
    // 1 & 2: Datacenter Enforcers (flanking the approach)
    if (enforcerPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, enforcerPrefab, "Datacenter_Enforcer_Alpha", 
            new Vector3(-2.2f, 0f, -34f), Quaternion.Euler(0f, 150f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);

        SpawnDatacenterEnemy(vaultRoot, enforcerPrefab, "Datacenter_Enforcer_Beta", 
            new Vector3(2.2f, 0f, -34f), Quaternion.Euler(0f, 210f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);
    }

    // 3 & 4: Cyber Ninjas (patrolling past the central core)
    if (ninjaPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, ninjaPrefab, "Cyber_Ninja_Specter", 
            new Vector3(-2.0f, 0f, -15f), Quaternion.Euler(0f, 160f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);

        SpawnDatacenterEnemy(vaultRoot, ninjaPrefab, "Cyber_Ninja_Shadow", 
            new Vector3(2.0f, 0f, -15f), Quaternion.Euler(0f, 200f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);
    }

    // 5: Heavy ProtoMech (Gatekeeper before the Blackwall threshold)
    if (protoMechPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, protoMechPrefab, "Gatekeeper_ProtoMech", 
            new Vector3(0f, 0f, -5.5f), Quaternion.Euler(0f, 180f, 0f), 340f, playerGO, ripplePrefab, enemyTrailMat);
    }
}

