/// <summary>
/// Builds the Subterranean Datacenter Vault with futuristic monolithic server towers,
/// extruded central crimson energy core, overhead cable bridges, warning signs, and Insane Gun/Sword enemies.
/// </summary>
private static void BuildDatacenterVault(
    GameObject envRoot, 
    GameObject playerGO, 
    GameObject ripplePrefab,
    Material heroTrailMat, 
    Material enemyTrailMat)
{
    GameObject vaultRoot = new GameObject("[Datacenter_BlackRed_Vault]");
    vaultRoot.transform.SetParent(envRoot.transform, false);

    var serverPrefab   = AssetDatabase.LoadAssetAtPath<GameObject>(SERVER_RACK_PATH);
    var consolePrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(CONSOLE_PATH);
    var col1Prefab     = AssetDatabase.LoadAssetAtPath<GameObject>(SCI_COLUMN_01_PATH);
    var col2Prefab     = AssetDatabase.LoadAssetAtPath<GameObject>(SCI_COLUMN_02_PATH);
    var towerPrefab    = AssetDatabase.LoadAssetAtPath<GameObject>(CORP_TOWER_PATH);
    var gatePrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(CORP_GATE_PATH);
    var wallPrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(CORP_WALL_PATH);
    var genPrefab      = AssetDatabase.LoadAssetAtPath<GameObject>(POWER_GEN_PATH);
    var neon1Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_01_PATH);
    var neon2Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_02_PATH);
    var holoSignPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(HOLO_SIGN_01_PATH);
    var girdersPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(GIRDERS_PATH);

    var enforcerPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_ENFORCER_PATH);
    var ninjaPrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_NINJA_PATH);
    var protoMechPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_MECH_PATH);

    // ── A. Left & Right Monolithic Server Towers ──────────────────────────
    float[] zPillars = new float[] { -48f, -38f, -26f, -16f, -6f };
    foreach (float zp in zPillars)
    {
        // Left Tower Column
        if (towerPrefab != null || col1Prefab != null)
        {
            var pObj = towerPrefab != null ? towerPrefab : col1Prefab;
            GameObject lPillar = (GameObject)PrefabUtility.InstantiatePrefab(pObj);
            lPillar.name = $"Left_Tower_Pillar_{zp}";
            lPillar.transform.SetParent(vaultRoot.transform, false);
            lPillar.transform.position = new Vector3(-10.5f, 0f, zp);
            lPillar.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
            lPillar.transform.localScale = new Vector3(1.35f, 1.6f, 1.35f);

            // Right Tower Column
            GameObject rPillar = (GameObject)PrefabUtility.InstantiatePrefab(pObj);
            rPillar.name = $"Right_Tower_Pillar_{zp}";
            rPillar.transform.SetParent(vaultRoot.transform, false);
            rPillar.transform.position = new Vector3(10.5f, 0f, zp);
            rPillar.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
            rPillar.transform.localScale = new Vector3(1.35f, 1.6f, 1.35f);
        }
    }

    // Server Racks along corridors
    float[] zServers = new float[] { -45f, -42f, -39f, -33f, -30f, -22f, -19f, -13f, -10f };
    if (serverPrefab != null)
    {
        foreach (float zs in zServers)
        {
            // Left server rack
            GameObject lServer = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
            lServer.name = $"ServerRack_L_{zs}";
            lServer.transform.SetParent(vaultRoot.transform, false);
            lServer.transform.position = new Vector3(-7.2f, 0f, zs);
            lServer.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
            lServer.transform.localScale = new Vector3(1.1f, 1.35f, 1.1f);

            // Right server rack
            GameObject rServer = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
            rServer.name = $"ServerRack_R_{zs}";
            rServer.transform.SetParent(vaultRoot.transform, false);
            rServer.transform.position = new Vector3(7.2f, 0f, zs);
            rServer.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
            rServer.transform.localScale = new Vector3(1.1f, 1.35f, 1.1f);
        }
    }

    // Power Generators & Consoles flanking the walls
    if (genPrefab != null)
    {
        GameObject gen1 = (GameObject)PrefabUtility.InstantiatePrefab(genPrefab);
        gen1.transform.SetParent(vaultRoot.transform, false);
        gen1.transform.position = new Vector3(-12.5f, 0f, -34f);
        gen1.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

        GameObject gen2 = (GameObject)PrefabUtility.InstantiatePrefab(genPrefab);
        gen2.transform.SetParent(vaultRoot.transform, false);
        gen2.transform.position = new Vector3(12.5f, 0f, -20f);
        gen2.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
    }

    if (consolePrefab != null)
    {
        GameObject con1 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
        con1.transform.SetParent(vaultRoot.transform, false);
        con1.transform.position = new Vector3(6.2f, 0f, -36f);
        con1.transform.rotation = Quaternion.Euler(0f, -90f, 0f);

        GameObject con2 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
        con2.transform.SetParent(vaultRoot.transform, false);
        con2.transform.position = new Vector3(-6.2f, 0f, -16f);
        con2.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
    }

    // Red Point Lights along server corridors
    float[] zLights = new float[] { -44f, -32f, -20f, -10f };
    foreach (float zl in zLights)
    {
        // Left red accent light
        GameObject lLightGO = new GameObject($"Server_Light_L_{zl}");
        lLightGO.transform.SetParent(vaultRoot.transform, false);
        lLightGO.transform.position = new Vector3(-6.5f, 2.8f, zl);
        var lLight = lLightGO.AddComponent<Light>();
        lLight.type = LightType.Point;
        lLight.color = new Color(1.0f, 0.08f, 0.12f, 1f);
        lLight.intensity = 3.5f;
        lLight.range = 10.0f;
        lLight.shadows = LightShadows.None;

        // Right red accent light
        GameObject rLightGO = new GameObject($"Server_Light_R_{zl}");
        rLightGO.transform.SetParent(vaultRoot.transform, false);
        rLightGO.transform.position = new Vector3(6.5f, 2.8f, zl);
        var rLight = rLightGO.AddComponent<Light>();
        rLight.type = LightType.Point;
        rLight.color = new Color(1.0f, 0.08f, 0.12f, 1f);
        rLight.intensity = 3.5f;
        rLight.range = 10.0f;
        rLight.shadows = LightShadows.None;
    }

    // ── B. The Monolithic Central Extrusion Core (Z = -26) ────────────────
    float coreZ = -26.0f;
    GameObject coreRoot = new GameObject("Central_Monolith_Extrusion_Core");
    coreRoot.transform.SetParent(vaultRoot.transform, false);
    coreRoot.transform.position = new Vector3(0f, 0f, coreZ);

    // Flanking Core Pillars
    if (col1Prefab != null || col2Prefab != null)
    {
        var colObj = col2Prefab != null ? col2Prefab : col1Prefab;

        GameObject lCoreCol = (GameObject)PrefabUtility.InstantiatePrefab(colObj);
        lCoreCol.name = "Core_Pillar_L";
        lCoreCol.transform.SetParent(coreRoot.transform, false);
        lCoreCol.transform.position = new Vector3(-2.2f, 0f, coreZ);
        lCoreCol.transform.localScale = new Vector3(1.5f, 2.2f, 1.5f);

        GameObject rCoreCol = (GameObject)PrefabUtility.InstantiatePrefab(colObj);
        rCoreCol.name = "Core_Pillar_R";
        rCoreCol.transform.SetParent(coreRoot.transform, false);
        rCoreCol.transform.position = new Vector3(2.2f, 0f, coreZ);
        rCoreCol.transform.localScale = new Vector3(1.5f, 2.2f, 1.5f);
    }

    // The Vertical Radiant Crimson Energy Core Beam (laser/plasma aperture)
    GameObject beamGO = GameObject.CreatePrimitive(PrimitiveType.Cube);
    beamGO.name = "Radiant_Crimson_Laser_Core";
    beamGO.transform.SetParent(coreRoot.transform, false);
    beamGO.transform.position = new Vector3(0f, 8.5f, coreZ);
    beamGO.transform.localScale = new Vector3(0.55f, 17.0f, 0.95f);

    var beamCol = beamGO.GetComponent<Collider>();
    if (beamCol != null) Object.DestroyImmediate(beamCol);

    var beamRenderer = beamGO.GetComponent<MeshRenderer>();
    var beamMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
    beamMat.name = "M_Datacenter_CentralCore_Beam";
    beamMat.SetColor("_BaseColor", new Color(14.0f, 0.2f, 0.35f, 1.0f));
    beamRenderer.sharedMaterial = beamMat;
    beamRenderer.shadowCastingMode = ShadowCastingMode.Off;
    AssetDatabase.CreateAsset(beamMat, "Assets/SyntyCombined/Materials/M_Datacenter_CentralCore_Beam.mat");

    // Vertical stacked core lights
    List<Light> stackedLights = new List<Light>();
    float[] lightHeights = new float[] { 2.0f, 6.0f, 10.5f, 15.0f };
    foreach (float lh in lightHeights)
    {
        GameObject cLightGO = new GameObject($"Core_Light_Y{lh}");
        cLightGO.transform.SetParent(coreRoot.transform, false);
        cLightGO.transform.position = new Vector3(0f, lh, coreZ);

        var cl = cLightGO.AddComponent<Light>();
        cl.type = LightType.Point;
        cl.color = new Color(1.0f, 0.05f, 0.15f, 1.0f);
        cl.intensity = 6.0f;
        cl.range = 18.0f;
        cl.shadows = LightShadows.None;
        stackedLights.Add(cl);
    }

    // Core Pulsator component
    var pulsator = coreRoot.AddComponent<DatacenterRedCorePulsator>();
    pulsator.coreLights = stackedLights.ToArray();
    pulsator.coreRenderer = beamRenderer;
    pulsator.baseLightIntensity = 4.8f;
    pulsator.pulseLightIntensity = 8.5f;
    pulsator.baseEmissionColor = new Color(5.0f, 0.1f, 0.2f, 1f);
    pulsator.peakEmissionColor = new Color(14.0f, 0.25f, 0.45f, 1f);
    pulsator.pulseSpeed = 2.0f;

    // Overhead horizontal cable bridges & gantry beams
    if (girdersPrefab != null)
    {
        GameObject g1 = (GameObject)PrefabUtility.InstantiatePrefab(girdersPrefab);
        g1.name = "Gantry_Overhead_Low";
        g1.transform.SetParent(coreRoot.transform, false);
        g1.transform.position = new Vector3(0f, 7.5f, coreZ);
        g1.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
        g1.transform.localScale = new Vector3(1.8f, 1.0f, 2.2f);

        GameObject g2 = (GameObject)PrefabUtility.InstantiatePrefab(girdersPrefab);
        g2.name = "Gantry_Overhead_High";
        g2.transform.SetParent(coreRoot.transform, false);
        g2.transform.position = new Vector3(0f, 13.0f, coreZ);
        g2.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
        g2.transform.localScale = new Vector3(1.8f, 1.0f, 2.2f);
    }

    // ── C. Overhead Holographic / Neon Warning Signs ─────────────────────
    if (neon1Prefab != null)
    {
        GameObject s1 = (GameObject)PrefabUtility.InstantiatePrefab(neon1Prefab);
        s1.name = "Neon_Alert_Entrance";
        s1.transform.SetParent(vaultRoot.transform, false);
        s1.transform.position = new Vector3(0f, 7.2f, -42f);
        s1.transform.localScale = new Vector3(1.4f, 1.4f, 1.4f);
    }

    if (neon2Prefab != null)
    {
        GameObject s2 = (GameObject)PrefabUtility.InstantiatePrefab(neon2Prefab);
        s2.name = "Neon_Alert_Core";
        s2.transform.SetParent(vaultRoot.transform, false);
        s2.transform.position = new Vector3(0f, 8.8f, -25.2f);
        s2.transform.localScale = new Vector3(1.5f, 1.5f, 1.5f);
    }

    if (holoSignPrefab != null)
    {
        GameObject hs1 = (GameObject)PrefabUtility.InstantiatePrefab(holoSignPrefab);
        hs1.name = "Holo_HighVoltage_Gate";
        hs1.transform.SetParent(vaultRoot.transform, false);
        hs1.transform.position = new Vector3(0f, 6.5f, -2.5f);
        hs1.transform.localScale = new Vector3(1.3f, 1.3f, 1.3f);
    }

    // ── D. High-Security Gateway & Blast Walls (Z = 0) ───────────────────
    if (gatePrefab != null)
    {
        GameObject gateGO = (GameObject)PrefabUtility.InstantiatePrefab(gatePrefab);
        gateGO.name = "Corp_Wall_Gate_Blackwall_Portal";
        gateGO.transform.SetParent(vaultRoot.transform, false);
        gateGO.transform.position = new Vector3(0f, 0f, 0f);
        gateGO.transform.rotation = Quaternion.identity;
        gateGO.transform.localScale = new Vector3(1.25f, 1.25f, 1.25f);
    }

    if (wallPrefab != null)
    {
        GameObject lWall = (GameObject)PrefabUtility.InstantiatePrefab(wallPrefab);
        lWall.name = "BlastWall_L";
        lWall.transform.SetParent(vaultRoot.transform, false);
        lWall.transform.position = new Vector3(-8.5f, 0f, 0f);
        lWall.transform.rotation = Quaternion.identity;
        lWall.transform.localScale = new Vector3(1.25f, 1.25f, 1.25f);

        GameObject rWall = (GameObject)PrefabUtility.InstantiatePrefab(wallPrefab);
        rWall.name = "BlastWall_R";
        rWall.transform.SetParent(vaultRoot.transform, false);
        rWall.transform.position = new Vector3(8.5f, 0f, 0f);
        rWall.transform.rotation = Quaternion.identity;
        rWall.transform.localScale = new Vector3(1.25f, 1.25f, 1.25f);
    }

    // ── E. Enemies Armed with Insane Gun / Sword Combo Combat Set ────────
    // 1 & 2: Datacenter Enforcers (Approach guards)
    if (enforcerPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, enforcerPrefab, "Datacenter_Enforcer_Alpha", 
            new Vector3(-4.2f, 0f, -36f), Quaternion.Euler(0f, 150f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);

        SpawnDatacenterEnemy(vaultRoot, enforcerPrefab, "Datacenter_Enforcer_Beta", 
            new Vector3(4.2f, 0f, -36f), Quaternion.Euler(0f, 210f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);
    }

    // 3 & 4: Cyber Ninjas (Core defenders)
    if (ninjaPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, ninjaPrefab, "Cyber_Ninja_Specter", 
            new Vector3(-3.2f, 0f, -17f), Quaternion.Euler(0f, 160f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);

        SpawnDatacenterEnemy(vaultRoot, ninjaPrefab, "Cyber_Ninja_Shadow", 
            new Vector3(3.2f, 0f, -17f), Quaternion.Euler(0f, 200f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);
    }

    // 5: Heavy ProtoMech (Gatekeeper before Blackwall)
    if (protoMechPrefab != null)
    {
        SpawnDatacenterEnemy(vaultRoot, protoMechPrefab, "Gatekeeper_ProtoMech", 
            new Vector3(0f, 0f, -7.5f), Quaternion.Euler(0f, 180f, 0f), 340f, playerGO, ripplePrefab, enemyTrailMat);
    }
}

