using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using UnityEditor;
using UnityEditor.SceneManagement;
using SyntyCombined;
using InsaneGun.Combat;
using InsaneGun.Testing;

namespace InsaneGun.Editor
{
    /// <summary>
    /// Dedicated scene builder for the complete Blackwall Cyberspace & Datacenter experience:
    /// - An enclosed Datacenter Room (Z = -46 to Z = 15.5) with walls, ceiling, and reflective floor:
    ///   * Multi-tiered server banks lining the left and right walls exclusively
    ///   * An extruded central server monolith core in the middle of the room radiating crimson red laser/light
    ///   * Overhead cable bridges, structural pillars, and nitrogen cooling vents
    ///   * Patrolling enemies with Insane Gun / Sword combo combat set
    /// - At the end of the room (Z = 16.5): The colossal 200m authentic Blackwall LiDAR barrier looming directly as the terminator wall!
    /// </summary>
    public static class BlackwallCyberspaceSceneBuilder
    {
        public const string SCENE_PATH = "Assets/Scenes/Scene_Blackwall_Cyberspace.unity";

        // Asset paths
        private const string BLACKWALL_MESH_PATH     = "Assets/BlackwallMesh/Blackwall_UltraHD_200m_Mesh.asset";
        private const string BLACKWALL_MAT_PATH      = "Assets/SyntyCombined/Materials/M_Blackwall_Authentic_Lidar.mat";
        private const string MIRROR_FLOOR_MAT_PATH   = "Assets/InsaneGun_Sword_Set/Materials/M_Cyberspace_Water_Mirror.mat";
        private const string GHOST_ATTACK_AUDIO_PATH  = "Assets/Audio/Blackwall/cyberpunk-2077-blackwall-ghost-attack.mp3";
        private const string AMBIENT_MUSIC_PATH      = "Assets/Audio/Blackwall/51-beyond-the-blackwall.mp3";
        private const string SPACE_SKYBOX_PATH       = "Assets/Synty/PolygonSciFiWorlds/Materials/Misc/SkyBoxSpace_01.mat";
        private const string PLAYER_PREFAB_PATH      = "Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab";
        private const string WATER_RIPPLE_PATH       = "Assets/Synty/PolygonParticles/Prefabs/FX_WaterRipple_01.prefab";
        private const string SPARKS_FX_PATH          = "Assets/Synty/PolygonParticles/Prefabs/FX_Sparks_01.prefab";
        private const string ELECTRICITY_FX_PATH     = "Assets/Synty/PolygonParticles/Prefabs/FX_Electricity_01.prefab";
        private const string ROGUE_AI_PREFAB_PATH    = "Assets/SyntyCombined/Prefabs/PF_SwordEnemy_CyberCity.prefab";

        // Datacenter Assets
        private const string SERVER_RACK_PATH        = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Server_01.prefab";
        private const string CONSOLE_PATH            = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Console_01.prefab";
        private const string CORP_GATE_PATH          = "Assets/Synty/PolygonSciFiWorlds/Prefabs/Buildings/SM_Bld_Corp_Wall_Gate_01.prefab";
        private const string NEON_SIGN_01_PATH       = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_NeonSign_01.prefab";
        private const string NEON_SIGN_02_PATH       = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_NeonSign_02.prefab";
        private const string HOLO_SIGN_01_PATH       = "Assets/PolygonCyberCity/Prefabs/Props/SM_Prop_Holo_Sign_01.prefab";
        private const string GIRDERS_PATH            = "Assets/Synty/PolygonSciFiWorlds/Prefabs/Buildings/SM_Bld_Bridge_Rail_Pillar_01.prefab";

        // Combat Enemies with Insane Gun / Sword Combo
        private const string ENEMY_ENFORCER_PATH     = "Assets/Prefabs/Mission1_Enemy_Enforcer.prefab";
        private const string ENEMY_NINJA_PATH        = "Assets/Prefabs/Mission1_Enemy_Ninja.prefab";
        private const string ENEMY_MECH_PATH         = "Assets/Prefabs/Mission1_Enemy_ProtoMech.prefab";

        // The Blackwall stands right at the end of the server room!
        private const float BLACKWALL_Z = 16.5f;

        [MenuItem("Tools/Cyberpunk Blackwall Arena/Build Dedicated Blackwall Scene", priority = 0)]
        public static void BuildStandaloneBlackwallScene()
        {
            Debug.Log("<color=#FF0055><b>[Blackwall Scene Builder]</b></color> Building enclosed Datacenter Room with Blackwall at the end...");

            // 1. Create clean scene
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);

            // 2. Load Core Assets
            var blackwallMesh = AssetDatabase.LoadAssetAtPath<Mesh>(BLACKWALL_MESH_PATH);
            var blackwallMat = AssetDatabase.LoadAssetAtPath<Material>(BLACKWALL_MAT_PATH);
            var mirrorFloorMat = AssetDatabase.LoadAssetAtPath<Material>(MIRROR_FLOOR_MAT_PATH);
            var ghostAttackClip = AssetDatabase.LoadAssetAtPath<AudioClip>(GHOST_ATTACK_AUDIO_PATH);
            var ambientMusicClip = AssetDatabase.LoadAssetAtPath<AudioClip>(AMBIENT_MUSIC_PATH);
            var spaceSkybox = AssetDatabase.LoadAssetAtPath<Material>(SPACE_SKYBOX_PATH);
            var playerPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(PLAYER_PREFAB_PATH);
            var rogueAIPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(ROGUE_AI_PREFAB_PATH);
            var ripplePrefab = AssetDatabase.LoadAssetAtPath<GameObject>(WATER_RIPPLE_PATH);
            var sparksPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(SPARKS_FX_PATH);
            var electricityPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(ELECTRICITY_FX_PATH);

            var heroTrailMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/SyntyCombined/Materials/Mat_HeroTrail_Alpha.mat");
            var enemyTrailMat = AssetDatabase.LoadAssetAtPath<Material>("Assets/SyntyCombined/Materials/Mat_EnemyTrail_Alpha.mat");

            // 3. Environment Root
            GameObject envRoot = new GameObject("[Blackwall_Cyberspace_Environment]");

            // 4. Cyberspace Atmosphere & Skybox
            if (spaceSkybox != null) RenderSettings.skybox = spaceSkybox;
            RenderSettings.fog = true;
            RenderSettings.fogMode = FogMode.ExponentialSquared;
            RenderSettings.fogColor = new Color(0.008f, 0.008f, 0.015f, 1.0f);
            RenderSettings.fogDensity = 0.015f;
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.035f, 0.02f, 0.035f, 1.0f);

            // 5. Directional Cyber Fill Light
            GameObject dirLightGO = new GameObject("Directional_Cyberspace_Light");
            dirLightGO.transform.SetParent(envRoot.transform, false);
            dirLightGO.transform.rotation = Quaternion.Euler(40f, -30f, 0f);
            var dirLight = dirLightGO.AddComponent<Light>();
            dirLight.type = LightType.Directional;
            dirLight.color = new Color(0.3f, 0.35f, 0.5f, 1.0f);
            dirLight.intensity = 0.4f;
            dirLight.shadows = LightShadows.Soft;

            // 6. Ambient Soundtrack (2D Beyond the Blackwall)
            if (ambientMusicClip != null)
            {
                GameObject bgmGO = new GameObject("Blackwall_Atmosphere_AudioSource");
                bgmGO.transform.SetParent(envRoot.transform, false);
                var bgmSource = bgmGO.AddComponent<AudioSource>();
                bgmSource.clip = ambientMusicClip;
                bgmSource.loop = true;
                bgmSource.volume = 0.45f;
                bgmSource.spatialBlend = 0.0f;
                bgmSource.playOnAwake = true;
            }

            // 7. Planar Mirror Water Floor (covers entire room and beyond: Z = -60 to +60)
            GameObject floorGO = GameObject.CreatePrimitive(PrimitiveType.Plane);
            floorGO.name = "Cyberspace_SaltLake_MirrorFloor";
            floorGO.transform.SetParent(envRoot.transform, false);
            floorGO.transform.position = new Vector3(0f, 0f, 0f);
            floorGO.transform.localScale = new Vector3(16.0f, 1.0f, 16.0f);

            var oldCol = floorGO.GetComponent<Collider>();
            if (oldCol != null) Object.DestroyImmediate(oldCol);
            var floorCol = floorGO.AddComponent<BoxCollider>();
            floorCol.center = new Vector3(0f, -0.05f, 0f);
            floorCol.size = new Vector3(10f, 0.1f, 10f);

            var floorRenderer = floorGO.GetComponent<MeshRenderer>();
            if (floorRenderer != null && mirrorFloorMat != null)
            {
                floorRenderer.sharedMaterial = mirrorFloorMat;
                floorRenderer.shadowCastingMode = ShadowCastingMode.Off;
                floorRenderer.receiveShadows = true;
            }

            var planarMirror = floorGO.AddComponent<CyberspacePlanarMirror>();
            planarMirror.planeHeight = 0.0f;
            planarMirror.clipPlaneOffset = 0.05f;
            planarMirror.floorRenderer = floorRenderer;
            planarMirror.mirrorMaterial = mirrorFloorMat;
            planarMirror.textureResolution = 1024;
            planarMirror.renderScale = 1.0f;
            planarMirror.reflectionLayers = ~0;
            planarMirror.renderInEditor = true;

            // 8. 200m Towering Authentic Blackwall LiDAR Matrix Barrier right at Z = 16.5 (The End of the Room!)
            GameObject blackwallGO = new GameObject("Blackwall_Canonical_Lidar_Wall");
            blackwallGO.transform.SetParent(envRoot.transform, false);
            blackwallGO.transform.position = new Vector3(0f, 0f, BLACKWALL_Z);
            blackwallGO.transform.rotation = Quaternion.identity;
            blackwallGO.transform.localScale = new Vector3(3.0f, 2.0f, 1.0f);

            var wallFilter = blackwallGO.AddComponent<MeshFilter>();
            if (blackwallMesh != null) wallFilter.sharedMesh = blackwallMesh;

            var wallRenderer = blackwallGO.AddComponent<MeshRenderer>();
            if (blackwallMat != null)
            {
                wallRenderer.sharedMaterial = blackwallMat;
                wallRenderer.shadowCastingMode = ShadowCastingMode.Off;
                wallRenderer.receiveShadows = true;
            }

            var wallCol = blackwallGO.AddComponent<BoxCollider>();
            wallCol.center = new Vector3(0f, 18f, 0f);
            wallCol.size = new Vector3(85f, 36f, 2.0f);
            wallCol.isTrigger = false;

            var wallAudio = blackwallGO.AddComponent<AudioSource>();
            if (ghostAttackClip != null)
            {
                wallAudio.clip = ghostAttackClip;
                wallAudio.loop = true;
                wallAudio.volume = 0.35f;
                wallAudio.spatialBlend = 1.0f;
                wallAudio.minDistance = 6.0f;
                wallAudio.maxDistance = 65.0f;
                wallAudio.playOnAwake = true;
            }

            var barrier = blackwallGO.AddComponent<BlackwallRogueAIBarrier>();
            barrier.blackwallSoundLoop = ghostAttackClip;
            barrier.audioReactive = true;
            barrier.enableZDisplacement = true;
            barrier.shockDamage = 45.0f;
            barrier.contactCooldown = 0.45f;

            for (int li = -4; li <= 4; li++)
            {
                float xPos = li * 9.5f;
                GameObject beaconGO = new GameObject($"Blackwall_Beacon_{li}");
                beaconGO.transform.SetParent(blackwallGO.transform, false);
                beaconGO.transform.position = new Vector3(xPos, 2.8f, BLACKWALL_Z - 1.2f);

                var bLight = beaconGO.AddComponent<Light>();
                bLight.type = LightType.Point;
                bLight.color = new Color(1.0f, 0.04f, 0.15f, 1.0f);
                bLight.intensity = 6.0f;
                bLight.range = 20.0f;
                bLight.shadows = LightShadows.None;
            }

            if (sparksPrefab != null)
            {
                GameObject sparkGO = (GameObject)PrefabUtility.InstantiatePrefab(sparksPrefab);
                if (sparkGO != null)
                {
                    sparkGO.name = "RogueAI_Sparks_FX";
                    sparkGO.transform.SetParent(blackwallGO.transform, false);
                    sparkGO.transform.position = new Vector3(0f, 1.2f, BLACKWALL_Z - 0.5f);
                    barrier.rogueAISparksVFX = sparkGO.GetComponent<ParticleSystem>();
                }
            }

            if (electricityPrefab != null)
            {
                GameObject elecGO = (GameObject)PrefabUtility.InstantiatePrefab(electricityPrefab);
                if (elecGO != null)
                {
                    elecGO.name = "RogueAI_Electricity_FX";
                    elecGO.transform.SetParent(blackwallGO.transform, false);
                    elecGO.transform.position = new Vector3(0f, 3.5f, BLACKWALL_Z - 0.5f);
                    barrier.rogueAILightningVFX = elecGO.GetComponent<ParticleSystem>();
                }
            }

            barrier.CollectRenderersAndLights();

            // 9. Global Post-Processing Volume
            GameObject volumeGO = new GameObject("AAA_Cyberpunk_PostProcess_Volume");
            volumeGO.transform.SetParent(envRoot.transform, false);
            var volume = volumeGO.AddComponent<Volume>();
            volume.isGlobal = true;
            volume.priority = 10f;

            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
            profile.name = "Blackwall_Cyberspace_Profile";

            var bloom = profile.Add<Bloom>(true);
            bloom.threshold.Override(1.05f);
            bloom.intensity.Override(1.85f);
            bloom.scatter.Override(0.72f);
            bloom.tint.Override(new Color(1.0f, 0.25f, 0.35f));

            var colorAdjust = profile.Add<ColorAdjustments>(true);
            colorAdjust.postExposure.Override(0.25f);
            colorAdjust.contrast.Override(30f);
            colorAdjust.saturation.Override(20f);

            var tonemapping = profile.Add<Tonemapping>(true);
            tonemapping.mode.Override(TonemappingMode.ACES);

            var chromaticAberration = profile.Add<ChromaticAberration>(true);
            chromaticAberration.intensity.Override(0.35f);

            var vignette = profile.Add<Vignette>(true);
            vignette.intensity.Override(0.35f);
            vignette.smoothness.Override(0.45f);

            volume.profile = profile;
            AssetDatabase.CreateAsset(profile, "Assets/InsaneGun_Sword_Set/Blackwall_PostProcess_Profile.asset");

            // 10. Instantiate Player Character (Alita Hero) inside Datacenter Room at Z = -42
            GameObject playerGO = null;
            if (playerPrefab != null)
            {
                playerGO = (GameObject)PrefabUtility.InstantiatePrefab(playerPrefab);
                playerGO.name = "Alita_BattleAngel_Hero";
                playerGO.tag = "Player";
                playerGO.transform.position = new Vector3(0f, 0f, -42.0f);
                playerGO.transform.rotation = Quaternion.identity;

                if (ripplePrefab != null)
                {
                    var rippleSpawner = playerGO.GetComponent<FootstepWaterRippleSpawner>();
                    if (rippleSpawner == null) rippleSpawner = playerGO.AddComponent<FootstepWaterRippleSpawner>();
                    rippleSpawner.ripplePrefab = ripplePrefab;
                    rippleSpawner.groundHeight = 0.02f;
                }

                if (heroTrailMat != null)
                {
                    foreach (var tr in playerGO.GetComponentsInChildren<TrailRenderer>(true))
                    {
                        tr.sharedMaterial = heroTrailMat;
                    }
                }

                GameObject fillLightGO = new GameObject("Player_Blackwall_FrontFill");
                fillLightGO.transform.SetParent(playerGO.transform, false);
                fillLightGO.transform.localPosition = new Vector3(0f, 1.4f, -1.0f);
                var fillLight = fillLightGO.AddComponent<Light>();
                fillLight.type = LightType.Point;
                fillLight.color = new Color(0.85f, 0.4f, 0.5f, 1.0f);
                fillLight.intensity = 1.2f;
                fillLight.range = 4.5f;
                fillLight.shadows = LightShadows.None;
            }

            // 11. Main Camera & Smooth Orbit System
            GameObject camGO = new GameObject("Main Camera");
            camGO.tag = "MainCamera";
            camGO.transform.position = new Vector3(0f, 2.0f, -46.5f);
            camGO.transform.rotation = Quaternion.Euler(10f, 0f, 0f);

            var cam = camGO.AddComponent<Camera>();
            cam.clearFlags = CameraClearFlags.Skybox;
            cam.cullingMask = ~0;
            cam.fieldOfView = 60f;
            cam.nearClipPlane = 0.1f;
            cam.farClipPlane = 1000f;

            var camData = camGO.AddComponent<UniversalAdditionalCameraData>();
            camData.antialiasing = AntialiasingMode.None;
            camData.renderPostProcessing = true;

            camGO.AddComponent<AudioListener>();

            var orbitCam = camGO.AddComponent<SmoothOrbitCamera>();
            if (playerGO != null) orbitCam.target = playerGO.transform;
            orbitCam.targetOffset = new Vector3(0f, 1.45f, 0f);
            orbitCam.cameraOffset = new Vector3(0f, 0.40f, -5.2f);
            orbitCam.tightPositionFollow = true;
            orbitCam.minDistance = 2.2f;
            orbitCam.maxDistance = 9.5f;

            // 12. Build the Enclosed Datacenter Room with Server Banks, Middle Extrusion, and Blackwall at the end
            BuildEnclosedDatacenterRoom(envRoot, playerGO, ripplePrefab, heroTrailMat, enemyTrailMat);

            // 13. Holographic Rogue AI Enemy beyond the Blackwall (Z = 22)
            GameObject rogueAIGO = null;
            if (rogueAIPrefab != null)
            {
                rogueAIGO = (GameObject)PrefabUtility.InstantiatePrefab(rogueAIPrefab);
                rogueAIGO.name = "RogueAI_Holographic_Duelist";
                rogueAIGO.tag = "Enemy";
                rogueAIGO.transform.position = new Vector3(0f, 0f, 22.0f);
                rogueAIGO.transform.rotation = Quaternion.Euler(0f, 180f, 0f);

                var holoEmergence = rogueAIGO.GetComponent<HolographicBlackwallEmergence>();
                if (holoEmergence == null) holoEmergence = rogueAIGO.AddComponent<HolographicBlackwallEmergence>();
                holoEmergence.keepPermanentlyHolographic = true;
                holoEmergence.holographicShader = Shader.Find("Cyberpunk/Holographic_RogueAI");
                holoEmergence.holographicColor = new Color(1.0f, 0.08f, 0.35f, 1.0f);
                holoEmergence.rimGlowColor = new Color(3.5f, 0.15f, 1.2f, 1.0f);
                holoEmergence.coreTranslucency = 0.35f;
                holoEmergence.ApplyHolographicMaterials(initialDissolve: 1.0f);

                if (ripplePrefab != null)
                {
                    var rippleSpawner = rogueAIGO.GetComponent<FootstepWaterRippleSpawner>();
                    if (rippleSpawner == null) rippleSpawner = rogueAIGO.AddComponent<FootstepWaterRippleSpawner>();
                    rippleSpawner.ripplePrefab = ripplePrefab;
                    rippleSpawner.groundHeight = 0.02f;
                }

                if (enemyTrailMat != null)
                {
                    foreach (var tr in rogueAIGO.GetComponentsInChildren<TrailRenderer>(true))
                    {
                        tr.sharedMaterial = enemyTrailMat;
                    }
                }

                var enemyCtrl = rogueAIGO.GetComponent<InsaneGunSwordController>();
                if (enemyCtrl != null)
                {
                    enemyCtrl.maxHealth = 250f;
                    enemyCtrl.currentHealth = 250f;
                    enemyCtrl.autoReviveOnDeath = true;
                    enemyCtrl.autoReviveDelay = 2.5f;
                    enemyCtrl.controlMode = InsaneGunSwordController.ControlMode.AICirclingEnemy;
                    if (playerGO != null) enemyCtrl.targetEnemy = playerGO.transform;
                }

                var ragdoll = rogueAIGO.GetComponent<EuphoriaRagdollController>();
                if (ragdoll == null) ragdoll = rogueAIGO.AddComponent<EuphoriaRagdollController>();
                ragdoll.ragdollForceMultiplier = 1.6f;
                ragdoll.SetupRagdollBones();
            }

            // 14. Combat Test Manager & Blackwall Holographic Spawner
            GameObject managerGO = new GameObject("Combat_Test_Manager");
            var testManager = managerGO.AddComponent<InsaneGunCombatTestManager>();
            if (playerGO != null) testManager.player = playerGO.GetComponent<InsaneGunSwordController>();
            if (rogueAIGO != null) testManager.enemy = rogueAIGO.GetComponent<InsaneGunSwordController>();
            testManager.enemySpawnPos = new Vector3(0f, 0f, 10.0f);
            testManager.enemySpawnRot = Quaternion.Euler(0f, 180f, 0f);
            testManager.showHelpOverlay = true;

            var spawner = managerGO.AddComponent<BlackwallHolographicSpawner>();
            spawner.enemyPrefab = rogueAIPrefab;
            spawner.blackwallZ = BLACKWALL_Z;
            spawner.spawnWidthX = 22.0f;
            spawner.spawnY = 0.0f;
            spawner.spawnSingleKey = KeyCode.B;
            spawner.spawnSquadKey = KeyCode.N;
            spawner.clearEnemiesKey = KeyCode.V;
            spawner.showOnScreenGUI = true;

            // 15. Save Scene & Build Settings
            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene, SCENE_PATH);
            AddSceneToBuildSettings(SCENE_PATH);

            AssetDatabase.SaveAssets();
            AssetDatabase.Refresh();

            Debug.Log($"<color=#00FFAA><b>[Blackwall Scene Builder]</b></color> Successfully created and saved scene at <b>{SCENE_PATH}</b>!");
        }

        /// <summary>
        /// Builds the enclosed Datacenter Room structure (Walls, Ceiling, Cables, Pure Server Banks)
        /// with the Central Red Laser Extrusion in the middle, and terminating directly at the Blackwall!
        /// </summary>
        private static void BuildEnclosedDatacenterRoom(
            GameObject envRoot, 
            GameObject playerGO, 
            GameObject ripplePrefab,
            Material heroTrailMat, 
            Material enemyTrailMat)
        {
            GameObject roomRoot = new GameObject("[Datacenter_Server_Room]");
            roomRoot.transform.SetParent(envRoot.transform, false);

            var serverPrefab   = AssetDatabase.LoadAssetAtPath<GameObject>(SERVER_RACK_PATH);
            var consolePrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(CONSOLE_PATH);
            var gatePrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(CORP_GATE_PATH);
            var neon1Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_01_PATH);
            var neon2Prefab    = AssetDatabase.LoadAssetAtPath<GameObject>(NEON_SIGN_02_PATH);
            var holoSignPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(HOLO_SIGN_01_PATH);
            var girdersPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(GIRDERS_PATH);

            var enforcerPrefab  = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_ENFORCER_PATH);
            var ninjaPrefab     = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_NINJA_PATH);
            var protoMechPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(ENEMY_MECH_PATH);

            // Material for Room Enclosure Walls & Ceiling
            var wallMat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
            wallMat.name = "M_Datacenter_Room_Wall";
            wallMat.SetColor("_BaseColor", new Color(0.045f, 0.045f, 0.055f, 1f));
            wallMat.SetFloat("_Metallic", 0.85f);
            wallMat.SetFloat("_Smoothness", 0.45f);
            AssetDatabase.CreateAsset(wallMat, "Assets/SyntyCombined/Materials/M_Datacenter_Room_Wall.mat");

            float roomWidth = 12.0f; // from X = -6.0 to +6.0
            float roomHalfWidth = roomWidth * 0.5f;
            float roomHeight = 6.8f;
            float zStart = -46.0f;
            float zEnd = 15.5f;
            float roomLength = zEnd - zStart; // 61.5m
            float zCenter = (zStart + zEnd) * 0.5f;

            // ── 1. Room Shell (Left Wall, Right Wall, Back Wall, Ceiling) ──────────
            GameObject shellRoot = new GameObject("Room_Enclosure_Shell");
            shellRoot.transform.SetParent(roomRoot.transform, false);

            // Left Wall
            GameObject lWall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            lWall.name = "Datacenter_LeftWall";
            lWall.transform.SetParent(shellRoot.transform, false);
            lWall.transform.position = new Vector3(-roomHalfWidth, roomHeight * 0.5f, zCenter);
            lWall.transform.localScale = new Vector3(0.5f, roomHeight, roomLength);
            lWall.GetComponent<MeshRenderer>().sharedMaterial = wallMat;

            // Right Wall
            GameObject rWall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            rWall.name = "Datacenter_RightWall";
            rWall.transform.SetParent(shellRoot.transform, false);
            rWall.transform.position = new Vector3(roomHalfWidth, roomHeight * 0.5f, zCenter);
            rWall.transform.localScale = new Vector3(0.5f, roomHeight, roomLength);
            rWall.GetComponent<MeshRenderer>().sharedMaterial = wallMat;

            // Back Entrance Wall (behind player)
            GameObject bWall = GameObject.CreatePrimitive(PrimitiveType.Cube);
            bWall.name = "Datacenter_BackWall";
            bWall.transform.SetParent(shellRoot.transform, false);
            bWall.transform.position = new Vector3(0f, roomHeight * 0.5f, zStart);
            bWall.transform.localScale = new Vector3(roomWidth, roomHeight, 0.5f);
            bWall.GetComponent<MeshRenderer>().sharedMaterial = wallMat;

            // Ceiling
            GameObject ceiling = GameObject.CreatePrimitive(PrimitiveType.Cube);
            ceiling.name = "Datacenter_Ceiling";
            ceiling.transform.SetParent(shellRoot.transform, false);
            ceiling.transform.position = new Vector3(0f, roomHeight, zCenter);
            ceiling.transform.localScale = new Vector3(roomWidth + 0.5f, 0.4f, roomLength);
            ceiling.GetComponent<MeshRenderer>().sharedMaterial = wallMat;

            // ── 2. Structural Ceiling Girders & Overhead Trusses ───────────────────
            if (girdersPrefab != null)
            {
                float[] zGirders = new float[] { -40f, -28f, -16f, -4f, 8f };
                foreach (float zg in zGirders)
                {
                    GameObject gantry = (GameObject)PrefabUtility.InstantiatePrefab(girdersPrefab);
                    gantry.name = $"Overhead_Truss_Z{zg:F0}";
                    gantry.transform.SetParent(shellRoot.transform, false);
                    gantry.transform.position = new Vector3(0f, roomHeight - 1.2f, zg);
                    gantry.transform.rotation = Quaternion.Euler(0f, 90f, 0f);
                    gantry.transform.localScale = new Vector3(1.35f, 0.9f, 1.4f);
                }
            }

            // ── 3. Pure Server Banks Lining Left and Right Walls ──────────────────
            // Stacked 2-high (Y=0 and Y=2.28) lining both walls all the way down the room!
            if (serverPrefab != null)
            {
                for (float z = zStart + 2f; z <= zEnd - 2.5f; z += 1.15f)
                {
                    // Gap around central core
                    if (z >= -20.5f && z <= -15.5f) continue;

                    for (int tier = 0; tier < 2; tier++)
                    {
                        float yPos = tier * 2.28f;

                        // Left Wall Server Rack (facing X+)
                        GameObject lServer = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                        lServer.name = $"Server_L_Z{z:F0}_T{tier}";
                        lServer.transform.SetParent(roomRoot.transform, false);
                        lServer.transform.position = new Vector3(-roomHalfWidth + 1.1f, yPos, z);
                        lServer.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

                        // Right Wall Server Rack (facing X-)
                        GameObject rServer = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                        rServer.name = $"Server_R_Z{z:F0}_T{tier}";
                        rServer.transform.SetParent(roomRoot.transform, false);
                        rServer.transform.position = new Vector3(roomHalfWidth - 1.1f, yPos, z);
                        rServer.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
                    }
                }
            }

            // Consoles placed along the server walls
            if (consolePrefab != null)
            {
                GameObject con1 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
                con1.transform.SetParent(roomRoot.transform, false);
                con1.transform.position = new Vector3(-roomHalfWidth + 1.5f, 0f, -34f);
                con1.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

                GameObject con2 = (GameObject)PrefabUtility.InstantiatePrefab(consolePrefab);
                con2.transform.SetParent(roomRoot.transform, false);
                con2.transform.position = new Vector3(roomHalfWidth - 1.5f, 0f, -6f);
                con2.transform.rotation = Quaternion.Euler(0f, -90f, 0f);
            }

            // Red Ambient Strip Point Lights along the server aisle
            float[] zAisleLights = new float[] { -38f, -28f, -18f, -8f, 2f, 10f };
            foreach (float zl in zAisleLights)
            {
                GameObject lLightGO = new GameObject($"Aisle_Light_L_{zl:F0}");
                lLightGO.transform.SetParent(roomRoot.transform, false);
                lLightGO.transform.position = new Vector3(-3.2f, 2.6f, zl);
                var lLight = lLightGO.AddComponent<Light>();
                lLight.type = LightType.Point;
                lLight.color = new Color(1.0f, 0.05f, 0.12f, 1f);
                lLight.intensity = 4.2f;
                lLight.range = 8.5f;
                lLight.shadows = LightShadows.None;

                GameObject rLightGO = new GameObject($"Aisle_Light_R_{zl:F0}");
                rLightGO.transform.SetParent(roomRoot.transform, false);
                rLightGO.transform.position = new Vector3(3.2f, 2.6f, zl);
                var rLight = rLightGO.AddComponent<Light>();
                rLight.type = LightType.Point;
                rLight.color = new Color(1.0f, 0.05f, 0.12f, 1f);
                rLight.intensity = 4.2f;
                rLight.range = 8.5f;
                rLight.shadows = LightShadows.None;
            }

            // ── 4. The Extruded Central Server Monolith Core in the Middle of Room (Z = -18) ──
            float coreZ = -18.0f;
            GameObject coreRoot = new GameObject("Central_Server_Extrusion_Core");
            coreRoot.transform.SetParent(roomRoot.transform, false);
            coreRoot.transform.position = new Vector3(0f, 0f, coreZ);

            if (serverPrefab != null)
            {
                for (int ty = 0; ty < 2; ty++)
                {
                    float yOffset = ty * 2.28f;
                    // Left flank server
                    GameObject sL = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                    sL.transform.SetParent(coreRoot.transform, false);
                    sL.transform.position = new Vector3(-0.95f, yOffset, coreZ);
                    sL.transform.rotation = Quaternion.Euler(0f, 90f, 0f);

                    // Right flank server
                    GameObject sR = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                    sR.transform.SetParent(coreRoot.transform, false);
                    sR.transform.position = new Vector3(0.95f, yOffset, coreZ);
                    sR.transform.rotation = Quaternion.Euler(0f, -90f, 0f);

                    // Back enclosing server
                    GameObject sB = (GameObject)PrefabUtility.InstantiatePrefab(serverPrefab);
                    sB.transform.SetParent(coreRoot.transform, false);
                    sB.transform.position = new Vector3(0f, yOffset, coreZ + 0.65f);
                    sB.transform.rotation = Quaternion.Euler(0f, 180f, 0f);
                }
            }

            // The Radiant Crimson Laser/Plasma Core Aperture
            GameObject beamGO = GameObject.CreatePrimitive(PrimitiveType.Cube);
            beamGO.name = "Radiant_Crimson_Laser_Core";
            beamGO.transform.SetParent(coreRoot.transform, false);
            beamGO.transform.position = new Vector3(0f, 3.2f, coreZ);
            beamGO.transform.localScale = new Vector3(0.42f, 6.2f, 0.55f);

            var beamCol = beamGO.GetComponent<Collider>();
            if (beamCol != null) Object.DestroyImmediate(beamCol);

            var beamRenderer = beamGO.GetComponent<MeshRenderer>();
            var beamMat = new Material(Shader.Find("Universal Render Pipeline/Unlit"));
            beamMat.name = "M_Datacenter_CentralCore_Beam";
            beamMat.SetColor("_BaseColor", new Color(20.0f, 0.15f, 0.28f, 1.0f));
            beamRenderer.sharedMaterial = beamMat;
            beamRenderer.shadowCastingMode = ShadowCastingMode.Off;
            AssetDatabase.CreateAsset(beamMat, "Assets/SyntyCombined/Materials/M_Datacenter_CentralCore_Beam.mat");

            // Stacked vertical point lights inside the aperture
            List<Light> stackedLights = new List<Light>();
            float[] lightHeights = new float[] { 1.2f, 3.2f, 5.2f };
            foreach (float lh in lightHeights)
            {
                GameObject cLightGO = new GameObject($"Core_Light_Y{lh}");
                cLightGO.transform.SetParent(coreRoot.transform, false);
                cLightGO.transform.position = new Vector3(0f, lh, coreZ - 0.2f);

                var cl = cLightGO.AddComponent<Light>();
                cl.type = LightType.Point;
                cl.color = new Color(1.0f, 0.04f, 0.12f, 1.0f);
                cl.intensity = 8.5f;
                cl.range = 14.0f;
                cl.shadows = LightShadows.None;
                stackedLights.Add(cl);
            }

            var pulsator = coreRoot.AddComponent<DatacenterRedCorePulsator>();
            pulsator.coreLights = stackedLights.ToArray();
            pulsator.coreRenderer = beamRenderer;
            pulsator.baseLightIntensity = 6.0f;
            pulsator.pulseLightIntensity = 11.5f;
            pulsator.baseEmissionColor = new Color(10.0f, 0.08f, 0.15f, 1f);
            pulsator.peakEmissionColor = new Color(25.0f, 0.2f, 0.35f, 1f);
            pulsator.pulseSpeed = 2.2f;

            // ── 5. Overhead Warning Signs ─────────────────────────────────────────
            if (neon1Prefab != null)
            {
                GameObject s1 = (GameObject)PrefabUtility.InstantiatePrefab(neon1Prefab);
                s1.name = "Neon_Alert_Entrance";
                s1.transform.SetParent(roomRoot.transform, false);
                s1.transform.position = new Vector3(0f, 4.8f, -38f);
                s1.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
            }

            if (neon2Prefab != null)
            {
                GameObject s2 = (GameObject)PrefabUtility.InstantiatePrefab(neon2Prefab);
                s2.name = "Neon_Alert_Core";
                s2.transform.SetParent(roomRoot.transform, false);
                s2.transform.position = new Vector3(0f, 5.5f, coreZ);
                s2.transform.localScale = new Vector3(1.2f, 1.2f, 1.2f);
            }

            if (holoSignPrefab != null)
            {
                GameObject hs = (GameObject)PrefabUtility.InstantiatePrefab(holoSignPrefab);
                hs.name = "Holo_HighVoltage_Blackwall_Gate";
                hs.transform.SetParent(roomRoot.transform, false);
                hs.transform.position = new Vector3(0f, 4.8f, 14.0f);
                hs.transform.localScale = new Vector3(1.1f, 1.1f, 1.1f);
            }

            // ── 6. Portal Archway framing the Blackwall at the end of the room ────
            if (gatePrefab != null)
            {
                GameObject gateGO = (GameObject)PrefabUtility.InstantiatePrefab(gatePrefab);
                gateGO.name = "Blackwall_Portal_Frame_Arch";
                gateGO.transform.SetParent(roomRoot.transform, false);
                gateGO.transform.position = new Vector3(0f, 0f, zEnd);
                gateGO.transform.rotation = Quaternion.identity;
                gateGO.transform.localScale = new Vector3(1.2f, 1.2f, 1.2f);
            }

            // ── 7. Combat Enemies with Insane Gun / Sword Combo inside the Room ──
            // Enforcers stationed in the first half of the room
            if (enforcerPrefab != null)
            {
                SpawnDatacenterEnemy(roomRoot, enforcerPrefab, "Datacenter_Enforcer_Alpha", 
                    new Vector3(-2.2f, 0f, -30f), Quaternion.Euler(0f, 150f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);

                SpawnDatacenterEnemy(roomRoot, enforcerPrefab, "Datacenter_Enforcer_Beta", 
                    new Vector3(2.2f, 0f, -30f), Quaternion.Euler(0f, 210f, 0f), 220f, playerGO, ripplePrefab, enemyTrailMat);
            }

            // Ninjas stationed past the central core
            if (ninjaPrefab != null)
            {
                SpawnDatacenterEnemy(roomRoot, ninjaPrefab, "Cyber_Ninja_Specter", 
                    new Vector3(-2.0f, 0f, -10f), Quaternion.Euler(0f, 160f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);

                SpawnDatacenterEnemy(roomRoot, ninjaPrefab, "Cyber_Ninja_Shadow", 
                    new Vector3(2.0f, 0f, -10f), Quaternion.Euler(0f, 200f, 0f), 185f, playerGO, ripplePrefab, enemyTrailMat);
            }

            // Heavy ProtoMech guarding right before the Blackwall threshold
            if (protoMechPrefab != null)
            {
                SpawnDatacenterEnemy(roomRoot, protoMechPrefab, "Gatekeeper_ProtoMech", 
                    new Vector3(0f, 0f, 6.0f), Quaternion.Euler(0f, 180f, 0f), 340f, playerGO, ripplePrefab, enemyTrailMat);
            }
        }

        /// <summary>
        /// Instantiates and configures a combat enemy with InsaneGunSwordController,
        /// weapon trail materials, footstep ripples, ragdoll physics, and AI targeting.
        /// </summary>
        private static void SpawnDatacenterEnemy(
            GameObject parent,
            GameObject prefab,
            string enemyName,
            Vector3 position,
            Quaternion rotation,
            float maxHealth,
            GameObject playerGO,
            GameObject ripplePrefab,
            Material trailMat)
        {
            GameObject enemyGO = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            enemyGO.name = enemyName;
            enemyGO.tag = "Enemy";
            enemyGO.transform.SetParent(parent.transform, false);
            enemyGO.transform.position = position;
            enemyGO.transform.rotation = rotation;

            var ctrl = enemyGO.GetComponent<InsaneGunSwordController>();
            if (ctrl != null)
            {
                ctrl.controlMode = InsaneGunSwordController.ControlMode.AICirclingEnemy;
                ctrl.maxHealth = maxHealth;
                ctrl.currentHealth = maxHealth;
                ctrl.autoReviveOnDeath = true;
                ctrl.autoReviveDelay = 4.0f;
                if (playerGO != null) ctrl.targetEnemy = playerGO.transform;
            }

            if (trailMat != null)
            {
                foreach (var tr in enemyGO.GetComponentsInChildren<TrailRenderer>(true))
                {
                    tr.sharedMaterial = trailMat;
                }
            }

            if (ripplePrefab != null)
            {
                var rippleSpawner = enemyGO.GetComponent<FootstepWaterRippleSpawner>();
                if (rippleSpawner == null) rippleSpawner = enemyGO.AddComponent<FootstepWaterRippleSpawner>();
                rippleSpawner.ripplePrefab = ripplePrefab;
                rippleSpawner.groundHeight = 0.02f;
            }

            var ragdoll = enemyGO.GetComponent<EuphoriaRagdollController>();
            if (ragdoll == null) ragdoll = enemyGO.AddComponent<EuphoriaRagdollController>();
            ragdoll.ragdollForceMultiplier = 1.6f;
            ragdoll.SetupRagdollBones();
        }

        private static void AddSceneToBuildSettings(string scenePath)
        {
            var scenes = new List<EditorBuildSettingsScene>(EditorBuildSettings.scenes);
            for (int i = 0; i < scenes.Count; i++)
            {
                if (scenes[i].path == scenePath)
                {
                    scenes[i].enabled = true;
                    EditorBuildSettings.scenes = scenes.ToArray();
                    return;
                }
            }

            scenes.Add(new EditorBuildSettingsScene(scenePath, true));
            EditorBuildSettings.scenes = scenes.ToArray();
        }
    }
}

