// ── The Freestanding Door in the Middle of Nowhere (Z = zStart) ──────────
// Stands isolated on the reflective salt-lake void in the middle of nowhere,
// blending into the dark mist, with subtle crimson cybernetic scanlines.
var doorDoublePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PolygonCyberCity/Prefabs/Buildings/SM_Bld_Door_Double_01.prefab");
var portalThinPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonParticles/Prefabs/FX_Portal_Thin_01.prefab");

if (doorDoublePrefab != null)
{
    GameObject doorGO = (GameObject)PrefabUtility.InstantiatePrefab(doorDoublePrefab);
    doorGO.name = "Freestanding_Door_In_Middle_Of_Nowhere";
    doorGO.transform.SetParent(envRoot.transform, false);
    doorGO.transform.position = new Vector3(0f, 0f, zStart);
    doorGO.transform.rotation = Quaternion.identity;
    doorGO.transform.localScale = new Vector3(1.15f, 1.15f, 1.15f);

    // Add subtle red indicator glow
    GameObject dLightGO = new GameObject("NowhereDoor_IndicatorLight");
    dLightGO.transform.SetParent(doorGO.transform, false);
    dLightGO.transform.localPosition = new Vector3(0f, 2.3f, -0.3f);
    var dLight = dLightGO.AddComponent<Light>();
    dLight.type = LightType.Point;
    dLight.color = new Color(1.0f, 0.08f, 0.15f, 1.0f);
    dLight.intensity = 3.0f;
    dLight.range = 5.5f;

    // Add Portal Reality Glitch FX inside the frame
    if (portalThinPrefab != null)
    {
        GameObject pfx = (GameObject)PrefabUtility.InstantiatePrefab(portalThinPrefab);
        pfx.name = "Doorway_RealityGlitch_FX";
        pfx.transform.SetParent(doorGO.transform, false);
        pfx.transform.localPosition = new Vector3(0f, 1.15f, 0f);
        pfx.transform.localScale = new Vector3(0.55f, 0.55f, 0.55f);
    }

    // Add NowhereDoorPortal controller (automatic pneumatic slide open on approach)
    var portalScript = doorGO.AddComponent<NowhereDoorPortal>();
    portalScript.serverRoomRoot = roomRoot;
    portalScript.leftDoorPanel = doorGO.transform.Find("SM_Bld_Door_Double_01_Door_01");
    portalScript.rightDoorPanel = doorGO.transform.Find("SM_Bld_Door_Double_01_Door_02");
    portalScript.doorIndicatorLight = dLight;
    portalScript.triggerDistance = 5.0f;
    portalScript.openSlideDistance = 0.85f;
}

