using System.Reflection;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var door = GameObject.Find("Freestanding_Door_In_Middle_Of_Nowhere");
        var portal = door.GetComponent<NowhereDoorPortal>();
        var playerField = typeof(NowhereDoorPortal).GetField("_playerTransform", BindingFlags.NonPublic | BindingFlags.Instance);
        var isInsideField = typeof(NowhereDoorPortal).GetField("_isInside", BindingFlags.NonPublic | BindingFlags.Instance);
        var isOpenField = typeof(NowhereDoorPortal).GetField("_isOpen", BindingFlags.NonPublic | BindingFlags.Instance);

        var pt = playerField.GetValue(portal) as Transform;
        var inside = (bool)isInsideField.GetValue(portal);
        var open = (bool)isOpenField.GetValue(portal);

        result.Log($"_playerTransform: {(pt != null ? pt.name + " at " + pt.position.ToString() : "null")}, _isInside: {inside}, _isOpen: {open}");
    }
}

