        var bTop = GameObject.Find("Datacenter_BackWall_Header");
        var lWall = GameObject.Find("Datacenter_LeftWall");
        var rWall = GameObject.Find("Datacenter_RightWall");
        var ceiling = GameObject.Find("Datacenter_Ceiling");

        if (bL != null) Object.DestroyImmediate(bL);
        if (bR != null) Object.DestroyImmediate(bR);
        if (bTop != null) Object.DestroyImmediate(bTop);

        // Also let's check left and right walls: where do they start?
        // If left and right walls start at Z = -95, from the outside they stick out!
        // The side walls and ceiling should only start a few meters inside, or be part of the interior room!
        var room = GameObject.Find("[Datacenter_Server_Room]");
        if (room != null) room.SetActive(false);

        var sceneView = SceneView.lastActiveSceneView;
        if (sceneView != null)
