using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // 1. Turn off Fog
        RenderSettings.fog = false;

        // 2. Adjust Lighting to Harsh Lunar Sun & Deep Space Ambient
        RenderSettings.ambientMode = AmbientMode.Flat;
        RenderSettings.ambientLight = new Color(0.04f, 0.05f, 0.07f, 1.0f); // very dark lunar shadows

        var dirLights = Object.FindObjectsByType<Light>(FindObjectsSortMode.None);
        foreach (var l in dirLights)
        {
            if (l.type == LightType.Directional)
            {
                l.color = new Color(1.0f, 0.98f, 0.95f, 1.0f); // harsh white sun
                l.intensity = 2.4f;
                l.shadows = LightShadows.Hard;
                l.shadowStrength = 0.95f;
            }
        }

        // 3. Find and hide alien plants / corals under Environment
        int hiddenPlants = 0;
        var envObj = GameObject.Find("Environment");
        if (envObj != null)
        {
            foreach (Transform t in envObj.GetComponentsInChildren<Transform>(true))
            {
                string n = t.gameObject.name.ToLower();
                if (n.Contains("plant") || n.Contains("coral") || n.Contains("flower") || n.Contains("cactus") || n.Contains("tree") || n.Contains("spikes") || n.Contains("kelp") || n.Contains("bulb"))
                {
                    t.gameObject.SetActive(false);
                    hiddenPlants++;
                }
            }
        }
        result.Log($"Hidden {hiddenPlants} alien flora objects.");

        // 4. Update Triplanar Materials to Lunar Grey
        var matExp = AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonSciFiWorlds/Materials/Environment/PolygonSciFiWorlds_Env_Triplanar_Exp_01.mat");
        if (matExp != null)
        {
            matExp.SetColor("_Ground_Color", new Color(0.22f, 0.22f, 0.24f, 1.0f));
            matExp.SetColor("_Rock_Color", new Color(0.32f, 0.32f, 0.35f, 1.0f));
            matExp.SetColor("_Road_Color", new Color(0.15f, 0.15f, 0.17f, 1.0f));
        }

        var matGrass = AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonSciFiWorlds/Materials/Environment/PolygonSciFiWorlds_Env_Triplanar_Grass_01.mat");
        if (matGrass != null)
        {
            matGrass.SetColor("_Ground_Color", new Color(0.20f, 0.20f, 0.22f, 1.0f));
            matGrass.SetColor("_Rock_Color", new Color(0.30f, 0.30f, 0.33f, 1.0f));
            matGrass.SetColor("_Road_Color", new Color(0.14f, 0.14f, 0.16f, 1.0f));
        }

        // 5. SkyDome: hide orange atmosphere dome
        var skydome = GameObject.Find("SkyDome");
        if (skydome != null)
        {
            foreach (Transform t in skydome.GetComponentsInChildren<Transform>(true))
            {
                if (t.name == "SM_FX_Skydome_01")
                {
                    // This is the orange atmosphere mesh
                    t.gameObject.SetActive(false);
                }
            }
        }

        // 6. Camera skybox to solid black or space
        var mainCam = Camera.main;
        if (mainCam != null)
        {
            mainCam.clearFlags = CameraClearFlags.SolidColor;
            mainCam.backgroundColor = new Color(0.01f, 0.01f, 0.02f, 1f);
        }

        // 7. Adjust Global Volume to high contrast cinematic
        var vol = Object.FindFirstObjectByType<Volume>();
        if (vol != null && vol.profile != null)
        {
            if (vol.profile.TryGet<ColorAdjustments>(out var ca))
            {
                ca.contrast.value = 35f;
                ca.saturation.value = -15f; // stark desaturated moon look
            }
            if (vol.profile.TryGet<Bloom>(out var bloom))
            {
                bloom.threshold.value = 1.1f;
                bloom.intensity.value = 1.8f;
            }
        }

        result.Log("Transformed environment into Lunar Moon Surface!");
    }
}

