using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using System.Collections.Generic;

namespace InsaneGun.Editor
{
    public static class MoonBattleFlashbackSceneBuilder
    {
        [MenuItem("Cyberpunk/Build Moon Battle Flashback Scene")]
        public static void BuildMoonBattleScene()
        {
            Debug.Log("[MoonBattle] Assembling Moon Battle Flashback Scene...");

            // ── 1. Configure Lunar Atmosphere & Lighting ─────────────────────────────
            ConfigureLunarAtmosphere();

            // ── 2. Configure Earth in the Lunar Sky ──────────────────────────────────
            SetupEarthInSky();

            // ── 3. Clean Alien Flora (Keep Desolate Lunar Surface) ───────────────────
            CleanAlienFlora();

            // ── 4. Spawn Alita and Spacesuit Crew with Guns ──────────────────────────
            Transform battleRoot = GetOrCreateRoot("[Moon_Combat_Encounter]");

            Vector3 squadOrigin = new Vector3(88f, 1.2f, 72f); // Clear lunar plateau near rovers
            SetupAlitaAndCrew(battleRoot, squadOrigin);

            // ── 5. Spawn Enemy Spacesuit Squad ───────────────────────────────────────
            SetupEnemySquad(battleRoot, squadOrigin + new Vector3(0f, 0f, 26f));

            // ── 6. Spawn Gun Combat VFX (Tracers, Muzzle Flashes) ─────────────────────
            SetupCombatVFX(battleRoot, squadOrigin);

            // ── 7. Setup 4 Cinematic Cameras for Multi-Angle Renders ────────────────
            SetupCinematicCameras(squadOrigin);

            AssetDatabase.SaveAssets();
            Debug.Log("[MoonBattle] Successfully assembled Moon Battle Flashback Scene!");
        }

        private static Transform GetOrCreateRoot(string name)
        {
            var go = GameObject.Find(name);
            if (go != null)
            {
                Object.DestroyImmediate(go);
            }
            go = new GameObject(name);
            go.transform.position = Vector3.zero;
            return go.transform;
        }

        private static void ConfigureLunarAtmosphere()
        {
            RenderSettings.fog = false;
            RenderSettings.ambientMode = AmbientMode.Flat;
            RenderSettings.ambientLight = new Color(0.04f, 0.05f, 0.07f, 1.0f);

            // Lunar Grey Terrain Materials
            var matExp = AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonSciFiWorlds/Materials/Environment/PolygonSciFiWorlds_Env_Triplanar_Exp_01.mat");
            if (matExp != null)
            {
                matExp.SetColor("_Ground_Color", new Color(0.22f, 0.22f, 0.24f, 1.0f));
                matExp.SetColor("_Rock_Color", new Color(0.32f, 0.32f, 0.35f, 1.0f));
                matExp.SetColor("_Road_Color", new Color(0.15f, 0.15f, 0.17f, 1.0f));
            }

            var matGrass = AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonSciFiWorlds/Materials/Environment/PolygonSciFiWorlds_Env_Triplanar_Grass_01.mat");
            if (matGrass != null)
            {
                matGrass.SetColor("_Ground_Color", new Color(0.20f, 0.20f, 0.22f, 1.0f));
                matGrass.SetColor("_Rock_Color", new Color(0.30f, 0.30f, 0.33f, 1.0f));
                matGrass.SetColor("_Road_Color", new Color(0.14f, 0.14f, 0.16f, 1.0f));
            }

            // Directional Light: Stark Lunar Sun
            var lightsRoot = GameObject.Find("Lights - Enable One");
            if (lightsRoot != null)
            {
                var urpObj = lightsRoot.transform.Find("URP");
                if (urpObj != null)
                {
                    urpObj.gameObject.SetActive(true);
                    var dirLightGO = urpObj.Find("Directional Light");
                    if (dirLightGO != null)
                    {
                        var dirLight = dirLightGO.GetComponent<Light>();
                        if (dirLight != null)
                        {
                            dirLight.enabled = true;
                            dirLight.color = new Color(1.0f, 0.98f, 0.95f, 1.0f);
                            dirLight.intensity = 2.8f;
                            dirLight.shadows = LightShadows.Hard;
                            dirLight.shadowStrength = 0.96f;
                            dirLight.transform.rotation = Quaternion.Euler(42f, -35f, 0f);
                        }
                    }
                }
            }

            // Hide atmosphere dome
            var skydome = GameObject.Find("SkyDome");
            if (skydome != null)
            {
                var domeMesh = skydome.transform.Find("SM_FX_Skydome_01");
                if (domeMesh != null) domeMesh.gameObject.SetActive(false);
            }

            // Global Volume: High-contrast cinematic bloom
            var vol = Object.FindFirstObjectByType<Volume>();
            if (vol != null && vol.profile != null)
            {
                if (vol.profile.TryGet<ColorAdjustments>(out var ca))
                {
                    ca.contrast.value = 38f;
                    ca.saturation.value = -12f;
                }
                if (vol.profile.TryGet<Bloom>(out var bloom))
                {
                    bloom.threshold.value = 1.05f;
                    bloom.intensity.value = 2.2f;
                }
            }
        }

        private static void SetupEarthInSky()
        {
            var earthObj = GameObject.Find("Earth_In_Lunar_Sky");
            if (earthObj != null) Object.DestroyImmediate(earthObj);

            earthObj = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            earthObj.name = "Earth_In_Lunar_Sky";
            earthObj.transform.position = new Vector3(88f, 180f, 420f);
            earthObj.transform.localScale = new Vector3(85f, 85f, 85f);

            var earthMat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
            earthMat.name = "M_Earth_In_Sky";
            earthMat.color = new Color(0.12f, 0.35f, 0.85f, 1.0f); // Vibrant ocean blue
            earthMat.SetColor("_EmissionColor", new Color(0.15f, 0.45f, 0.95f) * 1.8f);
            earthMat.EnableKeyword("_EMISSION");
            earthMat.SetFloat("_Smoothness", 0.7f);

            earthObj.GetComponent<MeshRenderer>().sharedMaterial = earthMat;
            Object.DestroyImmediate(earthObj.GetComponent<Collider>());
        }

        private static void CleanAlienFlora()
        {
            var envObj = GameObject.Find("Environment");
            if (envObj != null)
            {
                foreach (Transform t in envObj.GetComponentsInChildren<Transform>(true))
                {
                    string n = t.gameObject.name.ToLower();
                    if (n.Contains("plant") || n.Contains("coral") || n.Contains("flower") || n.Contains("cactus") || 
                        n.Contains("tree") || n.Contains("spikes") || n.Contains("kelp") || n.Contains("bulb") || n.Contains("pinecone"))
                    {
                        t.gameObject.SetActive(false);
                    }
                }
            }
        }

        private static void SetupAlitaAndCrew(Transform parent, Vector3 center)
        {
            Transform heroSquad = new GameObject("Hero_Squad_Alita_And_Crew").transform;
            heroSquad.SetParent(parent, false);

            // 1. Alita (Center Point Commander)
            var alitaPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Alita_Sidekick/Alita_03_Final_NanoBerserker.prefab");
            if (alitaPrefab != null)
            {
                var alita = (GameObject)PrefabUtility.InstantiatePrefab(alitaPrefab);
                alita.name = "Alita_Combat_Hero";
                alita.transform.SetParent(heroSquad, false);
                alita.transform.position = center + new Vector3(0f, 0f, 0f);
                alita.transform.rotation = Quaternion.Euler(0f, 15f, 0f);

                AttachWeapon(alita, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Assault_01.prefab", true);
            }

            // 2. Spacesuit Crew Member 1: Heavy Gunner (Left Flank)
            var suitMale1 = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonSciFiWorlds/Prefabs/Characters/SM_Chr_ScifiWorlds_SpaceSuit_Male_01.prefab");
            if (suitMale1 != null)
            {
                var kagel = (GameObject)PrefabUtility.InstantiatePrefab(suitMale1);
                kagel.name = "Crew_Kagel_HeavyGunner";
                kagel.transform.SetParent(heroSquad, false);
                kagel.transform.position = center + new Vector3(-3.2f, 0f, -1.5f);
                kagel.transform.rotation = Quaternion.Euler(0f, 25f, 0f);

                AttachWeapon(kagel, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Heavy_01.prefab", false);
            }

            // 3. Spacesuit Crew Member 2: Marksman / Sniper (Right Ridge)
            var suitFemale1 = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonSciFiWorlds/Prefabs/Characters/SM_Chr_ScifiWorlds_SpaceSuit_Female_01.prefab");
            if (suitFemale1 != null)
            {
                var raye = (GameObject)PrefabUtility.InstantiatePrefab(suitFemale1);
                raye.name = "Crew_Raye_Sniper";
                raye.transform.SetParent(heroSquad, false);
                raye.transform.position = center + new Vector3(3.4f, 0.4f, -1.0f);
                raye.transform.rotation = Quaternion.Euler(0f, 5f, 0f);

                AttachWeapon(raye, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Sniper_01.prefab", false);
            }

            // 4. Spacesuit Crew Member 3: Vanguard Breacher (Support Center)
            var suitMale2 = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonSciFiWorlds/Prefabs/Characters/SM_Chr_ScifiWorlds_SpaceSuit_Male_02.prefab");
            if (suitMale2 != null)
            {
                var vance = (GameObject)PrefabUtility.InstantiatePrefab(suitMale2);
                vance.name = "Crew_Vance_Vanguard";
                vance.transform.SetParent(heroSquad, false);
                vance.transform.position = center + new Vector3(-1.4f, 0f, -3.2f);
                vance.transform.rotation = Quaternion.Euler(0f, 18f, 0f);

                AttachWeapon(vance, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Assault_02.prefab", false);
            }
        }

        private static void SetupEnemySquad(Transform parent, Vector3 enemyCenter)
        {
            Transform enemySquad = new GameObject("Hostile_Enemy_Squad").transform;
            enemySquad.SetParent(parent, false);

            var soldierPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonSciFiWorlds/Prefabs/Characters/SM_Chr_ScifiWorlds_Soldier_Male_01.prefab");
            var alienSoldierPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonSciFiWorlds/Prefabs/Characters/SM_Chr_ScifiWorlds_Soldier_Male_02.prefab");

            // Enemy 1: Rifleman behind barrier
            if (soldierPrefab != null)
