                e1.name = "Enemy_Rifleman_Alpha";
                e1.transform.SetParent(enemySquad, false);
                e1.transform.position = enemyCenter + new Vector3(-4.5f, 0.2f, 0f);
                e1.transform.rotation = Quaternion.Euler(0f, 195f, 0f);
                AttachWeapon(e1, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Assault_01.prefab", false);
            }

            // Enemy 2: Heavy Enforcer
            if (alienSoldierPrefab != null)
            {
                var e2 = (GameObject)PrefabUtility.InstantiatePrefab(alienSoldierPrefab);
                e2.name = "Enemy_Heavy_Enforcer";
                e2.transform.SetParent(enemySquad, false);
                e2.transform.position = enemyCenter + new Vector3(0.5f, 0.5f, 3.5f);
                e2.transform.rotation = Quaternion.Euler(0f, 180f, 0f);
                AttachWeapon(e2, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_Heavy_02.prefab", false);
