                e3.transform.SetParent(enemySquad, false);
                e3.transform.position = enemyCenter + new Vector3(5.0f, 0f, -1.0f);
                e3.transform.rotation = Quaternion.Euler(0f, 165f, 0f);
                AttachWeapon(e3, "Assets/Synty/PolygonSciFiWorlds/Prefabs/Weapons/SM_Wep_SMG_01.prefab", false);
            }
