        private static void AttachWeapon(GameObject character, string weaponPrefabPath, bool isHero)
        {
            var weaponPrefab = AssetDatabase.LoadAssetAtPath<GameObject>(weaponPrefabPath);
            if (weaponPrefab == null) return;

            // Find right hand bone
            Transform rightHand = FindBone(character.transform, "hand_r", "hand.r", "r_hand", "hand_r", "weapon_r", "right_hand");
            if (rightHand == null)
            {
                rightHand = character.transform;
            }

            var weapon = (GameObject)PrefabUtility.InstantiatePrefab(weaponPrefab);
            weapon.name = "Equipped_Gun";
            weapon.transform.SetParent(rightHand, false);
            weapon.transform.localPosition = new Vector3(0.08f, 0.05f, 0.05f);
            weapon.transform.localRotation = Quaternion.Euler(-10f, 90f, 0f);
            weapon.transform.localScale = Vector3.one * 1.1f;
        }

        private static Transform FindBone(Transform current, params string[] boneNames)
        {
            string lowerName = current.name.ToLower();
            foreach (var b in boneNames)
            {
                if (lowerName.Contains(b)) return current;
            }

            for (int i = 0; i < current.childCount; i++)
            {
                var found = FindBone(current.GetChild(i), boneNames);
                if (found != null) return found;
            }
            return null;
        }

        private static void SetupCombatVFX(Transform parent, Vector3 center)
        {
            Transform vfxRoot = new GameObject("Combat_Battle_VFX").transform;
            vfxRoot.SetParent(parent, false);

            var tracerPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonParticles/Prefabs/FX_Gunshot_Heavy_Repeating_Tracers_01.prefab");
            var gunshotPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonParticles/Prefabs/FX_Gunshot_01.prefab");
            var sniperLinePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Synty/PolygonParticles/Prefabs/FX_Gunshot_Sniper_Line_01.prefab");

            // 1. Alita Muzzle Flash
            if (gunshotPrefab != null)
            {
                var mf = (GameObject)PrefabUtility.InstantiatePrefab(gunshotPrefab);
                mf.name = "VFX_Alita_MuzzleFlash";
                mf.transform.SetParent(vfxRoot, false);
                mf.transform.position = center + new Vector3(0.3f, 1.3f, 1.2f);
                mf.transform.rotation = Quaternion.Euler(0f, 15f, 0f);
            }

            // 2. Tracers crossing the battlefield towards enemies
            if (tracerPrefab != null)
            {
                var tracer = (GameObject)PrefabUtility.InstantiatePrefab(tracerPrefab);
                tracer.name = "VFX_Hero_Tracers";
                tracer.transform.SetParent(vfxRoot, false);
                tracer.transform.position = center + new Vector3(0f, 1.4f, 2.0f);
                tracer.transform.rotation = Quaternion.Euler(-2f, 15f, 0f);
            }

            // 3. Sniper laser beam
            if (sniperLinePrefab != null)
            {
                var sniper = (GameObject)PrefabUtility.InstantiatePrefab(sniperLinePrefab);
                sniper.name = "VFX_Sniper_Laser";
                sniper.transform.SetParent(vfxRoot, false);
                sniper.transform.position = center + new Vector3(3.4f, 1.6f, 0f);
                sniper.transform.rotation = Quaternion.Euler(-1f, 5f, 0f);
            }

            // 4. Enemy return fire tracers
            if (tracerPrefab != null)
            {
                var enemyTracer = (GameObject)PrefabUtility.InstantiatePrefab(tracerPrefab);
                enemyTracer.name = "VFX_Enemy_ReturnFire_Tracers";
                enemyTracer.transform.SetParent(vfxRoot, false);
                enemyTracer.transform.position = center + new Vector3(0.5f, 1.5f, 24f);
                enemyTracer.transform.rotation = Quaternion.Euler(2f, 195f, 0f);
            }
        }

        private static void SetupCinematicCameras(Vector3 center)
        {
            Transform camRoot = GetOrCreateRoot("[Cinematic_Cutscene_Cameras]");

            // Cam 1: Low-angle dynamic squad advance (Action Wide)
            CreateCinematicCamera(camRoot, "CinematicCam_1_SquadAdvance", 
                center + new Vector3(-2.8f, 0.7f, -4.5f), 
                Quaternion.Euler(6f, 22f, 0f), 42f);

            // Cam 2: Over the shoulder aiming down sights
            CreateCinematicCamera(camRoot, "CinematicCam_2_OverTheShoulder", 
                center + new Vector3(-0.7f, 1.5f, -1.8f), 
                Quaternion.Euler(4f, 16f, 0f), 35f);

            // Cam 3: Epic Battlefield Panorama with Earthrise in Sky
            CreateCinematicCamera(camRoot, "CinematicCam_3_EarthriseBattle", 
                center + new Vector3(-12.0f, 4.2f, -14.0f), 
                Quaternion.Euler(14f, 32f, 0f), 55f);

            // Cam 4: Close-Up Combat Hero Portrait
            CreateCinematicCamera(camRoot, "CinematicCam_4_HeroCloseUp", 
                center + new Vector3(0.9f, 1.35f, 2.2f), 
                Quaternion.Euler(6f, 205f, 0f), 30f);
        }

        private static Camera CreateCinematicCamera(Transform parent, string name, Vector3 pos, Quaternion rot, float fov)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            go.transform.position = pos;
            go.transform.rotation = rot;

            var cam = go.AddComponent<Camera>();
            cam.fieldOfView = fov;
            cam.nearClipPlane = 0.1f;
            cam.farClipPlane = 1500f;
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.01f, 0.01f, 0.02f, 1f);

            var urpData = go.AddComponent<UniversalAdditionalCameraData>();
            urpData.renderPostProcessing = true;

            return cam;
        }
    }
}

