            result.Log($"Audio clips count: {guids.Length}");
            for (int i = 0; i < Mathf.Min(20, guids.Length); i++)
            {
                result.Log($"   -> {AssetDatabase.GUIDToAssetPath(guids[i])}");
            }
        }
    }
