using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;

namespace Alita
{
    public enum MoonBattleCutscenePhase
    {
        FortressBreach,      // 0.0s - 9.0s: Wide establishing shot of the lunar defense wall & Earth
        VanguardAssault,     // 9.0s - 18.0s: Dynamic low-angle tracking shot of charging spacesuit troops
        ZeroGravityLeap,     // 18.0s - 26.0s: Alita's mid-air zero-gravity combat leap with bullet time
        CrossfireClash,      // 26.0s - 35.0s: Intense over-the-shoulder firefight against enemy soldiers
        TheCommanderBond,    // 35.0s - 44.0s: Commander Gelda reaches out hand to Alita against Earth backdrop
        IconicRemembrance    // 44.0s - 52.0s: Macro close-up on Alita's face reflecting the blue Earth
    }

    [System.Serializable]
    public class CinematicCameraShot
    {
        public string shotName;
        public Vector3 startPos;
        public Vector3 endPos;
        public Vector3 startRotEuler;
        public Vector3 endRotEuler;
        public float startFov = 45f;
        public float endFov = 40f;
    }

    /// <summary>
    /// Master 52-second AAA Cinematic Cutscene Director for the Alita Moon Flashback Battle.
    /// Based directly on the reference storyboard:
    /// - Shot 1: Colossal fortress defense wall on lunar surface under giant blue Earth.
    /// - Shot 2: Low-angle vanguard charge of URM spacesuit troops in low gravity.
    /// - Shot 3: Alita mid-air low-g leap with assault rifle and bullet-time.
    /// - Shot 4: Heavy ridge crossfire and muzzle flare bursts.
    /// - Shot 5: Emotional clasp between Commander Gelda and Alita against the Earth.
    /// - Shot 6: Iconic close-up of Alita looking up in remembrance with Earth in the cosmos.
    /// </summary>
    public class AlitaMoonBattleCutsceneDirector : MonoBehaviour
    {
        public static AlitaMoonBattleCutsceneDirector Instance { get; private set; }

        [Header("Playback State")]
        public MoonBattleCutscenePhase currentPhase = MoonBattleCutscenePhase.FortressBreach;
        public float currentTime = 0f;
        public float totalDuration = 52.0f;
        public bool isPlaying = true;
        public bool autoPlayOnStart = true;
        public bool loopAfterFinish = false;

        [Header("Cinematic Camera Rig")]
        public Camera cinematicCamera;
        public float cameraShakeIntensity = 0f;

        [Header("Actors")]
        public GameObject alitaHero;
        public GameObject commanderGelda;
        public List<GameObject> squadTroops = new List<GameObject>();
        public List<GameObject> enemyTroops = new List<GameObject>();

        [Header("Environment & Celestial")]
        public Transform earthTransform;
        public Light lunarSunLight;

        [Header("VFX & Particles")]
        public GameObject tracerVFXRoot;
        public GameObject muzzleFlashVFXRoot;
        public GameObject explosionVFXRoot;

        [Header("Audio")]
        public AudioSource musicSource;
        public AudioSource combatSFXSource;
        public AudioClip combatSoundtrack;
        public AudioClip emotionalSoundtrack;

        // Subtitles & Film Letterbox Styling
        private Texture2D _blackPixel;
        private Texture2D _boxBgPixel;
        private GUIStyle _speakerStyle;
        private GUIStyle _subStyle;
        private GUIStyle _timecodeStyle;
        private string _activeSpeaker = "";
        private string _activeSubtitle = "";

        // Predefined Camera Shots
        private Dictionary<MoonBattleCutscenePhase, CinematicCameraShot> _shots = new Dictionary<MoonBattleCutscenePhase, CinematicCameraShot>();

        private void Awake()
        {
            Instance = this;
            SetupStyles();
            SetupShots();
        }

        private void Start()
        {
            if (cinematicCamera == null)
            {
                cinematicCamera = Camera.main;
            }

            if (autoPlayOnStart)
            {
                StartCutscene();
            }
        }

        private void SetupStyles()
        {
            _blackPixel = new Texture2D(1, 1);
            _blackPixel.SetPixel(0, 0, Color.black);
            _blackPixel.Apply();

            _boxBgPixel = new Texture2D(1, 1);
            _boxBgPixel.SetPixel(0, 0, new Color(0.04f, 0.06f, 0.10f, 0.88f));
            _boxBgPixel.Apply();
        }

        private void SetupShots()
        {
            // Base battle origin at lunar ridge: (172, 13, 10)
            Vector3 center = new Vector3(172f, 13f, 10f);

            // Shot 1: Wide establishing shot of the fortress battlements & giant Earth in sky
            _shots[MoonBattleCutscenePhase.FortressBreach] = new CinematicCameraShot
            {
                shotName = "Wide_Fortress_Breach",
                startPos = center + new Vector3(-25f, 12f, -32f),
                endPos = center + new Vector3(-18f, 10f, -24f),
                startRotEuler = new Vector3(14f, 40f, 0f),
                endRotEuler = new Vector3(11f, 36f, 0f),
                startFov = 58f,
                endFov = 50f
            };

            // Shot 2: Low-angle tracking shot right beside charging vanguard troops
            _shots[MoonBattleCutscenePhase.VanguardAssault] = new CinematicCameraShot
            {
                shotName = "Low_Angle_Vanguard_Charge",
                startPos = center + new Vector3(-5.2f, 0.7f, -7.5f),
                endPos = center + new Vector3(-3.8f, 1.1f, -1.5f),
                startRotEuler = new Vector3(5f, 24f, 0f),
                endRotEuler = new Vector3(7f, 18f, 0f),
                startFov = 48f,
                endFov = 42f
            };

            // Shot 3: Hero Action - Alita zero-gravity leap spiral camera with bullet time
            _shots[MoonBattleCutscenePhase.ZeroGravityLeap] = new CinematicCameraShot
            {
                shotName = "Alita_ZeroG_Leap",
                startPos = center + new Vector3(2.5f, 3.2f, -1.8f),
                endPos = center + new Vector3(-1.8f, 2.4f, 3.5f),
                startRotEuler = new Vector3(8f, -45f, 0f),
                endRotEuler = new Vector3(15f, 65f, 0f),
                startFov = 40f,
                endFov = 34f
            };

            // Shot 4: Over-the-shoulder intense crossfire against enemy soldiers
            _shots[MoonBattleCutscenePhase.CrossfireClash] = new CinematicCameraShot
            {
                shotName = "OTS_Ridge_Firefight",
                startPos = center + new Vector3(-0.8f, 1.45f, -1.4f),
                endPos = center + new Vector3(-0.4f, 1.55f, 0.8f),
                startRotEuler = new Vector3(4f, 10f, 0f),
                endRotEuler = new Vector3(2f, 8f, 0f),
                startFov = 36f,
                endFov = 30f
            };

            // Shot 5: Commander Gelda reaches out hand to Alita against the giant Earth
            _shots[MoonBattleCutscenePhase.TheCommanderBond] = new CinematicCameraShot
            {
                shotName = "Commander_Hand_Clasp",
                startPos = center + new Vector3(-2.2f, 1.1f, 1.2f),
                endPos = center + new Vector3(-1.4f, 1.25f, 1.6f),
                startRotEuler = new Vector3(4f, 35f, 0f),
                endRotEuler = new Vector3(6f, 40f, 0f),
                startFov = 32f,
                endFov = 26f
            };

            // Shot 6: Iconic macro close-up on Alita's face reflecting the blue Earth
            _shots[MoonBattleCutscenePhase.IconicRemembrance] = new CinematicCameraShot
            {
                shotName = "Alita_Iconic_Remembrance",
                startPos = center + new Vector3(0.55f, 1.35f, 1.8f),
                endPos = center + new Vector3(0.42f, 1.32f, 1.25f),
                startRotEuler = new Vector3(5f, 198f, 0f),
                endRotEuler = new Vector3(7f, 194f, 0f),
                startFov = 28f,
                endFov = 22f
            };
        }

        public void StartCutscene()
        {
            currentTime = 0f;
            isPlaying = true;
            Time.timeScale = 1.0f;

            if (musicSource != null && combatSoundtrack != null)
            {
                musicSource.clip = combatSoundtrack;
                musicSource.loop = true;
                musicSource.Play();
            }
        }

        private void Update()
        {
            // Keyboard interactive shortcuts
            if (Input.GetKeyDown(KeyCode.Space))
            {
                isPlaying = !isPlaying;
            }
            if (Input.GetKeyDown(KeyCode.R))
            {
                StartCutscene();
            }
            if (Input.GetKeyDown(KeyCode.Alpha1)) ScrubTo(0f);
            if (Input.GetKeyDown(KeyCode.Alpha2)) ScrubTo(9f);
            if (Input.GetKeyDown(KeyCode.Alpha3)) ScrubTo(18f);
            if (Input.GetKeyDown(KeyCode.Alpha4)) ScrubTo(26f);
            if (Input.GetKeyDown(KeyCode.Alpha5)) ScrubTo(35f);
            if (Input.GetKeyDown(KeyCode.Alpha6)) ScrubTo(44f);

            if (!isPlaying) return;

            currentTime += Time.deltaTime;
            if (currentTime >= totalDuration)
            {
                if (loopAfterFinish)
                {
                    StartCutscene();
                }
                else
                {
                    isPlaying = false;
                    Time.timeScale = 1.0f;
                }
                return;
            }

            UpdateCutscenePhase();
            UpdateCameraChoreography();
            UpdateActorPacing();
            UpdateVFXAndAudio();
        }

        public void ScrubTo(float time)
        {
            currentTime = Mathf.Clamp(time, 0f, totalDuration);
            UpdateCutscenePhase();
            UpdateCameraChoreography();
        }

        private void UpdateCutscenePhase()
        {
            if (currentTime < 9.0f)
            {
                currentPhase = MoonBattleCutscenePhase.FortressBreach;
                _activeSpeaker = "U.R.M. INVASION ARCHIVE";
                _activeSubtitle = "THE FALL // LUNAR DEFENSE SECTOR 04 - FORWARD ASSAULT";
            }
            else if (currentTime < 18.0f)
            {
                currentPhase = MoonBattleCutscenePhase.VanguardAssault;
                _activeSpeaker = "URM VANGUARD SQUAD";
                _activeSubtitle = "\"Breach charge armed! Suppress the heavy towers! Push to the ridge!\"";
            }
            else if (currentTime < 26.0f)
            {
                currentPhase = MoonBattleCutscenePhase.ZeroGravityLeap;
                _activeSpeaker = "ALITA (BERSERKER 99)";
                _activeSubtitle = "\"Commander, I have angle on the perimeter bunker! Leaping in!\"";
            }
            else if (currentTime < 35.0f)
            {
                currentPhase = MoonBattleCutscenePhase.CrossfireClash;
                _activeSpeaker = "GELDA (URM COMMANDER)";
                _activeSubtitle = "\"Incoming heavy artillery! Hold the line, 99! On my mark!\"";
            }
            else if (currentTime < 44.0f)
            {
                currentPhase = MoonBattleCutscenePhase.TheCommanderBond;
                _activeSpeaker = "GELDA";
                _activeSubtitle = "\"I've got you. Stay focused, 99. Together we finish this!\"";
            }
            else
            {
                currentPhase = MoonBattleCutscenePhase.IconicRemembrance;
                _activeSpeaker = "ALITA";
                _activeSubtitle = "\"...I remember. That was the day we fought for the future.\"";
            }
        }

        private void UpdateCameraChoreography()
        {
            if (cinematicCamera == null || !_shots.ContainsKey(currentPhase)) return;

            CinematicCameraShot shot = _shots[currentPhase];
            float phaseStart = GetPhaseStartTime(currentPhase);
            float phaseDuration = GetPhaseDuration(currentPhase);
            float t = Mathf.Clamp01((currentTime - phaseStart) / phaseDuration);

            // Smooth cubic ease in-out
            float easeT = Mathf.SmoothStep(0f, 1f, t);

            Vector3 targetPos = Vector3.Lerp(shot.startPos, shot.endPos, easeT);
            Quaternion targetRot = Quaternion.Slerp(
                Quaternion.Euler(shot.startRotEuler), 
                Quaternion.Euler(shot.endRotEuler), 
                easeT);
            float targetFov = Mathf.Lerp(shot.startFov, shot.endFov, easeT);

            // Dynamic camera shake
            if (cameraShakeIntensity > 0.001f)
            {
                Vector3 shake = new Vector3(
                    (Mathf.PerlinNoise(Time.time * 25f, 0f) - 0.5f) * cameraShakeIntensity,
                    (Mathf.PerlinNoise(0f, Time.time * 25f) - 0.5f) * cameraShakeIntensity,
                    0f);
                targetPos += shake;
            }

            cinematicCamera.transform.position = targetPos;
            cinematicCamera.transform.rotation = targetRot;
            cinematicCamera.fieldOfView = targetFov;
        }

        private void UpdateActorPacing()
        {
            Vector3 center = new Vector3(172f, 13f, 10f);

            // Phase 3 Bullet-time dynamic slow motion for Alita's zero-g leap
            if (currentPhase == MoonBattleCutscenePhase.ZeroGravityLeap)
            {
                float leapT = (currentTime - 18.0f) / 8.0f;
                Time.timeScale = Mathf.Lerp(0.35f, 0.75f, leapT);

                if (alitaHero != null)
                {
                    // Dynamic zero-g leap arc
                    float arcY = Mathf.Sin(leapT * Mathf.PI) * 2.2f;
                    alitaHero.transform.position = center + new Vector3(leapT * 4.2f, arcY, leapT * 3.5f);
                    alitaHero.transform.rotation = Quaternion.Euler(-12f, 35f + leapT * 15f, 5f);
                }
            }
            else
            {
                Time.timeScale = 1.0f;
            }

            // Phase 5 Commander & Alita Hand Reaching
            if (currentPhase == MoonBattleCutscenePhase.TheCommanderBond)
            {
                if (alitaHero != null)
                {
                    alitaHero.transform.position = center + new Vector3(0f, 0.2f, 0f);
                    alitaHero.transform.rotation = Quaternion.Euler(5f, 15f, 0f);
                }
                if (commanderGelda != null)
                {
                    commanderGelda.transform.position = center + new Vector3(-0.95f, 0.25f, 0.45f);
                    commanderGelda.transform.rotation = Quaternion.Euler(0f, 65f, 0f);
                }
            }

            // Phase 6 Close up pose
            if (currentPhase == MoonBattleCutscenePhase.IconicRemembrance)
            {
                if (alitaHero != null)
                {
                    alitaHero.transform.position = center + new Vector3(0f, 0.0f, 0f);
                    alitaHero.transform.rotation = Quaternion.Euler(3f, 12f, 0f);
                }
            }
        }

        private void UpdateVFXAndAudio()
        {
            // Explosions and camera shake in Phase 1 and 4
            if (currentPhase == MoonBattleCutscenePhase.FortressBreach)
            {
                cameraShakeIntensity = Mathf.Sin(currentTime * 3f) > 0.7f ? 0.08f : 0.02f;
            }
            else if (currentPhase == MoonBattleCutscenePhase.CrossfireClash)
            {
                cameraShakeIntensity = 0.12f;
            }
            else
            {
                cameraShakeIntensity = Mathf.MoveTowards(cameraShakeIntensity, 0f, Time.deltaTime * 0.5f);
            }

            // Soundtrack crossfade in Phase 6
            if (currentPhase == MoonBattleCutscenePhase.IconicRemembrance)
            {
                if (emotionalSoundtrack != null && musicSource != null && musicSource.clip != emotionalSoundtrack)
                {
                    musicSource.clip = emotionalSoundtrack;
                    musicSource.Play();
                }
            }
        }

        private float GetPhaseStartTime(MoonBattleCutscenePhase phase)
        {
            switch (phase)
            {
                case MoonBattleCutscenePhase.FortressBreach: return 0.0f;
                case MoonBattleCutscenePhase.VanguardAssault: return 9.0f;
                case MoonBattleCutscenePhase.ZeroGravityLeap: return 18.0f;
                case MoonBattleCutscenePhase.CrossfireClash: return 26.0f;
                case MoonBattleCutscenePhase.TheCommanderBond: return 35.0f;
                case MoonBattleCutscenePhase.IconicRemembrance: return 44.0f;
                default: return 0f;
            }
        }

        private float GetPhaseDuration(MoonBattleCutscenePhase phase)
        {
            switch (phase)
            {
                case MoonBattleCutscenePhase.FortressBreach: return 9.0f;
                case MoonBattleCutscenePhase.VanguardAssault: return 9.0f;
                case MoonBattleCutscenePhase.ZeroGravityLeap: return 8.0f;
                case MoonBattleCutscenePhase.CrossfireClash: return 9.0f;
                case MoonBattleCutscenePhase.TheCommanderBond: return 9.0f;
                case MoonBattleCutscenePhase.IconicRemembrance: return 8.0f;
                default: return 9f;
            }
        }

        private void OnGUI()
        {
            float screenW = Screen.width;
            float screenH = Screen.height;

            // ── 1. Anamorphic 2.39:1 Cinema Letterbox Bars ─────────────────────────────
            float targetAspect = 2.39f;
            float currentAspect = screenW / screenH;
            float barH = 0f;

            if (currentAspect > targetAspect)
            {
                // Screen is wider than 2.39:1
            }
            else
            {
                // Standard 16:9 (1.77) -> Draw top and bottom cinema bars
                float cinemaHeight = screenW / targetAspect;
                barH = (screenH - cinemaHeight) * 0.5f;
            }

            if (barH > 0f)
            {
                // Top bar
                GUI.DrawTexture(new Rect(0, 0, screenW, barH), _blackPixel);
                // Bottom bar
                GUI.DrawTexture(new Rect(0, screenH - barH, screenW, barH), _blackPixel);
            }

            // ── 2. Top-Left Live Film Timecode & Phase HUD ────────────────────────────
            if (_timecodeStyle == null)
            {
                _timecodeStyle = new GUIStyle(GUI.skin.label)
                {
                    fontSize = Mathf.Clamp(Mathf.RoundToInt(screenH * 0.016f), 11, 18),
                    fontStyle = FontStyle.Bold,
                    alignment = TextAnchor.UpperLeft
                };
                _timecodeStyle.normal.textColor = new Color(0.15f, 0.85f, 1.0f, 0.85f); // Cyan sci-fi
            }

            int mins = Mathf.FloorToInt(currentTime / 60f);
            int secs = Mathf.FloorToInt(currentTime % 60f);
            int millis = Mathf.FloorToInt((currentTime * 100f) % 100f);
            string tc = $"REC [URM-MEM-099]  TC {mins:00}:{secs:00}.{millis:00}  // PHASE: {currentPhase}";
            GUI.Label(new Rect(32, barH + 16, 600, 30), tc, _timecodeStyle);

            // ── 3. Frosted Glass Cinematic Subtitles ──────────────────────────────────
            if (!string.IsNullOrEmpty(_activeSubtitle))
            {
                if (_speakerStyle == null)
                {
                    _speakerStyle = new GUIStyle(GUI.skin.label)
                    {
                        fontSize = Mathf.Clamp(Mathf.RoundToInt(screenH * 0.018f), 12, 20),
                        fontStyle = FontStyle.Bold,
                        alignment = TextAnchor.MiddleCenter
                    };
                    _speakerStyle.normal.textColor = new Color(0.20f, 0.88f, 1.0f, 1.0f); // Bright Cyan
                }

                if (_subStyle == null)
                {
                    _subStyle = new GUIStyle(GUI.skin.label)
                    {
                        fontSize = Mathf.Clamp(Mathf.RoundToInt(screenH * 0.022f), 14, 26),
                        fontStyle = FontStyle.Normal,
                        alignment = TextAnchor.MiddleCenter,
                        wordWrap = true
                    };
                    _subStyle.normal.textColor = Color.white;
                }

                float boxW = Mathf.Min(screenW * 0.72f, 950f);
                float boxH = 68f;
                float boxX = (screenW - boxW) * 0.5f;
                float boxY = screenH - barH - boxH - 24f;

                // Frosted Dark Glass Underlay
                GUI.DrawTexture(new Rect(boxX, boxY, boxW, boxH), _boxBgPixel);

                // Speaker name
                GUI.Label(new Rect(boxX, boxY + 4, boxW, 22), _activeSpeaker, _speakerStyle);

                // Subtitle Line
                GUI.Label(new Rect(boxX + 16, boxY + 26, boxW - 32, 36), _activeSubtitle, _subStyle);
            }
        }
    }
}

