using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Find a humanoid run/aim animation clip
        var clips = AssetDatabase.FindAssets("A_Jump_Sprinting_Masc t:AnimationClip");
        if (clips.Length > 0)
        {
            var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(AssetDatabase.GUIDToAssetPath(clips[0]));
            result.Log($"Loaded clip: {clip.name}");

            var soldiers = GameObject.FindGameObjectsWithTag("Untagged");
            int sampled = 0;
            foreach (var go in soldiers)
            {
                if (go.name.StartsWith("URM_Soldier") || go.name.Contains("Gelda"))
                {
                    AnimationMode.SampleAnimationClip(go, clip, 0.4f);
                    sampled++;
                }
            }
            result.Log($"Sampled clip on {sampled} soldiers!");
            if (SceneView.lastActiveSceneView != null) SceneView.lastActiveSceneView.Repaint();
        }
        else
        {
            result.Log("Clip not found");
        }
