private void UpdateCameraChoreography()
{
    if (cinematicCamera == null || !_shots.ContainsKey(currentPhase)) return;

    CinematicCameraShot shot = _shots[currentPhase];
    float phaseStart = GetPhaseStartTime(currentPhase);
    float phaseDuration = GetPhaseDuration(currentPhase);
    float t = Mathf.Clamp01((currentTime - phaseStart) / phaseDuration);

    // Smooth cubic ease in-out
    float easeT = Mathf.SmoothStep(0f, 1f, t);

    Vector3 center = new Vector3(172f, 13f, 10f);
    Vector3 targetPos = Vector3.Lerp(shot.startPos, shot.endPos, easeT);
    Quaternion targetRot;

    // Intelligent cinematic LookAt framing for each shot
    switch (currentPhase)
    {
        case MoonBattleCutscenePhase.FortressBreach:
            Vector3 lookBreach = center + new Vector3(3.5f, 1.6f, 2.5f);
            targetRot = Quaternion.LookRotation((lookBreach - targetPos).normalized, Vector3.up);
            break;
        case MoonBattleCutscenePhase.VanguardAssault:
            Vector3 lookVanguard = center + new Vector3(2.0f, 1.25f, 1.0f);
            targetRot = Quaternion.LookRotation((lookVanguard - targetPos).normalized, Vector3.up);
            break;
        case MoonBattleCutscenePhase.ZeroGravityLeap:
            Vector3 lookHero = (alitaHero != null) ? (alitaHero.transform.position + Vector3.up * 0.45f) : (center + Vector3.up * 1.5f);
            targetRot = Quaternion.LookRotation((lookHero - targetPos).normalized, Vector3.up);
            break;
        case MoonBattleCutscenePhase.CrossfireClash:
            Vector3 lookCrossfire = center + new Vector3(16.0f, 1.3f, 2.0f);
            targetRot = Quaternion.LookRotation((lookCrossfire - targetPos).normalized, Vector3.up);
            break;
        case MoonBattleCutscenePhase.TheCommanderBond:
            Vector3 alitaP = (alitaHero != null) ? alitaHero.transform.position : center;
            Vector3 geldaP = (commanderGelda != null) ? commanderGelda.transform.position : center;
            Vector3 lookBond = (alitaP + geldaP) * 0.5f + Vector3.up * 0.85f;
            targetRot = Quaternion.LookRotation((lookBond - targetPos).normalized, Vector3.up);
            break;
        case MoonBattleCutscenePhase.IconicRemembrance:
            Vector3 lookRemembrance = (alitaHero != null) ? (alitaHero.transform.position + Vector3.up * 1.38f) : (center + Vector3.up * 1.38f);
            targetRot = Quaternion.LookRotation((lookRemembrance - targetPos).normalized, Vector3.up);
            break;
        default:
            targetRot = Quaternion.Slerp(Quaternion.Euler(shot.startRotEuler), Quaternion.Euler(shot.endRotEuler), easeT);
            break;
    }

    float targetFov = Mathf.Lerp(shot.startFov, shot.endFov, easeT);

    // Dynamic camera shake
    if (cameraShakeIntensity > 0.001f)
    {
        Vector3 shake = new Vector3(
            (Mathf.PerlinNoise(Time.time * 25f, 0f) - 0.5f) * cameraShakeIntensity,
            (Mathf.PerlinNoise(0f, Time.time * 25f) - 0.5f) * cameraShakeIntensity,
            0f);
        targetPos += shake;
    }

    cinematicCamera.transform.position = targetPos;
    cinematicCamera.transform.rotation = targetRot;
    cinematicCamera.fieldOfView = targetFov;
}

private void UpdateActorPacing()
{
    Vector3 center = new Vector3(172f, 13f, 10f);

    // Phase 3 Bullet-time dynamic slow motion for Alita's zero-g leap
    if (currentPhase == MoonBattleCutscenePhase.ZeroGravityLeap)
    {
        float leapT = Mathf.Clamp01((currentTime - 18.0f) / 8.0f);
        Time.timeScale = Mathf.Lerp(0.35f, 0.75f, leapT);

        if (alitaHero != null)
        {
            // Dynamic zero-g leap arc
            float arcY = Mathf.Sin(leapT * Mathf.PI) * 2.6f;
            alitaHero.transform.position = center + new Vector3(leapT * 3.8f, arcY, leapT * 3.0f);
            alitaHero.transform.rotation = Quaternion.Euler(-15f, 38f + leapT * 10f, 6f);
        }
    }
    else
    {
        Time.timeScale = 1.0f;
    }

    // Phase 5 Commander & Alita Hand Reaching
    if (currentPhase == MoonBattleCutscenePhase.TheCommanderBond)
    {
        if (alitaHero != null)
        {
            alitaHero.transform.position = center + new Vector3(0.2f, 0.05f, 0.15f);
            alitaHero.transform.rotation = Quaternion.Euler(0f, -25f, 0f);
        }
        if (commanderGelda != null)
        {
            commanderGelda.transform.position = center + new Vector3(-0.55f, 0.15f, 0.45f);
            commanderGelda.transform.rotation = Quaternion.Euler(0f, 135f, 0f);
        }
    }

    // Phase 6 Close up pose
    if (currentPhase == MoonBattleCutscenePhase.IconicRemembrance)
    {
        if (alitaHero != null)
        {
            alitaHero.transform.position = center + new Vector3(0f, 0.0f, 0f);
            alitaHero.transform.rotation = Quaternion.Euler(-6f, 25f, 0f);
        }
    }
}

