using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    private AnimationClip GetClipFromFBX(string path)
    {
        var assets = AssetDatabase.LoadAllAssetsAtPath(path);
        foreach (var a in assets)
        {
            if (a is AnimationClip c && !c.name.StartsWith("__preview__"))
            {
                return c;
            }
        }
        return null;
    }

    public void Execute(ExecutionResult result)
    {
        string[] paths = new string[]
        {
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/atk_gun_walking.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/atk_gun_01.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/atk_gun_02.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/jump.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/idle.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/sit.fbx",
            "Assets/InsaneGun_Sword_Set/Animation/Humanoid/move_run_front.fbx"
        };

        foreach (var p in paths)
        {
            var clip = GetClipFromFBX(p);
            result.Log("Path {0} -> Clip: {1}", System.IO.Path.GetFileName(p), clip != null ? clip.name : "NULL");
        }
    }
}

