// 1. Pose Alita
if (director.alitaHero != null)
{
    AnimationClip alitaClip = clipGunWalk;
    float sampleT = 0.35f;

    if (i == 0) { alitaClip = clipGunWalk; sampleT = 0.35f; }
    else if (i == 1) { alitaClip = clipGunWalk; sampleT = 0.55f; }
    else if (i == 2) { alitaClip = clipJump != null ? clipJump : clipGunWalk; sampleT = 0.28f; }
    else if (i == 3) { alitaClip = clipGun01; sampleT = 0.25f; }
    else if (i == 4) { alitaClip = clipSit; sampleT = 0.20f; }
    else if (i == 5) { alitaClip = clipIdle; sampleT = 0.50f; }

    SafeSample(director.alitaHero, alitaClip, sampleT);
}

// 2. Pose Commander Gelda
if (director.commanderGelda != null)
{
    AnimationClip geldaClip = clipRunFront;
    float sampleT = 0.40f;

    if (i <= 1) { geldaClip = clipRunFront; sampleT = 0.45f; }
    else if (i == 2 || i == 3) { geldaClip = clipGun02; sampleT = 0.35f; }
    else if (i == 4) { geldaClip = clipSit; sampleT = 0.40f; }
    else { geldaClip = clipGun02; sampleT = 0.15f; }

    SafeSample(director.commanderGelda, geldaClip, sampleT);
}

// 3. Pose Vanguard Squad Troops
for (int s = 0; s < director.squadTroops.Count; s++)
{
    var soldier = director.squadTroops[s];
