+            for (int e = 0; e < enemyTroops.Count && e < enemyPositions.Length; e++)
+            {
+                if (enemyTroops[e] != null)
+                {
+                    enemyTroops[e].transform.position = enemyRidgeCenter + enemyPositions[e];
+                    enemyTroops[e].transform.rotation = Quaternion.Euler(0f, 185f + (e * 5f), 0f);
+                }
+            }
+        }
+
+        private void UpdateSpaceDogfights()
+        {
+            Vector3 center = new Vector3(172f, 13f, 10f);
+
+            // 1. Starfighter Squadron Alpha (URM Starfighters)
+            // Flying high across the lunar sky in front of the giant Earth
+            for (int i = 0; i < starfighters.Count; i++)
+            {
+                if (starfighters[i] == null) continue;
+                float shipCycle = (currentTime * 0.055f + (i * 0.045f)) % 1.0f;
+                Vector3 wingOffset = new Vector3(i * -14f, i * 4.5f, i * -10f);
+                float x = Mathf.Lerp(60f, 300f, shipCycle);
+                float y = 52f + Mathf.Sin(shipCycle * Mathf.PI * 2f + i) * 8f;
+                float z = Mathf.Lerp(20f, 130f, shipCycle);
+
+                starfighters[i].transform.position = new Vector3(x, y, z) + wingOffset;
+                Vector3 forwardDir = new Vector3(240f, 18f, 110f).normalized;
+                starfighters[i].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, Mathf.Sin(currentTime * 2.2f + i) * 22f);
+            }
+
+            // 2. Enemy Interceptors (Defense Fighters)
+            // Chasing Squadron Alpha closely, banking aggressively
+            for (int e = 0; e < enemyInterceptors.Count; e++)
+            {
+                if (enemyInterceptors[e] == null) continue;
+                float chaseCycle = ((currentTime + 0.45f + e * 0.22f) * 0.055f) % 1.0f;
+                Vector3 chaseOffset = new Vector3(e * -16f - 22f, -5f + e * 4.5f, -18f - e * 12f);
+                float x = Mathf.Lerp(40f, 280f, chaseCycle);
+                float y = 47f + Mathf.Sin(chaseCycle * Mathf.PI * 2f + e) * 7.5f;
+                float z = Mathf.Lerp(12f, 120f, chaseCycle);
+
+                enemyInterceptors[e].transform.position = new Vector3(x, y, z) + chaseOffset;
+                Vector3 forwardDir = new Vector3(240f, 18f, 110f).normalized;
+                enemyInterceptors[e].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, -28f + Mathf.Sin(currentTime * 2.8f + e) * 25f);
+            }
+
+            // 3. Low-Altitude Assault Gunship
+            // Sweeps in low over the battle ridge during Shots 2 & 3 (8s to 26s)
+            if (assaultGunship != null)
+            {
+                if (currentTime >= 7.0f && currentTime <= 28.0f)
+                {
+                    assaultGunship.SetActive(true);
+                    float runT = (currentTime - 7.0f) / 21.0f;
+                    Vector3 startRun = center + new Vector3(-45f, 22f, -32f);
+                    Vector3 endRun = center + new Vector3(42f, 16f, 32f);
+                    assaultGunship.transform.position = Vector3.Lerp(startRun, endRun, runT);
+                    Vector3 heading = (endRun - startRun).normalized;
+                    assaultGunship.transform.rotation = Quaternion.LookRotation(heading, Vector3.up) * Quaternion.Euler(10f, 0f, 32f);
+                }
+                else
+                {
+                    // High orbit standby
+                    assaultGunship.transform.position = center + new Vector3(90f, 85f, 95f);
+                }
+            }
+
+            // 4. Space Dogfight Laser Beams (Line Renderers)
+            for (int l = 0; l < dogfightLaserBeams.Count; l++)
+            {
+                var lr = dogfightLaserBeams[l];
+                if (lr == null) continue;
+                bool isCyan = (l % 2 == 0);
+                float laserCycle = (currentTime * 4.8f + l * 0.35f) % 1.0f;
+                Vector3 origin, target;
+                if (isCyan && starfighters.Count > 0 && starfighters[0] != null)
+                {
+                    origin = starfighters[0].transform.position + new Vector3(0f, -1f, 2f);
+                    target = origin + starfighters[0].transform.forward * 48f;
+                }
+                else if (enemyInterceptors.Count > 0 && enemyInterceptors[0] != null)
+                {
+                    origin = enemyInterceptors[0].transform.position + new Vector3(0f, 0f, 2f);
+                    target = origin + enemyInterceptors[0].transform.forward * 42f;
+                }
+                else
+                {
+                    origin = new Vector3(120f, 50f, 40f) + new Vector3(l * 12f, l * 2.5f, l * 6f);
+                    target = origin + new Vector3(65f, 5f, 32f);
+                }
+
+                Vector3 curStart = Vector3.Lerp(origin, target, Mathf.Max(0f, laserCycle - 0.28f));
+                Vector3 curEnd = Vector3.Lerp(origin, target, laserCycle);
+                lr.SetPosition(0, curStart);
+                lr.SetPosition(1, curEnd);
+            }
+
+            // 5. Planetary Cannon Recoil & Horizon Titan Artillery
+            if (planetaryCannon != null)
+            {
