        [MenuItem("Cyberpunk/Dump All Cutscene Frames And Build Matrix")]
        public static void DumpFramesAndBuildMatrix()
        {
            string scenePath = "Assets/Scenes/Scene_Moon_Battle_Flashback.unity";
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);

            var director = Object.FindFirstObjectByType<AlitaMoonBattleCutsceneDirector>();
            if (director == null || director.cinematicCamera == null)
            {
                Debug.LogError("[FrameInspector] Director or Cinematic Camera not found!");
                return;
            }

            string outDir = Path.Combine(Application.dataPath, "../VerifiedCutsceneFrames/MoonBattle");
            if (!Directory.Exists(outDir))
            {
                Directory.CreateDirectory(outDir);
            }

            // Load authentic humanoid inplace gun combat clips
            var clipGunWalk = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_walking_inplace.fbx");
            var clipGun01 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_01_inplace.fbx");
            var clipGun02 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_02_inplace.fbx");
            var clipGun03 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_03_inplace.fbx");
            var clipGun04 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_04_inplace.fbx");
            var clipRun = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/move_run_front_inplace.fbx");
            var clipStrafe = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/run_strafe_front_inplace.fbx");
            var clipJump = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/jump_inplace.fbx");
            var clipRoll = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/roll_front_inplace.fbx");
            var clipReload = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/reload_inplace.fbx");
            var clipHit = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/hit_heavy_front_inplace.fbx");
            var clipIdle = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/N_idle_inplace.fbx");

            var cam = director.cinematicCamera;

            // ── 1. Render all 52 Seconds (0s to 51s) ──────────────────────────────────
            int totalSeconds = 52;
            int cellW = 320;
            int cellH = 180;
            int cols = 8;
            int rows = 7; // 8 x 7 = 56 slots

            Texture2D[] secondThumbnails = new Texture2D[totalSeconds];

            var renderRT = new RenderTexture(960, 540, 24, RenderTextureFormat.ARGB32);

            for (int sec = 0; sec < totalSeconds; sec++)
            {
                float t = (float)sec;
                director.ScrubTo(t);

                AnimationMode.StartAnimationMode();

                // Dynamic combat choreography at this exact second
                SampleCombatChoreography(
                    director, t,
                    clipGunWalk, clipGun01, clipGun02, clipGun03, clipGun04,
                    clipRun, clipStrafe, clipJump, clipRoll, clipReload, clipHit, clipIdle);

                cam.targetTexture = renderRT;
                cam.Render();

                RenderTexture.active = renderRT;
                var frameTex = new Texture2D(960, 540, TextureFormat.RGB24, false);
                frameTex.ReadPixels(new Rect(0, 0, 960, 540), 0, 0);
                frameTex.Apply();

                cam.targetTexture = null;
                RenderTexture.active = null;

                AnimationMode.StopAnimationMode();

                // Downscale to 320x180 for matrix cell
                var thumb = ScaleTexture(frameTex, cellW, cellH);
                secondThumbnails[sec] = thumb;

                // Burn timestamp label onto thumbnail (bottom-left)
                DrawTimestamp(thumb, 12, 14, sec);
                thumb.Apply();

                // Save individual key seconds (every 4 seconds or hero seconds)
                if (sec % 3 == 0 || sec == 51)
                {
                    byte[] pngBytes = frameTex.EncodeToPNG();
                    string secPath = Path.Combine(outDir, $"sec_{sec:00}s.png");
                    File.WriteAllBytes(secPath, pngBytes);
                }

                Object.DestroyImmediate(frameTex);
            }

            Object.DestroyImmediate(renderRT);

            // ── 2. Assemble Master Contact Sheet Matrix (2560 x 1260) ─────────────────
            int matrixW = cols * cellW;
            int matrixH = rows * cellH;
            var matrixTex = new Texture2D(matrixW, matrixH, TextureFormat.RGB24, false);

            // Fill background with cinematic dark charcoal
            Color bgCol = new Color(0.03f, 0.05f, 0.08f);
            Color[] bgPixels = new Color[matrixW * matrixH];
            for (int p = 0; p < bgPixels.Length; p++) bgPixels[p] = bgCol;
            matrixTex.SetPixels(bgPixels);

            for (int row = 0; row < rows; row++)
            {
                for (int col = 0; col < cols; col++)
                {
                    int index = row * cols + col;
                    int startX = col * cellW;
                    // In Unity Texture coordinate, y=0 is at bottom, so invert row
                    int startY = (rows - 1 - row) * cellH;

                    if (index < totalSeconds && secondThumbnails[index] != null)
                    {
                        var thumb = secondThumbnails[index];
                        Color[] thumbPixels = thumb.GetPixels();
                        matrixTex.SetPixels(startX, startY, cellW, cellH, thumbPixels);
                    }
                    else
                    {
                        // Summary slot
                        DrawLegendSlot(matrixTex, startX, startY, cellW, cellH, index - totalSeconds);
                    }
                }
            }

            // Cleanup individual thumbnail textures
            for (int i = 0; i < secondThumbnails.Length; i++)
            {
                if (secondThumbnails[i] != null) Object.DestroyImmediate(secondThumbnails[i]);
            }

            matrixTex.Apply();
            byte[] matrixBytes = matrixTex.EncodeToPNG();
            Object.DestroyImmediate(matrixTex);

            string matrixFilePath = Path.Combine(outDir, "moon_battle_cutscene_frame_matrix.png");
            File.WriteAllBytes(matrixFilePath, matrixBytes);
            Debug.Log($"[FrameInspector] Successfully built 2560x1260 Cutscene Matrix: {matrixFilePath} ({matrixBytes.Length} bytes)");

            // Also copy matrix to Documentation/Images/ for README presentation
            string docDir = Path.Combine(Application.dataPath, "../Documentation/Images");
            if (!Directory.Exists(docDir)) Directory.CreateDirectory(docDir);
            File.WriteAllBytes(Path.Combine(docDir, "moon_battle_cutscene_frame_matrix.png"), matrixBytes);

            // ── 3. Render 6 High-Res 1080p Hero Frames ───────────────────────────────
            DumpAllFrames();

            AssetDatabase.Refresh();
            Debug.Log("[FrameInspector] Completed 52-Second Frame Analysis and Matrix Generation!");
        }

        [MenuItem("Cyberpunk/Dump All 6 Moon Battle Frames")]
        public static void DumpAllFrames()
        {
            string scenePath = "Assets/Scenes/Scene_Moon_Battle_Flashback.unity";
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);

            var director = Object.FindFirstObjectByType<AlitaMoonBattleCutsceneDirector>();
            if (director == null || director.cinematicCamera == null)
            {
                Debug.LogError("[FrameInspector] Director or Cinematic Camera not found!");
                return;
            }

            string outDir = Path.Combine(Application.dataPath, "../VerifiedCutsceneFrames/MoonBattle");
            if (!Directory.Exists(outDir)) Directory.CreateDirectory(outDir);

            var clipGunWalk = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_walking_inplace.fbx");
            var clipGun01 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_01_inplace.fbx");
            var clipGun02 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_02_inplace.fbx");
            var clipGun03 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_03_inplace.fbx");
            var clipGun04 = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/atk_gun_04_inplace.fbx");
            var clipRun = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/move_run_front_inplace.fbx");
            var clipStrafe = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/run_strafe_front_inplace.fbx");
            var clipJump = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/jump_inplace.fbx");
            var clipRoll = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/roll_front_inplace.fbx");
            var clipReload = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/reload_inplace.fbx");
            var clipHit = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/hit_heavy_front_inplace.fbx");
            var clipIdle = GetClipFromFBX("Assets/InsaneGun_Sword_Set/Animation/Humanoid/Inplace/N_idle_inplace.fbx");

            float[] testTimes = new float[] { 3.0f, 12.0f, 21.0f, 30.0f, 39.0f, 48.0f };
            string[] frameNames = new string[]
            {
                "frame_01_fortress_breach_03s.png",
                "frame_02_vanguard_charge_12s.png",
                "frame_03_zerog_leap_21s.png",
                "frame_04_ridge_crossfire_30s.png",
                "frame_05_commander_bond_39s.png",
                "frame_06_alita_remembrance_48s.png"
            };

            var cam = director.cinematicCamera;

            for (int i = 0; i < testTimes.Length; i++)
            {
                float t = testTimes[i];
                director.ScrubTo(t);

                AnimationMode.StartAnimationMode();

                SampleCombatChoreography(
                    director, t,
                    clipGunWalk, clipGun01, clipGun02, clipGun03, clipGun04,
                    clipRun, clipStrafe, clipJump, clipRoll, clipReload, clipHit, clipIdle);

                // Synchronize SceneView
                if (SceneView.lastActiveSceneView != null)
                {
                    var sv = SceneView.lastActiveSceneView;
                    sv.AlignViewToObject(cam.transform);
                    sv.cameraSettings.fieldOfView = cam.fieldOfView;
                    sv.Repaint();
                }

                // Render into RenderTexture
                var rt = new RenderTexture(1920, 1080, 24, RenderTextureFormat.ARGB32);
                cam.targetTexture = rt;
                cam.Render();

                RenderTexture.active = rt;
                var tex = new Texture2D(1920, 1080, TextureFormat.RGB24, false);
                tex.ReadPixels(new Rect(0, 0, 1920, 1080), 0, 0);
                tex.Apply();

                cam.targetTexture = null;
                RenderTexture.active = null;
                Object.DestroyImmediate(rt);

                AnimationMode.StopAnimationMode();

                byte[] bytes = tex.EncodeToPNG();
                Object.DestroyImmediate(tex);

                string filePath = Path.Combine(outDir, frameNames[i]);
                File.WriteAllBytes(filePath, bytes);
                Debug.Log($"[FrameInspector] Rendered Hero Frame {i + 1}/6: {frameNames[i]} ({bytes.Length} bytes)");

                // Copy best showcase frame to Documentation
                if (i == 0 || i == 2)
                {
                    string showcaseDest = Path.Combine(Application.dataPath, "../Documentation/Images/inengine_moon_battle_flashback.png");
                    File.WriteAllBytes(showcaseDest, bytes);
                }
            }

            AssetDatabase.Refresh();
        }

        private static void SampleCombatChoreography(
            AlitaMoonBattleCutsceneDirector director,
            float t,
            AnimationClip clipGunWalk,
            AnimationClip clipGun01,
            AnimationClip clipGun02,
            AnimationClip clipGun03,
            AnimationClip clipGun04,
            AnimationClip clipRun,
            AnimationClip clipStrafe,
            AnimationClip clipJump,
            AnimationClip clipRoll,
            AnimationClip clipReload,
            AnimationClip clipHit,
            AnimationClip clipIdle)
        {
            // 1. Alita Combat Motions
            if (director.alitaHero != null)
            {
                if (t < 9.0f)
                {
                    SafeSample(director.alitaHero, clipGunWalk, (t * 1.3f) % (clipGunWalk != null ? clipGunWalk.length : 1f));
                }
                else if (t < 18.0f)
                {
                    float subT = t - 9.0f;
                    if (subT < 5.0f && clipRun != null) SafeSample(director.alitaHero, clipRun, (subT * 1.5f) % clipRun.length);
                    else if (clipGun01 != null) SafeSample(director.alitaHero, clipGun01, ((subT - 5.0f) * 1.4f) % clipGun01.length);
                }
                else if (t < 26.0f)
                {
                    float leapT = (t - 18.0f) / 8.0f;
                    if (leapT < 0.65f && clipJump != null) SafeSample(director.alitaHero, clipJump, leapT * clipJump.length * 0.75f);
                    else if (clipGun02 != null) SafeSample(director.alitaHero, clipGun02, (leapT - 0.65f) * clipGun02.length * 2.5f);
                }
                else if (t < 35.0f)
                {
                    float fireT = t - 26.0f;
                    var c = ((int)fireT % 2 == 0) ? clipGun01 : clipGun03;
                    if (c != null) SafeSample(director.alitaHero, c, fireT % c.length);
                }
                else if (t < 44.0f)
                {
                    float bondT = t - 35.0f;
                    var c = (bondT < 4.5f) ? clipReload : clipGun04;
                    if (c != null) SafeSample(director.alitaHero, c, bondT % c.length);
                }
                else
                {
                    if (clipIdle != null) SafeSample(director.alitaHero, clipIdle, (t - 44.0f) % clipIdle.length);
                }
            }

            // 2. Commander Gelda Combat Motions
            if (director.commanderGelda != null)
            {
                if (t < 9.0f)
                {
                    if (clipRun != null) SafeSample(director.commanderGelda, clipRun, (t * 1.1f) % clipRun.length);
                }
                else if (t < 18.0f)
                {
                    if (clipGun02 != null) SafeSample(director.commanderGelda, clipGun02, (t * 1.3f) % clipGun02.length);
                }
                else if (t < 26.0f)
                {
                    if (clipGun04 != null) SafeSample(director.commanderGelda, clipGun04, (t * 0.9f) % clipGun04.length);
                }
                else if (t < 35.0f)
                {
                    if (clipGun04 != null) SafeSample(director.commanderGelda, clipGun04, ((t - 26f) * 1.2f) % clipGun04.length);
                }
                else if (t < 44.0f)
                {
                    if (clipGun02 != null) SafeSample(director.commanderGelda, clipGun02, (t - 35f) % clipGun02.length);
                }
                else
                {
                    if (clipIdle != null) SafeSample(director.commanderGelda, clipIdle, (t - 44f) % clipIdle.length);
                }
            }

            // 3. Squad Troops Motions
            for (int s = 0; s < director.squadTroops.Count; s++)
            {
                var soldier = director.squadTroops[s];
                if (soldier == null) continue;
                if (t < 18.0f)
                {
                    var c = (s % 2 == 0) ? clipRun : clipGunWalk;
                    if (c != null) SafeSample(soldier, c, (t * 1.2f + s * 0.35f) % c.length);
                }
                else if (t < 35.0f)
                {
                    if (s == 3 && t >= 28.0f && t <= 32.0f && clipHit != null)
                    {
                        SafeSample(soldier, clipHit, (t - 28.0f) % clipHit.length);
                    }
                    else
                    {
                        var c = (s % 2 == 0) ? clipGun01 : clipGun02;
                        if (c != null) SafeSample(soldier, c, (t * 1.4f + s * 0.4f) % c.length);
                    }
                }
                else
                {
                    var c = (s % 2 == 0) ? clipGun03 : clipIdle;
                    if (c != null) SafeSample(soldier, c, (t * 0.8f + s * 0.2f) % c.length);
                }
            }

            // 4. Enemy Defense Troops Motions
            for (int e = 0; e < director.enemyTroops.Count; e++)
            {
                var enemy = director.enemyTroops[e];
                if (enemy == null) continue;
                var c = (e % 2 == 0) ? clipGun01 : clipGun02;
                if (c != null) SafeSample(enemy, c, (t * 1.5f + e * 0.5f) % c.length);
            }
        }

        private static AnimationClip GetClipFromFBX(string path)
        {
            var assets = AssetDatabase.LoadAllAssetsAtPath(path);
            foreach (var a in assets)
            {
                if (a is AnimationClip c && !c.name.StartsWith("__preview__"))
                {
                    return c;
                }
            }
            return null;
        }

        private static void SafeSample(GameObject go, AnimationClip clip, float time)
        {
            if (go == null || clip == null) return;
            Vector3 pos = go.transform.position;
            Quaternion rot = go.transform.rotation;
            AnimationMode.SampleAnimationClip(go, clip, time);
            go.transform.position = pos;
            go.transform.rotation = rot;
        }

        private static Texture2D ScaleTexture(Texture2D source, int targetWidth, int targetHeight)
        {
            var rt = RenderTexture.GetTemporary(targetWidth, targetHeight, 0, RenderTextureFormat.ARGB32);
            Graphics.Blit(source, rt);
            var prev = RenderTexture.active;
            RenderTexture.active = rt;
            var result = new Texture2D(targetWidth, targetHeight, TextureFormat.RGB24, false);
            result.ReadPixels(new Rect(0, 0, targetWidth, targetHeight), 0, 0);
            result.Apply();
            RenderTexture.active = prev;
            RenderTexture.ReleaseTemporary(rt);
            return result;
        }

        private static void DrawTimestamp(Texture2D tex, int startX, int startY, int second)
        {
            // Black translucent background pill
            for (int y = startY - 2; y <= startY + 12; y++)
            {
                for (int x = startX - 4; x <= startX + 32; x++)
                {
                    if (x >= 0 && x < tex.width && y >= 0 && y < tex.height)
                    {
                        Color c = tex.GetPixel(x, y);
                        tex.SetPixel(x, y, Color.Lerp(c, new Color(0.02f, 0.04f, 0.08f), 0.85f));
                    }
                }
            }

            string s = $"{second:00}s";
            int curX = startX;
            for (int i = 0; i < s.Length; i++)
            {
                DrawChar(tex, curX, startY, s[i], new Color(0.18f, 0.90f, 1.0f));
                curX += 8;
            }
        }

        private static void DrawLegendSlot(Texture2D tex, int startX, int startY, int w, int h, int slot)
        {
            Color border = new Color(0.12f, 0.25f, 0.40f);
            for (int y = startY; y < startY + h; y++)
            {
                for (int x = startX; x < startX + w; x++)
                {
                    if (x == startX || x == startX + w - 1 || y == startY || y == startY + h - 1)
                        tex.SetPixel(x, y, border);
                    else
                        tex.SetPixel(x, y, new Color(0.04f, 0.06f, 0.10f));
                }
            }

            string label = (slot == 0) ? "URM 99" : (slot == 1) ? "EARTH" : (slot == 2) ? "STAR FLEET" : "52s MASTER";
            int curX = startX + 20;
            int curY = startY + (h / 2) - 4;
            for (int i = 0; i < label.Length; i++)
            {
                DrawChar(tex, curX, curY, label[i], new Color(0.25f, 0.75f, 1.0f));
                curX += 8;
            }
        }

        private static void DrawChar(Texture2D tex, int x, int y, char c, Color color)
        {
            // 5x7 bitmap font
            byte[] glyph = GetGlyph(c);
            for (int r = 0; r < 7; r++)
            {
                byte rowBits = glyph[r];
                for (int col = 0; col < 5; col++)
                {
                    if ((rowBits & (1 << (4 - col))) != 0)
                    {
                        int px = x + col;
                        int py = y + (6 - r); // Flip row to match texture coordinates
                        if (px >= 0 && px < tex.width && py >= 0 && py < tex.height)
                        {
                            tex.SetPixel(px, py, color);
                        }
                    }
                }
            }
        }

        private static byte[] GetGlyph(char c)
        {
            switch (c)
            {
                case '0': return new byte[] { 0x0E, 0x11, 0x13, 0x15, 0x19, 0x11, 0x0E };
                case '1': return new byte[] { 0x04, 0x0C, 0x04, 0x04, 0x04, 0x04, 0x0E };
                case '2': return new byte[] { 0x0E, 0x11, 0x01, 0x06, 0x08, 0x10, 0x1F };
                case '3': return new byte[] { 0x1E, 0x01, 0x01, 0x0E, 0x01, 0x01, 0x1E };
                case '4': return new byte[] { 0x02, 0x06, 0x0A, 0x12, 0x1F, 0x02, 0x02 };
                case '5': return new byte[] { 0x1F, 0x10, 0x1E, 0x01, 0x01, 0x11, 0x0E };
                case '6': return new byte[] { 0x06, 0x08, 0x10, 0x1E, 0x11, 0x11, 0x0E };
                case '7': return new byte[] { 0x1F, 0x01, 0x02, 0x04, 0x08, 0x08, 0x08 };
                case '8': return new byte[] { 0x0E, 0x11, 0x11, 0x0E, 0x11, 0x11, 0x0E };
                case '9': return new byte[] { 0x0E, 0x11, 0x11, 0x0F, 0x01, 0x02, 0x0C };
                case 's': return new byte[] { 0x00, 0x00, 0x0E, 0x10, 0x0E, 0x01, 0x1E };
                case 'U': return new byte[] { 0x11, 0x11, 0x11, 0x11, 0x11, 0x11, 0x0E };
                case 'R': return new byte[] { 0x1E, 0x11, 0x11, 0x1E, 0x14, 0x12, 0x11 };
                case 'M': return new byte[] { 0x11, 0x1B, 0x15, 0x15, 0x11, 0x11, 0x11 };
                case 'E': return new byte[] { 0x1F, 0x10, 0x10, 0x1E, 0x10, 0x10, 0x1F };
                case 'A': return new byte[] { 0x0E, 0x11, 0x11, 0x1F, 0x11, 0x11, 0x11 };
                case 'T': return new byte[] { 0x1F, 0x04, 0x04, 0x04, 0x04, 0x04, 0x04 };
                case 'H': return new byte[] { 0x11, 0x11, 0x11, 0x1F, 0x11, 0x11, 0x11 };
                case 'S': return new byte[] { 0x0F, 0x10, 0x10, 0x0E, 0x01, 0x01, 0x1E };
                case 'F': return new byte[] { 0x1F, 0x10, 0x10, 0x1E, 0x10, 0x10, 0x10 };
                case 'L': return new byte[] { 0x10, 0x10, 0x10, 0x10, 0x10, 0x10, 0x1F };
                default:  return new byte[] { 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };
            }
        }
    }
