using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var alita = GameObject.Find("Alita_Combat_Hero");
        if (alita == null) { result.LogError("Alita not found"); return; }

        Transform handR = null;
        foreach (var t in alita.GetComponentsInChildren<Transform>(true))
        {
            string n = t.name.ToLower();
            if (n.StartsWith("ik_") || n.Contains("ikhand")) continue;
            if (n == "hand_r" || n == "hand.r" || n == "r_hand" || n == "right_hand")
            {
                handR = t;
                break;
            }
        }

        if (handR != null)
        {
            result.Log("Found real hand bone: {0} parented to {1}", handR.name, handR.parent.name);
            // Check if existing gun is present
            var existingGun = alita.transform.Find("Equipped_Gun");
            foreach (var t in alita.GetComponentsInChildren<Transform>(true))
            {
                if (t.name == "Equipped_Gun")
                {
                    result.RegisterObjectModification(t);
                    t.SetParent(handR, false);
                    t.localPosition = new Vector3(0.08f, 0.05f, 0.05f);
                    t.localRotation = Quaternion.Euler(-10f, 90f, 0f);
                    result.Log("Reparented Equipped_Gun to {0}", handR.name);
                }
            }
        }
        else
        {
            result.LogError("Could not find real hand bone!");
        }
    }
}

