// 1. Starfighter Squadron Alpha (URM Starfighters)
// Flying high across the lunar sky directly across the face of Earth
for (int i = 0; i < starfighters.Count; i++)
{
    if (starfighters[i] == null) continue;
    float shipCycle = (currentTime * 0.045f + (i * 0.065f)) % 1.0f;
    Vector3 wingOffset = new Vector3(i * -12f, i * 4.0f, i * -8f);
    float x = Mathf.Lerp(195f, 275f, shipCycle);
    float y = 54f + Mathf.Sin(shipCycle * Mathf.PI * 2f + i) * 6f;
    float z = Mathf.Lerp(55f, 115f, shipCycle);

    starfighters[i].transform.position = new Vector3(x, y, z) + wingOffset;
    Vector3 forwardDir = new Vector3(80f, 6f, 60f).normalized;
    starfighters[i].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, Mathf.Sin(currentTime * 2.2f + i) * 22f);
}

// 2. Enemy Interceptors (Defense Fighters)
// Chasing Squadron Alpha closely across the face of Earth
for (int e = 0; e < enemyInterceptors.Count; e++)
{
    if (enemyInterceptors[e] == null) continue;
    float chaseCycle = ((currentTime + 0.35f + e * 0.18f) * 0.045f) % 1.0f;
    Vector3 chaseOffset = new Vector3(e * -14f - 18f, -4f + e * 3.5f, -14f - e * 10f);
    float x = Mathf.Lerp(185f, 265f, chaseCycle);
    float y = 50f + Mathf.Sin(chaseCycle * Mathf.PI * 2f + e) * 5.5f;
    float z = Mathf.Lerp(48f, 108f, chaseCycle);

    enemyInterceptors[e].transform.position = new Vector3(x, y, z) + chaseOffset;
    Vector3 forwardDir = new Vector3(80f, 6f, 60f).normalized;
    enemyInterceptors[e].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, -25f + Mathf.Sin(currentTime * 2.8f + e) * 25f);
}

// 3. Low-Altitude Assault Gunship
// Sweeps in low over the battle ridge during Shots 2 & 3 (7s to 28s) directly across camera view
if (assaultGunship != null)
{
    if (currentTime >= 7.0f && currentTime <= 28.0f)
    {
        assaultGunship.SetActive(true);
        float runT = (currentTime - 7.0f) / 21.0f;
        Vector3 startRun = center + new Vector3(-24f, 19f, -8f);
        Vector3 endRun = center + new Vector3(28f, 17f, 32f);
        assaultGunship.transform.position = Vector3.Lerp(startRun, endRun, runT);
        Vector3 heading = (endRun - startRun).normalized;
        assaultGunship.transform.rotation = Quaternion.LookRotation(heading, Vector3.up) * Quaternion.Euler(8f, 0f, 28f);
    }
    else
    {
        // High orbit standby
        assaultGunship.transform.position = center + new Vector3(90f, 85f, 95f);
    }
}

// 4. Space Dogfight Laser Beams (Line Renderers)
for (int l = 0; l < dogfightLaserBeams.Count; l++)
{
    var lr = dogfightLaserBeams[l];
    if (lr == null) continue;
    bool isCyan = (l % 2 == 0);
    float laserCycle = (currentTime * 4.8f + l * 0.35f) % 1.0f;
    Vector3 origin, target;
    if (isCyan && starfighters.Count > 0 && starfighters[0] != null)
    {
        origin = starfighters[0].transform.position + new Vector3(0f, -0.8f, 3.2f);
        target = origin + starfighters[0].transform.forward * 65f;
    }
    else if (enemyInterceptors.Count > 0 && enemyInterceptors[0] != null)
    {
        origin = enemyInterceptors[0].transform.position + new Vector3(0f, 0.4f, 3.0f);
        target = origin + enemyInterceptors[0].transform.forward * 58f;
    }
    else
    {
        origin = new Vector3(205f, 55f, 60f) + new Vector3(l * 8f, l * 2.5f, l * 6f);
        target = origin + new Vector3(48f, 4f, 30f);
    }

    Vector3 curStart = Vector3.Lerp(origin, target, Mathf.Max(0f, laserCycle - 0.28f));
    Vector3 curEnd = Vector3.Lerp(origin, target, laserCycle);
    lr.SetPosition(0, curStart);
    lr.SetPosition(1, curEnd);
}

