    public void Execute(ExecutionResult result)
    {
        var alita = GameObject.Find("Alita_Combat_Hero");
        var gun = alita != null ? alita.transform.Find("hand_r/Equipped_Gun") : null;
        if (gun == null && alita != null)
        {
            foreach (var t in alita.GetComponentsInChildren<Transform>(true))
            {
                if (t.name == "Equipped_Gun") gun = t;
            }
        }
        if (gun != null)
        {
            result.Log("Alita Equipped_Gun parent: {0}, localPos: {1}, localRot: {2}", gun.parent.name, gun.localPosition, gun.localEulerAngles);
