}

using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var earth = GameObject.Find("Earth_In_Lunar_Sky");
        if (earth != null)
        {
            result.Log("Earth pos: {0}, scale: {1}, active: {2}", earth.transform.position, earth.transform.localScale, earth.activeInHierarchy);
            var mr = earth.GetComponent<MeshRenderer>();
            if (mr != null)
            {
                result.Log("Earth material: {0}, shader: {1}, enabled: {2}", mr.sharedMaterial.name, mr.sharedMaterial.shader.name, mr.enabled);
            }
        }
        else
        {
            result.LogError("Earth_In_Lunar_Sky NOT found!");
        }

        var cam = GameObject.Find("Moon_Battle_Cinematic_Camera")?.GetComponent<Camera>();
        if (cam != null)
        {
            result.Log("Camera pos: {0}, rot: {1}, fov: {2}, farClip: {3}", cam.transform.position, cam.transform.rotation.eulerAngles, cam.fieldOfView, cam.farClipPlane);
            if (earth != null)
            {
                Vector3 vp = cam.WorldToViewportPoint(earth.transform.position);
                result.Log("Earth Viewport Point from Shot 1: {0}", vp);
            }
        }
    }
}

