using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var earth = GameObject.Find("Earth_In_Lunar_Sky");
        if (earth == null) { result.LogError("Earth not found"); return; }

        var mr = earth.GetComponent<MeshRenderer>();
        var mat = mr.sharedMaterial;

        var texAlbedo = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Synty/PolygonSciFiWorlds/Textures/Misc/Planet_01.png");
        var texEmissive = AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Synty/PolygonSciFiWorlds/Textures/Misc/Planet_01_Emissive.png");

        if (texAlbedo != null)
        {
            mat.mainTexture = texAlbedo;
            mat.color = Color.white;
            result.Log("Assigned Planet_01.png to Earth!");
        }
        if (texEmissive != null)
        {
            mat.SetTexture("_EmissionMap", texEmissive);
            mat.SetColor("_EmissionColor", new Color(0.25f, 0.65f, 1.0f) * 2.5f);
            mat.EnableKeyword("_EMISSION");
            result.Log("Assigned Planet_01_Emissive.png to Earth!");
        }

        earth.transform.position = new Vector3(225f, 32f, 72f);
        earth.transform.rotation = Quaternion.Euler(-15f, 140f, 0f);
        result.Log("Repositioned and textured Earth in lunar sky!");
    }
}

