using UnityEngine;
using UnityEditor;
using Alita;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var director = Object.FindFirstObjectByType<AlitaMoonBattleCutsceneDirector>();
        director.ScrubTo(21f);
        var cam = director.cinematicCamera;

        Ray ray = cam.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
        if (Physics.Raycast(ray, out RaycastHit hit, 500f))
        {
            result.Log("Hit: {0} at distance {1:F2}, pos: {2}", hit.collider.gameObject.name, hit.distance, hit.point);
        }
        else
        {
            result.Log("No Physics collider hit from viewport center. Checking all meshes in frustum...");
        }

        // Check objects near cam pos (168.83, 15.42, 8.96)
        foreach (var mr in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))
        {
            if (!mr.enabled || !mr.gameObject.activeInHierarchy) continue;
            var bounds = mr.bounds;
            if (bounds.Contains(cam.transform.position + cam.transform.forward * 5f) ||
                Vector3.Distance(bounds.center, cam.transform.position) < 25f)
            {
                result.Log("MeshRenderer near camera: {0} (parent: {1}), bounds center: {2}, size: {3}",
                    mr.gameObject.name, mr.transform.parent != null ? mr.transform.parent.name : "null", bounds.center, bounds.size);
            }
        }
    }
}

