// 1. Starfighter Squadron Alpha (URM Starfighters in Delta Wing)
// Flying high across the lunar sky directly across the face of Earth
for (int i = 0; i < starfighters.Count; i++)
{
    if (starfighters[i] == null) continue;
    float shipCycle = (currentTime * 0.045f) % 1.0f;
    Vector3 wingOffset = (i == 0) ? Vector3.zero :
        ((i == 1) ? new Vector3(-12f, -2.0f, -14f) : new Vector3(12f, 2.0f, -16f));
    float x = Mathf.Lerp(190f, 275f, shipCycle);
    float y = 48f + Mathf.Sin(shipCycle * Mathf.PI * 2f) * 4f;
    float z = Mathf.Lerp(50f, 110f, shipCycle);

    starfighters[i].transform.position = new Vector3(x, y, z) + wingOffset;
    Vector3 forwardDir = new Vector3(85f, 4f, 60f).normalized;
    starfighters[i].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, Mathf.Sin(currentTime * 2.2f + i) * 18f);
}

// 2. Enemy Interceptors (Defense Fighters in tight pursuit)
// Chasing Squadron Alpha closely across the face of Earth
for (int e = 0; e < enemyInterceptors.Count; e++)
{
    if (enemyInterceptors[e] == null) continue;
    float chaseCycle = ((currentTime - 0.5f) * 0.045f) % 1.0f;
    Vector3 chaseOffset = (e == 0) ? new Vector3(-8f, -1.5f, -28f) : new Vector3(8f, 1.5f, -32f);
    float x = Mathf.Lerp(190f, 275f, chaseCycle);
    float y = 47f + Mathf.Sin(chaseCycle * Mathf.PI * 2f) * 4f;
    float z = Mathf.Lerp(50f, 110f, chaseCycle);

    enemyInterceptors[e].transform.position = new Vector3(x, y, z) + chaseOffset;
    Vector3 forwardDir = new Vector3(85f, 4f, 60f).normalized;
    enemyInterceptors[e].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, -22f + Mathf.Sin(currentTime * 2.8f + e) * 20f);
}

