261:         private static void SampleCombatChoreography(
262:             AlitaMoonBattleCutsceneDirector director,
263:             float t,
264:             AnimationClip clipGunWalk,
265:             AnimationClip clipGun01,
266:             AnimationClip clipGun02,
267:             AnimationClip clipGun03,
268:             AnimationClip clipGun04,
269:             AnimationClip clipRun,
270:             AnimationClip clipStrafe,
271:             AnimationClip clipJump,
272:             AnimationClip clipRoll,
273:             AnimationClip clipReload,
274:             AnimationClip clipHit,
275:             AnimationClip clipIdle)
276:         {
277:             // 1. Alita Combat Motions
278:             if (director.alitaHero != null)
279:             {
280:                 if (t < 9.0f)
281:                 {
282:                     SafeSample(director.alitaHero, clipGunWalk, (t * 1.3f) % (clipGunWalk != null ? clipGunWalk.length : 1f));
283:                 }
284:                 else if (t < 18.0f)
285:                 {
286:                     float subT = t - 9.0f;
287:                     if (subT < 5.0f && clipRun != null) SafeSample(director.alitaHero, clipRun, (subT * 1.5f) % clipRun.length);
288:                     else if (clipGun01 != null) SafeSample(director.alitaHero, clipGun01, ((subT - 5.0f) * 1.4f) % clipGun01.length);
289:                 }
290:                 else if (t < 26.0f)
291:                 {
292:                     float leapT = (t - 18.0f) / 8.0f;
293:                     var c = (clipGun02 != null) ? clipGun02 : clipJump;
294:                     if (c != null) SafeSample(director.alitaHero, c, (leapT * c.length * 1.5f) % c.length);
295:                 }
296:                 else if (t < 35.0f)
297:                 {
298:                     float fireT = t - 26.0f;
299:                     var c = ((int)fireT % 2 == 0) ? clipGun01 : clipGun03;
300:                     if (c != null) SafeSample(director.alitaHero, c, fireT % c.length);
301:                 }
302:                 else if (t < 44.0f)
303:                 {
304:                     float bondT = t - 35.0f;
305:                     var c = (bondT < 4.5f) ? clipGun04 : clipIdle;
306:                     if (c != null) SafeSample(director.alitaHero, c, bondT % c.length);
307:                 }
