398:         private static Transform FindBone(Transform current, params string[] boneNames)
399:         {
400:             // First pass: exact matches (excluding ik_ bones)
401:             foreach (var t in current.GetComponentsInChildren<Transform>(true))
402:             {
403:                 string lower = t.name.ToLower();
404:                 if (lower.StartsWith("ik_") || lower.Contains("ikhand") || lower.Contains("ik_hand")) continue;
405:                 foreach (var b in boneNames)
406:                 {
407:                     if (lower == b) return t;
408:                 }
409:             }
410: 
411:             // Second pass: contains matches (excluding ik_ bones)
412:             foreach (var t in current.GetComponentsInChildren<Transform>(true))
413:             {
414:                 string lower = t.name.ToLower();
415:                 if (lower.StartsWith("ik_") || lower.Contains("ikhand") || lower.Contains("ik_hand")) continue;
416:                 foreach (var b in boneNames)
417:                 {
418:                     if (lower.Contains(b)) return t;
419:                 }
420:             }
421: 
422:             return null;
423:         }
