330:         private void UpdateCameraChoreography()
331:         {
332:             if (cinematicCamera == null || !_shots.ContainsKey(currentPhase)) return;
333: 
334:             CinematicCameraShot shot = _shots[currentPhase];
335:             float phaseStart = GetPhaseStartTime(currentPhase);
336:             float phaseDuration = GetPhaseDuration(currentPhase);
337:             float t = Mathf.Clamp01((currentTime - phaseStart) / phaseDuration);
338: 
339:             // Smooth cubic ease in-out
340:             float easeT = Mathf.SmoothStep(0f, 1f, t);
341: 
342:             Vector3 center = new Vector3(172f, 13f, 10f);
343:             Vector3 targetPos = Vector3.Lerp(shot.startPos, shot.endPos, easeT);
344:             Quaternion targetRot;
345: 
346:             // Intelligent cinematic LookAt framing for each shot
347:             switch (currentPhase)
348:             {
349:                 case MoonBattleCutscenePhase.FortressBreach:
350:                     Vector3 lookBreach = center + new Vector3(1.5f, 1.3f, 1.0f);
351:                     targetRot = Quaternion.LookRotation((lookBreach - targetPos).normalized, Vector3.up);
352:                     break;
353:                 case MoonBattleCutscenePhase.VanguardAssault:
354:                     Vector3 lookVanguard = center + new Vector3(0.5f, 1.4f, 0.6f);
355:                     targetRot = Quaternion.LookRotation((lookVanguard - targetPos).normalized, Vector3.up);
356:                     break;
357:                 case MoonBattleCutscenePhase.ZeroGravityLeap:
358:                     Vector3 lookHero = (alitaHero != null) ? (alitaHero.transform.position + Vector3.up * 0.40f) : (center + Vector3.up * 1.5f);
359:                     targetRot = Quaternion.LookRotation((lookHero - targetPos).normalized, Vector3.up);
360:                     break;
361:                 case MoonBattleCutscenePhase.CrossfireClash:
362:                     Vector3 lookCrossfire = center + new Vector3(8.5f, 1.30f, 2.2f);
363:                     targetRot = Quaternion.LookRotation((lookCrossfire - targetPos).normalized, Vector3.up);
364:                     break;
365:                 case MoonBattleCutscenePhase.TheCommanderBond:
366:                     Vector3 alitaP = (alitaHero != null) ? alitaHero.transform.position : center;
367:                     Vector3 geldaP = (commanderGelda != null) ? commanderGelda.transform.position : center;
368:                     Vector3 lookBond = (alitaP + geldaP) * 0.5f + Vector3.up * 1.15f;
369:                     targetRot = Quaternion.LookRotation((lookBond - targetPos).normalized, Vector3.up);
370:                     break;
371:                 case MoonBattleCutscenePhase.IconicRemembrance:
372:                     Vector3 lookRemembrance = (alitaHero != null) ? (alitaHero.transform.position + Vector3.up * 1.38f) : (center + Vector3.up * 1.38f);
373:                     targetRot = Quaternion.LookRotation((lookRemembrance - targetPos).normalized, Vector3.up);
374:                     break;
375:                 default:
376:                     targetRot = Quaternion.Slerp(Quaternion.Euler(shot.startRotEuler), Quaternion.Euler(shot.endRotEuler), easeT);
377:                     break;
378:             }
379: 
380:             float targetFov = Mathf.Lerp(shot.startFov, shot.endFov, easeT);
381: 
382:             // Dynamic camera shake
383:             if (cameraShakeIntensity > 0.001f)
384:             {
385:                 Vector3 shake = new Vector3(
386:                     (Mathf.PerlinNoise(Time.time * 25f, 0f) - 0.5f) * cameraShakeIntensity,
387:                     (Mathf.PerlinNoise(0f, Time.time * 25f) - 0.5f) * cameraShakeIntensity,
388:                     0f);
389:                 targetPos += shake;
390:             }
391: 
392:             cinematicCamera.transform.position = targetPos;
393:             cinematicCamera.transform.rotation = targetRot;
394:             cinematicCamera.fieldOfView = targetFov;
395:         }
