543:         private void UpdateSpaceDogfights()
544:         {
545:             Vector3 center = new Vector3(172f, 13f, 10f);
546: 
547:             // 1. Starfighter Squadron Alpha (URM Starfighters in Delta Wing)
548:             // Flying high across the lunar sky directly across the face of Earth
549:             for (int i = 0; i < starfighters.Count; i++)
550:             {
551:                 if (starfighters[i] == null) continue;
552:                 float shipCycle = (currentTime * 0.045f) % 1.0f;
553:                 Vector3 wingOffset = (i == 0) ? Vector3.zero :
554:                     ((i == 1) ? new Vector3(-12f, -2.0f, -14f) : new Vector3(12f, 2.0f, -16f));
555:                 float x = Mathf.Lerp(190f, 275f, shipCycle);
556:                 float y = 48f + Mathf.Sin(shipCycle * Mathf.PI * 2f) * 4f;
557:                 float z = Mathf.Lerp(50f, 110f, shipCycle);
558: 
559:                 starfighters[i].transform.position = new Vector3(x, y, z) + wingOffset;
560:                 Vector3 forwardDir = new Vector3(85f, 4f, 60f).normalized;
561:                 starfighters[i].transform.rotation = Quaternion.LookRotation(forwardDir, Vector3.up) * Quaternion.Euler(0f, 0f, Mathf.Sin(currentTime * 2.2f + i) * 18f);
