internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Vector3 origin = new Vector3(172f, 13f, 10f);
        Vector3 target = new Vector3(225f, 32f, 72f);
        Vector3 dir = (target - origin).normalized;
        float dist = Vector3.Distance(origin, target) + 100f;

        var hits = Physics.RaycastAll(origin, dir, dist);
        result.Log("Raycast from {0} towards Earth {1} (dir {2}, dist {3}): hits count = {4}", origin, target, dir, dist, hits.Length);
        foreach (var h in hits)
        {
            result.Log("Hit: {0} at {1}, dist {2}", h.collider.gameObject.name, h.point, h.distance);
        }

        // Also check all colliders or meshes near that line
        var renderers = Object.FindObjectsByType<MeshRenderer>(FindObjectsInactive.Exclude, FindObjectsSortMode.None);
        foreach (var mr in renderers)
        {
            // Point to line segment distance
            Vector3 p = mr.transform.position;
            Vector3 pToOrigin = p - origin;
            float proj = Vector3.Dot(pToOrigin, dir);
            if (proj > 0 && proj < dist)
            {
                Vector3 closest = origin + dir * proj;
                float d = Vector3.Distance(p, closest);
                if (d < 40f && mr.name != "Earth_In_Lunar_Sky")
                {
                    result.Log("Mesh near Earth sightline: {0} at {1}, d={2}, bounds={3}", mr.name, p, d, mr.bounds.size);
                }
            }
        }
    }
}

