using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // 1. Deactivate all spike objects in Environment
        var env = GameObject.Find("Environment");
        int deactivatedSpikes = 0;
        if (env != null)
        {
            foreach (Transform t in env.GetComponentsInChildren<Transform>(true))
            {
                if (t.name.ToLower().Contains("spike"))
                {
                    t.gameObject.SetActive(false);
                    deactivatedSpikes++;
                }
            }
        }
        result.Log("Deactivated {0} spike objects", deactivatedSpikes);

        // 2. Set Earth material to Planet_01.mat
        var earth = GameObject.Find("Earth_In_Lunar_Sky");
        if (earth != null)
        {
            var mat = AssetDatabase.LoadAssetAtPath<Material>("Assets/Synty/PolygonSciFiWorlds/Materials/Sky/Planet_01.mat");
            if (mat != null)
            {
                earth.GetComponent<MeshRenderer>().sharedMaterial = mat;
                result.Log("Applied Planet_01.mat to Earth");
            }
        }

        // 3. Render a test frame of Shot 1 and Shot 3
        var cam = GameObject.Find("Moon_Battle_Cinematic_Camera").GetComponent<Camera>();
        var director = Object.FindFirstObjectByType<Alita.AlitaMoonBattleCutsceneDirector>();

        string outDir = Path.Combine(Application.dataPath, "../VerifiedCutsceneFrames/MoonBattle");

        // Test Shot 1 at 3.0s
        director.ScrubTo(3.0f);
        var rt = new RenderTexture(960, 540, 24);
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        var tex = new Texture2D(960, 540, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 960, 540), 0, 0);
        tex.Apply();
        cam.targetTexture = null;
        RenderTexture.active = null;
        File.WriteAllBytes(Path.Combine(outDir, "test_shot1_no_spike.png"), tex.EncodeToPNG());
        Object.DestroyImmediate(tex);

        // Test Shot 3 at 21.0s
        director.ScrubTo(21.0f);
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        tex = new Texture2D(960, 540, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 960, 540), 0, 0);
        tex.Apply();
        cam.targetTexture = null;
        RenderTexture.active = null;
        File.WriteAllBytes(Path.Combine(outDir, "test_shot3_no_spike.png"), tex.EncodeToPNG());
        Object.DestroyImmediate(tex);

        Object.DestroyImmediate(rt);
        result.Log("Saved test_shot1_no_spike.png and test_shot3_no_spike.png");
    }
}

