using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string srcPath = @"C:\Users\LEGION\.gemini\antigravity-ide\brain\e435c426-d83c-40b2-8ade-57eec1271d17\earth_globe_texture_1791835507687.jpg";
        if (!File.Exists(srcPath))
        {
            result.LogError("Source image not found: {0}", srcPath);
            return;
        }

        byte[] fileData = File.ReadAllBytes(srcPath);
        Texture2D srcTex = new Texture2D(2, 2);
        srcTex.LoadImage(fileData);

        int w = srcTex.width;
        int h = srcTex.height;
        Texture2D rgbaTex = new Texture2D(w, h, TextureFormat.RGBA32, false);

        Vector2 center = new Vector2(w * 0.5f, h * 0.5f);
        float radius = w * 0.478f; // Earth globe radius with cyan atmospheric halo
        float feather = w * 0.018f;

        Color[] pixels = srcTex.GetPixels();
        Color[] outPixels = new Color[pixels.Length];

        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                int idx = y * w + x;
                Color c = pixels[idx];
                float dist = Vector2.Distance(new Vector2(x, y), center);

                float alpha = 1.0f;
                if (dist > radius)
                {
                    alpha = Mathf.Clamp01(1.0f - (dist - radius) / feather);
                }

                outPixels[idx] = new Color(c.r, c.g, c.b, alpha);
            }
        }

        rgbaTex.SetPixels(outPixels);
        rgbaTex.Apply();

        string destDir = Path.Combine(Application.dataPath, "Textures/Environment");
        if (!Directory.Exists(destDir)) Directory.CreateDirectory(destDir);
        string destPath = Path.Combine(destDir, "T_Earth_Photorealistic.png");

        File.WriteAllBytes(destPath, rgbaTex.EncodeToPNG());
        Object.DestroyImmediate(srcTex);
        Object.DestroyImmediate(rgbaTex);

        AssetDatabase.Refresh();

        // Configure texture importer for transparent sprite/texture
        string relPath = "Assets/Textures/Environment/T_Earth_Photorealistic.png";
        var importer = AssetImporter.GetAtPath(relPath) as TextureImporter;
        if (importer != null)
        {
            importer.alphaIsTransparency = true;
            importer.mipmapEnabled = true;
            importer.SaveAndReimport();
        }

        result.Log("Successfully created transparent photorealistic Earth texture at: {0}", relPath);
    }
}

