using UnityEngine;
using UnityEditor;
using System.IO;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var earth = GameObject.Find("Earth_In_Lunar_Sky");
        if (earth == null)
        {
            result.LogError("Earth not found");
            return;
        }

        Vector3 center = new Vector3(172f, 13f, 10f);
        Vector3 targetPos = new Vector3(262f, 32f, 85f);
        earth.transform.position = targetPos;
        earth.transform.localScale = new Vector3(68f, 68f, 1f);

        Vector3 lookDir = (center + new Vector3(0f, 2.5f, 0f) - targetPos).normalized;
        // Face camera: quad normal is (0,0,-1), so lookDir should align with -Z (i.e. +Z points away from camera)
        earth.transform.rotation = Quaternion.LookRotation(-lookDir, Vector3.up);

        var mr = earth.GetComponent<MeshRenderer>();
        if (mr != null && mr.sharedMaterial != null)
        {
            mr.sharedMaterial.SetInt("_Cull", (int)UnityEngine.Rendering.CullMode.Off);
        }

        var cam = GameObject.Find("Moon_Battle_Cinematic_Camera").GetComponent<Camera>();
        var director = Object.FindFirstObjectByType<Alita.AlitaMoonBattleCutsceneDirector>();
        string outDir = Path.Combine(Application.dataPath, "../VerifiedCutsceneFrames/MoonBattle");

        // Render Shot 1 at 3s
        director.ScrubTo(3.0f);
        var rt = new RenderTexture(960, 540, 24);
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        var tex = new Texture2D(960, 540, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 960, 540), 0, 0);
        tex.Apply();
        cam.targetTexture = null;
        RenderTexture.active = null;
        File.WriteAllBytes(Path.Combine(outDir, "test_earth_shot1.png"), tex.EncodeToPNG());
        Object.DestroyImmediate(tex);

        // Render Shot 3 at 21s
        director.ScrubTo(21.0f);
        cam.targetTexture = rt;
        cam.Render();
        RenderTexture.active = rt;
        tex = new Texture2D(960, 540, TextureFormat.RGB24, false);
        tex.ReadPixels(new Rect(0, 0, 960, 540), 0, 0);
        tex.Apply();
        cam.targetTexture = null;
        RenderTexture.active = null;
        File.WriteAllBytes(Path.Combine(outDir, "test_earth_shot3.png"), tex.EncodeToPNG());
        Object.DestroyImmediate(tex);

        Object.DestroyImmediate(rt);
        result.Log("Saved test_earth_shot1.png and test_earth_shot3.png successfully!");
    }
}

