using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        if (SceneView.lastActiveSceneView != null)
        {
            var sv = SceneView.lastActiveSceneView;
            float oldFov = sv.cameraSettings.fieldOfView;
            sv.cameraSettings.fieldOfView = 60f;
            sv.Repaint();
            result.Log("Reset SceneView FOV from {0} to 60.0", oldFov);
        }

        // Also check all open scene views
        foreach (SceneView sv in SceneView.sceneViews)
        {
            if (sv != null)
            {
                sv.cameraSettings.fieldOfView = 60f;
                sv.Repaint();
                result.Log("Set SceneView {0} FOV to 60.0", sv.name);
            }
        }
    }
}

