using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var group = GameObject.Find("[Cinematic_Cutscene_Cameras]");
        if (group != null)
        {
            result.Log("Disabling [Cinematic_Cutscene_Cameras] and Main Camera to prevent multi-camera conflicts.");
            result.RegisterObjectModification(group);
            group.SetActive(false);
        }

        var mainCam = GameObject.Find("Main Camera");
        if (mainCam != null)
        {
            result.Log("Main Camera found. Active: {0}", mainCam.activeSelf);
            result.RegisterObjectModification(mainCam);
            mainCam.SetActive(false);
        }

        var cineCam = GameObject.Find("Moon_Battle_Cinematic_Camera");
        if (cineCam != null)
        {
            var cam = cineCam.GetComponent<Camera>();
            result.Log("Moon_Battle_Cinematic_Camera found. Active: {0}, FOV: {1}, Depth: {2}", cineCam.activeSelf, cam.fieldOfView, cam.depth);
            result.RegisterObjectModification(cam);
            cam.depth = 1; // Ensure it renders cleanly on top
        }

        // Save scene
        UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
        UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes();
        result.Log("Scene saved successfully.");
    }
}

