using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var svList = SceneView.sceneViews;
        if (svList != null)
        {
            foreach (var item in svList)
            {
                if (item is SceneView sv)
                {
                    sv.cameraSettings.fieldOfView = 60f;
                    sv.Repaint();
                    result.Log("SceneView FOV reset to: {0}", sv.cameraSettings.fieldOfView);
                }
            }
        }
        if (SceneView.lastActiveSceneView != null)
        {
            SceneView.lastActiveSceneView.cameraSettings.fieldOfView = 60f;
            SceneView.lastActiveSceneView.Repaint();
            result.Log("lastActiveSceneView FOV reset to: {0}", SceneView.lastActiveSceneView.cameraSettings.fieldOfView);
        }
    }
}

